    normed: list[str] = [];
    seen: dict[str, bool] = {};
    if tags is not None {
        for t in tags {
            low: str = t.lower();
            trimmed: str = low.strip();
            if trimmed == "" { continue; }
            if trimmed in seen { continue; }
            if len(normed) >= 5 { break; }
            seen[trimmed] = True;
            normed.append(trimmed);
        }
    }
