```jac
node Program {
    has name: str;
    has dialect: str;
}
node Relation {
    has name: str;
    has kind: str;
    has is_external: bool = True;
}
node ViewDef {
    has name: str;
    has sql: str;
}
node Knowledge {
    has kind: str;
    has detail: str;
}

edge Declares {}
edge Depends {}
edge Expands {}
edge Binds {}

walker HydrateWalker {
    has claimed: dict[str, bool] = {};
    has order: list[str] = [];

    can hyd_prog with Program entry {
        if here.name in self.claimed { skip; }
        self.claimed[here.name] = True;
        print("hydrate prog " + here.name);
        for nxt in [here ->:Declares:->][?:Relation] {
            visit :0: [nxt];
        }
        visit [] else { disengage; }
    }
    can hyd_rel with Relation entry {
        if here.name in self.claimed { skip; }
        self.claimed[here.name] = True;
        self.order.append(here.name);
        print("hydrate rel " + here.name);
        for dep in [here ->:Depends:->][?:Relation] {
            visit :0: [dep];
        }
        for vd in [here ->:Expands:->][?:ViewDef] {
            visit :0: [vd];
        }
        visit [] else { disengage; }
    }
    can hyd_view with ViewDef entry {
        if here.name in self.claimed { skip; }
        self.claimed[here.name] = True;
        self.order.append(here.name);
        print("hydrate view " + here.name);
        visit [] else { disengage; }
    }
}

def make_program(name: str, dialect: str) -> Program {
    prog = Program(name=name, dialect=dialect);
    root ++> prog;
    return prog;
}

def add_relation(prog: Program, name: str, kind: str) -> Relation {
    rel = Relation(name=name, kind=kind, is_external=True);
    root ++> rel;
    prog +>:Declares:+> rel;
    return rel;
}

def add_dependency(src: Relation, dst: Relation) {
    src +>:Depends:+> dst;
}

def add_view(rel: Relation, sql: str) -> ViewDef {
    vd = ViewDef(name=rel.name + "_view", sql=sql);
    root ++> vd;
    rel +>:Expands:+> vd;
    return vd;
}

def get_reachable_relations(prog: Program) -> list[str] {
    # collect reachable external Relation closure with recursive view expansion
    w = prog spawn HydrateWalker(claimed={}, order=[]);
    out: list[str] = [];
    for n in w.order {
        # filter view-def synthetic names, keep only relation names
        is_view: bool = False;
        # view names end with _view by construction
        if n == n { }  # keep shape
        # simple heuristic: view def names contain _view
        # rely on walker order already deduped via claim-map
        out.append(n);
    }
    # strip view-def entries to expose only relation closure
    filtered: list[str] = [];
    for x in out {
        if x not in filtered {
            # _view suffix indicates ViewDef, skip for relation closure
            if x.endswith("_view") == False {
                filtered.append(x);
            }
        }
    }
    print("reachable " + str(len(filtered)));
    return filtered;
}

def fetch_relation_metadata(prog: Program, names: list[str]) -> list[str] {
    # database adapter owns catalog boundary: batch fetch, unknown-id tolerant
    reachable = get_reachable_relations(prog);
    res: list[str] = [];
    for n in names {
        for r in reachable {
            if r == n {
                res.append(n);
            }
        }
    }
    print("fetch metadata " + str(len(res)));
    return res;
}

def fetch_view_definition(rel: Relation) -> str {
    for vd in [rel ->:Expands:->][?:ViewDef] {
        print("fetch view " + rel.name);
        return vd.sql;
    }
    print("fetch view miss " + rel.name);
    return "";
}

def bind_knowledge(prog: Program) -> list[Knowledge] {
    # fetcher owns name-binding: creates IR-linked Knowledge, no raw metadata leaks
    reachable = get_reachable_relations(prog);
    know: list[Knowledge] = [];
    for rname in reachable {
        k1 = Knowledge(kind="NonNullColumn", detail=rname);
        root ++> k1;
        prog +>:Binds:+> k1;
        know.append(k1);
        k2 = Knowledge(kind="UniqueSet", detail=rname);
        root ++> k2;
        prog +>:Binds:+> k2;
        know.append(k2);
    }
    print("bound " + str(len(know)));
    return know;
}

def hydrate(prog: Program) -> list[Knowledge] {
    # orchestration: walk -> batch fetch -> parse views recursively -> rebuild -> bind
    # simplified: walk closure already expands views, then bind
    return bind_knowledge(prog);
}

with entry {
    demo = make_program("demo_entry", "duckdb");
    w = demo spawn HydrateWalker(claimed={}, order=[]);
    print("entry done " + demo.name);
}
