def _is_traversal(path: str) -> bool {
    if ".." in path { return True; }
    if path.startswith("/") { return True; }
    if path.startswith("\\") { return True; }
    return False;
}

def _has_duplicate(pkg: Package, path: str) -> bool {
    kids: list[Part] = [pkg ->:Contains:->][?:Part];
    for k in kids {
        if k.path == path { return True; }
    }
    return False;
}

def _add_evidence(pkg: Package, kind: str, detail: str) -> Evidence {
    e = Evidence(kind=kind, detail=detail);
    pkg +>:EvidenceLink:+> e;
    return e;
}

def register_part(pkg: Package, path: str, content_type: str, size: int) -> Part | None {
    # bounded checks before expansion
    if _is_traversal(path) {
        _add_evidence(pkg, "traversal", path);
        return None;
    }
    if _has_duplicate(pkg, path) {
        _add_evidence(pkg, "duplicate", path);
        return None;
    }
    if pkg.compressed_bytes > pkg.limit_compressed {
        _add_evidence(pkg, "compressed_limit", path);
        return None;
    }
    if pkg.expansion_bytes + size > pkg.limit_expansion {
        _add_evidence(pkg, "expansion_limit", path);
        return None;
    }
    if ".exe" in path { _add_evidence(pkg, "embedded_executable", path); return None; }
    if "vbaProject" in path { _add_evidence(pkg, "macros", path); return None; }
    nd = Part(path=path, content_type=content_type, size=size);
    pkg +>:Contains:+> nd;
    pkg.expansion_bytes = pkg.expansion_bytes + size;
    return nd;
}

def add_relationship(src: Part | None, dst: Part | None, rid: str, is_external: bool = false) -> bool {
    if src == None { return False; }
    if dst == None { return False; }
    s = src as Part;
    d = dst as Part;
    if is_external {
        # do not link external; preserve evidence via parent package
        owners: list[Package] = [s <-:Contains:<-][?:Package];
        if owners {
            _add_evidence(owners[0], "external_reference", rid);
        }
        return False;
    }
    # typed edge connect - definite nodes already narrowed
    s +>:Rel:+> d;
    # store rid on edge would need edge ref; keep rid in evidence for determinism if needed
    return True;
}

def ingest_package(pkg: Package) -> dict[str, any] {
    w = pkg spawn ValidateWalker(claimed={}, errors=[], visited=[]);
    # deterministic normalization
    errs: list[str] = sorted(w.errors);
    vis: list[str] = sorted(w.visited);
    ok = len(errs) == 0;
    if pkg.cancelled { ok = False; }
    if pkg.revoked { ok = False; }
    return {"ok": ok, "errors": errs, "visited": vis};
}

def resolve_relationships(pkg: Package, start_path: str) -> list[str] {
    # unknown-id tolerance: unknown start returns empty
    kids: list[Part] = [pkg ->:Contains:->][?:Part];
    start: Part | None = None;
    for k in kids {
        if k.path == start_path { start = k; }
    }
    if start == None { return []; }
    s = start as Part;
    w = s spawn ResolveWalker(claimed={}, result=[]);
    return sorted(w.result);
}

def cancel_package(pkg: Package) -> int {
    if pkg.cancelled { return 0; }
    pkg.cancelled = True;
    w = pkg spawn DisposeCollectWalker(claimed={}, collected=[]);
    cnt: int = 0;
    for p in w.collected {
        # two-phase mutation: disconnect outside walk
        owners: list[Package] = [p <-:Contains:<-][?:Package];
        for o in owners { o -:Contains:-> p; }
        rel_out: list[Part] = [p ->:Rel:->][?:Part];
        for r in rel_out { p -:Rel:-> r; }
        rel_in: list[Part] = [p <-:Rel:<-][?:Part];
        for r in rel_in { r -:Rel:-> p; }
        cnt = cnt + 1;
    }
    return cnt;
}

def revoke_source(pkg: Package) -> int {
    pkg.revoked = True;
    return cancel_package(pkg);
}

def get_evidence(pkg: Package) -> list[dict[str, str]] {
    es: list[Evidence] = [pkg ->:EvidenceLink:->][?:Evidence];
    out: list[dict[str, str]] = [];
    for e in es { out.append({"kind": e.kind, "detail": e.detail}); }
    return out;
}

def get_required_missing(pkg: Package, required: list[str]) -> list[str] {
    have: dict[str, bool] = {};
    kids: list[Part] = [pkg ->:Contains:->][?:Part];
    for k in kids { have[k.path] = True; }
    miss: list[str] = [];
    for r in required {
        if r not in have { miss.append(r); }
    }
    return sorted(miss);
}

