    hit: GNode | None = find_node(graph_root, nid);
    if hit != None {
      hit.kind = knd;
    } else {
      nd = GNode(node_id=nid, kind=knd);
      graph_root ++> nd;
    }
  }
  return mid;
}

def upsert_edges(graph_root: GraphRoot, edges: list[dict]) -> str {
  graph_root.mutation_seq += 1;
  mid: str = "m-" + str(graph_root.mutation_seq);
  for spec in edges {
    eid: str = spec["id"];
    frm: str = spec["from"];
    to_id: str = spec["to"];
    src: GNode | None = find_node(graph_root, frm);
    if src == None {
      raise ValueError("missing endpoint");
    }
    dst: GNode | None = find_node(graph_root, to_id);
    if dst == None {
      raise ValueError("missing endpoint");
    }
    src +>:Adj(edge_id=eid, kind=spec["kind"]):+> dst;
  }
  return mid;
}

def get_nodes(graph_root: GraphRoot, ids: list[str]) -> list[dict] {
  out: list[dict] = [];
  for nid in ids {
    hit: GNode | None = find_node(graph_root, nid);
    if hit != None {
      row: dict = {};
      row["id"] = hit.node_id;
      row["kind"] = hit.kind;
      out.append(row);
    }
  }
  return out;
}

def neighbors(
  graph_root: GraphRoot,
  node_id: str,
  direction: str = "out",
  max_depth: int = 1,
  limit: int = 100,
) -> list[str] {
  start_node: GNode | None = find_node(graph_root, node_id);
  if start_node == None {
    return [];
  }
  w = start_node spawn NeighborWalk(
    origin_id=node_id,
    direction=direction,
    max_depth=max_depth,
    limit=limit,
    claimed={},
  );
  return sorted(w.found_ids);
}

def rebuild_path(parent: dict[str, str], start_id: str, goal_id: str) -> list[str] {
  seq: list[str] = [];
  cur: str = goal_id;
  while cur != start_id {
    seq.append(cur);
    if cur not in parent {
      return [];
    }
    cur = parent[cur];
  }
  seq.append(start_id);
  out: list[str] = [];
  i: int = len(seq) - 1;
  while i >= 0 {
    out.append(seq[i]);
    i -= 1;
  }
  return out;
}

def shortest_path(
  graph_root: GraphRoot,
  from_id: str,
  to_id: str,
  max_depth: int = 50,
) -> list[str] | None {
  start_node: GNode | None = find_node(graph_root, from_id);
  if start_node == None {
    return None;
  }
  goal_node: GNode | None = find_node(graph_root, to_id);
  if goal_node == None {
    return None;
  }
  if from_id == to_id {
    return [from_id];
  }
  w = start_node spawn PathWalk(goal_id=to_id, claimed={});
  if w.reached == False {
    return None;
  }
  return rebuild_path(w.parent, from_id, to_id);
}

def describe(graph_root: GraphRoot) -> dict {
  d: dict = {};
  d["mutation_seq"] = graph_root.mutation_seq;
  d["product"] = "graph";
  return d;
}
