def reachable_ids(graph_root: Step, start_id: str) -> list[str] {
    start = _find_step(graph_root, start_id);
    if start is None {
        return [];
    }
    w = start spawn ReachStepsWalker(claimed={});
    out: list[str] = [];
    for x in w.found {
        out.append(x);
    }
    return sorted(out);
}

def topo_order(graph_root: Step, start_id: str) -> list[str] {
    start = _find_step(graph_root, start_id);
    if start is None {
        return [];
    }
    w = start spawn TopoStepsWalker(claimed={});
    out: list[str] = [];
    for x in w.order {
        out.append(x);
    }
    return out;
}

def blast_radius(graph_root: Module, module_id: str) -> list[str] {
    start = _find_module(graph_root, module_id);
    if start is None {
        return [];
    }
    w = start spawn BlastWalker(claimed={});
    out: list[str] = [];
    for x in w.hits {
        out.append(x);
    }
    return sorted(out);
}

def modules_below_floor(graph_root: Module, anchor_id: str) -> list[str] {
    start = _find_module(graph_root, anchor_id);
    if start is None {
        return [];
    }
    w = start spawn BlastWalker(claimed={});
    out: list[str] = [];
    for nd in w.hits {
        if nd.covered_pct < nd.floor_pct {
            out.append(nd.mid);
        }
    }
    return sorted(out);
}

def suite_migration_order(graph_root: TestSuite) -> list[str] {
    suites: list[TestSuite] = [graph_root ->:Depends:->][?:TestSuite];
    start: TestSuite | None = None;
    for s in suites {
        if start is None {
            start = s;
        }
    }
    if start is None {
        return [];
    }
    w = start spawn MigrateOrderWalker(claimed={});
    out: list[str] = [];
    for x in w.pending {
        out.append(x);
    }
    return out;
}

