def state_rank(st: str) -> int {
    if st == "fail" { return 3; }
    if st == "warn" { return 2; }
    if st == "stale" { return 2; }
    if st == "unknown" { return 1; }
    return 0;
}

def max_state(a: str, b: str) -> str {
    if state_rank(a) >= state_rank(b) { return a; }
    return b;
}

def combine_effective(local: str, dep: str) -> str {
    if local == "fail" { return "fail"; }
    if dep == "fail" {
        if local == "fail" { return "fail"; }
        return "warn";
    }
    if dep == "unknown" or dep == "stale" {
        if local == "ok" { return "warn"; }
        return max_state(local, dep);
    }
    if dep == "warn" { return max_state(local, "warn"); }
    return local;
}

def create_service(sid: str, local_state: str = "unknown") -> Service {
    svc = Service(sid=sid, local_state=local_state, effective_state=local_state);
    root ++> svc;
    return svc;
}

def require_dep(from_svc: Service, to_svc: Service) {
    from_svc +>:Requires:+> to_svc;
    from_svc.required_dependencies.append(to_svc.sid);
