"""KittyCAD/modeling-app#13397 — helix edit must preserve cylinder input."""

node Op {
    has cid: str;
    has kind: str;
    has cylinder_ref: str = "";
    has revolutions: int = 0;
    has angle_start: int = 0;
}

edge Downstream {}

walker FindOp {
    has claimed: dict[str, bool] = {};
    has target: str;
    has result: Op | None = None;

    can step with Op entry {
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        print ["find_op", here.cid, self.target];
        if here.cid == self.target {
            self.result = here;
            disengage;
        }
        kids: list[Op] = [];
        for ch in [here ->:->][?:Op] {
            kids.append(ch);
        }
        visit kids;
    }
}

walker LastChildWalk {
    has claimed: dict[str, bool] = {};
    has found_id: str = "";

    can descend with Op entry {
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        self.found_id = here.cid;
        best: Op | None = None;
        for ch in [here ->:Downstream:->][?:Op] {
            if best is None or ch.cid > best.cid {
                best = ch;
            }
        }
        print ["last_child", here.cid, self.found_id];
        if best is not None {
            visit [best];
        } else {
            disengage;
        }
    }
}

walker CollectDownstream {
    has claimed: dict[str, bool] = {};
    has acc: list[str] = [];

    can walk with Op entry {
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        self.acc.append(here.cid);
        kids: list[Op] = [];
        for ch in [here ->:Downstream:->][?:Op] {
            kids.append(ch);
        }
        ordered: list[Op] = [];
        join_node: Op | None = None;
        rest: list[Op] = [];
        for k in kids {
            if k.cid == "join" {
                join_node = k;
            } else {
                rest.append(k);
            }
        }
        if join_node is not None {
            ordered.append(join_node);
        }
        for r in rest {
            ordered.append(r);
        }
        print ["collect", here.cid, self.acc];
        visit :0: ordered;
    }
}

def find_op(graph_root: Op, cid: str) -> Op | None {
    w = graph_root spawn FindOp(target=cid);
    return w.result;
}

def get_variable_exprs_from_selection(
    graph_root: Op,
    selection_id: str,
    last_child_lookup: bool
) -> list[str] {
    target = find_op(graph_root, selection_id);
    if target is None {
        out_empty: list[str] = [];
        return out_empty;
    }
    if not last_child_lookup {
        single: list[str] = [selection_id];
        return single;
    }
    w = target spawn LastChildWalk();
    out: list[str] = [];
    if w.found_id != "" {
        out.append(w.found_id);
    }
    return out;
}

def collect_downstream_ids(graph_root: Op, start_id: str) -> list[str] {
    start = find_op(graph_root, start_id);
    if start is None {
        none_out: list[str] = [];
        return none_out;
    }
    w = start spawn CollectDownstream();
    return sorted(w.acc);
}

def build_issue_graph() -> Op {
    graph_root = Op(cid="graph_root", kind="anchor");
    ex = Op(cid="extrude001", kind="extrude");
    hx = Op(cid="helix001", kind="helix", cylinder_ref="extrude001", revolutions=3, angle_start=0);
    pat = Op(cid="pattern001", kind="pattern");
    root ++> graph_root;
    graph_root ++> ex;
    graph_root ++> hx;
    graph_root ++> pat;
    ex +>:Downstream:+> pat;
    return graph_root;
}

def build_diamond_graph() -> Op {
    graph_root = Op(cid="graph_root", kind="anchor");
    apex = Op(cid="apex", kind="apex");
    left_n = Op(cid="left", kind="arm");
    right_n = Op(cid="right", kind="arm");
    join_n = Op(cid="join", kind="join");
    root ++> graph_root;
    graph_root ++> apex;
    apex +>:Downstream:+> join_n;
    apex +>:Downstream:+> left_n;
    left_n +>:Downstream:+> join_n;
    apex +>:Downstream:+> right_n;
    right_n +>:Downstream:+> join_n;
    return graph_root;
}

def add_helix(
    graph_root: Op,
    node_to_edit: str,
    cylinder_selection: str,
    revolutions: int,
    angle_start: int
) -> str {
    helix_node = find_op(graph_root, node_to_edit);
    if helix_node is None {
        return "";
    }
    cylinder_id: str = "";
    if helix_node.cylinder_ref != "" {
        cylinder_id = helix_node.cylinder_ref;
    } else {
        exprs: list[str] = get_variable_exprs_from_selection(
            graph_root, cylinder_selection, True
        );
        if len(exprs) > 0 {
            cylinder_id = exprs[0];
        } else {
            cylinder_id = cylinder_selection;
        }
    }
    helix_node.revolutions = revolutions;
    helix_node.angle_start = angle_start;
    helix_node.cylinder_ref = cylinder_id;
    return cylinder_id;
}
