    root ++> pr;
    return pr;
}

def attach_evidence(app: Application, eid: str, etype: str) -> Evidence {
    ev = Evidence(eid=eid, etype=etype);
    app +>:Contains:+> ev;
    return ev;
}

def add_derived(src: Evidence, dst: Evidence) {
    src +>:Derived:+> dst;
}

def add_reference(src: Evidence, dst: Evidence) {
    src +>:References:+> dst;
}

def evidence_closure(start: Evidence) -> list[str] {
    w = start spawn EvidenceReach(claimed={});
    return sorted(w.found);
}

def application_evidence_ids(app: Application) -> list[str] {
    w = app spawn AppEvidenceWalker(claimed={});
    return sorted(w.found);
}

def create_check_run(app: Application, cid: str, release: PolicyRelease) -> CheckRun {
    cr = CheckRun(cid=cid);
    root ++> cr;
    cr +>:Governed:+> release;
    evs: list[Evidence] = [];
    for e in [app ->:Contains:->][?:Evidence] { evs.append(e); }
    for e in evs { cr +>:Freezes:+> e; }
    return cr;
}
