def ready_workstreams(completed: list[str]) -> list[str] {
    build_dmimp_control_graph();
    catalog: list[str] = ["177", "178", "179", "180", "181", "182"];
    done: dict[str, bool] = {};
    for c in completed {
        done[c] = True;
    }
    ready: list[str] = [];
    for wid in catalog {
        if wid in done {
            continue;
        }
        prereqs = prerequisite_ids(wid);
        blocked = False;
        for p in prereqs {
            if p not in done {
                blocked = True;
            }
        }
        if blocked == False {
            ready.append(wid);
        }
    }
    ready.sort();
    return ready;
}

def promotion_allowed(ws_id: str, completed: list[str], gates_ok: list[int]) -> bool {
    build_dmimp_control_graph();
    gate = workstream_gate(ws_id);
    if gate == 0 {
        return False;
    }
    gate_hit = False;
    for g in gates_ok {
        if g == gate {
            gate_hit = True;
        }
    }
    if gate_hit == False {
        return False;
    }
    done: dict[str, bool] = {};
    for c in completed {
        done[c] = True;
    }
    prereqs = prerequisite_ids(ws_id);
    for p in prereqs {
        if p not in done {
            return False;
        }
    }
    return True;
}
