"""bobluppes/graaf#334 — Kahn's algorithm for topological sorting."""

node Vertex {
    has vid: str;
    has indeg: int = 0;
}

edge Out {}

class TopologicalCycleError(Exception) {}

def _ensure_vertex(store: dict[str, Vertex], vid: str) -> Vertex {
    if vid in store {
        return store[vid];
    }
    v = Vertex(vid=vid);
    root ++> v;
    store[vid] = v;
    return v;
}

def _build_graph(adjacency: dict[str, list[str]]) -> dict[str, Vertex] {
    store: dict[str, Vertex] = {};
    for src in adjacency {
        _ensure_vertex(store, src);
    }
    for src in adjacency {
        u = store[src];
        nbrs: list[str] = adjacency[src];
        for dst in nbrs {
            v = _ensure_vertex(store, dst);
            u +>:Out:+> v;
            v.indeg = v.indeg + 1;
        }
    }
    return store;
}

def _sort_vertices_by_vid(vs: list[Vertex]) -> list[Vertex] {
    ids: list[str] = [];
    for v in vs {
        ids.append(v.vid);
    }
    ids = sorted(ids);
    idx: dict[str, Vertex] = {};
    for v in vs {
        idx[v.vid] = v;
    }
    out: list[Vertex] = [];
    for sid in ids {
        out.append(idx[sid]);
    }
    return out;
}

walker KahnWalker {
    has claimed: dict[str, bool] = {};
    has order: list[str] = [];
    has seeds: list[Vertex] = [];

    can drain with Vertex entry {
        if here.vid in self.claimed {
            skip;
        }
        self.claimed[here.vid] = True;
        self.order.append(here.vid);
        print("kahn", here.vid);
        ready: list[Vertex] = [];
        kids: list[Vertex] = [here ->:Out:->][?:Vertex];
        for ch in kids {
            ch.indeg = ch.indeg - 1;
            if ch.indeg == 0 {
                ready.append(ch);
            }
        }
        ready = _sort_vertices_by_vid(ready);
        if len(ready) > 0 {
            visit ready;
        }
    }

    with entry {
        seeds_sorted = _sort_vertices_by_vid(self.seeds);
        if len(seeds_sorted) > 0 {
            visit seeds_sorted;
        } else {
            disengage;
        }
    }
}

def kahn_sort(adjacency: dict[str, list[str]]) -> list[str] {
    store = _build_graph(adjacency);
    seeds: list[Vertex] = [];
    for k in store {
        nd = store[k];
        if nd.indeg == 0 {
            seeds.append(nd);
        }
    }
    w = root spawn KahnWalker(claimed={}, order=[], seeds=seeds);
    if len(w.order) != len(store) {
        raise TopologicalCycleError("cycle in directed graph");
    }
    return w.order;
}

def has_cycle(adjacency: dict[str, list[str]]) -> bool {
    store = _build_graph(adjacency);
    seeds: list[Vertex] = [];
    for k in store {
        nd = store[k];
        if nd.indeg == 0 {
            seeds.append(nd);
        }
    }
    w = root spawn KahnWalker(claimed={}, order=[], seeds=seeds);
    return len(w.order) != len(store);
}
