        by_id[vid] = vtx;
        root ++> vtx;
    }
    return by_id;
}

def _wire_edges(by_id: dict[str, Vtx], edges: list[tuple[str, str]]) {
    for pair in edges {
        sid: str = pair[0];
        did: str = pair[1];
        if (sid in by_id) and (did in by_id) {
            src: Vtx = by_id[sid] as Vtx;
            dst: Vtx = by_id[did] as Vtx;
            src +>:Dep:+> dst;
        }
    }
}

def kahn_topological_sort(vertex_ids: list[str], edges: list[tuple[str, str]]) -> list[str] {
    if len(vertex_ids) == 0 {
        return [];
    }
    by_id: dict[str, Vtx] = _build_vertices(vertex_ids);
    _wire_edges(by_id, edges);
    all_nodes: list[Vtx] = [];
    for vid in vertex_ids {
        all_nodes.append(by_id[vid] as Vtx);
    }
    anchor: Vtx = by_id[vertex_ids[0]] as Vtx;
    iw: IndegreeWalker = anchor spawn IndegreeWalker(
        claimed={},
        indeg={},
        all_vtx=all_nodes,
        booted=False
    );
    pending: dict[str, int] = {};
    for vid in vertex_ids {
        if vid in iw.indeg {
            pending[vid] = iw.indeg[vid];
        } else {
            pending[vid] = 0;
        }
    }
    starters: list[Vtx] = [];
    for vid in vertex_ids {
        if pending[vid] == 0 {
            starters.append(by_id[vid] as Vtx);
        }
    }
    kw: KahnWalker = anchor spawn KahnWalker(
        claimed={},
        order=[],
        pending=pending,
        starters=starters,
        booted=False
    );
    if len(kw.order) < len(vertex_ids) {
        raise CycleError(message="cycle detected during kahn topological sort");
    }
    return kw.order;
}

