    print("walk session");
    key = "s:" + here.name;
    if key in self.claimed { skip; }
    self.claimed[key] = True;
    sups: list[Supervisor] = [here ->:Owns:->][?:Supervisor];
    for sup in sups {
      blobs: list[Blob] = [sup ->:Owns:->][?:Blob];
      for b in blobs {
        if b.status == "accepted" {
          self.found.append(b.blob_id);
        }
      }
    }
    nexts: list[ReconSession] = [here ->:Links:->][?:ReconSession];
    if nexts {
      visit :0: nexts;
    } else {
      disengage;
    }
  }
}

walker ClosureProbeWalker {
  has claimed: dict[str, bool] = {};
  has order: list[str] = [];

  can probe_session with ReconSession entry {
    print("probe session");
    key = "s:" + here.name;
    if key in self.claimed { skip; }
    self.claimed[key] = True;
    self.order.append(here.name);
    nexts: list[ReconSession] = [here ->:Links:->][?:ReconSession];
    if nexts {
      visit :0: nexts;
    } else {
      disengage;
    }
  }
}

def build_reconstruction_graph(session_id: str, blob_ids: list[str], accepted_count: int) -> ReconSession {
  sess = ReconSession(name=session_id);
  root ++> sess;
  sup = Supervisor(session_id=session_id, checkpoint=accepted_count);
  sess +>:Owns:+> sup;
  idx = 0;
  for bid in blob_ids {
    b = Blob(blob_id=bid, size=290, git_sha="gitsha_" + bid);
    if idx < accepted_count {
      b.status = "accepted";
    }
    sup +>:Owns:+> b;
    idx += 1;
  }
  return sess;
}

def collect_accepted_blob_ids(session: ReconSession) -> list[str] {
  w = session spawn BlobCollectWalker(claimed={});
  print("spawn collect");
  xs: list[str] = [];
  for x in w.found {
    xs.append(x);
  }
  xs.sort();
  return xs;
}

def validate_blob_record(blob_id: str, size: int, git_sha: str) -> bool {
  if size != 290 {
    return False;
  }
  expected = "gitsha_" + blob_id;
  if git_sha != expected {
    return False;
  }
  return True;
}

def interrupt_reconstruction(session: ReconSession) -> dict[str, object] {
  session.interrupted = True;
  out: dict[str, object] = {};
  sups: list[Supervisor] = [session ->:Owns:->][?:Supervisor];
  remaining = 0;
  for sup in sups {
    if sup.alive {
      sup.alive = False;
    }
    if sup.alive {
      remaining += 1;
    }
  }
  out["interrupted"] = True;
  out["owned_remaining"] = remaining;
  out["descendants_reaped"] = remaining == 0;
  return out;
}

def resume_pending_blob_ids(session: ReconSession) -> list[str] {
  pending: list[str] = [];
  sups: list[Supervisor] = [session ->:Owns:->][?:Supervisor];
  if len(sups) == 0 {
    return pending;
  }
  sup = sups[0];
  blobs: list[Blob] = [sup ->:Owns:->][?:Blob];
  for b in blobs {
    if b.status == "pending" {
      pending.append(b.blob_id);
    }
  }
  pending.sort();
  return pending;
}

def blob_status_for(session: ReconSession, blob_id: str) -> str {
  sups: list[Supervisor] = [session ->:Owns:->][?:Supervisor];
  for sup in sups {
    blobs: list[Blob] = [sup ->:Owns:->][?:Blob];
    for b in blobs {
      if b.blob_id == blob_id {
        return b.status;
      }
    }
  }
  return "unknown";
}

def audit_lifecycle(session: ReconSession) -> dict[str, object] {
  rep: dict[str, object] = {};
  rep["session"] = session.name;
  rep["interrupted"] = session.interrupted;
  rep["accepted"] = collect_accepted_blob_ids(session);
  rep["pending"] = resume_pending_blob_ids(session);
  return rep;
