        if here.pid in self.claimed { skip; }
        self.claimed[here.pid] = True;
        if here.owned {
            self.found.append(here.pid);
            self.nodes.append(here);
        }
        for ch in [here ->:Spawned:->][?:Proc] { visit :0: [ch]; }
        print(here.pid);
    }
}

def create_reconstruction(rid: str) -> Reconstruction {
    # create handle owning all blobs and sessions
    h = Reconstruction(rid=rid);
    root ++> h;
    return h;
}
def add_blob(handle: Reconstruction, blob_id: str, size: int, sha: str) -> Blob {
    b = Blob(blob_id=blob_id, size=size, sha=sha, status="pending");
    handle +>:Owns:+> b;
    return b;
}
def link_depends(a: Blob, b: Blob) {
    a +>:Depends:+> b;
}
def add_session(handle: Reconstruction, sid: str) -> Session {
    s = Session(sid=sid, active=True);
    handle +>:Owns:+> s;
    return s;
}
def spawn_proc(parent: Session, pid: str, owned: bool) -> Proc {
    p = Proc(pid=pid, owned=owned, alive=True);
    parent +>:Spawned:+> p;
    return p;
}
def spawn_child_proc(parent: Proc, pid: str, owned: bool) -> Proc {
    p = Proc(pid=pid, owned=owned, alive=True);
    parent +>:Spawned:+> p;
    return p;
}
def validate_and_checkpoint(handle: Reconstruction, blob_id: str, exp_size: int, exp_sha: str) -> bool {
    # exact size and Git-SHA validation; isolate .part on mismatch
    for b in [handle ->:Owns:->][?:Blob] {
        if b.blob_id == blob_id {
            if b.size == exp_size and b.sha == exp_sha {
                b.status = "accepted";
                return True;
            } else {
                b.status = "part";
                return False;
            }
        }
    }
    return False;
}
def get_accepted(handle: Reconstruction) -> list[str] {
    w = handle spawn AcceptedWalk(claimed={});
    return w.result;
}
def get_pending(handle: Reconstruction) -> list[str] {
    w = handle spawn PendingWalk(claimed={});
    return w.result;
}
def collect_owned_descendants(handle: Reconstruction, sid: str) -> list[str] {
    # deterministically collect owned pids under session
    for s in [handle ->:Owns:->][?:Session] {
        if s.sid == sid {
            w = s spawn DescendantWalk(claimed={});
            return w.found;
        }
    }
    return [];
}
def terminate_group(handle: Reconstruction, sid: str) -> dict[str, bool] {
    # parent supervisor owns and reaps all descendants; wait and verify
    found_sess: Session | None = None;
    for s in [handle ->:Owns:->][?:Session] {
        if s.sid == sid { found_sess = s; }
    }
    if found_sess is None {
        return {"terminated": False, "clean": False};
    }
    sess = found_sess as Session;
    w = sess spawn DescendantWalk(claimed={});
    # phase 2: mutate outside walk
    for n in w.nodes { n.alive = False; }
    sess.active = False;
    # verify no owned process remains alive
    w2 = sess spawn DescendantWalk(claimed={});
    clean: bool = True;
    for n in w2.nodes {
        if n.alive { clean = False; }
    }
    # preserve unrelated embedding: nodes not owned were never collected
    return {"terminated": True, "clean": clean};
}
def audit(handle: Reconstruction, sid: str) -> dict[str, bool] {
    # audit lifecycle and cleanup status
    res = terminate_group(handle, sid);
    return res;
}

