"""pnpm/pnpm#14352 — workspace discovery walk and per-importer resolver cache."""

node Dir {
    has did: str;
    has manifest: bool = False;
    has pkg_name: str = "";
}

edge Down {}

node Imp {
    has iid: str;
}

node Pkg {
    has name: str;
}

edge Import {}

walker Discover {
    has claimed: dict[str, bool] = {};
    has patterns: list[str] = [];
    has hits: list[str] = [];

    can walk with Dir entry {
        if here.did in self.claimed { skip; }
        self.claimed[here.did] = True;
        if here.manifest {
            matched: bool = False;
            for pat in self.patterns {
                if match_pattern(here.did, pat) { matched = True; }
            }
            if matched {
                self.hits.append(here.pkg_name);
                print("discover  ", here.pkg_name);
            }
        }
        kids: list[Dir] = [here ->:Down:->][?:Dir];
        if kids { visit :0: kids; } else { disengage; }
    }
}

walker Resolve {
    has claimed: dict[str, bool] = {};
    has key_cache: dict[str, bool] = {};
    has use_project_dir: bool = True;
    has hits: int = 0;
    has misses: int = 0;

    can step with Imp entry {
        if here.iid == "__hub__" {
            subs: list[Imp] = [here ->:Import:->][?:Imp];
            if subs { visit :0: subs; } else { disengage; }
        } else {
            if here.iid in self.claimed { skip; }
            self.claimed[here.iid] = True;
            pkgs: list[Pkg] = [here ->:Import:->][?:Pkg];
            for pkg in pkgs {
                ck: str = "";
                if self.use_project_dir { ck = here.iid + "::" + pkg.name; }
                else { ck = pkg.name; }
                if ck in self.key_cache {
                    self.hits += 1;
                } else {
                    self.misses += 1;
                    self.key_cache[ck] = True;
                    print("resolve  ", here.iid, "  ->  ", pkg.name);
                }
            }
            disengage;
        }
    }
}

def match_pattern(path: str, pattern: str) -> bool {
    plen: int = len(pattern);
    if plen >= 2 {
        tail: str = pattern[plen - 2:plen];
        if tail == "/*" {
            parent: str = pattern[0:plen - 2];
            prefix: str = parent + "/";
            plx: int = len(prefix);
            if path.startswith(prefix) {
                rest: str = path[plx:];
                for i in range(0, len(rest)) {
                    if rest[i] == "/" { return False; }
                }
                return len(rest) > 0;
            }
            return False;
        }
    }
    return path == pattern;
}

def build_dir_graph(root_did: str, edges: list[tuple[str, str]], manifests: dict[str, str]) -> Dir {
    store: dict[str, Dir] = {};
    rnode = Dir(did=root_did);
    store[root_did] = rnode;
    for e in edges {
        p: str = e[0];
        c: str = e[1];
        if p not in store { store[p] = Dir(did=p); }
        if c not in store { store[c] = Dir(did=c); }
        pa = store[p];
        ch = store[c];
        pa +>:Down:+> ch;
    }
    for key in manifests {
        if key in store {
            dn = store[key];
            dn.manifest = True;
            dn.pkg_name = manifests[key];
        }
    }
    return rnode;
}

def discover_workspaces(
    root_did: str,
    tree_edges: list[tuple[str, str]],
    manifests: dict[str, str],
    patterns: list[str],
) -> list[str] {
    graph_root = build_dir_graph(root_did, tree_edges, manifests);
    root ++> graph_root;
    w = graph_root spawn Discover(patterns=patterns);
    return sorted(w.hits);
}

def build_imp_graph(importers: list[str], deps: list[tuple[str, str]]) -> Imp {
    pkg_store: dict[str, Pkg] = {};
    imp_store: dict[str, Imp] = {};
    imps: list[Imp] = [];
    for iid in importers {
        n = Imp(iid=iid);
        imp_store[iid] = n;
        imps.append(n);
    }
    for row in deps {
        iid: str = row[0];
        pname: str = row[1];
        if pname not in pkg_store { pkg_store[pname] = Pkg(name=pname); }
        if iid in imp_store {
            imp = imp_store[iid];
            pkg = pkg_store[pname];
            imp +>:Import:+> pkg;
        }
    }
    hub = Imp(iid="__hub__");
    for n in imps { hub +>:Import:+> n; }
    return hub;
}

def resolve_workspace_deps(
    importers: list[str],
    deps: list[tuple[str, str]],
    include_project_dir_key: bool,
) -> dict[str, int] {
    hub = build_imp_graph(importers, deps);
    root ++> hub;
    w = hub spawn Resolve(use_project_dir=include_project_dir_key);
    out: dict[str, int] = {};
    out["hits"] = w.hits;
    out["misses"] = w.misses;
    return out;
}
