# iss_trinhtanphat__QS3D-BricsCAD__3938.jac
"""trinhtanphat/QS3D-BricsCAD#3938 LOCAL-010 qualification dependency workflow."""

node QualRow {
    has row_id: str;
    has lane_key: str;
    has blocked: bool = True;
    has is_prereq: bool = False;
    has satisfied: bool = False;
}

edge Dep {}

node Local010Store {
    has rows_by_id: dict[str, QualRow] = {};
}

walker DepClosureWalker {
    has claimed: dict[str, bool] = {};
    has found: list[str] = {};

    can step with QualRow entry {
        print ["closure_visit", here.row_id];
        if here.row_id in self.claimed { skip; }
        self.claimed[here.row_id] = True;
        self.found.append(here.row_id);
        kids: list[QualRow] = [here ->:Dep:->][?:QualRow];
        nxt: list[QualRow] = [];
        for ch in kids {
            nxt.append(ch);
        }
        visit :0: nxt else { disengage; }
    }
}

def _ensure_prereq(store: Local010Store, pid: str) -> QualRow {
    if pid in store.rows_by_id {
        return store.rows_by_id[pid] as QualRow;
    }
    pn = QualRow(row_id=pid, lane_key="");
    pn.is_prereq = True;
    pn.blocked = False;
    root ++> pn;
    store.rows_by_id[pid] = pn;
    return pn;
}

def make_local010_store(row_specs: list[dict], dep_pairs: list[list[str]]) -> Local010Store {
    store = Local010Store(rows_by_id={});
    root ++> store;
    for spec in row_specs {
        rid: str = spec["row_id"] as str;
        lk: str = spec["lane_key"] as str;
        bl: bool = True;
        if "blocked" in spec {
            bl = spec["blocked"] as bool;
        }
        nd = QualRow(row_id=rid, lane_key=lk, blocked=bl);
        root ++> nd;
        store.rows_by_id[rid] = nd;
    }
    for pair in dep_pairs {
        src_id: str = pair[0] as str;
        dst_id: str = pair[1] as str;
        src = store.rows_by_id[src_id] as QualRow;
        if dst_id in store.rows_by_id {
            dst = store.rows_by_id[dst_id] as QualRow;
            src +>:Dep:+> dst;
        } else {
            dstp = _ensure_prereq(store, dst_id);
            src +>:Dep:+> dstp;
        }
    }
    return store;
}

def dependency_closure(store: Local010Store, start_id: str) -> list[str] {
    if start_id not in store.rows_by_id {
        empty: list[str] = [];
        return empty;
    }
    nd = store.rows_by_id[start_id] as QualRow;
    w = nd spawn DepClosureWalker(claimed={}, found=[]);
    out: list[str] = sorted(w.found);
    return out;
}

def blocked_row_ids(store: Local010Store) -> list[str] {
    ids: list[str] = [];
    for rid in store.rows_by_id {
        nd = store.rows_by_id[rid] as QualRow;
        if nd.blocked and not nd.is_prereq {
            ids.append(rid);
        }
    }
    return sorted(ids);
}

def mark_prereq_satisfied(store: Local010Store, prereq_id: str) -> bool {
    if prereq_id not in store.rows_by_id {
        return False;
    }
    pn = store.rows_by_id[prereq_id] as QualRow;
    if not pn.is_prereq {
        return False;
    }
    pn.satisfied = True;
    return True;
}
