def corner_key(process: str, temp: int, supply_v: float) -> str {
    vs: str = str(supply_v);
    if supply_v == 1.62 { vs = "1.62"; }
    elif supply_v == 1.80 { vs = "1.80"; }
    elif supply_v == 1.98 { vs = "1.98"; }
    return process + "@" + str(temp) + "@" + vs;
}

def full_pvt_grid() -> list[str] {
    out: list[str] = [];
    for p in PROCESS_CORNERS {
        for t in TEMP_CORNERS {
            for v in SUPPLY_CORNERS {
                out.append(corner_key(p, t, v));
            }
        }
    }
    return sorted(out);
