def filter_known_corners(ids: list[str]) -> list[str] {
    full_set: dict[str, bool] = {};
    for c in full_pvt_grid() {
        full_set[c] = True;
    }
    out: list[str] = [];
    for i in ids {
        if i in full_set {
            out.append(i);
        }
    }
    return sorted(out);
}

def missing_corners(declared: list[str], full: list[str] | None = None) -> list[str] {
    grid: list[str] = full;
    if grid is None {
        grid = full_pvt_grid();
    }
    decl_set: dict[str, bool] = {};
    for d in declared {
        decl_set[d] = True;
    }
    miss: list[str] = [];
    for c in grid {
        if c not in decl_set {
            miss.append(c);
        }
    }
    return miss;
}

def expand_manifest_corners(declared: list[str]) -> list[str] {
    filter_known_corners(declared);
    return full_pvt_grid();
}

def materialize_pvt_grid(anchor: graph_anchor) -> dict[str, corner] {
    store: dict[str, corner] = {};
    for p in PROCESS_CORNERS {
        for t in TEMP_CORNERS {
            for v in SUPPLY_CORNERS {
                cid: str = corner_key(p, t, v);
                nd = corner(cid=cid, process=p, temp=t, supply_v=v);
                anchor ++> nd;
                store[cid] = nd;
            }
        }
    }
    return store;
}

def wire_nominal_chain(store: dict[str, corner]) -> None {
    keys: list[str] = sorted(store.keys());
    if len(keys) < 2 {
        return;
    }
    prev = store[keys[0]] as corner;
    j: int = 1;
    while j < len(keys) {
        cur = store[keys[j]] as corner;
        prev +>:depends:+> cur;
        prev = cur;
        j += 1;
    }
}

def wire_diamond(store: dict[str, corner], anchor: graph_anchor) -> None {
    top = corner(cid="top", process="tt", temp=27, supply_v=1.80);
    left = corner(cid="left", process="tt", temp=27, supply_v=1.80);
    right = corner(cid="right", process="tt", temp=27, supply_v=1.80);
    bot = corner(cid="bot", process="tt", temp=27, supply_v=1.80);
    anchor ++> top;
    store["top"] = top;
    store["left"] = left;
    store["right"] = right;
    store["bot"] = bot;
    top +>:depends:+> right;
    top +>:depends:+> left;
    left +>:depends:+> bot;
    right +>:depends:+> bot;
}

def collect_closure(start_id: str, store: dict[str, corner]) -> list[str] {
    start_nd = store[start_id] as corner;
    w = start_nd spawn order_collect(claimed={});
    return w.found;
}
