def add_project(repo: Repo, pid: str) -> None {
    # no docstring
    if pid in repo.projects {
        return;
    }
    p = Project(pid=pid);
    repo.projects[pid] = p;
    repo ++> p;
}

def add_dependency(repo: Repo, frm: str, to: str) -> None {
    if frm not in repo.projects { return; }
    if to not in repo.projects { return; }
    fr: Project = repo.projects[frm] as Project;
    to_n: Project = repo.projects[to] as Project;
    fr +>:Depends:+> to_n;
}

def add_contains(repo: Repo, parent: str, child: str) -> None {
    if parent not in repo.projects { return; }
    if child not in repo.projects { return; }
    par: Project = repo.projects[parent] as Project;
    ch: Project = repo.projects[child] as Project;
    par +>:Contains:+> ch;
}

