node Workspace { has name: str = "ws"; }
node SourceFile { has repo: str; has path: str; has fid: str; has link_conf: float = 0.0; }
node TestFile { has repo: str; has path: str; has tid: str; }
edge ContractEdge {}
edge CallEdge {}
edge ImportEdge {}
edge CoverageEdge {}
edge HasFile {}
edge HasTest {}

walker ImpactWalker {
    has claimed: dict[str, bool] = {};
    has found: list[dict[str, str]] = [];
    has depth: dict[str, int] = {};
    has provider_fid: str = "";
    can step_src with SourceFile entry {
        if here.fid in self.claimed { skip; }
        self.claimed[here.fid] = True;
        print(here.fid);
        cur: int = 0;
        if here.fid in self.depth { cur = self.depth[here.fid]; }
        if cur > 3 { skip; }
        for nxt in [here ->:ContractEdge:->][?:SourceFile] {
            if nxt.fid in self.claimed { continue; }
            self.depth[nxt.fid] = cur + 1;
            visit :0: [nxt];
        }
        for nxt in [here ->:CallEdge:->][?:SourceFile] {
            if nxt.fid in self.claimed { continue; }
            self.depth[nxt.fid] = cur + 1;
            visit :0: [nxt];
        }
        for t in [here ->:CallEdge:->][?:TestFile] {
            if t.tid in self.claimed { continue; }
            self.claimed[t.tid] = True;
            rec: dict[str, str] = {"repo": t.repo, "test_path": t.path, "basis": "inferred", "via": "call-graph", "confidence": str(here.link_conf), "source": self.provider_fid};
            self.found.append(rec);
            print(t.tid);
        }
        for t in [here ->:ImportEdge:->][?:TestFile] {
            if t.tid in self.claimed { continue; }
            self.claimed[t.tid] = True;
            rec: dict[str, str] = {"repo": t.repo, "test_path": t.path, "basis": "inferred", "via": "import-graph", "confidence": str(here.link_conf), "source": self.provider_fid};
            self.found.append(rec);
            print(t.tid);
        }
        for t in [here ->:CoverageEdge:->][?:TestFile] {
            if t.tid in self.claimed { continue; }
            self.claimed[t.tid] = True;
            rec: dict[str, str] = {"repo": t.repo, "test_path": t.path, "basis": "measured", "via": "coverage-map", "confidence": str(here.link_conf), "source": self.provider_fid};
            self.found.append(rec);
            print(t.tid);
        }
    }
    can step_test with TestFile entry {
        if here.tid in self.claimed { skip; }
        self.claimed[here.tid] = True;
        print(here.tid);
    }
}

def make_workspace(name: str) -> Workspace {
    ws = Workspace(name=name);
    root ++> ws;
    return ws;
}
def register_provider(ws: Workspace, repo: str, path: str) -> SourceFile {
    fid: str = repo + ":" + path;
    nd = SourceFile(repo=repo, path=path, fid=fid);
    ws +>:HasFile:+> nd;
    return nd;
}
def register_consumer_source(ws: Workspace, repo: str, path: str) -> SourceFile {
    fid: str = repo + ":" + path;
    nd = SourceFile(repo=repo, path=path, fid=fid);
    ws +>:HasFile:+> nd;
    return nd;
}
def register_test(ws: Workspace, repo: str, path: str) -> TestFile {
    tid: str = repo + ":" + path;
    nd = TestFile(repo=repo, path=path, tid=tid);
    ws +>:HasTest:+> nd;
    return nd;
}
def link_contract(provider: SourceFile, consumer: SourceFile, confidence: float) {
    consumer.link_conf = confidence;
    provider +>:ContractEdge:+> consumer;
}
def link_call(src: SourceFile, target: TestFile) {
    src +>:CallEdge:+> target;
}
def link_import(src: SourceFile, target: TestFile) {
    src +>:ImportEdge:+> target;
}
def link_coverage(src: SourceFile, target: TestFile) {
    src +>:CoverageEdge:+> target;
}
def link_call_src(src: SourceFile, dst: SourceFile) {
    src +>:CallEdge:+> dst;
}
def get_workspace_test_impact(ws: Workspace, changed: list[dict[str, str]]) -> list[dict[str, str]] {
    out: list[dict[str, str]] = [];
    seen: dict[str, bool] = {};
    for ch in changed {
        fid: str = ch["repo"] + ":" + ch["path"];
        for cand in [ws ->:HasFile:->][?:SourceFile] {
            if cand.fid != fid { continue; }
            w = cand spawn ImpactWalker(provider_fid=fid);
            for rec in w.found {
                key: str = rec["repo"] + ":" + rec["test_path"];
                if key in seen { continue; }
                seen[key] = True;
                out.append(rec);
            }
        }
    }
    n: int = len(out);
    i: int = 0;
    while i < n {
        j: int = 0;
        while j < n - 1 {
            a: dict[str, str] = out[j];
            b: dict[str, str] = out[j + 1];
            ak: str = a["repo"] + ":" + a["test_path"];
            bk: str = b["repo"] + ":" + b["test_path"];
            if ak > bk {
                tmp: dict[str, str] = out[j];
                out[j] = out[j + 1];
                out[j + 1] = tmp;
            }
            j = j + 1;
        }
        i = i + 1;
    }
    return out;
}
