def find_sub(store: dict[str, Subscription], sid: str) -> Subscription | None {
    # lookup with unknown-id tolerance
    if sid in store {
        return store[sid];
    }
    return None;
}

def make_store() -> dict[str, Subscription] {
    s: dict[str, Subscription] = {};
    return s;
}

def create_subscription(store: dict[str, Subscription], sid: str, user: str, is_folder: bool, unread: int) -> Subscription {
    nd = Subscription(sid=sid, user=user, is_folder=is_folder, unread=unread);
    root ++> nd;
    store[sid] = nd;
    return nd;
}

def can_set_parent(store: dict[str, Subscription], child_id: str, parent_id: str) -> bool {
    if child_id == parent_id { return False; }
    child = find_sub(store, child_id);
    if child is None { return False; }
    parent = find_sub(store, parent_id);
    if parent is None { return False; }
    c = child as Subscription;
    p = parent as Subscription;
    if !p.is_folder { return False; }
    if p.user != c.user { return False; }
    # cycle check: walk ancestors of parent looking for child
    chk = p spawn AncestorCheck(target_sid=c.sid, seen={}, cycle=False);
    if chk.cycle { return False; }
    return True;
}

def set_parent(store: dict[str, Subscription], child_id: str, parent_id: str) -> bool {
    if !can_set_parent(store, child_id, parent_id) { return False; }
    child = find_sub(store, child_id);
    parent = find_sub(store, parent_id);
    if child is None { return False; }
    if parent is None { return False; }
    c = child as Subscription;
    p = parent as Subscription;
    olds: list[Subscription] = [];
    for o in [c ->:Parent:->][?:Subscription] {
        olds.append(o);
    }
    for o in olds {
        c -:Parent:- o;
    }
    c +>:Parent:+> p;
    return True;
}

def get_descendants(store: dict[str, Subscription], root_id: str) -> list[str] {
    nd = find_sub(store, root_id);
    if nd is None { return []; }
    n = nd as Subscription;
    w = n spawn DescendantCollect(seen={}, out=[]);
    res: list[str] = [];
    for sid in w.out {
        if sid != root_id {
            res.append(sid);
        }
    }
    return sorted(res);
}

def get_unread_count(store: dict[str, Subscription], root_id: str) -> int {
    nd = find_sub(store, root_id);
    if nd is None { return 0; }
    n = nd as Subscription;
    w = n spawn UnreadCountWalker(seen={}, total=0);
    return w.total;
}

def mark_read(store: dict[str, Subscription], sid: str) -> bool {
    nd = find_sub(store, sid);
    if nd is None { return False; }
    n = nd as Subscription;
    n.unread = 0;
    return True;
}

def get_paginated_posts(store: dict[str, Subscription], root_id: str, offset: int, limit: int) -> list[str] {
    descs = get_descendants(store, root_id);
    out: list[str] = [];
    i: int = 0;
    for s in descs {
        if i >= offset {
            if len(out) < limit {
                out.append(s);
            }
        }
        i += 1;
    }
    return out;
}

def get_unread_subscription_list_for_user(store: dict[str, Subscription], user: str) -> list[str] {
    out: list[str] = [];
    seen_global: dict[str, bool] = {};
    roots: list[Subscription] = [];
    for sid in store {
        nd = store[sid] as Subscription;
        if nd.user != user { continue; }
        has_par = False;
        for pr in [nd ->:Parent:->][?:Subscription] {
            has_par = True;
        }
        if !has_par {
            roots.append(nd);
        }
    }
    for r in roots {
        w = r spawn UnreadCollectWalker(seen={}, out=[]);
        for sid in w.out {
            if sid not in seen_global {
                seen_global[sid] = True;
                nd2 = find_sub(store, sid);
                if nd2 is None { continue; }
                nn = nd2 as Subscription;
                if nn.user == user {
                    out.append(sid);
                }
            }
        }
    }
    # also include orphan unread nodes not reached from roots (legacy detached)
    for sid in store {
        if sid in seen_global { continue; }
        nd = store[sid] as Subscription;
        if nd.user != user { continue; }
        if nd.unread > 0 {
            # verify not already counted via parent walk
            has_par = False;
            for pr in [nd ->:Parent:->][?:Subscription] { has_par = True; }
            if !has_par {
                # orphan root missed because is_folder false root still needs inclusion
                out.append(sid);
                seen_global[sid] = True;
            }
        }
    }
    return sorted(out);
}

