def make_campaign(name: str) -> Campaign {
    # create campaign anchored at root
    c = Campaign(name=name);
    root ++> c;
    return c;
}

def make_issue(iid: str) -> IssueNode {
    # create issue node anchored at root
    n = IssueNode(iid=iid);
    root ++> n;
    return n;
}

def make_record(rid: str, campaign_name: str) -> Record {
    r = Record(rid=rid, campaign_name=campaign_name);
    root ++> r;
    return r;
}

def add_corner(camp: Campaign, cid: str, process: str, temp: int, supply: float) -> Corner {
    nd = Corner(cid=cid, process=process, temp=temp, supply=supply);
    camp +>:Covers:+> nd;
    return nd;
}

def attach_record(camp: Campaign, rec: Record) -> None {
    camp +>:HasRecord:+> rec;
}

def cover_record(rec: Record, corner: Corner) -> None {
    rec +>:Covers:+> corner;
}

def link_depends(src: IssueNode, dst: IssueNode) -> None {
    src +>:Depends:+> dst;
}

def link_references(src: IssueNode, dst: IssueNode) -> None {
    src +>:References:+> dst;
}

def link_supersedes(newer: Record, older: Record) -> None {
    newer +>:Supersedes:+> older;
}

def get_grid_corner_ids(camp: Campaign) -> list[str] {
    # collect all corner ids reachable from campaign via Covers/HasRecord
    w = camp spawn GridWalker(claimed={}, found=[]);
    # filter to corner ids only: walker found includes record rids and corner cids;
    # keep ids that look like PVT cids (contain underscore) or just sorted
    return sorted(w.found);
}

def get_depends_closure(start: IssueNode) -> list[str] {
    w = start spawn ClosureWalker(claimed={}, found=[]);
    return sorted(w.found);
}

def get_supersede_chain(start: Record) -> list[str] {
    w = start spawn ChainWalker(claimed={}, chain=[]);
    return w.chain;
}

def build_full_pvt_grid(camp: Campaign) -> list[str] {
    # populate the canonical 27-point grid tt/ss/ff x -40/27/125 x 1.62/1.80/1.98
    procs: list[str] = ["ff", "ss", "tt"];
    temps: list[int] = [-40, 27, 125];
    supplies: list[float] = [1.62, 1.8, 1.98];
    out: list[str] = [];
    p: str;
    for p in procs {
        t: int;
        for t in temps {
            s: float;
            for s in supplies {
                cid = p + "_" + str(t) + "_" + str(s);
                add_corner(camp, cid, p, t, s);
                out.append(cid);
            }
        }
    }
    return sorted(out);
}

