            prefix: str = user_id + ":";
            if k.startswith(prefix) {
                # avoid double append if already added
                found: bool = False;
                for o in owned { if o.org_id == nd.org_id { found = True; } }
                if !found { owned.append(nd); }
                break;
            }
        }
    }
    # also check ancestors of graph_root (in case graph_root not top)
    aw = graph_root spawn AncestorWalk(claimed={}, depths={}, result=[], nodes=[]);
    for nd in aw.nodes {
        already: bool = False;
        for o in owned { if o.org_id == nd.org_id { already = True; } }
        if already { continue; }
        for k in nd.assignments {
            if k.startswith(user_id + ":") { owned.append(nd); break; }
        }
    }
    acc: dict[str, bool] = {};
    result: list[str] = [];
    for own in owned {
        dw = own spawn DescendantWalk(claimed={}, depths={}, result=[], nodes=[]);
        for oid in dw.result {
            if oid not in acc {
                acc[oid] = True;
                result.append(oid);
            }
        }
    }
    return result;
}

