    for eid in ids {
        if eid in g.edge_ids and g.edge_ids[eid] {
            d: dict[str, str] = {};
            d["id"] = eid;
            res.append(d);
        }
    }
    return res;
}

def delete_nodes(g: GraphStore, ids: list[str]) -> dict[str, int] {
    for nid in ids {
        nd = find_node(g, nid);
        if nd is None { continue; }
        outs: list[GraphNode] = [nd ->:GraphEdge:->][?:GraphNode];
        for tgt in outs { nd -:GraphEdge:- tgt; }
        ins: list[GraphNode] = [nd <-:GraphEdge:<-][?:GraphNode];
        for src in ins { src -:GraphEdge:- nd; }
        nd.alive = False;
        g -:StoreLink:- nd;
    }
    g.mutation += 1;
    return {"mutationId": g.mutation};
}

def delete_edges(g: GraphStore, ids: list[str]) -> dict[str, int] {
    for eid in ids {
        if eid in g.edge_ids { g.edge_ids[eid] = False; }
    }
    g.mutation += 1;
    return {"mutationId": g.mutation};
}

def neighbors(g: GraphStore, node_id: str, direction: str | None = None, depth: int | None = None, limit: int | None = None) -> list[str] {
    dir: str = "out";
    if direction is not None { dir = direction; }
    d: int = 1;
    if depth is not None { d = depth; }
    lim: int = 100;
    if limit is not None { lim = limit; }
    nd = find_node(g, node_id);
    if nd is None { return []; }
    claimed: dict[str, bool] = {};
    depth_map: dict[str, int] = {};
    claimed[nd.nid] = True;
    depth_map[nd.nid] = 0;
    w = nd spawn NeighborsWalker(claimed=claimed, depth_map=depth_map, max_depth=d, direction=dir, limit=lim);
    res: list[str] = sorted(w.result);
    return res;
}

def shortest_path(g: GraphStore, from_id: str, to_id: str) -> list[str] {
    if from_id == to_id {
        nd = find_node(g, from_id);
        if nd is None { return []; }
        return [from_id];
    }
    fn = find_node(g, from_id);
    tn = find_node(g, to_id);
    if fn is None or tn is None { return []; }
    claimed: dict[str, bool] = {};
    parent: dict[str, str] = {};
    w = fn spawn ShortestPathWalker(claimed=claimed, parent=parent, target=to_id);
    return w.result;
}

def describe(g: GraphStore) -> dict[str, int] {
    c: int = 0;
    for nd in [g ->:StoreLink:->][?:GraphNode] {
        if nd.alive { c += 1; }
    }
    ec: int = 0;
    for k in g.edge_ids {
        if g.edge_ids[k] { ec += 1; }
    }
    return {"nodes": c, "edges": ec, "mutation": g.mutation};
}

