def blocked_by(svc: Service) -> list[str] {
    w = svc spawn CollectRequired(start_sid=svc.sid);
    return w.blocked_by;
}

def dependency_evidence(svc: Service) -> list[dict[str, str]] {
    w = svc spawn CollectRequired(start_sid=svc.sid);
    out: list[dict[str, str]] = [];
    for i in range(len(w.e_ids)) {
        d: dict[str, str] = {"target_id": w.e_ids[i], "target_state": w.e_states[i], "relation_type": "required"};
        out.append(d);
    }
    return out;
}

def dependency_state(svc: Service) -> str {
    w = svc spawn CollectRequired(start_sid=svc.sid);
    if w.has_unknown { return "unknown"; }
    if w.has_fail { return "fail"; }
    if w.has_degraded { return "degraded"; }
    if len(w.e_ids) == 0 { return "healthy"; }
    return "healthy";
}

def effective_state(svc: Service) -> str {
    # local failure always remains fail
    if svc.local_state == "fail" or svc.local_state == "stopped" { return "fail"; }
    if svc.app_probe_failed and svc.local_state != "healthy" and svc.local_state != "running" { return "fail"; }
    if svc.stale { return "unknown"; }
    if svc.local_state == "unknown" { return "unknown"; }
    w = svc spawn CollectRequired(start_sid=svc.sid);
    if w.has_unknown { return "unknown"; }
    if w.has_fail {
        if svc.app_probe_failed { return "fail"; }
        return "degraded";
    }
    if w.has_degraded { return "degraded"; }
    return svc.local_state;
}

def health_payload(svc: Service) -> dict[str, str] {
    return {"local_state": svc.local_state, "dependency_state": dependency_state(svc), "effective_state": effective_state(svc)};
}

