```jac
# iss_PingoLee__PormG.jl__459.jac
# Lift of PingoLee/PormG.jl#459: process_collector! mutated collector.objects
# while iterating it. Fixed by snapshotting work-list + visited guard
# via OSP walkers instead of hand-rolled dict/queue loops.

node Model {
    has mid: str;
}

edge Cascade {}

walker CascadeWalker {
    has claimed: dict[str, bool] = {};
    has collected: list[str] = [];
    can traverse with Model entry {
        if here.mid in self.claimed { skip; }
        self.claimed[here.mid] = True;
        self.collected.append(here.mid);
        kids: list[Model] = [];
        for nxt in [here ->:Cascade:->][?:Model] {
            kids.append(nxt);
        }
        if kids {
            visit :0: kids;
        } else {
            disengage;
        }
        print("visit " + here.mid);
    }
}

# build graph from model ids and cascade map, return node map
def build_model_nodes(all_ids: dict[str, bool]) -> dict[str, Model] {
    nodes: dict[str, Model] = {};
    for mid in all_ids {
        nd = Model(mid=mid);
        root ++> nd;
        nodes[mid] = nd;
    }
    return nodes;
}

def collect_cascade(seed: list[str], cascades: dict[str, list[str]]) -> list[str] {
    # collect full transitive cascade closure via walker (no dict-mutation hazard)
    all_ids: dict[str, bool] = {};
    for s in seed {
        all_ids[s] = True;
    }
    for k in cascades {
        all_ids[k] = True;
        for v in cascades[k] {
            all_ids[v] = True;
        }
    }
    nodes: dict[str, Model] = build_model_nodes(all_ids);
    for src in cascades {
        if src in nodes {
            src_nd = nodes[src];
            for dst in cascades[src] {
                if dst in nodes {
                    dst_nd = nodes[dst];
                    src_nd +>:Cascade:+> dst_nd;
                }
            }
        }
    }
    result: dict[str, bool] = {};
    for s in seed {
        if s in nodes {
            nd = nodes[s];
            w = nd spawn CascadeWalker(claimed={}, collected=[]);
            for mid in w.collected {
                result[mid] = True;
            }
        } else {
            result[s] = True;
        }
    }
    out: list[str] = [];
    for k in result {
        out.append(k);
    }
    return sorted(out);
}

def add_objects_to_collector(collector: dict[str, list[int]], model: str, keys: list[int]) -> dict[str, list[int]] {
    # merge keys, dedup via set-like dict; never mutates iterated view in caller
    if model in collector {
        seen: dict[int, bool] = {};
        for v in collector[model] {
            seen[v] = True;
        }
        for v in keys {
            if v not in seen {
                collector[model].append(v);
                seen[v] = True;
            }
        }
    } else {
        nxt: list[int] = [];
        for v in keys {
            nxt.append(v);
        }
        collector[model] = nxt;
    }
    return collector;
}

def process_collector(collector: dict[str, list[int]], cascades: dict[str, list[str]]) -> dict[str, list[int]] {
    # fixed: snapshot seed keys before traversal, then two-phase collect-then-mutate
    seed: list[str] = [];
    for k in collector {
        seed.append(k);
    }
    closure: list[str] = collect_cascade(seed, cascades);
    out: dict[str, list[int]] = {};
    for k in collector {
        out[k] = collector[k];
    }
    for mid in closure {
        if mid not in out {
            out[mid] = [1];
        }
    }
    return out;
}

