node Relation {
    has name: str;
    has kind: str;
    has view_sql: str = "";
}
node Program {
    has dialect: str = "duckdb";
}
node Hydration {
    has count: int = 0;
}
node Knowledge {
    has fact: str;
}
edge Contains {}
edge Depends {}
edge InHydration {}
edge HasKnowledge {}

walker HydrateWalk {
    has claimed: dict[str, bool] = {};
    has out: list[Relation] = [];
    can start with Program entry {
        print("hydrate start");
        for r in [here ->:Contains:->][?:Relation] {
            visit :0: [r];
        }
    }
    can expand with Relation entry {
        if here.name in self.claimed { skip; }
        self.claimed[here.name] = True;
        self.out.append(here);
        kids: list[Relation] = [];
        for nxt in [here ->:Depends:->][?:Relation] {
            kids.append(nxt);
        }
        if len(kids) > 0 {
            visit :0: kids;
        } else {
            disengage;
        }
        print(here.name);
    }
}

def make_program(dialect: str) -> Program {
    p = Program(dialect=dialect);
    root ++> p;
    return p;
}
def add_relation(prog: Program, name: str, kind: str, view_sql: str) -> Relation {
    r = Relation(name=name, kind=kind, view_sql=view_sql);
    root ++> r;
    prog +>:Contains:+> r;
    return r;
}
def add_dependency(src: Relation, dst: Relation) {
    src +>:Depends:+> dst;
}
def fetch_relation_metadata(prog: Program, names: list[str]) -> list[Relation] {
    res: list[Relation] = [];
    want: dict[str, bool] = {};
    for n in names {
        want[n] = True;
    }
    for r in [prog ->:Contains:->][?:Relation] {
        if r.name in want {
            res.append(r);
        }
    }
    return res;
}
def fetch_view_definition(rel: Relation) -> str {
    return rel.view_sql;
}
def hydrate(prog: Program) -> Hydration {
    w = prog spawn HydrateWalk();
    hyd = Hydration(count=0);
    root ++> hyd;
    for r in w.out {
        hyd +>:InHydration:+> r;
    }
    hyd.count = len(w.out);
    return hyd;
}
def bind(prog: Program, hyd: Hydration) -> list[Knowledge] {
    out: list[Knowledge] = [];
    for r in [hyd ->:InHydration:->][?:Relation] {
        k = Knowledge(fact="NonNullColumn:" + r.name);
        root ++> k;
        hyd +>:HasKnowledge:+> k;
        out.append(k);
        if r.kind == "table" {
            k2 = Knowledge(fact="UniqueSet:" + r.name);
            root ++> k2;
            out.append(k2);
        }
    }
    return out;
}

