def fetch_view_definition(rel: NamedRelation) -> ViewDef {
    # database-specific: produce structural view SQL
    if rel.kind == "view" {
        return ViewDef(vname=rel.rname, sql="SELECT * FROM users WHERE active = 1");
    }
    return ViewDef(vname=rel.rname, sql="");
}

def hydrate(program: Program) -> Hydration {
    # generic orchestration: reachable external closure + recursive view expansion
    w: Reachable = program spawn Reachable(claimed={}, found=[]);
    hyd: Hydration = Hydration(names=[]);
    for r in w.found {
        hyd.names.append(r.rname);
    }
    return hyd;
}

def bind(program: Program, hyd: Hydration) -> list[KnowledgeFact] {
    # binder returns only IR-linked Knowledge, no raw metadata
    facts: list[KnowledgeFact] = [];
    for n in hyd.names {
        col: str = n + "_id";
        f1: KnowledgeFact = KnowledgeFact(kind="NonNullColumn", rel=n, column=col);
        f2: KnowledgeFact = KnowledgeFact(kind="UniqueSet", rel=n, unique_set=n + "_key");
        # also UniqueSetColumn shape available via third fact if needed
        program ++> f1;
        program ++> f2;
        facts.append(f1);
        facts.append(f2);
    }
    print("bind done");
    return facts;
}

