def new_root(rid: str) -> GraphRoot {
    r = GraphRoot(rid=rid);
    return r;
}

def add_package(graph_root: GraphRoot, store: dict[str, Package], name: str, is_direct: bool, is_project_ref: bool) -> Package {
    p = Package(cid=name, name=name, is_direct=is_direct, is_project_ref=is_project_ref);
    store[name] = p;
    graph_root +>:Contains:+> p;
    return p;
}

def add_depends(store: dict[str, Package], parent_name: str, child_name: str) -> bool {
    if parent_name not in store { return False; }
    if child_name not in store { return False; }
    pp = store[parent_name];
    cc = store[child_name];
    pp +>:Depends:+> cc;
    return True;
}

def exclude_packages(graph_root: GraphRoot, store: dict[str, Package], filter_val: str) -> list[str] {
    matched: list[str] = [];
    for k, v in store.items() {
        if k == filter_val {
            matched.append(k);
        }
    }
    if len(matched) == 0 {
        print("exclude none");
        return sorted(matched);
    }
    for nm in matched {
        if nm in store {
            p = store[nm];
            graph_root -:Contains:-> p;
            preds: list[Package] = [p <-:Depends:-][?:Package];
            succs: list[Package] = [p ->:Depends:->][?:Package];
            for pr in preds { pr -:Depends:-> p; }
            for su in succs { p -:Depends:-> su; }
        }
    }
    for nm in matched {
        if nm in store { store.pop(nm); }
    }
    print("excluded");
    return sorted(matched);
}

def remove_orphaned_packages(graph_root: GraphRoot, store: dict[str, Package]) -> list[str] {
    if len(store) == 0 {
        print("no packages");
        return [];
    }
    w = graph_root spawn ReachWalker(claimed={}, reachable=[]);
    reachable_set: dict[str, bool] = {};
    for r in w.reachable { reachable_set[r] = True; }
    to_remove: list[str] = [];
    for k, v in store.items() {
        if k not in reachable_set { to_remove.append(k); }
    }
    for nm in to_remove {
        if nm in store {
            p = store[nm];
            graph_root -:Contains:-> p;
            preds: list[Package] = [p <-:Depends:-][?:Package];
            succs: list[Package] = [p ->:Depends:->][?:Package];
            for pr in preds { pr -:Depends:-> p; }
            for su in succs { p -:Depends:-> su; }
        }
    }
    for nm in to_remove { store.pop(nm); }
    print("orphan removed");
    return sorted(to_remove);
}

def remove_project_refs_and_make_direct(graph_root: GraphRoot, store: dict[str, Package]) -> int {
    cnt: int = 0;
    to_detach: list[str] = [];
    for k, v in store.items() {
        if v.is_project_ref { to_detach.append(k); }
    }
    for nm in to_detach {
        if nm in store {
            p = store[nm];
            deps: list[Package] = [p ->:Depends:->][?:Package];
            for d in deps {
                if not d.is_direct {
                    d.is_direct = True;
                    cnt += 1;
                }
            }
            graph_root -:Contains:-> p;
            preds: list[Package] = [p <-:Depends:-][?:Package];
            succs: list[Package] = [p ->:Depends:->][?:Package];
            for pr in preds { pr -:Depends:-> p; }
            for su in succs { p -:Depends:-> su; }
        }
    }
    for nm in to_detach { store.pop(nm); }
    print("project refs removed");
    return cnt;
}

