def mark_verified(root_node: ControlRoot, wid: str) -> bool {
    nd = find_ws(root_node, wid);
    if nd == None { return False; }
    nd.phase = "verified";
    return True;
}

def add_dependency(root_node: ControlRoot, from_wid: str, to_wid: str) -> bool {
    a = find_ws(root_node, from_wid);
    b = find_ws(root_node, to_wid);
    if a == None { return False; }
    if b == None { return False; }
    a +>:Depends:+> b;
    return True;
}

def can_promote(root_node: ControlRoot, wid: str) -> bool {
    # promotion allowed only if transitive deps are verified
    nd = find_ws(root_node, wid);
    if nd == None { return False; }
    deps: list[str] = get_transitive_closure(root_node, wid);
    for d in deps {
        if d == wid { continue; }
        dep_nd = find_ws(root_node, d);
        if dep_nd == None { continue; }
        if dep_nd.phase != "verified" { return False; }
    }
    return True;
}

