def new_graph() -> GraphRoot {
    g: GraphRoot = GraphRoot();
    return g;
}

def declare_enum(graph_root: GraphRoot, name: str) -> EnumDecl {
    nd: EnumDecl = EnumDecl(name=name, cid=name);
    graph_root +>:RootLink:+> nd;
    return nd;
}

def add_vec_ref(src: EnumDecl, target: EnumDecl) {
    src +>:Depends:+> target;
}

def ordered(graph_root: GraphRoot) -> list[str] {
    collector: Gather = graph_root spawn Gather();
    all_nodes: list[EnumDecl] = collector.nodes;
    names: list[str] = [];
    for nd in all_nodes {
        names.append(nd.name);
    }
    names = sorted(names);
    remaining: list[str] = names;
    result: list[str] = [];
    while len(remaining) > 0 {
        chosen: str = "";
        found: bool = False;
        for cur in remaining {
            cur_node: EnumDecl | None = None;
            for nd in all_nodes {
                if nd.name == cur {
                    cur_node = nd;
                }
            }
            if cur_node is None {
                continue;
            }
            deps_ok: bool = True;
            if cur_node is not None {
                deps: list[EnumDecl] = [cur_node ->:Depends:->][?:EnumDecl];
                for dep in deps {
                    seen: bool = False;
                    for r in result {
                        if r == dep.name {
                            seen = True;
                        }
                    }
                    if not seen {
                        deps_ok = False;
                    }
                }
            }
            if deps_ok {
                chosen = cur;
                found = True;
                break;
            }
        }
        if not found {
            print("cycle refused");
            return [];
        }
        result.append(chosen);
        new_rem: list[str] = [];
        removed: bool = False;
        for cur in remaining {
            if cur == chosen and not removed {
                removed = True;
            } else {
                new_rem.append(cur);
            }
        }
        remaining = new_rem;
    }
    print(result);
    return result;
}

def printers(graph_root: GraphRoot) -> list[str] {
    order: list[str] = ordered(graph_root);
    if len(order) == 0 {
        print("printers empty or cycle refused");
        return [];
    }
    res: list[str] = [];
    for n in order {
        res.append("def tl_show_" + n);
    }
    print(res);
    return res;
}

