def cid_of(p: str, t: int, v: float) -> str {
    ts: str = "27";
    if t == -40 { ts = "-40"; }
    if t == 125 { ts = "125"; }
    vs: str = "1.8";
    if v == 1.62 { vs = "1.62"; }
    if v == 1.98 { vs = "1.98"; }
    return p + "_" + ts + "_" + vs;
}

def make_pvt_grid() -> list[Corner] {
    proc_names: list[str] = ["tt", "ss", "ff"];
    temp_vals: list[int] = [-40, 27, 125];
    volt_vals: list[float] = [1.62, 1.8, 1.98];
    out: list[Corner] = [];
    for p in proc_names {
        for t in temp_vals {
            for v in volt_vals {
                cid: str = cid_of(p, t, v);
                c: Corner = Corner(proc=p, temp=t, volt=v, cid=cid);
                root ++> c;
                out.append(c);
            }
        }
    }
    return out;
}

