def compile_world(world_id: str, block_ids: list[str]) -> World {
    root_node = World(world_id=world_id);
    if len(block_ids) > 0 {
        root_node.entry_id = block_ids[0];
    }
    for block_id in block_ids {
        block = Block(block_id=block_id, title=block_id);
        root_node +>:Catalog:+> block;
    }
    return root_node;
}

def find_block(world: World, block_id: str) -> Block | None {
    finder = world spawn LookupWalker(target_id=block_id);
    return finder.found;
}

def add_choice_by_id(
    world: World,
    source_id: str,
    target_id: str,
    choice_id: str,
    label: str
) -> bool {
    source: Block | None = find_block(world, source_id);
    target: Block | None = find_block(world, target_id);
    if source is None or target is None {
        return False;
    }
    choice = Choice(choice_id=choice_id, label=label);
    source +>:HasChoice:+> choice;
    choice +>:ChoiceTarget:+> target;
    return True;
}

def add_fragment(block: Block, kind: str, value: str, label: str) -> bool {
    if kind != "content" and kind != "attributed" and kind != "media" {
        return False;
    }
    fragment = Fragment(kind=kind, value=value, label=label);
    block +>:HasFragment:+> fragment;
    return True;
}

def preview_block(block: Block) -> str {
    text: str = block.journal;
    for fragment in [block ->:HasFragment:->][?:Fragment] {
        if fragment.kind == "content" {
            text = text + "\n" + fragment.value;
        } elif fragment.kind == "attributed" {
            text = text + "\n**" + fragment.label + ":** " + fragment.value;
        } elif fragment.kind == "media" {
            text = text + "\n![" + fragment.label + "](" + fragment.value + ")";
        }
    }
    return text;
}

def publish_world(world: World) -> str {
    publisher = world spawn PublicationWalker();
    return publisher.output;
}
