def find_part(pkg: Package, path: str) -> Part | None {
    for part in [pkg ->:Contains:->][?:Part] {
        if part.path == path { return part; }
    }
    return None;
}

def new_package(package_id: str, max_entries: int = 256,
    max_compressed: int = 134217728, max_expanded: int = 536870912) -> Package {
    return Package(package_id=package_id, max_entries=max_entries,
        max_compressed=max_compressed, max_expanded=max_expanded);
}

def add_part(pkg: Package, path: str, content_type: str,
    compressed_size: int, expanded_size: int, malformed: bool = False,
    macro: bool = False, executable: bool = False) -> bool {
    if path == "" or path.startswith("/") {
        pkg.evidence.append("traversal:" + path);
        pkg.rejected = True;
        return False;
    }
    for segment in path.split("/") {
        if segment == ".." {
            pkg.evidence.append("traversal:" + path);
            pkg.rejected = True;
            return False;
        }
    }
    if find_part(pkg, path) != None {
        pkg.evidence.append("duplicate:" + path);
        pkg.rejected = True;
        return False;
    }
    if malformed or macro or executable or compressed_size < 0 or expanded_size < 0 {
        pkg.evidence.append("unsafe:" + path);
        pkg.rejected = True;
        return False;
    }
    part = Part(path=path, content_type=content_type,
        compressed_size=compressed_size, expanded_size=expanded_size);
    pkg +>:Contains:+> part;
    if path == "[Content_Types].xml" { pkg.has_content_types = True; }
    if path == "word/document.xml" { pkg.has_document = True; }
    return True;
}

def add_relationship(pkg: Package, source_path: str, target_path: str,
    external: bool = False) -> bool {
    if external {
        pkg.evidence.append("external:" + target_path);
        pkg.rejected = True;
        return False;
    }
    source = find_part(pkg, source_path);
    target = find_part(pkg, target_path);
    if source == None or target == None {
        pkg.evidence.append("missing-target:" + target_path);
        return False;
    }
    source +>:Relationship:+> target;
    return True;
}

def validate_package(pkg: Package) -> bool {
    if pkg.rejected or pkg.cancelled or pkg.revoked or not pkg.archive_ok or pkg.encrypted {
        return False;
    }
    if not pkg.has_content_types or not pkg.has_document {
        return False;
    }
    count = 0;
    compressed = 0;
    expanded = 0;
    for part in [pkg ->:Contains:->][?:Part] {
        count += 1;
        compressed += part.compressed_size;
        expanded += part.expanded_size;
    }
    if count > pkg.max_entries or compressed > pkg.max_compressed or expanded > pkg.max_expanded {
        return False;
    }
    return True;
}

def resolve_internal(pkg: Package, start_path: str) -> list[str] {
    found: list[str] = [];
    if not validate_package(pkg) { return found; }
    start = find_part(pkg, start_path);
    if start == None { return found; }
    walker = start spawn ResolveInternal(claimed={});
    return walker.found;
}

def sanitize_package(pkg: Package, start_path: str) -> list[str] {
    clean: list[str] = [];
    for path in resolve_internal(pkg, start_path) {
        part = find_part(pkg, path);
        if part != None {
            if part.content_type == "application/xml"
                or part.content_type == "application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"
                or part.content_type == "application/vnd.openxmlformats-package.relationships+xml" {
                clean.append(path);
            } else {
                pkg.evidence.append("omitted:" + path);
            }
        }
    }
    return clean;
}

def set_archive_state(pkg: Package, archive_ok: bool, encrypted: bool) {
    pkg.archive_ok = archive_ok;
    pkg.encrypted = encrypted;
}

def cancel_package(pkg: Package) {
    pkg.cancelled = True;
}

def revoke_source(pkg: Package) {
    pkg.revoked = True;
}
