    has used_expanded: int = 0;
    has required: list[str] = [];
    has issues: list[str] = [];
}

node Part {
    has path: str;
    has content_type: str;
    has compressed_size: int;
    has expanded_size: int;
    has malformed: bool = False;
    has macro: bool = False;
    has executable: bool = False;
    has accepted: bool = True;
}

node Relationship {
    has rel_id: str;
    has source: str;
    has target: str;
    has external: bool = False;
}

edge Contains {}
edge HasRelationship {}
edge FromPart {}
edge Resolves {}

def valid_path(path: str) -> bool {
    if path == "" { return false; }
    if path.startswith("/") { return false; }
    if "\\" in path { return false; }
    if ".." in path { return false; }
    return true;
}

walker SanitizeWalker {
    has claimed: dict[str, bool] = {};
    has paths: list[str] = [];

    can collect_pkg with Package entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        for part in [here ->:Contains:->][?:Part] {
            visit :0: [part];
        }
        print(self.paths);
    }

    can collect_part with Part entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        if here.accepted {
            self.paths.append(here.path);
        }
        print(self.paths);
    }
}

walker ResolveWalker {
    has claimed: dict[str, bool> = {};
    has seen_paths: dict[str, bool> = {};
    has start: str;
    has paths: list[str] = [];

    can resolve_part with Part entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        for rel in [here ->:FromPart:->][?:Relationship] {
            visit :0: [rel];
        }
        print(self.paths);
    }

    can resolve_relationship with Relationship entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        if here.external { skip; }
        for target in [here ->:Resolves:->][?:Part] {
            if not (target.path in self.seen_paths) {
                self.seen_paths[target.path] = True;
                self.paths.append(target.path);
            }
            visit :0: [target];
        }
        print(self.paths);
    }
}

def new_package(compressed_limit: int = 134217728, expanded_limit: int = 536870912) -> Package {
    return Package(compressed_limit=compressed_limit, expanded_limit=expanded_limit);
}

def add_part(pkg: Package, path: str, content_type: str, compressed_size: int, expanded_size: int, malformed: bool = False, macro: bool = False, executable: bool = False) -> bool {
    ok: bool = true;
    if not valid_path(path) { ok = false; }
    if content_type == "" { ok = false; }
    if compressed_size < 0 or expanded_size < 0 { ok = false; }
    if pkg.entry_count >= 4096 { ok = false; }
    if pkg.used_compressed + compressed_size > pkg.compressed_limit { ok = false; }
    if pkg.used_expanded + expanded_size > pkg.expanded_limit { ok = false; }
    if malformed or macro or executable { ok = false; }
    for old in [pkg ->:Contains:->][?:Part] {
        if old.path == path { ok = false; }
    }
    part = Part(path=path, content_type=content_type,
        compressed_size=compressed_size, expanded_size=expanded_size,
        malformed=malformed, macro=macro, executable=executable,
        accepted=ok);
    pkg ++> part;
    pkg.entry_count += 1;
    pkg.used_compressed += compressed_size;
    pkg.used_expanded += expanded_size;
    if not ok { pkg.issues.append(path); }
    return ok;
}

def add_relationship(pkg: Package, source: str, rel_id: str, target: str, external: bool = False) -> bool {
    ok: bool = not external;
    rel = Relationship(rel_id=rel_id, source=source, target=target, external=external);
    pkg +>:HasRelationship:+> rel;
    source_found: bool = false;
    target_found: bool = false;
    for part in [pkg ->:Contains:->][?:Part] {
        if part.path == source {
            source_found = true;
            part +>:FromPart:+> rel;
        }
        if part.path == target {
            target_found = true;
            rel +>:Resolves:+> part;
        }
    }
    if not source_found or not target_found { ok = false; }
    if not ok { pkg.issues.append(rel_id); }
    return ok;
}

def resolve_relationships(pkg: Package, source: str) -> list[str] {
    for part in [pkg ->:Contains:->][?:Part] {
        if part.path == source and part.accepted {
            walker = part spawn ResolveWalker(claimed={}, start=source);
            return sorted(walker.paths);
        }
    }
    return [];
}

def sanitize_package(pkg: Package) -> list[str] {
    walker = pkg spawn SanitizeWalker(claimed={});
    return sorted(walker.paths);
}

def validate_package(pkg: Package) -> bool {
    ok: bool = pkg.entry_count <= 4096;
    ok = ok and pkg.used_compressed <= pkg.compressed_limit;
    ok = ok and pkg.used_expanded <= pkg.expanded_limit;
    seen: dict[str, bool] = {};
    for part in [pkg ->:Contains:->][?:Part] {
        if part.path in seen { ok = false; }
        seen[part.path] = true;
        if not part.accepted { ok = false; }
    }
    for required_path in pkg.required {
        found: bool = false;
        for part in [pkg ->:Contains:->][?:Part] {
            if part.path == required_path and part.accepted {
                found = true;
            }
        }
        if not found { ok = false; }
    }
    if len(pkg.issues) > 0 { ok = false; }
    return ok;
}
