def delegation_tree(ws: Workspace, tid: str) -> list[str] {
    starts: list[Task] = find_tasks(ws, tid);
    if len(starts) == 0 {
        return [];
    }
    walk = starts[0] spawn Descendants(claimed={});
    return sorted(walk.found);
}

def submit_review(task: Task, approved: bool) -> str {
    if approved {
        task.review = "approved";
    } else {
