```jac
"""OSP lift for 2AMLogic/sky130-pll#54: full PVT measurement campaigns."""

node Campaign {
    has name: str;
}

node PVTPoint {
    has point_id: str;
    has corner: str;
    has temp: str;
    has supply: str;
}

edge Contains {}
edge Depends {}

walker MatrixWalk {
    has claimed: dict[str, bool] = {};
    has found: list[str] = [];

    can collect_campaign with Campaign entry {
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        print("campaign " + here.name);
        for point in [here ->:Contains:->][?:PVTPoint] {
            visit :0: [point];
        }
    }

    can collect_point with PVTPoint entry {
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        self.found.append(here.point_id);
        print("point " + here.point_id);
        for dependent in [here ->:Depends:->][?:PVTPoint] {
            visit :0: [dependent];
        }
    }
}

def _build_graph(campaign_name: str, selected: list[str] | None = None) -> Campaign {
    graph = Campaign(name=campaign_name);
    points: list[PVTPoint] = [];

    for corner in ["tt", "ss", "ff"] {
        for temp in ["-40", "27", "125"] {
            for supply in ["1.62", "1.80", "1.98"] {
                point_id = corner + "|" + temp + "|" + supply;
                include: bool = False;
                if selected is None {
                    include = True;
                } else {
                    if point_id in selected {
                        include = True;
                    }
                }
                if include {
                    point = PVTPoint(
                        point_id=point_id,
                        corner=corner,
                        temp=temp,
                        supply=supply
                    );
                    graph +>:Contains:+> point;
                    points.append(point);
                }
            }
        }
    }

    if len(points) >= 4 {
        points[0] +>:Depends:+> points[1];
        points[0] +>:Depends:+> points[2];
        points[1] +>:Depends:+> points[3];
        points[2] +>:Depends:+> points[3];
        points[3] +>:Depends:+> points[0];
    }
    return graph;
}

def pvt_points(campaign_name: str, selected: list[str] | None = None) -> list[str] {
    graph = _build_graph(campaign_name, selected);
    walker = graph spawn MatrixWalk(claimed={});
    result: list[str] = [];
    for point_id in walker.found {
        result.append(point_id);
    }
    return sorted(result);
}

def measurement_order(campaign_name: str, selected: list[str] | None = None) -> list[str] {
    graph = _build_graph(campaign_name, selected);
    walker = graph spawn MatrixWalk(claimed={});
    ordered: list[str] = [];
    for point_id in walker.found {
        ordered.append(point_id);
    }
    return ordered;
}

def remaining_points(
    campaign_name: str,
    selected: list[str] | None = None,
    completed: list[str] | None = None
) -> list[str] {
    all_points = pvt_points(campaign_name, selected);
    done: list[str] = [];
    if completed is not None {
        done = completed;
    }

    remaining: list[str] = [];
    for point_id in all_points {
        if point_id not in done {
            remaining.append(point_id);
        }
    }
    return remaining;
}
