def anchor_path(base: str, value: str) -> str {
    if len(value) == 0 {
        return base;
    }
    if value[0] == "/" {
        return value;
    }
    return base + "/" + value;
}

def render_requirement(req: LinkRequirement, owner: Package) -> str {
    if req.kind == "path" {
        path = req.value;
        if req.relative {
            path = anchor_path(owner.root_path, req.value);
        }
        return "-L" + path;
    }
    if req.kind == "lib" {
        return "-l" + req.value;
    }
    return req.value;
}

