"""ListenCloser/listencloser#417: audit public workflow intent separately from worker registration."""

node Workflow {
    has name: str;
}

node Capability {
    has name: str;
    has public: bool = False;
    has worker: bool = False;
}

edge Uses {}
edge Depends {}

walker BoundaryWalker {
    has claimed: dict[str, bool] = {};
    has names: list[str] = [];
    has violations: list[str] = [];

    can begin with Workflow entry {
        print(here.name);
        for cap in [here ->:Uses:->][?:Capability] {
            visit :0: [cap];
        }
    }

    can inspect with Capability entry {
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        self.names.append(here.name);
        print(here.name);
        if here.worker {
            if not here.public {
                self.violations.append(here.name);
            }
        }
        for dep in [here ->:Depends:->][?:Capability] {
            visit :0: [dep];
        }
    }
}

def build_registry(
    workflow_name: str,
    capability_names: list[str],
    worker_names: list[str],
    public_names: list[str],
    entry_names: list[str],
    links: list[list[str]]
) -> Workflow {
    graph_root = Workflow(name=workflow_name);
    caps: dict[str, Capability] = {};

    for name in capability_names {
        cap = Capability(name=name);
        if name in worker_names {
            cap.worker = True;
        }
        if name in public_names {
            cap.public = True;
        }
        caps[name] = cap;
    }

    for name in entry_names {
        if name in caps {
            graph_root +>:Uses:+> caps[name];
        }
    }

    for link in links {
        if len(link) >= 2 {
            source_name = link[0];
            target_name = link[1];
            if source_name in caps and target_name in caps {
                caps[source_name] +>:Depends:+> caps[target_name];
            }
        }
    }
    return graph_root;
}

def reachable_capabilities(graph_root: Workflow) -> list[str] {
    walker = graph_root spawn BoundaryWalker(claimed={});
    return sorted(walker.names);
}

def is_reachable(graph_root: Workflow, target_name: str) -> bool {
    walker = graph_root spawn BoundaryWalker(claimed={});
    for name in walker.names {
        if name == target_name {
            return True;
        }
    }
    return False;
}

def audit_public_boundary(graph_root: Workflow) -> list[str] {
    walker = graph_root spawn BoundaryWalker(claimed={});
    return sorted(walker.violations);
}
