// PROGRAM: iss_shruggietech__glitchpad__84.jac
// shruggietech/glitchpad#84

obj ZipEntry {
    has path: str;
    has compressed: int;
    has expanded: int;
    has compression: str;
    has kind: str;
    has content_type: str = "application/xml";
    has xml_ok: bool = True;
    has encrypted: bool = False;
    has central_ok: bool = True;
}

obj PackageRel {
    has source: str;
    has target: str;
    has external: bool = False;
    has kind: str = "officeDocument";
}

node DocxPackage {
    has label: str;
    has evidence: list[str] = [];
}

node Part {
    has path: str;
    has semantic: bool = True;
}

edge Contains {}
edge InternalRel {}

walker ResolveParts {
    has claimed: dict[str, bool] = {};
    has found: list[str] = [];

    can begin with DocxPackage entry {
        print(here.label);
        for part in [here ->:Contains:->][?:Part] {
            if part.path == "word/document.xml" {
                visit :0: [part];
            }
        }
    }

    can collect with Part entry {
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        if here.semantic {
            self.found.append(here.path);
        }
        print(here.path);
        for kid in [here ->:InternalRel:->][?:Part] {
            visit :0: [kid];
        }
    }
}

def _safe_path(path: str) -> bool {
    if path == "" or path.startswith("/") or "\\" in path {
        return False;
    }
    segments: list[str] = path.split("/");
    for segment in segments {
        if segment == "" or segment == "." or segment == ".." {
            return False;
        }
    }
    return True;
}

def ingest_docx(
    entries: list[ZipEntry],
    relationships: list[PackageRel],
    max_compressed: int = 134217728,
    max_expanded: int = 268435456
) -> dict[str, list[str]] {
    result: dict[str, list[str]] = {};
    empty_parts: list[str] = [];
    problems: list[str] = [];
    result["parts"] = empty_parts;
    result["evidence"] = problems;

    seen: dict[str, bool] = {};
    total_compressed: int = 0;
    total_expanded: int = 0;
    has_types: bool = False;
    has_document: bool = False;
    compressed_limit: int = max_compressed;
    if compressed_limit > 134217728 {
        compressed_limit = 134217728;
    }

    if len(entries) > 4096 {
        problems.append("entry-count");
    }
    for entry in entries {
        if not _safe_path(entry.path) {
            problems.append("unsafe-path:" + entry.path);
        }
        if entry.path in seen {
            problems.append("duplicate:" + entry.path);
        }
        seen[entry.path] = True;
        if entry.compressed < 0 or entry.expanded < 0 {
            problems.append("negative-size:" + entry.path);
        }
        total_compressed += entry.compressed;
        total_expanded += entry.expanded;
        if entry.compression != "store" and entry.compression != "deflate" {
            problems.append("compression:" + entry.path);
        }
        if entry.encrypted {
            problems.append("encrypted:" + entry.path);
        }
        if not entry.central_ok {
            problems.append("central-directory:" + entry.path);
        }
        if entry.content_type == "" {
            problems.append("content-type:" + entry.path);
        }
        if entry.path == "[Content_Types].xml" {
            has_types = True;
        }
        if entry.path == "word/document.xml" {
            has_document = True;
        }
        if entry.kind == "xml" and not entry.xml_ok {
            problems.append("malformed-xml:" + entry.path);
        }
        if entry.path == "word/vbaProject.bin" or entry.path.endswith(".exe") or
            entry.path.endswith(".dll") or entry.path.endswith(".bat") {
            problems.append("blocked-executable:" + entry.path);
        }
        if entry.kind != "xml" {
            problems.append("unsupported:" + entry.path);
        }
    }

    if total_compressed > compressed_limit {
        problems.append("compressed-limit");
    }
    if total_expanded > max_expanded {
        problems.append("expanded-limit");
    }
    if not has_types {
        problems.append("missing-content-types");
    }
    if not has_document {
        problems.append("missing-document");
    }
    if len(problems) > 0 {
        return result;
    }

    graph_root = DocxPackage(label="docx", evidence=problems);
    parts_by_path: dict[str, Part] = {};
    for entry in entries {
        part = Part(path=entry.path, semantic=entry.kind == "xml");
        graph_root ++> part;
        parts_by_path[entry.path] = part;
    }

    for rel in relationships {
        if rel.external {
            problems.append("external:" + rel.target);
        } else if not _safe_path(rel.target) {
            problems.append("unsafe-target:" + rel.target);
        } else if rel.source in parts_by_path and rel.target in parts_by_path {
            source_part = parts_by_path[rel.source];
            target_part = parts_by_path[rel.target];
            source_part +>:InternalRel:+> target_part;
        } else {
            problems.append("unknown-relationship:" + rel.source + "->" + rel.target);
        }
    }

    walker = graph_root spawn ResolveParts(claimed={}, found=[]);
    result["parts"] = sorted(walker.found);
    return result;
}
