def open_package(
    entries: list[str] | None = None,
    compressed_bytes: int = 0,
    expanded_bytes: int = 0,
    encrypted: bool = False,
    xml_ok: bool = True
) -> Package {
    if entries is None {
        entries = [];
    }
    pkg = Package(label="docx");
    seen: dict[str, bool] = {};
    has_types: bool = False;
    has_doc: bool = False;

    if compressed_bytes > 134217728 {
        pkg.valid = False;
        pkg.evidence.append("compressed-limit");
    }
    if expanded_bytes > 536870912 {
        pkg.valid = False;
        pkg.evidence.append("expansion-limit");
    }
    if encrypted {
        pkg.valid = False;
        pkg.evidence.append("encryption");
    }
    if xml_ok == False {
        pkg.valid = False;
        pkg.evidence.append("malformed-xml");
    }
    if len(entries) > 4096 {
        pkg.valid = False;
        pkg.evidence.append("entry-limit");
    }

    for name in entries {
        if name in seen {
            pkg.valid = False;
            pkg.evidence.append("duplicate");
        }
        seen[name] = True;
        if name == "../evil" {
            pkg.valid = False;
            pkg.evidence.append("traversal");
        }
        if name == "word/../evil" {
            pkg.valid = False;
            pkg.evidence.append("traversal");
        }
        if name == "/evil" {
            pkg.valid = False;
            pkg.evidence.append("absolute-path");
        }
        if name == "word/vbaProject.bin" {
            pkg.valid = False;
            pkg.evidence.append("macro");
        }
        if name == "bin/tool.exe" {
            pkg.valid = False;
            pkg.evidence.append("executable");
        }
        if name == "[Content_Types].xml" {
            has_types = True;
        }
        if name == "word/document.xml" {
            has_doc = True;
        }
        part = Part(name=name, kind="xml");
        pkg ++> part;
    }

    if has_types == False {
        pkg.valid = False;
        pkg.evidence.append("missing-content-types");
    }
    if has_doc == False {
        pkg.valid = False;
        pkg.evidence.append("missing-document");
    }
    print("package-opened");
    return pkg;
}

def add_relationship(
    package: Package,
    source_name: str,
    target_name: str,
    external: bool = False
) -> bool {
    source_scan = package spawn FindPart(wanted=source_name, claimed={});
    target_scan = package spawn FindPart(wanted=target_name, claimed={});
    if source_scan.found is None {
        return False;
    }
    if target_scan.found is None {
        return False;
    }
    source_node: Part = source_scan.found;
    target_node: Part = target_scan.found;
    rel = Relationship(target=target_name, external=external);
    source_node +>:HasRelationship:+> rel;
    rel +>:ResolvesTo:+> target_node;
    return True;
}

def resolve_relationships(package: Package, start_name: str) -> list[str] {
    if package.valid == False {
        return [];
    }
    walker = package spawn ResolveRelationships(
        start_name=start_name,
        claimed={}
    );
    return sorted(walker.found);
}

def inspect_package(package: Package) -> list[str] {
    notes: list[str] = [];
    for item in package.evidence {
        notes.append(item);
    }
    return sorted(notes);
}
