    root_node.blocked_by.clear();
    root_node.dependency_evidence.clear();
    root_node.cycle_detected = False;

    scan = root_node spawn DependencyScan(
        root_id=service_id,
        target=root_node,
        claimed={}
    );
    root_node.cycle_detected = scan.cycle_detected;

    if root_node.local_state == "failed" {
        root_node.effective_state = "failed";
    } else if root_node.local_state == "unknown" or root_node.stale or
        root_node.observation_age > 300 {
        root_node.effective_state = "degraded";
    } else if scan.failed_required or scan.unknown_required or
        scan.degraded_required or root_node.cycle_detected {
        root_node.effective_state = "degraded";
    } else {
        root_node.effective_state = root_node.local_state;
    }

    print(root_node.sid + ":" + root_node.effective_state);
    return root_node.effective_state;
}
