    if parent.depth >= handle.max_depth {
        return None;
    }
    if handle.total_count >= handle.max_total {
        return None;
    }
    child = Task(task_id=task_id, depth=parent.depth + 1);
    parent +>:Child:+> child;
    handle.total_count += 1;
    return child;
}

def add_dependency(prerequisite: Task, dependent: Task) -> bool {
    if prerequisite.task_id == dependent.task_id {
        return False;
    }
    dependent +>:Depends:+> prerequisite;
    return True;
}

def task_ready(task: Task) -> bool {
    if task.state != "pending" {
        return False;
    }
    for prerequisite in [task ->:Depends:->][?:Task] {
        if prerequisite.state != "approved" {
            return False;
        }
    }
    return True;
}

def complete_task(task: Task) -> bool {
    if task_ready(task) == False {
        return False;
    }
    task.state = "awaiting_review";
    return True;
}

def review_task(task: Task, approved: bool) -> bool {
    if task.state != "awaiting_review" {
        return False;
    }
    task.reviewed = True;
    if approved {
        task.state = "approved";
    } else {
        task.state = "rejected";
    }
    return True;
}

def link_siblings(first: AgentProfile, second: AgentProfile) -> bool {
    if first.profile_id == second.profile_id {
        return False;
    }
    first +>:Sibling:+> second;
    second +>:Sibling:+> first;
    return True;
}

def send_sibling_message(
    sender: AgentProfile, sibling: AgentProfile, message: str
) -> bool {
    if sender.coordinator == False {
        return False;
    }
    for peer in [sender ->:Sibling:->][?:AgentProfile] {
        if peer.profile_id == sibling.profile_id {
            sibling.inbox.append(message);
            return True;
        }
    }
    return False;
}

def inbox(profile: AgentProfile) -> list[str] {
    return profile.inbox;
}

def delegation_tree(graph_root: Task) -> list[str] {
    walker = graph_root spawn TreeWalk(claimed={});
    return walker.found;
}

def task_state(graph_root: Task, task_id: str) -> str {
    walker = graph_root spawn LookupWalk(target_id=task_id, claimed={});
    return walker.answer;
}
