                self.ids.append(sub.sid);
            }
        }
    }
}

walker Closure {
    has target: str = "";
    has collect: bool = False;
    has claimed: dict[str, bool] = {};
    has found: bool = False;
    has total: int = 0;
    has ids: list[str] = [];
    has posts: list[str] = [];

    can walk with Subscription entry {
        print("closure " + here.sid);
        if here.sid in self.claimed {
            skip;
        }
        self.claimed[here.sid] = True;
        self.ids.append(here.sid);
        if here.sid == self.target {
            self.found = True;
        }
        if self.collect {
            self.total = self.total + len(here.unread_posts);
            for post in here.unread_posts {
                self.posts.append(post);
            }
        }
        for kid in [here ->:Parent:->][?:Subscription] {
            visit :0: [kid];
        }
    }
}

def locate(store: Store, sid: str) -> Subscription | None {
    scan = store.graph_root spawn CatalogScan(target=sid);
    return scan.found;
