    if cancelled {
        return {
            "accepted": [],
            "omitted": [],
            "rejected": ["cancelled"]
        };
    }

    package_node = DocxPackage(label="docx");
    if compressed_bytes < 0 or compressed_bytes > 134217728 {
        package_node.valid = False;
        package_node.rejected.append("compressed_limit");
    }
    if expanded_bytes < 0 or expanded_bytes > 134217728 {
        package_node.valid = False;
        package_node.rejected.append("expansion_limit");
