            package_node.rejected.append("traversal:" + path);
        } else if _forbidden_path(path) {
            package_node.valid = False;
            package_node.rejected.append("forbidden:" + path);
        } else {
            duplicate: bool = False;
            for old_part in package_node.parts {
                if old_part.path == path {
                    duplicate = True;
