            target_path: str = fields[1];
            if _external_target(target_path) {
                package_node.valid = False;
                package_node.rejected.append("external:" + relationship);
            } else if not _safe_path(target_path) {
                package_node.valid = False;
                package_node.rejected.append("traversal:" + relationship);
            } else {
                source: Part | None = None;
                target: Part | None = None;
                for part in package_node.parts {
                    if part.path == source_path {
                        source = part;
                    }
                    if part.path == target_path {
                        target = part;
                    }
                }
                if source == None or target == None {
                    package_node.omitted.append("unknown:" + relationship);
