def sanitizeDependencies(
    concepts: list[str], dependencies: list[dict[str, str]]
) -> list[dict[str, str]] {
    clean: list[dict[str, str]] = [];
    for dep in dependencies {
        left = slugify(dep["from"]);
        right = slugify(dep["to"]);
        left_ok: bool = False;
        right_ok: bool = False;
        for concept in concepts {
            cid = slugify(concept);
            if cid == left { left_ok = True; }
            if cid == right { right_ok = True; }
        }
        if left_ok and right_ok {
            clean.append({"from": left, "to": right});
        }
    }
    return clean;
}

def ingestMaterial(
    graph: LearningGraph,
    mid: str,
    concepts: list[str],
    dependencies: list[dict[str, str]],
    exercises: list[dict[str, str]]
) -> Material {
    material = Material(mid=mid);
    graph.graph +>:GraphMaterial:+> material;
    concept_nodes: list[KC] = [];

    for label in concepts {
        cid = slugify(label);
        finder = graph.graph spawn FindConcept(wanted=cid, claimed={});
        if len(finder.found) > 0 {
            existing: KC = finder.found[0];
            material +>:MaterialKC:+> existing;
            concept_nodes.append(existing);
        } else {
            created = KC(cid=cid, label=label);
            material +>:MaterialKC:+> created;
            concept_nodes.append(created);
        }
    }

    clean = sanitizeDependencies(concepts, dependencies);
    for dep in clean {
        source: KC | None = None;
        target: KC | None = None;
        for kid in concept_nodes {
            if kid.cid == dep["from"] { source = kid; }
            if kid.cid == dep["to"] { target = kid; }
        }
        if source != None {
            if target != None {
                source +>:KCDependency:+> target;
            }
        }
    }

    for item in exercises {
        owner: KC | None = None;
        for kid in concept_nodes {
            if kid.cid == slugify(item["kc"]) { owner = kid; }
        }
        if owner != None {
            exercise = Exercise(eid=item["id"], prompt=item["prompt"]);
            owner +>:KCExercise:+> exercise;
        }
    }
    return material;
}

def getGraphNeighborhood(graph: LearningGraph, cid: str) -> list[str] {
    finder = graph.graph spawn FindConcept(wanted=slugify(cid), claimed={});
    if len(finder.found) == 0 { return []; }
    walk = finder.found[0] spawn PrerequisiteWalker(
        start=slugify(cid), include_start=True, claimed={}
    );
    return sorted(walk.found);
}

def getPrerequisiteChain(graph: LearningGraph, cid: str) -> list[str] {
    finder = graph.graph spawn FindConcept(wanted=slugify(cid), claimed={});
    if len(finder.found) == 0 { return []; }
    walk = finder.found[0] spawn PrerequisiteWalker(
        start=slugify(cid), include_start=False, claimed={}
    );
    return sorted(walk.found);
}

def getExercisesForKc(graph: LearningGraph, cid: str) -> list[str] {
    finder = graph.graph spawn FindConcept(wanted=slugify(cid), claimed={});
    if len(finder.found) == 0 { return []; }
    walk = finder.found[0] spawn ExerciseWalker(claimed={});
    return sorted(walk.found);
}
