def link_cascade(
    collector: DeletionCollector,
    source_name: str,
    target_name: str
) -> bool {
    if source_name not in collector.models {
        return False;
    }
    if target_name not in collector.models {
        return False;
    }
    source_model = collector.models[source_name];
    target_model = collector.models[target_name];
    source_model +>:Cascade:+> target_model;
    return True;
}

