    claimed: dict[str, bool] = {};
    discovered: list[str] = [];
    for model_name in work {
        if model_name in claimed {
            continue;
        }
        if model_name not in collector.models {
            continue;
        }
        source_model = collector.models[model_name];
        w = source_model spawn CascadeWalker(claimed=claimed);
        for found_name in w.found {
            discovered.append(found_name);
        }
    }

    for model_name in discovered {
        if model_name not in collector.objects {
            collector.objects[model_name] = [];
