def admit_entry(state: IngestState, path: str, content_type: str,
                compressed_bytes: int, expanded_bytes: int,
                encrypted: bool, xml_ok: bool) -> bool {
    if not state.package.active or path == "" or path[0] == "/" {
        return False;
    }
    for segment in path.split("/") {
        if segment == ".." or segment == "" {
            return False;
        }
    }
    lower_path = path.lower();
    lower_type = content_type.lower();
    if "vba" in lower_path or lower_path.endswith(".exe") or
       lower_path.endswith(".dll") or encrypted {
        return False;
    }
    if "xml" in lower_type and not xml_ok {
        return False;
    }
    if path in state.parts or compressed_bytes < 0 or expanded_bytes < 0 {
        return False;
    }
    if compressed_bytes > 134217728 or expanded_bytes > 536870912 or
       state.package.used_entries >= state.package.declared_entries or
       state.package.used_compressed + compressed_bytes > 134217728 or
       state.package.used_expanded + expanded_bytes > 536870912 {
        return False;
    }
    unsupported: bool = not (lower_type == "application/xml" or
        lower_type == "application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml");
    part = Part(name=path, content_type=content_type, omitted=unsupported);
    state.package +>:Contains:+> part;
    state.parts[path] = part;
    state.package.used_entries += 1;
    state.package.used_compressed += compressed_bytes;
    state.package.used_expanded += expanded_bytes;
    if unsupported {
        state.reports.append("unsupported:" + path);
    }
    return True;
}

def add_relationship(state: IngestState, source: str, target: str,
                     external: bool) -> bool {
    if external {
        state.reports.append("external:" + source + "->" + target);
        return False;
    }
    if source not in state.parts or target not in state.parts {
        state.reports.append("unknown:" + source + "->" + target);
        return False;
    }
    source_part = state.parts[source];
    target_part = state.parts[target];
    source_part +>:Depends:+> target_part;
    return True;
}

def resolve_package(state: IngestState) -> list[str] {
    if not state.package.active {
