"""prisma/orm#4562 — recursive tree structures with adjacency-list relations."""

node Category {
    has id: str;
    has name: str;
    has parent_id: str | None = None;
}

edge ParentEdge {}

obj TreeStore {
    has nodes: dict[str, Category] = {};
}

walker DescendantWalker {
    has claimed: dict[str, bool] = {};
    has found: list[str] = [];

    can collect with Category entry {
        if here.id in self.claimed {
            skip;
        }
        self.claimed[here.id] = True;
        self.found.append(here.id);
        print(here.id);
        for kid in [here ->:ParentEdge:->][?:Category] {
            visit :0: [kid];
        }
    }
}

walker AncestorWalker {
    has claimed: dict[str, bool] = {};
    has found: list[str] = [];

    can collect with Category entry {
        if here.id in self.claimed {
            skip;
        }
        self.claimed[here.id] = True;
        self.found.append(here.id);
        print(here.id);
        for parent_node in [here <-:ParentEdge:<-][?:Category] {
            visit :0: [parent_node];
        }
    }
}

def new_tree -> TreeStore {
    return TreeStore();
}

def add_category(
    store: TreeStore,
    category_id: str,
    name: str,
    parent_id: str | None = None
) -> Category {
    if category_id in store.nodes {
        return store.nodes[category_id];
    }

    parent_ref: str | None = None;
    if parent_id != None {
        if parent_id in store.nodes {
            parent_ref = parent_id;
        }
    }

    category = Category(id=category_id, name=name, parent_id=parent_ref);
    store.nodes[category_id] = category;

    if parent_ref != None {
        parent_node: Category = store.nodes[parent_ref];
        parent_node +>:ParentEdge:+> category;
    }
    return category;
}

def get_children(store: TreeStore, category_id: str) -> list[str] {
    ids: list[str] = [];
    if category_id not in store.nodes {
        return ids;
    }

    category: Category = store.nodes[category_id];
    for child in [category ->:ParentEdge:->][?:Category] {
        ids.append(child.id);
    }
    return sorted(ids);
}

def get_descendants(
    store: TreeStore,
    category_id: str,
    include_self: bool = False
) -> list[str] {
    if category_id not in store.nodes {
        return [];
    }

    source: Category = store.nodes[category_id];
    w = source spawn DescendantWalker(claimed={}, found=[]);
    ids: list[str] = [];
    for found_id in w.found {
        if include_self or found_id != category_id {
            ids.append(found_id);
        }
    }
    return sorted(ids);
}

def get_ancestors(
    store: TreeStore,
    category_id: str,
    include_self: bool = False
) -> list[str] {
    if category_id not in store.nodes {
        return [];
    }

    source: Category = store.nodes[category_id];
    w = source spawn AncestorWalker(claimed={}, found=[]);
    ids: list[str] = [];
    for found_id in w.found {
        if include_self or found_id != category_id {
            ids.append(found_id);
        }
    }
    return sorted(ids);
}

def get_roots(store: TreeStore) -> list[str] {
    ids: list[str] = [];
    for category_id in store.nodes {
        category: Category = store.nodes[category_id];
        if category.parent_id == None {
            ids.append(category.id);
        }
    }
    return sorted(ids);
}
