            seen[spec.path] = True;
        }
        for segment in spec.path.split("/") {
            if segment == ".." {
                pkg.accepted = False;
                pkg.evidence.append("reject:traversal:" + spec.path);
            }
            if segment == "" {
                pkg.accepted = False;
                pkg.evidence.append("reject:path:" + spec.path);
            }
        }
        if spec.central_ok == False {
            pkg.accepted = False;
            pkg.evidence.append("reject:central:" + spec.path);
        }
        if spec.xml_valid == False {
            pkg.accepted = False;
            pkg.evidence.append("reject:xml:" + spec.path);
