    state.tasks.append(task);
    return True;
}

def delegate_task(
    state: CoordinatorState, parent_id: str, task_id: str,
    title: str, coordinator_id: str
) -> bool {
    parent = find_task(state, parent_id);
    profile = find_profile(state, coordinator_id);
    if parent is None { return False; }
    if profile is None { return False; }
    if not profile.coordinator_capable { return False; }
    if find_task(state, task_id) is not None { return False; }
    if parent.depth + 1 > state.max_depth { return False; }
    root_task = find_task(state, parent.root_id);
    if root_task is None { return False; }
    if root_task.subtask_count >= state.max_subtasks { return False; }
    child = Task(
        id=task_id, title=title, owner_id=coordinator_id,
        root_id=parent.root_id, depth=parent.depth + 1
    );
    parent +>:Child:+> child;
    state.tasks.append(child);
    root_task.subtask_count += 1;
    return True;
