node Profile {
    has name: str;
    has coordinator_capable: bool = False;
}

node Task {
    has tid: str;
    has state: str = "pending";
    has depth: int = 0;
    has root_id: str;
}

edge Child {}
edge Depends {}

obj CoordinatorPlan {
    has profile: Profile;
    has root_task: Task;
    has max_depth: int;
    has max_subtasks: int;
}

walker ScanTasks {
    has target: str = "";
    has root_id: str = "";
    has found: Task | None = None;
    has items: list[str] = [];
    has total: int = 0;
    has claimed: dict[str, bool] = {};

    can scan with Task entry {
        if here.tid in self.claimed { skip; }
        self.claimed[here.tid] = True;
        print(here.tid);
        if here.tid == self.target {
            self.found = here;
        }
        if here.tid != self.root_id {
            self.total += 1;
            self.items.append(here.tid + ":" + here.state);
        }
        for kid in [here ->:Child:->][?:Task] {
            visit :0: [kid];
        }
    }
}

def create_plan(profile_name: str, coordinator_capable: bool, max_depth: int, max_subtasks: int) -> CoordinatorPlan {
    profile = Profile(name=profile_name, coordinator_capable=coordinator_capable);
    root_task = Task(tid="root", state="pending", depth=0, root_id="root");
    return CoordinatorPlan(profile=profile, root_task=root_task, max_depth=max_depth, max_subtasks=max_subtasks);
}

def can_delegate(plan: CoordinatorPlan) -> bool {
    return plan.profile.coordinator_capable;
}

def can_message_siblings(plan: CoordinatorPlan) -> bool {
    return plan.profile.coordinator_capable;
}

def _scan(start: Task, root_id: str, target: str) -> ScanTasks {
    w = start spawn ScanTasks(target=target, root_id=root_id, claimed={});
    return w;
}

def subtask_count(plan: CoordinatorPlan) -> int {
    w = _scan(plan.root_task, plan.root_task.tid, "");
    return w.total;
}

def add_subtask(plan: CoordinatorPlan, parent_id: str, child_id: str) -> bool {
    if not can_delegate(plan) { return False; }
    parent_scan = _scan(plan.root_task, plan.root_task.tid, parent_id);
    parent_task = parent_scan.found;
    if parent_task is None { return False; }
    if _scan(plan.root_task, plan.root_task.tid, child_id).found is not None { return False; }
    if parent_task.depth + 1 > plan.max_depth { return False; }
    if subtask_count(plan) >= plan.max_subtasks { return False; }
    child = Task(tid=child_id, state="pending", depth=parent_task.depth + 1, root_id=plan.root_task.tid);
    parent_task +>:Child:+> child;
    return True;
}

def connect_existing(plan: CoordinatorPlan, parent_id: str, child_id: str) -> bool {
    if not can_delegate(plan) { return False; }
    parent_scan = _scan(plan.root_task, plan.root_task.tid, parent_id);
    parent_task = parent_scan.found;
    if parent_task is None { return False; }
    child_scan = _scan(plan.root_task, plan.root_task.tid, child_id);
    child_task = child_scan.found;
    if child_task is None { return False; }
    if parent_task.tid == child_task.tid { return False; }
    if parent_task.depth + 1 > plan.max_depth { return False; }
    back_scan = _scan(child_task, plan.root_task.tid, parent_task.tid);
    if back_scan.found is not None { return False; }
    parent_task +>:Child:+> child_task;
    return True;
}

def delegation_tree(plan: CoordinatorPlan) -> list[str] {
    w = _scan(plan.root_task, plan.root_task.tid, "");
    return sorted(w.items);
}

def submit_for_review(plan: CoordinatorPlan, task_id: str) -> bool {
    task_scan = _scan(plan.root_task, plan.root_task.tid, task_id);
    task = task_scan.found;
    if task is None { return False; }
    if task.state != "pending" { return False; }
    task.state = "review";
    return True;
}

def approve_task(plan: CoordinatorPlan, task_id: str) -> bool {
    task_scan = _scan(plan.root_task, plan.root_task.tid, task_id);
    task = task_scan.found;
    if task is None { return False; }
    if task.state != "review" { return False; }
    task.state = "approved";
    return True;
}
