def task_ready(task: Task) -> bool {
    for dependency in [task ->:Depends:->][?:Task] {
        if dependency.state != "done" {
            return False;
        }
    }
    return True;
}

def delegate_subtask(profile: Profile, parent: Task, child: Task, graph_root: Task) -> bool {
    if not profile.coordinator {
        return False;
    }
    known: list[str] = delegation_tree(graph_root);
    parent_found: bool = False;
    for task_id in known {
        if task_id == parent.tid {
            parent_found = True;
        }
        if task_id == child.tid {
            return False;
        }
    }
    if not parent_found or parent.root_id != graph_root.tid {
        return False;
    }
    if parent.depth >= graph_root.max_depth {
        return False;
    }
    if len(known) - 1 >= graph_root.max_total {
        return False;
    }
    child.depth = parent.depth + 1;
    child.root_id = graph_root.tid;
    child.max_depth = graph_root.max_depth;
    child.max_total = graph_root.max_total;
    parent +>:Child:+> child;
    return True;
}

def has_child(parent: Task, candidate: Task) -> bool {
