    can set_parent(child_id: str, parent_id: str) -> bool {
        if child_id not in self.subscriptions {
            return False;
        }
        if parent_id not in self.subscriptions {
            return False;
        }

        child = self.subscriptions[child_id];
        parent = self.subscriptions[parent_id];

        if child_id == parent_id {
            return False;
        }
        if parent.user_id != child.user_id {
            return False;
        }
        if not parent.is_folder {
            return False;
