def ingestMaterial(material_id: str, slugs: list[str]) -> list[KC] {
    concepts: list[KC] = [];
    for slug in slugs {
        concept = KC(
            material_id=material_id,
            slug=slug,
            title=slug
        );
        concepts.append(concept);
    }
    return concepts;
