                accepted=accepted
            );
            parts_by_name[name] = part;
            pkg +>:Contains:+> part;
        }
    }

    if compressed_total > max_compressed {
        report.errors.append("compressed-limit");
        blocked = True;
    }
    if expanded_total > max_expanded {
        report.errors.append("expansion-limit");
        blocked = True;
    }

    for required_name in required {
        if required_name not in parts_by_name {
            report.errors.append("missing-required");
            report.omitted.append(required_name);
            blocked = True;
        }
    }

    for source in relationships {
        if source in parts_by_name {
            src: Part = parts_by_name[source];
            for target in relationships[source] {
                external: bool = target.startswith("http:") or
                    target.startswith("https:") or target.startswith("mailto:");
                if target in parts_by_name and not external {
                    src +>:Rel:+> parts_by_name[target];
                } else {
                    ghost = Part(
                        name=target,
                        accepted=False,
                        external=external
                    );
                    src +>:Rel:+> ghost;
                    report.omitted.append(target);
                }
            }
        }
    }

    boot = pkg spawn Bootstrap(
        report=report,
        limit=max_expanded,
        blocked=blocked,
        cancelled=cancelled
    );
    report.disposed = True;

    out: dict[str, list[str]] = {};
    out["resolved"] = sorted(report.resolved);
    out["omitted"] = sorted(report.omitted);
    out["errors"] = sorted(report.errors);
    return out;
}
