def mark_evidence(graph_root: ControlPlane, workstream_key: str, verified: bool) -> bool {
    updated: bool = false;
    for ws in [graph_root ->:Contains:->][?:Workstream] {
        if ws.key == workstream_key {
            ws.evidence = verified;
            if verified {
                ws.status = "verified";
            } else {
                ws.status = "proposed";
            }
            updated = true;
        }
    }
    return updated;
}

def promotion_status(graph_root: ControlPlane, workstream_key: str) -> str {
    closure = dependency_closure(graph_root, workstream_key);
    if len(closure) == 0 {
        return "unknown";
    }
    blocked: bool = false;
    for dependency_key in closure {
        for ws in [graph_root ->:Contains:->][?:Workstream] {
            if ws.key == dependency_key and not ws.evidence {
                blocked = true;
            }
        }
    }
    if blocked {
        return "blocked";
    }
    return "ready";
}

def verify_claim(graph_root: ControlPlane, claim_key: str, verified: bool) -> bool {
    updated: bool = false;
    for claim in [graph_root ->:Contains:->][?:Claim] {
        if claim.key == claim_key {
            claim.verified = verified;
            updated = true;
        }
    }
    return updated;
}

