node RoleDefinition {
    has role_id: str;
    has permissions: list[str] = [];
    has inherits: list[str] = [];
}

edge Inherits {}

obj DrizzleRoleRegistry {
    has roles: dict[str, RoleDefinition] = {};
}

walker EffectivePermissions {
    has claimed: dict[str, bool] = {};
    has found: list[str] = [];

    can collect with RoleDefinition entry {
        if here.role_id in self.claimed {
            skip;
        }
        self.claimed[here.role_id] = True;

        for permission in here.permissions {
            if permission not in self.found {
                self.found.append(permission);
            }
        }

        for parent in [here ->:Inherits:->][?:RoleDefinition] {
            visit :0: [parent];
        }

        print(self.found);
    }
}

def register_role(
    registry: DrizzleRoleRegistry,
    role_id: str,
    permissions: list[str],
    inherits: list[str] | None = None
) -> None {
    parent_ids: list[str] = [];
    if inherits == None {
        parent_ids = [];
    } else {
        parent_ids = inherits;
    }

    role = RoleDefinition(
        role_id=role_id,
        permissions=permissions,
        inherits=parent_ids
    );
    registry.roles[role_id] = role;

    for parent_id in parent_ids {
        if parent_id in registry.roles {
            parent = registry.roles[parent_id];
            role +>:Inherits:+> parent;
        }
    }

    for existing in registry.roles.values() {
        if role_id in existing.inherits {
            existing +>:Inherits:+> role;
        }
    }
}

def get_role_permissions(
    registry: DrizzleRoleRegistry,
    role_id: str
) -> list[str] {
    if role_id not in registry.roles {
        return [];
    }

    role = registry.roles[role_id];
    w = role spawn EffectivePermissions(claimed={});
    return w.found;
}
