node Project { has name: str; }
node Task { has task_id: str; has state: str = "pending"; has next_seq: int = 0; }
node Event { has seq: int; has kind: str; has detail: str; }
node Feature { has key: str; }
node Component { has component_id: str; has risk: int = 0; }

edge HAS_TASK {}
edge HAS_EVENT {}
edge HAS_FEATURE {}
edge IMPACTS {}

def state_for_kind(kind: str) -> str {
    if kind == "started" { return "running"; }
    if kind == "verified" { return "verified"; }
    if kind == "accepted" { return "accepted"; }
    if kind == "failed" { return "failed"; }
    return kind;
}

def append_event(task: Task, kind: str, detail: str) -> Event {
    event = Event(seq=task.next_seq, kind=kind, detail=detail);
    task.next_seq += 1;
    task.state = state_for_kind(kind);
    task +>:HAS_EVENT:+> event;
    return event;
}

walker StateWalk {
    has claimed: dict[str, bool] = {};
    has state: str = "pending";
    has latest: int = -1;

    can collect_task with Task entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        for event in [here ->:HAS_EVENT:->][?:Event] { visit :0: [event]; }
        print(self.state);
    }

    can collect_event with Event entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        if here.seq > self.latest {
            self.latest = here.seq;
            self.state = state_for_kind(here.kind);
        }
        print(self.state);
    }
}

def rebuild_state(task: Task) -> str {
    w = task spawn StateWalk(claimed={});
    task.state = w.state;
    return w.state;
}

def task_state(graph_root: Project, task_id: str) -> str {
    for task in [graph_root ->:HAS_TASK:->][?:Task] {
        if task.task_id == task_id { return task.state; }
    }
    return "unknown";
}

walker FeatureWalk {
    has claimed: dict[str, bool] = {};
    has keys: list[str] = [];

    can collect_project with Project entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        for feature in [here ->:HAS_FEATURE:->][?:Feature] {
            visit :0: [feature];
        }
        print("feature-map");
    }

    can collect_feature with Feature entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        self.keys.append(here.key);
        print(here.key);
    }
}

def verification_feature_map(graph_root: Project) -> list[str] {
    w = graph_root spawn FeatureWalk(claimed={});
    return sorted(w.keys);
}

walker BlastWalk {
    has claimed: dict[str, bool] = {};
    has ids: list[str] = [];
    has risk_floor: int = 0;

    can collect_component with Component entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        if here.risk >= self.risk_floor { self.ids.append(here.component_id); }
        for child in [here ->:IMPACTS:->][?:Component] {
            visit :0: [child];
        }
        print(here.component_id);
    }
}

def risk_blast_radius(graph_root: Component, risk_floor: int = 0) -> list[str] {
    w = graph_root spawn BlastWalk(claimed={}, risk_floor=risk_floor);
    return sorted(w.ids);
}
