"""TARPS-group/pyEKI#15: Kronecker operators with graph dependencies."""

node Factor {
    has name: str;
    has rows: int = 0;
    has cols: int = 0;
}

node Kron {
    has name: str;
}

node KronLMC {
    has name: str;
    has terms: int = 0;
}

edge Depends {}

walker Closure {
    has claimed: dict[str, bool] = {};
    has found: list[str] = [];

    can collect_kron with Kron entry {
        if here.name in self.claimed {
            skip;
        }
        self.claimed[here.name] = True;
        self.found.append(here.name);
        print(here.name);
        for kid in [here ->:Depends:->][?:Kron] {
            visit :0: [kid];
        }
        for leaf in [here ->:Depends:->][?:Factor] {
            visit :0: [leaf];
        }
    }

    can collect_factor with Factor entry {
        if here.name in self.claimed {
            skip;
        }
        self.claimed[here.name] = True;
        self.found.append(here.name);
        print(here.name);
    }
}

def kron_shape(a_rows: int, a_cols: int, b_rows: int, b_cols: int) -> list[int] {
    return [a_rows * b_rows, a_cols * b_cols];
}

def kron_matvec(a: list[list[float]], b: list[list[float]], x: list[float]) -> list[float] {
    result: list[float] = [];
    if len(a) == 0 or len(b) == 0 {
        return result;
    }
    for i in range(len(a)) {
        for k in range(len(b)) {
            value: float = 0.0;
            for j in range(len(a[0])) {
                for l in range(len(b[0])) {
                    value += a[i][j] * b[k][l] * x[j * len(b[0]) + l];
                }
            }
            result.append(value);
        }
    }
    return result;
}

def kron_diag(a: list[float], b: list[float]) -> list[float] {
    result: list[float] = [];
    for left in a {
        for right in b {
            result.append(left * right);
        }
    }
    return result;
}

def kron_lmc_matvec(
    weights: list[float],
    terms: list[list[list[list[float]]]],
    x: list[float]
) -> list[float] {
    result: list[float] = [];
    if len(terms) == 0 {
        return result;
    }
    first: list[float] = kron_matvec(terms[0][0], terms[0][1], x);
    for value in first {
        result.append(0.0);
    }
    for q in range(len(terms)) {
        piece: list[float] = kron_matvec(terms[q][0], terms[q][1], x);
        for i in range(len(piece)) {
            result[i] += weights[q] * piece[i];
        }
    }
    return result;
}

def dependency_closure(
    links: dict[str, list[str]],
    start: str,
    factors: list[str]
) -> list[str] {
    kron_nodes: dict[str, Kron] = {};
    factor_nodes: dict[str, Factor] = {};

    for name in links {
        kron_nodes[name] = Kron(name=name);
    }
    for name in factors {
        factor_nodes[name] = Factor(name=name);
    }
    for name in links {
        current: Kron = kron_nodes[name];
        for child_name in links[name] {
            if child_name in kron_nodes {
                current +>:Depends:+> kron_nodes[child_name];
            } else if child_name in factor_nodes {
                current +>:Depends:+> factor_nodes[child_name];
            }
        }
    }
    if start not in kron_nodes {
        return [];
    }
    graph_root: Kron = kron_nodes[start];
    w = graph_root spawn Closure(claimed={});
    return sorted(w.found);
}
