# iss_TheLarkInn__aipm__1786.jac

node BuildReport {
    has compiler: str;
    has wall_seconds: float;
    has clean: bool = True;
}

node CompilationUnit {
    has unit_id: str;
    has crate: str;
    has version: str;
    has seconds: float;
    has mode: str = "build";
}

edge Contains {}
edge DependsOn {}

walker UnitCollector {
    has claimed: dict[str, bool] = {};
    has found: list[CompilationUnit] = [];

    can collect_report with BuildReport entry {
        print("walking build report");
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        for kid in [here ->:Contains:->][?:CompilationUnit] {
            visit :0: [kid];
        }
    }

    can collect_unit with CompilationUnit entry {
        print("walking compilation unit");
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        self.found.append(here);
        for kid in [here ->:DependsOn:->][?:CompilationUnit] {
            visit :0: [kid];
        }
    }
}

def add_unit(report: BuildReport, unit: CompilationUnit) {
    report +>:Contains:+> unit;
}

def connect_dependency(parent: CompilationUnit, dependency: CompilationUnit) {
    parent +>:DependsOn:+> dependency;
}

def find_unit(report: BuildReport, wanted: str) -> CompilationUnit | None {
    w = report spawn UnitCollector();
    for unit in w.found {
        if unit.unit_id == wanted {
            return unit;
        }
    }
    return None;
}

def dependency_closure(start: CompilationUnit) -> list[str] {
    w = start spawn UnitCollector();
    ids: list[str] = [];
    for unit in w.found {
        ids.append(unit.unit_id);
    }
    return ids;
}

def total_compile_seconds(report: BuildReport) -> float {
    w = report spawn UnitCollector();
    total: float = 0.0;
    for unit in w.found {
        total += unit.seconds;
    }
    return total;
}

def slowest_units(report: BuildReport, limit: int) -> list[str] {
    w = report spawn UnitCollector();
    remaining: list[CompilationUnit] = [];
    for unit in w.found {
        remaining.append(unit);
    }

    result: list[str] = [];
    while len(remaining) > 0 && len(result) < limit {
        best_index: int = 0;
        index: int = 1;
        while index < len(remaining) {
            if remaining[index].seconds > remaining[best_index].seconds {
                best_index = index;
            }
            index += 1;
        }
        best: CompilationUnit = remaining[best_index];
        result.append(best.crate + "@" + best.version);
        remaining.pop(best_index);
    }
    return result;
}

def duplicate_crates(report: BuildReport) -> list[str] {
    w = report spawn UnitCollector();
    counts: dict[str, int] = {};
    for unit in w.found {
        if unit.crate in counts {
            counts[unit.crate] = counts[unit.crate] + 1;
        } else {
            counts[unit.crate] = 1;
        }
    }

    duplicates: list[str] = [];
    for crate_name in counts {
        if counts[crate_name] > 1 {
            duplicates.append(crate_name);
        }
    }
    return sorted(duplicates);
}

def wall_clock_seconds(report: BuildReport) -> float {
    return report.wall_seconds;
}
