# Version the ordering used by provenance naming and migrate legacy tokens.

node Curve {
    has curve_id: str;
    has parent_set: str;
    has edge_rank_point: str;
    has rank_token: str = "";
}

edge Parent {}

obj NamingState {
    has ordering_version: str = "2";
    has legacy_tokens: dict[str, str] = {};
    has current_tokens: dict[str, str] = {};
}

walker ClosureWalker {
    has claimed: dict[str, bool] = {};
    has found: list[str] = [];

    can collect with Curve entry {
        if here.curve_id in self.claimed { skip; }
        self.claimed[here.curve_id] = True;
        self.found.append(here.curve_id);
        print(here.curve_id);
        for child in [here ->:Parent:->][?:Curve] {
            visit :0: [child];
        }
    }
}

walker RankWalker {
    has claimed: dict[str, bool] = {};
    has target_parent: str;
    has ordering_version: str;
    has tokens: list[str] = [];

    can rank with Curve entry {
        if here.curve_id in self.claimed { skip; }
        self.claimed[here.curve_id] = True;
        if here.parent_set == self.target_parent {
            self.tokens.append(
                stamp_rank(here, self.ordering_version)
            );
        }
        print(here.curve_id);
        for child in [here ->:Parent:->][?:Curve] {
            visit :0: [child];
        }
    }
}

def stamp_rank(curve: Curve, ordering_version: str) -> str {
    # The rank point is serialized inside an explicitly versioned token.
    return "v" + ordering_version + ":" + curve.parent_set + ":"
        + curve.edge_rank_point + ":" + curve.curve_id;
}

def migrate_on_load(state: NamingState) -> int {
    migrated: int = 0;
    for curve_id in state.legacy_tokens {
        if curve_id not in state.current_tokens {
            state.current_tokens[curve_id] =
                "v" + state.ordering_version + ":"
                + state.legacy_tokens[curve_id];
            migrated += 1;
        }
    }
    return migrated;
}

def load_rank(state: NamingState, curve_id: str) -> str {
    if curve_id in state.current_tokens {
        return state.current_tokens[curve_id];
    }
    return "";
}

def closure_ids(graph_root: Curve) -> list[str] {
    w = graph_root spawn ClosureWalker(claimed={});
    return w.found;
}

def name_group(state: NamingState, graph_root: Curve) -> list[str] {
    w = graph_root spawn RankWalker(
        target_parent=graph_root.curve_id,
        ordering_version=state.ordering_version,
        claimed={}
    );
    return sorted(w.tokens);
}
