# TESTS

test "diamond_revisit_is_claimed_once" {
    graph_root = Curve(
        curve_id="root", parent_set="", edge_rank_point=""
    );
    left = Curve(
        curve_id="left", parent_set="root", edge_rank_point="20|00|00"
    );
    right = Curve(
        curve_id="right", parent_set="root", edge_rank_point="30|00|00"
    );
    join = Curve(
        curve_id="join", parent_set="root", edge_rank_point="10|00|00"
    );

    graph_root +>:Parent:+> left;
    graph_root +>:Parent:+> right;
    left +>:Parent:+> join;
    right +>:Parent:+> join;
    join +>:Parent:+> graph_root;

    ids = closure_ids(graph_root);
    assert (sorted(ids) == ["join", "left", "right", "root"]);
}

test "migration_is_versioned_and_idempotent" {
    state = NamingState();
    state.legacy_tokens["left"] = "root:20|00|00:left";

    assert (migrate_on_load(state) == 1);
    assert (load_rank(state, "left") == "v2:root:20|00|00:left");
    assert (migrate_on_load(state) == 0);
    assert (load_rank(state, "missing") == "");
}

test "name_group_sorts_adversarial_diamond" {
    state = NamingState();
    graph_root = Curve(
        curve_id="root", parent_set="", edge_rank_point=""
    );
    left = Curve(
        curve_id="left", parent_set="root", edge_rank_point="20|00|00"
    );
    right = Curve(
        curve_id="right", parent_set="root", edge_rank_point="30|00|00"
    );
    join = Curve(
        curve_id="join", parent_set="root", edge_rank_point="10|00|00"
    );

    graph_root +>:Parent:+> left;
    graph_root +>:Parent:+> right;
    left +>:Parent:+> join;
    right +>:Parent:+> join;

    names = name_group(state, graph_root);
    assert (
        names == [
            "v2:root:10|00|00:join",
            "v2:root:20|00|00:left",
            "v2:root:30|00|00:right"
        ]
    );
}

test "empty_group_and_explicit_stamp" {
    state = NamingState();
    graph_root = Curve(
        curve_id="root", parent_set="", edge_rank_point=""
    );
    isolated = Curve(
        curve_id="other", parent_set="different", edge_rank_point="00|00|00"
    );

    graph_root +>:Parent:+> isolated;

    assert (
        stamp_rank(isolated, "3")
        == "v3:different:00|00|00:other"
    );
    assert (name_group(state, graph_root) == []);
}
