walker FindOrganization {
    has wanted: str;
    has found: Organization | None = None;
    has claimed: dict[str, bool] = {};

    can step_root with TenantRoot entry {
        if ("tenant-root" in self.claimed) { skip; }
        self.claimed["tenant-root"] = True;
        print("scan organizations");
        for org_node in [here ->:OwnsOrganization:->][?:Organization] {
            visit :0: [org_node];
        }
    }

    can step_org with Organization entry {
        if (here.oid in self.claimed) { skip; }
        self.claimed[here.oid] = True;
        print("inspect " + here.oid);
        if (here.oid == self.wanted) {
            self.found = here;
        }
    }
}

walker ReachTaxonomy {
    has found: list[str] = [];
    has claimed: dict[str, bool] = {};

    can step_org with Organization entry {
        if (("org:" + here.oid) in self.claimed) { skip; }
        self.claimed["org:" + here.oid] = True;
        print("reach organization " + here.oid);
        for cat in [here ->:HasCategory:->][?:Category] {
            visit :0: [cat];
        }
        for doc_type in [here ->:HasDocumentType:->][?:DocumentType] {
            visit :0: [doc_type];
