    can step_category with Category entry {
        if (("cat:" + here.cid) in self.claimed) { skip; }
        self.claimed["cat:" + here.cid] = True;
        self.found.append("category:" + here.cid);
        print("reach category " + here.cid);
        for cat in [here ->:Relates:->][?:Category] {
            visit :0: [cat];
        }
        for doc_type in [here ->:Relates:->][?:DocumentType] {
