        self.claimed["type:" + here.tid] = True;
        self.found.append("document_type:" + here.tid);
        print("reach document type " + here.tid);
        for cat in [here ->:Relates:->][?:Category] {
            visit :0: [cat];
        }
        for doc_type in [here ->:Relates:->][?:DocumentType] {
            visit :0: [doc_type];
        }
