}

def find_organization(graph_root: TenantRoot, organization_id: str)
    -> Organization | None {
    w = graph_root spawn FindOrganization(wanted=organization_id, claimed={});
    return w.found;
}

def create_organization(graph_root: TenantRoot, organization_id: str, name: str)
    -> bool {
    if (organization_id == "" || name == "") { return False; }
    if (find_organization(graph_root, organization_id) != None) { return False; }
    org_node = Organization(oid=organization_id, name=name);
    settings_node = OrganizationSettings();
    graph_root +>:OwnsOrganization:+> org_node;
    org_node +>:HasSettings:+> settings_node;
    return True;
}

def read_organization_settings(graph_root: TenantRoot, organization_id: str)
    -> OrganizationSettings | None {
    org_node = find_organization(graph_root, organization_id);
    if (org_node == None) { return None; }
    for settings_node in [org_node ->:HasSettings:->][?:OrganizationSettings] {
        return settings_node;
    }
    return None;
}

def update_organization_settings(
    graph_root: TenantRoot,
    organization_id: str,
    retention_days: int,
    expiration_required: bool
) -> bool {
    if (retention_days < 0) { return False; }
    settings_node = read_organization_settings(graph_root, organization_id);
    if (settings_node == None) { return False; }
    settings_node.retention_days = retention_days;
    settings_node.expiration_required = expiration_required;
    return True;
}

def create_category(
    graph_root: TenantRoot,
    organization_id: str,
    category_id: str,
    label: str
) -> bool {
    org_node = find_organization(graph_root, organization_id);
    if (org_node == None || category_id == "" || label == "") { return False; }
    for cat in [org_node ->:HasCategory:->][?:Category] {
        if (cat.cid == category_id || cat.label == label) { return False; }
    }
    cat_node = Category(cid=category_id, label=label);
    org_node +>:HasCategory:+> cat_node;
    return True;
}

def update_category(
    graph_root: TenantRoot,
    organization_id: str,
    category_id: str,
    label: str
) -> bool {
    org_node = find_organization(graph_root, organization_id);
    if (org_node == None || label == "") { return False; }
    for cat in [org_node ->:HasCategory:->][?:Category] {
        if (cat.cid == category_id) {
            cat.label = label;
            return True;
        }
    }
    return False;
}

def archive_category(
    graph_root: TenantRoot,
    organization_id: str,
    category_id: str
) -> bool {
    org_node = find_organization(graph_root, organization_id);
    if (org_node == None) { return False; }
    for cat in [org_node ->:HasCategory:->][?:Category] {
        if (cat.cid == category_id) {
            if (cat.used) { return False; }
            cat.active = False;
            return True;
        }
    }
    return False;
}

def list_active_categories(graph_root: TenantRoot, organization_id: str)
    -> list[str] {
    names: list[str] = [];
    org_node = find_organization(graph_root, organization_id);
    if (org_node == None) { return names; }
    for cat in [org_node ->:HasCategory:->][?:Category] {
        if (cat.active) { names.append(cat.label); }
    }
