```jac
node Agent {
    has agent_id: str;
    has principal: str;
    has workspace: str;
    has lineage: str;
    has parent_id: str = "";
    has ttl: int;
    has output_budget: int;
    has token_budget: int;
    has cost_budget: int;
    has model: str;
    has provider: str;
    has tool_policy: str;
    has status: str = "running";
    has output_used: int = 0;
    has logs: list[str] = [];
}

edge ChildOf {}

obj AgentRuntime {
    has agents: dict[str, Agent] = {};
    has idempotency: dict[str, str] = {};
    has allowed_models: list[str] = ["pi-default"];
    has allowed_providers: list[str] = ["pi"];
}

walker Descendants {
    has claimed: dict[str, bool] = {};
    has found: list[Agent] = [];

    can collect with Agent entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        self.found.append(here);
        print(here.agent_id);
        for kid in [here ->:ChildOf:->][?:Agent] {
            visit :0: [kid];
        }
    }
}

def visible(runtime: AgentRuntime, principal: str, workspace: str, agent_id: str) -> bool {
    if agent_id in runtime.agents {
        a = runtime.agents[agent_id];
        return a.principal == principal and a.workspace == workspace;
    }
    return False;
}

def agent_spawn(
    runtime: AgentRuntime,
    principal: str,
    workspace: str,
    lineage: str,
    agent_id: str,
    ttl: int,
    output_budget: int,
    token_budget: int,
    cost_budget: int,
    model: str,
    provider: str,
    tool_policy: str,
    idempotency_key: str,
    parent_id: str = ""
) -> dict[str, str] {
    if idempotency_key in runtime.idempotency {
        old_id = runtime.idempotency[idempotency_key];
        return {"agent_id": old_id, "status": runtime.agents[old_id].status};
    }
    if agent_id in runtime.agents or idempotency_key == "" {
        return {"agent_id": agent_id, "status": "rejected"};
    }
    if ttl <= 0 or output_budget <= 0 or token_budget <= 0 or cost_budget <= 0 {
        return {"agent_id": agent_id, "status": "rejected"};
    }
    if model not in runtime.allowed_models or provider not in runtime.allowed_providers {
        return {"agent_id": agent_id, "status": "rejected"};
    }
    if parent_id != "" {
        if parent_id not in runtime.agents {
            return {"agent_id": agent_id, "status": "rejected"};
        }
        parent = runtime.agents[parent_id];
        if parent.principal != principal or parent.workspace != workspace {
            return {"agent_id": agent_id, "status": "rejected"};
        }
    }
    a = Agent(
        agent_id=agent_id,
        principal=principal,
        workspace=workspace,
        lineage=lineage,
        parent_id=parent_id,
        ttl=ttl,
        output_budget=output_budget,
        token_budget=token_budget,
        cost_budget=cost_budget,
        model=model,
        provider=provider,
        tool_policy=tool_policy
    );
    runtime.agents[agent_id] = a;
    runtime.idempotency[idempotency_key] = agent_id;
    if parent_id != "" {
        parent +>:ChildOf:+> a;
    }
    a.logs.append("spawned");
    return {"agent_id": agent_id, "status": a.status};
}

def agent_status(runtime: AgentRuntime, principal: str, workspace: str, agent_id: str) -> dict[str, str] {
    if visible(runtime, principal, workspace, agent_id) {
        return {"agent_id": agent_id, "status": runtime.agents[agent_id].status};
    }
    return {"agent_id": agent_id, "status": "missing"};
}

def agent_logs(runtime: AgentRuntime, principal: str, workspace: str, agent_id: str) -> list[str] {
    logs: list[str] = [];
    if visible(runtime, principal, workspace, agent_id) {
        for line in runtime.agents[agent_id].logs {
            logs.append(line);
        }
    }
    return logs;
}

def agent_message(
    runtime: AgentRuntime,
    principal: str,
    workspace: str,
    agent_id: str,
    message: str
) -> dict[str, str] {
    if not visible(runtime, principal, workspace, agent_id) {
        return {"agent_id": agent_id, "status": "missing"};
    }
    a = runtime.agents[agent_id];
    if a.status != "running" or message == "" {
        return {"agent_id": agent_id, "status": "rejected"};
    }
    if a.output_used + len(message) > a.output_budget {
        return {"agent_id": agent_id, "status": "budget_exhausted"};
    }
    a.output_used += len(message);
    if len(a.logs) < 16 {
        a.logs.append(message);
    }
    return {"agent_id": agent_id, "status": "accepted"};
}

def agent_cancel(runtime: AgentRuntime, principal: str, workspace: str, agent_id: str) -> dict[str, str] {
    if not visible(runtime, principal, workspace, agent_id) {
        return {"agent_id": agent_id, "status": "missing"};
    }
    a = runtime.agents[agent_id];
    if a.status == "cancelled" {
        return {"agent_id": agent_id, "status": "cancelled"};
    }
    w = a spawn Descendants(claimed={}, found=[]);
    for descendant in w.found {
        descendant.status = "cancelled";
        if len(descendant.logs) < 16 {
            descendant.logs.append("cancelled");
        }
    }
    return {"agent_id": agent_id, "status": "cancelled"};
}

def agent_list(runtime: AgentRuntime, principal: str, workspace: str) -> list[str] {
    ids: list[str] = [];
    for agent_id in runtime.agents {
        if visible(runtime, principal, workspace, agent_id) {
            ids.append(agent_id);
        }
    }
    return sorted(ids);
}
