test "diamond revisit cancels each descendant once" {
    rt = AgentRuntime();
    agent_spawn(rt, "alice", "ws", "job", "r", 60, 100, 10, 10, "pi-default", "pi", "none", "k-r");
    agent_spawn(rt, "alice", "ws", "job", "left", 60, 100, 10, 10, "pi-default", "pi", "none", "k-l", "r");
    agent_spawn(rt, "alice", "ws", "job", "right", 60, 100, 10, 10, "pi-default", "pi", "none", "k-d", "r");
    agent_spawn(rt, "alice", "ws", "job", "leaf", 60, 100, 10, 10, "pi-default", "pi", "none", "k-x", "left");
    d = rt.agents["right"];
    leaf = rt.agents["leaf"];
    d +>:ChildOf:+> leaf;
    assert (agent_cancel(rt, "alice", "ws", "r")["status"] == "cancelled");
    assert (agent_status(rt, "alice", "ws", "leaf")["status"] == "cancelled");
    assert (len(agent_logs(rt, "alice", "ws", "leaf")) == 2);
}

test "unknown ids are tolerated" {
    rt = AgentRuntime();
