"""TimHoogervorst/Helix#595 — Source replaces containment."""

node SourceItem {
    has sid: str;
    has kind: str;
    has status: str = "active";
    has alive: bool = True;
    has source_path: list[str] = [];
}
node Project:SourceItem {}
node Folder:SourceItem {}
node Entry:SourceItem {}
node Entity:SourceItem {}
node Result:SourceItem {}

edge Contains {}

obj Catalog {
    has items: list[SourceItem] = [];
}

walker SourceWalk {
    has claimed: dict[str, bool] = {};
    has found: list[SourceItem] = [];

    can step with SourceItem entry {
        if here.sid in self.claimed {
            skip;
        }
        self.claimed[here.sid] = True;
        print here.sid;
        self.found.append(here);
        for child in [here ->:Contains:->][?:SourceItem] {
            if child.alive and child.sid not in self.claimed {
                child.source_path = here.source_path + [here.sid];
                visit :0: [child];
            }
        }
    }
}

def find_source(catalog: Catalog, source_id: str) -> SourceItem | None {
    for item in catalog.items {
        if item.alive and item.sid == source_id {
            return item;
        }
    }
    return None;
}

def walk_subtree(start: SourceItem) -> list[SourceItem] {
    w = start spawn SourceWalk(claimed={});
    return w.found;
}

def create_project(catalog: Catalog, project_id: str) -> Project {
    project = Project(
        sid=project_id,
        kind="project",
        source_path=[]
    );
    catalog.items.append(project);
    return project;
}

def create_folder(
    catalog: Catalog,
    folder_id: str,
    source_id: str
) -> Folder | None {
    parent = find_source(catalog, source_id);
    if parent is None {
        return None;
    }
    folder = Folder(sid=folder_id, kind="folder");
    catalog.items.append(folder);
    parent +>:Contains:+> folder;
    walk_subtree(parent);
    return folder;
}

def create_entry(
    catalog: Catalog,
    entry_id: str,
    source_id: str
) -> Entry | None {
    parent = find_source(catalog, source_id);
    if parent is None {
        return None;
    }
    entry = Entry(sid=entry_id, kind="entry");
    catalog.items.append(entry);
    parent +>:Contains:+> entry;
    walk_subtree(parent);
    return entry;
}

def register_entity(
    catalog: Catalog,
    entity_id: str,
    source_id: str
) -> Entity | None {
    parent = find_source(catalog, source_id);
    if parent is None {
        return None;
    }
    entity = Entity(sid=entity_id, kind="entity");
    catalog.items.append(entity);
    parent +>:Contains:+> entity;
    walk_subtree(parent);
    return entity;
}

def register_result(
    catalog: Catalog,
    result_id: str,
    entity_id: str
) -> Result | None {
    entity = find_source(catalog, entity_id);
    if entity is None or entity.kind != "entity" {
        return None;
    }
    result = Result(sid=result_id, kind="result");
    catalog.items.append(result);
    entity +>:Contains:+> result;
    walk_subtree(entity);
    return result;
}

def children_of(
    catalog: Catalog,
    source_id: str,
    recursive: bool = False
) -> list[str] {
    source = find_source(catalog, source_id);
    ids: list[str] = [];
    if source is None {
        return ids;
    }
    if recursive {
        for item in walk_subtree(source) {
            if item.sid != source.sid and item.alive {
                ids.append(item.sid);
            }
        }
        return sorted(ids);
    }
    for child in [source ->:Contains:->][?:SourceItem] {
        if child.alive {
            ids.append(child.sid);
        }
    }
    return sorted(ids);
}

def source_path_of(catalog: Catalog, source_id: str) -> list[str] {
    source = find_source(catalog, source_id);
    path: list[str] = [];
    if source is None {
        return path;
    }
    for segment in source.source_path {
        path.append(segment);
    }
    return path;
}

def cascade_status(
    catalog: Catalog,
    source_id: str,
    status: str
) -> list[str] {
    source = find_source(catalog, source_id);
    changed: list[str] = [];
    if source is None {
        return changed;
    }
    for item in walk_subtree(source) {
        if item.alive {
            item.status = status;
            changed.append(item.sid);
        }
    }
    return sorted(changed);
}

def delete_source(catalog: Catalog, source_id: str) -> list[str] {
    source = find_source(catalog, source_id);
    deleted: list[str] = [];
    if source is None {
        return deleted;
    }
    for item in walk_subtree(source) {
        if item.alive {
            item.alive = False;
            item.source_path = [];
            item.status = "deleted";
            deleted.append(item.sid);
        }
    }
    return sorted(deleted);
}
