# PROGRAM: iss_Velarixx__VelarixBot__150.jac
"""Velarixx/VelarixBot#150 durable, truthful multi-bot workflow state."""

node Workflow {
    has workflow_id: str;
}
node Task {
    has task_id: str;
    has status: str = "queued";
    has progress: int = 0;
    has activity: str = "thinking";
    has terminal: bool = False;
}
node FailureReason {
    has code: str;
    has retryable: bool = False;
}
node Result {
    has result_id: str;
    has payload: str;
    has delivery_state: str = "result_stored";
    has attempts: int = 0;
    has claimed: bool = False;
    has failure: FailureReason | None = None;
}
edge HasTask {}
edge DependsOn {}
edge CompletedBy {}
edge OfTask {}

walker DependencyWalk {
    has claimed: dict[str, bool] = {};
    has found: list[str] = [];

    can step with Task entry {
        if here.task_id in self.claimed { skip; }
        self.claimed[here.task_id] = True;
        self.found.append(here.task_id);
        print(here.task_id);
        for dep in [here ->:DependsOn:->][?:Task] {
            visit :0: [dep];
        }
    }
}

walker ReconcileWalk {
    has claimed: dict[str, bool] = {};
    has pending: list[str] = [];

    can inspect_workflow with Workflow entry {
        if ("workflow:" + here.workflow_id) in self.claimed { skip; }
        self.claimed["workflow:" + here.workflow_id] = True;
        print(here.workflow_id);
        for task in [here ->:HasTask:->][?:Task] {
            visit :0: [task];
        }
    }

    can inspect_task with Task entry {
        if ("task:" + here.task_id) in self.claimed { skip; }
        self.claimed["task:" + here.task_id] = True;
        print(here.task_id);
        for result in [here ->:CompletedBy:->][?:Result] {
            visit :0: [result];
        }
    }

    can inspect_result with Result entry {
        if ("result:" + here.result_id) in self.claimed { skip; }
        self.claimed["result:" + here.result_id] = True;
        print(here.result_id);
        for task in [here ->:OfTask:->][?:Task] {
            if here.delivery_state == "delivered" {
                task.activity = "settled";
            } else {
                if here.delivery_state == "delivery_failed" {
                    task.activity = "recoverable";
                } else {
                    task.activity = "delivery_pending";
                }
                self.pending.append(task.task_id);
            }
        }
    }
}

def create_workflow(workflow_id: str) -> Workflow {
    return Workflow(workflow_id=workflow_id);
}

def add_task(graph_root: Workflow, task_id: str,
             depends_on: list[Task] | None = None) -> Task {
    task = Task(task_id=task_id);
    graph_root +>:HasTask:+> task;
    if depends_on != None {
        for dep in depends_on {
            task +>:DependsOn:+> dep;
        }
    }
    return task;
}

def lookup_task(graph_root: Workflow, task_id: str) -> Task | None {
    for task in [graph_root ->:HasTask:->][?:Task] {
        if task.task_id == task_id { return task; }
    }
    return None;
}

def dependency_ids(start: Task) -> list[str] {
    w = start spawn DependencyWalk(claimed={});
    return sorted(w.found);
}

def record_progress(task: Task, percent: int) -> bool {
    if percent < 0 { return False; }
    if percent > 100 { return False; }
    task.progress = percent;
    task.status = "running";
    task.activity = "thinking";
    return True;
}

def complete_task(task: Task, payload: str) -> Result {
    for old in [task ->:CompletedBy:->][?:Result] {
        return old;
    }
    result = Result(result_id=task.task_id + "-result", payload=payload);
    task.status = "completed";
    task.progress = 100;
    task.terminal = True;
    task.activity = "delivery_pending";
    task +>:CompletedBy:+> result;
    result +>:OfTask:+> task;
    return result;
}

def claim_delivery(task: Task) -> Result | None {
    for result in [task ->:CompletedBy:->][?:Result] {
        if result.delivery_state == "result_stored" {
            result.delivery_state = "delivery_pending";
            result.claimed = True;
            result.attempts += 1;
            return result;
        }
        if result.delivery_state == "delivery_pending" {
            if result.claimed == False {
                result.claimed = True;
                result.attempts += 1;
                return result;
            }
        }
    }
    return None;
}

def finish_delivery(result: Result, succeeded: bool,
                    reason: FailureReason | None = None) -> str {
    if result.claimed == False { return result.delivery_state; }
    result.claimed = False;
    if succeeded {
        result.delivery_state = "delivered";
        result.failure = None;
    } else {
        result.delivery_state = "delivery_failed";
        if reason == None {
            result.failure = FailureReason(code="unknown", retryable=False);
        } else {
            result.failure = reason;
        }
    }
    for task in [result ->:OfTask:->][?:Task] {
        if succeeded { task.activity = "settled"; }
        else { task.activity = "recoverable"; }
    }
    return result.delivery_state;
}

def retry_delivery(result: Result) -> bool {
    if result.delivery_state != "delivery_failed" { return False; }
    if result.failure == None { return False; }
    if result.failure.retryable == False { return False; }
    if result.attempts >= 3 { return False; }
    result.delivery_state = "delivery_pending";
    result.claimed = False;
    return True;
}

def reconcile_activity(graph_root: Workflow) -> list[str] {
    w = graph_root spawn ReconcileWalk(claimed={});
    return sorted(w.pending);
}
