walker Pending {
    has pending: list[Turn] = [];
    has claimed: dict[str, bool] = {};

    can collect_campaign with Campaign entry {
        for item in [here ->:HAS_TURN:->][?:Turn] {
            visit :0: [item];
        }
        print("collect backlog");
    }

    can collect_turn with Turn entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        if here.processed == False {
            self.pending.append(here);
