    }
}

walker Reach {
    has start_seq: int = 0;
    has found: list[int] = [];
    has claimed: dict[str, bool] = {};

    can find_start with Campaign entry {
        for item in [here ->:HAS_TURN:->][?:Turn] {
            if item.seq == self.start_seq {
                visit :0: [item];
            }
        }
