            visit :0: [item];
        }
        for item in [here ->:HAS_FACT:->][?:Fact] {
            visit :0: [item];
        }
        print("snapshot campaign");
    }

    can snapshot_turn with Turn entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        if self.viewer == "dm" {
            self.values.append(f"turn:{here.seq}:{here.truth}");
        } else {
