def new_campaign(events: list[str], safe_lag: int = 3) -> Campaign {
    campaign = Campaign(safe_lag=safe_lag);
    seq: int = 1;
    for text in events {
        turn = Turn(seq=seq, text=text, truth=text);
        campaign +>:HAS_TURN:+> turn;
        seq += 1;
    }
    return campaign;
}

def _find_turn(campaign: Campaign, wanted: int) -> list[Turn] {
    w = campaign spawn Index(wanted_seq=wanted, claimed={});
    return w.found_turn;
}

def _find_fact(campaign: Campaign, wanted: str) -> list[Fact] {
    w = campaign spawn Index(wanted_key=wanted, claimed={});
    return w.found_fact;
}

def post_turn(campaign: Campaign, fail: bool = False) -> int {
    campaign.attempts += 1;
    w = campaign spawn Pending(claimed={});
    campaign.backlog = len(w.pending);
    if fail {
        return campaign.checkpoint;
    }
    if len(w.pending) > campaign.safe_lag {
        return campaign.checkpoint;
    }

    changed: bool = False;
    for turn in w.pending {
        if turn.processed == False {
            turn.processed = True;
            campaign.clock += 1;
            changed = True;
        }
    }

    next_seq: int = campaign.checkpoint + 1;
    advancing: bool = True;
    while advancing {
        advancing = False;
        for turn in w.pending {
            if turn.seq == next_seq && turn.processed {
                campaign.checkpoint = turn.seq;
                next_seq += 1;
                advancing = True;
            }
        }
    }

    if changed {
        campaign.summary_epoch += 1;
        campaign.embedding_epoch += 1;
    }
    campaign.backlog = 0;
    return campaign.checkpoint;
}

def link_dependency(campaign: Campaign, parent_seq: int, child_seq: int) -> bool {
    parents = _find_turn(campaign, parent_seq);
    children = _find_turn(campaign, child_seq);
    if len(parents) == 0 || len(children) == 0 || parent_seq == child_seq {
        return False;
    }
    parents[0] +>:DEPENDS:+> children[0];
    return True;
}

def upsert_fact(campaign: Campaign, key: str, value: str, secret: bool = False) -> bool {
    matches = _find_fact(campaign, key);
    if len(matches) > 0 {
        matches[0].value = value;
        if secret {
            matches[0].secret = True;
        }
        return False;
    }
    fact = Fact(key=key, value=value, secret=secret);
    campaign +>:HAS_FACT:+> fact;
    return True;
}

def repair_turn(
    campaign: Campaign,
    target_seq: int,
    replacement: str,
    retcon: bool = False,
    secret: bool = False
) -> bool {
    matches = _find_turn(campaign, target_seq);
    if len(matches) == 0 {
        return False;
    }
    turn = matches[0];
    old_value = turn.truth;
    turn.provenance.append(old_value);
    turn.truth = replacement;
    if secret {
        turn.repair_secret = True;
    }
    repair = Repair(
        seq=target_seq,
        old_value=old_value,
        new_value=replacement,
        retcon=retcon,
        secret=secret
    );
    campaign +>:HAS_REPAIR:+> repair;
    campaign.repairs += 1;
    if retcon {
        turn.retconned = True;
        campaign.retcons += 1;
    }
    campaign.summary_epoch += 1;
    campaign.embedding_epoch += 1;
    return True;
}

def project(campaign: Campaign, viewer: str) -> list[str] {
    w = campaign spawn Snapshot(viewer=viewer, claimed={});
    return sorted(w.values);
}

def reachable(campaign: Campaign, start_seq: int) -> list[int] {
    w = campaign spawn Reach(start_seq=start_seq, claimed={});
    return sorted(w.found);
}

def turn_history(campaign: Campaign, wanted: int) -> list[str] {
    matches = _find_turn(campaign, wanted);
    if len(matches) == 0 {
        return [];
    }
    return matches[0].provenance;
}
