) -> BinaryTarget {
    binary = BinaryTarget(
        name=name,
        target=target,
        artifact=artifact,
        supported=is_supported_target(target)
    );
    release ++> binary;
    release.binary_count += 1;
    return binary;
}

def connect_steps(before: BuildStep, after: BuildStep) -> None {
