        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        print here.name;
        if self.supported_only {
            if here.supported {
                self.artifacts.append(here.artifact);
            }
        } else {
            self.artifacts.append(here.artifact);
        }
        if self.wanted == here.name {
