node Package {
    has name: str;
}

edge Requires {}

walker DependencyWalk {
    has claimed: dict[str, bool] = {};
    has found: list[str] = [];

    can collect with Package entry {
        if here.name in self.claimed {
            skip;
        }
        self.claimed[here.name] = True;
        self.found.append(here.name);
        print(here.name);
        for needed in [here ->:Requires:->][?:Package] {
            visit :0: [needed];
        }
    }
}

def _make_nodes(
    packages: list[str],
    dependencies: dict[str, list[str]]
) -> dict[str, Package] {
    nodes: dict[str, Package] = {};

    for package_name in packages {
        if package_name not in nodes {
            item = Package(name=package_name);
            nodes[package_name] = item;
        }
    }

    for package_name in packages {
        if package_name in dependencies {
            for requirement in dependencies[package_name] {
                if requirement in nodes {
                    nodes[package_name] +>:Requires:+> nodes[requirement];
                }
            }
        }
    }
    return nodes;
}

def dependency_closure(
    packages: list[str],
    dependencies: dict[str, list[str]],
    start: str
) -> list[str] {
    nodes: dict[str, Package] = _make_nodes(packages, dependencies);
    if start not in nodes {
        return [];
    }
    w = nodes[start] spawn DependencyWalk(claimed={});
    return w.found;
}

def validate_dependency_graph(
    packages: list[str],
    dependencies: dict[str, list[str]]
) -> bool {
    nodes: dict[str, Package] = _make_nodes(packages, dependencies);

    for package_name in packages {
        if package_name in dependencies {
            for requirement in dependencies[package_name] {
                if requirement not in nodes {
                    return False;
                }
            }
        }
    }

    for package_name in packages {
        w = nodes[package_name] spawn DependencyWalk(claimed={});
        if len(w.found) == 0 {
            return False;
        }
    }
    return True;
}
