"""linq2db/linq2db#5822 — preserve UNION distinctness before projection."""

node CteRow {
    has cid: str;
    has counter: int = 0;
    has day: int = 0;
}

node ProjectedRow {
    has day: int = 0;
    has year: int = 0;
}

edge Next {}

walker CteReach {
    has claimed: dict[str, bool] = {};
    has found: list[CteRow] = [];

    can step with CteRow entry {
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        self.found.append(here);
        print here.cid;
        for kid in [here ->:Next:->][?:CteRow] {
            visit :0: [kid];
        }
    }
}

def build_recursive_cte(seed_day: int, horizon: int) -> CteRow {
    seed = CteRow(
        cid="row-0",
        counter=1,
        day=seed_day
    );
    previous = seed;
    for idx in range(1, horizon + 1) {
        current = CteRow(
            cid="row-" + idx,
            counter=idx + 1,
            day=seed_day + idx
        );
        previous +>:Next:+> current;
        previous = current;
    }
    return seed;
}

def collect_cte_rows(root_node: CteRow) -> list[CteRow] {
    w = root_node spawn CteReach(claimed={}, found=[]);
    return w.found;
}

def project_cte(root_node: CteRow) -> list[ProjectedRow] {
    rows = collect_cte_rows(root_node);
    projected: list[ProjectedRow] = [];
    for row in rows {
        projected.append(ProjectedRow(
            day=row.day,
            year=2000 + row.day
        ));
    }
    return projected;
}

def find_cte_row(root_node: CteRow, cid: str) -> CteRow | None {
    rows = collect_cte_rows(root_node);
    for row in rows {
        if row.cid == cid {
            return row;
        }
    }
    return None;
}
