node Phase {
    has pid: str;
    has label: str;
}

edge ContainsFeedback {}
edge ContainsRoute {}
edge ContainsPhase {}
edge NextPhase {}

walker FeedbackScan {
    has claimed: dict[str, bool] = {};
    has target: str = "";
    has found: list[Feedback] = [];

    can scan_governance with Governance entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        for item in [here ->:ContainsFeedback:->][?:Feedback] {
            visit :0: [item];
        }
        print("feedback scan");
    }

    can scan_feedback with Feedback entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        if here.fid == self.target {
            self.found.append(here);
        }
    }
}

walker RouteScan {
    has claimed: dict[str, bool] = {};
    has labels: list[str] = [];

    can scan_governance with Governance entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        for route in [here ->:ContainsRoute:->][?:Route] {
            visit :0: [route];
        }
        print("route scan");
    }

    can scan_route with Route entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        for phase in [here ->:ContainsPhase:->][?:Phase] {
            visit :0: [phase];
        }
    }

    can scan_phase with Phase entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        self.labels.append(here.label);
        for next_phase in [here ->:NextPhase:->][?:Phase] {
            visit :0: [next_phase];
        }
    }
}

def new_governance(name: str) -> Governance {
    return Governance(name=name);
}

def add_feedback(graph_root: Governance, fid: str, title: str, disposition: str) -> Feedback {
    item = Feedback(fid=fid, title=title, disposition=disposition);
    graph_root +>:ContainsFeedback:+> item;
    return item;
}

def add_route(graph_root: Governance, rid: str, label: str) -> Route {
    route = Route(rid=rid, label=label);
    graph_root +>:ContainsRoute:+> route;
    return route;
}

def add_phase(route: Route, pid: str, label: str) -> Phase {
    phase = Phase(pid=pid, label=label);
    route +>:ContainsPhase:+> phase;
    return phase;
}

def link_phase(first: Phase, second: Phase) -> bool {
    first +>:NextPhase:+> second;
    return True;
}

def collect_feedback(graph_root: Governance) -> list[str] {
    w = graph_root spawn FeedbackScan(claimed={}, target="");
    ids: list[str] = [];
    for item in [graph_root ->:ContainsFeedback:->][?:Feedback] {
        ids.append(item.fid);
    }
    return sorted(ids);
}

def close_feedback(graph_root: Governance, fid: str) -> bool {
    w = graph_root spawn FeedbackScan(claimed={}, target=fid);
    if len(w.found) == 0 {
        return False;
    }
    for item in w.found {
        item.closed = True;
    }
    return True;
}

def collect_route(graph_root: Governance) -> list[str] {
    w = graph_root spawn RouteScan(claimed={});
