    has rss: int = 0;
    has bounded: bool = true;
}
edge Contains {}
edge Resolves {}
edge Delegates {}
edge Spawns {}

walker HookAudit {
    has claimed: dict[str, bool] = {};
    has recursive: bool = false;
    has deterministic: bool = true;

    can walk_system with HookSystem entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        print("auditing hook system");
        for hook in [here ->:Contains:->][?:Hook] {
            visit :0: [hook];
        }
    }

    can walk_hook with Hook entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        print("auditing hook: " + here.command);
        for launcher in [here ->:Resolves:->][?:Launcher] {
            visit :0: [launcher];
        }
    }

    can walk_launcher with Launcher entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        print("resolved launcher: " + here.path);
        if here.bundled == False { self.deterministic = false; }
        if here.self_delegating { self.recursive = true; }
        for target in [here ->:Delegates:->][?:Launcher] {
            visit :0: [target];
        }
    }
}

walker ProcessAudit {
    has claimed: dict[str, bool] = {};
    has limit: int = 64;
    has count: int = 0;
    has total_rss: int = 0;
    has overflow: bool = false;

    can walk_system with HookSystem entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        print("auditing process tree");
        for process_node in [here ->:Contains:->][?:Process] {
            visit :0: [process_node];
        }
    }

    can walk_process with Process entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        self.count += 1;
        self.total_rss += here.rss;
        if self.count > self.limit { self.overflow = true; }
        print("process " + here.pid);
        for child in [here ->:Spawns:->][?:Process] {
            visit :0: [child];
        }
    }
}

walker FindLauncher {
    has claimed: dict[str, bool] = {};
    has wanted: str;
    has found: Launcher | None = None;

    can seek_system with HookSystem entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        print("searching launchers");
        for launcher in [here ->:Contains:->][?:Launcher] {
            visit :0: [launcher];
        }
    }

    can seek_launcher with Launcher entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        print("checking launcher: " + here.name);
        if here.name == self.wanted { self.found = here; }
        for target in [here ->:Delegates:->][?:Launcher] {
            visit :0: [target];
        }
    }
}

walker CancelTree {
    has claimed: dict[str, bool] = {};
    has found: list[Process] = [];

    can collect_process with Process entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        self.found.append(here);
        print("collecting process " + here.pid);
        for child in [here ->:Spawns:->][?:Process] {
            visit :0: [child];
        }
    }
}

def new_system(command: str, timeout: int = 10, max_processes: int = 64) -> HookSystem {
    return HookSystem(command=command, timeout=timeout, max_processes=max_processes);
}

def add_hook(graph_root: HookSystem, command: str, timeout: int = 10) -> Hook {
    hook = Hook(command=command, timeout=timeout);
    graph_root +>:Contains:+> hook;
    return hook;
}

def add_launcher(graph_root: HookSystem, name: str, path: str, bundled: bool = false) -> Launcher {
    launcher = Launcher(name=name, path=path, bundled=bundled);
    graph_root +>:Contains:+> launcher;
    return launcher;
}

def bind_hook(hook: Hook, launcher: Launcher) -> None {
    hook +>:Resolves:+> launcher;
}

def link_launcher(source: Launcher, target: Launcher) -> None {
    source +>:Delegates:+> target;
    if source.name == target.name { source.self_delegating = true; }
}

def add_process(graph_root: HookSystem, pid: int, rss: int = 0) -> Process {
    process_node = Process(pid=pid, rss=rss);
    graph_root +>:Contains:+> process_node;
    return process_node;
}

def link_process(parent: Process, child: Process) -> None {
    parent +>:Spawns:+> child;
}

def resolve_launcher(graph_root: HookSystem, name: str) -> Launcher | None {
    w = graph_root spawn FindLauncher(claimed={}, wanted=name);
    return w.found;
}

def inspect(graph_root: HookSystem) -> AuditResult {
    hooks = graph_root spawn HookAudit(claimed={});
    processes = graph_root spawn ProcessAudit(
        claimed={}, limit=graph_root.max_processes
    );
    result = AuditResult(
        recursive=hooks.recursive,
        deterministic=hooks.deterministic,
        process_count=processes.count,
        rss=processes.total_rss,
        bounded=processes.overflow == false
    );
    print("inspection complete");
    return result;
}

def cancel_process_tree(process_node: Process) -> int {
    w = process_node spawn CancelTree(claimed={});
    for item in w.found {
        item.alive = false;
    }
    return len(w.found);
}
