    names.append("authenticated session references and expiry without embedding raw credentials in plans");
    names.append("scheduled/stream ingestor triggers");
    names.append("change-set generation between repeated runs");
    return names;
}

def build_research_map() -> Finding {
    graph_root = Finding(name="OSINT research", classification="root");
    fanout = Finding(
        name="bounded parallel fan-out over a dynamic provider registry",
        classification=classify_semantic("bounded parallel fan-out over a dynamic provider registry")
