```jac
"""OSP lift for lyh970817/gwas#27."""

node Component {
    has cid: str;
    has reusable: bool = False;
    has test_only: bool = False;
    has duplicate: bool = False;
    has present: bool = True;
}

edge Depends {}

walker ReachabilityWalker {
    has claimed: dict[str, bool] = {};
    has found: list[str] = [];

    can step with Component entry {
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        self.found.append(here.cid);
        print(here.cid);
        for child in [here ->:Depends:->][?:Component] {
            visit :0: [child];
        }
    }
}

def audit_reachability(graph_root: Component) -> list[str] {
    w = graph_root spawn ReachabilityWalker(claimed={});
    return sorted(w.found);
}

def classify_components(
    graph_root: Component, inventory: list[Component]
) -> dict[str, str] {
    reachable: list[str] = audit_reachability(graph_root);
    labels: dict[str, str] = {};
    for item in inventory {
        if not item.present {
            labels[item.cid] = "orphaned";
        } elif item.test_only {
            labels[item.cid] = "test-only/self-referential";
        } elif item.duplicate {
            labels[item.cid] = "superseded duplicate";
        } elif item.reusable {
            labels[item.cid] =
                "standalone reusable component intentionally retained";
        } elif item.cid in reachable {
            labels[item.cid] = "active production dependency";
        } else {
            labels[item.cid] = "orphaned";
        }
    }
    return labels;
}

def removal_plan(
    graph_root: Component,
    inventory: list[Component],
    candidates: list[str],
) -> list[str] {
    labels: dict[str, str] = classify_components(graph_root, inventory);
    requested: dict[str, bool] = {};
    selected: dict[str, bool] = {};
    plan: list[str] = [];
    for cid in candidates {
        requested[cid] = True;
    }
    for item in inventory {
        if item.cid in requested {
            if item.cid in labels {
                if labels[item.cid] == "orphaned" ||
                    labels[item.cid] == "superseded duplicate" {
                    if not item.cid in selected {
                        selected[item.cid] = True;
                        plan.append(item.cid);
                    }
                }
            }
        }
    }
    return sorted(plan);
}

def apply_removals(
    inventory: list[Component], ids: list[str]
) -> list[str] {
    requested: dict[str, bool] = {};
    removed: list[str] = [];
    for cid in ids {
        requested[cid] = True;
    }
    for item in inventory {
        if item.cid in requested {
            if item.present {
                item.present = False;
                removed.append(item.cid);
            }
        }
    }
    return sorted(removed);
}
