```jac
"""Idiomatic OSP lift for nuxt-contrib/vue-bundle-renderer#398."""

node Chunk {
    has cid: str;
    has resource_type: str = "script";
}

node StyleAsset {
    has aid: str;
}

edge Imports {}
edge Styles {}

obj DependencyGraph {
    has chunks: dict[str, Chunk] = {};
    has assets: dict[str, StyleAsset] = {};
}

walker CollectDependencies {
    has origin: str;
    has claimed: dict[str, bool] = {};
    has scripts: dict[str, bool] = {};
    has styles: dict[str, bool] = {};
    has preload: dict[str, bool] = {};
    has prefetch: dict[str, bool] = {};

    can collect with Chunk entry {
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        print(here.cid);

        if here.cid != self.origin {
            if here.resource_type == "script" {
                self.scripts[here.cid] = True;
            }
        }

        for asset in [here ->:Styles:->][?:StyleAsset] {
            self.styles[asset.aid] = True;
        }

        for kid in [here ->:Imports:->][?:Chunk] {
            visit :0: [kid];
        }
    }
}

def precomputeDependencies(
    manifest: dict[str, dict[str, str | list[str]]]
) -> dict[str, dict[str, dict[str, dict[str, bool]]]] {
    graph = DependencyGraph();

    for cid in manifest.keys() {
        graph.chunks[cid] = Chunk(cid=cid);
    }

    for cid in manifest.keys() {
        meta = manifest[cid];
        if "resourceType" in meta {
            graph.chunks[cid].resource_type = meta["resourceType"] as str;
        }

        if "imports" in meta {
            import_ids: list[str] = meta["imports"] as list[str];
            for dep_id in import_ids {
                if dep_id in graph.chunks {
                    src = graph.chunks[cid];
                    dst = graph.chunks[dep_id];
                    src +>:Imports:+> dst;
                }
            }
        }

        if "css" in meta {
            css_ids: list[str] = meta["css"] as list[str];
            for css_id in css_ids {
                if css_id not in graph.assets {
                    graph.assets[css_id] = StyleAsset(aid=css_id);
                }
                src = graph.chunks[cid];
                asset = graph.assets[css_id];
                src +>:Styles:+> asset;
            }
        }
    }

    dependencies: dict[str, dict[str, dict[str, bool]]] = {};
    for cid in manifest.keys() {
        wk = graph.chunks[cid] spawn CollectDependencies(
            origin=cid,
            claimed={},
            scripts={},
            styles={},
            preload={},
            prefetch={}
        );
        bundle: dict[str, dict[str, bool]] = {};
        bundle["scripts"] = wk.scripts;
        bundle["styles"] = wk.styles;
        bundle["preload"] = wk.preload;
        bundle["prefetch"] = wk.prefetch;
        dependencies[cid] = bundle;
    }

    result: dict[str, dict[str, dict[str, dict[str, bool]]]] = {};
    result["dependencies"] = dependencies;
    return result;
}
