        if here.provider_id in self.providers {
            if self.providers[here.provider_id] or here.exclusive {
                self.errors.append("exclusive:" + here.provider_id);
            }
        } else {
            self.providers[here.provider_id] = here.exclusive;
        }
        for dep in [here ->:DependsOn:->][?:Contribution] {
            visit :0: [dep];
