def new_plane(name: str) -> ExtensionPlane {
    return ExtensionPlane(name=name);
}

def register_provider(plane: ExtensionPlane, name: str, exclusive: bool = False) -> Provider | None {
    if plane.sealed or name == "" {
        return None;
    }
    provider = Provider(name=name, plane_name=plane.name, exclusive=exclusive);
    plane +>:Provides:+> provider;
    return provider;
}

def declare_contribution(
    plane: ExtensionPlane,
    provider: Provider | None,
    payload: str,
    exclusive: bool = False
) -> Contribution | None {
    if plane.sealed or provider is None {
        return None;
    }
    if provider.plane_name != plane.name or provider.name == "" {
        return None;
    }
    item = Contribution(
        plane_name=plane.name,
        provider_id=provider.name,
        payload=payload,
        exclusive=exclusive
    );
    plane +>:Declares:+> item;
    item +>:OwnedBy:+> provider;
    return item;
}

def freeze_plane(plane: ExtensionPlane) -> Generation | None {
    if plane.sealed {
        return None;
    }
    w = plane spawn PlaneWalk(claimed={}, request_plane="");
    serial = plane.generation + 1;
    gen = Generation(serial=serial, plane_name=plane.name);
    for item in w.found {
        gen +>:Includes:+> item;
    }
    plane +>:HasGeneration:+> gen;
    plane.generation = serial;
    plane.sealed = True;
    return gen;
}

def make_request(plane_name: str, payload: str) -> Request {
    return Request(plane_name=plane_name, payload=payload);
}

def dispatch(generation: Generation | None, request: Request) -> list[str] {
    results: list[str] = [];
    if generation is None {
        return results;
    }
    w = generation spawn PlaneWalk(claimed={}, request_plane=request.plane_name);
    for item in w.found {
        results.append(item.payload);
    }
    return results;
}

def diagnostics(generation: Generation | None) -> list[str] {
    errors: list[str] = [];
    if generation is None {
        return errors;
    }
    w = generation spawn Audit(claimed={}, providers={}, errors=[]);
    for item in w.errors {
        errors.append(item);
    }
    return sorted(errors);
}
