    state.network_size = len(w.found);
    state.truncated = w.truncated;
    return w.found;
}

def select_transport(
    root_node: TransportNode,
    state: NetworkState,
    limit: int = 10000
) -> list[str] {
    state.highlighted = [];
    state.presentation = {};
    state.flow = {};
    state.selected = root_node.nid;
    members: list[TransportNode] = trace_network(root_node, state, limit);
    for member in members {
        state.highlighted.append(member.nid);
        if member.kind in state.adapters {
            state.presentation[member.nid] = "adapter";
        } elif member.kind == "endpoint" {
            state.presentation[member.nid] = "endpoint";
        } elif member.kind in ["connector", "sorter", "lift", "balancer"] {
            state.presentation[member.nid] = "connector";
        } else {
            state.presentation[member.nid] = "transport";
        }
    }
    state.flow = flow_cues(members);
    return state.highlighted;
}

def clear_selection(state: NetworkState) -> list[str] {
    state.selected = "";
    state.highlighted = [];
    state.presentation = {};
    state.flow = {};
    state.network_size = 0;
    state.truncated = False;
