"""Architecture reconciliation campaign for pelaggio/pelaggio#624."""

node Intent {
    has key: str;
    has text: str;
    has active: bool = True;
}

node Realization {
    has key: str;
    has consequential: bool = False;
    has explained: bool = False;
    has stale: bool = False;
    has duplicated: bool = False;
    has policy_embedded: bool = False;
    has worker_owned: bool = False;
    has derived_needed: bool = False;
    has challenges_intent: bool = False;
    has outcome: str = "uncertain";
}

edge Child {}
edge Realizes {}
edge Challenges {}

obj Campaign {
    has graph_root: Intent;
}

walker ReconciliationWalker {
    has claimed: dict[str, bool] = {};
    has records: list[Realization] = [];

    can inspect_intent with Intent entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        print(here.key);
        for child in [here ->:Child:->][?:Intent] {
            visit :0: [child];
        }
        for realization in [here ->:Realizes:->][?:Realization] {
            visit :0: [realization];
        }
    }

    can inspect_realization with Realization entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        if here.consequential and
            (not here.explained or here.stale or here.duplicated or
             here.policy_embedded or here.worker_owned or
             here.derived_needed or here.challenges_intent) {
            self.records.append(here);
            print(here.key);
        }
        for challenged in [here ->:Challenges:->][?:Intent] {
            visit :0: [challenged];
        }
    }
}

def reconcile(campaign: Campaign) -> list[str] {
    w = campaign.graph_root spawn ReconciliationWalker(claimed={});
    keys: list[str] = [];
    for record in w.records {
        keys.append(record.key);
    }
    return sorted(keys);
}

def investigate(campaign: Campaign, candidate_id: str) -> str {
    w = campaign.graph_root spawn ReconciliationWalker(claimed={});
    for record in w.records {
        if record.key == candidate_id {
            return record.outcome;
        }
    }
    return "unknown";
}

def adjudicate(campaign: Campaign, candidate_ids: list[str]) -> list[str] {
    pending: list[str] = [];
    for candidate_id in candidate_ids {
        if investigate(campaign, candidate_id) == "uncertain" {
            pending.append(candidate_id);
        }
    }
    return sorted(pending);
}
