```jac
"""OSP lift for zackees/kernal-api#17: bounded opaque blobs and exact output capabilities."""

node Registry {}

node Blob {
    has id: str;
    has writable: bool = False;
    has closed: bool = False;
    has data: list[int] = [];
    has cursor: int = 0;
    has max_bytes: int = 0;
}

node OutputFile {
    has id: str;
    has authorized: bool = True;
    has atomic: bool = True;
    has temporary: list[int] = [];
    has committed: list[int] = [];
}

node WriteProgress {
    has accepted: int;
    has remaining: int;
    has ok: bool;
}

node ReadChunk {
    has chunk: list[int];
    has done: bool;
    has ok: bool;
}

edge Owns {}
edge Lineage {}

obj BlobRuntime {
    has registry: Registry;
    has max_chunk: int = 65536;
    has max_blob_bytes: int = 0;
}

walker BlobLookup {
    has wanted: str;
    has found: Blob | None = None;

    can inspect with Registry entry {
        print("lookup blob");
        for candidate in [here ->:Owns:->][?:Blob] {
            if candidate.id == self.wanted {
                self.found = candidate;
            }
        }
        disengage;
    }
}

walker OutputLookup {
    has wanted: str;
    has found: OutputFile | None = None;

    can inspect with Registry entry {
        print("lookup output capability");
        for candidate in [here ->:Owns:->][?:OutputFile] {
            if candidate.id == self.wanted {
                self.found = candidate;
            }
        }
        disengage;
    }
}

walker Reach {
    has claimed: dict[str, bool] = {};
    has found: list[str] = [];

    can descend with Blob entry {
        print("visit blob lineage");
        if here.id in self.claimed {
            skip;
        }
        self.claimed[here.id] = True;
        self.found.append(here.id);
        kids: list[Blob] = [];
        for kid in [here ->:Lineage:->][?:Blob] {
            kids.append(kid);
        }
        visit :0: [kids];
    }
}

def _find_blob(store: BlobRuntime, wanted: str) -> Blob | None {
    w = store.registry spawn BlobLookup(wanted=wanted);
    return w.found;
}

def _find_output(store: BlobRuntime, wanted: str) -> OutputFile | None {
    w = store.registry spawn OutputLookup(wanted=wanted);
    return w.found;
}

def blob_write_chunk(
    store: BlobRuntime, blob_id: str, bytes: list[int]
) -> WriteProgress {
    blob = _find_blob(store, blob_id);
    if blob == None or blob.closed or not blob.writable {
        return WriteProgress(accepted=0, remaining=0, ok=False);
    }
    quota: int = blob.max_bytes;
    if store.max_blob_bytes > 0 and store.max_blob_bytes < quota {
        quota = store.max_blob_bytes;
    }
    accepted: int = len(bytes);
    if accepted > store.max_chunk {
        accepted = store.max_chunk;
    }
    available: int = quota - len(blob.data);
    if accepted > available {
        accepted = available;
    }
    index: int = 0;
    while index < accepted {
        blob.data.append(bytes[index]);
        index += 1;
    }
    return WriteProgress(
        accepted=accepted, remaining=quota - len(blob.data), ok=True
    );
}

def blob_read_chunk(
    store: BlobRuntime, blob_id: str, max_bytes: int
) -> ReadChunk {
    blob = _find_blob(store, blob_id);
    if blob == None or blob.closed or blob.writable or max_bytes < 0 {
        return ReadChunk(chunk=[], done=False, ok=False);
    }
    limit: int = max_bytes;
    if limit > store.max_chunk {
        limit = store.max_chunk;
    }
    chunk: list[int] = [];
    index: int = 0;
    count: int = 0;
    for value in blob.data {
        if index >= blob.cursor and count < limit {
            chunk.append(value);
            count += 1;
        }
        index += 1;
    }
    blob.cursor += count;
    return ReadChunk(
        chunk=chunk, done=blob.cursor >= len(blob.data), ok=True
    );
}

def blob_close(store: BlobRuntime, blob_id: str) -> bool {
    blob = _find_blob(store, blob_id);
    if blob == None or blob.closed {
        return False;
    }
    blob.closed = True;
    return True;
}

def write_blob_to_output(
    store: BlobRuntime, blob_id: str, output_id: str
) -> bool {
    blob = _find_blob(store, blob_id);
    output = _find_output(store, output_id);
    if blob == None or output == None {
        return False;
    }
    if blob.closed or blob.writable or not output.authorized {
        return False;
    }
    if not output.atomic {
        output.temporary = [];
        return False;
    }
    temp: list[int] = [];
    for value in blob.data {
        temp.append(value);
    }
    output.temporary = temp;
    output.committed = temp;
    output.temporary = [];
    return True;
}
