"""Adamantine-guild/guildpass-core#379 permission inheritance resolver."""

node Role {
    has id: str;
    has permissions: list[str] = [];
    has inherits: list[str] = [];
}

edge Inherits {}

obj PermissionResult {
    has permissions: list[str] = [];
    has error_code: str = "";
    has error_role: str = "";
}

obj ResolutionState {
    has claimed: dict[str, bool] = {};
    has active: dict[str, bool] = {};
    has permissions: list[str] = [];
}

walker ResolveRole {
    has state: ResolutionState;
    has depth: int = 0;
    has max_depth: int = 32;
    has max_roles: int = 1000;
    has error_code: str = "";
    has error_role: str = "";

    can resolve_role with Role entry {
        if here.id in self.state.claimed {
            if here.id in self.state.active {
                self.error_code = "cycle";
                self.error_role = here.id;
            }
            skip;
        }
        if len(self.state.claimed) >= self.max_roles {
            self.error_code = "graph_limit";
            self.error_role = here.id;
            skip;
        }
        if self.depth > self.max_depth {
            self.error_code = "depth_limit";
            self.error_role = here.id;
            skip;
        }

        self.state.claimed[here.id] = True;
        self.state.active[here.id] = True;
        print("resolve " + here.id);

        for permission in here.permissions {
            if permission not in self.state.permissions {
                self.state.permissions.append(permission);
            }
        }

        edge_ids: list[str] = [];
        for parent in [here ->:Inherits:->][?:Role] {
            edge_ids.append(parent.id);
        }

        for parent_id in here.inherits {
            if parent_id not in edge_ids {
                if self.error_code == "" {
                    self.error_code = "missing_parent";
                    self.error_role = parent_id;
                }
            }
        }
        for edge_id in edge_ids {
            if edge_id not in here.inherits {
                if self.error_code == "" {
                    self.error_code = "malformed";
                    self.error_role = here.id;
                }
            }
        }

        for parent_id in sorted(edge_ids) {
            if self.depth + 1 > self.max_depth {
                if self.error_code == "" {
                    self.error_code = "depth_limit";
                    self.error_role = parent_id;
                }
            } else {
                for parent in [here ->:Inherits:->][?:Role] {
                    if parent.id == parent_id {
                        child = parent spawn ResolveRole(
                            state=self.state,
                            depth=self.depth + 1,
                            max_depth=self.max_depth,
                            max_roles=self.max_roles
                        );
                        if self.error_code == "" {
                            if child.error_code != "" {
                                self.error_code = child.error_code;
                                self.error_role = child.error_role;
                            }
                        }
                    }
                }
            }
        }
        self.state.active[here.id] = False;
    }
}

def resolve_permissions(
    roles: list[Role],
    role_id: str,
    max_depth: int = 32,
    max_roles: int = 1000
) -> PermissionResult {
    result = PermissionResult();
    if max_depth < 0 {
        result.error_code = "depth_limit";
        result.error_role = role_id;
        return result;
    }
    if max_roles < 1 {
        result.error_code = "graph_limit";
        result.error_role = role_id;
        return result;
    }

    ids: dict[str, bool] = {};
    target: Role | None = None;
    malformed = False;
    for role_node in roles {
        if role_node.id == "" {
            malformed = True;
        }
        if role_node.id in ids {
            malformed = True;
        }
        ids[role_node.id] = True;
        if role_node.id == role_id {
            target = role_node;
        }
    }
    if malformed {
        result.error_code = "malformed";
        result.error_role = role_id;
        return result;
    }
    if target == None {
        result.error_code = "unknown_role";
        result.error_role = role_id;
        return result;
    }

    state = ResolutionState();
    w = target spawn ResolveRole(
        state=state,
        depth=0,
        max_depth=max_depth,
        max_roles=max_roles
    );
    if w.error_code != "" {
        result.error_code = w.error_code;
        result.error_role = w.error_role;
        return result;
    }
    result.permissions = sorted(state.permissions);
    return result;
}
