"""DanMarshall909/workflow-tools#10: dependency-aware epic execution plans."""

node Epic {
    has eid: str;
    has title: str;
    has phase: int = 0;
}

node PlanRoot {}

edge Depends {}

obj ExecutionPlan {
    has anchor: PlanRoot;
    has epics: dict[str, Epic] = {};
}

walker ExecutionOrder {
    has claimed: dict[str, bool] = {};
    has ordered: list[str] = [];

    can begin with PlanRoot entry {
        print("execution-plan");
        for epic in [here ->:Depends:->][?:Epic] {
            visit :0: [epic];
        }
    }

    can collect with Epic entry {
        if here.eid in self.claimed {
            skip;
        }
        self.claimed[here.eid] = True;
        for dependency in [here ->:Depends:->][?:Epic] {
            visit :0: [dependency];
        }
        self.ordered.append(here.eid);
        print(here.eid);
    }
}

def new_plan() -> ExecutionPlan {
    plan = ExecutionPlan();
    plan.anchor = PlanRoot();
    return plan;
}

def add_epic(
    plan: ExecutionPlan,
    eid: str,
    title: str,
    phase: int = 0
) -> bool {
    if eid in plan.epics {
        return False;
    }
    epic = Epic(eid=eid, title=title, phase=phase);
    plan.epics[eid] = epic;
    plan.anchor +>:Depends:+> epic;
    return True;
}

def add_dependency(
    plan: ExecutionPlan,
    child_id: str,
    parent_id: str
) -> bool {
    if child_id not in plan.epics {
        return False;
    }
    if parent_id not in plan.epics {
        return False;
    }
    child = plan.epics[child_id];
    parent = plan.epics[parent_id];
    child +>:Depends:+> parent;
    return True;
}

def dependencies(plan: ExecutionPlan, eid: str) -> list[str] {
    result: list[str] = [];
    if eid not in plan.epics {
        return result;
    }
    for dependency in [plan.epics[eid] ->:Depends:->][?:Epic] {
        result.append(dependency.eid);
    }
    return sorted(result);
}

def execution_order(plan: ExecutionPlan) -> list[str] {
    w = plan.anchor spawn ExecutionOrder(claimed={});
    return w.ordered;
}

def phase_epics(plan: ExecutionPlan, phase: int) -> list[str] {
    selected: list[str] = [];
    for eid in execution_order(plan) {
        if plan.epics[eid].phase == phase {
            selected.append(eid);
        }
    }
    return selected;
}
