"""Chrainx/CS-Handbook#81: expose incomplete topological orders on cycles."""

node Workflow {
    has name: str;
}

node Task {
    has id: str;
}

node TopoStep {
    has kind: str;
    has task_id: str = "";
}

edge Includes {}
edge DependsOn {}

walker TopologicalSort {
    has claimed: dict[str, bool] = {};
    has active: dict[str, bool] = {};
    has blocked: dict[str, bool] = {};
    has steps: list[TopoStep] = [];
    has expected: int = 0;
    has visited_count: int = 0;
    has cycle_detected: bool = False;

    can collect with Workflow entry {
        print("topological sort");
        for task in [here ->:Includes:->][?:Task] {
            self.expected += 1;
            visit :0: [task];
        }
        if self.visited_count < self.expected {
            self.cycle_detected = True;
            marker = TopoStep(kind="cycle-detected");
            self.steps.append(marker);
        }
    }

    can collect_task with Task entry {
        print(here.id);
        if here.id in self.claimed {
            if self.active[here.id] {
                self.cycle_detected = True;
                self.blocked[here.id] = True;
            }
            skip;
        }

        self.claimed[here.id] = True;
        self.active[here.id] = True;
        self.blocked[here.id] = False;

        for dependency in [here ->:DependsOn:->][?:Task] {
            visit :0: [dependency];
            if self.blocked[dependency.id] {
                self.blocked[here.id] = True;
            }
        }

        self.active[here.id] = False;
        if not self.blocked[here.id] {
            step = TopoStep(kind="mark-visited", task_id=here.id);
            self.steps.append(step);
            self.visited_count += 1;
        }
    }
}

walker TaskFinder {
    has target: str;
    has claimed: dict[str, bool] = {};
    has found: Task | None = None;

    can find_root with Workflow entry {
        print("find task");
        for task in [here ->:Includes:->][?:Task] {
            visit :0: [task];
        }
    }

    can find_task with Task entry {
        print(here.id);
        if here.id in self.claimed {
            skip;
        }
        self.claimed[here.id] = True;
        if here.id == self.target {
            self.found = here;
            disengage;
        }
        for dependency in [here ->:DependsOn:->][?:Task] {
            visit :0: [dependency];
        }
    }
}

def topologicalSortSteps(graph: Workflow) -> list[TopoStep] {
    w = graph spawn TopologicalSort(claimed={});
    return w.steps;
}

def deriveTopoOrder(steps: list[TopoStep]) -> list[str] {
    order: list[str] = [];
    for step in steps {
        if step.kind == "mark-visited" {
            order.append(step.task_id);
        }
    }
    return order;
}

def hasStepKind(steps: list[TopoStep], wanted: str) -> bool {
    for step in steps {
        if step.kind == wanted {
            return True;
        }
    }
    return False;
}

def findTask(graph: Workflow, task_id: str) -> Task | None {
    w = graph spawn TaskFinder(target=task_id, claimed={});
    return w.found;
}
