test "diamond revisit remains complete" {
    graph = Workflow(name="diamond");
    a = Task(id="a");
    b = Task(id="b");
    c = Task(id="c");
    d = Task(id="d");
    graph +>:Includes:+> a;
    graph +>:Includes:+> b;
    graph +>:Includes:+> c;
    graph +>:Includes:+> d;
    a +>:DependsOn:+> c;
    a +>:DependsOn:+> b;
    c +>:DependsOn:+> d;
    b +>:DependsOn:+> d;
    steps = topologicalSortSteps(graph);
    order = deriveTopoOrder(steps);
