    graph = Workflow(name="cyclic");
    a = Task(id="a");
    b = Task(id="b");
    c = Task(id="c");
    graph +>:Includes:+> a;
    graph +>:Includes:+> b;
    graph +>:Includes:+> c;
    a +>:DependsOn:+> b;
    b +>:DependsOn:+> a;
    c +>:DependsOn:+> a;
    steps = topologicalSortSteps(graph);
    order = deriveTopoOrder(steps);
