    replay_id = source_id + "::replay::" + replay_key;
    replay = Job(
        record_id=replay_id,
        principal=principal,
        status="PENDING",
        request_digest=candidate_digest,
        replay_source_job_record_id=source_id,
        replay_root_job_record_id=root_id,
        replay_generation_count=generation
    );
    source +>:Derived:+> replay;
    store.jobs[replay_id] = replay;
    store.replay_keys[token] = replay_id;
    store.replay_payloads[token] = candidate_digest;

    result["job_id"] = replay_id;
    result["status"] = "PENDING";
    result["generation"] = str(generation);
    result["replayed"] = "false";
    result["http_status"] = "202";
    return result;
}

def descendants(store: ReplayStore, record_id: str) -> list[str] {
    found: list[str] = [];
    if record_id not in store.jobs { return found; }
    job = store.jobs[record_id];
    w = job spawn DescendantWalker(claimed={});
    return sorted(w.found);
}

def lineage(store: ReplayStore, record_id: str) -> list[str] {
    found: list[str] = [];
    if record_id not in store.jobs { return found; }
    job = store.jobs[record_id];
    w = job spawn LineageWalker(claimed={});
    w.found.reverse();
    return w.found;
}

def provenance(store: ReplayStore, record_id: str) -> list[str] {
    path = lineage(store, record_id);
    edges: list[str] = [];
    for i in range(0, len(path) - 1) {
        edges.append(
            "prov:wasDerivedFrom(" + path[i + 1] + "," + path[i] + ")"
        );
    }
    return edges;
}
