def build_metadata(
    predicate_ids: list[str],
    subproperty_pairs: list[list[str]],
    inverse_pairs: list[list[str]]
) -> PredicateIndex {
    index = PredicateIndex();

    for cid in predicate_ids {
        if cid not in index.by_id {
            p = Predicate(cid=cid);
            index.by_id[cid] = p;
        }
    }

    for pair in subproperty_pairs {
        if len(pair) >= 2 {
            if pair[0] in index.by_id && pair[1] in index.by_id {
                parent = index.by_id[pair[0]];
                child = index.by_id[pair[1]];
                parent +>:SubProperty:+> child;
            }
        }
    }

    for pair in inverse_pairs {
        if len(pair) >= 2 {
            if pair[0] in index.by_id && pair[1] in index.by_id {
                left = index.by_id[pair[0]];
                right = index.by_id[pair[1]];
                left +>:Inverse:+> right;
                right +>:Inverse:+> left;
            }
        }
    }
    return index;
}

def expand_predicate(index: PredicateIndex, predicate_id: str) -> list[str] {
    if predicate_id not in index.by_id {
        return [predicate_id];
    }

    source = index.by_id[predicate_id];
    w = source spawn DescendantWalker(claimed={});
    return sorted(w.found);
}

def canonical_predicate(index: PredicateIndex, predicate_id: str) -> str {
    if predicate_id not in index.by_id {
        return predicate_id;
    }

    source = index.by_id[predicate_id];
    w = source spawn InverseWalker(claimed={});
    return w.chosen;
}

def canonicalize_edges(
    index: PredicateIndex,
    assertions: list[Assertion]
) -> list[Assertion] {
    normalized: list[Assertion] = [];

    for assertion in assertions {
        normalized.append(Assertion(
            source=assertion.source,
            predicate=canonical_predicate(index, assertion.predicate),
            target=assertion.target
        ));
    }
    return normalized;
}
