    reachable = reachable_review(graph, start_key);
    orphaned: list[str] = [];
    for item in graph.surfaces {
        supported = item.production and item.scenario and item.focused_test;
        if item.active and (not (item.key in reachable) or not supported) {
            orphaned.append(item.key);
        }
    }
    return sorted(orphaned);
