    has path: str;
    has size_bytes: int = 0;
    has line_count: int = 0;
}
node Page {
    has path: str;
    has sources: list[str] = [];
}

edge HasRawRoot {}
edge HasPage {}
edge RawChild {}
edge PageLink {}

def resolve_resource(page_path: str, resource: str) -> str {
    parts: list[str] = [];
    absolute: bool = len(resource) > 0 and resource[0] == "/";
    if absolute {
        parts = resource.split("/");
    } else {
        page_parts: list[str] = page_path.split("/");
        for i in range(0, len(page_parts) - 1) {
            parts.append(page_parts[i]);
        }
        for part in resource.split("/") {
            parts.append(part);
        }
    }

    normalized: list[str] = [];
    for part in parts {
        if part == "" or part == "." {
            continue;
        }
        if part == ".." {
            if len(normalized) > 0 {
                normalized.pop();
            }
        } else {
            normalized.append(part);
        }
    }

    result: str = "";
    for i in range(0, len(normalized)) {
        if i > 0 {
            result += "/";
        }
        result += normalized[i];
    }
    return result;
}

walker CollectRefs {
    has target_bundle: str;
    has claimed: dict[str, bool] = {};
    has referenced: dict[str, bool] = {};

    can collect_bundle with Bundle entry {
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        if here.cid != self.target_bundle {
            skip;
        }
        print("collect bundle");
        for page in [here ->:HasPage:->][?:Page] {
            visit :0: [page];
        }
    }

    can collect_page with Page entry {
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        print("collect page");
        for resource in here.sources {
            resolved: str = resolve_resource(here.path, resource);
            self.referenced[resolved] = True;
        }
        for linked in [here ->:PageLink:->][?:Page] {
            visit :0: [linked];
        }
    }
}

walker ReportRaw {
    has target_bundle: str;
    has referenced: dict[str, bool] = {};
    has claimed: dict[str, bool] = {};
    has orphans: list[str] = [];

    can report_bundle with Bundle entry {
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        if here.cid != self.target_bundle {
            skip;
        }
        print("report bundle");
        for raw_root in [here ->:HasRawRoot:->][?:RawDir] {
            visit :0: [raw_root];
        }
    }

    can report_dir with RawDir entry {
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        print(f"scan raw {here.path}");
        for directory in [here ->:RawChild:->][?:RawDir] {
            visit :0: [directory];
        }
        for capture in [here ->:RawChild:->][?:Capture] {
            visit :0: [capture];
        }
    }

    can report_capture with Capture entry {
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        print(f"scan capture {here.path}");
        if here.path not in self.referenced {
            self.orphans.append(
                f"{here.path}|{here.size_bytes}|{here.line_count}"
            );
        }
    }
}

def lint(raw_root: RawDir, pages: list[Page]) -> list[str] {
    bundle = Bundle();
    root ++> bundle;
    bundle +>:HasRawRoot:+> raw_root;
    for page in pages {
        bundle +>:HasPage:+> page;
    }

    collector = root spawn CollectRefs(target_bundle=bundle.cid);
    reporter = root spawn ReportRaw(
        target_bundle=bundle.cid,
        referenced=collector.referenced
    );
    return sorted(reporter.orphans);
}
