# Growth-Circle/cadis#1006

node Agent {
    has agent_id: str;
    has parent_agent_id: str | None = None;
    has home: str | None = None;
    has sessions: int = 0;
    has workers: int = 0;
    has alive: bool = True;
}

node Grant {
    has grant_id: str;
    has agent_id: str;
    has workspace: str;
    has active: bool = True;
}

edge ParentLink {}
edge GrantLink {}

obj Runtime {
    has agents: dict[str, Agent] = {};
    has grants: dict[str, Grant] = {};
    has max_total_agents: int = 100;
    has max_children_per_parent: int = 8;
    has max_depth: int = 2;
    has grants_persisted: bool = True;
}

walker Cascade {
    has claimed: dict[str, bool] = {};
    has found: list[str] = [];

    can collect with Agent entry {
        if here.agent_id in self.claimed {
            skip;
        }
        self.claimed[here.agent_id] = True;
        self.found.append(here.agent_id);
        print("cascade " + here.agent_id);
        kids: list[Agent] = [];
        for child in [here ->:ParentLink:->][?:Agent] {
            if child.alive {
                kids.append(child);
            }
        }
        visit :0: [kids];
    }
}

def new_runtime() -> Runtime {
    state = Runtime();
    main_node = Agent(agent_id="main", home="/agents/main");
    state.agents["main"] = main_node;
    return state;
}

def agent_depth(state: Runtime, agent_id: str) -> int {
    current: Agent | None = state.agents.get(agent_id);
    if current == None {
        return -1;
    }
    seen: dict[str, bool] = {};
    depth = 0;
    while current != None {
        if current.agent_id in seen {
            return depth;
        }
        seen[current.agent_id] = True;
        parent_id: str | None = current.parent_agent_id;
        if parent_id == None {
            return depth;
        }
        depth += 1;
        current = state.agents.get(parent_id);
    }
    return depth;
}

def spawn_agent_record(
    state: Runtime, agent_id: str, parent_agent_id: str
) -> Agent | None {
    if state.agents.get(agent_id) != None {
        return None;
    }
    parent: Agent | None = state.agents.get(parent_agent_id);
    if parent == None or parent.alive == False {
        return None;
    }
    child_count = 0;
    for child in [parent ->:ParentLink:->][?:Agent] {
        if child.alive {
            child_count += 1;
        }
    }
    if len(state.agents) >= state.max_total_agents {
        return None;
    }
    if child_count >= state.max_children_per_parent {
        return None;
    }
    if agent_depth(state, parent_agent_id) + 1 > state.max_depth {
        return None;
    }
    child = Agent(
        agent_id=agent_id,
        parent_agent_id=parent_agent_id,
        home="/agents/" + agent_id
    );
    parent +>:ParentLink:+> child;
    state.agents[agent_id] = child;
    print("spawn " + agent_id);
    return child;
}

def grant_workspace(
    state: Runtime, agent_id: str, workspace: str
) -> Grant | None {
    agent: Agent | None = state.agents.get(agent_id);
    if agent == None or agent.alive == False {
        return None;
    }
    grant_id = agent_id + "::" + workspace;
    if state.grants.get(grant_id) != None {
        return None;
    }
    grant = Grant(
        grant_id=grant_id,
        agent_id=agent_id,
        workspace=workspace
    );
    agent +>:GrantLink:+> grant;
    state.grants[grant_id] = grant;
    return grant;
}

def kill_agent(state: Runtime, agent_id: str) -> list[str] {
    target: Agent | None = state.agents.get(agent_id);
    if target == None or agent_id == "main" {
        return [];
    }
    w = target spawn Cascade(claimed={});
    removed: list[str] = [];
    index = len(w.found) - 1;
    while index >= 0 {
        killed_id = w.found[index];
        victim: Agent | None = state.agents.get(killed_id);
        if victim != None {
            grant_ids: list[str] = [];
            for grant in [victim ->:GrantLink:->][?:Grant] {
                grant.active = False;
                grant_ids.append(grant.grant_id);
            }
            for grant_id in grant_ids {
                state.grants.pop(grant_id);
            }
            victim.sessions = 0;
            victim.workers = 0;
            victim.home = None;
            victim.alive = False;
            victim.parent_agent_id = None;
            state.agents.pop(killed_id);
            removed.append(killed_id);
            state.grants_persisted = True;
            print("agent.killed " + killed_id);
        }
        index -= 1;
    }
    return removed;
}

def live_agent_ids(state: Runtime) -> list[str] {
    ids: list[str] = [];
    for agent_id in state.agents {
        if state.agents[agent_id].alive {
            ids.append(agent_id);
        }
    }
    return sorted(ids);
}
