    has found: list[str] = [];

    can step with Artifact entry {
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        self.found.append(here.cid);
        print(here.cid);

        kids: list[Artifact] = [];
        for kid in [here ->:Relationship:->][?:Artifact] {
            kids.append(kid);
        }
        visit :0: [kids];
    }
}

def new_navigation_map() -> NavigationMap {
    return NavigationMap();
}

def add_artifact(
    graph: NavigationMap,
    cid: str,
    title: str,
    kind: str,
    scope: str = "source",
    trusted: bool = False
) -> bool {
    if cid in graph.nodes {
        return False;
    }
    item = Artifact(
        cid=cid,
        title=title,
        kind=kind,
        scope=scope,
        trusted=trusted
    );
    graph.nodes[cid] = item;
    return True;
}

def link_artifacts(
    graph: NavigationMap,
    source_id: str,
    target_id: str,
    relation: str
) -> bool {
    if source_id not in graph.nodes {
        return False;
    }
    if target_id not in graph.nodes {
        return False;
    }
    source = graph.nodes[source_id];
    target = graph.nodes[target_id];
    source +>:Relationship(label=relation):+> target;
    return True;
}

def blast_radius(graph: NavigationMap, start_id: str) -> list[str] {
    if start_id not in graph.nodes {
        return [];
    }
    start = graph.nodes[start_id];
    w = start spawn BlastWalker(claimed={});
    return sorted(w.found);
}

def diagnose_blast_radius(
    graph: NavigationMap,
    start_id: str,
    minimum: int = 4
) -> str {
    if start_id not in graph.nodes {
        return "redirect";
    }
    impacted: list[str] = blast_radius(graph, start_id);
    if len(impacted) >= minimum {
        return "confirmed";
    }
    return "redirect";
}

def trusted_candidates(
    graph: NavigationMap,
    scope: str
) -> list[str] {
    matches: list[str] = [];
    for cid in graph.nodes {
        item = graph.nodes[cid];
        if item.kind == "candidate" {
            if item.scope == scope and item.trusted {
                matches.append(item.cid);
            }
        }
    }
    return sorted(matches);
}
