  }
  return "-".join(words);
}

def parse_document(source: str) -> Document {
  document = Document(title="document");
  current: Section | None = None;
  for line in source.split("\n") {
    if line.startswith("# ") {
      title = line[2:];
      section = Section(slug=_slugify(title), title=title);
      document +>:Contains:+> section;
      current = section;
    else {
      if current != None {
        if current.body == "" {
          current.body = line;
        } else {
          current.body = current.body + "\n" + line;
        }
      }
    }
  }
  return document;
}

def collect_sections(document: Document) -> list[str] {
  handle = WalkHandle();
  w = document spawn SectionWalker(handle=handle);
  return handle.found;
}

def resolve_section(document: Document, slug: str) -> Section | None {
  handle = WalkHandle(wanted=slug);
  w = document spawn ResolveWalker(handle=handle);
  return handle.match;
}
