def link_downstream(env: Environment, upstream_code: str, downstream_code: str) -> None {
    upstream = ensure_wsg(env, upstream_code);
    downstream = ensure_wsg(env, downstream_code);
    upstream +>:Downstream:+> downstream;
}

def register_dam(
    env: Environment,
    group_code: str,
    dam_id: str,
    persisted: bool = False
) -> Dam {
    group = ensure_wsg(env, group_code);
    dam = Dam(dam_id=dam_id, persisted=persisted);
    env.dams[dam_id] = dam;
    group +>:HasDam:+> dam;
    return dam;
