def ExecuteGraphAsync(
    ctx: ContextScope,
    graph: ContextGraph
) -> list[str] {
    w = graph spawn DependencyWalker();
    completed: list[str] = [];

    if w.cycle {
        return completed;
    }

    for task in w.ordered {
        if ctx.cancelled {
            task.status = "cancelled";
            break;
        }

        task.status = "running";
        run = TaskRun(
            task_id=task.id,
            context_id=ctx.context_id,
            phase="completed"
        );
        ctx +>:ContextEvent:+> run;
        task +>:ExecutedIn:+> ctx;
        task.status = "completed";
        completed.append(task.id);
        graph.completed_count += 1;
        ctx.progress = len(completed);
        print("completed " + task.id);
    }
    return completed;
}
