}

walker FoldEvents {
    has seed: int = 0;
    has total: int = 0;
    has claimed: dict[str, bool] = {};
    has states: dict[str, int] = {};

    can fold with Event entry {
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        self.total = self.total + here.value;
        self.states[here.event_id] = self.total;
        print here.event_id;
        for kid in [here ->:Next:->][?:Event] {
            visit :0: [kid];
        }
    }
}

def make_feed() -> Feed {
    return Feed();
}

def add_event(feed: Feed, event_id: str, value: int) -> Event {
    event = Event(event_id=event_id, value=value);
    feed.events[event_id] = event;
    return event;
}

def connect_events(feed: Feed, from_id: str, to_id: str) -> bool {
    if from_id in feed.events and to_id in feed.events {
        source = feed.events[from_id];
        target = feed.events[to_id];
        source +>:Next:+> target;
        return True;
    }
    return False;
}

def fold_events(feed: Feed, start_id: str, seed: int = 0) -> int {
    if start_id in feed.events {
        start_node = feed.events[start_id];
        w = start_node spawn FoldEvents(seed=seed, total=seed);
        return w.total;
    }
    return seed;
}

def fold_states(feed: Feed, start_id: str, seed: int = 0) -> dict[str, int] {
    if start_id in feed.events {
        start_node = feed.events[start_id];
        w = start_node spawn FoldEvents(seed=seed, total=seed);
        return w.states;
    }
    states: dict[str, int] = {};
    return states;
}
