    if from_root == to_root {
        return result;
    }
    for card in cards {
        if card.workspace_source != source {
            if card.workspace_source == "explicit" {
                result["refused"] += 1;
            } else {
                result["skipped"] += 1;
            }
        } elif card.anchor_root != from_root or
              not path_under(card.workspace_path, from_root) {
            result["skipped"] += 1;
        } else {
            result["affected"] += 1;
            if card.state == "running" or card.state == "claimed" {
                result["refused"] += 1;
            } elif result["verified"] == 0 {
                result["refused"] += 1;
            } elif has_collision(cards, card, source, from_root, to_root) {
                result["refused"] += 1;
            } elif apply {
                card.workspace_path = target_path(card.workspace_path, from_root, to_root);
                card.anchor_root = to_root;
                card.audit_count += 1;
                card.last_event = "workspace-rebound";
                result["changed"] += 1;
            }
        }
    }
    return result;
