def create_store() -> Store {
    graph_root = GraphRoot();
    return Store(graph_root=graph_root);
}

def create_session(store: Store, session_id: str) -> Session {
    session = Session(id=session_id);
    store.graph_root +>:Contains:+> session;
    return session;
}

def create_payload(payload_id: str, text: str) -> Payload {
    return Payload(id=payload_id, text=text);
}

def append_record(
    session: Session,
    record_id: str,
    kind: str,
    payload: Payload
) -> Record {
    record = Record(
        id=record_id,
        session_id=session.id,
        payload_id=payload.id,
        kind=kind
    );
    session +>:Contains:+> record;
    record +>:Contains:+> payload;
    payload.ref_count = payload.ref_count + 1;
    return record;
}

def payload_ref_count(store: Store, payload_id: str) -> int {
    for session in [store.graph_root ->:Contains:->][?:Session] {
        for record in [session ->:Contains:->][?:Record] {
            for payload in [record ->:Contains:->][?:Payload] {
                if payload.id == payload_id {
                    return payload.ref_count;
                }
            }
        }
    }
    return 0;
}

def payload_file_exists(store: Store, payload_id: str) -> bool {
    for session in [store.graph_root ->:Contains:->][?:Session] {
        for record in [session ->:Contains:->][?:Record] {
            for payload in [record ->:Contains:->][?:Payload] {
                if payload.id == payload_id {
                    return payload.file_exists;
                }
            }
        }
    }
    return False;
}

def active_record_count(session: Session) -> int {
    count: int = 0;
    for record in [session ->:Contains:->][?:Record] {
        count = count + 1;
    }
    return count;
}

def delete_sessions(store: Store, session_ids: list[str]) -> int {
    targets: list[Session] = [];
    for session in [store.graph_root ->:Contains:->][?:Session] {
        if session.id in session_ids {
            targets.append(session);
        }
    }

    deleted: int = 0;
    for session in targets {
        w = session spawn CleanupWalker(claimed={});
        for record in w.records {
            for payload in [record ->:Contains:->][?:Payload] {
                payload.ref_count = payload.ref_count - 1;
            }
            del record;
        }
        for payload in w.payloads {
            if payload.ref_count == 0 {
                payload.file_exists = False;
                del payload;
            }
        }
        del session;
        deleted = deleted + 1;
    }
    return deleted;
}

def reopen_store(store: Store) -> Store {
    store.reopened = True;
    return store;
}
