    } elif changed and store.artifacts.get(pkg.package_id + ":" + without_pdf(source.path) + ".md") is not None {
        item.status = "stale_derivation";
        artifact = store.artifacts[pkg.package_id + ":" + without_pdf(source.path) + ".md"];
        artifact.status = "stale_derivation";
    } elif item.status != "stale_derivation" {
        item.status = "indexed";
    }

    if pkg.managed_writes and source.supported and source.extract_ok and source.media_type == "application/pdf" {
        create_derivation(store, pkg, source);
    }
    return item;
}

def index_package(store: Store, package_id: str) -> list[InventoryItem] {
    result: list[InventoryItem] = [];
    pkg = store.packages.get(package_id);
    if pkg is None { return result; }
    w = pkg spawn IndexWalker(claimed={});
    for source in w.sources { result.append(index_source(store, pkg, source)); }
    for key in store.inventory {
        if key.startswith(package_id + ":") { result.append(store.inventory[key]); }
    }
    return result;
}

def collect_source_paths(root_folder: Folder) -> list[str] {
    w = root_folder spawn PathWalker(claimed={});
    return w.paths;
}

def inventory_status(store: Store, package_id: str, path: str) -> str {
    item = store.inventory.get(package_id + ":" + path);
    if item is None { return "unknown"; }
    return item.status;
}

def inventory_source_sha(store: Store, package_id: str, path: str) -> str {
