def define_macro(book: MacroBook, name: str, previous: str) -> bool {
    if name in book.macros {
        return False;
    }
    macro = MacroDef(name=name, previous=previous);
    book.macros[name] = macro;
    if previous != "" {
        if previous in book.macros {
            prior = book.macros[previous];
            macro +>: Expands :+> prior;
        }
    }
    return True;
}

def link_macro(book: MacroBook, source: str, target: str) -> bool {
    if source not in book.macros {
        return False;
    }
    if target not in book.macros {
        return False;
    }
    left = book.macros[source];
    right = book.macros[target];
    left +>: Expands :+> right;
    return True;
}

def expand_names(book: MacroBook, name: str) -> list[str] {
    result: list[str] = [];
    if name not in book.macros {
        return result;
    }
    start = book.macros[name];
    w = start spawn ExpansionWalker(claimed={});
    result = sorted(w.names);
    return result;
}

def expansion_work(book: MacroBook, name: str) -> int {
    if name not in book.macros {
        return 0;
    }
    start = book.macros[name];
    w = start spawn ExpansionWalker(claimed={});
    return w.work;
}

def make_chain(depth: int) -> MacroBook {
    book = new_book();
    if depth <= 0 {
        return book;
    }
    define_macro(book, "Foo0", "");
    i = 1;
    while i < depth {
        current = f"Foo{i}";
        previous = f"Foo{i - 1}";
        define_macro(book, current, previous);
        i += 1;
    }
    return book;
}
