    version: str,
    engine: str,
    inputs: list[str],
    outputs: list[str],
    capabilities: list[str],
    sandboxed: bool,
    streaming: bool
) -> Block {
    block = Block(
        name=name,
        version=version,
        engine=engine,
        inputs=inputs,
        outputs=outputs,
        capabilities=capabilities,
        sandboxed=sandboxed,
        streaming=streaming
    );
    catalog.blocks.append(block);
    return block;
}

def wire_blocks(catalog: Catalog, block_name: str, dependency_name: str) -> bool {
    block: Block | None = None;
    dependency: Block | None = None;
    for candidate in catalog.blocks {
        if candidate.name == block_name {
            block = candidate;
        }
        if candidate.name == dependency_name {
            dependency = candidate;
        }
    }
    if block is None {
        return False;
    }
    if dependency is None {
        return False;
    }
    block +>:Depends:+> dependency;
    return True;
}

def resolve_dependencies(catalog: Catalog, block_name: str) -> list[str] {
    result: list[str] = [];
    root_node: Block | None = None;
    for candidate in catalog.blocks {
        if candidate.name == block_name {
            root_node = candidate;
        }
    }
    if root_node is None {
        return result;
    }
    w = root_node spawn DependencyWalk(claimed={});
    for name in w.found {
        result.append(name);
    }
    return result;
}

def schema_compatible(upstream: Block, downstream: Block) -> bool {
    for required in downstream.inputs {
        matched: bool = False;
        for produced in upstream.outputs {
            if required == produced {
                matched = True;
            }
        }
        if not matched {
            return False;
        }
    }
    return True;
}

def capabilities_available(block: Block, available: list[str]) -> bool {
    for required in block.capabilities {
        matched: bool = False;
        for provided in available {
            if required == provided {
                matched = True;
            }
        }
        if not matched {
            return False;
        }
    }
    return True;
}

def add_computed_column(
    catalog: Catalog,
    block_name: str,
    expression: str
) -> bool {
    for block in catalog.blocks {
        if block.name == block_name {
            block.computed_columns.append(expression);
            return True;
        }
    }
    return False;
}

def execution_mode(block: Block) -> str {
    if block.sandboxed {
        return "sandbox";
    }
    return "trusted";
}

def record_run(
    catalog: Catalog,
    block_name: str,
    rows: int,
    millis: int
) -> Run | None {
    for block in catalog.blocks {
        if block.name == block_name {
            run = Run(block_name=block_name, rows=rows, millis=millis);
            catalog.runs.append(run);
            return run;
        }
    }
    return None;
}
