    has claimed: dict[str, bool] = {};
    has found: list[str] = [];
    has visited: list[str] = [];
    has links: list[str] = [];
    has start_id: str = "";

    can step with DataAsset entry {
        if here.asset_id in self.claimed { skip; }
        self.claimed[here.asset_id] = True;
        self.visited.append(here.asset_id);
        if here.asset_id != self.start_id {
            self.found.append(here.asset_id);
        }
        for kid in [here ->:Flows:->][?:DataAsset] {
            self.links.append(here.asset_id + "->" + kid.asset_id);
            visit :0: [kid];
        }
        print(here.asset_id);
    }
}

def add_asset(
    store: LineageStore,
    asset_id: str,
    kind: str,
    owner: str,
    records: int = 0
) -> DataAsset {
    asset = DataAsset(
        asset_id=asset_id,
        kind=kind,
        owner=owner,
        records=records
    );
    store.assets[asset_id] = asset;
    return asset;
}

def link_assets(
    store: LineageStore,
    source_id: str,
    target_id: str
) -> bool {
    if source_id not in store.assets { return False; }
    if target_id not in store.assets { return False; }
    source = store.assets[source_id];
    target = store.assets[target_id];
    source +>:Flows:+> target;
    return True;
}

def register_issue(
    store: LineageStore,
    issue_id: str,
    source_id: str
) -> bool {
    if issue_id in store.issues { return False; }
    if source_id not in store.assets { return False; }
    store.issues[issue_id] = source_id;
    store.assets[source_id].contaminated = True;
    return True;
}

