def impact_report(
    store: LineageStore,
    issue_id: str
) -> dict[str, int] {
    impact: dict[str, int] = {};
    records = 0;
    systems = 0;
    dashboards = 0;
    for asset_id in downstream_consumers(store, issue_id) {
        asset = store.assets[asset_id];
        records += asset.records;
        if asset.kind == "system" { systems += 1; }
        if asset.kind == "dashboard" { dashboards += 1; }
