def build_call_graph(spec: dict[str, list[str]]) -> CallGraph {
    graph = CallGraph();
    for name in sorted(spec) {
        graph.functions[name] = Function(name=name);
    }
    for name in sorted(spec) {
        caller: Function = graph.functions[name];
        for target in spec[name] {
            if target in graph.functions {
                callee: Function = graph.functions[target];
                caller +>:Calls:+> callee;
                callee.incoming += 1;
            }
        }
    }
    return graph;
}

def find_entry_points(graph: CallGraph) -> list[str] {
    entries: list[str] = [];
    for name in sorted(graph.functions) {
        if graph.functions[name].incoming == 0 {
            entries.append(name);
        }
    }
    return entries;
}

def _reachable(graph: CallGraph, starts: list[str]) -> list[str] {
    names: list[str] = [];
    for start_name in starts {
        if start_name in graph.functions {
            w = graph.functions[start_name] spawn TraceWalk(claimed={});
            for name in w.found {
                if name not in names { names.append(name); }
            }
        }
    }
    return sorted(names);
}

def find_unused_functions(graph: CallGraph, starts: list[str]) -> list[str] {
    reachable: list[str] = _reachable(graph, starts);
    unused: list[str] = [];
    for name in sorted(graph.functions) {
        if name not in reachable { unused.append(name); }
    }
    return unused;
}

def calculate_call_depths(
    graph: CallGraph, starts: list[str]
) -> dict[str, int] {
    depths: dict[str, int] = {};
    for start_name in starts {
        if start_name in graph.functions {
            w = graph.functions[start_name] spawn TraceWalk(claimed={});
            w.pending[start_name] = 0;
            for name in w.depths {
                if name not in depths {
                    depths[name] = w.depths[name];
                } elif w.depths[name] < depths[name] {
                    depths[name] = w.depths[name];
                }
            }
        }
    }
    return depths;
}

def _has_path(graph: CallGraph, source: str, target: str) -> bool {
    if source not in graph.functions || target not in graph.functions {
        return False;
    }
    w = graph.functions[source] spawn TraceWalk(claimed={});
    return target in w.found;
}

def detect_cycles(graph: CallGraph) -> list[list[str]] {
    cycles: list[list[str]] = [];
    seen: dict[str, bool] = {};
    for caller_name in sorted(graph.functions) {
        caller: Function = graph.functions[caller_name];
        for kid in [caller ->:Calls:->][?:Function] {
            if _has_path(graph, kid.name, caller_name) {
                key: str = caller_name + "|" + kid.name;
                if key not in seen {
                    seen[key] = True;
                    pair: list[str] = [];
                    pair.append(caller_name);
                    pair.append(kid.name);
                    cycles.append(pair);
                }
            }
        }
    }
    return sorted(cycles);
}

def generate_call_chains(graph: CallGraph, start: str) -> list[list[str]] {
    if start not in graph.functions { return []; }
    w = graph.functions[start] spawn TraceWalk(claimed={});
    w.paths[start] = [start];
    return w.chains;
}

def visual_call_graph(graph: CallGraph) -> list[str] {
    lines: list[str] = [];
    for name in sorted(graph.functions) {
        caller: Function = graph.functions[name];
        has_outgoing: bool = False;
        for kid in [caller ->:Calls:->][?:Function] {
            has_outgoing = True;
            lines.append(name + " -> " + kid.name);
        }
        if has_outgoing == False { lines.append(name); }
    }
    return lines;
}
