    if max_quotes < 0 { max_quotes = 0; }
    if timeout_ms < 0 { timeout_ms = 0; }

    for quote in [plan ->:QuoteLink:->][?:Fare] {
        if inspected < max_quotes {
            inspected += 1;
            if elapsed + quote.latency_ms <= timeout_ms {
                elapsed += quote.latency_ms;
                if quote.available {
                    available += 1;
                    if fare_compatible(plan, quote) {
                        compatible.append(quote);
                    }
                }
            }
        }
    }

    plan.fare_alternatives = available;
    plan.fare_available = available > 0;
    if available == 0 {
        plan.fare_summary = "unavailable";
        return;
    }
    if len(compatible) == 0 {
        plan.fare_summary = "partial";
        return;
    }

    best: Fare = compatible[0];
    for quote in compatible {
        if quote.amount < best.amount { best = quote; }
    }
    plan.fare_summary = "computed";
    if best.certainty == "authoritative" {
        plan.fare_summary = "authoritative";
    }
    plan.fare_amount = best.amount;
    plan.fare_provider = best.provider;
    plan.fare_expiry = best.expiry;
    plan.fare_certainty = best.certainty;
}

def serialize_plan(plan: Plan, include_fares: bool = True) -> dict[str, str] {
    out: dict[str, str] = {"id": plan.pid, "route": plan.route};
    if include_fares {
        out["fare_summary"] = plan.fare_summary;
        out["fare_amount"] = str(plan.fare_amount);
        out["fare_provider"] = plan.fare_provider;
        out["fare_expiry"] = str(plan.fare_expiry);
        out["fare_alternatives"] = str(plan.fare_alternatives);
        out["fare_available"] = str(plan.fare_available);
        out["fare_certainty"] = plan.fare_certainty;
    }
    return out;
}

def quote_journey_plans(
    graph_root: Plan,
    requested_id: str = "",
    include_fares: bool = False,
    max_quotes: int = 2,
    timeout_ms: int = 100
) -> list[dict[str, str]] {
    w = graph_root spawn PlanCollector(claimed={});
    results: list[dict[str, str]] = [];
    for plan in w.found {
        if requested_id == "" or plan.pid == requested_id {
            if include_fares {
                apply_quotes(plan, max_quotes, timeout_ms);
            }
            results.append(serialize_plan(plan, include_fares));
        }
    }
    return results;
}
