                return "attached:" + turn.turn_stream_id;
            }
            return "turn_already_active";
        }
    }
    conn.turn_seq += 1;
    stream_id: str = conn.connection_id + "-turn-" + str(conn.turn_seq);
    turn: Turn = Turn(turn_stream_id=stream_id, request=payload);
    conn +>:Owns:+> turn;
    publish_codex_event(turn, "turn.start", payload, "");
    return stream_id;
}

def publish_codex_event(
    turn: Turn,
    kind: str,
    text: str,
    native_call_id: str = ""
) -> str {
    if turn.status != "active" {
        return "turn_not_active";
    }
    if turn.terminal_count > 0 {
        return "duplicate_terminal";
    }
    turn.event_seq += 1;
    event_id: str = turn.turn_stream_id + "-event-" + str(turn.event_seq);
    normalized_call: str = "";
    effect: bool = False;
    if kind == "tool.call" or kind == "tool.result" {
        if native_call_id == "" {
            normalized_call = "call-" + str(turn.event_seq);
        } else {
            normalized_call = "call-" + native_call_id;
        }
        if kind == "tool.result" {
            effect = True;
        }
    }
    event: Event = Event(
        event_id=event_id,
        kind=kind,
        text=text,
        call_id=normalized_call,
        effect=effect
    );
    turn +>:Emits:+> event;
    if kind == "turn.end" {
        turn.status = "ended";
        turn.terminal_count += 1;
    }
    if kind == "turn.error" {
        turn.status = "errored";
        turn.terminal_count += 1;
    }
    if kind == "turn.cancelled" {
        turn.status = "cancelled";
        turn.terminal_count += 1;
    }
    return event_id;
}

def cancel_turn(conn: Connection, stream_id: str = "") -> str {
    wk: ActiveTurnWalker = conn spawn ActiveTurnWalker(requested_id=stream_id);
    if len(wk.targets) == 0 {
        if stream_id != "" and wk.matched == False {
            return "unknown_turn";
        }
        return "no_active_turn";
    }
    publish_codex_event(wk.targets[0], "turn.cancelled", "cancelled", "");
    return "cancelled";
}

def pause(conn: Connection) -> bool {
    conn.paused = True;
    return conn.paused;
}

def resume(conn: Connection) -> bool {
    conn.paused = False;
    return conn.paused;
}

def snapshot(conn: Connection) -> list[str] {
    w: StreamWalker = conn spawn StreamWalker();
    return sorted(w.lines);
}

def turn_for(conn: Connection, stream_id: str) -> Turn | None {
    for turn in [conn ->:Owns:->][?:Turn] {
        if turn.turn_stream_id == stream_id {
            return turn;
        }
    }
    return None;
}

def event_for(turn: Turn, event_id: str) -> Event | None {
    for event in [turn ->:Emits:->][?:Event] {
        if event.event_id == event_id {
            return event;
        }
    }
    return None;
}
