def append_attempt(state: LaunchState, attempt_id: str, generation: str) -> ProofAttempt {
    if state.active_attempt is not None { state.active_attempt.active = False; }
    attempt = ProofAttempt(key=attempt_id, generation=generation);
    state.graph_root +>:Contains:+> attempt;
    state.active_attempt = attempt; state.phase = "proofing";
    return attempt;
}

def append_epoch(attempt: ProofAttempt, epoch_id: str, kind: str, complete: bool) -> Epoch {
    epoch = Epoch(key=epoch_id, kind=kind, generation=attempt.generation, complete=complete);
    attempt +>:Contains:+> epoch;
    return epoch;
}

def seal_proof(state: LaunchState, attempt: ProofAttempt) -> bool {
    w = attempt spawn ProofCheck(claimed={});
    if w.baseline_count == 2 and w.aggressive_count == 1 and w.incomplete == 0 {
        attempt.status = "sealed"; state.phase = "proof_sealed"; return True;
    }
    return False;
}

def assign_day_one(state: LaunchState, attempt: ProofAttempt, assignment_id: str, identity: str, arm: str) -> Assignment {
    selected = arm;
    if identity != state.frozen_identity { selected = "fallback"; }
    assignment = Assignment(key=assignment_id, attempt_id=attempt.key, identity=identity, selected_arm=selected);
    state.graph_root +>:Contains:+> assignment;
    attempt +>:Binds:+> assignment; state.phase = "assigned";
    return assignment;
}

def complete_work(assignment: Assignment, work_id: str, writer: str) -> Work {
    work = Work(key=work_id, writer=writer, completed=True);
    assignment +>:Uses:+> work;
    return work;
}

def open_exposure(state: LaunchState, assignment: Assignment, work: Work, receipt_id: str, exposure_id: str) -> Exposure {
    receipt = Receipt(key=receipt_id, attempt_id=assignment.attempt_id, assignment_id=assignment.key, work_id=work.key);
    exposure = Exposure(key=exposure_id, receipt_id=receipt.key, is_open=assignment.blind_baseline and work.completed);
    state.graph_root +>:Contains:+> receipt; state.graph_root +>:Contains:+> exposure;
    assignment +>:Records:+> receipt; work +>:Records:+> receipt;
    assignment +>:Opens:+> exposure; exposure +>:Binds:+> assignment; exposure +>:Binds:+> work;
    if exposure.is_open { state.phase = "exposed"; }
    return exposure;
}

def close_exposure(state: LaunchState, exposure: Exposure) -> bool {
    if exposure.is_open == False { return False; }
    exposure.is_open = False; state.freezer_ready = True; state.phase = "freezer_ready";
    return True;
}

def prepare_rollback(state: LaunchState, exposure: Exposure) -> bool {
    if exposure.is_open { return False; }
    state.phase = "rollback_prepared";
    return True;
}

def reachable_ids(state: LaunchState) -> list[str] {
    w = state.graph_root spawn Reachability(claimed={});
    return w.keys;
