def build_leak_mat() -> Mat {
    m = Mat(cid="m0", row_ids=["r0"]);
    root ++> m;
    r = Row(rid="r0", target_cid="m0");
    m +>:ToRow:+> r;
    r +>:ToMat:+> m;
    return m;
}

def build_acyclic_mat() -> Mat {
    m = Mat(cid="a0", row_ids=["ar0"]);
    root ++> m;
    r = Row(rid="ar0", target_cid="a1");
    m +>:ToRow:+> r;
    leaf = Mat(cid="a1", row_ids=[]);
    r +>:ToMat:+> leaf;
    return m;
}

def build_diamond_mat() -> Mat {
    top = Mat(cid="d_top", row_ids=["dr1", "dr2"]);
    root ++> top;
    lr = Row(rid="dr1", target_cid="d_mid");
    rr = Row(rid="dr2", target_cid="d_mid");
    top +>:ToRow:+> lr;
    top +>:ToRow:+> rr;
    mid = Mat(cid="d_mid", row_ids=["dr3"]);
    lr +>:ToMat:+> mid;
    rr +>:ToMat:+> mid;
    br = Row(rid="dr3", target_cid="d_top");
    mid +>:ToRow:+> br;
    br +>:ToMat:+> top;
    return top;
}

def build_orphan_row_mat() -> Mat {
    m = Mat(cid="u0", row_ids=["ur0"]);
    root ++> m;
    r = Row(rid="ur0", target_cid="missing");
    m +>:ToRow:+> r;
    return m;
}

def mat_show_expand(graph_root: Mat) -> list[str] {
    w = graph_root spawn ShowWalker(claimed={});
    out: list[str] = [];
    for cid in w.visited_order {
        out.append(cid);
    }
    return out;
}

def mat_show_leaks(graph_root: Mat) -> bool {
    w = graph_root spawn ShowWalker(claimed={});
    return w.saw_cycle;
}
