"""Omega recursive Equal refinement — ggreif/omega#48."""

node TypeVarN {
    has tid: str;
    has vname: str;
}

node ExcludeN {
    has xid: str;
}

node EqualN {
    has eid: str;
}

edge SubType {}

obj Fixture {
    has eq_node: EqualN;
    has eq_id: str = "";

    def wire() -> None {
        vb = TypeVarN(tid="v_b", vname="_b");
        vc = TypeVarN(tid="v_c", vname="_c");
        ex = ExcludeN(xid="x_bc");
        eq = EqualN(eid="eq48");
        root ++> vb;
        root ++> vc;
        root ++> ex;
        root ++> eq;
        ex +>:SubType:+> vb;
        ex +>:SubType:+> vc;
        eq +>:SubType:+> ex;
        eq +>:SubType:+> vc;
        vb +>:SubType:+> ex;
        self.eq_node = eq;
        self.eq_id = "eq48";
    }
}

def _fixture() -> Fixture {
    fx = Fixture();
    fx.wire();
    return fx;
}

def build_recursive_equal() -> str {
    fx = _fixture();
    return fx.eq_id;
}

def infer_equal_type(eq_id: str) -> str {
    if eq_id == "eq48" {
        return "Equal{Exclude{_b,_c}} _c";
    }
    return "";
}

def lookup_type(tid: str) -> str {
    if tid == "v_b" {
        return "_b";
    }
    if tid == "v_c" {
        return "_c";
    }
    if tid == "x_bc" {
        return "Exclude{_b,_c}";
    }
    if tid == "eq48" {
        return "Equal";
    }
    return "";
}

walker CollectWalker {
    has claimed: dict[str, bool] = {};
    has order: list[str] = [];
    has visit_rhs_first: bool = False;

    can step_var with TypeVarN entry {
        if here.tid in self.claimed { skip; }
        self.claimed[here.tid] = True;
        self.order.append(here.tid);
        print(["collect_var", here.tid, here.vname]);
    }

    can step_ex with ExcludeN entry {
        if here.xid in self.claimed { skip; }
        self.claimed[here.xid] = True;
        self.order.append(here.xid);
        kids: list[TypeVarN] = [];
        for ch in [here ->:SubType:->][?:TypeVarN] {
            kids.append(ch);
        }
        for ch in kids {
            visit :0: [ch];
        }
        print(["collect_ex", here.xid]);
    }

    can step_eq with EqualN entry {
        if here.eid in self.claimed { skip; }
        self.claimed[here.eid] = True;
        rhs: list[TypeVarN] = [];
        lhs: list[ExcludeN] = [];
        for ch in [here ->:SubType:->][?:TypeVarN] {
            rhs.append(ch);
        }
        for ch in [here ->:SubType:->][?:ExcludeN] {
            lhs.append(ch);
        }
        if self.visit_rhs_first {
            for ch in rhs {
                visit :0: [ch];
            }
            for ch in lhs {
                visit :0: [ch];
            }
        } else {
            for ch in lhs {
                visit :0: [ch];
            }
            for ch in rhs {
                visit :0: [ch];
            }
        }
        print(["collect_eq", here.eid, self.order]);
    }
}

walker BootWalker {
    has claimed: dict[str, bool] = {};

    can step_eq with EqualN entry {
        if here.eid in self.claimed { skip; }
        self.claimed[here.eid] = True;
        here spawn CollectWalker(claimed={}, visit_rhs_first=False);
        print(["boot_equal", here.eid]);
