def _refine_from_order(order: list[str]) -> bool {
    seen_ex: bool = False;
    has_c: bool = False;
    for pid in order {
        if pid == "x_bc" {
            seen_ex = True;
        } else {
            if pid == "v_c" {
                if seen_ex == False {
                    return False;
                }
                has_c = True;
            }
        }
    }
    if seen_ex == False {
        return False;
    }
    if has_c == False {
        return False;
    }
    return True;
}

def _collect_order(fx: Fixture, rhs_first: bool) -> list[str] {
    w = fx.eq_node spawn CollectWalker(claimed={}, visit_rhs_first=rhs_first);
    return w.order;
}

def refine_equal(eq_id: str) -> bool {
