"""Items.Ancestors parent-chain traversal — FreekingDean/gojellyfin#598."""

node GraphRoot {}

node Item {
    has cid: str;
    has name: str = "";
}

edge Parent {}

walker AncestorWalker {
    has claimed: dict[str, bool] = {};
    has result: list[str] = {};
    has origin_id: str = "";

    can climb with Item entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        print("ancestors visit ", here.cid);
        if here.cid != self.origin_id {
            self.result.append(here.cid);
        }
        parents: list[Item] = [here ->:Parent:->][?:Item];
        visit parents;
    }
}

walker AncestorDemoWalker {
    can boot with GraphRoot entry {
        print("ancestor demo boot");
        ep = Item(cid="episode", name="Ep1");
        sn = Item(cid="season", name="S1");
        sr = Item(cid="series", name="Show");
        here ++> ep;
        ep +>:Parent:+> sn;
        sn +>:Parent:+> sr;
        w = ep spawn AncestorWalker(origin_id="episode");
        print("demo ancestors ", len(w.result));
        disengage;
    }
}

obj ItemStore {
    has graph_root: GraphRoot;
    has items: dict[str, Item];

    def register(self, cid: str, name: str = "") -> Item {
        nd = Item(cid=cid, name=name);
        self.graph_root ++> nd;
        self.items[cid] = nd;
        return nd;
    }

    def set_parent(self, child_id: str, parent_id: str) -> None {
        ch = self.items[child_id] as Item;
        pa = self.items[parent_id] as Item;
        ch +>:Parent:+> pa;
    }

    def ancestors(self, item_id: str) -> list[str] {
        if item_id not in self.items {
            return [];
        }
        start = self.items[item_id] as Item;
        w = start spawn AncestorWalker(origin_id=item_id);
        return w.result;
    }
}

def new_item_store() -> ItemStore {
    gr = GraphRoot();
    mp: dict[str, Item] = {};
    return ItemStore(graph_root=gr, items=mp);
}

def register_item(store: ItemStore, cid: str, name: str = "") -> Item {
    return store.register(cid, name);
}

def link_parent(store: ItemStore, child_id: str, parent_id: str) -> None {
    store.set_parent(child_id, parent_id);
}

def ancestors(store: ItemStore, item_id: str) -> list[str] {
    return store.ancestors(item_id);
}

with entry {
    root spawn AncestorDemoWalker;
}
