```jac
# Recursive conditional type rewrite / union expansion model.
# Provenance: microsoft/TypeScript#63783

node Anchor {}

node SeqLeaf {
    has cid: str;
    has kind: str;
}

node SeqBranch {
    has cid: str;
}

edge SeqLink {}

obj Store {
    has anchor: Anchor;
    has seq: int = 1;

    def mint() -> str {
        cid = "n" + str(self.seq);
        self.seq += 1;
        return cid;
    }
}

def rewrite_kinds(kind: str) -> list[str] {
    ks: list[str] = [];
    if kind == "A" {
        ks = ["A", "B", "C", "D"];
    } elif kind == "B" {
        ks = ["B", "C", "D", "A"];
    } elif kind == "C" {
        ks = ["C", "D", "A", "B"];
    } else {
        ks = ["D", "A", "B", "C"];
    }
    return ks;
}

walker FindNode {
    has claimed: dict[str, bool] = {};
    has target: str;
    has found: object = None;

    can find_leaf with SeqLeaf entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        if here.cid == self.target {
            self.found = here;
            print("find_leaf " + here.cid);
            disengage;
        }
        disengage;
    }

    can find_branch with SeqBranch entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        if here.cid == self.target {
            self.found = here;
            print("find_branch " + here.cid);
            disengage;
        }
        kids: list = [here ->:SeqLink:->][?];
        visit :0: kids else { disengage; }
    }
}

walker RewriteWalk {
    has claimed: dict[str, bool] = {};
    has store: Store;
    has out_cid: str = "";

    can rw_leaf with SeqLeaf entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        kinds: list[str] = rewrite_kinds(here.kind);
        c1 = make_leaf(self.store, kinds[0]);
        c2 = make_leaf(self.store, kinds[1]);
        c3 = make_leaf(self.store, kinds[2]);
        c4 = make_leaf(self.store, kinds[3]);
        self.out_cid = make_branch(self.store, c1, c2, c3, c4);
        print("rw_leaf " + here.cid + "->" + self.out_cid);
        disengage;
    }

    can rw_branch with SeqBranch entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        kids: list = [here ->:SeqLink:->][?];
        newkids: list[str] = [];
        for kid in kids {
            rw = kid spawn RewriteWalk(claimed=self.claimed, store=self.store);
            newkids.append(rw.out_cid);
        }
        if len(newkids) >= 4 {
            self.out_cid = make_branch(
                self.store, newkids[0], newkids[1], newkids[2], newkids[3]
            );
        }
        print("rw_branch " + here.cid);
        disengage;
    }
}

walker UnionWalk {
    has claimed: dict[str, bool] = {};
    has parts: list[str] = [];

    can union_leaf with SeqLeaf entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        if here.kind == "A" {
            self.parts.append("s");
        } elif here.kind == "B" {
            self.parts.append("n");
        } elif here.kind == "C" {
            self.parts.append("ns");
        } else {
            self.parts.append("sn");
        }
        print("union_leaf " + here.kind);
        disengage;
    }

    can union_branch with SeqBranch entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        kids: list = [here ->:SeqLink:->][?];
        merged: list[str] = [];
        if len(kids) >= 4 {
            w1 = kids[0] spawn UnionWalk(claimed=self.claimed);
            w2 = kids[1] spawn UnionWalk(claimed=self.claimed);
            w3 = kids[2] spawn UnionWalk(claimed=self.claimed);
            w4 = kids[3] spawn UnionWalk(claimed=self.claimed);
            for a in w1.parts {
                for b in w3.parts {
                    merged.append(a + b);
                }
            }
            for a in w2.parts {
                for b in w4.parts {
                    merged.append(a + b);
                }
            }
        }
        self.parts = merged;
        print("union_branch " + str(len(merged));
        disengage;
    }
}

walker DemoProbe {
    has store: Store;
    has root_cid: str;

    can run with Anchor entry {
        u = seq_union(self.store, self.root_cid);
        print("demo_union " + str(len(u)));
        disengage;
    }
}

def new_store() -> Store {
    anchor_nd = Anchor();
    root ++> anchor_nd;
    return Store(anchor=anchor_nd);
}

def find_node(store: Store, cid: str) -> object {
    starts: list = [store.anchor ->][?];
    for start in starts {
        w = start spawn FindNode(claimed={}, target=cid);
        if w.found != None {
            return w.found;
        }
    }
    return None;
}

def make_leaf(store: Store, kind: str) -> str {
    cid = store.mint();
    nd = SeqLeaf(cid=cid, kind=kind);
    store.anchor ++> nd;
    return cid;
}

def make_branch(store: Store, c1: str, c2: str, c3: str, c4: str) -> str {
    cid = store.mint();
    br = SeqBranch(cid=cid);
    store.anchor ++> br;
    n1 = find_node(store, c1);
    n2 = find_node(store, c2);
    n3 = find_node(store, c3);
    n4 = find_node(store, c4);
    if n1 != None { br +>:SeqLink:+> n1; }
    if n2 != None { br +>:SeqLink:+> n2; }
    if n3 != None { br +>:SeqLink:+> n3; }
    if n4 != None { br +>:SeqLink:+> n4; }
    return cid;
}

def rewrite_once(store: Store, root_cid: str) -> str {
    nd = find_node(store, root_cid);
    if nd == None {
        return "";
    }
    w = nd spawn RewriteWalk(claimed={}, store=store);
    return w.out_cid;
}

def apply_rewrite(store: Store, root_cid: str, steps: int) -> str {
    if find_node(store, root_cid) == None {
        return "";
    }
    cur = root_cid;
    i = 0;
    while i < steps {
        cur = rewrite_once(store, cur);
        i += 1;
    }
    return cur;
}

def seq_union(store: Store, root_cid: str) -> list[str] {
    nd = find_node(store, root_cid);
    if nd == None {
        return [];
    }
    w = nd spawn UnionWalk(claimed={});
    return sorted(w.parts);
}

with entry {
    st = new_store();
    cid = make_leaf(st, "A");
    root spawn DemoProbe(store=st, root_cid=cid);
}
