"""typst/typst#8066 — recursive matrix show rule without base case causes OOM."""

node Mat {
    has cid: str;
    has leaf: bool = False;
    has value: str = "";
}

edge Row {}

walker ShowApplyWalker {
    has claimed: dict[str, bool] = {};
    has rows: list[str] = [];
    has visits: int = 0;

    can step with Mat entry {
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        self.visits = self.visits + 1;
        print("show", here.cid);
        if here.leaf {
            self.rows.append(here.value);
        } else {
            kids: list[Mat] = [here ->:Row:->][?:Mat];
            for kid in kids {
                visit :0: kid;
            }
        }
    }
}

walker CycleProbeWalker {
    has claimed: dict[str, bool] = {};
    has saw_revisit: bool = False;
    has visits: int = 0;

    can step with Mat entry {
        if here.cid in self.claimed {
            self.saw_revisit = True;
            skip;
        }
        self.claimed[here.cid] = True;
        self.visits = self.visits + 1;
        print("probe", here.cid);
        kids: list[Mat] = [here ->:Row:->][?:Mat];
        for kid in kids {
            visit :0: kid;
        }
    }
}

walker FindWalker {
    has target_cid: str = "";
    has found: Mat | None = None;
    has claimed: dict[str, bool] = {};

    can find_step with Mat entry {
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        print("find", here.cid);
        if here.cid == self.target_cid {
            self.found = here;
            disengage;
        }
        kids: list[Mat] = [here ->:Row:->][?:Mat];
        for kid in kids {
            visit :0: kid;
        }
    }
}

def find_mat(graph_root: Mat, cid: str) -> Mat | None {
    with entry {
        root spawn FindWalker();
    }
    w = graph_root spawn FindWalker(target_cid=cid);
    return w.found;
}

def apply_show_rule(graph_root: Mat) -> list[str] {
    with entry {
        root spawn ShowApplyWalker();
    }
    w = graph_root spawn ShowApplyWalker();
    out: list[str] = [];
    for r in w.rows {
        out.append(r);
    }
    return out;
}

def show_visit_count(graph_root: Mat) -> int {
    with entry {
        root spawn ShowApplyWalker();
    }
    w = graph_root spawn ShowApplyWalker();
    return w.visits;
}

def has_show_cycle(graph_root: Mat) -> bool {
    with entry {
        root spawn CycleProbeWalker();
    }
    w = graph_root spawn CycleProbeWalker();
    return w.saw_revisit;
}

def show_visit_count_for_cid(graph_root: Mat, cid: str) -> int {
    target = find_mat(graph_root, cid);
    if target == None {
        return 0;
    }
    return show_visit_count(target);
}
