```jac
"""FreekingDean/gojellyfin#598 — parent-chain ancestor resolution."""

glob graph_root: Root;

node Root {}

node Item {
    has iid: str;
    has name: str;
    has kind: str;
    has parent_ref: str | None = None;
}

edge Parent {}

node Library {
    has by_id: dict[str, Item] = {};
}

walker AncestorWalk {
    has claimed: dict[str, bool] = {};
    has chain: list[str] = {};
    has start_iid: str = "";
    has lib_ref: Library;

    can begin with Library entry {
        start_nd: Item | None = None;
        if self.start_iid in here.by_id {
            start_nd = here.by_id[self.start_iid];
        }
        if start_nd {
            visit start_nd;
        } else {
            disengage;
        }
    }

    can climb with Item entry {
        if here.iid in self.claimed {
            skip;
        }
        self.claimed[here.iid] = True;
        if here.iid != self.start_iid {
            self.chain.append(here.iid);
        }
        nxt: Item | None = None;
        if here.parent_ref {
            if here.parent_ref in self.lib_ref.by_id {
                nxt = self.lib_ref.by_id[here.parent_ref];
            }
        }
        if nxt {
            visit nxt;
        } else {
            disengage;
        }
    }
}

walker DemoRun {
    can kick with Root entry {
        root spawn DemoRun;
        print("gojellyfin#598 ancestors demo");
        lib = new_library();
        register_item(lib, "series1", None, "Show", "series");
        register_item(lib, "season1", "series1", "S1", "season");
        register_item(lib, "ep1", "season1", "E1", "episode");
        rows = ancestors(lib, "ep1");
        print(len(rows));
        disengage;
    }
}

def new_library() -> Library {
    lib = Library(by_id={});
    graph_root ++> lib;
    return lib;
}

def register_item(
    lib: Library,
    item_id: str,
    parent_id: str | None = None,
    name: str = "",
    kind: str = ""
) -> None {
    nd = Item(iid=item_id, name=name, kind=kind, parent_ref=parent_id);
    lib ++> nd;
    lib.by_id[item_id] = nd;
    if parent_id {
        if parent_id in lib.by_id {
            par = lib.by_id[parent_id];
            nd +>:Parent:+> par;
        }
    }
    for cid in lib.by_id {
        if cid == item_id {
            continue;
        }
        ch = lib.by_id[cid];
        if ch.parent_ref == item_id {
            ch +>:Parent:+> nd;
        }
    }
}

def get_item(lib: Library, item_id: str) -> dict | None {
    if item_id not in lib.by_id {
        return None;
    }
    nd = lib.by_id[item_id];
    return {
        "id": nd.iid,
        "parent_id": nd.parent_ref,
        "name": nd.name,
        "kind": nd.kind
    };
}

def ancestors(lib: Library, item_id: str) -> list[dict] {
    w = lib spawn AncestorWalk(start_iid=item_id, lib_ref=lib, claimed={}, chain=[]);
    print("ancestors walk done", len(w.chain));
    out: list[dict] = [];
    for iid in w.chain {
        row = get_item(lib, iid);
        if row {
            out.append(row);
        }
    }
    return out;
}
