"""ggreif/omega#48 — recursive Equal refinement (OSP lift)."""

node T {
    has cid: str;
    has kind: str;
    has label: str = "";
}

edge Child {}

def _get(cid: str) -> T | None {
    for nd in [root -->][?:T] {
        if nd.cid == cid {
            return nd;
        }
    }
    return None;
}

def var(name: str) -> str {
    nd = T(cid=name, kind="var", label=name);
    root ++> nd;
    return name;
}

def exclude(member_names: list[str] | None = None) -> str {
    ms: list[str] = [];
    if member_names != None {
        for m in member_names {
            ms.append(m);
        }
    }
    parts: list[str] = sorted(ms);
    eid: str = "excl:" + ":".join(parts);
    nd = T(cid=eid, kind="exclude", label=eid);
    root ++> nd;
    for nm in ms {
        ch = _get(nm);
        if ch != None {
            nd +>:Child:+> ch;
        }
    }
    return eid;
}

def equal(lhs: str, rhs: str) -> str {
    eid: str = "eq:" + lhs + "~" + rhs;
    nd = T(cid=eid, kind="equal", label=eid);
    root ++> nd;
    lft = _get(lhs);
    rgt = _get(rhs);
    if lft != None {
        nd +>:Child:+> lft;
    }
    if rgt != None {
        nd +>:Child:+> rgt;
    }
    return eid;
}

walker Refine {
    has claimed: dict[str, bool] = {};
    has pat_id: str;
    has exp_id: str;
    has result: bool = True;

    can refine_t with T entry {
        pair: str = self.pat_id + "#" + self.exp_id;
        if pair in self.claimed {
            skip;
        }
        self.claimed[pair] = True;
        pn = _get(self.pat_id);
        en = _get(self.exp_id);
        if pn == None {
            self.result = False;
            print("missing_pat");
            disengage;
        }
        if en == None {
            self.result = False;
            print("missing_exp");
            disengage;
        }
        if pn.kind != en.kind {
            self.result = False;
            print("kind_mismatch");
            disengage;
        }
        if pn.kind == "var" {
            if pn.label != en.label {
                self.result = False;
                print("var_mismatch");
            }
            disengage;
        }
        if pn.kind == "exclude" {
            pl: list[str] = [];
            el: list[str] = [];
            for c in [pn ->:Child:->][?:T] {
                pl.append(c.label);
            }
            for c in [en ->:Child:->][?:T] {
                el.append(c.label);
            }
            if sorted(pl) != sorted(el) {
                self.result = False;
                print("exclude_mismatch");
            }
            disengage;
        }
        pk: list[T] = [pn ->:Child:->][?:T];
        ek: list[T] = [en ->:Child:->][?:T];
        if len(pk) != 2 or len(ek) != 2 {
            self.result = False;
            print("arity");
            disengage;
        }
        self.pat_id = pk[1].cid;
        self.exp_id = ek[1].cid;
        visit :0: [pk[1]] else {
            disengage;
        };
        if not self.result {
            disengage;
        }
        self.pat_id = pk[0].cid;
        self.exp_id = ek[0].cid;
        visit :0: [pk[0]] else {
            disengage;
        };
        print("refined");
        disengage;
    }
}

def refines(pat: str, exp: str) -> bool {
    pn = _get(pat);
    if pn == None {
        print("unknown");
        return False;
    }
    w = pn spawn Refine(pat_id=pat, exp_id=exp, claimed={}, result=True);
    print(w.result);
    return w.result;
}

def refines_first(candidates: list[str] | None, exp: str) -> bool {
    cs: list[str] = [];
    if candidates != None {
        for c in candidates {
            cs.append(c);
        }
    }
    for pid in cs {
        if refines(pid, exp) {
            return True;
        }
    }
    return False;
}

walker Demo {
    can run entry {
        var("_b");
        var("_c");
        ex = exclude(["_b", "_c"]);
        eq = equal(ex, "_c");
        nd = _get(eq);
        if nd != None {
            w = nd spawn Refine(pat_id=eq, exp_id=eq, claimed={}, result=True);
            print(w.result);
        }
    }
}

with entry {
    root spawn Demo;
}
