```jac
"""microsoft/TypeScript#63783 — bounded recursive sequence rewrite."""

node Leaf {
    has kind: str;
    has cid: str;
}

node Branch {
    has cid: str;
}

node Registry {
    has seq: int = 0;
    def bump(self) -> int {
        self.seq += 1;
        return self.seq;
    }
}

edge L1 {}
edge L2 {}
edge R1 {}
edge R2 {}
edge IndexLink {}
edge RegLink {}

def ensure_registry() -> Registry {
    regs: list[Registry] = [root ->:RegLink:->][?:Registry];
    if len(regs) > 0 {
        return regs[0];
    }
    reg = Registry();
    root ++>:RegLink:+> reg;
    return reg;
}

def leaf_kind_props(kind: str) -> list[str] {
    props: list[str] = [];
    if kind == "A" {
        props = ["s1", "s2", "s3"];
    } elif kind == "B" {
        props = ["n1", "n2", "n3"];
    } elif kind == "C" {
        for n in ["n1", "n2", "n3"] {
            for s in ["s1", "s2", "s3"] {
                props.append(n + s);
            }
        }
    } elif kind == "D" {
        for s in ["s1", "s2", "s3"] {
            for n in ["n1", "n2", "n3"] {
                props.append(s + n);
            }
        }
    }
    return sorted(props);
}

def rewrite_leaf_quads(kind: str) -> list[str] {
    quads: list[str] = [];
    if kind == "A" {
        quads = ["A", "B", "C", "D"];
    } elif kind == "B" {
        quads = ["B", "C", "D", "A"];
    } elif kind == "C" {
        quads = ["C", "D", "A", "B"];
    } elif kind == "D" {
        quads = ["D", "A", "B", "C"];
    }
    return quads;
}

def find_by_cid(cid: str) -> Leaf | Branch | None {
    hits: list[Leaf | Branch] = [];
    for nd in [root ->:IndexLink:->][?:Leaf | Branch] {
        if nd.cid == cid {
            hits.append(nd);
        }
    }
    if len(hits) > 0 {
        return hits[0];
    }
    return None;
}

def make_leaf(kind: str) -> str {
    reg = ensure_registry();
    cid = kind + "_" + str(reg.bump());
    nd = Leaf(kind=kind, cid=cid);
    root ++> nd;
    root ++>:IndexLink:+> nd;
    return cid;
}

def make_branch(l1: str, l2: str, r1: str, r2: str) -> str {
    reg = ensure_registry();
    cid = "Branch_" + str(reg.bump());
    b = Branch(cid=cid);
    root ++> b;
    root ++>:IndexLink:+> b;
    n1 = find_by_cid(l1);
    n2 = find_by_cid(l2);
    n3 = find_by_cid(r1);
    n4 = find_by_cid(r2);
    if n1 is not None and n2 is not None and n3 is not None and n4 is not None {
        b +>:L1:+> n1;
        b +>:L2:+> n2;
        b +>:R1:+> n3;
        b +>:R2:+> n4;
    }
    return cid;
}

def child_cid(b: Branch, slot: str) -> str {
    chs: list[Leaf | Branch] = [];
    if slot == "L1" {
        chs = [b ->:L1:->][?:Leaf | Branch];
    } elif slot == "L2" {
        chs = [b ->:L2:->][?:Leaf | Branch];
    } elif slot == "R1" {
        chs = [b ->:R1:->][?:Leaf | Branch];
    } elif slot == "R2" {
        chs = [b ->:R2:->][?:Leaf | Branch];
    }
    if len(chs) > 0 {
        return chs[0].cid;
    }
    return "";
}

def rewrite_once(cid: str) -> str {
    nd = find_by_cid(cid);
    if nd is None {
        return cid;
    }
    if nd is Leaf {
        quads = rewrite_leaf_quads(nd.kind);
        c1 = make_leaf(quads[0]);
        c2 = make_leaf(quads[1]);
        c3 = make_leaf(quads[2]);
        c4 = make_leaf(quads[3]);
        return make_branch(c1, c2, c3, c4);
    }
    bnd = nd as Branch;
    return make_branch(
        rewrite_once(child_cid(bnd, "L1")),
        rewrite_once(child_cid(bnd, "L2")),
        rewrite_once(child_cid(bnd, "R1")),
        rewrite_once(child_cid(bnd, "R2"))
    );
}

def apply_rewrite(cid: str, n: int) -> str {
    cur = cid;
    i = 0;
    while i < n {
        cur = rewrite_once(cur);
        i += 1;
    }
    return cur;
}

def seq_union_collect(nd: Leaf | Branch, claimed: dict[str, bool]) -> list[str] {
    if nd.cid in claimed {
        return [];
    }
    claimed[nd.cid] = True;
    if nd is Leaf {
        return leaf_kind_props(nd.kind);
    }
    b = nd as Branch;
    l1s: list[Leaf | Branch] = [b ->:L1:->][?:Leaf | Branch];
    l2s: list[Leaf | Branch] = [b ->:L2:->][?:Leaf | Branch];
    r1s: list[Leaf | Branch] = [b ->:R1:->][?:Leaf | Branch];
    r2s: list[Leaf | Branch] = [b ->:R2:->][?:Leaf | Branch];
    out: list[str] = [];
    for l1 in l1s {
        for r1 in r1s {
            left = seq_union_collect(l1, claimed);
            right = seq_union_collect(r1, claimed);
            for a in left {
                for c in right {
                    out.append(a + c);
                }
            }
        }
    }
    for l2 in l2s {
        for r2 in r2s {
            left = seq_union_collect(l2, claimed);
            right = seq_union_collect(r2, claimed);
            for a in left {
                for c in right {
                    out.append(a + c);
                }
            }
        }
    }
    return sorted(out);
}

def seq_union(cid: str) -> list[str] {
    nd = find_by_cid(cid);
    if nd is None {
        return [];
    }
    claimed: dict[str, bool] = {};
    return seq_union_collect(nd, claimed);
}

def node_count_collect(nd: Leaf | Branch, claimed: dict[str, bool]) -> int {
    if nd.cid in claimed {
        return 0;
    }
    claimed[nd.cid] = True;
    total = 1;
    if nd is Branch {
        b = nd as Branch;
        for ch in [b ->:L1:->][?:Leaf | Branch] {
            total += node_count_collect(ch, claimed);
        }
        for ch in [b ->:L2:->][?:Leaf | Branch] {
            total += node_count_collect(ch, claimed);
        }
        for ch in [b ->:R1:->][?:Leaf | Branch] {
            total += node_count_collect(ch, claimed);
        }
        for ch in [b ->:R2:->][?:Leaf | Branch] {
            total += node_count_collect(ch, claimed);
        }
    }
    return total;
}

def node_count(cid: str) -> int {
    nd = find_by_cid(cid);
    if nd is None {
        return 0;
    }
    claimed: dict[str, bool] = {};
    return node_count_collect(nd, claimed);
}

walker SummarizeWalker {
    has start_cid: str;
    can start {
        u = seq_union(self.start_cid);
        print("union_len=" + str(len(u)));
        disengage;
    }
}

with entry {
    reg = ensure_registry();
    cid = make_leaf("A");
    root spawn SummarizeWalker(start_cid=cid);
}
