```jac
"""ggreif/omega#48 — refinement failure with recursive Equal."""

node Term {
    has cid: str;
    has kind: str;
    has label: str = "";
}

edge Child {}
edge Lhs {}
edge Rhs {}
edge Excl {}

obj Store {
    has graph_root: Term;
}

walker FindTerm {
    has claimed: dict[str, bool] = {};
    has want: str = "";
    has found: Term | None = None;

    can step with Term entry {
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        if here.cid == self.want {
            self.found = here;
            disengage;
        }
        for ch in [here ->:Child:->][?:Term] {
            visit :0: [ch];
        }
        disengage;
    }
}

walker RefineProbe {
    has claimed: dict[str, bool] = {};
    has term_cid: str = "";
    has pat_cid: str = "";
    has ok: bool = False;

    can step with Term entry {
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        if here.cid == self.term_cid {
            for ch in [here ->:Child:->][?:Term] {
                if ch.cid == self.pat_cid {
                    self.ok = True;
                }
            }
        }
        for ch in [here ->:Child:->][?:Term] {
            visit :0: [ch];
        }
        disengage;
    }
}

def lookup_term(graph_root: Term, cid: str) -> Term | None {
    w = graph_root spawn FindTerm(want=cid);
    print("lookup", cid, w.found);
    return w.found;
}

def child_lhs(n: Term) -> Term | None {
    xs: list[Term] = [n ->:Lhs:->][?:Term];
    if len(xs) > 0 {
        return xs[0];
    }
    return None;
}

def child_rhs(n: Term) -> Term | None {
    xs: list[Term] = [n ->:Rhs:->][?:Term];
    if len(xs) > 0 {
        return xs[0];
    }
    return None;
}

def exclude_has(excl: Term, name: str) -> bool {
    for ch in [excl ->:Excl:->][?:Term] {
        if ch.label == name {
            return True;
        }
    }
    return False;
}

def refine_pair(term_node: Term, pat_node: Term, subs: dict[str, str]) -> bool {
    if pat_node.kind == "var" {
        vn = pat_node.label;
        if vn in subs {
            return subs[vn] == term_node.cid;
        }
        subs[vn] = term_node.cid;
        return True;
    }
    if term_node.kind == "var" and pat_node.kind == "equal" {
        pl = child_lhs(pat_node);
        pr = child_rhs(pat_node);
        if pl is not None and pr is not None {
            if pr.kind == "var" and pr.label == term_node.label {
                if pl.kind == "exclude" and exclude_has(pl, term_node.label) {
                    subs[term_node.cid] = pat_node.cid;
                    return True;
                }
            }
        }
    }
    if term_node.kind == "equal" and pat_node.kind == "equal" {
        tl = child_lhs(term_node);
        tr = child_rhs(term_node);
        pl = child_lhs(pat_node);
        pr = child_rhs(pat_node);
        if tl is None or tr is None or pl is None or pr is None {
            return False;
        }
        if not refine_pair(tl, pl, subs) {
            return False;
        }
        return refine_pair(tr, pr, subs);
    }
    return term_node.cid == pat_node.cid;
}

def create_store() -> Store {
    rt = Term(cid="__root__", kind="root");
    return Store(graph_root=rt);
}

def add_var(store: Store, name: str) -> str {
    nd = Term(cid=name, kind="var", label=name);
    store.graph_root +>:Child:+> nd;
    return name;
}

def add_equal(store: Store, left: str, right: str) -> str {
    cid = "eq_" + left + "_" + right;
    nd = Term(cid=cid, kind="equal");
    store.graph_root +>:Child:+> nd;
    lnd = lookup_term(store.graph_root, left);
    rnd = lookup_term(store.graph_root, right);
    if lnd is not None and rnd is not None {
        nd +>:Lhs:+> lnd;
        nd +>:Rhs:+> rnd;
    }
    return cid;
}

def add_exclude(store: Store, base: str, excluded: list[str]) -> str {
    cid = "ex_" + base;
    i = 0;
    while i < len(excluded) {
        cid = cid + "_" + excluded[i];
        i += 1;
    }
    nd = Term(cid=cid, kind="exclude");
    store.graph_root +>:Child:+> nd;
    bnd = lookup_term(store.graph_root, base);
    if bnd is not None {
        nd +>:Lhs:+> bnd;
    }
    j = 0;
    while j < len(excluded) {
        vnd = lookup_term(store.graph_root, excluded[j]);
        if vnd is not None {
            nd +>:Excl:+> vnd;
        }
        j += 1;
    }
    return cid;
}

def term_kind(store: Store, tid: str) -> str {
    nd = lookup_term(store.graph_root, tid);
    if nd is None {
        return "";
    }
    return nd.kind;
}

def refine(store: Store, tid: str, pid: str) -> dict[str, str] | None {
    tn = lookup_term(store.graph_root, tid);
    pn = lookup_term(store.graph_root, pid);
    if tn is None or pn is None {
        return None;
    }
    subs: dict[str, str] = {};
    if not refine_pair(tn, pn, subs) {
        print("refine fail", tid, pid);
        return None;
    }
    print("refine ok", tid, pid, subs);
    return subs;
}

def graph_has(store: Store, term_cid: str, pat_cid: str) -> bool {
    w = store.graph_root spawn RefineProbe(term_cid=term_cid, pat_cid=pat_cid);
    print("graph_has", term_cid, pat_cid, w.ok);
    return w.ok;
}

with entry {
    s = create_store();
    b = add_var(s, "_b");
    c = add_var(s, "_c");
    ex = add_exclude(s, b, ["_b", "_c"]);
    pat = add_equal(s, ex, c);
    root spawn FindTerm(want=pat);
    print("omega48 demo", refine(s, c, pat));
}
