    ks: list[str] = branch_kinds(kind);
    br = SeqNode(cid=new_cid(), kind="Branch");
    root ++> br;
    leaves: list[SeqNode] = [];
    for k in ks {
        nd = SeqNode(cid=new_cid(), kind=k);
        root ++> nd;
        leaves.append(nd);
    }
    br +>:L1:+> leaves[0];
    br +>:L2:+> leaves[1];
    br +>:R1:+> leaves[2];
    br +>:R2:+> leaves[3];
    return br.cid;
}

def link_branch(c1: str, c2: str, c3: str, c4: str) -> str {
    br = SeqNode(cid=new_cid(), kind="Branch");
    root ++> br;
    n1 = find_seq(c1);
    n2 = find_seq(c2);
    n3 = find_seq(c3);
    n4 = find_seq(c4);
    if n1 is not None { br +>:L1:+> n1; }
    if n2 is not None { br +>:L2:+> n2; }
    if n3 is not None { br +>:R1:+> n3; }
    if n4 is not None { br +>:R2:+> n4; }
    return br.cid;
}

def make_leaf(kind: str) -> str {
    nd = SeqNode(cid=new_cid(), kind=kind);
    root ++> nd;
    return nd.cid;
}

def rewrite_once(seq_cid: str) -> str {
    src = find_seq(seq_cid);
    if src is None { return seq_cid; }
    w = src spawn BuildRewrite(claimed={}, focus=seq_cid);
    if w.result_cid == "" { return seq_cid; }
    return w.result_cid;
}

def apply_rewrite(seq_cid: str, steps: int) -> str {
    src = find_seq(seq_cid);
    if src is None { return seq_cid; }
    cur: str = seq_cid;
    i: int = 0;
    while i < steps {
        cur = rewrite_once(cur);
        i += 1;
    }
    return cur;
}

def seq_union(seq_cid: str) -> list[str] {
    src = find_seq(seq_cid);
    if src is None { return []; }
    w = src spawn UnionCollect(claimed={});
    if seq_cid not in w.unions { return []; }
    return sorted(w.unions[seq_cid]);
}
