            if len(r1s) > 0 { c3 = self.slot[r1s[0].cid]; }
            if len(r2s) > 0 { c4 = self.slot[r2s[0].cid]; }
            new_cid = link_branch(c1, c2, c3, c4);
            self.slot[here.cid] = new_cid;
            if here.cid == self.focus { self.result_cid = new_cid; }
        } else {
            new_cid = expand_leaf(here.kind);
            self.slot[here.cid] = new_cid;
            if here.cid == self.focus { self.result_cid = new_cid; }
        }
    }
}

walker UnionCollect {
    has claimed: dict[str, bool] = {};
    has unions: dict[str, list[str]] = {};

    can collect with SeqNode entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        print("union", here.cid);
        if here.kind == "Branch" {
            l1s: list[SeqNode] = [here ->:L1:->][?:SeqNode];
            l2s: list[SeqNode] = [here ->:L2:->][?:SeqNode];
            r1s: list[SeqNode] = [here ->:R1:->][?:SeqNode];
            r2s: list[SeqNode] = [here ->:R2:->][?:SeqNode];
            kids: list[SeqNode] = gather_four(here);
            if len(kids) > 0 {
                visit :0: kids;
            } else {
                disengage;
            }
            out: list[str] = [];
            append_pairs(out, l1s, r1s, self.unions);
            append_pairs(out, l2s, r2s, self.unions);
            self.unions[here.cid] = out;
        } else {
            self.unions[here.cid] = leaf_union(here.kind);
        }
    }
}

