def new_cid -> str {
    return "n" + str(len([-->:SeqNode][::root]));
}

def find_seq(target_cid: str) -> SeqNode | None {
    found: SeqNode | None = None;
    for nd in [-->:SeqNode][::root] {
        if found is None and nd.cid == target_cid {
            found = nd;
        }
    }
    return found;
}

def branch_kinds(kind: str) -> list[str] {
    if kind == "A" { return ["A", "B", "C", "D"]; }
    if kind == "B" { return ["B", "C", "D", "A"]; }
    if kind == "C" { return ["C", "D", "A", "B"]; }
    if kind == "D" { return ["D", "A", "B", "C"]; }
    return ["A", "B", "C", "D"];
}

def leaf_union(kind: str) -> list[str] {
    if kind == "A" { return ["s"]; }
    if kind == "B" { return ["n"]; }
    if kind == "C" { return ["ns"]; }
    if kind == "D" { return ["sn"]; }
    return [];
}

def gather_four(here: SeqNode) -> list[SeqNode] {
    kids: list[SeqNode] = [];
    for ch in [here ->:L1:->][?:SeqNode] { kids.append(ch); }
    for ch in [here ->:L2:->][?:SeqNode] { kids.append(ch); }
    for ch in [here ->:R1:->][?:SeqNode] { kids.append(ch); }
    for ch in [here ->:R2:->][?:SeqNode] { kids.append(ch); }
    return kids;
}

def append_pairs(
    out: list[str],
    lefts: list[SeqNode],
    rights: list[SeqNode],
    unions: dict[str, list[str]]
) {
    for a_nd in lefts {
        for b_nd in rights {
            au: list[str] = unions[a_nd.cid];
            bu: list[str] = unions[b_nd.cid];
            for a in au {
                for b in bu {
                    out.append(a + b);
                }
            }
        }
    }
}

def expand_leaf(kind: str) -> str {
    ks: list[str] = branch_kinds(kind);
    br = SeqNode(cid=new_cid(), kind="Branch");
    root ++> br;
    leaves: list[SeqNode] = [];
    for k in ks {
        nd = SeqNode(cid=new_cid(), kind=k);
        root ++> nd;
        leaves.append(nd);
    }
    br +>:L1:+> leaves[0];
    br +>:L2:+> leaves[1];
    br +>:R1:+> leaves[2];
    br +>:R2:+> leaves[3];
    return br.cid;
}

def link_branch(c1: str, c2: str, c3: str, c4: str) -> str {
    br = SeqNode(cid=new_cid(), kind="Branch");
    root ++> br;
    n1 = find_seq(c1);
    n2 = find_seq(c2);
    n3 = find_seq(c3);
    n4 = find_seq(c4);
    if n1 is not None { br +>:L1:+> n1; }
    if n2 is not None { br +>:L2:+> n2; }
    if n3 is not None { br +>:R1:+> n3; }
    if n4 is not None { br +>:R2:+> n4; }
    return br.cid;
}

def make_leaf(kind: str) -> str {
    nd = SeqNode(cid=new_cid(), kind=kind);
    root ++> nd;
    return nd.cid;
}

def rewrite_once(seq_cid: str) -> str {
    src = find_seq(seq_cid);
    if src is None { return seq_cid; }
    w = src spawn BuildRewrite(claimed={}, focus=seq_cid);
    if w.result_cid == "" { return seq_cid; }
    return w.result_cid;
}

def apply_rewrite(seq_cid: str, steps: int) -> str {
    src = find_seq(seq_cid);
    if src is None { return seq_cid; }
    cur: str = seq_cid;
    i: int = 0;
    while i < steps {
        cur = rewrite_once(cur);
        i += 1;
    }
    return cur;
}

def seq_union(seq_cid: str) -> list[str] {
    src = find_seq(seq_cid);
    if src is None { return []; }
    w = src spawn UnionCollect(claimed={});
    if seq_cid not in w.unions { return []; }
    return sorted(w.unions[seq_cid]);
}
