def _link_if_absent(par: Item, ch: Item) -> None {
    let kids: list[Item] = [par ->:Link:->][?:Item];
    for kid in kids {
        if kid.cid == ch.cid {
            return;
        }
    }
    par +>:Link:+> ch;
}

def _ensure_item(store: GraphStore, cid: str, val: int) -> Item {
    if cid in store.by_cid {
        return store.by_cid[cid];
    }
    let nd = Item(cid=cid, val=val);
    root ++> nd;
    store.by_cid[cid] = nd;
    return nd;
}

def make_store() -> GraphStore {
    let anchor = Item(cid="__anchor__", val=-1);
    root ++> anchor;
    return GraphStore(anchor=anchor, by_cid={});
}

def add(store: GraphStore, spec: dict) -> str {
    let root_cid = str(spec["id"]);
    let root_nd = _ensure_item(store, root_cid, int(spec["id"]));
    _link_if_absent(store.anchor, root_nd);
    let stack: list[dict] = [];
    let parent_map: dict[str, str] = {};
    let top_children: list = [];
    if "children" in spec {
        top_children = spec["children"];
    }
    for ch_spec in top_children {
        stack.append(ch_spec);
        parent_map[str(ch_spec["id"])] = root_cid;
    }
    while len(stack) > 0 {
        let cur_spec = stack.pop();
        let cur_cid = str(cur_spec["id"]);
        let cur_nd = _ensure_item(store, cur_cid, int(cur_spec["id"]));
        let par_cid = parent_map[cur_cid];
        let par_nd = store.by_cid[par_cid];
        _link_if_absent(par_nd, cur_nd);
        let cur_children: list = [];
        if "children" in cur_spec {
            cur_children = cur_spec["children"];
        }
        for ch_spec in cur_children {
            let ch_cid = str(ch_spec["id"]);
            parent_map[ch_cid] = cur_cid;
            stack.append(ch_spec);
        }
    }
    return root_cid;
}

def count(store: GraphStore) -> int {
    return len(list_ids(store));
}

def list_ids(store: GraphStore) -> list[str] {
    let w = store.anchor spawn CollectWalker(claimed={});
    let out: list[str] = [];
    for cid in w.found {
        if cid != "__anchor__" {
            out.append(cid);
        }
    }
    let sorted_out: list[str] = sorted(out);
    return sorted_out;
}

def reachable(store: GraphStore, start_cid: str) -> list[str] {
    if start_cid not in store.by_cid {
