    root_node = store[root_id];
    claimed: dict[str, bool] = {};
    rows_out: list = [];
    depth_map: dict[str, int] = {};
    w = root_node spawn BfsDepthWalker(
        claimed=claimed, rows=rows_out, depth_by_cid=depth_map
    );
