    ids = sorted(ids);
    ordered: list = [];
    for iid in ids {
        for rec in hits {
            if rec["id"] == iid {
                ordered.append(rec);
            }
        }
    }
    return ordered;
}

def depth_from_json(record: dict) -> int {
    star_key = "*DEPTH*";
    if star_key in record {
        return record[star_key];
    }
