def make_equal(store: TypeStore, lhs: str, rhs: str) -> str {
    cid = store.new_id();
    n = TEq(cid=cid, lhs=lhs, rhs=rhs);
    store.register(cid, n);
    if lhs in store.by_id {
        ln = store.by_id[lhs];
        n +>:TSub:+> ln;
    }
    if rhs in store.by_id {
        rn = store.by_id[rhs];
        n +>:TSub:+> rn;
    }
    return cid;
}

