def compat_types(
    store: TypeStore,
    a: str,
    b: str,
    claimed: dict[str, bool]
) -> bool {
    key = a + "|" + b;
    if key in claimed { return True; }
    claimed[key] = True;
    ka = kind_of(store, a);
    kb = kind_of(store, b);
    if ka == "" or kb == "" { return False; }
    if ka != kb { return False; }
    if ka == "var" {
        av = store.by_id[a] as TVar;
        bv = store.by_id[b] as TVar;
        return av.name == bv.name;
    }
    if ka == "excl" {
        ae = store.by_id[a] as TExcl;
        be = store.by_id[b] as TExcl;
        if not same_banned(ae.banned, be.banned) { return False; }
        return compat_types(store, ae.base, be.base, claimed);
    }
    ae = store.by_id[a] as TEq;
    be = store.by_id[b] as TEq;
    if not compat_types(store, ae.lhs, be.lhs, claimed) { return False; }
    return compat_types(store, ae.rhs, be.rhs, claimed);
