def refine(
    store: TypeStore,
    pattern: str,
    typ: str,
    env: dict[str, str] | None
) -> dict[str, str] | None {
    bindings = env_copy(env);
    if pattern not in store.by_id or typ not in store.by_id { return None; }
    pk = kind_of(store, pattern);
    tk = kind_of(store, typ);
    if pk == "var" {
        pv = store.by_id[pattern] as TVar;
        if tk == "var" {
            tv = store.by_id[typ] as TVar;
            if pv.name != tv.name { return None; }
            return bindings;
        }
        if pv.name in bindings {
            cm: dict[str, bool] = {};
            if not compat_types(store, bindings[pv.name], typ, cm) { return None; }
            return bindings;
        }
        bindings[pv.name] = typ;
        return bindings;
    }
    if pk == "eq" and tk == "eq" {
        pe = store.by_id[pattern] as TEq;
        te = store.by_id[typ] as TEq;
        mid = refine(store, pe.lhs, te.lhs, bindings);
        if mid is None { return None; }
        return refine(store, pe.rhs, te.rhs, mid);
    }
    if pk == "excl" and tk == "excl" {
        pe = store.by_id[pattern] as TExcl;
        te = store.by_id[typ] as TExcl;
        if not same_banned(pe.banned, te.banned) { return None; }
        return refine(store, pe.base, te.base, bindings);
    }
    return None;
}

walker FreeVarsWalk {
    has claimed: dict[str, bool] = {};
    has out: list[str] = [];

    can w_var with TVar entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        nm = here.name;
        seen = False;
        for x in self.out { if x == nm { seen = True; } }
        if not seen { self.out.append(nm); }
        kids: list[object] = [here ->:TSub:->][?:object];
        for k in kids { visit :0: [k]; }
        if not kids { disengage; }
        print("fv", here.cid, self.out);
    }

    can w_excl with TExcl entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        kids: list[object] = [here ->:TSub:->][?:object];
        for k in kids { visit :0: [k]; }
        if not kids { disengage; }
        print("fv", here.cid, self.out);
    }

    can w_eq with TEq entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        kids: list[object] = [here ->:TSub:->][?:object];
        for k in kids { visit :0: [k]; }
        if not kids { disengage; }
        print("fv", here.cid, self.out);
    }
