"""urweb/urweb#74 — recursive CTE reachability via OSP walkers."""

node Entity {
    has eid: str;
}

node CteAnchor {
    has tag: str = "recursive_union";
}

edge Follows {}

def entity_for(store: dict[str, Entity], eid: str) -> Entity {
    if eid in store {
        return store[eid];
    }
    nd = Entity(eid=eid);
    store[eid] = nd;
    return nd;
}

def prepare_cte_graph(
    adjacency: dict[str, list[str]],
    roots: list[str],
) -> tuple[CteAnchor, dict[str, Entity]] {
    store: dict[str, Entity] = {};
    anchor = CteAnchor();
    root ++> anchor;
    for src in adjacency {
        src_nd = entity_for(store, src);
        dst_keys: list[str] = adjacency[src];
        for dst in dst_keys {
            dst_nd = entity_for(store, dst);
            src_nd +>:Follows:+> dst_nd;
        }
    }
    for rid in roots {
        root_nd = entity_for(store, rid);
        anchor ++> root_nd;
    }
    return (anchor, store);
}

walker CteRecursive {
    has claimed: dict[str, bool] = {};
    has found: list[str] = [];
    has depths: dict[str, int] = {};
    has root_depths: dict[str, int] = {};
    has track_depth: bool = False;

    can anchor with CteAnchor entry {
        print("recursive cte anchor union");
        seeds: list[Entity] = [here ->][?:Entity];
        if seeds {
            wk = root spawn CteRecursive(
                claimed=self.claimed,
                found=self.found,
                depths=self.depths,
                root_depths=self.root_depths,
                track_depth=self.track_depth,
            );
            for sd in seeds {
                visit :0: [sd];
            }
        } else {
            disengage;
        }
    }

    can expand with Entity entry {
        if here.eid in self.claimed {
            skip;
        }
        self.claimed[here.eid] = True;
        self.found.append(here.eid);
        dep = 0;
        if self.track_depth {
            if here.eid in self.depths {
                dep = self.depths[here.eid];
            } elif here.eid in self.root_depths {
                dep = self.root_depths[here.eid];
                self.depths[here.eid] = dep;
            } else {
                self.depths[here.eid] = 0;
                dep = 0;
            }
        }
        print("recursive cte row ", here.eid, " depth=", dep);
        nxt: list[Entity] = [here ->:Follows:->][?:Entity];
        if nxt {
            for ch in nxt {
                if self.track_depth {
                    cand = dep + 1;
                    if ch.eid in self.depths {
                        if cand < self.depths[ch.eid] {
                            self.depths[ch.eid] = cand;
                        }
                    } else {
                        self.depths[ch.eid] = cand;
                    }
                }
                visit [ch];
            }
        } else {
            disengage;
        }
    }
}

def cte_reachable(roots: list[str], adjacency: dict[str, list[str]]) -> list[str] {
    fixture = prepare_cte_graph(adjacency, roots);
    anchor = fixture[0];
    w = anchor spawn CteRecursive(
        claimed={},
        found=[],
        depths={},
        root_depths={},
        track_depth=False,
    );
    return sorted(w.found);
}

def cte_min_depth(roots: list[str], adjacency: dict[str, list[str]]) -> dict[str, int] {
    fixture = prepare_cte_graph(adjacency, roots);
    anchor = fixture[0];
    seed_depths: dict[str, int] = {};
