    xs: list[str] = [];
    for r in rows {
        xs.append(r);
    }
    return sorted(xs);
}

def all_emps(hub: Hub) -> list[Emp] {
    out: list[Emp] = [];
    for nd in [hub ->:Link:->][?:Emp] {
        out.append(nd);
    }
    return out;
}

def seeds_from(hub: Hub) -> list[Emp] {
    out: list[Emp] = [];
    for em in all_emps(hub) {
        if em.mgr_cid == "" {
            out.append(em);
        }
    }
    return out;
}

def children_of(hub: Hub, parent: Emp) -> list[Emp] {
    kids: list[Emp] = [];
    for em in all_emps(hub) {
        if em.mgr_cid == parent.cid {
            kids.append(em);
        }
    }
    return kids;
}

def dedupe_emp_rows(frontier: list[Emp]) -> list[Emp] {
    seen: dict[str, bool] = {};
    out: list[Emp] = [];
    for em in frontier {
        k = row_key(em.name, em.eid);
        if k in seen {
            continue;
        }
        seen[k] = True;
        out.append(em);
    }
    return out;
}

def attach(hub: Hub, em: Emp) -> None {
    hub +>:Link:+> em;
}

def execute_recurse_cte(graph_root: Hub, distinct: bool) -> list[str] {
    w = graph_root spawn RecurseRun(distinct_mode=distinct);
    return sort_rows(w.collected);
}
