```jac
"""
Audio dependency graph topological resolution.

Provenance: austintheriot/resonix#2
"""

node GraphAnchor {
    has gid: str = "audio_graph";
}

node AudioNode {
    has cid: str;
    has label: str = "";
}

edge Member {}
edge Depends {}

obj AudioGraph {
    has anchor: GraphAnchor;
    has nodes: dict[str, AudioNode];
}

walker TopoWalker {
    has claimed: dict[str, bool] = {};
    has order: list[str] = [];

    can step_anchor with GraphAnchor entry {
        members: list[AudioNode] = [];
        for m in [here ->:Member:->][?:AudioNode] {
            members.append(m);
        }
        cids: list[str] = [];
        for m in members {
            cids.append(m.cid);
        }
        cids = sorted(cids);
        ordered: list[AudioNode] = [];
        for cid in cids {
            for m in members {
                if m.cid == cid {
                    ordered.append(m);
                }
            }
        }
        visit :0: ordered;
    }

    can step_node with AudioNode entry {
        if here.cid in self.claimed {
            skip;
        }
        deps: list[AudioNode] = [];
        for d in [here ->:Depends:->][?:AudioNode] {
            deps.append(d);
        }
        dep_ids: list[str] = [];
        for d in deps {
            dep_ids.append(d.cid);
        }
        dep_ids = sorted(dep_ids);
        ordered_deps: list[AudioNode] = [];
        for did in dep_ids {
            for d in deps {
                if d.cid == did {
                    ordered_deps.append(d);
                }
            }
        }
        visit :0: ordered_deps;
        self.claimed[here.cid] = True;
        self.order.append(here.cid);
        print(here.cid);
    }
}

def create_graph() -> AudioGraph {
    anch = GraphAnchor();
    store: dict[str, AudioNode] = {};
    return AudioGraph(anchor=anch, nodes=store);
}

def add_node(g: AudioGraph, cid: str, label: str = "") -> bool {
    if cid in g.nodes {
        return False;
    }
    nd = AudioNode(cid=cid, label=label);
    g.nodes[cid] = nd;
    g.anchor +>:Member:+> nd;
    return True;
}

def add_dependency(g: AudioGraph, consumer_id: str, producer_id: str) -> bool {
    if consumer_id not in g.nodes {
        return False;
    }
    if producer_id not in g.nodes {
        return False;
    }
    consumer = g.nodes[consumer_id] as AudioNode;
    producer = g.nodes[producer_id] as AudioNode;
    consumer +>:Depends:+> producer;
    return True;
}

def resolve_order(g: AudioGraph) -> list[str] {
    claimed: dict[str, bool] = {};
    order: list[str] = [];
    w = g.anchor spawn TopoWalker(claimed=claimed, order=order);
    return w.order;
}

def has_node(g: AudioGraph, cid: str) -> bool {
    return cid in g.nodes;
}
