        parent_nd = _ensure_node(store, parent_id);
        child_nd = _ensure_node(store, child_id);
        parent_nd +>:ParentOf:+> child_nd;
    }
    return store;
}

def build_parent_map(edges: list[list[str]]) -> dict[str, str] {
