        downs: list[Note] = [here <-:Parent:<-][?:Note];
        for d in downs {
            visit [d];
        }
        linked: list[Note] = [here ++>][?:Note];
        for ln in linked {
            visit [ln];
        }
    }
}

walker AncestorWalk {
    has claimed: dict[str, bool] = {};
    has start_nid: str = "";
    has ids: list[str] = [];

    can climb with Note entry {
        if here.nid in self.claimed { skip; }
        self.claimed[here.nid] = True;
        parents: list[Note] = [here ->:Parent:->][?:Note];
        pnids: list[str] = [];
        for p in parents {
            pnids.append(p.nid);
