        sorted_pnids: list[str] = sorted(pnids);
        for pid in sorted_pnids {
            for p in parents {
                if p.nid == pid {
                    if p.nid not in self.claimed {
                        self.ids.append(p.nid);
                        print("ancestor", p.nid);
                        visit [p];
                    }
                }
            }
        }
    }
}

