    start: Note | None = find_note(graph_root, start_id);
    if start is None {
        return [];
    }
    wk = start spawn AncestorWalk(claimed={}, start_nid=start_id, ids=[]);
    print("ancestors_of done", start_id);
    return wk.ids;
