"""zenstackhq/zenstack#2363 — Views, materialized views, and recursive CTE registry."""

glob KIND_STANDARD = "standard";
glob KIND_MATERIALIZED = "materialized";
glob KIND_CTE = "cte";

node Registry {
    has tag: str = "registry";
}

node ViewDef {
    has vid: str;
    has name: str;
    has kind: str;
    has query_key: str;
    has refresh_on_migrate: bool = False;
    has allow_role: str = "";
    has deny_null: bool = False;
    has cache: list[str] = [];
}

node OrgUnit {
    has uid: int;
    has parent_uid: int = 0;
}

node OrderRow {
    has month_key: str;
    has amount: int;
}

node UserRow {
    has uid: int;
    has active: bool = True;
}

edge ReportsTo {}

walker DepthWalker {
    has claimed: dict[int, bool] = {};
    has depths: dict[int, int] = {};
    has level: int = 1;

    can walk with OrgUnit entry {
        if here.uid in self.claimed { skip; }
        self.claimed[here.uid] = True;
        self.depths[here.uid] = self.level;
        print("depth uid=" + str(here.uid) + " at=" + str(self.level));
        kids: list[OrgUnit] = [here ->:ReportsTo:->][?:OrgUnit];
        base: int = self.level;
        for kid in kids {
            self.level = base + 1;
            visit :0: [kid];
        }
        self.level = base;
    }
}

def lookup_view(reg: Registry, vid: str) -> ViewDef | None {
    for v in [reg ->][?:ViewDef] {
        if v.vid == vid { return v; }
    }
    return None;
}

def eval_monthly_sales(orders: list[OrderRow]) -> list[str] {
    totals: dict[str, int] = {};
    for o in orders {
        if o.month_key in totals { totals[o.month_key] = totals[o.month_key] + o.amount; }
        else { totals[o.month_key] = o.amount; }
    }
    keys: list[str] = [];
    for k in totals { keys.append(k); }
    keys.sort();
    out: list[str] = [];
    for k in keys { out.append(k + ":" + str(totals[k])); }
    return out;
}

def eval_active_users(users: list[UserRow]) -> list[str] {
    out: list[str] = [];
    for u in users {
        if u.active { out.append("u" + str(u.uid)); }
    }
    out.sort();
    return out;
}

def make_registry() -> Registry {
    reg = Registry();
    return reg;
}

def add_view(
    reg: Registry,
    name: str,
    kind: str,
    query_key: str,
    refresh_on_migrate: bool = False
) -> str {
    v = ViewDef(
        vid=name,
        name=name,
        kind=kind,
        query_key=query_key,
        refresh_on_migrate=refresh_on_migrate
    );
    if query_key == "monthly_sales" {
        v.allow_role = "ANALYST";
        v.deny_null = True;
    } else {
        if query_key == "active_users" { v.deny_null = True; }
    }
    reg ++> v;
    return name;
}

def list_views(reg: Registry) -> list[str] {
    ids: list[str] = [];
    for v in [reg ->][?:ViewDef] { ids.append(v.vid); }
    ids.sort();
    return ids;
}

def evaluate_view(
    reg: Registry,
    vid: str,
    orders: list[OrderRow],
    users: list[UserRow]
) -> list[str] {
    v: ViewDef | None = lookup_view(reg, vid);
    if v is None { return []; }
    if v.kind == KIND_MATERIALIZED { return v.cache; }
    if v.query_key == "monthly_sales" { return eval_monthly_sales(orders); }
    if v.query_key == "active_users" { return eval_active_users(users); }
    return [];
}

def refresh_materialized(
    reg: Registry,
    vid: str,
    orders: list[OrderRow],
    users: list[UserRow]
) -> list[str] {
    v: ViewDef | None = lookup_view(reg, vid);
    if v is None { return []; }
    if v.kind != KIND_MATERIALIZED { return []; }
    rows: list[str] = [];
    if v.query_key == "monthly_sales" { rows = eval_monthly_sales(orders); }
    else {
        if v.query_key == "active_users" { rows = eval_active_users(users); }
    }
    v.cache = rows;
    return rows;
}

def org_depths(uids: list[int], parents: list[int]) -> dict[int, int] {
    by_id: dict[int, OrgUnit] = {};
    roots: list[OrgUnit] = [];
    i: int = 0;
    while i < len(uids) {
        u = OrgUnit(uid=uids[i], parent_uid=parents[i]);
        by_id[uids[i]] = u;
        if parents[i] == 0 { roots.append(u); }
        i = i + 1;
    }
    j: int = 0;
    while j < len(uids) {
        if parents[j] != 0 {
            p: OrgUnit = by_id[parents[j]];
            c: OrgUnit = by_id[uids[j]];
            p +>:ReportsTo:+> c;
        }
        j = j + 1;
    }
    merged: dict[int, int] = {};
    for r in roots {
        w = r spawn DepthWalker(claimed={}, depths={}, level=1);
        for k in w.depths { merged[k] = w.depths[k]; }
    }
    return merged;
}

def can_read(reg: Registry, vid: str, role: str, auth_null: bool) -> bool {
    v: ViewDef | None = lookup_view(reg, vid);
    if v is None { return False; }
    if v.deny_null and auth_null { return False; }
    if v.allow_role != "" and role != v.allow_role { return False; }
    return True;
}
