        parent_id: int | None = None;
        if "parent_id" in row {
            parent_id = row["parent_id"];
        }
        nd = TreeRow(cid=cid, pk=pk, prefix=prefix, parent_id=parent_id);
        anchor ++> nd;
        nodes[cid] = nd;
    }
    for row in rows {
        prefix: str = row["prefix"];
        pk: int = row["pk"];
        cid: str = _row_key(prefix, pk);
        nd = nodes[cid] as TreeRow;
        if "parent_id" in row and row["parent_id"] is not None {
            par_cid: str = _row_key(prefix, row["parent_id"]);
            if par_cid in nodes {
                par = nodes[par_cid] as TreeRow;
                par +>:HasChild:+> nd;
                nd +>:HasParent:+> par;
