def _known_view(view_key: str) -> bool {
    keys: list[str] = view_catalog_keys();
    for k in keys {
        if k == view_key { return True; }
    }
    return False;
}

def policy_allows_view(view_key: str, auth_role: str | None) -> bool {
    if view_key == MONTHLY_KEY {
        if auth_role is None { return False; }
        if auth_role != "ANALYST" { return False; }
        return True;
    } elif view_key == ACTIVE_KEY {
        if auth_role is None { return False; }
        return True;
