def eval_monthly_sales(orders: list) -> list[str] {
    buckets: dict[str, int] = {};
    for raw in orders {
        mk = raw["month"] as str;
        amt = raw["amount"] as int;
        if mk in buckets { buckets[mk] = buckets[mk] + amt; }
        else { buckets[mk] = amt; }
    }
    months: list[str] = [];
    for mk in buckets { months.append(mk); }
    months.sort();
    out: list[str] = [];
    rid: int = 1;
    for mk in months {
        out.append(str(rid));
        rid = rid + 1;
    }
    return out;
}

def eval_active_users(users: list) -> list[str] {
    out: list[str] = [];
    for raw in users {
        active = raw["is_active"] as bool;
        if active {
            uid = raw["id"] as int;
            out.append(str(uid));
        }
    }
    out.sort();
    return out;
}

def _org_nonce(org_units: list) -> str {
    nonce: int = len(org_units);
    for raw in org_units { nonce = nonce + (raw["id"] as int); }
    return str(nonce);
}

def _index_org_nodes(org_units: list, nonce: str) -> dict[int, OrgUnit] {
    store: dict[int, OrgUnit] = {};
    for raw in org_units {
        uid = raw["id"] as int;
        pid = raw["parent_id"];
        nd = OrgUnit(cid=f"ou_{nonce}_{uid}", unit_id=uid, parent_id=pid);
        root ++> nd;
        store[uid] = nd;
    }
    return store;
}

def _wire_org_tree(store: dict[int, OrgUnit], org_units: list, extra_edges: list) {
    for raw in org_units {
        uid = raw["id"] as int;
        pid = raw["parent_id"];
        child = store[uid] as OrgUnit;
        if pid is not None {
            par = store[pid as int] as OrgUnit;
            par +>:OrgChild:+> child;
        }
    }
    for pair in extra_edges {
        a = pair[0] as int;
        b = pair[1] as int;
        par = store[a] as OrgUnit;
        ch = store[b] as OrgUnit;
        par +>:OrgChild:+> ch;
    }
}

def eval_org_hierarchy(org_units: list, extra_edges: list | None = None) -> list[str] {
    edges: list = [];
    if extra_edges is not None { edges = extra_edges; }
    nonce = _org_nonce(org_units);
    store = _index_org_nodes(org_units, nonce);
    _wire_org_tree(store, org_units, edges);
    anchors: list[OrgUnit] = [];
    for raw in org_units {
        if raw["parent_id"] is None {
            nd = store[raw["id"] as int] as OrgUnit;
            nd.depth = 1;
            anchors.append(nd);
        }
    }
    w = root spawn CteWalker(claimed={});
    for a in anchors { w.visit a; }
    ids: list[int] = [];
    for x in w.ordered_ids { ids.append(x); }
    ids.sort();
    out: list[str] = [];
    for x in ids { out.append(str(x)); }
    return out;
}

def query_view(view_key: str, auth_role: str | None, auth_dept: int | None, orders: list, users: list, org_units: list) -> list[str] {
    if not _known_view(view_key) { return []; }
    if not policy_allows_view(view_key, auth_role) { return []; }
    rows: list[str] = [];
    if view_key == MONTHLY_KEY { rows = eval_monthly_sales(orders); }
    elif view_key == ACTIVE_KEY { rows = eval_active_users(users); }
    elif view_key == ORG_KEY {
        all_rows = eval_org_hierarchy(org_units);
        filtered: list[str] = [];
        for rid in all_rows {
            if auth_dept is not None and str(auth_dept) == rid {
                filtered.append(rid);
            }
        }
        rows = filtered;
    }
    rows.sort();
    return rows;
}

