    has bag: list[str] = [];

    can walk with type_def entry {
        if here.name in self.claimed {
            skip;
        }
        self.claimed[here.name] = True;
        if here.name != self.start_name {
            self.bag.append(here.name);
        }
        nxt: list[type_def] = [];
        for ch in [here ->:type_ref:->][?:type_def] {
            nxt.append(ch);
        }
        nxt = sort_type_defs(nxt);
        visit :0: nxt;
    }
}

walker recur_check {
    has claimed: dict[str, bool] = {};
    has origin: str = "";
    has found: bool = False;
    has entered_origin: bool = False;

    can probe with type_def entry {
        if here.name == self.origin and self.entered_origin {
            self.found = True;
            skip;
        }
        if here.name in self.claimed {
            skip;
        }
        if here.name == self.origin {
            self.entered_origin = True;
        }
        self.claimed[here.name] = True;
        nxt: list[type_def] = [];
        for ch in [here ->:type_ref:->][?:type_def] {
            nxt.append(ch);
        }
        nxt = sort_type_defs(nxt);
        visit :0: nxt;
    }
}

walker topo_collect {
    has claimed: dict[str, bool] = {};
    has order: list[str] = [];

    can visit_types with type_def entry {
        if here.name in self.claimed {
            skip;
        }
        self.claimed[here.name] = True;
        deps: list[type_def] = [];
        for ch in [here ->:type_ref:->][?:type_def] {
            deps.append(ch);
        }
        deps = sort_type_defs(deps);
        visit :0: deps;
        self.order.append(here.name);
    }
}

def direct_refs(type_name: str, graph_root: schema_root) -> list[str] {
    td = find_type(graph_root, type_name);
    if td is None {
        return [];
    }
    out: list[str] = [];
    seen: dict[str, bool] = {};
    for ch in [td ->:type_ref:->][?:type_def] {
        if not dict_has_key(seen, ch.name) {
            seen[ch.name] = True;
            out.append(ch.name);
        }
    }
    print("direct_refs", type_name, sorted(out));
    return sorted(out);
}

def transitive_deps(type_name: str, graph_root: schema_root) -> list[str] {
    td = find_type(graph_root, type_name);
    if td is None {
        return [];
    }
    w = td spawn collect_deps(start_name=type_name, claimed={}, bag=[]);
    print("transitive_deps", type_name, sorted(w.bag));
    return sorted(w.bag);
}

def struct_is_recursive(type_name: str, graph_root: schema_root) -> bool {
    td = find_type(graph_root, type_name);
    if td is None {
        return False;
    }
    w = td spawn recur_check(origin=type_name, claimed={}, found=False, entered_origin=False);
    print("struct_is_recursive", type_name, w.found);
    return w.found;
}

def encode_order(primary: str, graph_root: schema_root) -> list[str] {
    td = find_type(graph_root, primary);
    if td is None {
        return [];
    }
    w = td spawn topo_collect(claimed={}, order=[]);
    print("encode_order", primary, w.order);
    return w.order;
}

def references_unknown(type_name: str, graph_root: schema_root) -> list[str] {
    td = find_type(graph_root, type_name);
    if td is None {
        return [];
    }
    known: dict[str, bool] = {};
    for t in [graph_root ->>][?:type_def] {
        known[t.name] = True;
    }
    unknown: list[str] = [];
    seen: dict[str, bool] = {};
    for fr in [td ->:owns_field:->][?:field_row] {
        ft = fr.ftype;
        if dict_has_key(known, ft) {
            continue;
        }
        if is_primitive(ft) {
            continue;
        }
        if not dict_has_key(seen, ft) {
            seen[ft] = True;
            unknown.append(ft);
        }
    }
    print("references_unknown", type_name, sorted(unknown));
    return sorted(unknown);
}
