"""Profile call-tree flat/cum top-N aggregation (joerick/pyinstrument#293)."""

node GraphRoot {
    has tag: str = "root";
}

node CallFrame {
    has cid: str;
    has name: str;
    has self_ms: float;
    has subtotal: float = 0.0;
}

edge ChildCall {}

walker FlatCollect {
    has claimed: dict[str, bool] = {};
    has totals: dict[str, float] = {};

    can step_root with GraphRoot entry {
        kids: list[CallFrame] = [here ->:ChildCall:->][?:CallFrame];
        for fr in kids {
            visit fr;
        }
        disengage;
    }

    can step_frame with CallFrame entry {
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        nm = here.name;
        if nm in self.totals {
            self.totals[nm] += here.self_ms;
        } else {
            self.totals[nm] = here.self_ms;
        }
        ch: list[CallFrame] = [here ->:ChildCall:->][?:CallFrame];
        for kid in ch {
            visit kid;
        }
        print([nm, self.totals[nm]]);
    }
}

walker CumCollect {
    has claimed: dict[str, bool] = {};
    has totals: dict[str, float] = {};

    can step_root with GraphRoot entry {
        kids: list[CallFrame] = [here ->:ChildCall:->][?:CallFrame];
        for fr in kids {
            visit fr;
        }
        disengage;
    }

    can step_frame with CallFrame entry {
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        ch: list[CallFrame] = [here ->:ChildCall:->][?:CallFrame];
        for kid in ch {
            visit kid;
        }
        sub: float = here.self_ms;
        for kid in ch {
            sub += kid.subtotal;
        }
        here.subtotal = sub;
        nm = here.name;
        if nm in self.totals {
            self.totals[nm] += here.subtotal;
        } else {
            self.totals[nm] = here.subtotal;
        }
        print([here.cid, here.subtotal]);
    }
}

def top_n_from_map(totals: dict[str, float], n: int) -> list {
    keys: list[str] = [];
    for k in totals {
        keys.append(k);
    }
    out: list = [];
    used: dict[str, bool] = {};
    lim: int = n;
    if lim > len(keys) {
        lim = len(keys);
    }
    i: int = 0;
    while i < lim {
        best: str = "";
        best_v: float = -1.0;
        for k in keys {
            if k in used {
                continue;
            }
            v = totals[k] as float;
            pick: bool = False;
            if best == "" {
                pick = True;
            } elif v > best_v {
                pick = True;
            } elif v == best_v and k < best {
                pick = True;
            }
            if pick {
                best = k;
                best_v = v;
            }
        }
        used[best] = True;
        row: list = [best, best_v];
        out.append(row);
        i += 1;
    }
    return out;
}

def build_profile(records: list[dict]) -> GraphRoot {
    anchor = GraphRoot();
    root ++> anchor;
    by_cid: dict[str, CallFrame] = {};
    for rec in records {
        cid = rec["cid"] as str;
        if cid in by_cid {
            continue;
        }
        nm = rec["name"] as str;
        ms = rec["self_ms"] as float;
        fr = CallFrame(cid=cid, name=nm, self_ms=ms);
        by_cid[cid] = fr;
    }
    for rec in records {
        cid = rec["cid"] as str;
        fr = by_cid[cid] as CallFrame;
        pcid = None;
        if "parent_cid" in rec {
            pcid = rec["parent_cid"];
        }
        if pcid is None {
            anchor +>:ChildCall:+> fr;
        } elif pcid in by_cid {
            par = by_cid[pcid] as CallFrame;
            par +>:ChildCall:+> fr;
        } else {
            anchor +>:ChildCall:+> fr;
        }
    }
    return anchor;
}

def flat_top(graph_root: GraphRoot, n: int) -> list {
    wk = graph_root spawn FlatCollect(claimed={}, totals={});
    return top_n_from_map(wk.totals, n);
}

def cum_top(graph_root: GraphRoot, n: int) -> list {
    wk = graph_root spawn CumCollect(claimed={}, totals={});
    return top_n_from_map(wk.totals, n);
}

