        by_id[rid] = nd;
        graph_root ++> nd;
    }
    for e in edges {
        parent_nd = by_id[e[0]] as Row;
        child_nd = by_id[e[1]] as Row;
        parent_nd +>:Ref:+> child_nd;
    }
    store: dict = {};
    store["root"] = graph_root;
    store["by_id"] = by_id;
    return store;
}

walker RecursiveDescent {
    has claimed: dict[str, bool] = {};
    has found: list[str] = [];
    has node_depth: dict[str, int] = {};
    has seeds: list[Row] = [];
    has booted: bool = False;

    can boot with Row entry {
        if here.rid != "__root__" {
