        parent_d = self.node_depth[here.rid] as int;
        kids: list[Row] = [];
        for kid in [here ->:Ref:->][?:Row] {
            kids.append(kid);
        }
        child_d = parent_d + 1;
        for kid in kids {
            if kid.rid in self.node_depth {
                old_d = self.node_depth[kid.rid] as int;
                if child_d < old_d {
                    self.node_depth[kid.rid] = child_d;
