    }

    def _find_station(self, station_id: str) -> Station | None {
        self._ensure_anchor();
        nodes: list[Station] = [self.anchor ->][?:Station];
        for st_nd in nodes {
            if st_nd.sid == station_id {
                return st_nd;
            }
        }
        return None;
