        self._ensure_anchor();
        st_nd = Station(sid=station_id, long_name=long_name, short_name=short_name);
        self.anchor ++> st_nd;
    }

    def add_relation(self, parent_id: str, child_id: str) {
        parent = self._find_responsibility(parent_id);
        child = self._find_responsibility(child_id);
        if parent is None or child is None {
            return;
        }
        parent +>:ChildOf:+> child;
    }

    def link_responsibility_station(self, resp_id: str, station_id: str) {
        resp = self._find_responsibility(resp_id);
        station = self._find_station(station_id);
        if resp is None or station is None {
            return;
