def create_citation_graph(
    nodes: list[tuple[str, str]],
    edges: list[tuple[str, str]],
) -> GraphStore {
    gs = GraphStore(label="local");
    root ++> gs;
    id_map: dict[str, CitationNode] = {};
    for spec in nodes {
        nid: str = spec[0];
        title: str = spec[1];
        nd = CitationNode(cid=nid, title=title);
        gs ++> nd;
        id_map[nid] = nd;
    }
    for pair in edges {
        a_id: str = pair[0];
        b_id: str = pair[1];
        if a_id in id_map and b_id in id_map {
            a = id_map[a_id];
            b = id_map[b_id];
            a +>:CoCit:+> b;
        }
    }
    return gs;
}

def export_node_list(graph_root: GraphStore) -> list[tuple[str, str]] {
    rows: list[tuple[str, str]] = [];
    for nd in [graph_root ->][?:CitationNode] {
        rows.append((nd.cid, nd.title));
    }
    out: list[tuple[str, str]] = [];
    for row in sorted(rows) {
        out.append(row);
    }
    return out;
}

def export_edge_list(graph_root: GraphStore) -> list[tuple[str, str]] {
    w = graph_root spawn EdgeGather(claimed={}, edges_out=[]);
    raw: list[tuple[str, str]] = w.edges_out;
    out: list[tuple[str, str]] = [];
    for e in sorted(raw) {
        out.append(e);
    }
    return out;
}

def export_adjacency_matrix(
    graph_root: GraphStore,
    node_order: list[str] | None = None,
) -> list[list[int]] {
    ids: list[str] = [];
    if node_order {
        ids = node_order;
    } else {
        for nd in [graph_root ->][?:CitationNode] {
            ids.append(nd.cid);
        }
        ids.sort();
    }
    idx_map: dict[str, int] = {};
    i: int = 0;
    for nid in ids {
        idx_map[nid] = i;
        i += 1;
    }
    n: int = len(ids);
    mat: list[list[int]] = [];
    r: int = 0;
    while r < n {
        row: list[int] = [];
        c: int = 0;
        while c < n {
            row.append(0);
            c += 1;
        }
        mat.append(row);
        r += 1;
    }
    edge_pairs = export_edge_list(graph_root);
    for pair in edge_pairs {
        src: str = pair[0];
        dst: str = pair[1];
        if src in idx_map and dst in idx_map {
            ri: int = idx_map[src];
            ci: int = idx_map[dst];
            mat[ri][ci] = 1;
        }
    }
    return mat;
}

def bfs_spanning_tree(
    graph_root: GraphStore,
    start_id: str,
) -> list[tuple[str, str]] {
    found: bool = False;
    for nd in [graph_root ->][?:CitationNode] {
        if nd.cid == start_id {
            found = True;
        }
    }
    if not found {
        return [];
    }
    w = graph_root spawn BfsSpan(claimed={}, tree_edges=[], start_id=start_id);
    out: list[tuple[str, str]] = [];
    for e in sorted(w.tree_edges) {
        out.append(e);
    }
    return out;
}

