def ensure_item(store: LocGraph, item_id: str) -> Item {
    if item_id not in store.item_by_id {
        it = Item(iid=item_id);
        store ++> it;
        store.item_by_id[item_id] = it;
    } else {
        it = store.item_by_id[item_id];
    }
    return it;
}

def assign_item_location(store: LocGraph, item_id: str, location_id: str) -> bool {
    if location_id not in store.location_by_id {
        return False;
    }
    it = ensure_item(store, item_id);
    loc = store.location_by_id[location_id];
    it +>:AtLocation:+> loc;
    return True;
}

def subtree_location_ids(store: LocGraph, root_id: str) -> list[str] {
    if root_id not in store.location_by_id {
        return [];
    }
    root_loc = store.location_by_id[root_id];
    w = root_loc spawn SubtreeIds(claimed={});
    out: list[str] = [];
    for x in w.found {
        out.append(x);
    }
    return sorted(out);
}

def items_in_subtree(store: LocGraph, root_id: str) -> list[str] {
    if root_id not in store.location_by_id {
        return [];
    }
    ids = subtree_location_ids(store, root_id);
    in_sub: dict[str, bool] = {};
    for lid in ids {
        in_sub[lid] = True;
    }
    found: list[str] = [];
    for iid in store.item_by_id {
        it = store.item_by_id[iid];
        for loc in [it ->:AtLocation:->][?:Location] {
            if loc.lid in in_sub {
                found.append(iid);
                break;
            }
        }
    }
    return sorted(found);
}

