        if here.uid != self.origin_uid {
            self.found.append(here.uid);
            print(f"desc:{here.uid}");
        }
        kids: list[User] = [];
        for ch in [here ->:Follows:->][?:User] {
            kids.append(ch);
        }
        if kids {
