        if here.uid in self.claimed {
            skip;
        }
        self.claimed[here.uid] = True;
        if here.uid != self.origin_uid {
            self.found.append(here.uid);
            print(f"anc:{here.uid}");
        }
        parents: list[User] = [];
        for p in [<-:Follows:<-][?:User] {
            parents.append(p);
        }
        if parents {
            visit :0: parents;
        } else {
            disengage;
        }
    }
}

def get_descendants(hub: GraphHub, user_id: str) -> list[str] {
