def make_dir_graph(
    specs: list[tuple[str, str, str]],
    extra_links: list[tuple[str, str]] | None = None
) -> WatchHandle {
    nodes_store: dict[str, Dir] = {};
    anchor_nd = Dir(cid="__anchor__", path="");
    root ++> anchor_nd;
    for item in specs {
        nd = Dir(cid=item[0], path=item[1]);
        nodes_store[item[0]] = nd;
    }
    for item in specs {
        child_nd = nodes_store[item[0]] as Dir;
        if item[2] == "" {
            anchor_nd +>:Subdir:+> child_nd;
        } else {
            parent_nd = nodes_store[item[2]] as Dir;
            parent_nd +>:Subdir:+> child_nd;
        }
    }
    links: list[tuple[str, str]] = [];
    if extra_links is not None {
        for lk in extra_links {
            links.append(lk);
        }
    }
    for lk in links {
        parent_nd = nodes_store[lk[0]] as Dir;
        child_nd = nodes_store[lk[1]] as Dir;
        parent_nd +>:Subdir:+> child_nd;
    }
    return WatchHandle(anchor=anchor_nd, nodes=nodes_store);
}

