edge GEdge {}

walker BfsWalker {
    has claimed: dict[str, bool] = {};
    has goal_id: int = -1;
    has found: int = -1;

    can step with GNode entry {
        cid: str = str(here.idx);
        if cid in self.claimed {
            skip;
        }
        self.claimed[cid] = True;
        print(["bfs", here.idx, here.dist]);
        if here.idx == self.goal_id {
            self.found = here.dist;
            disengage;
        }
        kids: list[GNode] = [];
        for ch in [here ->:GEdge:->][?:GNode] {
            ckey: str = str(ch.idx);
            if ckey not in self.claimed {
                ch.dist = here.dist + 1;
                kids.append(ch);
            }
        }
        visit :0: kids else {
            disengage;
        }
    }
}

def reset_distances(nodes: list[GNode]) -> None {
    for nd in nodes {
        nd.dist = -1;
    }
}

def build_nodes(adj: list[list[int]]) -> list[GNode] {
    nodes: list[GNode] = [];
    for i in range(len(adj)) {
        nd = GNode(idx=i);
        nodes.append(nd);
    }
    for i in range(len(adj)) {
        for j in adj[i] {
            if j >= 0 && j < len(nodes) {
                nodes[i] +>:GEdge:+> nodes[j];
            }
        }
    }
    return nodes;
}

def bfs_distance(
    nodes: list[GNode],
    start: GNode,
    goal: GNode,
) -> int {
    reset_distances(nodes);
    start.dist = 0;
    w = start spawn BfsWalker(claimed={}, goal_id=goal.idx, found=-1);
    return w.found;
}

def shortest_cycle_length(graph: list[list[int]], target: int) -> int {
    n = len(graph);
    if target < 0 || target >= n {
        return -1;
    }
    nodes = build_nodes(graph);
    tgt = nodes[target];
    for ch in [tgt ->:GEdge:->][?:GNode] {
        if ch.idx == target {
            return 1;
        }
    }
    best = -1;
    nbrs: list[GNode] = [];
    for ch in [tgt ->:GEdge:->][?:GNode] {
        nbrs.append(ch);
    }
    for u in nbrs {
        d = bfs_distance(nodes, u, tgt);
        if d != -1 {
            cand = d + 1;
            if best == -1 || cand < best {
                best = cand;
            }
        }
    }
    return best;
}
