    has order: list[str] = [];

    can hub_collect with GraphHub entry {
        keys: list[str] = [];
        for k in here.cells {
            keys.append(k);
        }
        sorted_keys: list[str] = sorted(keys);
        for k in sorted_keys {
            nd = here.cells[k];
            visit nd;
