        if here.cid in self.claimed {
            skip;
        }
        deps: list[Cell] = [here ->:Depends:->][?:Cell];
        for dep in deps {
            visit dep;
        }
        self.claimed[here.cid] = True;
        self.order.append(here.cid);
        print([here.cid, "collect"]);
    }
}

obj DepGraph {
    has hub: GraphHub;

    def _ensure_cell(self, cid: str) -> Cell {
        if cid in self.hub.cells {
            return self.hub.cells[cid];
        }
        nd = Cell(cid=cid);
        self.hub ++> nd;
        self.hub.cells[cid] = nd;
        return nd;
    }

    def _has_dep_edge(self, cell_nd: Cell, dep_nd: Cell) -> bool {
        outs: list[Cell] = [cell_nd ->:Depends:->][?:Cell];
        for ex in outs {
            if ex.cid == dep_nd.cid {
                return True;
            }
        }
        return False;
    }

    def add_dependency(self, cell: str, dependency: str) -> None {
        dep_nd = self._ensure_cell(dependency);
        cell_nd = self._ensure_cell(cell);
        if self._has_dep_edge(cell_nd, dep_nd) {
            return;
        }
        cell_nd +>:Depends:+> dep_nd;
    }

    def remove_cell(self, cell: str) -> None {
        if cell not in self.hub.cells {
            return;
        }
        target = self.hub.cells[cell];
        out_deps: list[Cell] = [target ->:Depends:->][?:Cell];
        for dep in out_deps {
            target disconnect Depends dep;
        }
        keys: list[str] = [];
        for k in self.hub.cells {
            keys.append(k);
        }
        for k in keys {
            if k == cell {
                continue;
            }
            nd = self.hub.cells[k];
            in_deps: list[Cell] = [nd ->:Depends:->][?:Cell];
            for dep in in_deps {
                if dep.cid == cell {
                    nd disconnect Depends target;
                }
            }
        }
        self.hub disconnect target;
        del self.hub.cells[cell];
    }

    def has_cycle(self) -> bool {
        claimed: dict[str, bool] = {};
        in_stack: dict[str, bool] = {};
        wk = self.hub spawn CycleWalker(claimed=claimed, in_stack=in_stack);
        return wk.found_cycle;
    }

    def topo_sort(self) -> list[str] {
        if self.has_cycle() {
            empty: list[str] = [];
            return empty;
        }
        claimed: dict[str, bool] = {};
        order: list[str] = [];
        wk = self.hub spawn TopoWalker(claimed=claimed, order=order);
        return wk.order;
    }
}

def DepGraph() -> DepGraph {
    hub_nd = GraphHub();
    root ++> hub_nd;
    return DepGraph(hub=hub_nd);
}
