def build_adjacency(modules: list[list[str]], refs: list[list[str]]) -> dict[str, list[str]] {
    adj: dict[str, list[str]] = {};
    for row in modules {
        mid = row[0];
        adj[mid] = [];
    }
    for row in refs {
        src = row[0];
        dst = row[1];
        adj[src].append(dst);
    }
    return adj;
}

def _graph_from_adjacency(adjacency: dict[str, list[str]]) -> ModuleGraph {
    g = ModuleGraph();
    anchor = Module(mid="__anchor__");
    g.graph_root = anchor;
    root ++> anchor;
    mids: list[str] = [];
    for k in adjacency {
        mids.append(k);
    }
    for mid in mids {
        if mid not in g.by_id {
            nd = Module(mid=mid);
            g.by_id[mid] = nd;
            anchor ++> nd;
        }
    }
    for mid in mids {
        src_nd = g.by_id[mid];
        deps = adjacency[mid];
        for dst in deps {
            if dst not in g.by_id {
                dst_nd = Module(mid=dst);
                g.by_id[dst] = dst_nd;
                anchor ++> dst_nd;
            }
            dst_nd = g.by_id[dst];
            src_nd +>:Ref:+> dst_nd;
        }
    }
    return g;
}

def extract_module_closure(adjacency: dict[str, list[str]], module_id: str) -> list[str] {
    if module_id not in adjacency {
        return [];
    }
    g = _graph_from_adjacency(adjacency);
    start = g.by_id[module_id];
    w = start spawn ClosureWalker(claimed={});
    out: list[str] = [];
    for x in w.found {
        out.append(x);
    }
    out.sort();
    print(out);
    return out;
}

def module_extraction_manifest(adjacency: dict[str, list[str]], module_id: str) -> dict[str, list[str]] {
    closure = extract_module_closure(adjacency, module_id);
    manifest: dict[str, list[str]] = {};
    in_closure: dict[str, bool] = {};
    for mid in closure {
        in_closure[mid] = True;
    }
    for mid in closure {
        deps: list[str] = [];
        raw = adjacency[mid];
        for dep in raw {
            if dep in in_closure {
                deps.append(dep);
            }
        }
        deps.sort();
        manifest[mid] = deps;
    }
    return manifest;
}
