"""Meet-Patel10/PulseGuard#220 — Topological Sort + Cycle Detection."""

node Skill {
    has sid: str;
}

edge Requires {}

obj GraphView {
    has anchor: Skill;
    has by_id: dict[str, Skill] = {};
    has indegree: dict[str, int] = {};
}

walker KahnWalker {
    has claimed: dict[str, bool] = {};
    has order: list[str] = [];
    has indeg: dict[str, int] = {};
    has pending: list[Skill] = [];
    has booted: bool = False;

    can process with Skill entry {
        if here.sid == "__root__" {
            if not self.booted {
                self.booted = True;
                for sd in self.pending {
                    visit :0: sd;
                }
            }
            disengage;
        }
        if here.sid in self.claimed {
            skip;
        }
        self.claimed[here.sid] = True;
        self.order.append(here.sid);
        nbrs: list[Skill] = [here ->:Requires:->][?:Skill];
        ready: list[Skill] = [];
        for nb in nbrs {
            nid: str = nb.sid;
            if nid in self.indeg {
                self.indeg[nid] = self.indeg[nid] - 1;
                if self.indeg[nid] == 0 {
                    ready.append(nb);
                }
            }
        }
        rids: list[str] = [];
        for nb in ready {
            rids.append(nb.sid);
        }
        rids = sorted(rids);
        for rid in rids {
            for nb in ready {
                if nb.sid == rid {
                    visit :0: nb;
                }
            }
        }
        print ("kahn " + here.sid);
    }
}

walker CollectWalker {
    has claimed: dict[str, bool] = {};
    has needed: dict[str, bool] = {};
    has want: dict[str, bool] = {};

    can climb with Skill entry {
        if here.sid in self.claimed {
            skip;
        }
        self.claimed[here.sid] = True;
        if here.sid in self.want {
            self.needed[here.sid] = True;
        }
        ups: list[Skill] = [<-:Requires:<-][?:Skill];
        ups_sorted: list[Skill] = [];
        uids: list[str] = [];
        for up in ups {
            uids.append(up.sid);
        }
        uids = sorted(uids);
        for uid in uids {
            for up in ups {
                if up.sid == uid {
                    ups_sorted.append(up);
                }
            }
        }
        for up in ups_sorted {
            visit :0: up;
        }
        print ("collect " + here.sid);
    }
}

def _run_kahn(gv: GraphView) -> list[str] {
    indeg: dict[str, int] = {};
    for sid in gv.indegree {
        indeg[sid] = gv.indegree[sid];
    }
    seeds: list[Skill] = [];
    sids: list[str] = [];
    for sid in gv.by_id {
        sids.append(sid);
    }
    sids = sorted(sids);
    for sid in sids {
        if indeg[sid] == 0 {
            seeds.append(gv.by_id[sid]);
        }
    }
    wk: KahnWalker = gv.anchor spawn KahnWalker(
        claimed={}, order=[], indeg=indeg, pending=seeds, booted=False
    );
    return wk.order;
}

def build_skill_graph(edges: list[tuple[str, str]]) -> GraphView {
    anc: Skill = Skill(sid="__root__");
    gv = GraphView(anchor=anc);
    root ++> anc;
    for pair in edges {
        prereq: str = pair[0];
        skill: str = pair[1];
        if prereq not in gv.by_id {
            pn: Skill = Skill(sid=prereq);
            gv.by_id[prereq] = pn;
            anc ++> pn;
            gv.indegree[prereq] = 0;
        }
        if skill not in gv.by_id {
            sn: Skill = Skill(sid=skill);
            gv.by_id[skill] = sn;
            anc ++> sn;
            gv.indegree[skill] = 0;
        }
        pa: Skill = gv.by_id[prereq];
        sb: Skill = gv.by_id[skill];
        pa +>: Requires :+> sb;
        gv.indegree[skill] = gv.indegree[skill] + 1;
    }
    return gv;
}

def graph_has_cycle(gv: GraphView) -> bool {
    ord: list[str] = _run_kahn(gv);
    return len(ord) != len(gv.by_id);
}

def graph_topological_order(gv: GraphView) -> list[str] | None {
    ord: list[str] = _run_kahn(gv);
    if len(ord) != len(gv.by_id) {
        return None;
    }
    return ord;
}

def plan_learning_path(gv: GraphView, missing: list[str]) -> list[str] | None {
    if graph_has_cycle(gv) {
        return None;
    }
    full: list[str] | None = graph_topological_order(gv);
    if full is None {
        return None;
    }
    want: dict[str, bool] = {};
    for m in missing {
        if m in gv.by_id {
            want[m] = True;
        }
    }
    needed: dict[str, bool] = {};
    for m in missing {
        if m not in gv.by_id {
            continue;
        }
        cw: CollectWalker = gv.by_id[m] spawn CollectWalker(
            claimed={}, needed={}, want=want
        );
        for sid in cw.needed {
            needed[sid] = True;
        }
    }
    out: list[str] = [];
    for sid in full {
        if sid in needed {
            out.append(sid);
        }
    }
    return out;
}
