"""Terraform module extraction — TechnicallyJoe/terraform-motf#54."""

node Module {
    has mid: str;
}

edge ModuleRef {}

obj ModuleGraph {
    has graph_root: Module;
    has by_id: dict[str, Module] = {};
}

walker CollectClosure {
    has claimed: dict[str, bool] = {};
    has found: list[str] = [];

    can collect with Module entry {
        if here.mid in self.claimed {
            skip;
        }
        self.claimed[here.mid] = True;
        self.found.append(here.mid);
        print("collect " + here.mid);
        kids: list[Module] = [here ->:ModuleRef:->][?:Module];
        if kids {
            for kid in kids {
                visit :0: [kid];
            }
        } else {
            disengage;
        }
    }
}

def build_module_graph(adjacency: dict[str, list[str]]) -> ModuleGraph {
    anchor = Module(mid="__anchor__");
    root ++> anchor;
    by_id: dict[str, Module] = {};
    keys: list[str] = [];
    for k in adjacency {
        keys.append(k);
    }
    for mid in keys {
        if mid not in by_id {
            nd = Module(mid=mid);
            root ++> nd;
            by_id[mid] = nd;
        }
        deps: list[str] = adjacency[mid];
        for dep in deps {
            if dep not in by_id {
                dep_nd = Module(mid=dep);
                root ++> dep_nd;
                by_id[dep] = dep_nd;
            }
        }
    }
    for mid in keys {
        src = by_id[mid];
        deps: list[str] = adjacency[mid];
        for dep in deps {
            dst = by_id[dep];
            src +>:ModuleRef:+> dst;
        }
    }
    g = ModuleGraph(graph_root=anchor, by_id=by_id);
    return g;
}

def extract_module_closure(g: ModuleGraph, module_id: str) -> list[str] {
    if module_id not in g.by_id {
        return [];
    }
    start = g.by_id[module_id];
    w = start spawn CollectClosure();
    raw: list[str] = w.found;
    out: list[str] = sorted(raw);
    return out;
}

def list_all_modules(g: ModuleGraph) -> list[str] {
    mids: list[str] = [];
    for mid in g.by_id {
        mids.append(mid);
    }
    return sorted(mids);
}
