"""
maik-hasler/vocational-training-resources#3
Recursive level-progression path (recursive CTE analogue).
"""

node Level {
    has lvl: int;
    has step_xp: int;
    has cid: str;
}

edge Next {}

obj GraphHandle {
    has by_lvl: dict[int, Level] = {};
}

walker CtePath {
    has claimed: dict[str, bool] = {};
    has start_lvl: int;
    has end_lvl: int;
    has acc: int = 0;
    has rows: list[tuple[int, int]] = [];

    can step with Level entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        if here.lvl < self.start_lvl {
            kids: list[Level] = [here ->:Next:->][?:Level];
            if kids {
                visit :0: kids;
            } else {
                disengage;
            }
        } else {
            if here.lvl > self.end_lvl {
                disengage;
            } else {
                new_acc: int = self.acc + here.step_xp;
                self.rows.append((here.lvl, new_acc));
                self.acc = new_acc;
                if here.lvl == self.end_lvl {
                    disengage;
                } else {
                    nxts: list[Level] = [here ->:Next:->][?:Level];
                    if nxts {
                        visit :0: nxts;
                    } else {
                        disengage;
                    }
                }
            }
        }
    }
}

def build_progression(steps: list[tuple[int, int]]) -> GraphHandle {
    gh = GraphHandle();
    prev: Level | None = None;
    for pair in steps {
        lvl: int = pair[0];
        xp: int = pair[1];
        cid: str = "L" + str(lvl);
        nd = Level(lvl=lvl, step_xp=xp, cid=cid);
        gh.by_lvl[lvl] = nd;
        root ++> nd;
        if prev {
            prev +>:Next:+> nd;
        }
        prev = nd;
    }
    return gh;
}

def add_edge(gh: GraphHandle, src: int, dst: int) -> None {
    if src not in gh.by_lvl {
        return;
    }
    if dst not in gh.by_lvl {
        return;
    }
    a = gh.by_lvl[src];
    b = gh.by_lvl[dst];
    a +>:Next:+> b;
}

def progression_path(gh: GraphHandle, start: int, end: int) -> list[tuple[int, int]] {
    if start not in gh.by_lvl {
        return [];
    }
    if end not in gh.by_lvl {
        return [];
    }
    if start > end {
        return [];
    }
    src = gh.by_lvl[start];
    w = src spawn CtePath(start_lvl=start, end_lvl=end, claimed={});
    out: list[tuple[int, int]] = [];
    for row in w.rows {
        out.append(row);
    }
    out.sort();
    return out;
}

def total_xp(gh: GraphHandle, start: int, end: int) -> int {
    path = progression_path(gh, start, end);
    if len(path) == 0 {
        return 0;
    }
    last = path[len(path) - 1];
    return last[1];
}
