"""Typed recursive CTE hierarchy traversal — adrianbrowning/prisma-ts-select#162."""

node GraphRoot {
    has name: str;
}

node Emp {
    has eid: str;
    has label: str;
}

edge ReportsTo {}

obj HierarchyGraph {
    has graph_root: GraphRoot;
    has by_id: dict[str, Emp] = {};
}

walker RecursiveCteWalker {
    has claimed: dict[str, bool] = {};
    has results: list[str] = [];
    has pending_anchors: list[str] = [];
    has by_id: dict[str, Emp] = {};

    can start with GraphRoot entry {
        print("recursive_cte anchor phase");
        seeds: list[Emp] = [];
        for aid in self.pending_anchors {
            if aid in self.by_id {
                seeds.append(self.by_id[aid]);
            }
        }
        if seeds {
            visit :0: seeds;
        } else {
            disengage;
        }
    }

    can descend with Emp entry {
        if here.eid in self.claimed {
            skip;
        }
        self.claimed[here.eid] = True;
        self.results.append(here.eid);
        print("cte_row " + here.eid);
        kids: list[Emp] = [];
        for ch in [here ->:ReportsTo:->][?:Emp] {
            kids.append(ch);
        }
        if kids {
            visit :0: kids;
        } else {
            disengage;
        }
    }
}

def make_hierarchy(edges: list[tuple[str, str]]) -> HierarchyGraph {
    g = HierarchyGraph();
    gr = GraphRoot(name="org");
    root ++> gr;
    g.graph_root = gr;
    touched: dict[str, bool] = {};
    for pair in edges {
        pid = pair[0];
        cid = pair[1];
        if pid not in touched {
            touched[pid] = True;
            p = Emp(eid=pid, label=pid);
            g.by_id[pid] = p;
            gr ++> p;
        }
        if cid not in touched {
            touched[cid] = True;
            c = Emp(eid=cid, label=cid);
            g.by_id[cid] = c;
            gr ++> c;
        }
        parent = g.by_id[pid];
        child = g.by_id[cid];
        parent +>:ReportsTo:+> child;
    }
    return g;
}

def with_recursive(anchor_ids: list[str], graph: HierarchyGraph) -> list[str] {
    w = graph.graph_root spawn RecursiveCteWalker(
        claimed={},
        pending_anchors=anchor_ids,
        by_id=graph.by_id
    );
    out: list[str] = [];
    for rid in w.results {
        out.append(rid);
    }
    out.sort();
    return out;
}

def column_compatible(anchor_cols: list[str], member_cols: list[str]) -> bool {
    if len(anchor_cols) != len(member_cols) {
        return False;
    }
    for i in range(len(anchor_cols)) {
        if anchor_cols[i] != member_cols[i] {
            return False;
        }
    }
    return True;
}

def recursive_sql(
    name: str,
    anchor_ids: list[str],
    graph: HierarchyGraph,
    dialect: str
) -> str {
    anchor_list = "";
    for i in range(len(anchor_ids)) {
        if i > 0 {
            anchor_list = anchor_list + ",";
        }
        anchor_list = anchor_list + "'" + anchor_ids[i] + "'";
    }
    anchor_q = "SELECT eid FROM emp WHERE eid IN (" + anchor_list + ")";
    member_q = "SELECT c.eid FROM emp c JOIN " + name + " p ON c.manager_id = p.eid";
    body = anchor_q + " UNION ALL " + member_q;
    sql = "WITH RECURSIVE " + name + " AS (" + body + ") SELECT * FROM " + name;
    if dialect == "mysql" {
        sql = "WITH RECURSIVE " + name + " AS (" + body + ") SELECT * FROM " + name;
    }
    return sql;
}

def node_id_known(node_id: str, graph: HierarchyGraph) -> bool {
    return node_id in graph.by_id;
}
