"""Meet-Patel10/PulseGuard#63 — Topological Sort & Cycle Detection."""

node Service {
    has sid: str;
}

edge DependsOn {}

walker DfsPaint {
    has claimed: dict[str, int] = {};
    has found_cycle: bool = False;
    has finish_order: list[str] = [];

    can paint with Service entry {
        sid = here.sid;
        if sid in self.claimed {
            if self.claimed[sid] == 1 {
                self.found_cycle = True;
            }
            skip;
        }
        self.claimed[sid] = 1;
        preds: list[Service] = [here ->:DependsOn:->][?:Service];
        for p in preds {
            visit [p];
        }
        self.claimed[sid] = 2;
        self.finish_order.append(sid);
        print("paint ", sid);
    }
}

def create_dependency_graph() -> dict {
    g: dict = {};
    lookup: dict[str, Service] = {};
    g["lookup"] = lookup;
    return g;
}

def add_dependency(graph: dict, service: str, depends_on: str) {
    lookup = graph["lookup"] as dict[str, Service];
    if service not in lookup {
        sn = Service(sid=service);
        lookup[service] = sn;
        root ++> sn;
    }
    if depends_on not in lookup {
        dn = Service(sid=depends_on);
        lookup[depends_on] = dn;
        root ++> dn;
    }
    prereq = lookup[depends_on];
    dependent = lookup[service];
    prereq +>:DependsOn:+> dependent;
}

def has_circular_dependency(graph: dict) -> bool {
    lookup = graph["lookup"] as dict[str, Service];
    claimed: dict[str, int] = {};
    cyclic = False;
    keys = sorted(lookup.keys());
    for sid in keys {
        if sid not in claimed {
            w = lookup[sid] spawn DfsPaint(
                claimed=claimed,
                found_cycle=cyclic,
                finish_order=[]
            );
            cyclic = cyclic or w.found_cycle;
            claimed = w.claimed;
        }
    }
    return cyclic;
}

def dependency_order(graph: dict) -> list[str] {
    if has_circular_dependency(graph) {
        raise ValueError("circular dependency detected");
    }
    lookup = graph["lookup"] as dict[str, Service];
    claimed: dict[str, int] = {};
    order: list[str] = [];
    keys = sorted(lookup.keys());
    for sid in keys {
        if sid not in claimed {
            w = lookup[sid] spawn DfsPaint(
                claimed=claimed,
                found_cycle=False,
                finish_order=order
            );
            order = w.finish_order;
            claimed = w.claimed;
        }
    }
    return order;
}
