def make_hierarchy(edges: list[tuple[str, str]]) -> HierarchyGraph {
    g = HierarchyGraph();
    root ++> g;
    store: dict[str, HierarchyNode] = {};
    for e in edges {
        parent_id = e[0];
        child_id = e[1];
        if parent_id not in store {
            pn = HierarchyNode(nid=parent_id);
            store[parent_id] = pn;
            g ++> pn;
        }
        if child_id not in store {
            cn = HierarchyNode(nid=child_id);
            store[child_id] = cn;
            g ++> cn;
        }
        store[parent_id] +>:ParentOf:+> store[child_id];
    }
    return g;
}

def anchor_rows(g: HierarchyGraph, anchor_ids: list[str]) -> list[str] {
    rows: list[str] = [];
    for aid in anchor_ids {
        nd = get_node_by_id(g, aid);
        if nd is not None {
            rows.append(nd.nid);
        }
    }
    rows = sorted(rows);
    return rows;
}

def closure_rows(g: HierarchyGraph, anchor_ids: list[str]) -> list[str] {
    claimed: dict[str, bool] = {};
    collected: list[str] = [];
    for aid in anchor_ids {
        nd = get_node_by_id(g, aid);
        if nd is None {
            continue;
