        w = nd spawn RecursiveWalker(claimed=claimed, collected=[]);
        for row in w.collected {
            collected.append(row);
        }
        for k in w.claimed {
            claimed[k] = w.claimed[k];
        }
    }
    collected = sorted(collected);
    return collected;
}

def with_recursive(g: HierarchyGraph, anchor_ids: list[str]) -> list[str] {
    merged: list[str] = [];
    seen: dict[str, bool] = {};
    anchor = anchor_rows(g, anchor_ids);
    closure = closure_rows(g, anchor_ids);
    for x in anchor {
        if x not in seen {
            merged.append(x);
            seen[x] = True;
        }
    }
    for x in closure {
        if x not in seen {
            merged.append(x);
            seen[x] = True;
