def replace_substr(text: str, pattern: str, replacement: str) -> str {
  if pattern == "" {
    return text;
  }
  out: str = "";
  i: int = 0;
  while i < len(text) {
    matched: bool = True;
    if i + len(pattern) > len(text) {
      matched = False;
    } else {
      j: int = 0;
      while j < len(pattern) {
        if text[i + j] != pattern[j] {
          matched = False;
        }
        j += 1;
      }
    }
    if matched {
      out = out + replacement;
      i = i + len(pattern);
    } else {
      out = out + text[i];
      i += 1;
    }
  }
  return out;
}

