            nxt.append(ch);
        }
        if nxt {
            visit :0: nxt;
        } else {
            disengage;
        }
    }
}

walker CycleProbe {
    has claimed: dict[str, bool] = {};
    has cyclic: bool = False;

    can probe with Schema entry {
        if here.sid in self.claimed {
            self.cyclic = True;
            skip;
        }
        self.claimed[here.sid] = True;
        print("probe", here.sid);
        nxt: list[Schema] = [];
        for ch in [here ->:Ref:->][?:Schema] {
            nxt.append(ch);
        }
        if nxt {
            visit :0: nxt;
        } else {
            disengage;
        }
    }
}

walker Materialize {
    has claimed: dict[str, bool] = {};
    has built: dict[str, dict] = {};

    can mat with Schema entry {
        if here.sid in self.claimed {
            skip;
        }
        self.claimed[here.sid] = True;
        print("materialize", here.sid);
        blob = here.def_blob;
        out: dict = {};
        if "title" in blob {
            out["title"] = blob["title"];
        }
        if "type" in blob {
            out["type"] = blob["type"];
        }
        props_out: dict = {};
        if "properties" in blob {
            props = blob["properties"] as dict;
            for pk in props {
                p = props[pk] as dict;
                if "$ref" in p {
                    rid = parse_ref(p["$ref"] as str);
                    props_out[pk] = {"$ref": "#/definitions/" + rid};
                } else {
                    props_out[pk] = p;
                }
            }
        }
        if props_out {
            out["properties"] = props_out;
        }
        self.built[here.sid] = out;
        nxt: list[Schema] = [];
        for ch in [here ->:Ref:->][?:Schema] {
            nxt.append(ch);
        }
        if nxt {
            visit :0: nxt;
        } else {
            disengage;
        }
    }
}

def parse_ref(ref: str) -> str {
    if not ref.startswith("#/definitions/") {
        return "";
    }
    parts: list[str] = ref.split("/");
    if len(parts) < 3 {
        return "";
    }
    return parts[2];
}

def _maybe_ref(defn: dict) -> str {
    if "$ref" in defn {
        return parse_ref(defn["$ref"] as str);
    }
    return "";
}

def _refs_in_def(defn: dict) -> list[str] {
    found: list[str] = [];
    rid = _maybe_ref(defn);
    if rid {
        found.append(rid);
    }
    if "properties" in defn {
        props = defn["properties"] as dict;
        for k in props {
            sub = props[k] as dict;
            r2 = _maybe_ref(sub);
            if r2 {
                found.append(r2);
            }
        }
    }
    if "patternProperties" in defn {
        pp = defn["patternProperties"] as dict;
        for k in pp {
            sub = pp[k] as dict;
            r2 = _maybe_ref(sub);
            if r2 {
                found.append(r2);
            }
        }
    }
    if "items" in defn {
        sub = defn["items"] as dict;
        r2 = _maybe_ref(sub);
        if r2 {
            found.append(r2);
        }
    }
    if "oneOf" in defn {
        oo = defn["oneOf"] as list;
        for item in oo {
            sub = item as dict;
            r2 = _maybe_ref(sub);
            if r2 {
                found.append(r2);
            }
        }
    }
    return found;
}

def _sorted_unique(xs: list[str]) -> list[str] {
    seen: dict[str, bool] = {};
    out: list[str] = [];
    for x in xs {
        if x not in seen {
            seen[x] = True;
            out.append(x);
        }
    }
    return sorted(out);
}

def ingest_definitions(definitions: dict) -> GraphHandle {
    gh = GraphHandle();
    root ++> gh;
    store: dict[str, Schema] = {};
    for sid in definitions {
        defn = definitions[sid] as dict;
        title = "";
        if "title" in defn {
            title = defn["title"] as str;
        }
        nd = Schema(sid=sid, title=title, def_blob=defn);
        root ++> nd;
        store[sid] = nd;
    }
    gh.nodes = store;
    for sid in definitions {
        defn = definitions[sid] as dict;
        src = store[sid];
        targets = _refs_in_def(defn);
        for tid in targets {
            if tid in store {
                dst = store[tid];
                src +>:Ref:+> dst;
            }
        }
    }
    return gh;
}

def transitive_ref_closure(gh: GraphHandle, schema_id: str) -> list[str] {
    if schema_id not in gh.nodes {
        return [];
    }
    start = gh.nodes[schema_id];
    w = start spawn CollectRefs();
    return _sorted_unique(w.out);
}

def is_cyclic(gh: GraphHandle, schema_id: str) -> bool {
    if schema_id not in gh.nodes {
        return False;
    }
    start = gh.nodes[schema_id];
    w = start spawn CycleProbe();
    return w.cyclic;
}

def materialize_schema(gh: GraphHandle, schema_id: str) -> dict {
    if schema_id not in gh.nodes {
        return {};
    }
    start = gh.nodes[schema_id];
    w = start spawn Materialize();
    if schema_id in w.built {
        return w.built[schema_id];
    }
    return {};
}

def json_safe_schema(gh: GraphHandle, schema_id: str) -> dict {
    return materialize_schema(gh, schema_id);
}
