def normalize_cycle(path: list[str]) -> list[str] {
    if len(path) == 0 {
        empty: list[str] = [];
        return empty;
    }
    best: list[str] = path;
    k = 0;
    while k < len(path) {
        rot: list[str] = [];
        i = k;
        while i < len(path) {
            rot.append(path[i]);
            i = i + 1;
        }
        j = 0;
        while j < k {
            rot.append(path[j]);
            j = j + 1;
        }
        if len(rot) < len(best) {
            best = rot;
        }
        k = k + 1;
    }
    return best;
}

def dedupe_cycles(raw: list[list[str]]) -> list[list[str]] {
    normed: list[list[str]] = [];
    for p in raw {
        normed.append(normalize_cycle(p));
    }
    uniq: list[list[str]] = [];
    seen: dict[str, bool] = {};
    for p in normed {
        key = "";
        for nm in p {
            key = key + nm + "\x00";
        }
        if not (key in seen) {
            seen[key] = True;
            uniq.append(p);
        }
    }
    return uniq;
}

walker CycleScan {
    has claimed: dict[str, bool] = {};
    has done: dict[str, bool] = {};
    has cycles: list[list[str]] = {};
    has path: list[str] = {};

    can dfs with Record entry {
        if here.name in self.done {
            skip;
        }
        if here.name in self.claimed and self.claimed[here.name] {
            cyc: list[str] = [];
            start_at = 0;
            idx = 0;
            for nm in self.path {
                if nm == here.name {
                    start_at = idx;
                }
                idx = idx + 1;
            }
            pos = start_at;
            while pos < len(self.path) {
                cyc.append(self.path[pos]);
                pos = pos + 1;
            }
            cyc.append(here.name);
            self.cycles.append(cyc);
            print here.name;
            skip;
        }
        self.claimed[here.name] = True;
        self.path.append(here.name);
        nexts: list[Record] = [];
        for kid in [here ->:FieldRef:->][?:Record] {
            nexts.append(kid);
        }
        ordered: list[Record] = [];
        knames: list[str] = [];
        for kid in nexts {
            knames.append(kid.name);
        }
        knames = sorted(knames);
        for kn in knames {
            for kid in nexts {
                if kid.name == kn {
                    ordered.append(kid);
                }
            }
        }
        if ordered {
            visit :0: ordered;
        } else {
            disengage;
        }
        trimmed: list[str] = [];
        lim = len(self.path) - 1;
        ti = 0;
        for nm in self.path {
            if ti < lim {
                trimmed.append(nm);
            }
            ti = ti + 1;
        }
        self.path = trimmed;
        self.claimed[here.name] = False;
        self.done[here.name] = True;
    }
}

def find_record_cycles(definitions: dict[str, list[str]]) -> list[list[str]] {
    hub = build_graph(definitions);
    global_done: dict[str, bool] = {};
    raw: list[list[str]] = {};
    starters: list[Record] = [];
    for rec in [hub ->:Member:->][?:Record] {
        starters.append(rec);
    }
    snames: list[str] = [];
    for rec in starters {
        snames.append(rec.name);
    }
    snames = sorted(snames);
    for sn in snames {
        for rec in starters {
            if rec.name == sn {
                if sn in global_done and global_done[sn] {
                    continue;
                }
                w = rec spawn CycleScan(
                    claimed={},
                    done=global_done,
                    cycles={},
                    path={}
                );
                for c in w.cycles {
                    raw.append(c);
                }
            }
        }
    }
    return dedupe_cycles(raw);
}

def check_no_record_cycles(definitions: dict[str, list[str]]) -> None {
    found = find_record_cycles(definitions);
    if len(found) > 0 {
        raise ValueError("by-value record cycle detected");
    }
}

