"""Lift for michelin/snowflake-grafana-datasource#29 — recursive CI run lineage."""

node Run {
    has cid: str;
    has run_id: str;
    has upstream_run_id: str = "";
    has job_name: str = "";
    has started: int = 0;
    has completed: int = 0;
    has pr_id: str = "";
    has pr_create: int = 0;
}

edge Downstream {}

walker ClosureWalker {
    has claimed: dict[str, bool] = {};
    has found: list[Run] = [];

    can step with Run entry {
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        self.found.append(here);
        print("visit", here.run_id);
        kids: list[Run] = [];
        for ch in [here ->:Downstream:->][?:Run] {
            kids.append(ch);
        }
        visit kids else {
            disengage;
        }
    }
}

def run_row_dict(rn: Run) -> dict {
    row: dict = {};
    row["run_id"] = rn.run_id;
    row["upstream_run_id"] = rn.upstream_run_id;
    row["job_name"] = rn.job_name;
    row["started"] = rn.started;
    row["completed"] = rn.completed;
    row["pr_id"] = rn.pr_id;
    row["pr_create"] = rn.pr_create;
    return row;
}

def build_lineage_store(run_rows: list[dict]) -> dict[str, Run] {
    index: dict[str, Run] = {};
    for row in run_rows {
        rid = str(row["run_id"]);
        up_val = row.get("upstream_run_id", "");
        up_str = "";
        if up_val is not None {
            up_str = str(up_val);
        }
        nd = Run(
            cid=rid,
            run_id=rid,
            upstream_run_id=up_str,
            job_name=str(row.get("job_name", "")),
            started=int(row.get("started", 0)),
            completed=int(row.get("completed", 0)),
            pr_id=str(row.get("pr_id", "")),
            pr_create=int(row.get("pr_create", 0))
        );
        root ++> nd;
        index[rid] = nd;
    }
    for row in run_rows {
        rid = str(row["run_id"]);
        up_val = row.get("upstream_run_id", "");
        up_str = "";
        if up_val is not None {
            up_str = str(up_val);
        }
        if up_str == "" {
            continue;
        }
        parent = index.get(up_str, None);
        if parent is None {
            continue;
        }
        child = index[rid];
        parent +>:Downstream:+> child;
    }
    return index;
}

def recursive_run_closure(store: dict[str, Run], seed_ids: list[str]) -> list[dict] {
    shared: dict[str, bool] = {};
    out: list[dict] = [];
    out_seen: dict[str, bool] = {};
    for sid in seed_ids {
        nd = store.get(sid, None);
        if nd is None {
            continue;
        }
        w = nd spawn ClosureWalker(claimed=shared);
        for rn in w.found {
            if rn.run_id in out_seen {
                continue;
            }
            out_seen[rn.run_id] = True;
            out.append(run_row_dict(rn));
        }
    }
    return out;
}

def sum_s3_machine_time(rows: list[dict]) -> list[dict] {
    acc: dict[str, int] = {};
    meta: dict[str, dict] = {};
    for row in rows {
        pr_id = str(row["pr_id"]);
        pr_create = int(row["pr_create"]);
        key = str(pr_create).zfill(16) + "|" + pr_id;
        if key not in meta {
            m: dict = {};
            m["time"] = pr_create;
            m["pr_id"] = pr_id;
            meta[key] = m;
            acc[key] = 0;
        }
        jn = str(row["job_name"]);
        if jn.startswith("s3_") {
            delta = int(row["completed"]) - int(row["started"]);
            acc[key] = acc[key] + delta;
        }
    }
    keys: list[str] = [];
    for k in meta {
        keys.append(k);
    }
    keys = sorted(keys);
    out: list[dict] = [];
    for k in keys {
        item: dict = {};
        item["time"] = int(meta[k]["time"]);
        item["s3_machine_time"] = int(acc[k]);
        out.append(item);
    }
    return out;
}

