"""michelin/snowflake-grafana-datasource#29 — recursive CI run lineage lift."""

node Run {
  has run_id: str;
  has upstream_run_id: str = "";
  has pr: str = "";
  has pr_create: str = "";
  has job_name: str = "";
  has started: int = 0;
  has completed: int = 0;
}

edge Triggers {}

walker LineageCollector {
  has claimed: dict[str, bool] = {};
  has found: list[str] = [];

  can collect with Run entry {
    if here.run_id in self.claimed {
      skip;
    }
    self.claimed[here.run_id] = True;
    self.found.append(here.run_id);
    print("visit", here.run_id);
    kids: list[Run] = [here ->:Triggers:->][?:Run];
    if kids {
      visit :0: kids;
    } else {
      disengage;
    }
  }
}

def make_run(
  run_id: str,
  upstream_run_id: str,
  pr: str,
  pr_create: str,
  job_name: str,
  started: int,
  completed: int,
) -> Run {
  nd = Run(
    run_id=run_id,
    upstream_run_id=upstream_run_id,
    pr=pr,
    pr_create=pr_create,
    job_name=job_name,
    started=started,
    completed=completed,
  );
  root ++> nd;
  return nd;
}

def connect_trigger(upstream: Run, downstream: Run) -> None {
  upstream +>:Triggers:+> downstream;
}

def in_window(pr_create: str, window_start: str, window_end: str) -> bool {
  if pr_create < window_start {
    return False;
  }
  if pr_create > window_end {
    return False;
  }
  return True;
}

def lookup_run(run_id: str) -> Run | None {
  hits: list[Run] = [root -->][?:Run];
  for nd in hits {
    if nd.run_id == run_id {
      return nd;
    }
  }
  return None;
}

def recursive_collect(
  seeds: list[Run],
  window_start: str,
  window_end: str,
) -> list[str] {
  merged: list[str] = [];
  seen_merge: dict[str, bool] = {};
  for seed in seeds {
    if not in_window(seed.pr_create, window_start, window_end) {
      continue;
    }
    w = seed spawn LineageCollector(claimed={}, found=[]);
    for rid in w.found {
      if rid not in seen_merge {
        seen_merge[rid] = True;
        merged.append(rid);
      }
    }
  }
  merged.sort();
  return merged;
}

def collect_runs_by_ids(run_ids: list[str]) -> list[Run] {
  out: list[Run] = [];
  for rid in run_ids {
    nd = lookup_run(rid);
    if nd != None {
      out.append(nd);
    }
  }
  return out;
}

def s3_machine_time_by_pr(records: list[Run]) -> list[tuple[str, str, int]] {
  agg: list[tuple[str, str, int]] = [];
  for rec in records {
    if not rec.job_name.startswith("s3_") {
      continue;
    }
    dur = rec.completed - rec.started;
    hit = False;
    for i in range(len(agg)) {
      row = agg[i];
      if row[0] == rec.pr and row[1] == rec.pr_create {
        agg[i] = (row[0], row[1], row[2] + dur);
        hit = True;
        break;
      }
    }
    if not hit {
      agg.append((rec.pr, rec.pr_create, dur));
    }
  }
  agg.sort();
  return agg;
}
