def block_comment_end(source: str, pos: int) -> int {
    depth: int = 1;
    i: int = pos + 2;
    n: int = len(source);
    while i < n and depth > 0 {
        if i + 1 < n and source[i] == "/" and source[i + 1] == "*" {
            depth += 1;
            i += 2;
        } else if i + 1 < n and source[i] == "*" and source[i + 1] == "/" {
            depth -= 1;
            i += 2;
        } else {
            i += 1;
        }
    }
    return i;
}

def strip_comments_recursive(source: str) -> str {
    out: str = "";
    i: int = 0;
    n: int = len(source);
    while i < n {
        if i + 1 < n and source[i] == "/" and source[i + 1] == "*" {
            i = block_comment_end(source, i);
        } else if i + 1 < n and source[i] == "/" and source[i + 1] == "/" {
            while i < n and source[i] != "\n" {
                i += 1;
            }
        } else {
            out += source[i];
            i += 1;
        }
    }
    return out;
}

def has_unquoted_js_key(source: str) -> bool {
    i: int = 0;
    n: int = len(source);
    while i < n {
        if source[i] == "{" {
            j: int = i + 1;
            while j < n and source[j] == " " {
                j += 1;
            }
            if j < n and source[j] != "\"" and source[j] != "}" {
                k: int = j;
                while k < n and source[k] != ":" and source[k] != " " and source[k] != "\t" {
                    k += 1;
                }
                if k < n and source[k] == ":" {
                    return True;
                }
            }
        }
        i += 1;
    }
    return False;
}

def link_next(a: JTok, b: JTok) -> None {
    a +>:JNext:+> b;
}

def graph_for_text(source: str) -> JRoot {
    g = JRoot(text=source);
    root ++> g;
    first: JTok | None = None;
    prev: JTok | None = None;
    i: int = 0;
    n: int = len(source);
    while i < n {
        tok: JTok | None = None;
        if i + 1 < n and source[i] == "/" and source[i + 1] == "*" {
            end_i: int = block_comment_end(source, i);
            lex: str = source[i:end_i];
            tok = JTok(kind="comment", lex=lex, i=i);
            i = end_i;
        } else if has_unquoted_js_key(source[i:]) {
            tok = JTok(kind="js_expr", lex=source[i:], i=i);
            i = n;
        } else {
            tok = JTok(kind="data", lex=source[i:], i=i);
            i = n;
        }
        root ++> tok;
        if first is None {
            first = tok;
            g +>:JChild:+> tok;
        }
        if prev is not None {
            link_next(prev, tok);
        }
        prev = tok;
    }
    return g;
}

def decode_object_body(inner: str) -> dict[str, object] {
    d: dict[str, object] = {};
    if inner == "" {
        return d;
    }
    i: int = 0;
    m: int = len(inner);
    while i < m {
        while i < m and inner[i] == " " {
            i += 1;
        }
        if i >= m or inner[i] != "\"" {
            break;
        }
        j: int = i + 1;
        while j < m and inner[j] != "\"" {
            j += 1;
        }
        key: str = inner[i + 1:j];
        i = j + 1;
        while i < m and inner[i] != ":" {
            i += 1;
        }
        i += 1;
        while i < m and inner[i] == " " {
            i += 1;
        }
        if i < m and inner[i] == "\"" {
            j2: int = i + 1;
            while j2 < m and inner[j2] != "\"" {
                j2 += 1;
            }
            d[key] = inner[i + 1:j2];
            i = j2 + 1;
        } else {
            j2 = i;
            while j2 < m and inner[j2] != "," {
                j2 += 1;
            }
            d[key] = int(inner[i:j2]);
            i = j2;
        }
        while i < m and (inner[i] == "," or inner[i] == " ") {
            i += 1;
        }
    }
    return d;
}

def decode_json_text(text: str) -> object {
    t: str = text.strip();
    m: int = len(t);
    if m >= 2 and t[0] == "\"" and t[m - 1] == "\"" {
        return t[1:m - 1];
    }
    if t == "true" {
        return True;
    }
    if t == "false" {
        return False;
    }
    if t == "null" {
        return None;
    }
    if m >= 2 and t[0] == "{" and t[m - 1] == "}" {
        return decode_object_body(t[1:m - 1].strip());
    }
    return int(t);
}

