def parse_weak_json(source: str, skip_comments: bool = False, fail_on_javascript: bool = True) -> object {
    if fail_on_javascript and has_unquoted_js_key(source) {
        raise ValueError("js_not_allowed");
    }
    body: str = source;
    if skip_comments {
        body = strip_comments_recursive(source);
    }
    gr = graph_for_text(body);
    wk = gr spawn JsonWalk(skip_comments=skip_comments, fail_on_javascript=fail_on_javascript);
    print len(wk.pieces);
    return decode_json_text(body);
}

