"""hyang0129/pyscope-mcp#57 — BFS shortest call chain between symbols."""

node CallGraph {
    has symbols: list[Symbol] = [];
}

node Symbol {
    has fqn: str;
}

edge Calls {}

def new_call_graph() -> CallGraph {
    return CallGraph();
}

def get_or_create(cg: CallGraph, fqn: str) -> Symbol {
    for s in cg.symbols {
        if s.fqn == fqn {
            return s;
        }
    }
    nd = Symbol(fqn=fqn);
    cg.symbols.append(nd);
    return nd;
}

def add_call(cg: CallGraph, src_fqn: str, dst_fqn: str) -> None {
    src_nd = get_or_create(cg, src_fqn);
    dst_nd = get_or_create(cg, dst_fqn);
    src_nd +>:Calls:+> dst_nd;
}

def find_symbol(cg: CallGraph, fqn: str) -> Symbol | None {
    for s in cg.symbols {
        if s.fqn == fqn {
            return s;
        }
    }
    return None;
}

def reconstruct_path(parent: dict[str, str | None], end_fqn: str) -> list[str] {
    rev: list[str] = [];
    cur: str | None = end_fqn;
    while cur is not None {
        rev.append(cur);
        nxt: str | None = None;
        if cur in parent {
            nxt = parent[cur];
        }
        cur = nxt;
    }
    out: list[str] = [];
    i = len(rev) - 1;
    while i >= 0 {
        out.append(rev[i]);
        i -= 1;
    }
    return out;
}

walker ChainWalker {
    has target: str;
    has max_depth: int;
    has claimed: dict[str, bool] = {};
    has depth: dict[str, int] = {};
    has parent: dict[str, str | None] = {};
    has result: list[str] | None = None;

    can step with Symbol entry {
        if here.fqn in self.claimed {
            skip;
        }
        self.claimed[here.fqn] = True;

        d: int = 0;
        if here.fqn in self.depth {
            d = self.depth[here.fqn];
        } else {
            self.depth[here.fqn] = 0;
            self.parent[here.fqn] = None;
        }

        if here.fqn == self.target {
            self.result = reconstruct_path(self.parent, here.fqn);
            print(self.result);
            disengage;
        }

        if d >= self.max_depth {
            disengage;
        }

        kids: list[Symbol] = [];
        for callee in [here ->:Calls:->][?:Symbol] {
            kids.append(callee);
        }

        next_visits: list[Symbol] = [];
        for kid in kids {
            if kid.fqn not in self.depth {
                self.depth[kid.fqn] = d + 1;
                self.parent[kid.fqn] = here.fqn;
                next_visits.append(kid);
            }
        }

        if next_visits {
            visit next_visits;
        } else {
            disengage;
        }
    }
}

def call_chain(
    cg: CallGraph, src_fqn: str, dst_fqn: str, max_depth: int = 6
) -> list[str] | None {
    src_nd = find_symbol(cg, src_fqn);
    dst_nd = find_symbol(cg, dst_fqn);
    if not src_nd {
        return None;
    }
    if not dst_nd {
        return None;
    }
    if src_fqn == dst_fqn {
        return [src_fqn];
    }
    w = src_nd spawn ChainWalker(target=dst_fqn, max_depth=max_depth);
    return w.result;
}
