    has rows_out: list[tuple[int, float]] = [];
    has limit_idx: int = 0;
    has rate: float = 1.0;

    can start with CTEAnchor entry {
        print("expand", here.name);
        seed_kids: list[Row] = [here ->:Derives:->][?:Row];
        for ch in seed_kids {
            visit :0: [ch];
        }
    }

    can grow with Row entry {
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        self.rows_out.append((here.idx, here.val));
        print("row", here.idx, here.val);
        if here.idx < self.limit_idx {
            nidx: int = here.idx + 1;
            nval: float = here.val * self.rate;
            ncid: str = "r-" + str(nidx);
            nxt = Row(idx=nidx, val=nval, cid=ncid);
            here +>:Derives:+> nxt;
            visit :0: [nxt];
        } else {
            disengage;
        }
    }
}

walker CollectRows {
    has claimed: dict[str, bool] = {};
    has rows_out: list[tuple[int, float]] = [];

    can begin with CTEAnchor entry {
        print("collect", here.name);
        kids: list[Row] = [here ->:Derives:->][?:Row];
        for ch in kids {
            visit :0: [ch];
        }
    }

    can take with Row entry {
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        self.rows_out.append((here.idx, here.val));
        print("seen", here.idx, here.val);
        kids: list[Row] = [here ->:Derives:->][?:Row];
        for ch in kids {
            visit :0: [ch];
        }
    }
}

def collect_cte_rows(anchor: CTEAnchor) -> list[tuple[int, float]] {
    root ++> anchor;
    w = anchor spawn CollectRows(claimed={}, rows_out=[]);
    out: list[tuple[int, float]] = w.rows_out;
    return out;
}

def growth_cte_rows(start_idx: int, start_val: float, rate: float, limit_idx: int) -> list[tuple[int, float]] {
    if limit_idx < start_idx {
        empty: list[tuple[int, float]] = [];
        return empty;
    }
    anchor = CTEAnchor(name="GrowthCTE", limit_idx=limit_idx, rate=rate);
    seed = Row(idx=start_idx, val=start_val, cid="r-" + str(start_idx));
    anchor +>:Derives:+> seed;
    root ++> anchor;
    w = anchor spawn ExpandGrowth(claimed={}, rows_out=[], limit_idx=limit_idx, rate=rate);
    out: list[tuple[int, float]] = w.rows_out;
    return out;
}

def growth_value_at(start_idx: int, start_val: float, rate: float, target_idx: int) -> float | None {
    if target_idx < start_idx {
        return None;
    }
    rows = growth_cte_rows(start_idx, start_val, rate, target_idx);
    for pair in rows {
        if pair[0] == target_idx {
            return pair[1];
        }
    }
    return None;
}

def growth_row_count(start_idx: int, start_val: float, rate: float, limit_idx: int) -> int {
    rows = growth_cte_rows(start_idx, start_val, rate, limit_idx);
    return len(rows);
}
