}

def _call_chain(
    hub: GraphHub,
    src_fqn: str,
    dst_fqn: str,
    max_depth: int
) -> tuple[list[str] | None, str | None] {
    if src_fqn == dst_fqn {
        return ([src_fqn], None);
    }
    if src_fqn not in hub.sym_map {
        return (None, "unknown src; try grep as fallback");
    }
    if dst_fqn not in hub.sym_map {
        return (None, "unknown dst; try grep as fallback");
    }
    dm: dict[str, int] = {};
    dm[src_fqn] = 0;
    src_nd = hub.sym_map[src_fqn];
    w = src_nd spawn BfsChain(
        target=dst_fqn,
        max_d=max_depth,
        start_fqn=src_fqn,
        depth_map=dm
    );
    if w.hit {
        return (w.result, None);
    }
    return (None, "no path found in static graph; try grep as fallback");
}
