        seed = st.index[sid];
        w = seed spawn CollectW(claimed={}, members=[], assigned=assigned);
        members_sorted: list[str] = sorted(w.members);
        out.append(members_sorted);
        for mid in members_sorted {
            assigned[mid] = True;
        }
    }
    return sorted(out);
