def parent_of_from_rows(flat_rows: list) -> dict[str, str | None] {
    pmap: dict[str, str | None] = {};
    for row in flat_rows {
        rid: str = row["cid"] as str;
        par: str | None = None;
        if "parentId" in row {
            val = row["parentId"];
            if val is not None {
                par = val as str;
            }
        }
        pmap[rid] = par;
    }
    return pmap;
}

def sort_by_cid(rows: list) -> list {
    ids: list = [];
    for r in rows {
        ids.append(r["cid"] as str);
    }
    ids = sorted(ids);
    out: list = [];
    for idv in ids {
        for r in rows {
            if (r["cid"] as str) == idv {
                out.append(r);
                break;
            }
        }
    }
    return out;
}

def validate_parent_for_post(post_id: str, parent_id: str | None, flat_rows: list) -> bool {
    if parent_id is None {
        return True;
    }
    by_id: dict[str, object] = index_rows(flat_rows);
    if parent_id not in by_id {
        return False;
    }
    prow: object = by_id[parent_id];
    return (prow["postId"] as str) == post_id;
}

def visual_level(cid: str, flat_rows: list, cap: int = 5) -> int {
    pmap: dict[str, str | None] = parent_of_from_rows(flat_rows);
    depth: int = 1;
    cur: str = cid;
    while True {
        par: str | None = pmap[cur];
        if par is None {
            break;
        }
        depth = depth + 1;
        if depth >= cap {
            return cap;
        }
        cur = par;
    }
    return depth;
}

def attach_children(node_row: object, children_of: dict[str, list]) -> object {
    cid: str = node_row["cid"] as str;
    built_kids: list = [];
    raw: list = children_of[cid] as list;
    sorted_raw: list = sort_by_cid(raw);
    for child in sorted_raw {
        built_kids.append(attach_children(child, children_of));
    }
    out: dict = {};
    out["cid"] = node_row["cid"];
    out["postId"] = node_row["postId"];
    out["parentId"] = node_row["parentId"];
    out["authorDisplayName"] = node_row["authorDisplayName"];
    out["body"] = node_row["body"];
    out["children"] = built_kids;
    return out;
}

def assemble_tree(flat_rows: list) -> list {
    pmap: dict[str, str | None] = parent_of_from_rows(flat_rows);
    children_of: dict[str, list] = {};
    roots: list = [];
    for row in flat_rows {
        children_of[row["cid"] as str] = [];
    }
    for row in flat_rows {
        cid: str = row["cid"] as str;
        par: str | None = pmap[cid];
        if par is None {
            roots.append(row);
        } else {
            bucket: list = children_of[par] as list;
            bucket.append(row);
            children_of[par] = bucket;
        }
    }
    sorted_roots: list = sort_by_cid(roots);
    tree: list = [];
    for root_row in sorted_roots {
        tree.append(attach_children(root_row, children_of));
    }
    return tree;
}

