        et: int = 0;
        if "elemtype" in spec {
            et = spec["elemtype"] as int;
        }
        if et != 0 and et in by_oid {
            src +>:ElemLink:+> by_oid[et];
        }
        attr_raw: list = [];
        if "attr_oids" in spec {
            attr_raw = spec["attr_oids"] as list;
        }
        for raw_a in attr_raw {
            aid: int = raw_a as int;
            if aid in by_oid {
                src +>:AttrLink:+> by_oid[aid];
            }
        }
    }
    return by_oid;
}

def expand_typeinfo_tree(catalog: dict, roots: list[int]) -> list[dict] {
    by_oid: dict[int, TypeEntry] = materialize_catalog(catalog);
    w = root spawn TypeinfoExpand(
        seed_oids=roots,
        by_oid=by_oid,
        claimed={},
        rows=[],
        depth=0
    );
    return w.rows;
}

def resolve_basetype_chain(catalog: dict, oid: int) -> int {
    by_oid: dict[int, TypeEntry] = materialize_catalog(catalog);
    if oid not in by_oid {
        return oid;
    }
    w = by_oid[oid] spawn BasetypeResolve(claimed={}, terminal=0);
    if w.terminal != 0 {
        return w.terminal;
    }
    return oid;
}

