obj DoublyLinkedList {
    has head: DllNode | None = None;
    has tail: DllNode | None = None;
    has length: int = 0;
    has anchor: ListAnchor | None = None;
    has seq: int = 0;

    def _node(self: DoublyLinkedList, data: int) -> DllNode {
        cid = "d" + str(self.seq);
        self.seq += 1;
        nd = DllNode(data=data, cid=cid);
        self.anchor ++> nd;
        return nd;
    }

    def append(self: DoublyLinkedList, data: int) -> None {
        nd = self._node(data);
        if self.head is None { self.head = nd; self.tail = nd; }
        else {
            self.tail +>:Fwd:+> nd;
            nd +>:Rev:+> self.tail;
            self.tail = nd;
        }
        self.length += 1;
    }

    def prepend(self: DoublyLinkedList, data: int) -> None {
        nd = self._node(data);
        if self.head is None { self.head = nd; self.tail = nd; }
        else {
            nd +>:Fwd:+> self.head;
            self.head +>:Rev:+> nd;
            self.head = nd;
        }
        self.length += 1;
    }

    def traverse_to_index(self: DoublyLinkedList, index: int) -> DllNode {
        if index < 0 or index >= self.length { raise IndexError("Index out of range"); }
        w = self.head spawn IndexWalk(target=index, claimed={});
        if w.out is None { raise IndexError("Index out of range"); }
        return w.out;
    }

    def insert_at(self: DoublyLinkedList, index: int, data: int) -> None {
        if index < 0 or index > self.length { raise IndexError("Index out of range"); }
        if index == 0 { self.prepend(data); return; }
        if index == self.length { self.append(data); return; }
        nd = self._node(data);
        leader = self.traverse_to_index(index - 1);
        follower: list[DllNode] = [leader ->:Fwd:->][?:DllNode];
        leader +>:Fwd:+> nd;
        nd +>:Rev:+> leader;
        if follower { nd +>:Fwd:+> follower[0]; follower[0] +>:Rev:+> nd; }
        self.length += 1;
    }

    def remove_at(self: DoublyLinkedList, index: int) -> None {
        if index < 0 or index >= self.length { raise IndexError("Index out of range"); }
        victim = self.traverse_to_index(index);
        prev_n: list[DllNode] = [victim ->:Rev:->][?:DllNode];
        next_n: list[DllNode] = [victim ->:Fwd:->][?:DllNode];
        if prev_n { prev_n[0] +>:Fwd:+> (next_n[0] if next_n else victim); }
        else { self.head = next_n[0] if next_n else None; }
        if next_n { next_n[0] +>:Rev:+> (prev_n[0] if prev_n else victim); }
        else { self.tail = prev_n[0] if prev_n else None; }
        self.length -= 1;
    }

    def print_list(self: DoublyLinkedList) -> None {
        if self.head is None { print("None"); print("Length: 0"); return; }
        w = self.head spawn CollectFwd(claimed={});
        out: list[str] = [];
        for v in w.items { out.append(str(v)); }
        print(" <-> ".join(out) + " <-> None");
        print("Length: " + str(self.length));
    }
}

obj HashTable {
    has size: int = 50;
    has anchor: HtAnchor | None = None;
    has buckets: list[Bucket] = [];

    def _hash(self: HashTable, key: str) -> int {
        h = 0;
        for i in range(len(key)) { h = (h * 31 + ord(key[i])) % self.size; }
        if h < 0 { h = -h; }
        return h % self.size;
    }

    def set(self: HashTable, key: str, value: str) -> None {
        bi = self._hash(key);
        b = self.buckets[bi];
        w = b spawn ChainFind(key=key, claimed={});
        if w.found is not None { w.found.val = value; return; }
        e = Entry(key=key, val=value, cid="e_" + key + "_" + str(bi));
        kids: list[Entry] = [b ->:Chain:->][?:Entry];
        if not kids { b +>:Chain:+> e; return; }
        tail = kids[0];
        nxt: list[Entry] = [tail ->:Chain:->][?:Entry];
        while nxt { tail = nxt[0]; nxt = [tail ->:Chain:->][?:Entry]; }
        tail +>:Chain:+> e;
    }

    def get(self: HashTable, key: str) -> str {
        bi = self._hash(key);
        w = self.buckets[bi] spawn ChainFind(key=key, claimed={});
        if w.found is None { raise KeyError(key); }
        return w.found.val;
    }

    def delete(self: HashTable, key: str) -> None {
        bi = self._hash(key);
        b = self.buckets[bi];
        w = b spawn ChainFind(key=key, claimed={});
        if w.found is None { raise KeyError(key); }
        prev_e: list[Entry] = [w.found ->:Rev:->][?:Entry];
        next_e: list[Entry] = [w.found ->:Chain:->][?:Entry];
        if prev_e { prev_e[0] +>:Chain:+> (next_e[0] if next_e else w.found); }
        else if next_e { b +>:Chain:+> next_e[0]; }
    }
}

def DoublyLinkedList() -> DoublyLinkedList {
    la = ListAnchor();
    root ++> la;
    return DoublyLinkedList(anchor=la);
}

def HashTable(size: int = 50) -> HashTable {
    ha = HtAnchor();
    root ++> ha;
    ht = HashTable(size=size, anchor=ha);
    i = 0;
    while i < size {
        bk = Bucket(idx=i, cid="b" + str(i));
        ha +>:Chain:+> bk;
        ht.buckets.append(bk);
        i += 1;
    }
    return ht;
}

def dll_values(dll: DoublyLinkedList) -> list[int] {
    if dll.head is None { return []; }
    w = dll.head spawn CollectFwd(claimed={});
    return w.items;
}
