"""
crate/crate-clients-tools#52 - Replace asyncpg recursive typeinfo CTE with OSP walks.
"""

node TypeRec {
    has oid: int;
    has ns: str;
    has name: str;
    has kind: str;
    has basetype: int = 0;
    has elemtype: int = 0;
    has depth: int = 0;
}

edge TypeDep {}
edge BasetypeEdge {}

def catalog_entry(
    ns: str,
    name: str,
    kind: str,
    basetype: int,
    elemtype: int
) -> dict[str, any] {
    meta: dict[str, any] = {};
    meta["ns"] = ns;
    meta["name"] = name;
    meta["kind"] = kind;
    meta["basetype"] = basetype;
    meta["elemtype"] = elemtype;
    return meta;
}

def materialize_catalog(catalog: dict[int, dict[str, any]]) -> dict[int, TypeRec] {
    by_oid: dict[int, TypeRec] = {};
    for oid in catalog {
        meta = catalog[oid] as dict[str, any];
        rec = TypeRec(
            oid=oid,
            ns=meta["ns"],
            name=meta["name"],
            kind=meta["kind"],
            basetype=meta["basetype"],
            elemtype=meta["elemtype"]
        );
        by_oid[oid] = rec;
    }
    for oid in by_oid {
        rec = by_oid[oid] as TypeRec;
        root ++> rec;
        if rec.basetype != 0 and rec.basetype in by_oid {
            base = by_oid[rec.basetype] as TypeRec;
            rec +>:BasetypeEdge:+> base;
            rec +>:TypeDep:+> base;
        }
        if rec.elemtype != 0 and rec.elemtype in by_oid {
            elem = by_oid[rec.elemtype] as TypeRec;
            rec +>:TypeDep:+> elem;
        }
    }
    return by_oid;
}

walker TypeTreeWalker {
    has claimed: dict[int, bool] = {};
    has found: list[dict] = [];
    can step with TypeRec entry {
        if here.oid in self.claimed {
            skip;
        }
        self.claimed[here.oid] = True;
        row: dict = {};
        row["oid"] = here.oid;
        row["ns"] = here.ns;
        row["name"] = here.name;
        row["kind"] = here.kind;
        row["basetype"] = here.basetype;
        row["elemtype"] = here.elemtype;
        row["depth"] = here.depth;
        self.found.append(row);
        kids: list[TypeRec] = [];
        for ch in [here ->:TypeDep:->][?:TypeRec] {
            ch.depth = here.depth + 1;
            kids.append(ch);
        }
        visit :0: kids else {
            disengage;
        }
    }
}

walker BasetypeWalker {
    has claimed: dict[int, bool] = {};
    has terminal: int = 0;
    can resolve with TypeRec entry {
        if here.oid in self.claimed {
            skip;
        }
        self.claimed[here.oid] = True;
        self.terminal = here.oid;
        kids: list[TypeRec] = [];
        for ch in [here ->:BasetypeEdge:->][?:TypeRec] {
            kids.append(ch);
        }
        visit :0: kids else {
            disengage;
        }
    }
}

def collect_typeinfo_tree(
    seed_oids: list[int],
    by_oid: dict[int, TypeRec]
) -> list[dict] {
    merged: list[dict] = [];
    seen: dict[int, bool] = {};
    for soid in seed_oids {
        if soid not in by_oid {
            continue;
        }
        start = by_oid[soid] as TypeRec;
        start.depth = 0;
        w = start spawn TypeTreeWalker(claimed={}, found=[]);
        for row in w.found {
            roid = row["oid"];
            if roid not in seen {
                seen[roid] = True;
                merged.append(row);
            }
        }
    }
    return merged;
}

def resolve_basetype(oid: int, by_oid: dict[int, TypeRec]) -> int {
    if oid not in by_oid {
        return 0;
    }
    start = by_oid[oid] as TypeRec;
    w = start spawn BasetypeWalker(claimed={}, terminal=0);
    if w.terminal != 0 {
        return w.terminal;
    }
    return oid;
}

def float_array_seed_chain(catalog: dict[int, dict[str, any]]) -> list[int] {
    by_oid = materialize_catalog(catalog);
    rows = collect_typeinfo_tree([1021], by_oid);
    oids: list[int] = [];
    for row in rows {
        oids.append(row["oid"]);
    }
    return sorted(oids);
}

