obj DoublyLinkedList {
    has anchor: ListAnchor;

    def _head(self: DoublyLinkedList) -> Elem | None {
        hs: list[Elem] = [self.anchor ->:Next:->][?:Elem];
        if hs { return hs[0]; }
        return None;
    }

    def append(self: DoublyLinkedList, data: int) {
        e = Elem(data=data);
        hd: Elem | None = self._head();
        if not hd {
            self.anchor +>:Next:+> e;
            self.anchor.tail = e;
        } else {
            t = self.anchor.tail;
            if t {
                t +>:Next:+> e;
                e +>:Prev:+> t;
                self.anchor.tail = e;
            }
        }
        self.anchor.length += 1;
    }

    def prepend(self: DoublyLinkedList, data: int) {
        e = Elem(data=data);
        hd: Elem | None = self._head();
        if not hd {
            self.anchor +>:Next:+> e;
            self.anchor.tail = e;
        } else {
            e +>:Next:+> hd;
            hd +>:Prev:+> e;
            self.anchor +>:Next:+> e;
        }
        self.anchor.length += 1;
    }

    def traverse_to_index(self: DoublyLinkedList, index: int) -> Elem {
        if index < 0 or index >= self.anchor.length {
            raise IndexError("Index out of range");
        }
        cur: Elem | None = self._head();
        counter: int = 0;
        while counter != index {
            if not cur { raise IndexError("Index out of range"); }
            nxs: list[Elem] = [cur ->:Next:->][?:Elem];
            if nxs { cur = nxs[0]; } else { cur = None; }
            counter += 1;
        }
        if not cur { raise IndexError("Index out of range"); }
        return cur;
    }

    def insert_at(self: DoublyLinkedList, index: int, data: int) {
        if index < 0 or index > self.anchor.length {
            raise IndexError("Index out of range");
        }
        if index == 0 { self.prepend(data); return; }
        if index == self.anchor.length { self.append(data); return; }
        new_e = Elem(data=data);
        leader = self.traverse_to_index(index - 1);
        fols: list[Elem] = [leader ->:Next:->][?:Elem];
        follower = fols[0];
        leader +>:Next:+> new_e;
        new_e +>:Prev:+> leader;
        new_e +>:Next:+> follower;
        follower +>:Prev:+> new_e;
        self.anchor.length += 1;
    }

    def remove_at(self: DoublyLinkedList, index: int) {
        if index < 0 or index >= self.anchor.length {
            raise IndexError("Index out of range");
        }
        if index == 0 {
            hd: Elem | None = self._head();
            if hd {
                nxs: list[Elem] = [hd ->:Next:->][?:Elem];
                if nxs {
                    self.anchor +>:Next:+> nxs[0];
                    nxs[0] +>:Prev:+> self.anchor;
                    if self.anchor.length == 1 { self.anchor.tail = None; }
                } else {
                    self.anchor.tail = None;
                }
            }
        } elif index == self.anchor.length - 1 {
            t = self.anchor.tail;
            if t {
                prs: list[Elem] = [t ->:Prev:->][?:Elem];
                if prs {
                    prs[0] +>:Next:+> t;
                    self.anchor.tail = prs[0];
                } else {
                    self.anchor.tail = None;
                }
            }
        } else {
            leader = self.traverse_to_index(index - 1);
            unp: list[Elem] = [leader ->:Next:->][?:Elem];
            unwanted = unp[0];
            fols: list[Elem] = [unwanted ->:Next:->][?:Elem];
            follower = fols[0];
            leader +>:Next:+> follower;
            follower +>:Prev:+> leader;
        }
        self.anchor.length -= 1;
    }

    def to_list(self: DoublyLinkedList) -> list[int] {
        w = self.anchor spawn ListCollectWalker(claimed={});
        return w.vals;
    }

    def print_list(self: DoublyLinkedList) {
        vals = self.to_list();
        i: int = 0;
        while i < len(vals) {
            if i > 0 { print " <-> "; }
            print vals[i];
            i += 1;
        }
        print " <-> None";
        print "Length: " + str(self.anchor.length);
    }
}

obj HashTable {
    has size: int;
    has buckets: list[list[tuple[str, int]]];

    def _hash(self: HashTable, key: str) -> int {
        return hash(key) % self.size;
    }

    def set(self: HashTable, key: str, value: int) {
        bi = self._hash(key);
        b = self.buckets[bi];
        i: int = 0;
        while i < len(b) {
            pair = b[i];
            if pair[0] == key {
                b[i] = (key, value);
                return;
            }
            i += 1;
        }
        b.append((key, value));
    }

    def get(self: HashTable, key: str) -> int {
        bi = self._hash(key);
        b = self.buckets[bi];
        i: int = 0;
        while i < len(b) {
            pair = b[i];
            if pair[0] == key { return pair[1]; }
            i += 1;
        }
        raise KeyError(key);
    }

    def delete(self: HashTable, key: str) {
        bi = self._hash(key);
        b = self.buckets[bi];
        i: int = 0;
        while i < len(b) {
            pair = b[i];
            if pair[0] == key {
                b.pop(i);
                return;
            }
            i += 1;
        }
        raise KeyError(key);
    }

    def __str__(self: HashTable) -> str {
        return str(self.buckets);
    }
}

