def insert_at_cursor(field: UINode, character: str) -> tuple[str, int] {
    pos: int = field.cursor;
    txt: str = field.content;
    if pos < 0 {
        pos = 0;
    }
    if pos > len(txt) {
        pos = len(txt);
    }
    left: str = txt[:pos];
    right: str = txt[pos:];
    field.content = left + character + right;
    field.cursor = pos + 1;
    return (field.content, field.cursor);
}

def set_text_content(field: UINode, text: str) -> None {
    field.content = text;
}

def bring_to_front(window: UINode, next_z: int, overlay_threshold: int) -> tuple[int, bool] {
    window.z_order = next_z;
    nz: int = next_z + 1;
    escaped: bool = False;
    if window.z_order >= overlay_threshold {
        escaped = True;
    }
    return (nz, escaped);
}

def safe_local_z(z: int, overlay_threshold: int, base: int) -> int {
    span: int = overlay_threshold - base;
    if span <= 0 {
        return base;
    }
    rem: int = z % span;
    return base + rem;
}

