def build_cte_graph(specs: list[dict]) -> dict[str, list[str]] {
  graph: dict[str, list[str]] = {};
  for sp in specs {
    nm = sp["name"] as str;
    refs: list[str] = [];
    if "refs" in sp {
      raw = sp["refs"];
      for r in raw {
        refs.append(r as str);
      }
    }
    graph[nm] = refs;
  }
  return graph;
}

def validate_recursive_cte(
  cte_name: str,
  anchor_refs: list[str],
  recursive_refs: list[str]
) -> list[str] {
  errors: list[str] = [];
  found_self = False;
  for rr in recursive_refs {
    if rr == cte_name {
      found_self = True;
    }
  }
  if not found_self {
    errors.append("missing_recursive_self_ref");
  }
  for ar in anchor_refs {
    if ar == cte_name {
      errors.append("anchor_self_ref");
    }
  }
  errors.sort();
  return errors;
}

def _registry_from_graph(graph: dict[str, list[str]]) -> dict[str, Cte] {
  registry: dict[str, Cte] = {};
  keys: list[str] = [];
  for k in graph {
    keys.append(k);
  }
  keys.sort();
  for nm in keys {
    nd = Cte(name=nm);
    root ++> nd;
    registry[nm] = nd;
  }
  for src_nm in keys {
    src = registry[src_nm];
    refs = graph[src_nm];
    for r in refs {
      if r in registry {
        tgt = registry[r];
        src +>:CteRef:+> tgt;
      }
    }
  }
  return registry;
}

def closure_from_graph(graph: dict[str, list[str]], seed: str) -> list[str] {
  if seed not in graph {
    return [];
  }
  registry = _registry_from_graph(graph);
  start = registry[seed];
  w = start spawn CollectRefs(claimed={});
  out: list[str] = [];
  for nm in w.collected {
    out.append(nm);
  }
  out.sort();
  return out;
}

