  for c in ctes {
    specs.append(c);
    if "recursive" in c and (c["recursive"] as bool) {
      recursive_names.append(c["name"] as str);
    }
  }
  graph = build_cte_graph(specs);
  for c in ctes {
    nm = c["name"] as str;
    if "recursive" in c and (c["recursive"] as bool) {
      anchor: list[str] = [];
      recur: list[str] = [];
      if "anchor_refs" in c {
        for a in c["anchor_refs"] {
