        }
      }
    }
  }
  errors.sort();
  order: list[str] = [];
  for k in graph {
    order.append(k);
  }
  order.sort();
  result: dict = {};
  result["model"] = model_name;
  result["errors"] = errors;
  result["compile_order"] = order;
  result["recursive"] = recursive_names;
