    node0: Dir | File = store[root_id];
    if node0 is File {
        if max_depth >= 0 {
            f0: File = node0 as File;
            return [f0.name];
        }
        return [];
    }
    paths: list[str] = [];
    claimed: dict[str, bool] = {};
