def remove_subtree(store: dict[str, Dir | File], node_id: str) -> bool {
    if node_id not in store {
        return False;
    }
    ids: list[str] = [];
    claimed: dict[str, bool] = {};
    with entry {
        root spawn SubtreeGather(
            gather_from=node_id,
            claimed=claimed,
            active=False,
            ids=ids
        );
    }
    fresh: dict[str, Dir | File] = {};
    for key in store {
        drop: bool = False;
        for gid in ids {
            if key == gid {
                drop = True;
            }
        }
        if not drop {
            fresh[key] = store[key];
        }
    }
    for key in store {
        del store[key];
    }
    for key in fresh {
        store[key] = fresh[key];
    }
    return True;
}
