def build_nested(root_id: str, by_id: dict[str, Comment], child_ids: dict[str, list[str]]) -> list[dict] {
    if root_id not in child_ids { return []; }
    out: list[dict] = [];
    for cid in child_ids[root_id] {
        if cid not in by_id { continue; }
        c = by_id[cid];
        nested: list[dict] = build_nested(cid, by_id, child_ids);
        out.append(comment_to_dict(c, nested));
    }
    return out;
}

def build_comment_graph(records: list) -> CommentGraph {
    g = CommentGraph();
    by_id: dict[str, Comment] = {};
    for rec in records {
        pid: str = record_parent_id(rec);
        c = Comment(
            id=str(rec["id"]),
            body=str(rec["body"]),
            content_id=str(rec["content_id"]),
            parent_id=pid,
            author=str(rec["author"]),
            created_at=str(rec["created_at"])
        );
        by_id[c.id] = c;
    }
    for rec in records {
        pid: str = record_parent_id(rec);
        cid: str = str(rec["id"]);
        if pid != "" && pid in by_id && cid in by_id {
            by_id[pid] +>:Reply:+> by_id[cid];
        }
    }
    g.by_id = by_id;
    return g;
}

def get_replies(graph: CommentGraph, parent_id: str, max_depth: int = 10) -> list[dict] {
    if parent_id not in graph.by_id { return []; }
    parent = graph.by_id[parent_id];
    claimed: dict[str, bool] = {};
    w = parent spawn LoadSubtree(claimed=claimed, max_depth=max_depth, start_depth=0);
    return build_nested(parent_id, graph.by_id, w.child_ids);
}

def get_by_content_id(graph: CommentGraph, content_id: str, max_depth: int = 10) -> list[dict] {
    roots: list[Comment] = [];
    for cid in graph.by_id {
        c = graph.by_id[cid];
        if c.content_id == content_id && c.parent_id == "" { roots.append(c); }
    }
    roots = sort_comments_by_created(roots);
    out: list[dict] = [];
    for r in roots {
        claimed: dict[str, bool] = {};
        w = r spawn LoadSubtree(claimed=claimed, max_depth=max_depth, start_depth=0);
        nested: list[dict] = build_nested(r.id, graph.by_id, w.child_ids);
        out.append(comment_to_dict(r, nested));
    }
    return out;
}
