# devstein/langchain#21 — recursive REPL scope binding lifted to OSP.

node ReplScope {
    has shared: bool = False;
    has bound: bool = False;
    has last_events: list[str] = [];
    has last_pairs: list[list[int]] = [];
}

node CallSite {
    has fn_name: str;
    has n: int;
    has cid: str;
}

node Tag {
    has cid: str;
    has label: str;
}

edge Invoke {}
edge Next {}

walker CollectCalls {
    has claimed: dict[str, bool] = {};
    has events: list[str] = [];
    has pairs: list[list[int]] = [];

    can expand with CallSite entry {
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        self.events.append(here.cid);
        print(here.cid);
        if here.n <= 1 {
            # base frame
        } else {
            left_id = f"{here.fn_name}:{here.n - 1}:L:{here.cid}";
            right_id = f"{here.fn_name}:{here.n - 2}:R:{here.cid}";
            left = CallSite(fn_name=here.fn_name, n=here.n - 1, cid=left_id);
            right = CallSite(fn_name=here.fn_name, n=here.n - 2, cid=right_id);
            root ++> left;
            root ++> right;
            left +>:Invoke:+> here;
            right +>:Invoke:+> here;
            pair_l: list[int] = [];
            pair_l.append(here.n - 1);
            pair_l.append(here.n);
            self.pairs.append(pair_l);
            pair_r: list[int] = [];
            pair_r.append(here.n - 2);
            pair_r.append(here.n);
            self.pairs.append(pair_r);
            kids: list[CallSite] = [];
            kids.append(left);
            kids.append(right);
            visit :0: kids else {
                disengage;
            }
        }
    }
}

walker ProbeDiamond {
    has claimed: dict[str, bool] = {};
    has order: list[str] = [];

    can walk_tag with Tag entry {
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        self.order.append(here.label);
        print(here.label);
        nxt: list[Tag] = [here ->:Next:->][?:Tag];
        if nxt {
            visit :0: nxt else {
                disengage;
            }
        } else {
            disengage;
        }
    }
}

def _fib_iter(n: int) -> int {
    memo: dict[int, int] = {};
    i = 0;
    while i <= n {
        if i <= 1 {
            memo[i] = i;
        } else {
            memo[i] = memo[i - 1] + memo[i - 2];
        }
        i += 1;
    }
    return memo[n];
}

def make_scope(shared: bool = False) -> ReplScope {
    sc = ReplScope(shared=shared);
    root ++> sc;
    return sc;
}

def execute_recursive(scope: ReplScope, fn_name: str, n: int) -> int {
    if fn_name != "fibonacci" {
        return 0;
    }
    if not scope.shared {
        raise NameError("fibonacci");
    }
    scope.bound = True;
    root_site = CallSite(fn_name=fn_name, n=n, cid=f"{fn_name}:{n}:root");
    root ++> root_site;
    w = root_site spawn CollectCalls(claimed={});
    scope.last_events = [];
    for ev in w.events {
        scope.last_events.append(ev);
    }
    scope.last_pairs = [];
    for pr in w.pairs {
        scope.last_pairs.append(pr);
    }
    return _fib_iter(n);
}

def reference_fib(n: int) -> int {
    return _fib_iter(n);
}

def resolve_fn(scope: ReplScope, fn_name: str) -> str {
    if fn_name == "fibonacci" and scope.shared {
        return "fibonacci";
    }
    return "";
}

def reaction_trace(scope: ReplScope, n: int) -> list[str] {
    execute_recursive(scope, "fibonacci", n);
    return sorted(scope.last_events);
}

def closure_pairs(n: int) -> list[list[int]] {
    scope = make_scope(shared=True);
    execute_recursive(scope, "fibonacci", n);
    return sorted(scope.last_pairs);
}

def probe_diamond() -> list[str] {
    a = Tag(cid="A", label="A");
    b = Tag(cid="B", label="B");
    c = Tag(cid="C", label="C");
    d = Tag(cid="D", label="D");
    root ++> a;
    a +>:Next:+> b;
    a +>:Next:+> c;
    b +>:Next:+> d;
    c +>:Next:+> d;
    w = a spawn ProbeDiamond(claimed={});
    return w.order;
}
