"""Mutual-recursion parity reachability — swarm-game/swarm#605 letrec bindings."""

node Cell {
    has cid: str;
}

edge Next {}

edge Alt {}

walker CellLookup {
    has target: str;
    has claimed: dict[str, bool] = {};
    has found: bool = False;
    has node_ref: Cell | None = None;

    can seek with Cell entry {
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        if here.cid == self.target {
            self.found = True;
            self.node_ref = here;
            print(here.cid);
            disengage;
        }
        kids: list[Cell] = [];
        for ch in [here -->][?:Cell] {
            kids.append(ch);
        }
        visit :0: kids else {
            disengage;
        }
    }
}

walker EvenWalk {
    has labels: dict[str, str] = {};
    has claimed: dict[str, bool] = {};

    can mark_even with Cell entry {
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        self.labels[here.cid] = "even";
        print(here.cid);
        kids: list[Cell] = [];
        for ch in [here ->:Next:->][?:Cell] {
            kids.append(ch);
        }
        for ch in [here ->:Alt:->][?:Cell] {
            kids.append(ch);
        }
        for ch in kids {
            ch spawn OddWalk(labels=self.labels, claimed=self.claimed);
        }
        disengage;
    }
}

walker OddWalk {
    has labels: dict[str, str] = {};
    has claimed: dict[str, bool] = {};

    can mark_odd with Cell entry {
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        self.labels[here.cid] = "odd";
        print(here.cid);
        kids: list[Cell] = [];
        for ch in [here ->:Next:->][?:Cell] {
            kids.append(ch);
        }
        for ch in [here ->:Alt:->][?:Cell] {
            kids.append(ch);
        }
        for ch in kids {
            ch spawn EvenWalk(labels=self.labels, claimed=self.claimed);
        }
        disengage;
    }
}

def lookup_cell(cid: str) -> Cell | None {
    w = root spawn CellLookup(target=cid, claimed={});
    if w.found {
        return w.node_ref;
    }
    return None;
}

def make_line_graph(length: int) -> str {
    if length <= 0 {
        return "";
    }
    first = Cell(cid="n0");
    root ++> first;
    prev = first;
    i = 1;
    while i < length {
        nd = Cell(cid="n" + str(i));
        root ++> nd;
        prev +>:Next:+> nd;
        prev = nd;
        i += 1;
    }
    return first.cid;
}

def make_diamond_cycle() -> str {
    r = Cell(cid="r");
    a = Cell(cid="a");
    b = Cell(cid="b");
    t = Cell(cid="t");
    root ++> r;
    root ++> a;
    root ++> b;
    root ++> t;
    r +>:Next:+> a;
    r +>:Next:+> b;
    a +>:Next:+> b;
    a +>:Alt:+> t;
    b +>:Alt:+> t;
    return r.cid;
}

def parities_from(root_cid: str) -> dict[str, str] {
    nd = lookup_cell(root_cid);
    if not nd {
        labs: dict[str, str] = {};
        return labs;
    }
    labels: dict[str, str] = {};
    claimed: dict[str, bool] = {};
    w = nd spawn EvenWalk(labels=labels, claimed=claimed);
    print(w.labels);
    return labels;
}

def parity_from(root_cid: str, target_cid: str) -> str {
    labs = parities_from(root_cid);
    if target_cid in labs {
        return labs[target_cid];
    }
    return "unknown";
}
