            while idx >= 0 {
                visit :0: [kids[idx]];
                idx -= 1;
            }
        } else {
            disengage;
        }
    }
}

def fib_cid(func: str, n: int, branch: str, parent_cid: str) -> str {
    if parent_cid == "" {
        return func + ":" + str(n) + ":" + branch;
    }
    return func + ":" + str(n) + ":" + branch + ":" + parent_cid;
}

def attach_fib_children(here: Call) -> None {
    if here.n <= 1 {
        return;
    }
    left_n = here.n - 1;
    right_n = here.n - 2;
    left_cid = fib_cid("fibonacci", left_n, "L", here.cid);
    right_cid = fib_cid("fibonacci", right_n, "R", here.cid);
    left_nd = Call(cid=left_cid, func="fibonacci", n=left_n, branch="L");
    right_nd = Call(cid=right_cid, func="fibonacci", n=right_n, branch="R");
    root ++> left_nd;
    root ++> right_nd;
    here +>:Calls:+> left_nd;
    here +>:Calls:+> right_nd;
    attach_fib_children(left_nd);
    attach_fib_children(right_nd);
}

def build_fib_root(n: int) -> Call {
    root_cid = fib_cid("fibonacci", n, "root", "");
    root_nd = Call(cid=root_cid, func="fibonacci", n=n, branch="root");
    root ++> root_nd;
    attach_fib_children(root_nd);
    return root_nd;
}

def pair_sort_key(row: list[str]) -> str {
    return row[0] + "\t" + row[1];
}

def sort_pair_rows(rows: list[list[str]]) -> list[list[str]] {
    keys: list[str] = [];
    for row in rows {
        keys.append(pair_sort_key(row));
    }
    keys = sorted(keys);
    out: list[list[str]] = [];
    for key in keys {
        parts: list[str] = key.split("\t");
        out.append([parts[0], parts[1]]);
    }
    return out;
}

def collect_closure_pairs(here: Call, pairs: list[list[str]]) -> None {
    kids: list[Call] = [here ->:Calls:->][?:Call];
    for kid in kids {
        row: list[str] = [here.cid, kid.cid];
        pairs.append(row);
        collect_closure_pairs(kid, pairs);
    }
}

def closure_pairs(n: int) -> list[list[str]] {
    root_nd = build_fib_root(n);
    pairs: list[list[str]] = [];
    collect_closure_pairs(root_nd, pairs);
    return sort_pair_rows(pairs);
}

def trace_call_lines(n: int) -> list[str] {
    root_nd = build_fib_root(n);
    w = root_nd spawn FibTrace(claimed={}, lines=[]);
    return w.lines;
}

def frame_by_cid(root_nd: Call, target: str) -> Call | None {
    if root_nd.cid == target {
        return root_nd;
    }
    kids: list[Call] = [root_nd ->:Calls:->][?:Call];
    for kid in kids {
        hit = frame_by_cid(kid, target);
        if hit != None {
            return hit;
        }
    }
    return None;
}

def parent_closure(n: int, cid: str) -> str {
    root_nd = build_fib_root(n);
    frame = frame_by_cid(root_nd, cid);
    if frame == None {
        return "";
    }
    parent_cid: str = "";
    if frame.branch == "root" {
        return "";
    }
    parts: list[str] = frame.cid.split(":");
    tail: list[str] = [];
    idx = 3;
    while idx < len(parts) {
        tail.append(parts[idx]);
        idx += 1;
    }
    j = 0;
    while j < len(tail) {
        if j > 0 {
            parent_cid = parent_cid + ":";
        }
        parent_cid = parent_cid + tail[j];
        j += 1;
    }
    return parent_cid;
}

def build_diamond_root() -> Call {
    a = Call(cid="scope:a", func="scope", n=1, branch="root");
    b = Call(cid="scope:b:L:scope:a", func="scope", n=2, branch="L");
    c = Call(cid="scope:c:R:scope:a", func="scope", n=2, branch="R");
    d = Call(cid="scope:d:B:scope:b:L:scope:a", func="scope", n=3, branch="B");
    d2 = Call(cid="scope:d:C:scope:c:R:scope:a", func="scope", n=3, branch="C");
    root ++> a;
    root ++> b;
    root ++> c;
    root ++> d;
    root ++> d2;
    a +>:Calls:+> b;
    a +>:Calls:+> c;
    b +>:Calls:+> d;
    c +>:Calls:+> d2;
    return a;
}

def diamond_trace_lines() -> list[str] {
    graph_root = build_diamond_root();
    w = graph_root spawn DiamondTrace(claimed={}, lines=[]);
    return w.lines;
}

