    return n.after_calls;
}

def _record_after_validator(here: ValNode, ctx: ValidateCtx) {
    ctx.after_count += 1;
    here.after_calls += 1;
    ctx.log.append("validator called");
}

walker AfterValWalk {
    has ctx: ValidateCtx;
    has claimed: dict[str, bool] = {};

    can step with ValNode entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        _record_after_validator(here, self.ctx);
        kids: list[ValNode] = [];
        for ch in [here ->:ChildEdge:->][?:ValNode] { kids.append(ch); }
        visit :0: kids else { disengage; }
    }
}

walker PrebuiltPassWalk {
    has ctx: ValidateCtx;
    has claimed: dict[str, bool] = {};

    can step with ValNode entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        _record_after_validator(here, self.ctx);
        kids: list[ValNode] = [];
        for ch in [here ->:ChildEdge:->][?:ValNode] { kids.append(ch); }
        visit :0: kids else { disengage; }
    }
}

def _run_after_validators(graph_root: ValNode, ctx: ValidateCtx) {
    graph_root spawn AfterValWalk(ctx=ctx);
    graph_root spawn PrebuiltPassWalk(ctx=ctx);
}

def _val_node_from_payload(payload: dict, prefix: str) -> ValNode {
    nd = ValNode(cid=prefix);
    if "child" in payload {
        child_payload: dict = payload["child"] as dict;
        kid = _val_node_from_payload(child_payload, prefix + ":child");
        nd +>:ChildEdge:+> kid;
    }
    return nd;
}

def model_validate_node(payload: dict, ctx: ValidateCtx) -> ValNode {
    nd = _val_node_from_payload(payload, "node");
    _run_after_validators(nd, ctx);
    return nd;
}

def model_validate_outer(payload: dict, ctx: ValidateCtx) -> ValNode {
    inner_payload: dict = {};
    if "node" in payload {
        inner_payload = payload["node"] as dict;
    }
    nd = _val_node_from_payload(inner_payload, "outer:node");
    _run_after_validators(nd, ctx);
    return nd;
}

def _make_diamond_graph() -> ValNode {
    a = ValNode(cid="a");
    b = ValNode(cid="b");
    c = ValNode(cid="c");
    d = ValNode(cid="d");
    a +>:ChildEdge:+> b;
    a +>:ChildEdge:+> c;
    b +>:ChildEdge:+> d;
    c +>:ChildEdge:+> d;
    return a;
}

walker FindValWalk {
    has target: str;
    has found: ValNode | None = None;
    has claimed: dict[str, bool] = {};

    can step with ValNode entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        if here.cid == self.target {
            self.found = here;
            disengage;
        }
        kids: list[ValNode] = [];
        for ch in [here ->:ChildEdge:->][?:ValNode] { kids.append(ch); }
        visit :0: kids else { disengage; }
    }
}

def find_val_by_cid(graph_root: ValNode, target: str) -> ValNode | None {
    w = graph_root spawn FindValWalk(target=target);
    return w.found;
}

walker DemoWalk {
    has ctx: ValidateCtx;

    can start with Root entry {
        payload: dict = {};
        inner: dict = {};
        payload["node"] = inner;
        model_validate_outer(payload, self.ctx);
        print("after_count=" + str(after_validator_call_count(self.ctx)));
        disengage;
    }
}

with entry {
