"""
Payment dependency cycle detection — Stellar-split/split-sdk#644.
Lift: recursive DFS call-stack -> OSP walker with explicit visit stack (DFS via visit :0:).
"""

node PayNode {
    has nid: str;
}

edge Dep {}

walker CycleWalker {
    has visiting: dict[str, bool] = {};
    has visited: dict[str, bool] = {};
    has cycle_found: bool = False;

    can probe with PayNode entry {
        if self.cycle_found {
            disengage;
        }
        if here.nid in self.visiting and self.visiting[here.nid] {
            self.cycle_found = True;
            print("cycle:", here.nid);
            disengage;
        }
        if here.nid in self.visited and self.visited[here.nid] {
            skip;
        }
        self.visiting[here.nid] = True;
        kids: list[PayNode] = [here ->:Dep:->][?:PayNode];
        kid_nids: list[str] = [];
        for ch in kids {
            kid_nids.append(ch.nid);
        }
        ordered: list[str] = sorted(kid_nids);
        for want in ordered {
            for ch in kids {
                if ch.nid == want {
                    visit :0: [ch];
                }
            }
        }
        self.visiting[here.nid] = False;
        self.visited[here.nid] = True;
        print("visit:", here.nid);
    }
}

def build_payment_graph(graph: dict[str, list[str]]) -> dict[str, PayNode] {
    nodes: dict[str, PayNode] = {};
    keys: list[str] = [];
    for k in graph {
        keys.append(k);
    }
    ordered: list[str] = sorted(keys);
    for k in ordered {
        nd = PayNode(nid=k);
        nodes[k] = nd;
        root ++> nd;
    }
    for src in ordered {
        src_nd = nodes[src] as PayNode;
        deps: list[str] = graph[src];
        for dep in deps {
            if dep in nodes {
                tgt = nodes[dep] as PayNode;
                src_nd +>:Dep:+> tgt;
            }
        }
    }
    return nodes;
}

def detect_cycle(graph: dict[str, list[str]]) -> bool {
    if len(graph) == 0 {
        print(False);
        return False;
    }
    nodes = build_payment_graph(graph);
    visiting: dict[str, bool] = {};
    visited: dict[str, bool] = {};
    cycle_found: bool = False;
    keys: list[str] = [];
    for k in graph {
        keys.append(k);
    }
    starts: list[str] = sorted(keys);
    for start_k in starts {
        if cycle_found {
            break;
        }
        if start_k in visited and visited[start_k] {
            continue;
        }
        start_nd = nodes[start_k] as PayNode;
        w = start_nd spawn CycleWalker(visiting=visiting, visited=visited, cycle_found=cycle_found);
        visiting = w.visiting;
        visited = w.visited;
        cycle_found = w.cycle_found;
    }
    print(cycle_found);
    return cycle_found;
}
