# Stellar-split/split-sdk#644 — iterative DFS cycle detection (OSP lift)

node PaymentNode {
    has cid: str;
}

edge Depends {}

obj CycleState {
    has black: dict[str, bool] = {};
    has found: bool = False;
}

obj PaymentGraph {
    has nodes_by_id: dict[str, PaymentNode] = {};
    has node_list: list[PaymentNode] = [];

    def add_node(self, cid: str) -> PaymentNode {
        if cid in self.nodes_by_id {
            return self.nodes_by_id[cid];
        }
        nd = PaymentNode(cid=cid);
        root ++> nd;
        self.nodes_by_id[cid] = nd;
        self.node_list.append(nd);
        return nd;
    }

    def add_edge(self, from_id: str, to_id: str) -> None {
        if from_id not in self.nodes_by_id {
            return;
        }
        if to_id not in self.nodes_by_id {
            return;
        }
        src = self.nodes_by_id[from_id];
        dst = self.nodes_by_id[to_id];
        src +>:Depends:+> dst;
    }
}

walker CycleBoot {
    has graph: PaymentGraph;

    can boot entry {
        print("cycle_check_boot");
        if len(self.graph.node_list) > 0 {
            visit self.graph.node_list[0];
        }
    }

    can ping with PaymentNode entry {
        print("boot_ping ", here.cid);
        disengage;
    }
}

walker IterDFSCycle {
    has state: CycleState;

    can probe with PaymentNode entry {
        if here.cid in self.state.black and self.state.black[here.cid] {
            disengage;
        }

        color: dict[str, int] = {};
        stack: list[PaymentNode] = [];
        next_idx: dict[str, int] = {};

        stack.append(here);
        color[here.cid] = 1;
        print("visit: ", here.cid);

        while len(stack) > 0 {
            cur = stack[-1];
            ccid = cur.cid;

            kids: list[PaymentNode] = [];
            for ch in [cur ->:Depends:->][?:PaymentNode] {
                kids.append(ch);
            }

            idx: int = 0;
            if ccid in next_idx {
                idx = next_idx[ccid];
            }

            if idx < len(kids) {
                next_idx[ccid] = idx + 1;
                nxt = kids[idx];
                ncid = nxt.cid;

                skip_black: bool = False;
                if ncid in self.state.black {
                    skip_black = self.state.black[ncid];
                }
                if skip_black {
                    continue;
                }

                if ncid in color and color[ncid] == 1 {
                    self.state.found = True;
                    print("cycle at ", ncid);
                    disengage;
                }

                if ncid not in color {
                    color[ncid] = 1;
                    stack.append(nxt);
                    print("visit: ", ncid);
                }
            } else {
                color[ccid] = 2;
                self.state.black[ccid] = True;
                stack.pop();
            }
        }
    }
}

def detect_cycle(g: PaymentGraph) -> bool {
    wboot = root spawn CycleBoot(graph=g);
    st = CycleState();

    ids: list[str] = [];
    for nd in g.node_list {
        ids.append(nd.cid);
    }
    sorted_ids: list[str] = sorted(ids);

    for sid in sorted_ids {
        done: bool = False;
        if sid in st.black {
            done = st.black[sid];
        }
        if done {
            continue;
        }
        start = g.nodes_by_id[sid];
        wk = start spawn IterDFSCycle(state=st);
        if st.found {
            return True;
        }
    }
    return False;
}
