"""Nested format string parsing — r1chardj0n3s/parse#206."""

node ParseRoot {
    has rid: str = "root";
}

node Nest {
    has nid: str;
    has label: str = "";
    has depth: int = 0;
    has conv: str = "";
    has is_leaf: bool = False;
    has ref_key: str = "";
    has parse_pos: int = 0;
