edge Child {}

def next_nonspace(fmt: str, i: int) -> int {
    j: int = i;
    while j < len(fmt) {
        if fmt[j] != " " {
            return j;
        }
        j = j + 1;
    }
    return j;
}

def parse_int_at(text: str, pos: int) -> tuple[int, int] {
    n: int = len(text);
    j: int = pos;
    while j < n and text[j] == " " {
        j = j + 1;
    }
    val: int = 0;
    got: bool = False;
    while j < n {
        ch: str = text[j];
        if ch >= "0" and ch <= "9" {
            val = val * 10 + int(ch);
            got = True;
            j = j + 1;
        } else {
            break;
        }
    }
    if got {
        return (val, j);
    }
    return (0, pos);
}

def link_child(graph_root: ParseRoot, parent: Nest, node: Nest) -> None {
    if parent.nid == "start" {
        graph_root +>:Child:+> node;
    } else {
        parent +>:Child:+> node;
    }
}

def expand_segment(
    fmt: str,
    pos: int,
    depth: int,
    limit: int,
    seq: int,
    graph_root: ParseRoot,
    parent: Nest
) -> tuple[int, int, str] {
    err: str = "";
    if depth > limit {
        return (pos, seq, "max_depth");
    }
    i: int = pos;
    n: int = len(fmt);
    while i < n {
        c: str = fmt[i];
        if c == "\\" {
            i = i + 2;
            continue;
        }
        if c != "{" {
            i = i + 1;
            continue;
        }
        label_buf: str = "";
        j: int = i + 1;
        while j < n {
            if fmt[j] == "\\" {
                if j + 1 < n {
                    label_buf = label_buf + fmt[j + 1];
                    j = j + 2;
                    continue;
                }
            }
            if fmt[j] == ":" or fmt[j] == "}" {
                break;
            }
            label_buf = label_buf + fmt[j];
            j = j + 1;
        }
        if j >= n {
            return (i, seq, "unclosed");
        }
        nid: str = "n" + str(seq);
        seq = seq + 1;
        node = Nest(
            nid=nid,
            label=label_buf,
            depth=depth,
            ref_key=label_buf,
            parse_pos=j + 1
        );
        link_child(graph_root, parent, node);
        if fmt[j] == "}" {
            node.is_leaf = True;
            i = j + 1;
            continue;
        }
        k: int = next_nonspace(fmt, j + 1);
        if k < n and fmt[k] == "{" {
            node.parse_pos = k;
            i = k;
            continue;
        }
        conv_buf: str = "";
        p: int = j + 1;
        while p < n {
            if fmt[p] == "\\" {
                if p + 1 < n {
                    conv_buf = conv_buf + fmt[p + 1];
                    p = p + 2;
                    continue;
                }
            }
            if fmt[p] == "}" {
                break;
            }
            conv_buf = conv_buf + fmt[p];
            p = p + 1;
        }
        if p >= n {
            return (p, seq, "unclosed");
        }
        node.conv = conv_buf;
        node.is_leaf = True;
        i = p + 1;
    }
    return (i, seq, err);
}

