        kids: list[Nest] = [];
        for ch in [here ->:Child:->][?:Nest] {
            kids.append(ch);
        }
        for kid in kids {
            visit :0: [kid];
        }
        print ["match_root", self.pos, len(self.out)];
    }

    can match_nest with Nest entry {
        if here.nid in self.claimed {
            skip;
        }
        self.claimed[here.nid] = True;
        kids: list[Nest] = [];
        for ch in [here ->:Child:->][?:Nest] {
            kids.append(ch);
        }
        if len(kids) > 0 {
            child_map: dict[str, object] = {};
            self.stack.append(self.out);
            self.out = child_map;
            visit :0: [kids[0]];
            parent_out: dict[str, object] = self.stack[len(self.stack) - 1];
            new_stack: list[dict[str, object]] = [];
            si: int = 0;
            while si < len(self.stack) - 1 {
                new_stack.append(self.stack[si]);
                si = si + 1;
            }
            self.stack = new_stack;
            if here.label != "" {
