def parse(format_string: str, value_string: str, max_nesting_depth: int = 10) -> dict[str, object] {
    graph_root = ParseRoot();
    root ++> graph_root;
    ew = graph_root spawn ExpandWalker(
        fmt=format_string,
        limit=max_nesting_depth,
        seq=0,
        err="",
        graph_root=graph_root,
        claimed={}
    );
    if ew.err != "" {
        return {};
    }
    mw = graph_root spawn MatchWalk(
        text=value_string,
        pos=0,
        out={},
        stack=[],
        claimed={}
    );
    return mw.out;
}

def has_circular_reference(format_string: str, max_nesting_depth: int = 10) -> bool {
    graph_root = ParseRoot();
    root ++> graph_root;
    ew = graph_root spawn ExpandWalker(
        fmt=format_string,
        limit=max_nesting_depth,
        seq=0,
        err="",
        graph_root=graph_root,
        claimed={}
    );
    if ew.err != "" {
        return False;
    }
    cp = graph_root spawn CycleProbe(circular=False, claimed={});
    return cp.circular;
}
