def build_registry(defs: dict[str, list[str]]) -> Registry {
  reg = Registry();
  root ++> reg;
  names: dict[str, TypeDef] = {};
  for nm in defs {
    refs: list[str] = defs[nm];
    td = TypeDef(name=nm, refs=refs);
    reg ++> td;
    names[nm] = td;
  }
  for nm in defs {
    src = names[nm];
    refs: list[str] = defs[nm];
    for r in refs {
      if r in names {
        tgt = names[r];
        src +>:Refs:+> tgt;
      }
    }
  }
  return reg;
}

def compile_once(reg: Registry, root_name: str) -> str {
  key = f"grammar:{root_name}";
  td = find_type(reg, root_name);
  if td {
    reg.compiled[key] = True;
    mk = td spawn MarkCompile(root_name=root_name);
  }
  return key;
}

def plug_string(reg: Registry, compiled: str, slot: str, text: str) -> dict[str, str] {
  out: dict[str, str] = {};
  if compiled in reg.compiled {
    out[slot] = text;
    reg.plugs[compiled] = out;
  }
  return out;
}

def resolve_refs(reg: Registry, name: str) -> list[str] | None {
  td = find_type(reg, name);
  if not td { return None; }
  return sorted(td.refs);
}

def closure_types(reg: Registry, root_name: str) -> list[str] {
  td = find_type(reg, root_name);
  found: list[str] = [];
  if td {
    wk = td spawn CollectClosure(claimed={});
    found = wk.found;
  }
  return sorted(found);
}

def detach_ref(reg: Registry, type_name: str, ref_name: str) -> list[str] {
  src = find_type(reg, type_name);
  if not src { return []; }
  to_cut: list[TypeDef] = [];
  for ch in [src ->:Refs:->][?:TypeDef] {
    if ch.name == ref_name { to_cut.append(ch); }
  }
  for ch in to_cut {
    disconnect src +>:Refs:+> ch;
  }
  kept: list[str] = [];
  for r in src.refs {
    if r != ref_name { kept.append(r); }
  }
  src.refs = kept;
  return closure_types(reg, type_name);
}

