```jac
"""Nested format strings — r1chardj0n3s/parse#206."""

node FmtRoot {
    has spec: str;
    has limit: int = 10;
}

node Field {
    has fid: str;
    has name: str;
    has conv: str = "s";
    has leaf: bool = True;
    has depth: int = 0;
}

edge Nested {}

def attach_to_parent(graph_root: FmtRoot, parent: Field | None, ch: Field) {
    if parent is None {
        graph_root +>:Nested:+> ch;
    } else {
        parent +>:Nested:+> ch;
    }
}

def read_brace(spec: str, start: int) -> tuple[str, int] {
    if start >= len(spec) or spec[start] != "{" {
        return ("", -1);
    }
    depth: int = 1;
    i: int = start + 1;
    body: str = "";
    while i < len(spec) and depth > 0 {
        c = spec[i];
        if c == "{" {
            if i + 1 < len(spec) and spec[i + 1] == "{" {
                body += "{{";
                i += 2;
                continue;
            }
            depth += 1;
            body += c;
        } elif c == "}" {
            if i + 1 < len(spec) and spec[i + 1] == "}" {
                body += "}}";
                i += 2;
                continue;
            }
            depth -= 1;
            if depth > 0 {
                body += c;
            }
        } else {
            body += c;
        }
        i += 1;
    }
    if depth != 0 {
        return ("", -1);
    }
    return (body, i);
}

def split_name_conv(body: str) -> tuple[str, str, str] {
    colon: int = -1;
    depth: int = 0;
    j: int = 0;
    while j < len(body) {
        c = body[j];
        if c == "{" {
            depth += 1;
        } elif c == "}" {
            depth -= 1;
        } elif c == ":" and depth == 0 and colon < 0 {
            colon = j;
        }
        j += 1;
    }
    if colon < 0 {
        return (body.strip(), "s", "");
    }
    nm = body[0:colon].strip();
    rest = body[colon + 1:].strip();
    conv: str = "s";
    inner: str = rest;
    if len(rest) > 0 and rest[0] != "{" {
        sp: int = 0;
        while sp < len(rest) and rest[sp] != " " and rest[sp] != "{" {
            sp += 1;
        }
        if sp > 0 {
            conv = rest[0:sp];
            inner = rest[sp:].strip();
        }
    }
    return (nm, conv, inner);
}

def parse_int_at(text: str, pos: int) -> tuple[int, int] {
    n: int = len(text);
    if pos >= n {
        return (0, pos);
    }
    sign: int = 1;
    i: int = pos;
    if text[i] == "-" {
        sign = -1;
        i += 1;
    }
    val: int = 0;
    got: bool = False;
    while i < n and text[i] >= "0" and text[i] <= "9" {
        d: int = 0;
        d = ord(text[i]) - ord("0");
        val = val * 10 + d;
        got = True;
        i += 1;
    }
    if not got {
        return (0, pos);
    }
    return (sign * val, i);
}

def read_word_at(text: str, pos: int) -> tuple[str, int] {
    i: int = pos;
    n: int = len(text);
    out: str = "";
    while i < n and text[i] != " " and text[i] != "}" {
        out += text[i];
        i += 1;
    }
    return (out, i);
}

def consume_spec(graph_root: FmtRoot, parent: Field | None, spec: str, depth: int, limit: int) -> str {
    if depth > limit {
        return "max depth";
    }
    i: int = 0;
    n: int = len(spec);
    while i < n {
        c = spec[i];
        if c == "{" {
            if i + 1 < n and spec[i + 1] == "{" {
                i += 2;
                continue;
            }
            (body, ni) = read_brace(spec, i);
            if ni < 0 {
                return "unclosed";
            }
            (nm, cv, rest) = split_name_conv(body);
            if nm == "" {
                return "empty field";
            }
            leaf: bool = True;
            inner: str = rest;
            if len(rest) > 0 and rest[0] == "{" {
                leaf = False;
            }
            ch = Field(fid=nm + "#" + str(depth), name=nm, conv=cv, leaf=leaf, depth=depth);
            attach_to_parent(graph_root, parent, ch);
            if not leaf {
                sb = ch spawn SubBuildW(graph_root=graph_root, spec=inner, depth=depth + 1, limit=limit);
                if sb.err != "" {
                    return sb.err;
                }
            }
            i = ni + 1;
            continue;
        }
        i += 1;
    }
    return "";
}

walker SubBuildW {
    has graph_root: FmtRoot;
    has spec: str;
    has depth: int = 0;
    has limit: int = 10;
    has err: str = "";
    can start_root with FmtRoot entry {
        self.err = consume_spec(here, None, self.spec, self.depth, self.limit);
        print("SubBuildW root err=" + self.err);
        disengage;
    }
    can start_field with Field entry {
        self.err = consume_spec(self.graph_root, here, self.spec, self.depth, self.limit);
        print("SubBuildW field err=" + self.err);
        disengage;
    }
}

walker NamesW {
    has claimed: dict[str, bool] = {};
    has names: list[str] = [];
    can step_root with FmtRoot entry {
        kids: list[Field] = [here ->:Nested:->][?:Field];
        for k in kids {
            visit [k];
        }
        print("NamesW total=" + str(len(self.names)));
    }
    can step_field with Field entry {
        if here.fid in self.claimed { skip; }
        self.claimed[here.fid] = True;
        self.names.append(here.name);
        kids: list[Field] = [here ->:Nested:->][?:Field];
        if len(kids) > 0 {
            for k in kids {
                visit [k];
            }
        } else {
            disengage;
        }
    }
}

walker DepthW {
    has claimed: dict[str, bool] = {};
    has deepest: int = 0;
    can step_root with FmtRoot entry {
        kids: list[Field] = [here ->:Nested:->][?:Field];
        for k in kids {
            visit [k];
        }
        print("DepthW max=" + str(self.deepest));
    }
    can step_field with Field entry {
        if here.fid in self.claimed { skip; }
        self.claimed[here.fid] = True;
        if here.depth > self.deepest {
            self.deepest = here.depth;
        }
        kids: list[Field] = [here ->:Nested:->][?:Field];
        if len(kids) > 0 {
            for k in kids {
                visit [k];
            }
        } else {
            disengage;
        }
    }
}

walker MatchW {
    has text: str;
    has pos: int = 0;
    has out: dict[str, object] = {};
    has claimed: dict[str, bool] = {};
    has err: str = "";
    can walk_root with FmtRoot entry {
        kids: list[Field] = [here ->:Nested:->][?:Field];
        if len(kids) == 0 {
            disengage;
        } else {
            for k in kids {
                visit [k];
            }
        }
        print("MatchW root pos=" + str(self.pos));
    }
    can walk_field with Field entry {
        if here.fid in self.claimed { skip; }
        self.claimed[here.fid] = True;
        kids: list[Field] = [here ->:Nested:->][?:Field];
        if len(kids) > 0 {
            parent_out = self.out;
            nested_out: dict[str, object] = {};
            self.out = nested_out;
            for k in kids {
                visit [k];
            }
            parent_out[here.name] = nested_out;
            self.out = parent_out;
        } elif here.leaf and here.conv == "d" {
            (v, p2) = parse_int_at(self.text, self.pos);
            self.pos = p2;
            self.out[here.name] = v;
        } elif here.leaf {
            (w, p3) = read_word_at(self.text, self.pos);
            self.pos = p3;
            self.out[here.name] = w;
        }
        print("MatchW field " + here.name);
    }
}

def build_graph(fmt: str, max_nesting_depth: int = 10) -> FmtRoot {
    gr = FmtRoot(spec=fmt, limit=max_nesting_depth);
    root ++> gr;
    wk = gr spawn SubBuildW(graph_root=gr, spec=fmt, depth=0, limit=max_nesting_depth);
    print("build_graph err=" + wk.err);
    return gr;
}

def field_names(fmt: str, max_nesting_depth: int = 10) -> list[str] {
    gr = build_graph(fmt, max_nesting_depth);
    w = gr spawn NamesW();
    out: list[str] = sorted(w.names);
    print("field_names count=" + str(len(out)));
    return out;
}

def nesting_depth(fmt: str, max_nesting_depth: int = 10) -> int {
    gr = build_graph(fmt, max_nesting_depth);
    w = gr spawn DepthW();
    print("nesting_depth result=" + str(w.deepest));
    return w.deepest;
}

def parse(fmt: str, value: str, max_nesting_depth: int = 10) -> dict[str, object] {
    gr = build_graph(fmt, max_nesting_depth);
    w = gr spawn MatchW(text=value);
    print("parse done err=" + w.err);
    result: dict[str, object] = w.out;
    return result;
}
