        return RECUR;
    }
    if left == right {
        return left;
    }
    raise ValueError("incompatible types: [" + left + ", " + right + "]");
}

def min_type_raises(left: str, right: str) -> bool {
    try {
        min_type(left, right);
        return False;
    } except ValueError {
        return True;
    }
}

def expand_type(type_name: str, defs: dict[str, object]) -> dict[str, object] {
    if type_name not in defs {
        return {"type": type_name};
    }
    reg = build_registry(defs);
    start_nd = reg[type_name];
    w = start_nd spawn ExpandW(path={}, done={}, nodes=reg);
    if type_name in w.done {
        return w.done[type_name] as dict[str, object];
    }
    return {"type": OBJ, "properties": {}};
}

def canonical_form(type_name: str, defs: dict[str, object]) -> dict[str, object] {
    return expand_type(type_name, defs);
}

