"""drizzle-team/drizzle-orm#1215 — recursive relational with children depth."""

node Post {
    has cid: str;
    has post_id: int;
    has body: str;
    has kind: str;
}

edge Child {}

walker BuildSubtree {
    has claimed: dict[str, bool] = {};
    has depth_limit: int = 0;
    has level: int = 1;
    has subtree: dict = {};

    can step with Post entry {
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        child_payloads: list[dict] = [];
        allow_descent = self.depth_limit == 0 or self.level < self.depth_limit;
        if allow_descent {
            raw_kids: list[Post] = [];
            for ch in [here ->:Child:->][?:Post] {
                raw_kids.append(ch);
            }
            order: list[int] = [];
            for k in raw_kids {
                order.append(k.post_id);
            }
            order = sorted(order);
            sorted_kids: list[Post] = [];
            for want in order {
                for k in raw_kids {
                    if k.post_id == want {
                        sorted_kids.append(k);
                    }
                }
            }
            next_level = self.level + 1;
            for kid in sorted_kids {
                wk = kid spawn BuildSubtree(
                    claimed=self.claimed,
                    depth_limit=self.depth_limit,
                    level=next_level
                );
                child_payloads.append(wk.subtree);
            }
        }
        payload: dict = {};
        payload["id"] = here.post_id;
        payload["body"] = here.body;
        payload["kind"] = here.kind;
        if len(child_payloads) > 0 {
            payload["children"] = child_payloads;
        }
        self.subtree = payload;
        print("built", here.post_id, "at", self.level);
    }
}

def _cid_for(post_id: int) -> str {
    return "p:" + str(post_id);
}

def make_store(rows: list[dict], parent_links: list[tuple[int, int]]) -> dict {
    posts: dict[int, dict] = {};
    children: dict[int, list[int]] = {};
    for row in rows {
        pid = row["id"];
        body_val = row["body"];
        kind_val = row["kind"];
        posts[pid] = {"id": pid, "body": body_val, "kind": kind_val};
        children[pid] = [];
    }
    for link in parent_links {
        parent_id = link[0];
        child_id = link[1];
        if parent_id in children and child_id in posts {
            slot = children[parent_id];
            slot.append(child_id);
        }
    }
    out: dict = {};
    out["posts"] = posts;
    out["children"] = children;
    return out;
}

def _materialize(store: dict) -> dict[int, Post] {
    posts_map = store["posts"] as dict[int, dict];
    child_map = store["children"] as dict[int, list[int]];
    by_id: dict[int, Post] = {};
    for pid in posts_map {
        row = posts_map[pid] as dict;
        body_txt = row["body"];
        kind_txt = row["kind"];
        nd = Post(cid=_cid_for(pid), post_id=pid, body=body_txt, kind=kind_txt);
        by_id[pid] = nd;
    }
    for pid in child_map {
        if pid not in by_id {
            continue;
        }
        parent_nd = by_id[pid];
        child_ids = child_map[pid] as list[int];
        for cid in child_ids {
            if cid in by_id {
                child_nd = by_id[cid];
                parent_nd +>:Child:+> child_nd;
            }
        }
    }
    return by_id;
}

def find_post_with_children(store: dict, post_id: int, depth: int = 0) -> dict | None {
    posts_map = store["posts"] as dict[int, dict];
    if post_id not in posts_map {
        return None;
    }
    index = _materialize(store);
    target = index[post_id];
    root ++> target;
    wk = target spawn BuildSubtree(claimed={}, depth_limit=depth, level=1);
    return wk.subtree;
}
