"""Recursive post tree queries — drizzle-team/drizzle-orm#1215."""

node Post {
    has pid: int;
    has body: str;
    has kind: str;
}

edge ChildOf {}

walker ResolvePost {
    has target: int;
    has found: Post | None = None;

    can start entry {
        print("resolve scan " + str(self.target));
        visit [-->][?:Post];
    }

    can probe with Post entry {
        if here.pid == self.target {
            self.found = here;
            print("resolve hit " + str(self.target));
            disengage;
        }
    }
}

walker BuildTree {
    has remaining: int;
    has claimed: dict[str, bool] = {};
    has result: dict = {};

    can grow with Post entry {
        cid = str(here.pid);
        if cid in self.claimed {
            skip;
        }
        self.claimed[cid] = True;
        self.result = {
            "id": here.pid,
            "body": here.body,
            "kind": here.kind,
        };
        print("tree " + str(here.pid));
        if self.remaining <= 0 {
            disengage;
        }
        raw: list[Post] = [here ->:ChildOf:->][?:Post];
        order: list[int] = [];
        for ch in raw {
            order.append(ch.pid);
        }
        child_rows: list[dict] = [];
        next_depth = self.remaining - 1;
        for pid in sorted(order) {
            for ch in raw {
                if ch.pid != pid {
                    continue;
                }
                ck = str(ch.pid);
                if ck in self.claimed {
                    continue;
                }
                sub = ch spawn BuildTree(
                    remaining=next_depth,
                    claimed=self.claimed,
                );
                if "id" in sub.result {
                    child_rows.append(sub.result);
                }
            }
        }
        if len(child_rows) > 0 {
            self.result["children"] = child_rows;
        }
        disengage;
    }
}

walker FindFirst {
    has target: int;
    has depth: int;
    has payload: dict | None = None;

    can start entry {
        print("find scan " + str(self.target));
        visit [-->][?:Post];
    }

    can seek with Post entry {
        if here.pid != self.target {
            skip;
        }
        lim = self.depth;
        if lim == 0 {
            lim = 100000;
        }
        claim: dict[str, bool] = {};
        tw = here spawn BuildTree(remaining=lim, claimed=claim);
        self.payload = tw.result;
        print("found " + str(self.target) + " depth " + str(self.depth));
        disengage;
    }
}

def create_post(pid: int, body: str, kind: str) -> dict {
    node = Post(pid=pid, body=body, kind=kind);
    root ++> node;
    print("built " + str(pid) + " at " + str(pid));
    return {"id": pid, "body": body, "kind": kind};
}

def link_child(parent_id: int, child_id: int) -> bool {
    pr = root spawn ResolvePost(target=parent_id);
    cr = root spawn ResolvePost(target=child_id);
    if pr.found is None {
        return False;
    }
    if cr.found is None {
        return False;
    }
    pr.found +>:ChildOf:+> cr.found;
    return True;
}

def find_first(post_id: int, depth: int = 10) -> dict | None {
    wk = root spawn FindFirst(target=post_id, depth=depth);
    return wk.payload;
}
