def normalize_group_ref(cmb: CmbStore, group_ref: object) -> str {
    refs = group_ref as list;
    if refs is not None {
        if len(refs) >= 2 {
            return str(refs[1]);
        }
        if len(refs) >= 1 {
            return str(refs[0]);
        }
        return "";
    }
    return str(group_ref);
}

def locate_group(cmb: CmbStore, group_id: str) -> Group | None {
