}

def add_group_field(cmb: CmbStore, group_ref: object, spec: dict) -> object {
    parent_id = normalize_group_ref(cmb, group_ref);
    parent = locate_group(cmb, parent_id);
    if parent is None {
        return None;
    }
    ftype: str = "text";
    if "type" in spec {
        ftype = str(spec["type"]);
    }
    if ftype == "group" {
        sub_id = str(spec["id"]);
        sub_desc: str = "";
        if "desc" in spec {
            sub_desc = str(spec["desc"]);
        }
        sub = Group(group_id=sub_id, desc=sub_desc);
        parent +>:InGroup:+> sub;
        pair: list[str] = [parent_id, sub_id];
        return pair;
    }
    fld_id = str(spec["id"]);
    nm: str = "";
    if "name" in spec {
        nm = str(spec["name"]);
    }
    fld = Field(field_id=fld_id, name=nm, field_type=ftype);
    parent +>:InGroup:+> fld;
    return fld_id;
}

def get_group_children(cmb: CmbStore, group_id: str) -> list[str] {
    ids: list[str] = [];
    parent = locate_group(cmb, group_id);
    if parent is None {
        return ids;
