    for g in [parent ->:InGroup:->][?:Group] {
        ids.append(g.group_id);
    }
    for f in [parent ->:InGroup:->][?:Field] {
        ids.append(f.field_id);
    }
    out: list[str] = sorted(ids);
    return out;
}

