```jac
"""dromara/easy-query#479 — asTreeCte extra columns (root_id propagation)."""

node Entity {
    has id: str;
    has parent_id: str | None = None;
}

edge Child {}

walker CteWalker {
    has claimed: dict[str, bool] = {};
    has rows: list[dict] = [];
    has root_id: str = "";

    can walk with Entity entry {
        if here.id in self.claimed {
            skip;
        }
        self.claimed[here.id] = True;
        row: dict = {};
        row["id"] = here.id;
        row["parent_id"] = here.parent_id;
        row["root_id"] = self.root_id;
        self.rows.append(row);
        kids: list[Entity] = [here ->:Child:->][?:Entity];
        if kids {
            visit kids;
        } else {
            disengage;
        }
    }
}

walker DemoWalker {
    has claimed: dict[str, bool] = {};

    can run entry {
        if "demo" in self.claimed {
            skip;
        }
        self.claimed["demo"] = True;
        demo_specs: list[dict] = [
            {"id": "r1", "parent_id": None},
            {"id": "c1", "parent_id": "r1"},
            {"id": "c2", "parent_id": "r1"},
        ];
        demo_rows = as_tree_cte(demo_specs);
        for dr in demo_rows {
            print(dr);
        }
        disengage;
    }
}

def sort_rows(rows: list[dict]) -> list[dict] {
    ids: list[str] = [];
    for r in rows {
        ids.append(r["id"] as str);
    }
    ids = sorted(ids);
    out: list[dict] = [];
    for sid in ids {
        for r in rows {
            if (r["id"] as str) == sid {
                out.append(r);
                break;
            }
        }
    }
    return out;
}

def seed_entities(specs: list[dict]) -> Entity | None {
    id_map: dict[str, Entity] = {};
    anchor = Entity(id="__anchor__", parent_id=None);
    root ++> anchor;
    for spec in specs {
        eid = spec["id"] as str;
        pid_val = spec.get("parent_id");
        parent_id: str | None = None;
        if pid_val is not None {
            parent_id = pid_val as str;
        }
        nd = Entity(id=eid, parent_id=parent_id);
        id_map[eid] = nd;
        anchor ++> nd;
    }
    for spec in specs {
        eid = spec["id"] as str;
        pid_val = spec.get("parent_id");
        if pid_val is not None {
            pid_str = pid_val as str;
            if pid_str in id_map {
                parent_nd = id_map[pid_str] as Entity;
                child_nd = id_map[eid] as Entity;
                parent_nd +>:Child:+> child_nd;
            }
        }
        alt_val = spec.get("secondary_parent_id");
        if alt_val is not None {
            alt_str = alt_val as str;
            if alt_str in id_map {
                alt_parent = id_map[alt_str] as Entity;
                alt_child = id_map[eid] as Entity;
                alt_parent +>:Child:+> alt_child;
            }
        }
    }
    return anchor;
}

def as_tree_cte(entities: list[dict]) -> list[dict] {
    if not entities {
        return [];
    }
    anchor = seed_entities(entities);
    if anchor is None {
        return [];
    }
    out: list[dict] = [];
    top: list[Entity] = [anchor ->:Child:->][?:Entity];
    for nd in top {
        if nd.id == "__anchor__" {
            continue;
        }
        if nd.parent_id is None {
            w = nd spawn CteWalker(claimed={}, rows=[], root_id=nd.id);
            for row in w.rows {
                out.append(row);
            }
        }
    }
    return sort_rows(out);
}

with entry {
    root spawn DemoWalker;
}
