"""restsql/restsql#79 — recursive geo closure lifted to OSP walkers."""

node GeoGraph {}

node Geo {
    has geo_id: int;
    has parent_id: int;
    has cid: str;
}

edge GeoChild {}

edge InGraph {}

walker GeoWalker {
    has seeds: list[int] = [];
    has claimed: dict[str, bool] = {};
    has found: list[list[int]] = [];

    can begin with GeoGraph entry {
        print("begin geo walker");
        pool: list[Geo] = [here ->:InGraph:->][?:Geo];
        for sid in self.seeds {
            for nd in pool {
                if nd.geo_id == sid {
                    visit :0: nd;
                }
            }
        }
        disengage;
    }

    can step with Geo entry {
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        row: list[int] = [here.geo_id, here.parent_id];
        self.found.append(row);
        print(here.geo_id);
        kids: list[Geo] = [here ->:GeoChild:->][?:Geo];
        for kid in kids {
            visit :0: kid;
        }
    }
}

def geo_cid(geo_id: int) -> str {
    return f"g:{geo_id}";
}

def build_geo_graph(records: list) -> GeoGraph {
    g = GeoGraph();
    root ++> g;
    id_to_node: dict[str, Geo] = {};
    for rec in records {
        gid = rec["id"];
        pid = rec["parent"];
        if pid is None {
            pid = -1;
        }
        cid = geo_cid(gid);
        nd = Geo(geo_id=gid, parent_id=pid, cid=cid);
        g +>:InGraph:+> nd;
        id_to_node[str(gid)] = nd;
    }
    for rec in records {
        gid = rec["id"];
        pid = rec["parent"];
        if pid is None {
            pid = -1;
        }
        if pid != -1 {
            pkey = str(pid);
            ckey = str(gid);
            if pkey in id_to_node {
                if ckey in id_to_node {
                    parent_nd = id_to_node[pkey] as Geo;
                    child_nd = id_to_node[ckey] as Geo;
                    parent_nd +>:GeoChild:+> child_nd;
                }
            }
        }
    }
    return g;
}

def recursive_geo(records: list, seed_ids: list[int]) -> list[list[int]] {
    g = build_geo_graph(records);
    wk = g spawn GeoWalker(seeds=seed_ids);
    out: list[list[int]] = wk.found;
    return sorted(out);
}
