```jac
"""dromara/easy-query#479 — asTreeCte extra column (root_id propagation)."""

node Row {
    has cid: str;
    has parent_id: str = "";
    has root_id: str = "";
}

edge ParentEdge {}

def append_row(results: list[dict], nd: Row) -> None {
    row: dict = {};
    row["id"] = nd.cid;
    if nd.parent_id == "" {
        row["parent_id"] = None;
    } else {
        row["parent_id"] = nd.parent_id;
    }
    row["root_id"] = nd.root_id;
    results.append(row);
}

def build_graph(rows: list[dict]) -> Row {
    all_nodes: list[Row] = [];
    id_to_node: dict[str, Row] = {};
    for raw in rows {
        rid: str = str(raw["id"]);
        pid: str = "";
        if "parent_id" in raw and raw["parent_id"] is not None {
            pid = str(raw["parent_id"]);
        }
        nd = Row(cid=rid, parent_id=pid);
        all_nodes.append(nd);
        id_to_node[rid] = nd;
    }
    graph_root = Row(cid="__root__");
    root ++> graph_root;
    for nd in all_nodes {
        graph_root ++> nd;
    }
    for nd in all_nodes {
        if nd.parent_id == "" {
            continue;
        }
        if nd.parent_id not in id_to_node {
            continue;
        }
        parent = id_to_node[nd.parent_id];
        parent +>:ParentEdge:+> nd;
    }
    return graph_root;
}

def sort_results(items: list[dict]) -> list[dict] {
    ids: list[str] = [];
    for it in items {
        ids.append(str(it["id"]));
    }
    ids = sorted(ids);
    sorted_out: list[dict] = [];
    for sid in ids {
        for it in items {
            if str(it["id"]) == sid {
                sorted_out.append(it);
                break;
            }
        }
    }
    return sorted_out;
}

walker TreeCteWalker {
    has claimed: dict[str, bool] = {};
    has results: list[dict] = [];

    can boot with Row entry {
        if here.cid != "__root__" {
            skip;
        }
        for ch in [here ->][?:Row] {
            if ch.cid == "__root__" {
                continue;
            }
            if ch.parent_id != "" {
                continue;
            }
            visit :0: [ch];
        }
        print("boot tree cte");
        disengage;
    }

    can walk with Row entry {
        if here.cid == "__root__" {
            skip;
        }
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        if here.parent_id == "" {
            here.root_id = here.cid;
        }
        append_row(self.results, here);
        kids: list[Row] = [here ->:ParentEdge:->][?:Row];
        for kid in kids {
            kid.root_id = here.root_id;
            visit :0: [kid];
        }
        print(f"row {here.cid} root_id={here.root_id}");
    }
}

def as_tree_cte(rows: list[dict]) -> list[dict] {
    graph_root = build_graph(rows);
    w = graph_root spawn TreeCteWalker(claimed={});
    return sort_results(w.results);
}
