def lookup_table(tid: str) -> TableRoot | None {
    for ch in [root -->][?:TableRoot] {
        if ch.tid == tid {
            return ch;
        }
    }
    return None;
}

def build_table(entries: list[list[int]]) -> str {
    tid = "t_pr_cte";
    tr = TableRoot(tid=tid);
    root ++> tr;
    by_n: dict[int, Row] = {};
    for ent in entries {
        n = ent[0];
        p = ent[1];
        cid = "row_" + str(n);
        r = Row(n=n, p=p, cid=cid);
        by_n[n] = r;
        tr ++> r;
    }
    for ent in entries {
        n = ent[0];
        p = ent[1];
        if p in by_n {
            par = by_n[p];
            chn = by_n[n];
            par +>:Child:+> chn;
        }
    }
    return tid;
}

def recursive_cte_collect(tid: str, anchor: int) -> list[int] {
    tr = lookup_table(tid);
    if tr is None {
        raise ValueError(msg="unknown table");
    }
    w = tr spawn RecursiveCollect(anchor=anchor);
    out: list[int] = sorted(w.collected);
    return out;
}

def union_has_recursive_ref(rewrite: str) -> bool {
    if rewrite == "none" {
        return True;
    }
    if rewrite == "parallel_in" {
        return False;
    }
    return True;
}

def query_in_subquery_count(tid: str, anchor: int, rewrite: str) -> int {
    if not union_has_recursive_ref(rewrite) {
        le = LogicalError(msg="UNION query r is not recursive");
        raise le;
    }
    vals = recursive_cte_collect(tid, anchor);
    return len(vals);
}

def query_top_level_count(tid: str, anchor: int, rewrite: str) -> int {
    if rewrite == "parallel_top" {
        td = TooDeepRecursion(msg="Maximum recursive CTE evaluation depth exceeded");
        raise td;
    }
    vals = recursive_cte_collect(tid, anchor);
    return len(vals);
}
