"""eclipse-opensovd/classic-diagnostic-adapter#349"""

node ComParam {
    has cid: str;
    has key: str;
    has leaf_val: int = -1;
    has is_leaf: bool = False;
}

edge Child {}

node TreeAnchor {
    has counter: int = 0;
}

def _new_cid(anchor: TreeAnchor) -> str {
    cid = "n" + str(anchor.counter);
    anchor.counter += 1;
    return cid;
}

walker CidFinder {
    has wanted: str;
    has found: ComParam | None = None;
    has claimed: dict[str, bool] = {};
    can find with ComParam entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        if here.cid == self.wanted {
            self.found = here;
            print("cidfinder hit " + here.cid);
        }
        kids: list[ComParam] = [here ->:Child:->][?:ComParam];
        for ch in kids {
            visit :0: [ch];
        }
    }
}

walker FlattenWalker {
    has claimed: dict[str, bool] = {};
    has prefix: str = "";
    has leaves: list = [];
    can step with ComParam entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        path = self.prefix;
        if here.key != "" {
            if self.prefix != "" { path = self.prefix + "." + here.key; }
            else { path = here.key; }
        }
        if here.is_leaf {
            pair = (path, here.leaf_val);
            self.leaves.append(pair);
            print("flatten leaf " + path);
        }
        kids: list[ComParam] = [here ->:Child:->][?:ComParam];
        idx = len(kids) - 1;
        while idx >= 0 {
            saved = self.prefix;
            if here.key != "" {
                if self.prefix != "" { self.prefix = self.prefix + "." + here.key; }
                else { self.prefix = here.key; }
            }
            visit :0: [kids[idx]];
            self.prefix = saved;
            idx -= 1;
        }
    }
}

def create_param_tree(spec: dict[str, object]) -> dict {
    anchor = TreeAnchor();
    graph_root = ComParam(cid="n0", key="");
    anchor.counter = 1;
    root ++> graph_root;
    root ++> anchor;
    out_nodes: dict[str, object] = {};
    root_meta: dict = {"key": "", "val": None, "kids": []};
    out_nodes["n0"] = root_meta;
    stack: list = [];
    seed: dict = {"pid": "n0", "parent": graph_root, "items": spec};
    stack.append(seed);
    while len(stack) > 0 {
        frame = stack.pop();
        pid: str = frame["pid"];
        parent_node: ComParam = frame["parent"];
        items: dict = frame["items"];
        keys: list[str] = sorted(items.keys());
        kids_meta: list = out_nodes[pid]["kids"];
        for k in keys {
            v = items[k];
            cid = _new_cid(anchor);
            nd = ComParam(cid=cid, key=k);
            parent_node +>:Child:+> nd;
            kid_meta: dict = {"key": k, "val": None, "kids": []};
            nested = v as dict[str, object];
            if nested {
                out_nodes[cid] = kid_meta;
                kids_meta.append(cid);
                child_frame: dict = {"pid": cid, "parent": nd, "items": nested};
                stack.append(child_frame);
            } else {
                nd.is_leaf = True;
                nd.leaf_val = v as int;
                kid_meta["val"] = nd.leaf_val;
                out_nodes[cid] = kid_meta;
                kids_meta.append(cid);
            }
        }
    }
    result: dict = {"root": "n0", "nodes": out_nodes};
    return result;
}

def _resolve_root(tree: dict) -> ComParam | None {
    wanted: str = tree["root"];
    wk = root spawn CidFinder(wanted=wanted);
    return wk.found;
}

def flatten_leaves(tree: dict) -> list {
    start = _resolve_root(tree);
    leaves: list = [];
    if start {
        fw = start spawn FlattenWalker();
        leaves = fw.leaves;
    }
    return sorted(leaves);
}

def get_leaf(tree: dict, path: str) -> int | None {
    pairs = flatten_leaves(tree);
    for pr in pairs {
        p: str = pr[0];
        val: int = pr[1];
        if p == path { return val; }
    }
    return None;
}

def count_leaves(tree: dict) -> int {
    pairs = flatten_leaves(tree);
    return len(pairs);
}
