    by_id: dict[int, Task] = {};
    if back_edges is None {
        back_edges = [];
    }
    for row in tasks {
        tid = row["task_id"] as int;
        t = Task(
            cid=str(tid),
            task_id=tid,
            name=row["name"] as str,
            parent_id=row["parent_id"] as int
        );
        root ++> t;
        by_id[tid] = t;
    }
    for row in tasks {
        tid = row["task_id"] as int;
        pid = row["parent_id"] as int;
        if pid in by_id {
            par = by_id[pid] as Task;
            ch = by_id[tid] as Task;
            par +>:Child:+> ch;
        }
    }
    for be in back_edges {
        fr = be["from"] as int;
        to = be["to"] as int;
        if fr in by_id && to in by_id {
            a = by_id[fr] as Task;
            b = by_id[to] as Task;
            a +>:Child:+> b;
        }
    }
    return by_id;
}

def recursive_closure_ids(
    tasks: list,
    anchor_parent_id: int,
    back_edges: list | None = None
) -> list[int] {
    by_id = materialize_tasks(tasks, back_edges);
    claimed: dict[str, bool] = {};
    acc: list[int] = [];
    for row in tasks {
        if (row["parent_id"] as int) == anchor_parent_id {
            tid = row["task_id"] as int;
            if tid in by_id {
                nd = by_id[tid] as Task;
                w = nd spawn RtqWalker(claimed=claimed);
                for fid in w.found {
                    acc.append(fid);
                }
            }
        }
    }
    seen: dict[int, bool] = {};
    uniq: list[int] = [];
    for x in acc {
        if x not in seen {
            seen[x] = True;
            uniq.append(x);
        }
    }
    return sorted(uniq);
}

def count_recursive_closure(
    tasks: list,
    anchor_parent_id: int,
    back_edges: list | None = None
) -> int {
    ids = recursive_closure_ids(tasks, anchor_parent_id, back_edges);
    return len(ids);
}

def mixed_recursive_plain_error(cte_specs: list) -> bool {
    has_rec = False;
    has_plain = False;
    for spec in cte_specs {
        if spec["recursive"] as bool {
            has_rec = True;
        } else {
            has_plain = True;
        }
    }
    if has_rec && has_plain {
        return True;
    }
    return False;
}

def subquery_has_mixed_cte_kinds(cte_specs: list) -> bool {
    return mixed_recursive_plain_error(cte_specs);
}
