def split_path(path: str) -> list[str] {
    parts: list[str] = [];
    buf = "";
    for ch in path {
        if ch == "." {
            if buf != "" {
                parts.append(buf);
                buf = "";
            }
        } else {
            buf = buf + ch;
        }
    }
    if buf != "" {
        parts.append(buf);
    }
    return parts;
}

def _fill_complex(parent: ComParam, spec: dict) -> None {
    keys: list[str] = [];
    for k in spec {
        keys.append(k);
    }
    sorted_keys = sorted(keys);
    for key in sorted_keys {
        val = spec[key];
        if val is int {
            leaf = ComParam(cid=parent.cid + "/" + key, name=key, leaf_val=val, is_leaf=True);
            parent +>:Child:+> leaf;
        } else {
            if val is dict {
                branch = ComParam(cid=parent.cid + "/" + key, name=key, is_leaf=False);
                parent +>:Child:+> branch;
                _fill_complex(branch, val as dict);
            }
        }
    }
}

def build_tree(spec: dict) -> ComParam {
    graph_root = ComParam(cid="root", name="", is_leaf=False);
    _fill_complex(graph_root, spec);
    return graph_root;
}

def parse_from_complex(spec: dict) -> dict {
    out: dict = {};
    keys: list[str] = [];
    for k in spec {
        keys.append(k);
    }
    sorted_keys = sorted(keys);
    for key in sorted_keys {
        val = spec[key];
        if val is int {
            out[key] = val;
        } else {
            if val is dict {
                nested = parse_from_complex(val as dict);
                out[key] = nested;
            }
        }
    }
    return out;
}

def flatten_leaves(root_node: ComParam) -> dict[str, int] {
    w = root_node spawn CollectLeaves(claimed={}, prefix="", out={});
    return w.out;
}

def get_leaf(root_node: ComParam, path: str) -> int {
    parts = split_path(path);
    cur = root_node;
    idx = 0;
    while idx < len(parts) {
        part = parts[idx];
        kids: list[ComParam] = [cur ->:Child:->][?:ComParam];
        found = False;
        for kid in kids {
            if kid.name == part {
                cur = kid;
                found = True;
                break;
            }
        }
        if found == False {
            return 0;
        }
        idx = idx + 1;
    }
    if cur.is_leaf {
        return cur.leaf_val;
    }
    return 0;
}

