"""ent/ent#2167 — recursive CTE LIMIT/ORDER scoping for undeleted file traversal."""

node Anchor {}

node File {
    has cid: str;
    has name: str;
    has deleted: bool = False;
}

edge Child {}

node GraphHandle {
    has anchor: Anchor;
    has by_cid: dict[str, File] = {};
}

def order_key_for(nd: File, order_key: str) -> str {
    if order_key == "deleted" {
        if nd.deleted { return "1"; }
        return "0";
    }
    if order_key == "name" { return nd.name; }
    return nd.cid;
}

def sort_ids(graph: GraphHandle, ids: list[str], order_key: str) -> list[str] {
    xs: list[str] = [];
    for cid in ids { xs.append(cid); }
    n = len(xs);
    i = 0;
    while i < n {
        j = i + 1;
        while j < n {
            ka = order_key_for(graph.by_cid[xs[i]], order_key);
            kb = order_key_for(graph.by_cid[xs[j]], order_key);
            if ka > kb {
                tmp = xs[i];
                xs[i] = xs[j];
                xs[j] = tmp;
            }
            j += 1;
        }
        i += 1;
    }
    return xs;
}

def limit_ids(ids: list[str], lim: int | None) -> list[str] {
    if lim is None { return ids; }
    out: list[str] = [];
    i = 0;
    for cid in ids {
        if i >= lim { break; }
        out.append(cid);
        i += 1;
    }
    return out;
}

def sort_names(names: list[str]) -> list[str] {
    xs: list[str] = [];
    for nm in names { xs.append(nm); }
    n = len(xs);
    i = 0;
    while i < n {
        j = i + 1;
        while j < n {
            if xs[i] > xs[j] {
                tmp = xs[i];
                xs[i] = xs[j];
                xs[j] = tmp;
            }
            j += 1;
        }
        i += 1;
    }
    return xs;
}

def put_file(graph: GraphHandle, nd: File) -> None {
    graph.by_cid[nd.cid] = nd;
}

def build_fs_graph() -> GraphHandle {
    anc = Anchor();
    root ++> anc;
    graph = GraphHandle(anchor=anc);
    a = File(cid="a", name="a");
    b = File(cid="b", name="b");
    ba = File(cid="ba", name="ba");
    bb = File(cid="bb", name="bb");
    bc = File(cid="bc", name="bc", deleted=True);
    c = File(cid="c", name="c", deleted=True);
    ca = File(cid="ca", name="ca");
    cb = File(cid="cb", name="cb");
    d = File(cid="d", name="d", deleted=True);
    anc +>:Child:+> a;
    a +>:Child:+> b;
    a +>:Child:+> c;
    a +>:Child:+> d;
    b +>:Child:+> ba;
    b +>:Child:+> bb;
    b +>:Child:+> bc;
    c +>:Child:+> ca;
    c +>:Child:+> cb;
    put_file(graph, a);
    put_file(graph, b);
    put_file(graph, ba);
    put_file(graph, bb);
    put_file(graph, bc);
    put_file(graph, c);
    put_file(graph, ca);
    put_file(graph, cb);
    put_file(graph, d);
    return graph;
}

def build_diamond_graph() -> GraphHandle {
    anc = Anchor();
    root ++> anc;
    graph = GraphHandle(anchor=anc);
    x = File(cid="x", name="x");
    y = File(cid="y", name="y");
    z = File(cid="z", name="z");
    anc +>:Child:+> x;
    anc +>:Child:+> y;
    x +>:Child:+> z;
    y +>:Child:+> z;
    put_file(graph, x);
    put_file(graph, y);
    put_file(graph, z);
    return graph;
}

def get_name(graph: GraphHandle, cid: str) -> str | None {
    if cid not in graph.by_cid { return None; }
    return graph.by_cid[cid].name;
}

def recursive_undeleted_names(
    graph: GraphHandle,
    initial_limit: int | None = None,
    recursive_limit: int | None = None,
    initial_order: str = "id",
    recursive_order: str = "id",
) -> list[str] {
    undeleted: dict[str, bool] = {};
    frontier: list[str] = [];
    initial_ids: list[str] = [];
    for ch in [graph.anchor ->:Child:->][?:File] {
        if not ch.deleted { initial_ids.append(ch.cid); }
    }
    initial_ids = sort_ids(graph, initial_ids, initial_order);
    initial_ids = limit_ids(initial_ids, initial_limit);
    for cid in initial_ids {
        undeleted[cid] = True;
        frontier.append(cid);
    }
    while len(frontier) > 0 {
        candidates: list[str] = [];
        for pid in frontier {
            parent = graph.by_cid[pid];
            for ch in [parent ->:Child:->][?:File] {
                if ch.deleted { continue; }
                if ch.cid in undeleted { continue; }
                candidates.append(ch.cid);
            }
        }
        candidates = sort_ids(graph, candidates, recursive_order);
        candidates = limit_ids(candidates, recursive_limit);
        if len(candidates) == 0 { break; }
        next_frontier: list[str] = [];
        for cid in candidates {
            undeleted[cid] = True;
            next_frontier.append(cid);
        }
        frontier = next_frontier;
    }
    names: list[str] = [];
    for cid in undeleted { names.append(graph.by_cid[cid].name); }
    return sort_names(names);
}

