"""Recursive undeleted file traversal with scoped initial/recursive limits — ent/ent#2167."""

node file {
    has cid: str;
    has name: str;
    has deleted: bool = False;
}

edge parent_of {}

obj fs_store {
    has roots: list[file] = [];
}

def sort_files_by_key(items: list[file], key: str) -> list[file] {
    keyed: list[tuple] = [];
    for nd in items {
        sort_key = nd.name if key == "name" else nd.cid;
        keyed.append((sort_key, nd));
    }
    keyed.sort();
    out: list[file] = [];
    for pair in keyed {
        out.append(pair[1]);
    }
    return out;
}

def take_limit(items: list[file], limit: int | None) -> list[file] {
    if limit == None {
        return items;
    }
    out: list[file] = [];
    i = 0;
    for nd in items {
        if i >= limit {
            break;
        }
        out.append(nd);
        i += 1;
    }
    return out;
}

def initial_roots(store: fs_store, limit: int | None, order_key: str) -> list[file] {
    cand: list[file] = [];
    for nd in store.roots {
        if not nd.deleted {
            cand.append(nd);
        }
    }
    ordered = sort_files_by_key(cand, order_key);
    return take_limit(ordered, limit);
}

walker undeleted_walk {
    has claimed: dict[str, bool] = {};
    has names: list[str] = [];
    has recursive_limit: int | None = None;
    has recursive_order: str = "id";

    can step with file entry {
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        self.names.append(here.name);
        print("visit ", here.name);
        raw: list[file] = [here ->:parent_of:->][?:file];
        kids: list[file] = [];
        for ch in raw {
            if not ch.deleted {
                kids.append(ch);
            }
        }
        ordered = sort_files_by_key(kids, self.recursive_order);
        limited = take_limit(ordered, self.recursive_limit);
        if limited {
            visit :0: limited;
        } else {
            disengage;
        }
    }
}

