def undeleted_recursive_names(
    store: fs_store,
    initial_limit: int | None = None,
    initial_order: str = "id",
    recursive_limit: int | None = None,
    recursive_order: str = "id",
) -> list[str] {
    anchors = initial_roots(store, initial_limit, initial_order);
    out: list[str] = [];
    for anchor in anchors {
        w = anchor spawn undeleted_walk(
            recursive_limit=recursive_limit,
            recursive_order=recursive_order,
        );
        for nm in w.names {
            out.append(nm);
        }
    }
    return out;
}

def diamond_walk_names() -> list[str] {
    top = build_diamond_fixture();
    w = top spawn undeleted_walk();
    return w.names;
