def build_node(schema: dict, prop_key: str = "") -> TypeNode {
    nd = TypeNode(prop_key=prop_key);
    if "type" not in schema {
        nd.kind = "prim";
        nd.prim = STRING;
        return nd;
    }
    tp = schema["type"] as str;
    if tp == OBJECT {
        nd.kind = "object";
        if "properties" in schema {
            props = schema["properties"] as dict;
            for pk in props {
                ch = build_node(props[pk] as dict, pk);
                nd +>:Child:+> ch;
            }
        }
        return nd;
    }
    nd.kind = "ref";
    nd.reg_name = tp;
    return nd;
}

def build_registry(named: dict) -> dict {
    reg: dict[str, TypeNode] = {};
    for nm in named {
        nd = build_node(named[nm] as dict);
        nd.reg_name = nm;
        reg[nm] = nd;
    }
    return reg;
}

def min_type(candidates: list[str]) -> str {
    if len(candidates) == 0 {
        return STRING;
    }
    uniq: list[str] = [];
    for c in candidates {
        seen = False;
        for u in uniq {
            if u == c {
                seen = True;
            }
        }
        if not seen {
            uniq.append(c);
        }
    }
    if len(uniq) == 1 {
        return uniq[0];
    }
    all_recur = True;
    for u in uniq {
        if u != RECUR {
            all_recur = False;
        }
    }
    if all_recur {
        return RECUR;
    }
    raise ValueError("incompatible types: " + str(candidates));
}

def expand_schema(schema: dict, named: dict) -> dict {
    reg: dict[str, TypeNode] = build_registry(named);
    root = build_node(schema);
    w = root spawn ExpandWalker(
        stack={},
        visited={},
        registry=reg,
        results={}
    );
    return w.out;
}

def node_from_expanded(d: dict, prop_key: str = "") -> TypeNode {
    nd = TypeNode(prop_key=prop_key);
    tp = d["type"] as str;
    if tp == OBJECT {
        nd.kind = "object";
        if "properties" in d {
            props = d["properties"] as dict;
            for pk in props {
                ch = node_from_expanded(props[pk] as dict, pk);
                nd +>:Child:+> ch;
            }
        }
        return nd;
    }
    nd.kind = "prim";
    nd.prim = tp;
    return nd;
}

def canonical_form(expanded: dict) -> dict {
    g = node_from_expanded(expanded);
    w = g spawn CanonWalker(visited={}, results={});
    return w.out;
}
