        kids: list[int] = [];
        if row.pid in g.children { kids = g.children[row.pid]; }
        kids.append(rid);
        g.children[row.pid] = kids;
    }
    for pid in sorted(g.children) {
        g.children[pid] = sorted(g.children[pid]);
    }
    return g;
}

walker IndexedCteWalk {
    has claimed: dict[int, bool] = {};
    has out_ids: list[int] = [];
    has plan: list[str] = [];
    has anchor_id: int = 0;
    has child_map: dict[int, list[int]] = {};
    has row_map: dict[int, TmpRow] = {};

    can expand with TmpRow entry {
        if here.tid in self.claimed { skip; }
        self.claimed[here.tid] = True;
        self.out_ids.append(here.tid);
        if here.tid != self.anchor_id { self.plan.append("INDEX_FOREIGN"); }
        nxt: list[TmpRow] = [];
        if here.tid in self.child_map {
            for cid in self.child_map[here.tid] {
                if cid in self.row_map { nxt.append(self.row_map[cid]); }
            }
        }
        if len(nxt) > 0 { visit :0: nxt; } else { disengage; }
    }
}

walker PostFilterCteWalk {
