    has filter_tid: int = 0;
    has seed_tid: int = 0;
    has child_map: dict[int, list[int]] = {};
    has row_map: dict[int, TmpRow] = {};

    can traverse with TmpRow entry {
        self.plan.append("NATURAL");
        ck = f"{self.seed_tid}:{here.tid}";
        if ck in self.claimed { skip; }
        self.claimed[ck] = True;
        if self.seed_tid == self.filter_tid { self.out_ids.append(here.tid); }
        nxt: list[TmpRow] = [];
