"""FirebirdSQL/firebird#2830 — anchored recursive closure vs post-filter CTE semantics."""

node GNode {
    has nid: int;
}

edge PChild {}

node Graph {
    has nodes: dict[int, GNode] = {};
}

def build_graph(edges: list[tuple[int, int]]) -> Graph {
    g = Graph();
    for e in edges {
        pa: int = e[0];
        ch: int = e[1];
        if pa not in g.nodes {
            na = GNode(nid=pa);
            g.nodes[pa] = na;
            root ++> na;
        }
        if ch not in g.nodes {
            nb = GNode(nid=ch);
            g.nodes[ch] = nb;
            root ++> nb;
        }
        g.nodes[pa] +>:PChild:+> g.nodes[ch];
    }
    return g;
}

walker IdxWalk {
    has claimed: dict[int, bool] = {};
    has found: list[int] = [];
    has anchor_id: int = 0;

    can step with GNode entry {
        if here.nid in self.claimed {
            skip;
        }
        self.claimed[here.nid] = True;
        self.found.append(here.nid);
        print("indexed step nid=", here.nid);
        kids: list[GNode] = [];
        for ch in [here ->:PChild:->][?:GNode] {
            kids.append(ch);
        }
        if len(kids) > 0 {
            visit :0: kids;
        } else {
            disengage;
        }
    }
}

def indexed_closure(g: Graph, anchor: int) -> list[int] {
    store = g.nodes as dict[int, GNode];
    if anchor not in store {
        return [];
    }
    nd = store[anchor];
    w = nd spawn IdxWalk(claimed={}, anchor_id=anchor);
    xs = sorted(w.found);
    print("indexed_closure anchor=", anchor, " ids=", xs);
    return xs;
}

def post_filter_closure(g: Graph, tid: int) -> list[int] {
    store = g.nodes as dict[int, GNode];
    if tid not in store {
        return [];
    }
    all_ids: list[int] = sorted(store);
    queue: list[tuple[int, int]] = [];
    seen: dict[str, bool] = {};
    for i in all_ids {
        key: str = str(i) + ":" + str(i);
        if key not in seen {
            seen[key] = True;
            queue.append((i, i));
        }
    }
    qi: int = 0;
    while qi < len(queue) {
        cur = queue[qi];
        qi += 1;
        t: int = cur[0];
        nid: int = cur[1];
        nd = store[nid];
        kids: list[GNode] = [];
        for ch in [nd ->:PChild:->][?:GNode] {
            kids.append(ch);
        }
        for ch in kids {
            nk: str = str(t) + ":" + str(ch.nid);
            if nk not in seen {
                seen[nk] = True;
                queue.append((t, ch.nid));
            }
        }
    }
    out: list[int] = [];
    picked: dict[int, bool] = {};
    for pr in queue {
        if pr[0] == tid {
            if pr[1] not in picked {
                picked[pr[1]] = True;
                out.append(pr[1]);
            }
        }
    }
    xs = sorted(out);
    print("post_filter tid=", tid, " ids=", xs);
    return xs;
}

def query_plans(mode: str) -> list[str] {
    if mode == "indexed" {
        return ["INDEX_PRIMARY", "INDEX_FOREIGN"];
    }
    return ["NATURAL", "NATURAL", "NATURAL"];
}
