}

def _wire_graph(store: dict[str, TypeNode]) -> None {
  a = TypeNode(cid="S_u32", name="S", gen_slot="u32");
  b = TypeNode(cid="S_fn_u32", name="S", gen_slot="fn_u32");
  c = TypeNode(cid="S_fn_fn_u32", name="S", gen_slot="fn_fn_u32");
  d = TypeNode(cid="S_merge", name="S", gen_slot="merge");
  root ++> a;
  root ++> b;
  root ++> c;
  root ++> d;
  a +>:Inst:+> b;
  a +>:Inst:+> c;
  b +>:Inst:+> d;
  c +>:Inst:+> d;
  c +>:Inst:+> b;
  store["S_u32"] = a;
  store["S_fn_u32"] = b;
  store["S_fn_fn_u32"] = c;
  store["S_merge"] = d;
