def add_prefix(cat: CatalogRoot, path: str) -> Prefix {
    if path in cat.by_path {
        return cat.by_path[path] as Prefix;
    }
    nd = Prefix(path=path);
    root ++> nd;
    cat.by_path[path] = nd;
    return nd;
}

def add_file(cat: CatalogRoot, prefix_path: str, key: str, size: int = 0) -> FileKey {
    pfx = add_prefix(cat, prefix_path);
    fk = FileKey(key=key, size=size);
    pfx +>:Contains:+> fk;
    return fk;
}

def connect_prefix(cat: CatalogRoot, parent_path: str, child_path: str) -> None {
    par = add_prefix(cat, parent_path);
    ch = add_prefix(cat, child_path);
    par +>:Contains:+> ch;
}

def list_recursive_pages(cat: CatalogRoot, root_path: str, page_size: int = 50) -> list[list[str]] {
    if root_path not in cat.by_path {
        empty: list[list[str]] = [];
