"""sicara/tf-explain#63 — recursive model layer-name resolution for callbacks."""

node Layer {
    has lid: str;
    has name: str;
}

edge Nested {}

walker CollectLayerNames {
    has claimed: dict[str, bool] = {};
    has names: list[str] = [];

    can walk with Layer entry {
        if here.lid in self.claimed {
            skip;
        }
        self.claimed[here.lid] = True;
        self.names.append(here.name);
        print(here.name);
        kids: list[Layer] = [];
        for ch in [here ->:Nested:->][?:Layer] {
            kids.append(ch);
        }
        visit :0: kids else {
            disengage;
        }
    }
}

walker FindLayerByName {
    has claimed: dict[str, bool] = {};
    has target: str = "";
    has hit: Layer | None = None;

    can walk with Layer entry {
        if here.lid in self.claimed {
            skip;
        }
        self.claimed[here.lid] = True;
        print(here.lid);
        if self.hit is None and here.name == self.target {
            self.hit = here;
        }
        kids: list[Layer] = [];
        for ch in [here ->:Nested:->][?:Layer] {
            kids.append(ch);
        }
        visit :0: kids else {
            disengage;
        }
    }
}

walker IndexLayers {
    has claimed: dict[str, bool] = {};
    has by_name: dict[str, Layer] = {};

    can walk with Layer entry {
        if here.lid in self.claimed {
            skip;
        }
        self.claimed[here.lid] = True;
        self.by_name[here.name] = here;
        print(here.name);
        kids: list[Layer] = [];
        for ch in [here ->:Nested:->][?:Layer] {
            kids.append(ch);
        }
        visit :0: kids else {
            disengage;
        }
    }
}

def collect_layer_names(root_node: Layer) -> list[str] {
    w = root_node spawn CollectLayerNames(claimed={});
    out: list[str] = [];
    for nm in w.names {
        out.append(nm);
    }
    return out;
}

def find_layer_by_name(root_node: Layer, name: str) -> Layer | None {
    w = root_node spawn FindLayerByName(claimed={}, target=name);
    return w.hit;
}

def resolve_layers_names(root_node: Layer, names: list[str]) -> list[Layer] {
    w = root_node spawn IndexLayers(claimed={});
    store = w.by_name;
    out: list[Layer] = [];
    for nm in names {
        if nm in store {
            out.append(store[nm]);
        }
    }
    return out;
}

def filter_unknown_layers_names(root_node: Layer, names: list[str]) -> list[str] {
    w = root_node spawn IndexLayers(claimed={});
    store = w.by_name;
    miss: list[str] = [];
    for nm in names {
        if nm not in store {
            miss.append(nm);
        }
    }
    miss.sort();
    return miss;
}
