"""Recursive ancestor queries and hierarchy breadcrumbs.
Ground truth: blacksmithgu/obsidian-dataview#318
"""

node Note {
    has cid: str;
    has title: str;
}

edge ParentOf {}

node Hierarchy {
    has notes: dict[str, Note] = {};
}

walker AncestorWalker {
    has claimed: dict[str, bool] = {};
    has found: list[str] = [];

    can climb with Note entry {
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        parents: list[Note] = [here ->:ParentOf:->][?:Note];
        for p in parents {
            self.found.append(p.cid);
            visit :0: [p];
        }
        if len(parents) == 0 {
            disengage;
        }
        print(self.found);
    }
}

walker DemoWalker {
    can kick entry {
        hs = create_hierarchy();
        register_note(hs, "epic", "Epic");
        register_note(hs, "project", "Project", "epic");
        register_note(hs, "story", "Story", "project");
        register_note(hs, "task", "Task", "story");
        print(ancestors(hs, "task"));
        print(breadcrumb(hs, "task"));
    }
}

def create_hierarchy() -> Hierarchy {
    hs = Hierarchy();
    root ++> hs;
    return hs;
}

def register_note(h: Hierarchy, cid: str, title: str, parent_cid: str | None = None) -> str {
    nd = Note(cid=cid, title=title);
    h.notes[cid] = nd;
    root ++> nd;
    if parent_cid is not None {
        if parent_cid in h.notes {
            par = h.notes[parent_cid] as Note;
            nd +>:ParentOf:+> par;
        }
    }
    return cid;
}

def ancestors(h: Hierarchy, note_id: str) -> list[str] {
    if note_id not in h.notes {
        return [];
    }
    start = h.notes[note_id] as Note;
    w = start spawn AncestorWalker(claimed={});
    return w.found;
}

def breadcrumb(h: Hierarchy, note_id: str) -> list[str] {
    if note_id not in h.notes {
        return [];
    }
    titles: list[str] = [];
    path_ids: list[str] = [];
    anc = ancestors(h, note_id);
    i: int = len(anc) - 1;
    while i >= 0 {
        path_ids.append(anc[i]);
        i = i - 1;
    }
    path_ids.append(note_id);
    for cid in path_ids {
        nd = h.notes[cid] as Note;
        titles.append(nd.title);
    }
    return titles;
}

