# tristanpenman/valijson#200 — recursive $ref resolution without stack blow-up.

node SchemaNode {
    has nid: str;
    has is_ref: bool = False;
    has ref_to: str = "";
}

edge PointsTo {}

walker RefWalkWalker {
    has claimed: dict[str, bool] = {};
    has order: list[str] = [];
    has saw_cycle: bool = False;

    can walk with SchemaNode entry {
        if here.nid in self.claimed {
            self.saw_cycle = True;
            print("cycle_skip ", here.nid);
            skip;
        }
        self.claimed[here.nid] = True;
        self.order.append(here.nid);
        print("visit ", here.nid);
        kids: list[SchemaNode] = [];
        for tgt in [here ->:PointsTo:->][?:SchemaNode] {
            kids.append(tgt);
        }
        if kids {
            visit :0: kids;
        } else {
            disengage;
        }
    }
}

def pointer_segments(pointer: str) -> list[str] {
    out: list[str] = [];
    if not pointer {
        return out;
    }
    if not (pointer.startswith("#/")) {
        return out;
    }
    body = pointer[2:];
    if not body {
        return out;
    }
    parts = body.split("/");
    for p in parts {
        out.append(p);
    }
    return out;
}

def resolve_pointer(document: dict, pointer: str) -> object {
    segs = pointer_segments(pointer);
    cur: object = document;
    for seg in segs {
        if cur is dict {
            doc_map = cur as dict;
            if seg not in doc_map {
                raise KeyError(seg);
            }
            cur = doc_map[seg];
        } elif cur is list {
            doc_list = cur as list;
            idx = int(seg);
            cur = doc_list[idx];
        } else {
            raise KeyError(seg);
        }
    }
    return cur;
}

def _node_at(store: dict, nid: str) -> SchemaNode {
    if nid in store {
        return store[nid] as SchemaNode;
    }
    nd = SchemaNode(nid=nid);
    store[nid] = nd;
    return nd;
}

def _attach_ref(store: dict, src: SchemaNode, ref_ptr: str) -> None {
    src.is_ref = True;
    src.ref_to = ref_ptr;
    tgt = _node_at(store, ref_ptr);
    src +>:PointsTo:+> tgt;
}

def build_schema_graph(document: dict, schema: dict) -> SchemaNode {
    store: dict[str, SchemaNode] = {};
    graph_root = _node_at(store, "#");
    pending: list[list] = [];
    pending.append(["#", schema]);
    while pending {
        job = pending.pop();
        path = job[0] as str;
        frag = job[1] as dict;
        here_nd = _node_at(store, path);
        if "$ref" in frag {
            ref_val = frag["$ref"] as str;
            _attach_ref(store, here_nd, ref_val);
        }
        if "items" in frag {
            items_val = frag["items"] as list;
            idx = 0;
            for item_schema in items_val {
                child_path = path + "/items/" + str(idx);
                child_nd = _node_at(store, child_path);
                here_nd +>:PointsTo:+> child_nd;
                item_dict = item_schema as dict;
                pending.append([child_path, item_dict]);
                idx += 1;
            }
        }
        if "properties" in frag {
            props = frag["properties"] as dict;
            for prop_name in sorted(props) {
                prop_schema = props[prop_name] as dict;
                child_path = path + "/properties/" + prop_name;
                child_nd = _node_at(store, child_path);
                here_nd +>:PointsTo:+> child_nd;
                pending.append([child_path, prop_schema]);
            }
        }
    }
    return graph_root;
}

def detect_ref_cycle(document: dict, schema: dict) -> bool {
    graph_root = build_schema_graph(document, schema);
    root ++> graph_root;
    w = graph_root spawn RefWalkWalker(claimed={});
    print("detect_ref_cycle ", w.saw_cycle);
    return w.saw_cycle;
}

def ordered_ref_nodes(document: dict, schema: dict) -> list[str] {
    graph_root = build_schema_graph(document, schema);
    root ++> graph_root;
    w = graph_root spawn RefWalkWalker(claimed={});
    out: list[str] = [];
    for nid in w.order {
        out.append(nid);
    }
    print("ordered_ref_nodes ", len(out));
    return out;
}
