def make_store -> dict {
    st: dict = {};
    st["by_prefix"] = {};
    return st;
}

def _ensure_bucket(store: dict, prefix: str) -> dict {
    bp = store["by_prefix"] as dict;
    if prefix not in bp {
        inner: dict = {};
        inner["index"] = {};
        bp[prefix] = inner;
    }
    return bp[prefix] as dict;
}

def register_prefix(store: dict, prefix: str) {
    _ensure_bucket(store, prefix);
}

def configured_prefixes(store: dict) -> list[str] {
    bp = store["by_prefix"] as dict;
    keys: list[str] = [];
    for k in bp {
        keys.append(k);
    }
    return sorted(keys);
}

def add_record(store: dict, prefix: str, cid: str, parent_cid: str | None = None) -> Record | None {
    if prefix == "" {
        return None;
    }
    bucket = _ensure_bucket(store, prefix);
    idx = bucket["index"] as dict;
    if cid in idx {
        nd = idx[cid] as Record;
    } else {
        nd = Record(cid=cid, prefix=prefix);
        idx[cid] = nd;
    }
    if parent_cid is not None and parent_cid != "" {
        if parent_cid in idx {
            par = idx[parent_cid] as Record;
            par +>:ChildOf:+> nd;
        }
    }
    return nd;
}

def _lookup(store: dict, prefix: str, record_id: str) -> Record | None {
    bp = store["by_prefix"] as dict;
    if prefix not in bp {
        return None;
    }
    idx = (bp[prefix] as dict)["index"] as dict;
    if record_id not in idx {
        return None;
    }
    return idx[record_id] as Record;
}

def descendants(store: dict, record_id: str, prefix: str, depth: int = DEFAULT_DEPTH) -> list[str] {
    nd = _lookup(store, prefix, record_id);
    if nd is None {
        return [];
    }
    w = nd spawn DescendWalker(
        claimed={},
        found=[],
        max_depth=depth,
        depths={},
        target_prefix=prefix,
        origin=record_id
    );
    print {"op": "descendants", "prefix": prefix, "id": record_id, "count": len(w.found)};
    out: list[str] = [];
    for x in w.found {
        out.append(x);
    }
    return out;
}

def ancestors(store: dict, record_id: str, prefix: str, depth: int = DEFAULT_DEPTH) -> list[str] {
    nd = _lookup(store, prefix, record_id);
    if nd is None {
        return [];
    }
    w = nd spawn AncestorWalker(
        claimed={},
        found=[],
        max_depth=depth,
        depths={},
        target_prefix=prefix,
        origin=record_id
    );
    print {"op": "ancestors", "prefix": prefix, "id": record_id, "count": len(w.found)};
    out: list[str] = [];
    for x in w.found {
        out.append(x);
    }
    return out;
}
