def partition_self_refs(cte_name: str, refs: list[str]) -> tuple[list[str], list[str]] {
    externals: list[str] = [];
    self_hits: list[str] = [];
    for r in refs {
        if r == cte_name {
            self_hits.append(r);
        } else {
            externals.append(r);
        }
    }
    return (sorted(externals), sorted(self_hits));
}

def is_analyzable(
    cte_name: str, anchor_refs: list[str], recursive_refs: list[str]
) -> bool {
    for a in anchor_refs {
        if a == cte_name {
            return False;
        }
    }
    for r in recursive_refs {
        if r == cte_name {
            return True;
        }
    }
    return False;
}

def build_cte_graph(
    ctes: dict[str, tuple[list[str], list[str]]]
) -> dict[str, CteSpec] {
    nodes: dict[str, CteSpec] = {};
    for name, pair in ctes.items() {
        anchor, recursive = pair;
        nd = CteSpec(
            name=name,
            anchor_refs=anchor,
            recursive_refs=recursive
        );
        root ++> nd;
        nodes[name] = nd;
    }
    for name, pair in ctes.items() {
        nd = nodes[name];
        anchor, recursive = pair;
        combined: list[str] = [];
        for x in anchor {
            combined.append(x);
        }
        for x in recursive {
            combined.append(x);
        }
        seen_e: dict[str, bool] = {};
        for dep in combined {
            if dep in nodes and dep not in seen_e {
                seen_e[dep] = True;
                child = nodes[dep];
                nd +>: Depends:+> child;
            }
        }
    }
    return nodes;
}

def cte_dependency_closure(
    ctes: dict[str, tuple[list[str], list[str]]], start: str
) -> list[str] {
    if start not in ctes {
        return [];
    }
    nodes = build_cte_graph(ctes);
    start_nd = nodes[start];
    w = start_nd spawn ClosureWalker(claimed={});
    return sorted(w.found);
}

def analyze_recursive_model(
    ctes: dict[str, tuple[list[str], list[str]]], target: str
) -> dict[str, object] {
    result: dict[str, object] = {};
    if target not in ctes {
        result["valid"] = False;
        result["closure"] = [];
        result["anchor"] = [];
        result["recursive"] = [];
        return result;
    }
    pair = ctes[target];
    anchor, recursive = pair;
    valid = is_analyzable(target, anchor, recursive);
    ext_a, _ = partition_self_refs(target, anchor);
    ext_r, _ = partition_self_refs(target, recursive);
    closure: list[str] = [];
    if valid {
        closure = cte_dependency_closure(ctes, target);
    }
    result["valid"] = valid;
    result["closure"] = closure;
    result["anchor"] = ext_a;
    result["recursive"] = ext_r;
    return result;
}
