"""devstein/langchain#21 — PythonREPL exec with split globals/locals breaks recursion."""

node PythonREPL {
    has globals: dict[str, int] = {};
    has locals: dict[str, int] = {};
}

node FibJob {
    has n: int;
    has result: int = -1;
}

node Binding {
    has name: str;
    has scope: str;
}

edge Spawns {}

walker BindReact {
    has claimed: dict[str, bool] = {};

    can react_bind with Binding entry {
        nid: str = here.scope + ":" + here.name;
        if nid in self.claimed {
            skip;
        }
        self.claimed[nid] = True;
        print("react", here.name, here.scope);
        disengage;
    }
}

walker FibCTE {
    has claimed: dict[str, bool] = {};
    has cache: dict[str, int] = {};

    can eval_fib with FibJob entry {
        ck: str = str(here.n);
        if ck in self.cache {
            here.result = self.cache[ck];
            disengage;
        }
        if ck in self.claimed {
            skip;
        }
        self.claimed[ck] = True;
        print("fib", here.n);
        if here.n <= 1 {
            here.result = here.n;
            self.cache[ck] = here.result;
            disengage;
        }
        left: FibJob = FibJob(n=here.n - 1);
        right: FibJob = FibJob(n=here.n - 2);
        root ++> left;
        root ++> right;
        here +>:Spawns:+> left;
        here +>:Spawns:+> right;
        sub: list[FibJob] = [];
        sub.append(left);
        sub.append(right);
        visit :0: sub else { disengage; };
        here.result = left.result + right.result;
        self.cache[ck] = here.result;
        disengage;
    }
}

def make_repl() -> PythonREPL {
    r: PythonREPL = PythonREPL();
    return r;
}

def bind_recursive_def(repl: PythonREPL, name: str) -> None {
    repl.locals[name] = 1;
    b: Binding = Binding(name=name, scope="local");
    root ++> b;
    wk: BindReact = b spawn BindReact(claimed={});
}

def lookup_global(repl: PythonREPL, name: str) -> int {
    if name in repl.globals {
        return repl.globals[name];
    }
    return -1;
}

def lookup_local(repl: PythonREPL, name: str) -> int {
    if name in repl.locals {
        return repl.locals[name];
    }
    return -1;
}

def fibonacci(n: int) -> int {
    job: FibJob = FibJob(n=n);
    root ++> job;
    wk: FibCTE = job spawn FibCTE(claimed={}, cache={});
    return job.result;
}

def run_recursive_fib(repl: PythonREPL, n: int) -> dict {
    out: dict = {};
    bind_recursive_def(repl, "fibonacci");
    if lookup_global(repl, "fibonacci") < 0 {
        out["ok"] = False;
        out["error"] = "NameError: name 'fibonacci' is not defined";
        out["value"] = -1;
        return out;
    }
    v: int = fibonacci(n);
    out["ok"] = True;
    out["error"] = "";
    out["value"] = v;
    return out;
}

def run_recursive_fib_shared(repl: PythonREPL, n: int) -> dict {
    out: dict = {};
    bind_recursive_def(repl, "fibonacci");
    repl.globals["fibonacci"] = 1;
    v: int = fibonacci(n);
    out["ok"] = True;
    out["error"] = "";
    out["value"] = v;
    return out;
}

def apply_shared_scope_hack(repl: PythonREPL) -> None {
    repl.globals = repl.locals;
}
