    if name in repl.locals {
        return repl.locals[name];
    }
    return -1;
}

def fibonacci(n: int) -> int {
    job: FibJob = FibJob(n=n);
    root ++> job;
    wk: FibCTE = job spawn FibCTE(claimed={}, cache={});
    return job.result;
}

