def _section_list(spec: dict, cte_name: str, section: str) -> list[str] {
    out: list[str] = [];
    cte_map = spec[cte_name] as dict;
    raw = cte_map[section] as list;
    for item in raw {
        out.append(item as str);
    }
    return out;
