def build_recursive_cte_graph(spec: dict) -> CteGraph {
    graph_root = CteGraph(graph_id="recursive_cte");
    root ++> graph_root;
    node_by_rid: dict[str, CteRef] = {};
    for cte_name in sorted(spec.keys() as list) {
        for section in ["anchor", "recursive"] {
            refs: list[str] = _section_list(spec, cte_name as str, section);
            for ref_name in refs {
                rid = (cte_name as str) + ":" + section + ":" + ref_name;
                if rid not in node_by_rid {
                    nd = CteRef(
                        rid=rid,
                        cte_name=ref_name,
                        section=section
                    );
                    graph_root ++> nd;
                    node_by_rid[rid] = nd;
                }
            }
        }
    }
    for cte_name in sorted(spec.keys() as list) {
        rec_refs: list[str] = _section_list(spec, cte_name as str, "recursive");
        for ref_name in rec_refs {
            src_rid = (cte_name as str) + ":recursive:" + ref_name;
            src = node_by_rid[src_rid] as CteRef;
            for tgt_section in ["anchor", "recursive"] {
                tgt_rid = ref_name + ":" + tgt_section + ":" + cte_name;
                if tgt_rid in node_by_rid {
                    tgt = node_by_rid[tgt_rid] as CteRef;
                    src +>:RefEdge:+> tgt;
                }
            }
            ext_rid = ref_name + ":anchor:" + ref_name;
            if ext_rid in node_by_rid {
                ext = node_by_rid[ext_rid] as CteRef;
                src +>:RefEdge:+> ext;
            }
        }
    }
    return graph_root;
}

def get_section_refs(graph_root: CteGraph, cte_name: str, section: str) -> list[str] {
    out: list[str] = [];
    pfx: str = cte_name + ":" + section + ":";
    pfx_len: int = len(pfx);
    for nd in [graph_root ->] {
        cref = nd as CteRef;
        if cref.section == section and len(cref.rid) >= pfx_len and cref.rid[0:pfx_len] == pfx {
            out.append(cref.cte_name);
        }
    }
    sorted_out: list[str] = sorted(out);
    return sorted_out;
}

