def _spawn_closure(graph_root: CteGraph, start_rid: str, section_filter: str) -> list[str] {
    start: CteRef = None;
    for nd in [graph_root ->] {
        cref = nd as CteRef;
        if cref.rid == start_rid {
            start = cref;
        }
