def transitive_recursive_closure(graph_root: CteGraph, cte_name: str) -> list[str] {
    seeds: list[str] = get_recursive_refs(graph_root, cte_name);
    seen: dict[str, bool] = {};
    out: list[str] = [];
    queue: list[str] = [];
    for seed in seeds {
        queue.append(seed);
    }
    while queue {
        cur = queue[0];
        new_queue: list[str] = [];
        for item in queue[1:] {
            new_queue.append(item);
        }
        queue = new_queue;
        if cur in seen {
            continue;
        }
        seen[cur] = True;
        out.append(cur);
        for ref_name in get_recursive_refs(graph_root, cur) {
            queue.append(ref_name);
        }
    }
    sorted_out: list[str] = sorted(out);
    return sorted_out;
}

def validate_recursive_cte(graph_root: CteGraph, cte_name: str) -> bool {
    anchors = get_anchor_refs(graph_root, cte_name);
    recursive = get_recursive_refs(graph_root, cte_name);
    if not anchors {
        return False;
    }
    if not recursive {
        return False;
    }
    has_self: bool = False;
    for ref_name in recursive {
        if ref_name == cte_name {
            has_self = True;
        }
    }
    return has_self;
}

def analyze_recursive_cte(graph_root: CteGraph, cte_name: str) -> dict {
