def find_scope(cid: str) -> Scope {
    for nd in [root -->][?:Scope] {
        if nd.cid == cid {
            return nd;
        }
    }
    miss = Scope(cid="__none__");
    return miss;
}

def make_python_repl(unified: bool) -> Repl {
    g = Scope(cid="globals");
    root ++> g;
    loc = Scope(cid="locals");
    root ++> loc;
    r = Repl(
        cid="repl",
        global_scope="globals",
        local_scope="locals",
        unified=unified
    );
    root ++> r;
    return r;
}

def install_fibonacci(repl: Repl) -> None {
    loc = find_scope(repl.local_scope);
    loc.fn_name = "fibonacci";
    loc.fn_ready = True;
    if repl.unified {
        g = find_scope(repl.global_scope);
        g.fn_name = "fibonacci";
        g.fn_ready = True;
    }
}

def recursive_name_visible(repl: Repl) -> bool {
    g = find_scope(repl.global_scope);
    if g.fn_ready {
        return True;
    }
    return False;
}

def unify_python_repl_namespaces(repl: Repl) -> Repl {
    repl.unified = True;
    loc = find_scope(repl.local_scope);
    g = find_scope(repl.global_scope);
    g.fn_name = loc.fn_name;
    g.fn_ready = loc.fn_ready;
    return repl;
}

