"""effect-gates task dependency queue — cycle-safe add + topological run.

Provenance: lucianfialho/effect-gates#58
"""

import from collections { defaultdict }

node Task {
    has tid: str;
    has done: bool = False;
}

edge Depends {}

node TaskGraph {
    has tasks: dict[str, Task] = {};
}

walker CycleProbe {
    has target: str;
    has found: bool = False;
    has claimed: dict[str, bool] = {};

    can chase with Task entry {
        if here.tid == self.target {
            self.found = True;
            disengage;
        }
        if here.tid in self.claimed {
            skip;
        }
        self.claimed[here.tid] = True;
        deps: list[Task] = [here ->:Depends:->][?:Task];
        for dep in deps {
            visit dep;
        }
        disengage;
    }
}

walker ReadyCollect {
    has ready: list[str] = [];
    has claimed: dict[str, bool] = {};

    can gather with TaskGraph entry {
        kids: list[Task] = [here -->][?:Task];
        for kid in kids {
            visit kid;
        }
        disengage;
    }

    can scan with Task entry {
        if here.tid in self.claimed {
            skip;
        }
        self.claimed[here.tid] = True;
        if not here.done {
            all_ready = True;
            deps: list[Task] = [here ->:Depends:->][?:Task];
            for dep in deps {
                if not dep.done {
                    all_ready = False;
                }
            }
            if all_ready {
                self.ready.append(here.tid);
            }
        }
        disengage;
    }
}

walker Demo {
    has ran: list[str] = [];

    can run with TaskGraph entry {
        print("effect-gates#58 demo");
        g = create_queue();
        add_task(g, "a", []);
        add_task(g, "b", ["a"]);
        add_task(g, "c", ["b"]);
        self.ran = run_all(g);
        print(self.ran);
        disengage;
    }
}

def create_queue() -> TaskGraph {
    g = TaskGraph();
    root ++> g;
    return g;
}

def _deps_have_dupes(deps: list[str]) -> bool {
    seen: dict[str, bool] = {};
    for dep_id in deps {
        if dep_id in seen {
            return True;
        }
        seen[dep_id] = True;
    }
    return False;
}

def _would_cycle(graph: TaskGraph, task_id: str, deps: list[str]) -> bool {
    for dep_id in deps {
        if dep_id not in graph.tasks {
            continue;
        }
        dep_node = graph.tasks[dep_id];
        w = dep_node spawn CycleProbe(target=task_id, claimed={});
        if w.found {
            return True;
        }
    }
    return False;
}

def add_task(graph: TaskGraph, task_id: str, deps: list[str]) -> bool {
    if task_id in graph.tasks {
        return False;
    }
    if _deps_have_dupes(deps) {
        return False;
    }
    if task_id in deps {
        return False;
    }
    for dep_id in deps {
        if dep_id not in graph.tasks {
            return False;
        }
    }
    if _would_cycle(graph, task_id, deps) {
        return False;
    }
    t = Task(tid=task_id);
    graph ++> t;
    graph.tasks[task_id] = t;
    for dep_id in deps {
        dep_node = graph.tasks[dep_id];
        t +>:Depends:+> dep_node;
    }
    return True;
}

def complete_task(graph: TaskGraph, task_id: str) -> bool {
    if task_id not in graph.tasks {
        return False;
    }
    graph.tasks[task_id].done = True;
    return True;
}

def get_ready(graph: TaskGraph) -> list[str] {
    w = graph spawn ReadyCollect(claimed={});
    ready = w.ready;
    ready.sort();
    return ready;
}

def run_all(graph: TaskGraph) -> list[str] {
    order: list[str] = [];
    while True {
        batch = get_ready(graph);
        if len(batch) == 0 {
            break;
        }
        for tid in batch {
