"""Reachability bipartite graph assembly — fmaguire/Bridger_Assembler#4."""

node BPNode {
    has nid: str;
    has color: int = -1;
}

edge DLink {}
edge ULink {}

walker BipartiteWalker {
    has claimed: dict[str, bool] = {};
    has colors: dict[str, int] = {};
    has ok: bool = True;

    can paint with BPNode entry {
        if here.nid in self.claimed {
            skip;
        }
        self.claimed[here.nid] = True;
        if here.nid not in self.colors {
            self.colors[here.nid] = 0;
        }
        print(f"paint {here.nid}");
        nbrs: list[BPNode] = [here ->:ULink:->][?:BPNode];
        nxt: list[BPNode] = [];
        for nb in nbrs {
            if nb.nid in self.colors {
                if self.colors[nb.nid] == self.colors[here.nid] {
                    self.ok = False;
                }
            } else {
                self.colors[nb.nid] = 1 - self.colors[here.nid];
                nxt.append(nb);
            }
        }
        if len(nxt) > 0 {
            visit nxt;
        } else {
            disengage;
        }
    }
}

walker ReachWalker {
    has claimed: dict[str, bool] = {};
    has found: list[str] = [];

    can bfs with BPNode entry {
        if here.nid in self.claimed {
            skip;
        }
        self.claimed[here.nid] = True;
        self.found.append(here.nid);
        print(f"bfs {here.nid}");
        nbrs: list[BPNode] = [here ->:DLink:->][?:BPNode];
        nids: list[str] = [];
        for nb in nbrs {
            nids.append(nb.nid);
        }
        nids = sorted(nids);
        batch: list[BPNode] = [];
        for sn in nids {
            for nb in nbrs {
                if nb.nid == sn and nb.nid not in self.claimed {
                    batch.append(nb);
                }
            }
        }
        if len(batch) > 0 {
            visit batch;
        } else {
            disengage;
        }
    }
}

walker TopoWalker {
    has claimed: dict[str, bool] = {};
    has order: list[str] = [];

    can step with BPNode entry {
        if here.nid in self.claimed {
            skip;
        }
        self.claimed[here.nid] = True;
        self.order.append(here.nid);
        print(f"dfs {here.nid}");
        kids: list[BPNode] = [here ->:DLink:->][?:BPNode];
        kid_nids: list[str] = [];
        for kd in kids {
            kid_nids.append(kd.nid);
        }
        kid_nids = sorted(kid_nids);
        sorted_kids: list[BPNode] = [];
        for kn in kid_nids {
            for kd in kids {
                if kd.nid == kn {
                    sorted_kids.append(kd);
                }
            }
        }
        if len(sorted_kids) > 0 {
            visit :0: sorted_kids;
        } else {
            disengage;
        }
    }
}

def _build_directed(node_ids: list[str], edge_pairs: list[list[str]]) -> dict[str, BPNode] {
    index: dict[str, BPNode] = {};
    for nid in node_ids {
        nd = BPNode(nid=nid);
        root ++> nd;
        index[nid] = nd;
    }
    for ep in edge_pairs {
        if len(ep) >= 2 {
            u = ep[0];
            v = ep[1];
            if u in index and v in index {
                a = index[u] as BPNode;
                b = index[v] as BPNode;
                a +>:DLink:+> b;
            }
        }
    }
    return index;
}

def _build_undirected(node_ids: list[str], edge_pairs: list[list[str]]) -> dict[str, BPNode] {
    index: dict[str, BPNode] = {};
    for nid in node_ids {
        nd = BPNode(nid=nid);
        root ++> nd;
        index[nid] = nd;
    }
    for ep in edge_pairs {
        if len(ep) >= 2 {
            u = ep[0];
            v = ep[1];
            if u in index and v in index {
                a = index[u] as BPNode;
                b = index[v] as BPNode;
                a +>:ULink:+> b;
                b +>:ULink:+> a;
            }
        }
    }
    return index;
}

def is_bipartite_graph(node_ids: list[str], edges: list[list[str]]) -> bool {
    if len(node_ids) == 0 {
        return True;
    }
    index = _build_undirected(node_ids, edges);
    colors: dict[str, int] = {};
    ok = True;
    for nid in sorted(node_ids) {
        if nid not in colors {
            nd = index[nid] as BPNode;
            wk = nd spawn BipartiteWalker(claimed={}, colors=colors, ok=ok);
            colors = wk.colors;
            ok = wk.ok;
            if not ok {
                return False;
            }
        }
    }
    return ok;
}

def bfs_reachable_nodes(node_ids: list[str], edges: list[list[str]], source: str) -> list[str] {
    index = _build_directed(node_ids, edges);
    if source not in index {
        return [];
    }
    src = index[source] as BPNode;
    wk = src spawn ReachWalker(claimed={}, found=[]);
    return wk.found;
}

def dfs_topology_order(node_ids: list[str], edges: list[list[str]]) -> list[str] {
    if len(node_ids) == 0 {
        return [];
    }
    index = _build_directed(node_ids, edges);
    start_nid = sorted(node_ids)[0];
    start_nd = index[start_nid] as BPNode;
    wk = start_nd spawn TopoWalker(claimed={}, order=[]);
    return wk.order;
}

def transitive_reachability_pairs(node_ids: list[str], edges: list[list[str]]) -> list[list[str]] {
    pairs: list[list[str]] = [];
    for src in sorted(node_ids) {
        reach = bfs_reachable_nodes(node_ids, edges, src);
        for dst in reach {
            if src != dst {
                row: list[str] = [];
                row.append(src);
                row.append(dst);
                pairs.append(row);
            }
        }
    }
    pairs = sorted(pairs);
    return pairs;
}
