        if here.cid != self.origin {
            self.found.append(here.cid);
        }
        if len(nxt) > 0 {
            visit :> nxt;
        } else {
            disengage;
        }
    }
}

def ensure_node(h: GraphHandle, cid: str) -> N {
    if cid in h.node_by_cid {
        return h.node_by_cid[cid];
    }
    nd = N(cid=cid);
    h.root_node ++> nd;
    h.node_by_cid[cid] = nd;
    return nd;
}

def make_graph() -> GraphHandle {
    h = GraphHandle(root_node=root, node_by_cid={});
    return h;
}

def load_edges(h: GraphHandle, edges: list[tuple[str, str]]) -> None {
    for p in edges {
        src = ensure_node(h, p[0]);
        dst = ensure_node(h, p[1]);
        src +>:Ref:+> dst;
    }
}

def set_tiers(h: GraphHandle, tiers: dict[str, int]) -> None {
    for k in tiers {
        nd = ensure_node(h, k);
        nd.tier = tiers[k];
    }
}

def edge_count(h: GraphHandle) -> int {
    n = 0;
    for nd in [h.root_node -->][?:N] {
        refs: list[N] = [nd ->:Ref:->][?:N];
        n += len(refs);
    }
    return n;
}

def blast_radius(h: GraphHandle, start_id: str, max_depth: int = -1) -> list[str] {
    if start_id not in h.node_by_cid {
        return [];
    }
    start_nd = h.node_by_cid[start_id];
    depths: dict[str, int] = {};
    depths[start_id] = 0;
    w = start_nd spawn BlastW(
        claimed={},
        found=[],
        depth_lim=max_depth,
        origin=start_id,
        depths=depths
    );
    print("blast", start_id, len(w.found));
    out: list[str] = [];
    for x in w.found {
        out.append(x);
    }
    sorted(out);
    return out;
}

def blast_radius_filtered(
    h: GraphHandle,
    start_id: str,
    min_tier: int,
    max_depth: int = -1
) -> list[str] {
    raw = blast_radius(h, start_id, max_depth);
    kept: list[str] = [];
    for cid in raw {
        if cid in h.node_by_cid {
            nd = h.node_by_cid[cid];
            if nd.tier >= min_tier {
                kept.append(cid);
            }
        }
    }
    sorted(kept);
    return kept;
}
