walker collect_ancestors {
    has claimed: dict[str, bool] = {};
    has result: list[str] = [];
    has max_depth: int = 10;
    has depth: int = 0;

    can climb with Group entry {
        if here.gid in self.claimed { skip; }
        self.claimed[here.gid] = True;
        print ["ancestor", here.gid, self.depth];
        self.result.append(here.gid);
        if self.depth >= self.max_depth { disengage; }
        parents: list[Group] = [here <-:child_link:<-][?:Group];
        nd: list[Group] = [];
        for p in parents {
            nd.append(p);
        }
        if nd {
            self.depth += 1;
            visit :0: nd else { disengage; }
        } else {
            disengage;
        }
    }
}

