"""ent/ent#2167 — phased recursive undeleted traversal (anchor ORDER/LIMIT vs recursive ORDER/LIMIT)."""

node File {
    has cid: str;
    has name: str;
    has deleted: bool = False;
}

edge Child {}

obj FsHandle {
    has graph_root: File;
}

walker FindByCid {
    has target: str;
    has found: File | None = None;
    has claimed: dict[str, bool] = {};

    can seek with File entry {
        if here.cid == "__root__" {
            disengage;
        }
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        if here.cid == self.target {
            self.found = here;
            disengage;
        }
        nxt: list[File] = [];
        for ch in [here ->:Child:->][?:File] {
            nxt.append(ch);
        }
        visit nxt;
    }
}

walker UndeletedWalk {
    has claimed: dict[str, bool] = {};
    has order_key: str = "name";
    has expand_limit: int = -1;
    has names: list[str] = [];

    can step with File entry {
        if here.cid == "__root__" {
            disengage;
        }
        if here.deleted {
            disengage;
        }
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        self.names.append(here.name);
        kids: list[File] = [];
        for ch in [here ->:Child:->][?:File] {
            if ch.cid != "__root__" {
                kids.append(ch);
            }
        }
        kids = sort_files(kids, self.order_key);
        taken: int = 0;
        for kid in kids {
            if self.expand_limit >= 0 and taken >= self.expand_limit {
                break;
            }
            visit :0: [kid];
            taken += 1;
        }
    }
}

def sort_key_val(f: File, key: str) -> str {
    if key == "deleted" {
        if f.deleted {
            return "1";
        }
        return "0";
    }
    if key == "id" {
        return f.cid;
    }
    return f.name;
}

def sort_files(files: list[File], key: str) -> list[File] {
    pairs: list[list] = [];
    for f in files {
        pairs.append([sort_key_val(f, key), f]);
    }
    pairs = sorted(pairs);
    out: list[File] = [];
    for p in pairs {
        out.append(p[1]);
    }
    return out;
}

def find_by_cid(graph_root: File, target: str) -> File | None {
    w = graph_root spawn FindByCid(target=target);
    return w.found;
}

def make_handle() -> FsHandle {
    r = File(cid="__root__", name="__root__");
    root ++> r;
    return FsHandle(graph_root=r);
}

def add_file(
    h: FsHandle,
    cid: str,
    name: str,
    parent_cid: str | None = None,
    deleted: bool = False,
) -> None {
    nd = File(cid=cid, name=name, deleted=deleted);
    if parent_cid is None {
        h.graph_root +>:Child:+> nd;
        return;
    }
    par = find_by_cid(h.graph_root, parent_cid);
    if par is None {
        return;
    }
    par +>:Child:+> nd;
}

def connect_files(h: FsHandle, parent_cid: str, child_cid: str) -> None {
    par = find_by_cid(h.graph_root, parent_cid);
    ch = find_by_cid(h.graph_root, child_cid);
    if par is None or ch is None {
        return;
    }
    par +>:Child:+> ch;
}

def recursive_undeleted_names(
    h: FsHandle,
    initial_order: str,
    initial_limit: int,
    recursive_order: str,
    recursive_limit: int,
) -> list[str] {
    anchors: list[File] = [];
    for ch in [h.graph_root ->:Child:->][?:File] {
        if not ch.deleted {
            anchors.append(ch);
        }
    }
    anchors = sort_files(anchors, initial_order);
    if initial_limit >= 0 {
        trimmed: list[File] = [];
        i: int = 0;
        for a in anchors {
            if i >= initial_limit {
                break;
            }
            trimmed.append(a);
            i += 1;
        }
        anchors = trimmed;
    }
    out: list[str] = [];
    shared: dict[str, bool] = {};
    for a in anchors {
        w = a spawn UndeletedWalk(
            claimed=shared,
            order_key=recursive_order,
            expand_limit=recursive_limit,
        );
        shared = w.claimed;
        for nm in w.names {
            out.append(nm);
        }
    }
    return out;
}
