def find_path(graph_root: TaskRoot, start_id: str, end_id: str) -> list[str] {
    start_nd = find_task_node(graph_root, start_id);
    if start_nd is None { return []; }
    w = start_nd spawn PathBfs(target=end_id, claimed={});
    if not w.found_target { return []; }
    rev: list[str] = [];
    cur: str = end_id;
    while cur != "" {
        rev.append(cur);
        if cur == start_id { break; }
        if cur in w.parent_of {
            cur = w.parent_of[cur] as str;
        } else {
            return [];
        }
    }
    if len(rev) == 0 or rev[len(rev) - 1] != start_id { return []; }
    out: list[str] = [];
    i = len(rev) - 1;
    while i >= 0 {
        out.append(rev[i]);
        i = i - 1;
    }
    return out;
}

def add_dependency(graph_root: TaskRoot, task_id: str, depends_on_id: str) -> bool {
