        if nd is None { continue; }
        if nd.archived { continue; }
        blockers: list[Task] = [nd ->:Dep:->][?:Task];
        blocked = False;
        for bl in blockers {
            if not bl.done { blocked = True; break; }
        }
        if not blocked { ready.append(tid); }
    }
    return sorted(ready);
}

def resolve_short_id(graph_root: TaskRoot, prefix: str) -> str {
    w = graph_root spawn TaskScan(claimed={});
    matches: list[str] = [];
    for tid in w.hits {
        nd = find_task_node(graph_root, tid);
        if nd is None { continue; }
        if nd.short_id == prefix {
            matches.append(tid);
        }
    }
    if len(matches) == 0 { raise ValueError("no match"); }
    if len(matches) > 1 { raise ValueError("ambiguous"); }
    return matches[0];
}

def delete_task_cascade(graph_root: TaskRoot, task_id: str) -> list[str] {
