    nd = HierarchyNode(nid=node_id);
    if store.anchor is None {
        store.anchor = HierarchyNode(nid="__anchor__");
    }
    store.anchor ++> nd;
    store.nodes_by_id[node_id] = nd;
    return nd;
}

def _rewire_parent_edge(store: ClosureStore, node_id: str, parent_id: str | None) -> None {
    child_nd = store.nodes_by_id[node_id];
    preds: list[HierarchyNode] = [];
    for pred in [child_nd <-:ParentEdge:<-][?:HierarchyNode] {
        preds.append(pred);
    }
    for pred in preds {
        pred -:ParentEdge:- child_nd;
    }
    if parent_id is not None {
        store.nodes_by_id[parent_id] +>:ParentEdge:+> child_nd;
    }
}

def _detach_subtree_closure(store: ClosureStore, node_id: str) -> None {
    descendants: list[str] = [];
    for child in store.closure {
        child_row = store.closure[child];
        if node_id in child_row {
            descendants.append(child);
        }
    }
    ancestors: list[str] = [];
    node_row = store.closure[node_id];
    for anc in node_row {
        if anc != node_id {
            ancestors.append(anc);
        }
    }
    for child in descendants {
        child_row = store.closure[child];
        kept: dict[str, int] = {};
        for anc in child_row {
            if anc not in ancestors {
                kept[anc] = child_row[anc];
            }
        }
        store.closure[child] = kept;
    }
}

def _attach_subtree_to_parent(store: ClosureStore, node_id: str, parent_id: str) -> None {
    subtree: list[tuple[str, int]] = [];
    for child in store.closure {
        child_row = store.closure[child];
        if node_id in child_row {
            subtree.append((child, child_row[node_id]));
        }
    }
    parent_row = store.closure[parent_id];
    parent_anc: list[tuple[str, int]] = [];
    for anc in parent_row {
        parent_anc.append((anc, parent_row[anc] + 1));
    }
    for pair in subtree {
        child = pair[0];
        d_c = pair[1];
        child_row = store.closure[child];
        for anc_pair in parent_anc {
            anc = anc_pair[0];
            d_a = anc_pair[1];
            child_row[anc] = d_c + d_a;
        }
    }
}

def rebuild_closure(store: ClosureStore, parent_map: dict[str, str | None]) -> None {
    store.parent_of = {};
    store.closure = {};
    store.nodes_by_id = {};
    pending: list[str] = [];
    for nid in parent_map {
        pending.append(nid);
        store.parent_of[nid] = parent_map[nid];
    }
    while len(pending) > 0 {
        progressed = False;
        next_pending: list[str] = [];
        for nid in pending {
            pid = store.parent_of[nid];
            if pid is not None and pid not in store.closure {
                next_pending.append(nid);
            } else {
                row = _closure_touch(store, nid);
                row[nid] = 0;
                if pid is not None {
                    parent_row = store.closure[pid];
                    for anc in parent_row {
                        row[anc] = parent_row[anc] + 1;
                    }
                }
                progressed = True;
            }
        }
        pending = next_pending;
        if not progressed {
            break;
        }
    }
    if store.anchor is None {
        store.anchor = HierarchyNode(nid="__anchor__");
    }
    ids: list[str] = [];
    for nid in store.parent_of {
        ids.append(nid);
    }
    ids.sort();
    for nid in ids {
        _ensure_graph_node(store, nid);
    }
    for nid in ids {
        pid = store.parent_of[nid];
        if pid is not None {
            store.nodes_by_id[pid] +>:ParentEdge:+> store.nodes_by_id[nid];
        }
    }
}

def insert_node(store: ClosureStore, node_id: str, parent_id: str | None = None) -> bool {
    if node_id in store.parent_of {
        return False;
    }
    if parent_id is not None and parent_id not in store.parent_of {
        return False;
    }
    store.parent_of[node_id] = parent_id;
    row = _closure_touch(store, node_id);
    row[node_id] = 0;
    if parent_id is not None {
        parent_row = store.closure[parent_id];
        for anc in parent_row {
            row[anc] = parent_row[anc] + 1;
        }
    }
    _ensure_graph_node(store, node_id);
    if parent_id is not None {
        store.nodes_by_id[parent_id] +>:ParentEdge:+> store.nodes_by_id[node_id];
    }
    return True;
}

def move_node(store: ClosureStore, node_id: str, new_parent_id: str | None) -> bool {
    if node_id not in store.parent_of {
        return False;
    }
    if new_parent_id is not None and new_parent_id not in store.parent_of {
        return False;
    }
    old_parent = store.parent_of[node_id];
    if old_parent == new_parent_id {
        return True;
    }
    if new_parent_id is not None {
        sub_row = store.closure[node_id];
        if new_parent_id in sub_row {
            return False;
        }
    }
    _detach_subtree_closure(store, node_id);
    store.parent_of[node_id] = new_parent_id;
    if new_parent_id is not None {
        _attach_subtree_to_parent(store, node_id, new_parent_id);
    }
    _rewire_parent_edge(store, node_id, new_parent_id);
    return True;
}

def ancestors_of(store: ClosureStore, node_id: str) -> list[tuple[str, int]] {
    if node_id not in store.closure {
        return [];
    }
    out: list[tuple[str, int]] = [];
    row = store.closure[node_id];
    for anc in row {
        if anc != node_id {
            out.append((anc, row[anc]));
        }
    }
    out.sort();
    return out;
}

def descendants_of(store: ClosureStore, node_id: str) -> list[tuple[str, int]] {
    if node_id not in store.parent_of {
        return [];
    }
    out: list[tuple[str, int]] = [];
    for child in store.closure {
        row = store.closure[child];
        if node_id in row {
            depth = row[node_id];
            if depth > 0 {
                out.append((child, depth));
            }
        }
    }
    out.sort();
    return out;
}

def collect_subtree_ids(store: ClosureStore, node_id: str) -> list[str] {
    if node_id not in store.nodes_by_id {
        return [];
    }
    nd = store.nodes_by_id[node_id];
    w = nd spawn SubtreeWalker(origin=node_id, claimed={});
    out: list[str] = [];
    for item in w.collected {
        out.append(item);
    }
    out.sort();
    return out;
}
