def new_store -> dict[str, Topic] {
  store: dict[str, Topic] = {};
  return store;
}

def add_topic(
  store: dict[str, Topic],
  tid: str,
  title: str,
  section: int,
  status: str = "pending"
) -> None {
  if tid in store {
    return;
  }
  t = Topic(tid=tid, title=title, section=section, status=status);
  store[tid] = t;
  root ++> t;
}

def add_prerequisite(
  store: dict[str, Topic],
  before_tid: str,
  after_tid: str
) -> None {
  if before_tid not in store {
    return;
  }
  if after_tid not in store {
    return;
  }
  before = store[before_tid];
  after = store[after_tid];
  before +>:Prereq:+> after;
}

def mark_complete(store: dict[str, Topic], tid: str) -> None {
  if tid not in store {
    return;
  }
  store[tid].status = "completed";
}

def topic_status(store: dict[str, Topic], tid: str) -> str {
  if tid not in store {
    return "unknown";
  }
  return store[tid].status;
}

def pending_tids(store: dict[str, Topic]) -> list[str] {
  out: list[str] = [];
  for tid in sorted(store.keys()) {
    if store[tid].status != "completed" {
      out.append(tid);
    }
  }
  return out;
}

def completed_tids(store: dict[str, Topic]) -> list[str] {
  out: list[str] = [];
  for tid in sorted(store.keys()) {
    if store[tid].status == "completed" {
      out.append(tid);
    }
  }
  return out;
}

def _roots(store: dict[str, Topic]) -> list[Topic] {
  ranked: list[tuple[int, str, Topic]] = [];
  for tid in sorted(store.keys()) {
    t = store[tid];
    prereqs: list[Topic] = [t <-:Prereq:<-][?:Topic];
    if len(prereqs) == 0 {
      ranked.append((t.section, t.tid, t));
    }
  }
  ranked.sort();
  out: list[Topic] = [];
  for row in ranked {
    out.append(row[2]);
  }
  return out;
}

def learning_order(store: dict[str, Topic]) -> list[str] {
  merged: list[str] = [];
  merged_claimed: dict[str, bool] = {};
  roots = _roots(store);
  if len(roots) == 0 {
    if len(store.keys()) == 0 {
      return [];
    }
    first_tid = sorted(store.keys())[0];
    roots = [store[first_tid]];
  }
  for rt in roots {
    if rt.tid in merged_claimed {
      continue;
    }
    wk = rt spawn TopicDfsWalker(claimed=merged_claimed);
    for tid in wk.order {
      if tid not in merged_claimed {
        merged.append(tid);
        merged_claimed[tid] = True;
      }
    }
    merged_claimed = wk.claimed;
  }
  extras: list[str] = [];
  for tid in sorted(store.keys()) {
    if tid not in merged_claimed {
      extras.append(tid);
    }
  }
  for tid in extras {
    merged.append(tid);
  }
  return merged;
}

def has_prerequisite_cycle(store: dict[str, Topic]) -> bool {
  if len(store.keys()) == 0 {
    return False;
  }
  for tid in sorted(store.keys()) {
    wk = store[tid] spawn CycleDetectWalker(active={}, cyclic=False);
    if wk.cyclic {
      return True;
    }
  }
  return False;
}

def topics_reachable(store: dict[str, Topic], start_tid: str) -> list[str] {
  if start_tid not in store {
    return [];
  }
  start = store[start_tid];
  wk = start spawn ReachWalker(claimed={}, reached=[]);
  return sorted(wk.reached);
}

