def make_store -> TaskStore {
    by: dict[str, Task] = {};
    return TaskStore(by_id=by);
}

def create_task(store: TaskStore, tid: str, title: str = "") -> Task {
    sid: str = tid;
    if len(tid) >= 6 { sid = tid[0:6]; }
    t = Task(id=tid, title=title, short_id=sid);
    store.by_id[tid] = t;
    root ++> t;
    return t;
}

def get_task(store: TaskStore, tid: str) -> Task {
    if tid not in store.by_id { raise ValueError("unknown task"); }
    return store.by_id[tid];
}

def set_parent(store: TaskStore, child_id: str, parent_id: str) -> None {
    child = get_task(store, child_id);
    parent = get_task(store, parent_id);
    parent +>:Child:+> child;
}

def has_incomplete_blocker(store: TaskStore, t: Task) -> bool {
    deps: list[Task] = [t ->:Depends:->][?:Task];
    for dep in deps {
        if not dep.done { return True; }
    }
    return False;
}

def find_path(store: TaskStore, from_id: str, to_id: str) -> list[str] | None {
    if from_id not in store.by_id { return None; }
    if to_id not in store.by_id { return None; }
    if from_id == to_id { return [from_id]; }
    start = store.by_id[from_id];
    w = start spawn BfsPath(
        target=to_id,
        start_id=from_id,
        claimed={},
        parent_map={},
        result=[]
    );
    if w.found { return w.result; }
    return None;
}

def add_dependency(store: TaskStore, task_id: str, depends_on_id: str) -> None {
    task = get_task(store, task_id);
    dep = get_task(store, depends_on_id);
    back = find_path(store, depends_on_id, task_id);
    if back is not None { raise ValueError("dependency cycle"); }
    task +>:Depends:+> dep;
}

def get_blockers(store: TaskStore, task_id: str) -> list[str] {
    t = get_task(store, task_id);
    out: list[str] = [];
    deps: list[Task] = [t ->:Depends:->][?:Task];
    for dep in deps {
        if not dep.done { out.append(dep.id); }
    }
    out.sort();
    return out;
}

def list_ready(store: TaskStore) -> list[str] {
    out: list[str] = [];
    keys: list[str] = [];
    for k in store.by_id.keys() { keys.append(k); }
    keys.sort();
    for tid in keys {
        t = store.by_id[tid];
        if t.archived { continue; }
        if t.done { continue; }
        if has_incomplete_blocker(store, t) { continue; }
        out.append(tid);
    }
    return out;
}

def resolve_short_id(store: TaskStore, prefix: str) -> str {
    matches: list[str] = [];
    for tid in store.by_id.keys() {
        t = store.by_id[tid];
        if t.id.startswith(prefix) { matches.append(tid); continue; }
        if t.short_id.startswith(prefix) { matches.append(tid); }
    }
    matches.sort();
    if len(matches) == 0 { raise ValueError("not found"); }
    if len(matches) > 1 { raise ValueError("ambiguous"); }
    return matches[0];
}

def update_task(store: TaskStore, tid: str, done: bool | None = None) -> Task {
    t = get_task(store, tid);
    if done is not None { t.done = done; }
    return t;
}

def delete_task(store: TaskStore, tid: str, cascade: bool = False) -> None {
    t = get_task(store, tid);
    to_del: list[str] = [tid];
    if cascade {
        w = t spawn CollectDescendants(claimed={}, ids=[]);
        to_del = w.ids;
    }
    for did in to_del {
        if did in store.by_id { del store.by_id[did]; }
    }
}
