def build_workspace_graph(edges: list) -> WorkspaceGraph {
    gr = GraphRoot();
    root ++> gr;
    handle = WorkspaceGraph(graph_root=gr);
    for row in edges {
        wid: str = row[0];
        if wid not in handle.by_id {
            ws = Workspace(ws_id=wid, name=wid);
            handle.by_id[wid] = ws;
            gr ++> ws;
        }
    }
    for row in edges {
        wid: str = row[0];
        src = handle.by_id[wid];
        i: int = 1;
        while i < len(row) {
            dep_id: str = row[i];
            if dep_id not in handle.by_id {
                dep_nd = Workspace(ws_id=dep_id, name=dep_id);
                handle.by_id[dep_id] = dep_nd;
                gr ++> dep_nd;
            }
            tgt = handle.by_id[dep_id];
            src +>:Depends:+> tgt;
            i += 1;
        }
    }
    return handle;
}

def detect_dependency_cycles(graph: WorkspaceGraph, enabled: bool = True) -> list[list[str]] {
    if not enabled {
        return [];
    }
    wk = graph.graph_root spawn CycleCollect(enabled=True);
    out: list[list[str]] = [];
    for raw in wk.found {
        norm: list[str] = sorted(raw);
        out.append(norm);
    }
    out = sorted(out);
    return out;
}

def workspace_run_order(
    graph: WorkspaceGraph,
    start_id: str,
    recursive: bool = False,
    cycle_detection: bool = True,
) -> list[str] {
    if cycle_detection {
        hits = detect_dependency_cycles(graph, True);
        if len(hits) > 0 {
            raise ValueError("dependency cycle detected");
        }
    }
    if start_id not in graph.by_id {
        return [];
    }
    start_nd = graph.by_id[start_id];
    wk = start_nd spawn VisitCollect(recursive=recursive);
    res: list[str] = [];
    for x in wk.order {
        res.append(x);
    }
    return res;
}
