walker DescendantClosureWalker {
    has closure: list[str] = [];
    has claimed: dict[str, bool] = {};

    can descend with Schema entry {
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        self.closure.append(here.cid);
        subs: list[Schema] = [here <-:Extends:<-][?:Schema];
        visit :0: subs;
        if not subs {
            print({"closure": self.closure});
            disengage;
        }
    }
}

def find_schema(graph_root: object, cid: str) -> Schema | None {
    w = graph_root spawn FindSchemaWalker(want=cid);
    return w.result;
}

def detect_extends_cycle(graph_root: object, schema_id: str, parent_id: str) -> bool {
    start = find_schema(graph_root, parent_id);
    if start is None {
        return False;
    }
    w = start spawn ExtendsCycleWalker(target=schema_id);
    return w.found;
}

def resolve_effective_fields(graph_root: object, schema_id: str) -> list[str] {
    nd = find_schema(graph_root, schema_id);
    if nd is None {
        return [];
    }
    merged: list[str] = [];
    parents: list[Schema] = [nd ->:Extends:->][?:Schema];
    for p in parents {
        pw = p spawn EffectiveFieldWalker();
        for nm in pw.names {
            dup: bool = False;
            for m in merged {
                if m == nm {
                    dup = True;
                }
            }
            if not dup {
                merged.append(nm);
            }
        }
    }
    for nm in nd.fields {
        dup2: bool = False;
        for m in merged {
            if m == nm {
                dup2 = True;
            }
        }
        if not dup2 {
            merged.append(nm);
        }
    }
    return merged;
}

def validate_declared_fields(graph_root: object, schema_id: str, new_fields: list[str]) -> bool {
    nd = find_schema(graph_root, schema_id);
    if nd is None {
        return True;
    }
    eff = resolve_effective_fields(graph_root, schema_id);
    for nf in new_fields {
        for ef in eff {
            if nf != ef {
                continue;
            }
            in_own: bool = False;
            for of in nd.fields {
                if of == nf {
                    in_own = True;
                }
            }
            if not in_own {
                return False;
            }
        }
    }
    return True;
}

def instance_node_type(graph_root: object, schema_id: str) -> str {
    nd = find_schema(graph_root, schema_id);
    if nd is None {
        return "";
    }
    return nd.cid;
}

def extends_descendant_closure(graph_root: object, schema_id: str) -> list[str] {
    nd = find_schema(graph_root, schema_id);
    if nd is None {
        return [];
    }
    w = nd spawn DescendantClosureWalker();
    return sorted(w.closure);
}
