"""rayhuang2006/asymptote#25 — DFS/BFS adjacency traversal & recursion pattern hints."""

node Vertex {
    has vid: str;
}

edge Arc {}

node GraphHandle {
    has vertices: dict[str, Vertex] = {};
}

walker DfsWalker {
    has claimed: dict[str, bool] = {};
    has order: list[str] = [];

    can probe with Vertex entry {
        if here.vid in self.claimed {
            skip;
        }
        self.claimed[here.vid] = True;
        self.order.append(here.vid);
        print(here.vid);
        nbrs: list[Vertex] = [];
        for nxt in [here ->:Arc:->][?:Vertex] {
            nbrs.append(nxt);
        }
        if nbrs {
            visit :0: nbrs;
        } else {
            disengage;
        }
    }
}

walker BfsWalker {
    has claimed: dict[str, bool] = {};
    has order: list[str] = [];

    can probe with Vertex entry {
        if here.vid in self.claimed {
            skip;
        }
        self.claimed[here.vid] = True;
        self.order.append(here.vid);
        print(here.vid);
        nbrs: list[Vertex] = [];
        for nxt in [here ->:Arc:->][?:Vertex] {
            nbrs.append(nxt);
        }
        if nbrs {
            visit nbrs;
        } else {
            disengage;
        }
    }
}

def build_from_adjacency(adj: dict[str, list[str]]) -> GraphHandle {
    gh = GraphHandle();
    keys: list[str] = [];
    for k in adj {
        keys.append(k);
    }
    keys = sorted(keys);
    first: bool = True;
    for k in keys {
        v = Vertex(vid=k);
        if first {
            root ++> v;
            first = False;
        }
        gh.vertices[k] = v;
    }
    for src in keys {
        raw: list[str] = [];
        if src in adj {
            raw = adj[src] as list[str];
        }
        for dst in raw {
            if dst in gh.vertices {
                a = gh.vertices[src] as Vertex;
                b = gh.vertices[dst] as Vertex;
                a +>:Arc:+> b;
            }
        }
    }
    return gh;
}

def dfs_order(adj: dict[str, list[str]], start: str) -> list[str] {
    gh = build_from_adjacency(adj);
    if start not in gh.vertices {
        return [];
    }
    v = gh.vertices[start] as Vertex;
    w = v spawn DfsWalker(claimed={}, order=[]);
    return w.order;
}

def bfs_order(adj: dict[str, list[str]], start: str) -> list[str] {
    gh = build_from_adjacency(adj);
    if start not in gh.vertices {
        return [];
    }
    v = gh.vertices[start] as Vertex;
    w = v spawn BfsWalker(claimed={}, order=[]);
    return w.order;
}

def vertex_edge_counts(adj: dict[str, list[str]]) -> dict[str, int] {
    keys: list[str] = [];
    for k in adj {
        keys.append(k);
    }
    e: int = 0;
    for src in keys {
        raw: list[str] = [];
        if src in adj {
            raw = adj[src] as list[str];
        }
        e += len(raw);
    }
    out: dict[str, int] = {};
    out["V"] = len(keys);
    out["E"] = e;
    return out;
}

def classify_graph_traversal(mode: str) -> dict[str, str] {
    out: dict[str, str] = {};
    if mode == "dfs" {
        out["pattern"] = "dfs_adjacency";
        out["complexity"] = "O(V+E)";
        out["confidence"] = "high";
    } elif mode == "bfs" {
        out["pattern"] = "bfs_adjacency";
        out["complexity"] = "O(V+E)";
        out["confidence"] = "high";
    } else {
        out["pattern"] = "unknown";
        out["complexity"] = "(?)";
        out["confidence"] = "low";
    }
    return out;
}

def master_theorem_hint(a: int, b: int, d: int) -> str {
    if a <= 0 or b <= 1 or d < 0 {
        return "(?)";
    }
    if a == 1 and b == 2 and d == 0 {
        return "O(log n)";
    }
    if a == 2 and b == 2 and d == 1 {
        return "O(n log n)";
    }
    if a == 2 and b == 2 and d == 0 {
        return "O(n)";
    }
    if d >= 2 {
        return "O(n^" + str(d) + ")";
    }
    return "(?)";
}
