"""Recursive crafting with environmental sources — blushiemagic/MagicStorage#266."""

glob ANCHOR = "__craft_root__";

node GraphRoot {
    has tag: str = ANCHOR;
}

node Material {
    has mid: str;
    has is_env: bool = False;
}

node Recipe {
    has rid: str;
}

edge Produces {}

edge Requires {}

obj CraftGraph {
    has root_nd: GraphRoot;
    has mats: dict[str, Material] = {};
    has by_output: dict[str, Recipe] = {};
}

def _get_or_make_mat(g: CraftGraph, mid: str, is_env: bool) -> Material {
    if mid in g.mats {
        return g.mats[mid];
    }
    nd = Material(mid=mid, is_env=is_env);
    g.root_nd ++> nd;
    g.mats[mid] = nd;
    return nd;
}

def add_env_source(g: CraftGraph, mid: str) -> None {
    _get_or_make_mat(g, mid, True);
}

def add_recipe(
    g: CraftGraph,
    rid: str,
    output_mid: str,
    ing_mids: list[str],
    ing_qtys: list[int]
) -> None {
    out_nd = _get_or_make_mat(g, output_mid, False);
    rp = Recipe(rid=rid);
    g.root_nd ++> rp;
    rp +>:Produces:+> out_nd;
    g.by_output[output_mid] = rp;
    i: int = 0;
    while i < len(ing_mids) {
        ing_mid: str = ing_mids[i];
        ing_nd = _get_or_make_mat(g, ing_mid, False);
        rp +>:Requires:+> ing_nd;
        i = i + 1;
    }
}

def make_graph() -> CraftGraph {
    rt = GraphRoot();
    g = CraftGraph(root_nd=rt);
    root ++> rt;
    add_env_source(g, "water");
    add_recipe(g, "mk_bottle", "bottled_water", ["water"], [1]);
    add_recipe(
        g,
        "mk_flymeal",
        "flymeal",
        ["bottled_water", "fallen_star"],
        [1, 1]
    );
    return g;
}

def make_diamond_graph() -> CraftGraph {
    rt = GraphRoot();
    g = CraftGraph(root_nd=rt);
    root ++> rt;
    add_recipe(g, "r_top", "top", ["left", "right"], [1, 1]);
    add_recipe(g, "r_left", "left", ["leaf"], [1]);
    add_recipe(g, "r_right", "right", ["leaf"], [1]);
    return g;
}

walker NeedWalker {
    has claimed: dict[str, bool] = {};
    has needs: dict[str, int] = {};
    has stock: dict[str, int] = {};
    has recipes: dict[str, Recipe] = {};
    has max_depth: int = 0;
    has depth: int = 0;

    can expand with Material entry {
        if here.mid in self.claimed {
            skip;
        }
        if here.is_env {
            print("env ", here.mid);
            disengage;
        }
        avail: int = 0;
        if here.mid in self.stock {
            avail = self.stock[here.mid];
        }
        if avail > 0 {
            self.stock[here.mid] = avail - 1;
            print("stock ", here.mid);
            disengage;
        }
        if self.depth >= self.max_depth {
            miss: int = 0;
            if here.mid in self.needs {
                miss = self.needs[here.mid];
            }
            self.needs[here.mid] = miss + 1;
            print("miss ", here.mid);
            disengage;
        }
        if here.mid not in self.recipes {
            miss2: int = 0;
            if here.mid in self.needs {
                miss2 = self.needs[here.mid];
            }
            self.needs[here.mid] = miss2 + 1;
            print("leaf ", here.mid);
            disengage;
        }
        self.claimed[here.mid] = True;
        print("expand ", here.mid);
        rp = self.recipes[here.mid];
        self.depth = self.depth + 1;
        kids: list[Material] = [rp ->:Requires:->][?:Material];
        for kid in kids {
            visit :0: [kid];
        }
        self.depth = self.depth - 1;
        self.claimed[here.mid] = False;
    }
}

def can_craft(
    g: CraftGraph,
    target_mid: str,
    stock: dict[str, int],
    max_depth: int
) -> bool {
    if target_mid not in g.mats {
        return False;
    }
    stk: dict[str, int] = {};
    for k in stock {
        stk[k] = stock[k];
    }
    nd = g.mats[target_mid];
    w = nd spawn NeedWalker(
        stock=stk,
        recipes=g.by_output,
        max_depth=max_depth
    );
    for k in w.needs {
        need: int = w.needs[k];
        have: int = 0;
        if k in stk {
            have = stk[k];
        }
        if have < need {
            return False;
        }
    }
    return True;
}

def apply_craft(
    g: CraftGraph,
    target_mid: str,
    stock: dict[str, int],
    max_depth: int
) -> bool {
    if not can_craft(g, target_mid, stock, max_depth) {
        return False;
    }
    stk: dict[str, int] = {};
    for k in stock {
        stk[k] = stock[k];
    }
    nd = g.mats[target_mid];
    w = nd spawn NeedWalker(
        stock=stk,
        recipes=g.by_output,
        max_depth=max_depth
    );
    keys: list[str] = [];
    for k in w.needs {
        keys.append(k);
    }
    for k in sorted(keys) {
        need: int = w.needs[k];
        cur: int = stk[k];
        stk[k] = cur - need;
    }
    out: int = 0;
    if target_mid in stk {
        out = stk[target_mid];
    }
    stk[target_mid] = out + 1;
    for k in stk {
        stock[k] = stk[k];
    }
    return True;
}

with entry {
    g = make_graph();
    st: dict[str, int] = {};
    nd = g.mats["bottled_water"];
    w = nd spawn NeedWalker(
        stock=st,
        recipes=g.by_output,
        max_depth=2
    );
    print("demo ", can_craft(g, "bottled_water", st, 2));
}
