"""hfour/wsrun#65 — optional cycle detection for workspace dependency graphs."""

node Workspace {
    has name: str;
}

node GraphRoot {
    has label: str = "workspaces";
}

edge Depends {}

walker OrderWalker {
    has claimed: dict[str, bool] = {};
    has path: list[str] = [];
    has detect_cycles: bool = True;
    has order: list[str] = [];
    has cycle_error: bool = False;

    can step with Workspace entry {
        print({"step": here.name, "detect_cycles": self.detect_cycles});
        if self.detect_cycles {
            if here.name in self.path {
                self.cycle_error = True;
                skip;
            }
            self.path.append(here.name);
        } else {
            if here.name in self.claimed {
                skip;
            }
            self.claimed[here.name] = True;
        }
        self.order.append(here.name);
        kids: list[Workspace] = [here ->:Depends:->][?:Workspace];
        for kid in kids {
            visit :0: [kid];
        }
        if self.detect_cycles {
            trimmed: list[str] = [];
            upto: int = len(self.path) - 1;
            for i in range(upto) {
                trimmed.append(self.path[i]);
            }
            self.path = trimmed;
        }
    }
}

def lookup_workspace(gr: GraphRoot, name: str) -> Workspace | None {
    result: Workspace | None = None;
    nodes: list[Workspace] = [gr ->:Depends:->][?:Workspace];
    for nd in nodes {
        if nd.name == name {
            result = nd;
        }
    }
    return result;
}

def build_workspace_graph(edges: list[tuple[str, str]]) -> GraphRoot {
    gr = GraphRoot();
    root ++> gr;
    store: dict[str, Workspace] = {};
    for pair in edges {
        src: str = pair[0];
        dst: str = pair[1];
        if src not in store {
            src_nd: Workspace = Workspace(name=src);
            gr +>:Depends:+> src_nd;
            store[src] = src_nd;
        }
        if dst not in store {
            dst_nd: Workspace = Workspace(name=dst);
            gr +>:Depends:+> dst_nd;
            store[dst] = dst_nd;
        }
        store[src] +>:Depends:+> store[dst];
    }
    return gr;
}

def resolve_order(
    gr: GraphRoot,
    start: str,
    detect_cycles: bool = True
) -> list[str] {
    ws: Workspace | None = lookup_workspace(gr, start);
    if ws is None {
        return [];
    }
    w = ws spawn OrderWalker(
        claimed={},
        path=[],
        detect_cycles=detect_cycles,
        order=[],
        cycle_error=False
    );
    if w.cycle_error {
        return [];
    }
    return w.order;
}

def has_dependency_cycle(gr: GraphRoot, detect_cycles: bool = True) -> bool {
    nodes: list[Workspace] = [gr ->:Depends:->][?:Workspace];
    for nd in nodes {
        w = nd spawn OrderWalker(
            claimed={},
            path=[],
            detect_cycles=detect_cycles,
            order=[],
            cycle_error=False
        );
        if w.cycle_error {
            return True;
        }
    }
    return False;
}
