"""stlab/cel-rs#187 — Kahn topological plan order; is_acyclic without Tarjan SCC."""

node Step {
    has sid: str;
}

edge Depends {}

def build_plan_graph(adj: dict[str, list[str]]) -> dict[str, Step] {
    store: dict[str, Step] = {};
    seeds: list[str] = sorted(adj.keys());
    for sid in seeds {
        if sid not in store {
            nd = Step(sid=sid);
            root ++> nd;
            store[sid] = nd;
        }
    }
    for tgt in seeds {
        deps: list[str] = adj[tgt];
        for dep in deps {
            if dep not in store {
                pnd = Step(sid=dep);
                root ++> pnd;
                store[dep] = pnd;
            }
            parent = store[dep] as Step;
            child = store[tgt] as Step;
            parent +>:Depends:+> child;
        }
    }
    return store;
}

def _in_degrees(store: dict[str, Step]) -> dict[str, int] {
    deg: dict[str, int] = {};
    ids: list[str] = sorted(store.keys());
    for sid in ids {
        deg[sid] = 0;
    }
    for sid in ids {
        nd = store[sid] as Step;
        outs: list[Step] = [nd ->:Depends:->][?:Step];
        for succ in outs {
            deg[succ.sid] += 1;
        }
    }
    return deg;
}

def _kahn_order(store: dict[str, Step]) -> list[str] {
    deg = _in_degrees(store);
    queue: list[str] = [];
    for sid in sorted(deg.keys()) {
        if deg[sid] == 0 {
            queue.append(sid);
        }
    }
    order: list[str] = [];
    while len(queue) > 0 {
        cur = queue[0];
        rest: list[str] = [];
        qi = 0;
        while qi < len(queue) {
            if not (qi == 0 and queue[qi] == cur) {
                rest.append(queue[qi]);
            }
            qi += 1;
        }
        queue = rest;
        order.append(cur);
        cur_nd = store[cur] as Step;
        outs: list[Step] = [cur_nd ->:Depends:->][?:Step];
        ready: list[str] = [];
        for succ in outs {
            deg[succ.sid] -= 1;
            if deg[succ.sid] == 0 {
                ready.append(succ.sid);
            }
        }
        ready = sorted(ready);
        for rs in ready {
            queue.append(rs);
        }
    }
    return order;
}

def is_acyclic(adj: dict[str, list[str]]) -> bool {
    store = build_plan_graph(adj);
    order = _kahn_order(store);
    return len(order) == len(sorted(store.keys()));
}

def plan(adj: dict[str, list[str]]) -> list[str] {
    store = build_plan_graph(adj);
    order = _kahn_order(store);
    if len(order) != len(sorted(store.keys())) {
        raise Exception(msg="FilterCycle");
    }
    return order;
}

walker AcyclicProbe {
    has claimed: dict[str, bool] = {};
    has visit_log: list[str] = [];

    can walk with Step entry {
        print("probe ", here.sid);
        if here.sid in self.claimed {
            skip;
        }
        self.claimed[here.sid] = True;
        self.visit_log.append(here.sid);
        raw: list[Step] = [here ->:Depends:->][?:Step];
        kid_sids: list[str] = [];
        for ch in raw {
            kid_sids.append(ch.sid);
        }
        kid_sids = sorted(kid_sids);
        kids: list[Step] = [];
        for ks in kid_sids {
            for ch in raw {
                if ch.sid == ks {
                    kids.append(ch);
                }
            }
        }
        if len(kids) > 0 {
            visit :0: kids;
        } else {
            disengage;
        }
    }
}

def probe_plan_walk(adj: dict[str, list[str]]) -> list[str] {
    store = build_plan_graph(adj);
    w = root spawn AcyclicProbe(claimed={});
    ids: list[str] = sorted(store.keys());
    for sid in ids {
        nd = store[sid] as Step;
        zero_in = True;
        ins: list[Step] = [nd <-:Depends:<-][?:Step];
        if len(ins) > 0 {
            zero_in = False;
        }
        if zero_in {
            wk = nd spawn AcyclicProbe(claimed=w.claimed);
            w.claimed = wk.claimed;
            w.visit_log = wk.visit_log;
        }
    }
    return w.visit_log;
}
