        if here.mid in self.claimed {
            skip;
        }
        self.claimed[here.mid] = True;
        if here.mid != self.root_mid {
            self.found.append(here.mid);
        }
        kids: list[Org] = [here ->:ReportsTo:->][?:Org];
        if kids {
            for ch in kids {
                visit :0: [ch];
            }
        } else {
