def recursive_descendants(store: OrgStore, root_id: str) -> list[str] {
    if root_id not in store.members {
        empty: list[str] = [];
        return empty;
    }
    start = store.members[root_id] as Org;
    w = start spawn DescendWalker(claimed={}, found=[], root_mid=root_id);
    return sorted(w.found);
}

def _sorted_members_by_revenue(store: OrgStore) -> list[list] {
    mids: list[str] = [];
    for k in store.members {
        mids.append(k);
    }
    items: list[list] = [];
    for mid in mids {
        nd = store.members[mid] as Org;
        row: list = [];
        row.append(mid);
        row.append(nd.revenue);
        items.append(row);
    }
    n = len(items);
    i = 0;
    while i < n {
        j = i + 1;
        while j < n {
            ri = items[i][1] as int;
            rj = items[j][1] as int;
            mi = items[i][0] as str;
            mj = items[j][0] as str;
            if rj > ri || (rj == ri && mj < mi) {
                tmp = items[i];
                items[i] = items[j];
                items[j] = tmp;
            }
            j += 1;
        }
        i += 1;
    }
    return items;
}

def dense_rank(store: OrgStore) -> list[tuple[str, int]] {
    items = _sorted_members_by_revenue(store);
    ranked: list[tuple[str, int]] = [];
    n = len(items);
    if n == 0 {
        return ranked;
    }
    rank = 1;
    prev_rev = items[0][1] as int;
    pos = 0;
    while pos < n {
        mid = items[pos][0] as str;
        rev = items[pos][1] as int;
        if pos > 0 && rev != prev_rev {
            rank += 1;
        }
        ranked.append((mid, rank));
        prev_rev = rev;
        pos += 1;
    }
    return ranked;
}

def rank_with_gaps(store: OrgStore) -> list[tuple[str, int]] {
    items = _sorted_members_by_revenue(store);
    ranked: list[tuple[str, int]] = [];
    n = len(items);
    pos = 0;
    rank = 1;
    while pos < n {
        mid = items[pos][0] as str;
        ranked.append((mid, rank));
        rank += 1;
        pos += 1;
    }
    return ranked;
}
