# stlab/cel-rs#187 — Kahn topo sort, acyclic check, plan (planner cleanup).

node Step {
    has cid: str;
    has indeg: int = 0;
}

edge Dep {}

walker TopoProbe {
    has claimed: dict[str, bool] = {};
    has log: list[str] = [];

    can probe with Step entry {
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        self.log.append(here.cid);
        print("probe", here.cid);
        pending: list[Step] = [];
        for nxt in [here ->:Dep:->][?:Step] {
            pending.append(nxt);
        }
        ordered: list[Step] = sort_steps_by_cid(pending);
        if ordered {
            visit :0: ordered;
        } else {
            disengage;
        }
    }
}

def sort_steps_by_cid(items: list[Step]) -> list[Step] {
    out: list[Step] = [];
    for it in items {
        out.append(it);
    }
    i = 0;
    while i < len(out) {
        j = i + 1;
        while j < len(out) {
            if out[j].cid < out[i].cid {
                tmp = out[i];
                out[i] = out[j];
                out[j] = tmp;
            }
            j += 1;
        }
        i += 1;
    }
    return out;
}

def build_index(node_ids: list[str]) -> dict[str, Step] {
    idx: dict[str, Step] = {};
    for nid in node_ids {
        st = Step(cid=nid);
        root ++> st;
        idx[nid] = st;
    }
    return idx;
}

def wire_edges(idx: dict[str, Step], edges: list[tuple[str, str]], known: dict[str, bool]) -> None {
    for e in edges {
        src = e[0];
        dst = e[1];
        if (src in known) and (dst in known) {
            a = idx[src];
            b = idx[dst];
            a +>:Dep:+> b;
        }
    }
}

def compute_indegrees(node_ids: list[str], edges: list[tuple[str, str]]) -> dict[str, int] {
    deg: dict[str, int] = {};
    known: dict[str, bool] = {};
    for nid in node_ids {
        deg[nid] = 0;
        known[nid] = True;
    }
    for e in edges {
        src = e[0];
        dst = e[1];
        if (src in known) and (dst in known) {
            deg[dst] += 1;
        }
    }
    return deg;
}

def build_diamond() -> dict[str, Step] {
    idx: dict[str, Step] = {};
    for cid in ["a", "b", "c", "d"] {
        nd = Step(cid=cid);
        root ++> nd;
        idx[cid] = nd;
    }
    idx["a"] +>:Dep:+> idx["b"];
    idx["a"] +>:Dep:+> idx["c"];
    idx["b"] +>:Dep:+> idx["d"];
    idx["c"] +>:Dep:+> idx["d"];
    return idx;
}

def topological_order(node_ids: list[str], edges: list[tuple[str, str]]) -> list[str] {
    if not node_ids {
        return [];
    }
    idx = build_index(node_ids);
    known: dict[str, bool] = {};
    for nid in node_ids {
        known[nid] = True;
    }
    wire_edges(idx, edges, known);
    deg = compute_indegrees(node_ids, edges);
    queue: list[str] = [];
    for nid in node_ids {
        if deg[nid] == 0 {
            queue.append(nid);
        }
    }
    order: list[str] = [];
    while queue {
        cur = queue[0];
        rest: list[str] = [];
        ti = 1;
        while ti < len(queue) {
            rest.append(queue[ti]);
            ti += 1;
        }
        queue = rest;
        order.append(cur);
        st = idx[cur];
        for nxt in [st ->:Dep:->][?:Step] {
            deg[nxt.cid] -= 1;
            if deg[nxt.cid] == 0 {
                queue.append(nxt.cid);
            }
        }
    }
    if len(order) != len(node_ids) {
        return [];
    }
    return order;
}

def is_acyclic(node_ids: list[str], edges: list[tuple[str, str]]) -> bool {
    ord = topological_order(node_ids, edges);
    return len(ord) == len(node_ids);
}

def plan(node_ids: list[str], edges: list[tuple[str, str]]) -> list[str] {
    ord = topological_order(node_ids, edges);
    if len(ord) != len(node_ids) {
        raise ValueError("FilterCycle");
    }
    return ord;
}

