}

def can_finish(num_courses: int, prerequisites: list[list[int]]) -> bool {
    if num_courses <= 0 {
        return True;
    }
    nodes: list[Course] = [];
    idx: dict[str, Course] = {};
    for i in range(num_courses) {
        nd = Course(cid=i);
        root ++> nd;
        nodes.append(nd);
        idx[str(i)] = nd;
    }
    for pair in prerequisites {
        if len(pair) < 2 {
            continue;
        }
        a: int = pair[0];
        b: int = pair[1];
        if a < 0 or a >= num_courses or b < 0 or b >= num_courses {
            continue;
        }
        src = idx[str(b)] as Course;
        dst = idx[str(a)] as Course;
        src +>:Prereq:+> dst;
    }
    cyclic: bool = False;
    done: dict[str, bool] = {};
    for nd in nodes {
        key: str = str(nd.cid);
        if key in done {
            continue;
        }
        w = nd spawn CycleProbe(cyclic=False, done=done);
        cyclic = w.cyclic;
        done = w.done;
        print("probe ", nd.cid, " cyclic=", w.cyclic);
        if cyclic {
            return False;
        }
    }
    return True;
}
