def build_demo() -> None {
  nic = MemSpace(sid="NicRam", pinned_default="NPUHBM");
  hbm = MemSpace(sid="NpuHbm", pinned_default="NPUHBM");
  remote = MemSpace(sid="RemoteHbm", pinned_default="NPUHBM");
