def find_space(sid: str) -> MemSpace | None {
  nodes: list[MemSpace] = [root ->][?:MemSpace];
  for nd in nodes {
    if nd.sid == sid {
      return nd;
    }
  }
  return None;
}

def rebuild_path(parent: dict[str, str], src: str, dst: str) -> list[str] {
  rev: list[str] = [];
  cur = dst;
  guard = 0;
  while cur != "" and guard < 32 {
    rev.append(cur);
    if cur == src {
      break;
    }
    if cur in parent {
      cur = parent[cur];
    } else {
      cur = "";
    }
    guard += 1;
  }
  out: list[str] = [];
  i = len(rev) - 1;
  while i >= 0 {
    out.append(rev[i]);
    i -= 1;
  }
  return out;
}

def dijkstra(source: str, target: str) -> list[str] {
  start = find_space(source);
  if start is None {
    return [];
  }
  cw = start spawn CollectW();
  dist: dict[str, int] = {};
  parent: dict[str, str] = {};
  dist[source] = 0;
  updated = True;
  rounds = 0;
  while updated and rounds < 32 {
    updated = False;
    rounds += 1;
    i = 0;
    while i < len(cw.edges) {
      e = cw.edges[i];
      u = e[0];
      v = e[1];
      du = 999999;
      if u in dist {
        du = dist[u];
      }
      dv = 999999;
      if v in dist {
        dv = dist[v];
      }
      if du + 1 < dv {
        dist[v] = du + 1;
        parent[v] = u;
        updated = True;
      }
      i += 1;
    }
  }
  if target not in dist {
    return [];
  }
  return rebuild_path(parent, source, target);
}

def type_default_memory(sid: str) -> str {
  nd = find_space(sid);
  if nd is None {
    return "";
  }
  return nd.pinned_default;
}

def expr_memory(sid: str) -> str {
  nd = find_space(sid);
  if nd is None {
    return "";
  }
  return nd.sid;
}

def expand_transfer(source: str, dest: str) -> list[str] {
  return dijkstra(source, dest);
}

def verify_semantics(source: str, dest: str, use_expr_space: bool) -> bool {
  route = dijkstra(source, dest);
  if len(route) == 0 {
    return False;
  }
  first = find_space(route[0]);
  if first is None {
    return False;
  }
  vw = first spawn VerifyW(route=route, use_expr=use_expr_space);
  return vw.ok;
}
