"""Ordered cross-pipeline deploy/run from control lineage — databricks-solutions/flowx#24."""

node Pipeline {
    has pid: str;
}

edge ControlCall {}

def wire_control_graph(pipelines: list[str], edges: list[list[str]]) -> dict[str, Pipeline] {
    nodes: dict[str, Pipeline] = {};
    for pid in pipelines {
        nd = Pipeline(pid=pid);
        nodes[pid] = nd;
        root ++> nd;
    }
    for e in edges {
        caller: str = e[0];
        callee: str = e[1];
        if caller not in nodes {
            continue;
        }
        if callee not in nodes {
            continue;
        }
        nodes[caller] +>:ControlCall:+> nodes[callee];
    }
    return nodes;
}

def job_depends_on(pipeline: str, edges: list[list[str]]) -> list[str] {
    deps: list[str] = [];
    for e in edges {
        if e[0] == pipeline {
            deps.append(e[1]);
        }
    }
    deps.sort();
    return deps;
}

def deploy_order(pipelines: list[str], edges: list[list[str]]) -> list[str] {
    indeg: dict[str, int] = {};
    adj: dict[str, list[str]] = {};
    for p in pipelines {
        indeg[p] = 0;
        adj[p] = [];
    }
    for e in edges {
        caller: str = e[0];
        callee: str = e[1];
        if caller not in indeg {
            continue;
        }
        if callee not in indeg {
            continue;
        }
        adj[callee].append(caller);
        indeg[caller] = indeg[caller] + 1;
    }
    queue: list[str] = [];
    for p in pipelines {
        if indeg[p] == 0 {
            queue.append(p);
        }
    }
    queue.sort();
    out: list[str] = [];
    while len(queue) > 0 {
        cur: str = queue[0];
        nq: list[str] = [];
        qi: int = 1;
        while qi < len(queue) {
            nq.append(queue[qi]);
            qi = qi + 1;
        }
        queue = nq;
        out.append(cur);
        for nxt in adj[cur] {
            indeg[nxt] = indeg[nxt] - 1;
            if indeg[nxt] == 0 {
                queue.append(nxt);
            }
        }
        queue.sort();
    }
    if len(out) != len(pipelines) {
        return sorted(pipelines);
    }
    return out;
}

def is_acyclic_control(pipelines: list[str], edges: list[list[str]]) -> bool {
    indeg: dict[str, int] = {};
    adj: dict[str, list[str]] = {};
    for p in pipelines {
        indeg[p] = 0;
        adj[p] = [];
    }
    for e in edges {
        caller: str = e[0];
        callee: str = e[1];
        if caller not in indeg {
            continue;
        }
        if callee not in indeg {
            continue;
        }
        adj[callee].append(caller);
        indeg[caller] = indeg[caller] + 1;
    }
    queue: list[str] = [];
    for p in pipelines {
        if indeg[p] == 0 {
            queue.append(p);
        }
    }
    seen: int = 0;
    while len(queue) > 0 {
        cur: str = queue[0];
        nq: list[str] = [];
        qi: int = 1;
        while qi < len(queue) {
            nq.append(queue[qi]);
            qi = qi + 1;
        }
        queue = nq;
        seen = seen + 1;
        for nxt in adj[cur] {
            indeg[nxt] = indeg[nxt] - 1;
            if indeg[nxt] == 0 {
                queue.append(nxt);
            }
        }
    }
    return seen == len(pipelines);
}

walker CalleeClosure {
    has root_pid: str;
    has claimed: dict[str, bool] = {};
    has found: list[str] = [];

    can step with Pipeline entry {
        if here.pid in self.claimed {
            skip;
        }
        self.claimed[here.pid] = True;
        print("closure", here.pid);
        if here.pid != self.root_pid {
            self.found.append(here.pid);
        }
        kids: list[Pipeline] = [here ->:ControlCall:->][?:Pipeline];
        for kid in kids {
            visit :0: [kid];
        }
    }
}

def transitive_callees(pipeline: str, pipelines: list[str], edges: list[list[str]]) -> list[str] {
    if pipeline not in pipelines {
        return [];
    }
    nodes: dict[str, Pipeline] = wire_control_graph(pipelines, edges);
    start: Pipeline = nodes[pipeline];
    w = start spawn CalleeClosure(root_pid=pipeline);
    res: list[str] = w.found;
    res.sort();
    return res;
}
