    for e in edges {
        cp: str = e["caller_pipeline"];
        ce: str = e["callee_pipeline"];
        if cp not in hooked {
            graph_root ++> store[cp];
            hooked[cp] = True;
        }
        if ce not in hooked {
            graph_root ++> store[ce];
            hooked[ce] = True;
        }
