```jac
"""vx-lang/Vx#132 - multi-hop transfer semantic verification without pinned-default recursion."""

glob MAX_VERIFY_DEPTH: int = 32;

node MemSpace {
    has sid: str;
    has pinned_default: str;
}

edge Hop {}

obj TopoHandle {
    has by_sid: dict[str, MemSpace] = {};
}

walker HopSearch {
    has target: str = "";
    has origin: str = "";
    has claimed: dict[str, bool] = {};
    has parent: dict[str, str] = {};
    has result: list[str] = [];
    has done: bool = False;

    can expand with MemSpace entry {
        if self.done {
            disengage;
        }
        if here.sid in self.claimed {
            skip;
        }
        self.claimed[here.sid] = True;
        print ["hop_expand", here.sid];
        if here.sid == self.target {
            cur: str = self.target;
            rev: list[str] = [];
            while cur != self.origin {
                rev.append(cur);
                cur = self.parent[cur];
            }
            rev.append(self.origin);
            self.result = [];
            idx: int = len(rev) - 1;
            while idx >= 0 {
                self.result.append(rev[idx]);
                idx -= 1;
            }
            self.done = True;
            print ["hop_done", self.result];
            disengage;
        }
        nxt: list[MemSpace] = [];
        for ch in [here ->:Hop:->][?:MemSpace] {
            if ch.sid not in self.parent {
                self.parent[ch.sid] = here.sid;
            }
            nxt.append(ch);
        }
        if nxt {
            visit :0: nxt;
        } else {
            disengage;
        }
    }
}

def build_demo() {
    make_topo();
}

def make_topo() -> TopoHandle {
    h = TopoHandle();
    nic = MemSpace(sid="NicRam", pinned_default="NPUHBM");
    npu = MemSpace(sid="NPU(0)", pinned_default="NPUHBM");
    remote = MemSpace(sid="RemoteHBM", pinned_default="NPUHBM");
    hbm = MemSpace(sid="NPUHBM", pinned_default="NPUHBM");
    root ++> nic;
    root ++> npu;
    root ++> remote;
    root ++> hbm;
    h.by_sid["NicRam"] = nic;
    h.by_sid["NPU(0)"] = npu;
    h.by_sid["RemoteHBM"] = remote;
    h.by_sid["NPUHBM"] = hbm;
    nic +>:Hop:+> npu;
    npu +>:Hop:+> remote;
    npu +>:Hop:+> hbm;
    return h;
}

def make_diamond_topo() -> TopoHandle {
    h = TopoHandle();
    a = MemSpace(sid="A", pinned_default="P");
    b = MemSpace(sid="B", pinned_default="P");
    c = MemSpace(sid="C", pinned_default="P");
    d = MemSpace(sid="D", pinned_default="P");
    p = MemSpace(sid="P", pinned_default="P");
    root ++> a;
    root ++> b;
    root ++> c;
    root ++> d;
    root ++> p;
    h.by_sid["A"] = a;
    h.by_sid["B"] = b;
    h.by_sid["C"] = c;
    h.by_sid["D"] = d;
    h.by_sid["P"] = p;
    a +>:Hop:+> b;
    a +>:Hop:+> c;
    b +>:Hop:+> d;
    c +>:Hop:+> d;
    return h;
}

def resolve_space_sid(h: TopoHandle, space_sid: str, expr_space: str, use_expr_space: bool) -> str {
    if use_expr_space {
        return expr_space;
    }
    if space_sid not in h.by_sid {
        return space_sid;
    }
    return h.by_sid[space_sid].pinned_default;
}

def shortest_path_sids(h: TopoHandle, src_sid: str, dst_sid: str) -> list[str] {
    if src_sid not in h.by_sid or dst_sid not in h.by_sid {
        return [];
    }
    if src_sid == dst_sid {
        return [src_sid];
    }
    src_nd = h.by_sid[src_sid];
    w = src_nd spawn HopSearch(target=dst_sid, origin=src_sid);
    return w.result;
}

def make_nested_transfer(path: list[str]) -> dict {
    if len(path) < 2 {
        out: dict = {};
        out["space"] = "";
        out["dst"] = "";
        out["inner"] = None;
        return out;
    }
    inner_expr: dict | None = None;
    i: int = len(path) - 2;
    while i >= 0 {
        step: dict = {};
        step["space"] = path[i];
        step["dst"] = path[i + 1];
        step["inner"] = inner_expr;
        inner_expr = step;
        i -= 1;
    }
    return inner_expr;
}

def rewrite_transfer(h: TopoHandle, src_sid: str, dst_sid: str) -> dict {
    path = shortest_path_sids(h, src_sid, dst_sid);
    return make_nested_transfer(path);
}

def verify_transfer_expr(h: TopoHandle, expr: dict, use_expr_space: bool, depth: int) -> str {
    if depth > MAX_VERIFY_DEPTH {
        return "STACK_OVERFLOW";
    }
    space_sid: str = expr["space"];
    dst_sid: str = expr["dst"];
    inner = expr["inner"];
    if inner is not None {
        inner_space: str = inner["space"];
        recovered = resolve_space_sid(h, inner_space, inner_space, use_expr_space);
        if recovered != inner_space {
            path = shortest_path_sids(h, recovered, dst_sid);
            if len(path) >= 2 {
                reb = make_nested_transfer(path);
                return verify_transfer_expr(h, reb, use_expr_space, depth + 1);
            }
        }
        return verify_transfer_expr(h, inner, use_expr_space, depth + 1);
    }
    cur_space = resolve_space_sid(h, space_sid, space_sid, use_expr_space);
    if cur_space == dst_sid {
        return dst_sid;
    }
    path = shortest_path_sids(h, cur_space, dst_sid);
    if len(path) < 2 {
        return dst_sid;
    }
    nested = make_nested_transfer(path);
    return verify_transfer_expr(h, nested, use_expr_space, depth + 1);
}

def verify_transfer(h: TopoHandle, src_sid: str, dst_sid: str, use_expr_space: bool) -> str {
    if src_sid not in h.by_sid or dst_sid not in h.by_sid {
        return "UNKNOWN";
    }
    if src_sid == dst_sid {
        return dst_sid;
    }
    path = shortest_path_sids(h, src_sid, dst_sid);
    if len(path) < 2 {
        return dst_sid;
    }
    expr = make_nested_transfer(path);
    return verify_transfer_expr(h, expr, use_expr_space, 0);
}
