def register_course(cat: AcademicCatalog, course_id: str, title: str = "") -> Course {
    if course_id in cat.courses {
        return cat.courses[course_id] as Course;
    }
    nd = Course(cid=course_id, title=title);
    cat.courses[course_id] = nd;
