def get_prerequisites(cat: AcademicCatalog, course_id: str) -> list[str] {
    ids: list[str] = [];
    if course_id not in cat.courses {
        return ids;
    }
    crs = cat.courses[course_id] as Course;
    for n in [crs ->:Prereq:->][?:Course] {
        ids.append(n.cid);
    }
    ids.sort();
    return ids;
}

def admin_add_prerequisite(cat: AcademicCatalog, course_id: str, prereq_id: str) -> None {
    if course_id not in cat.courses {
        raise KeyError(course_id);
    }
    if prereq_id not in cat.courses {
        raise KeyError(prereq_id);
    }
    if course_id == prereq_id {
        raise CycleError(conflicting_course_id=course_id);
    }
    crs = cat.courses[course_id] as Course;
    pre = cat.courses[prereq_id] as Course;
    for existing in [crs ->:Prereq:->][?:Course] {
        if existing.cid == prereq_id {
            return;
        }
    }
    w = pre spawn CycleProbe(target_cid=course_id, claimed={});
    if w.found is not None {
        raise CycleError(conflicting_course_id=course_id);
    }
    crs +>:Prereq:+> pre;
}

def admin_remove_prerequisite(cat: AcademicCatalog, course_id: str, prereq_id: str) -> bool {
    if course_id not in cat.courses {
        return False;
