def topological_sort(graph: dict[str, list[str]]) -> list[str] {
    _materialize_deps(graph);
    indeg: dict[str, int] = {};
    for src in graph {
        if src not in indeg { indeg[src] = 0; }
        nbrs: list[str] = graph[src] as list[str];
        for dst in nbrs {
            if dst not in indeg { indeg[dst] = 0; }
            indeg[dst] = indeg[dst] + 1;
        }
    }
    ready: list[str] = [];
    for nid in indeg {
        if indeg[nid] == 0 { ready.append(nid); }
    }
    ready = sorted(ready);
    order: list[str] = [];
    while len(ready) > 0 {
        cur = ready[0];
        ready = ready[1:];
        order.append(cur);
        if cur in graph {
            nbrs2: list[str] = graph[cur] as list[str];
            for dst in sorted(nbrs2) {
                indeg[dst] = indeg[dst] - 1;
                if indeg[dst] == 0 { ready.append(dst); }
            }
            ready = sorted(ready);
        }
    }
    w = root spawn TopoWalker(claimed={});
    print("topo walker visits", len(w.order));
    return order;
}

def detect_cycle(graph: dict[str, list[str]]) -> list[str] | None {
    nodes = _materialize_deps(graph);
    starts: list[Entity] = [];
    for nid in nodes {
        starts.append(nodes[nid]);
    }
    w = root spawn CycleWalker(claimed={}, state={}, stack=[], found=[]);
    for st in starts {
        st spawn CycleWalker(claimed=w.claimed, state=w.state, stack=w.stack, found=w.found);
    }
    if len(w.found) > 0 { return w.found; }
    return None;
}

