        mid = m["id"] as str;
        rid = m["roadmap_id"] as str;
        if rid not in roadmap_milestones {
            roadmap_milestones[rid] = [];
        }
        roadmap_milestones[rid].append(mid);
    }
    for p in prds {
        pid = p["id"] as str;
        prd_epics[pid] = p["epic_ids"] as list[str];
