    maps: dict[str, any] = {};
    maps["story_epic"] = story_epic;
    maps["epic_milestone"] = epic_milestone;
    maps["roadmap_milestones"] = roadmap_milestones;
    maps["prd_epics"] = prd_epics;
    return maps;
}

def resolve_chains(bundle: dict[str, any], maps: dict[str, any]) -> dict[str, any] {
    stories = bundle["stories"] as list[dict[str, any]];
    epics = bundle["epics"] as list[dict[str, any]];
    milestones = bundle["milestones"] as list[dict[str, any]];
    roadmaps = bundle["roadmaps"] as list[dict[str, any]];
    epic_idx = index_by_id(epics);
    ms_idx = index_by_id(milestones);
    rd_idx = index_by_id(roadmaps);
    story_epic = maps["story_epic"] as dict[str, str];
    epic_milestone = maps["epic_milestone"] as dict[str, str];
    chains: list[dict[str, any]] = [];
    errors: list[str] = [];
    for s in stories {
        sid = s["id"] as str;
        chain: dict[str, any] = {};
        chain["story"] = sid;
        if sid not in story_epic {
            errors.append("missing:story_epic:" + sid);
            chains.append(chain);
            continue;
        }
        eid = story_epic[sid];
        chain["epic"] = eid;
        if eid not in epic_idx {
            errors.append("missing:epic:" + eid);
            chains.append(chain);
            continue;
        }
        mid = epic_milestone[eid] if eid in epic_milestone else "";
        chain["milestone"] = mid;
        if mid == "" or mid not in ms_idx {
            errors.append("missing:milestone:" + eid);
            chains.append(chain);
            continue;
        }
        rid = ms_idx[mid]["roadmap_id"] as str;
        chain["roadmap"] = rid;
        if rid not in rd_idx {
            errors.append("missing:roadmap:" + rid);
            chains.append(chain);
            continue;
        }
        chains.append(chain);
    }
    out: dict[str, any] = {};
    out["chains"] = chains;
    out["errors"] = errors;
    return out;
}

def build_adjacency(bundle: dict[str, any]) -> dict[str, list[str]] {
    stories = bundle["stories"] as list[dict[str, any]];
    adj: dict[str, list[str]] = {};
    for s in stories {
        sid = s["id"] as str;
        deps = s["deps"] as list[str];
        if sid not in adj {
            adj[sid] = [];
        }
        for d in deps {
            adj[sid].append(d);
        }
    }
    return adj;
}

def build_dep_nodes(adj: dict[str, list[str]]) -> dict[str, DepNode] {
    nodes: dict[str, DepNode] = {};
    for src in adj {
        if src not in nodes {
            nd = DepNode(id=src);
            root ++> nd;
            nodes[src] = nd;
        }
        dep_list = adj[src];
        for dst in dep_list {
            if dst not in nodes {
                nd2 = DepNode(id=dst);
                root ++> nd2;
                nodes[dst] = nd2;
            }
            nodes[src] +>:Depends:+> nodes[dst];
        }
    }
    return nodes;
}

def detect_cycles(adj: dict[str, list[str]]) -> list[list[str]] {
    nodes = build_dep_nodes(adj);
    nids: list[str] = [];
    for k in nodes {
        nids.append(k);
    }
    nids = sorted(nids);
    all_cycles: list[list[str]] = [];
    for nid in nids {
        w = nodes[nid] spawn CycleFinder(adj=adj);
        for c in w.cycles {
            all_cycles.append(c);
        }
    }
    return all_cycles;
}

def topological_order(adj: dict[str, list[str]]) -> list[str] {
    if len(adj) == 0 {
