        nids.append(k);
    }
    nids = sorted(nids);
    merged: list[str] = [];
    seen: dict[str, bool] = {};
    has_cycle = False;
    for nid in nids {
        already = False;
        if nid in seen {
            already = seen[nid];
        }
        if already {
            continue;
        }
        w = nodes[nid] spawn TopoWalker(adj=adj);
        if w.has_cycle {
            has_cycle = True;
        }
        for x in w.order {
            if x not in seen or not seen[x] {
                merged.append(x);
                seen[x] = True;
            }
        }
    }
    if has_cycle {
        return [];
    }
    return merged;
}

def resolve_tree(bundle: dict[str, any]) -> dict[str, any] {
    maps = build_lookup_maps(bundle);
    chain_res = resolve_chains(bundle, maps);
    chains = chain_res["chains"] as list[dict[str, any]];
    errors = chain_res["errors"] as list[str];
    adj = build_adjacency(bundle);
    topo = topological_order(adj);
    cycles = detect_cycles(adj);
    if len(cycles) > 0 {
        errors.append("cycle:detected");
    }
    errors = sorted(errors);
    out: dict[str, any] = {};
    out["maps"] = maps;
    out["chains"] = chains;
    out["errors"] = errors;
    out["adj"] = adj;
    out["topo"] = topo;
    out["cycles"] = cycles;
    return out;
}

