"""Transitive subclass closure for type carve completeness (styk-tv/pgRDF#6)."""

node Type {
    has cid: str;
    has label: str = "";
}

edge SubClassOf {}

node Entity {
    has cid: str;
    has type_cid: str = "";
}

glob root;

def find_type(graph_root: Type, cid: str) -> Type | None {
    for t in [graph_root-->][?:Type] {
        if t.cid == cid {
            return t;
        }
    }
    return None;
}

walker SubclassWalker {
    has found: list[str] = [];
    has claimed: dict[str, bool] = {};

    can descend with Type entry {
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        self.found.append(here.cid);
        print("closure visit", here.cid);
        subs: list[Type] = [here <-:SubClassOf:<-][?:Type];
        if subs {
            visit :0: subs;
        } else {
            disengage;
        }
    }
}

def subclass_closure(graph_root: Type, anchor_cid: str) -> list[str] {
    anchor = find_type(graph_root, anchor_cid);
    if not anchor {
        return [];
    }
    claimed: dict[str, bool] = {};
    wk = anchor spawn SubclassWalker(claimed=claimed);
    out: list[str] = [];
    for x in wk.found {
        out.append(x);
    }
    out.sort();
    return out;
}

def expanded_type_set(
    graph_root: Type,
    anchor_cids: list[str],
    include_subclasses: bool,
) -> list[str] {
    acc: list[str] = [];
    seen: dict[str, bool] = {};
    for ac in anchor_cids {
        part: list[str] = [];
        if include_subclasses {
            part = subclass_closure(graph_root, ac);
        } else {
            ft = find_type(graph_root, ac);
            if ft {
                part.append(ac);
            }
        }
        for p in part {
            if p not in seen {
                seen[p] = True;
                acc.append(p);
            }
        }
    }
    acc.sort();
    return acc;
}

def entities_matching_type(
    graph_root: Type,
    anchor_type: str,
    include_subclasses: bool,
) -> list[str] {
    allowed = expanded_type_set(graph_root, [anchor_type], include_subclasses);
    allow: dict[str, bool] = {};
    for a in allowed {
        allow[a] = True;
    }
    hits: list[str] = [];
    for ent in [graph_root-->][?:Entity] {
        if ent.type_cid in allow {
            hits.append(ent.cid);
        }
    }
    hits.sort();
    return hits;
}

def register_entity(graph_root: Type, cid: str, type_cid: str) -> Entity {
    ent = Entity(cid=cid, type_cid=type_cid);
    graph_root ++> ent;
    return ent;
}
