"""Transitive subclass closure for type carve — styk-tv/pgRDF#6."""

node Type {
    has cid: str;
    has label: str;
}

node Entity {
    has cid: str;
    has name: str;
}

edge SubclassOf {}

edge InstanceOf {}

def find_type(graph_root: Type, cid: str) -> Type | None {
    if graph_root.cid == cid {
        return graph_root;
    }
    kids: list[Type] = [];
    for ch in [graph_root ->:][:?:Type] {
        kids.append(ch);
    }
    for ch in kids {
        hit = find_type(ch, cid);
        if hit {
            return hit;
        }
    }
    return None;
}

walker SubclassDescent {
    has claimed: dict[str, bool] = {};
    has found: list[str] = [];

    can step with Type entry {
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        self.found.append(here.cid);
        kids: list[Type] = [];
        for ch in [here <-:SubclassOf:<-][?:Type] {
            kids.append(ch);
        }
        if kids {
            visit kids;
        } else {
            disengage;
        }
    }
}

def subclass_closure(graph_root: Type, anchor_cid: str) -> list[str] {
    anchor = find_type(graph_root, anchor_cid);
    if not anchor {
        return [];
    }
    wk = anchor spawn SubclassDescent();
    out: list[str] = [];
    for cid in wk.found {
        out.append(cid);
    }
    return sorted(out);
}

def entities_of_type(
    graph_root: Type,
    anchor_cid: str,
    include_subclasses: bool
) -> list[str] {
    allowed: dict[str, bool] = {};
    if include_subclasses {
        closed = subclass_closure(graph_root, anchor_cid);
        for cid in closed {
            allowed[cid] = True;
        }
    } else {
        allowed[anchor_cid] = True;
    }
    ents: list[str] = [];
    for ent in [graph_root ->:][:?:Entity] {
        match = False;
        for t in [ent ->:InstanceOf:->][?:Type] {
            if t.cid in allowed {
                match = True;
            }
        }
        if match {
            ents.append(ent.cid);
        }
    }
    return sorted(ents);
}

def build_demo_graph() -> Type {
    gr = Type(cid="graph", label="graph");
    root ++> gr;
    univ = Type(cid="Q3918", label="university");
    pub = Type(cid="Q875538", label="public university");
    gr ++> univ;
    gr ++> pub;
    pub +>:SubclassOf:+> univ;
    ent = Entity(cid="E-demo", name="State College");
    gr ++> ent;
    ent +>:InstanceOf:+> pub;
    return gr;
}

walker DemoWalker {
    can run with Type entry {
        if here.cid != "graph" {
            disengage;
        }
        closed = subclass_closure(here, "Q3918");
        print(closed);
        ents = entities_of_type(here, "Q3918", True);
        print(ents);
        disengage;
    }
}

with entry {
    build_demo_graph();
    root spawn DemoWalker;
}
