"""Synthetic OSP lift for iteathen/Connect4#13 — coarse multicore negamax subtree dispatch."""

node Position {
    has pid: str;
    has depth: int = 0;
    has score: int = 0;
}

edge Branch {}

walker FrontierWalk {
    has claimed: dict[str, bool] = {};
    has frontier: list[str] = [];
    has cap: int = 1;
    has visit_count: int = 0;

    can step with Position entry {
        print("frontier step ", here.pid);
        if here.pid in self.claimed {
            skip;
        }
        self.claimed[here.pid] = True;
        self.visit_count += 1;
        if here.depth >= self.cap {
            self.frontier.append(here.pid);
            disengage;
        }
        kids: list[Position] = [here ->:Branch:->][?:Position];
        if kids {
            visit :0: kids;
        } else {
            disengage;
        }
    }
}

def available_parallelism() -> int {
    return 4;
}

def lookup_score(pid: str) -> int {
    if pid == "r" {
        return 3;
    }
    if pid == "a" {
        return 1;
    }
    if pid == "b" {
        return 2;
    }
    if pid == "c" {
        return 4;
    }
    return 0;
}

def select_active_workers(capacity: int, frontier_count: int, depth_hint: int) -> int {
    active: int = 1;
    if capacity > 1 {
        if frontier_count > 1 {
            active = capacity;
        }
    }
    if depth_hint < 2 {
        active = 1;
    }
    if active > frontier_count {
        active = frontier_count;
    }
    if active < 1 {
        active = 1;
    }
    return active;
}

def build_diamond_tree() -> Position {
    graph_root = Position(pid="r", depth=0, score=3);
    na = Position(pid="a", depth=1, score=1);
    nb = Position(pid="b", depth=1, score=2);
    nc = Position(pid="c", depth=2, score=4);
    graph_root +>:Branch:+> na;
    graph_root +>:Branch:+> nb;
    na +>:Branch:+> nc;
    nb +>:Branch:+> nc;
    return graph_root;
}

def coarse_search(graph_root: Position, worker_cap: int, depth_cap: int) -> int {
    w = graph_root spawn FrontierWalk(claimed={}, frontier=[], cap=depth_cap, visit_count=0);
    ordered: list[str] = sorted(w.frontier);
    active = select_active_workers(worker_cap, len(ordered), depth_cap);
    best: int = -9999;
    for pid in ordered {
        sc = lookup_score(pid);
        if sc > best {
            best = sc;
        }
    }
    if best < 0 {
        return 0;
    }
    if active > 1 {
        return best;
    }
    return best;
}

with entry {
    graph_root = build_diamond_tree();
    root ++> graph_root;
    cap = available_parallelism();
    out = coarse_search(graph_root, cap, 1);
    print("coarse_search=", out);
}
