```jac
"""iteathen/Connect4#13 — multicore coarse negamax subtree dispatch."""

node Position {
    has pid: str;
    has leaf_score: int = 0;
}

edge Move {}

walker CoarseFrontier {
    has claimed: dict[str, bool] = {};
    has visit_count: int = 0;
    has leaf_evals: int = 0;
    has visited: list[str] = [];

    can step with Position entry {
        if here.pid in self.claimed {
            skip;
        }
        self.claimed[here.pid] = True;
        self.visit_count += 1;
        self.visited.append(here.pid);
        print("frontier step ", here.pid);
        if here.leaf_score != 0 {
            self.leaf_evals += 1;
        }
        kids: list[Position] = [here ->:Move:->][?:Position];
        for ch in kids {
            visit :0: [ch];
        }
    }
}

def make_node(pid: str, leaf_score: int = 0) -> Position {
    nd = Position(pid=pid, leaf_score=leaf_score);
    root ++> nd;
    return nd;
}

def link_nodes(parent: Position, child: Position) {
    parent +>:Move:+> child;
}

def detect_parallelism() -> int {
    return 4;
}

def init_worker_pool(cap: int) -> dict[str, int] {
    eff: int = cap;
    if eff < 1 {
        eff = 1;
    }
    store: dict[str, int] = {};
    store["max"] = eff;
    store["warm"] = eff;
    return store;
}

def cap_active_workers(max_workers: int, active_workers: int, pool_max: int) -> int {
    eff: int = active_workers;
    if eff < 1 {
        eff = 1;
    }
    mw: int = max_workers;
    if mw < 1 {
        mw = 1;
    }
    if eff > mw {
        eff = mw;
    }
    if eff > pool_max {
        eff = pool_max;
    }
    return eff;
}

def pool_get(pool: dict[str, int], key: str) -> int {
    if key in pool {
        return pool[key];
    }
    return 0;
}

def frontier_visit_count(root_node: Position) -> int {
    w = root_node spawn CoarseFrontier(claimed={});
    return w.visit_count;
}

def frontier_visit_ids(root_node: Position) -> list[str] {
    w = root_node spawn CoarseFrontier(claimed={});
    out: list[str] = w.visited;
    return sorted(out);
}

def coarse_search(root_node: Position, max_workers: int, active_workers: int) -> int {
    pool: dict[str, int] = init_worker_pool(max_workers);
    pool_max: int = pool["max"];
    active: int = cap_active_workers(max_workers, active_workers, pool_max);
    w = root_node spawn CoarseFrontier(claimed={});
    if active < 1 {
        return 0;
    }
    return w.leaf_evals;
}
