        nodes.append(nd);
        by_id[wid] = nd;
        root ++> nd;
    }
    for nd in nodes {
        if nd.root_bead_id != "" and nd.root_bead_id in by_id {
            parent: Wisp = by_id[nd.root_bead_id];
            parent +>:ChildOf:+> nd;
        }
    }
    if extra_pairs is not None {
        for pair in extra_pairs {
            a_id: str = pair[0];
            b_id: str = pair[1];
            if a_id in by_id and b_id in by_id {
                child: Wisp = by_id[a_id];
                par: Wisp = by_id[b_id];
                par +>:ChildOf:+> child;
