def get_or_create_table(reg: SchemaRegistry, table_name: str) -> Table {
    if table_name in reg.tables {
        return reg.tables[table_name];
    }
    tbl = Table(name=table_name);
    reg.tables[table_name] = tbl;
    root ++> tbl;
    reg.anchor +>:FkRef:+> tbl;
    return tbl;
}

def register_table(reg: SchemaRegistry, table_name: str, references: list[str]) -> None {
    tbl = get_or_create_table(reg, table_name);
    for ref_name in references {
        ref_tbl = get_or_create_table(reg, ref_name);
        tbl +>:FkRef:+> ref_tbl;
    }
}

def circular_dependency_tables(reg: SchemaRegistry) -> list[str] {
    w = reg.anchor spawn FkCycleScan(
        claimed={}, finished={}, cycle_hit={}, has_cycle=False
    );
    out: list[str] = [];
    if w.has_cycle {
        names: list[str] = [];
        for nm in w.cycle_hit {
            names.append(nm);
        }
        names.sort();
        out = names;
    }
    return out;
