def compute_postorder(albums_here: dict[str, int], children: dict[str, list], root_cid: str) -> dict[str, int] {
    totals: dict[str, int] = {};
    stack: list[str] = [root_cid];
    order: list[str] = [];
    while len(stack) > 0 {
        cid = stack.pop();
        order.append(cid);
        ch: list = children.get(cid, []);
        for c in ch {
            stack.append(c);
        }
    }
    order.reverse();
    for cid in order {
        t: int = albums_here.get(cid, 0);
        ch2: list = children.get(cid, []);
        for c in ch2 {
