"""BOM explosion lift — raphael-cura/ExplodeBOM#1."""

glob EPSILON = 1e-12;
glob MIN_QUANTITY_THRESHOLD = 1e-12;

node Product {
    has pid: int;
    has name: str;
}

edge Uses {
    has ratio: float;
}

walker ExplodeWalker {
    has claimed: dict[str, bool] = {};
    has results: list[dict] = [];
    has depth: int = 0;
    has max_depth: int = 50;
    has mult: float = 1.0;
    has parent_id: int = -1;
    has colfilial: str = "";
    has enable_logging: bool = True;
    has next_mults: dict[str, float] = {};
    has next_parents: dict[str, int] = {};

    can step with Product entry {
        pid_key: str = str(here.pid);
        if pid_key in self.claimed {
            skip;
        }
        self.claimed[pid_key] = True;
        eff_mult: float = self.mult;
        if pid_key in self.next_mults {
            eff_mult = self.next_mults[pid_key];
            self.mult = eff_mult;
        }
        if pid_key in self.next_parents {
            self.parent_id = self.next_parents[pid_key];
        }
        if self.depth > 0 {
            row: dict = {};
            row["parent_id"] = self.parent_id;
            row["child_id"] = here.pid;
            row["name"] = here.name;
            row["qty"] = eff_mult;
            row["depth"] = self.depth;
            row["key_colfilial"] = self.colfilial;
            self.results.append(row);
        }
        if self.enable_logging {
            print({"event": "explode", "pid": here.pid, "depth": self.depth, "qty": eff_mult});
        }
        if self.depth >= self.max_depth {
            disengage;
        }
        kids: list[Product] = [here ->:Uses:->][?:Product];
        pending: list[Product] = [];
        for ch in kids {
            es: list[Uses] = [here ->:Uses:-> ch];
            rv: float = 1.0;
            if len(es) > 0 {
                rv = es[0].ratio;
            }
            ck: str = str(ch.pid);
            self.next_mults[ck] = eff_mult * rv;
            self.next_parents[ck] = here.pid;
            pending.append(ch);
        }
        visit pending else {
            disengage;
        }
    }
}

def _ensure_product(store: dict[str, Product], pid: int, name: str) -> Product {
    key: str = str(pid);
    if key in store {
        return store[key];
    }
    nd: Product = Product(pid=pid, name=name);
    root ++> nd;
    store[key] = nd;
    return nd;
}

def _sort_exploded(rows: list[dict]) -> list[dict] {
    out: list[dict] = [];
    for r in rows {
        out.append(r);
    }
    n: int = len(out);
    i: int = 0;
    while i < n {
        j: int = i + 1;
        while j < n {
            a: dict = out[i];
            b: dict = out[j];
            swap: bool = False;
            da: int = int(a["depth"]);
            db: int = int(b["depth"]);
            if da > db {
                swap = True;
            } else {
                if da == db {
                    ca: int = int(a["child_id"]);
                    cb: int = int(b["child_id"]);
                    if ca > cb {
                        swap = True;
                    } else {
                        if ca == cb {
                            if int(a["parent_id"]) > int(b["parent_id"]) {
                                swap = True;
                            }
                        }
                    }
                }
            }
            if swap {
                tmp: dict = out[i];
                out[i] = out[j];
                out[j] = tmp;
            }
            j += 1;
        }
        i += 1;
    }
    return out;
}

def explode_bom(
    df_bom: list[dict],
    key_colfilial: str | None = None,
    roots: list[int] | None = None,
    max_depth: int = 50,
    max_iter: int = 20,
    tol: float = 1e-9,
    intermediate_handling: str = "split",
    enable_logging: bool = False
) -> list[dict] {
    store: dict[str, Product] = {};
    parent_ids: dict[str, bool] = {};
    child_ids: dict[str, bool] = {};
    for row in df_bom {
        kf: str = str(row.get("key_colfilial", ""));
        if key_colfilial is not None and kf != key_colfilial {
            continue;
        }
        pp: int = int(row["parent_id"]);
        cc: int = int(row["child_id"]);
        ratio: float = float(row["qty"]);
        pname: str = str(row.get("parent_name", str(pp)));
        cname: str = str(row.get("child_name", str(cc)));
        pnd: Product = _ensure_product(store, pp, pname);
        cnd: Product = _ensure_product(store, cc, cname);
        pnd +>:Uses:ratio=ratio:+> cnd;
        parent_ids[str(pp)] = True;
        child_ids[str(cc)] = True;
    }
