        }
        graph_root: Product = store[sk];
        claimed: dict[str, bool] = {};
        next_mults: dict[str, float] = {};
        next_parents: dict[str, int] = {};
        wk: ExplodeWalker = graph_root spawn ExplodeWalker(
            claimed=claimed,
            results=all_results,
            depth=0,
            max_depth=max_depth,
            mult=1.0,
            parent_id=-1,
            colfilial=kf_out,
            enable_logging=enable_logging,
            next_mults=next_mults,
            next_parents=next_parents
        );
    }
    if intermediate_handling == "split" {
        tagged: list[dict] = [];
        for r in all_results {
            cid: str = str(r["child_id"]);
            kind: str = "raw";
            if cid in parent_ids {
