            nr["name"] = r["name"];
            nr["qty"] = r["qty"];
            nr["depth"] = r["depth"];
            nr["key_colfilial"] = r["key_colfilial"];
            nr["line_type"] = kind;
            tagged.append(nr);
        }
        return _sort_exploded(tagged);
    }
    return _sort_exploded(all_results);
