        }
        if "child_name" in row {
            cname = row["child_name"];
        }
        if "is_produced" in row {
            pprod = row["is_produced"];
        }
        if "child_is_produced" in row {
            cprod = row["child_is_produced"];
        }
        h.ensure_item(pid, pname, pprod);
