            }
            rnode: Item = h.items[rid];
            graph_root ++> rnode;
            wk: ExplodeWalker = rnode spawn ExplodeWalker(
                claimed={},
                root_id=rid,
                max_depth=max_depth,
                enable_logging=enable_logging
            );
            for rec in wk.out {
                merged.append(rec);
            }
        }
        if iter_n >= 1 {
            break;
        }
    }
    if intermediate_handling == "split" {
        tagged: list[dict] = [];
        for rec in merged {
            nr: dict = {};
            nr["root_id"] = rec["root_id"];
            nr["component_id"] = rec["component_id"];
            nr["depth"] = rec["depth"];
            nr["qty"] = rec["qty"];
