def create_insert_shape(g: CommentGraph, parent_id: str | None, max_depth: int) -> dict {
    out: dict = {};
    if parent_id is None {
        out["stored_parent_id"] = None;
        out["depth"] = 0;
        out["intended_parent_id"] = None;
        out["aborts"] = False;
        return out;
    }
    anchor = find_anchor(g, parent_id, max_depth);
    if anchor is not None {
        ac = g.by_id[anchor];
        out["stored_parent_id"] = anchor;
        out["depth"] = ac.depth + 1;
        out["intended_parent_id"] = parent_id;
        out["aborts"] = False;
        return out;
    }
    out["stored_parent_id"] = None;
    out["depth"] = 0;
    out["intended_parent_id"] = parent_id;
    out["aborts"] = True;
    return out;
