        stop: bool = False;
        for j in range(n) {
            a: str = cyc[(i + j) % n];
            b: str = cyc[(best_i + j) % n];
            if a < b {
                better = True;
                stop = True;
                break;
            }
            if a > b {
                stop = True;
                break;
            }
        }
        if better {
            best_i = i;
        }
    }
    out: list[str] = [];
