"""Comment depth-cap anchor walk — 1f916-ai/1f916#249."""

node Comment {
  has cid: str;
  has depth: int = 0;
}

edge ParentOf {}

obj CommentGraph {
  has by_id: dict[str, Comment] = {};
}

walker AnchorSeek {
  has cap: int = 0;
  has claimed: dict[str, bool] = {};
  has found: str = "";

  can ascend with Comment entry {
    if here.cid in self.claimed { skip; }
    self.claimed[here.cid] = True;
    print("ascend", here.cid, here.depth);
    if here.depth < self.cap {
      self.found = here.cid;
      print("anchor_hit", self.found);
      disengage;
    }
    parents: list[Comment] = [here ->:ParentOf:->][?:Comment];
    if parents {
      visit :0: parents;
    } else {
      disengage;
    }
  }
}

walker BootDemo {
  has graph: CommentGraph;
  has parent_id: str = "";
  has max_cap: int = 5;

  can boot with Comment entry {
    shape = create_insert_shape(self.graph, self.parent_id, self.max_cap);
    print("boot_shape", shape["stored_parent_id"], shape["would_abort"]);
    disengage;
  }
}

def comment_graph() -> CommentGraph {
  return CommentGraph();
}

def add_comment(g: CommentGraph, cid: str, depth: int) -> Comment {
  nd = Comment(cid=cid, depth=depth);
  g.by_id[cid] = nd;
  root ++> nd;
  return nd;
}

def link_parent(g: CommentGraph, child_id: str, parent_id: str) -> None {
  child = g.by_id[child_id];
  par = g.by_id[parent_id];
  child +>:ParentOf:+> par;
}

def find_anchor(g: CommentGraph, parent_id: str | None, max_depth: int) -> str | None {
  if parent_id is None {
    return None;
  }
  if parent_id not in g.by_id {
    return None;
  }
  start = g.by_id[parent_id];
  w = start spawn AnchorSeek(cap=max_depth, claimed={});
  if w.found == "" {
    return None;
  }
  return w.found;
}

def create_insert_shape(
  g: CommentGraph, parent_id: str | None, max_depth: int
) -> dict[str, str | int | bool | None] {
  out: dict[str, str | int | bool | None] = {};
  if parent_id is None {
    out["stored_parent_id"] = None;
    out["intended_parent_id"] = None;
    out["depth"] = 0;
    out["would_abort"] = False;
    return out;
  }
  anchor_id = find_anchor(g, parent_id, max_depth);
  if anchor_id is None {
    out["stored_parent_id"] = None;
    out["intended_parent_id"] = parent_id;
    out["depth"] = 0;
    out["would_abort"] = True;
    return out;
  }
  anchor = g.by_id[anchor_id];
  out["stored_parent_id"] = anchor_id;
  out["intended_parent_id"] = parent_id;
  out["depth"] = anchor.depth + 1;
  out["would_abort"] = False;
  return out;
}

with entry {
  g = comment_graph();
  graph_root = add_comment(g, "boot", 0);
  kid = add_comment(g, "kid", 1);
  link_parent(g, "kid", "boot");
  wk = graph_root spawn BootDemo(graph=g, parent_id="kid", max_cap=5);
}
