            return False;
        }
        u_nd = self._nodes[u] as V;
        v_nd = self._nodes[v] as V;
        u_nd +>:E:+> v_nd;
        return True;
    }

    can has_vertex(self, vertex_id: str) -> bool {
        return vertex_id in self._nodes;
    }

