def sorted_nbr_vertices(nbrs: list[V]) -> list[V] {
    out: list[V] = [];
    ids: list[str] = [];
    for nb in nbrs {
        ids.append(nb.vid);
    }
    ids = sorted(ids);
    for sid in ids {
        for nb in nbrs {
            if nb.vid == sid {
