        raw: list[V] = [here ->:E:->][?:V];
        nbrs: list[V] = sorted_nbr_vertices(raw);
        for ch in nbrs {
            if ch.vid not in self.claimed {
                visit [ch];
            }
        }
    }
}

walker DfsRecWalker {
    has order: list[str] = {};
    has claimed: dict[str, bool] = {};

    can walk with V entry {
        if here.vid in self.claimed {
            skip;
        }
        self.claimed[here.vid] = True;
        self.order.append(here.vid);
        print(f"dfs_rec visit {here.vid}");
        raw: list[V] = [here ->:E:->][?:V];
        nbrs: list[V] = sorted_nbr_vertices(raw);
        rev: list[V] = [];
        idx: int = len(nbrs) - 1;
        while idx >= 0 {
            rev.append(nbrs[idx]);
            idx = idx - 1;
        }
        for ch in rev {
            if ch.vid not in self.claimed {
                visit :0: [ch];
            }
