"""F3-Nation/f3-nation#1001 depth-agnostic org ancestry for pv_* flattening."""

node Org {
    has cid: str;
    has name: str;
    has org_type: str;
}

edge Parent {}

walker LookupOrg {
    has target_id: str = "";
    has claimed: dict[str, bool] = {};
    has hit: Org | None = None;

    can seek with Org entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        if here.cid == self.target_id {
            self.hit = here;
            print ["lookup_hit", here.cid];
            disengage;
        }
        nbrs: list[Org] = [];
        for par in [here ->:Parent:->][?:Org] { nbrs.append(par); }
        for ch in [here <-:Parent:<-][?:Org] { nbrs.append(ch); }
        if len(nbrs) > 0 { visit nbrs; } else { disengage; }
    }
}

walker AncestorFind {
    has target_type: str = "";
    has claimed: dict[str, bool] = {};
    has found_id: str = "";
    has found_name: str = "";

    can climb with Org entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        if here.org_type == self.target_type {
            self.found_id = here.cid;
            self.found_name = here.name;
            print ["ancestor_found", self.found_id, self.target_type];
            disengage;
        }
        parents: list[Org] = [here ->:Parent:->][?:Org];
        if len(parents) > 0 { visit parents; } else { disengage; }
    }
}

walker ChainCollect {
    has claimed: dict[str, bool] = {};
    has chain: list[Org] = [];

    can climb with Org entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        self.chain.append(here);
        print ["chain_add", here.cid, here.org_type];
        parents: list[Org] = [here ->:Parent:->][?:Org];
        if len(parents) > 0 { visit parents; } else { disengage; }
    }
}

walker DescendantCount {
    has target_type: str = "";
    has claimed: dict[str, bool] = {};
    has count: int = 0;

    can descend with Org entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        if here.org_type == self.target_type {
            self.count = self.count + 1;
            print ["desc_count", here.cid, self.count];
        }
        kids: list[Org] = [here <-:Parent:<-][?:Org];
        if len(kids) > 0 { visit :0: kids; } else { disengage; }
    }
}

walker DescendantIds {
    has target_type: str = "";
    has claimed: dict[str, bool] = {};
    has ids: list[str] = [];

    can descend with Org entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        if here.org_type == self.target_type {
            self.ids.append(here.cid);
            print ["desc_id", here.cid];
        }
        kids: list[Org] = [here <-:Parent:<-][?:Org];
        if len(kids) > 0 { visit :0: kids; } else { disengage; }
    }
}

def resolve_org(graph_root: node, org_id: str) -> Org | None {
    w = graph_root spawn LookupOrg(target_id=org_id);
    return w.hit;
}

def find_ancestor_by_type(graph_root: node, org_id: str, target_type: str) -> list[str] {
    org = resolve_org(graph_root, org_id);
    if org is None { return ["", ""]; }
    w = org spawn AncestorFind(target_type=target_type);
    return [w.found_id, w.found_name];
}

def flatten_org_tiers(graph_root: node, org_id: str) -> dict[str, str] {
    tier_types: list[str] = ["ao", "region", "area", "territory", "sector"];
    out: dict[str, str] = {};
    for tt in tier_types {
        out[tt + "_org_id"] = "";
        out[tt + "_name"] = "";
    }
    org = resolve_org(graph_root, org_id);
    if org is None { return out; }
    w = org spawn ChainCollect();
    for nd in w.chain {
        if nd.org_type == "ao" or nd.org_type == "region" or nd.org_type == "area"
            or nd.org_type == "territory" or nd.org_type == "sector" {
            out[nd.org_type + "_org_id"] = nd.cid;
            out[nd.org_type + "_name"] = nd.name;
        }
    }
    return out;
}

def count_descendants_by_type(graph_root: node, root_org_id: str, descendant_type: str) -> int {
    org = resolve_org(graph_root, root_org_id);
    if org is None { return 0; }
    w = org spawn DescendantCount(target_type=descendant_type);
    return w.count;
}

def list_descendant_ids_by_type(graph_root: node, root_org_id: str, descendant_type: str) -> list[str] {
    org = resolve_org(graph_root, root_org_id);
    if org is None { return []; }
    w = org spawn DescendantIds(target_type=descendant_type);
    return sorted(w.ids);
}
