"""Graph traversal (BFS & DFS) — DH-YASSER/algorithms-practice#1."""

node GNode {
    has nid: str;
}

edge GEdge {}

def adj_keys(adj: dict[str, list[str]]) -> list[str] {
    keys: list[str] = [];
    for k in adj {
        keys.append(k);
    }
    return sorted(keys);
}

def has_key(adj: dict[str, list[str]], key: str) -> bool {
    for k in adj {
        if k == key {
            return True;
        }
    }
    return False;
}

def build_graph(adj: dict[str, list[str]], start: str) -> GNode {
    store: dict[str, GNode] = {};
    keys: list[str] = adj_keys(adj);
    for kid in keys {
        nd = GNode(nid=kid);
        store[kid] = nd;
        root ++> nd;
    }
    for kid in keys {
        src_nd = store[kid] as GNode;
        neigh: list[str] = adj[kid];
        for dst_id in neigh {
            dst_nd = store[dst_id] as GNode;
            src_nd +>:GEdge:+> dst_nd;
        }
    }
    return store[start] as GNode;
}

def sorted_children(here: GNode) -> list[GNode] {
    child_map: dict[str, GNode] = {};
    ids: list[str] = [];
    for ch in [here ->:GEdge:->][?:GNode] {
        ids.append(ch.nid);
        child_map[ch.nid] = ch;
    }
    ids = sorted(ids);
    out: list[GNode] = [];
    for cid in ids {
        out.append(child_map[cid] as GNode);
    }
    return out;
}

def bfs(adj: dict[str, list[str]], start: str) -> list[str] {
    if not has_key(adj, start) {
        return [];
    }
    graph_root = build_graph(adj, start);
    w = graph_root spawn BfsWalker();
    print("bfs", w.order);
    return w.order;
}

def dfs_iterative(adj: dict[str, list[str]], start: str) -> list[str] {
    if not has_key(adj, start) {
        return [];
    }
    graph_root = build_graph(adj, start);
    w = graph_root spawn DfsIterWalker();
    print("dfs_iter", w.order);
    return w.order;
}

def dfs_recursive(adj: dict[str, list[str]], start: str) -> list[str] {
    if not has_key(adj, start) {
        return [];
    }
    graph_root = build_graph(adj, start);
    w = graph_root spawn DfsRecWalker();
    print("dfs_rec", w.order);
    return w.order;
}

walker BfsWalker {
    has claimed: dict[str, bool] = {};
    has order: list[str] = [];

    can traverse with GNode entry {
        if here.nid in self.claimed {
            skip;
        }
        self.claimed[here.nid] = True;
        self.order.append(here.nid);
        print("bfs visit", here.nid);
        kids: list[GNode] = sorted_children(here);
        if kids {
            for ch in kids {
                visit [ch];
            }
        } else {
            disengage;
        }
    }
}

walker DfsIterWalker {
    has claimed: dict[str, bool] = {};
    has order: list[str] = [];

    can traverse with GNode entry {
        if here.nid in self.claimed {
            skip;
        }
        self.claimed[here.nid] = True;
        self.order.append(here.nid);
        print("dfs_iter visit", here.nid);
        kids: list[GNode] = sorted_children(here);
        if kids {
            idx = len(kids) - 1;
            while idx >= 0 {
                visit :0: [kids[idx]];
                idx = idx - 1;
            }
        } else {
            disengage;
        }
    }
}

walker DfsRecWalker {
    has claimed: dict[str, bool] = {};
    has order: list[str] = [];

    can traverse with GNode entry {
        if here.nid in self.claimed {
            skip;
        }
        self.claimed[here.nid] = True;
        self.order.append(here.nid);
        print("dfs_rec visit", here.nid);
        kids: list[GNode] = sorted_children(here);
        if kids {
            for ch in kids {
                if ch.nid not in self.claimed {
                    visit [ch];
                    break;
                }
            }
            disengage;
        } else {
            disengage;
        }
    }
}
