"""EleutherAI/lm-evaluation-harness#4133 — reject cyclic group_subtasks before hierarchy display ordering."""

node Group {
    has gid: str;
}

edge Subtask {}

walker ValidateHierarchy {
    has on_stack: dict[str, bool] = {};
    has finished: dict[str, bool] = {};
    has found_cycle: bool = False;

    can validate with Group entry {
        if here.gid in self.on_stack {
            self.found_cycle = True;
            print("cycle", here.gid);
            skip;
        }
        if here.gid in self.finished {
            skip;
        }
        self.on_stack[here.gid] = True;
        kids: list[Group] = [here ->:Subtask:->][?:Group];
        kid_names: list[str] = [];
        for kd in kids {
            kid_names.append(kd.gid);
        }
        kid_names = sorted(kid_names);
        for kn in kid_names {
            for kd in kids {
                if kd.gid == kn {
                    visit kd;
                }
            }
        }
        self.on_stack[here.gid] = False;
        self.finished[here.gid] = True;
        print("validate", here.gid);
    }
}

walker BuildHierarchy {
    has claimed: dict[str, bool] = {};
    has rows: list[tuple[str, int]] = [];
    has current_depth: int = 0;

    can walk with Group entry {
        if here.gid in self.claimed {
            skip;
        }
        self.claimed[here.gid] = True;
        self.rows.append((here.gid, self.current_depth));
        print("row", here.gid, self.current_depth);
        kids: list[Group] = [here ->:Subtask:->][?:Group];
        kid_names: list[str] = [];
        for kd in kids {
            kid_names.append(kd.gid);
        }
        kid_names = sorted(kid_names);
        saved: int = self.current_depth;
        for kn in kid_names {
            for kd in kids {
                if kd.gid == kn {
                    self.current_depth = saved + 1;
                    visit :0: kd;
                }
            }
        }
        self.current_depth = saved;
    }
}

def _materialize_graph(
    group_subtasks: dict[str, list[str]],
    available_keys: list[str],
) -> tuple[Group, dict[str, Group]] {
    anchor = Group(gid="__anchor__");
    root ++> anchor;
    nodes: dict[str, Group] = {};
    avail: dict[str, bool] = {};
    for k in available_keys {
        avail[k] = True;
    }
    for gname in group_subtasks {
        if gname not in avail {
            continue;
        }
        if gname not in nodes {
            nd = Group(gid=gname);
            nodes[gname] = nd;
            anchor ++> nd;
        }
    }
    for gname in group_subtasks {
        if gname not in avail {
            continue;
        }
        parent = nodes[gname];
        child_list = group_subtasks[gname];
        for cname in child_list {
            if cname not in avail {
                continue;
            }
            if cname not in nodes {
                ch = Group(gid=cname);
                nodes[cname] = ch;
                anchor ++> ch;
            }
            child = nodes[cname];
            parent +>:Subtask:+> child;
        }
    }
    return (anchor, nodes);
}

def _find_roots(
    group_subtasks: dict[str, list[str]],
    available_keys: list[str],
) -> list[str] {
    referenced: dict[str, bool] = {};
    for gname in group_subtasks {
        child_list = group_subtasks[gname];
        for cname in child_list {
            referenced[cname] = True;
        }
    }
    avail: dict[str, bool] = {};
    for k in available_keys {
        avail[k] = True;
    }
    roots: list[str] = [];
    for gname in group_subtasks {
        if gname not in avail {
            continue;
        }
        if gname not in referenced {
            roots.append(gname);
        }
    }
    roots = sorted(roots);
    return roots;
}

def _validate_no_cycles(
    group_subtasks: dict[str, list[str]],
    available_keys: list[str],
) -> None {
    (_anchor, nodes) = _materialize_graph(group_subtasks, available_keys);
    on_stack: dict[str, bool] = {};
    finished: dict[str, bool] = {};
    found: bool = False;
    roots = _find_roots(group_subtasks, available_keys);
    for rname in roots {
        if rname in nodes {
            rn = nodes[rname];
            v = rn spawn ValidateHierarchy(on_stack=on_stack, finished=finished, found_cycle=found);
            found = v.found_cycle;
            on_stack = v.on_stack;
            finished = v.finished;
        }
    }
    for nname in nodes {
        if nname not in finished {
            nd = nodes[nname];
            v = nd spawn ValidateHierarchy(on_stack=on_stack, finished=finished, found_cycle=found);
            found = v.found_cycle;
            on_stack = v.on_stack;
            finished = v.finished;
        }
    }
    if found {
        raise ValueError("cyclic group_subtasks metadata");
    }
}

def _build_hierarchy_info(
    group_subtasks: dict[str, list[str]],
    available_keys: list[str],
) -> list[tuple[str, int]] {
    _validate_no_cycles(group_subtasks, available_keys);
    (_anchor, nodes) = _materialize_graph(group_subtasks, available_keys);
    roots = _find_roots(group_subtasks, available_keys);
    shared_claimed: dict[str, bool] = {};
    rows_out: list[tuple[str, int]] = [];
    for rname in roots {
        if rname in nodes {
            rn = nodes[rname];
            wk = rn spawn BuildHierarchy(claimed=shared_claimed, rows=rows_out, current_depth=0);
            rows_out = wk.rows;
            shared_claimed = wk.claimed;
        }
    }
    return rows_out;
}
