"""EleutherAI/lm-evaluation-harness#4133 — cyclic group_subtasks validation."""

node Group {
    has gid: str;
}

edge Subtask {}

walker ValidateWalker {
    has group_subtasks: dict[str, list[str]] = {};
    has available: dict[str, bool] = {};
    has active: dict[str, bool] = {};
    has completed: dict[str, bool] = {};
    has nodes: dict[str, Group] = {};
    has err: str = "";

    can validate with Group entry {
        g = here.gid;
        if g in self.active {
            self.err = "cyclic group_subtasks metadata";
            print("cycle ", g);
            disengage;
        }
        if g in self.completed {
            skip;
        }
        self.active[g] = True;
        print("validate ", g);
        kids: list[str] = [];
        if g in self.group_subtasks {
            kids = self.group_subtasks[g];
        }
        for ch in kids {
            if ch in self.available and ch in self.nodes {
                visit :0: [self.nodes[ch]];
            }
        }
        self.active[g] = False;
        self.completed[g] = True;
        disengage;
    }
}

walker BuildWalker {
    has group_subtasks: dict[str, list[str]] = {};
    has available: dict[str, bool] = {};
    has claimed: dict[str, bool] = {};
    has rows: list[list] = [];
    has nodes: dict[str, Group] = {};
    has depth: int = 0;

    can walk with Group entry {
        g = here.gid;
        if g in self.claimed {
            skip;
        }
        self.claimed[g] = True;
        self.rows.append([self.depth, g]);
        print("row ", self.depth, " ", g);
        nd = self.depth + 1;
        kids: list[str] = [];
        if g in self.group_subtasks {
            kids = self.group_subtasks[g];
        }
        for ch in kids {
            if ch in self.available and ch in self.nodes {
                cw = self.nodes[ch] spawn BuildWalker(
                    group_subtasks=self.group_subtasks,
                    available=self.available,
                    claimed=self.claimed,
                    rows=self.rows,
                    nodes=self.nodes,
                    depth=nd
                );
            }
        }
        disengage;
    }
}

def _sorted_keys(nodes: dict[str, Group]) -> list[str] {
    keys: list[str] = [];
    for k in nodes {
        keys.append(k);
    }
    return sorted(keys);
}

def _make_nodes(
    group_subtasks: dict[str, list[str]],
    available_keys: dict[str, bool],
) -> dict[str, Group] {
    nodes: dict[str, Group] = {};
    for k in available_keys {
        if k in group_subtasks {
            nd = Group(gid=k);
            nodes[k] = nd;
            root ++> nd;
        }
    }
    for p in group_subtasks {
        if p in nodes {
            subs: list[str] = group_subtasks[p];
            for ch in subs {
                if ch in available_keys and ch in nodes {
                    nodes[p] +>:Subtask:+> nodes[ch];
                }
            }
        }
    }
    return nodes;
}

def _validate_no_cycles(
    group_subtasks: dict[str, list[str]],
    available_keys: dict[str, bool],
) -> None {
    nodes = _make_nodes(group_subtasks, available_keys);
    completed: dict[str, bool] = {};
    ids = _sorted_keys(nodes);
    for i in ids {
        if i not in completed {
            w = nodes[i] spawn ValidateWalker(
                group_subtasks=group_subtasks,
                available=available_keys,
                active={},
                completed=completed,
                nodes=nodes,
                err=""
            );
            if w.err != "" {
                raise ValueError(w.err);
            }
        }
    }
}

def _find_root_groups(
    group_subtasks: dict[str, list[str]],
    nodes: dict[str, Group],
    available_keys: dict[str, bool],
) -> list[str] {
    is_child: dict[str, bool] = {};
    for p in group_subtasks {
        if p in nodes {
            subs: list[str] = group_subtasks[p];
            for ch in subs {
                if ch in available_keys and ch in nodes {
                    is_child[ch] = True;
                }
            }
        }
    }
    roots: list[str] = [];
    for g in nodes {
        if g not in is_child {
            roots.append(g);
        }
    }
    return sorted(roots);
}

def _build_hierarchy_info(
    group_subtasks: dict[str, list[str]],
    available_keys: dict[str, bool],
) -> list[list] {
    _validate_no_cycles(group_subtasks, available_keys);
    nodes = _make_nodes(group_subtasks, available_keys);
    root_ids = _find_root_groups(group_subtasks, nodes, available_keys);
    claimed: dict[str, bool] = {};
    rows: list[list] = [];
    for gid in root_ids {
        w = nodes[gid] spawn BuildWalker(
            group_subtasks=group_subtasks,
            available=available_keys,
            claimed=claimed,
            rows=rows,
            nodes=nodes,
            depth=0
        );
    }
    return rows;
}
