"""INTENTIUS/chant#2417 — derive execution order from the full graph; fan downstream."""

class UnknownDependencyError(Exception) {}
class DependencyCycleError(Exception) {}

node GraphRoot {}
node Component { has cid: str; has depends_on: list[str] = []; }
edge Depends {}

obj ComponentGraph {
  has anchor: GraphRoot;
  has by_id: dict[str, Component] = {};
}

def _keys_sorted(specs: dict[str, list[str]]) -> list[str] {
  keys: list[str] = [];
  for k in specs { keys.append(k); }
  keys = sorted(keys);
  return keys;
}

def build_graph(specs: dict[str, list[str]]) -> ComponentGraph {
  g = ComponentGraph();
  g.anchor = GraphRoot();
  root ++> g.anchor;
  ids = _keys_sorted(specs);
  for cid in ids {
    nd = Component(cid=cid);
    g.by_id[cid] = nd;
    g.anchor ++> nd;
  }
  for cid in ids {
    dep_ids: list[str] = specs[cid];
    nd = g.by_id[cid];
    deps_copy: list[str] = [];
    for d in dep_ids { deps_copy.append(d); }
    nd.depends_on = deps_copy;
    for dep_id in dep_ids {
      if dep_id not in g.by_id { raise UnknownDependencyError(); }
      dep_nd = g.by_id[dep_id];
      dep_nd +>:Depends:+> nd;
    }
  }
  _ = topological_waves(g);
  return g;
}

def topological_waves(g: ComponentGraph) -> list[list[str]] {
  ids: list[str] = [];
  for k in g.by_id { ids.append(k); }
  ids = sorted(ids);
  indeg: dict[str, int] = {};
  for cid in ids { indeg[cid] = 0; }
  for cid in ids {
    nd = g.by_id[cid];
    for dep_id in nd.depends_on { indeg[cid] = indeg[cid] + 1; }
  }
  waves: list[list[str]] = [];
  ready: list[str] = [];
  for cid in ids {
    if indeg[cid] == 0 { ready.append(cid); }
  }
  ready = sorted(ready);
  seen = 0;
  while len(ready) > 0 {
    layer: list[str] = ready;
    ready = [];
    waves.append(layer);
    seen = seen + len(layer);
    for cid in layer {
      src = g.by_id[cid];
      kids: list[Component] = [src <-:Depends:<-][?:Component];
      for ch in kids {
        kid_id = ch.cid;
        indeg[kid_id] = indeg[kid_id] - 1;
        if indeg[kid_id] == 0 { ready.append(kid_id); }
      }
    }
    ready = sorted(ready);
  }
  if seen < len(ids) { raise DependencyCycleError(); }
  return waves;
}

def topological_order(g: ComponentGraph) -> list[str] {
  flat: list[str] = [];
  layers = topological_waves(g);
  for layer in layers {
    for cid in layer { flat.append(cid); }
  }
  return flat;
}

def order_subset(g: ComponentGraph, selected: list[str]) -> list[str] {
  sel: dict[str, bool] = {};
  for s in selected { sel[s] = True; }
  out: list[str] = [];
  for cid in topological_order(g) {
    if cid in sel { out.append(cid); }
  }
  return out;
}

walker DownstreamWalker {
  has source_id: str;
  has claimed: dict[str, bool] = {};
  has hits: dict[str, bool] = {};
  can step with Component entry {
    if here.cid in self.claimed { skip; }
    self.claimed[here.cid] = True;
    print("downstream", here.cid);
    if here.cid != self.source_id { self.hits[here.cid] = True; }
    kids: list[Component] = [];
    for ch in [here <-:Depends:<-][?:Component] { kids.append(ch); }
    visit :0: kids else { disengage; }
  }
}

def collect_downstream(g: ComponentGraph, source_id: str) -> list[str] {
  if source_id not in g.by_id { return []; }
  src = g.by_id[source_id];
  w = src spawn DownstreamWalker(source_id=source_id, claimed={});
  mark = w.hits;
  out: list[str] = [];
  for cid in topological_order(g) {
    if cid in mark { out.append(cid); }
  }
  return out;
}
