"""KingPin/Garrul#119 — same-thread parent cycle re-root on import."""

node Comment {
    has cid: str;
    has thread_source_id: str;
}

edge Parent {}

def build_store(rows: list[dict]) -> dict[str, Comment] {
    store: dict[str, Comment] = {};
    for row in rows {
        cid = row["id"];
        th = row["thread"];
        nd = Comment(cid=cid, thread_source_id=th);
        store[cid] = nd;
        root ++> nd;
    }
    return store;
}

def build_effective_parent(comments: dict[str, Comment], raw_parent: dict[str, str]) -> dict[str, str] {
    eff: dict[str, str] = {};
    keys: list[str] = sorted(comments.keys());
    for cid in keys {
        c = comments[cid] as Comment;
        pid: str = "";
        if cid in raw_parent {
            pid = raw_parent[cid];
        }
        if pid == cid {
            pid = "";
        }
        if pid != "" {
            if pid not in comments {
                pid = "";
            } else {
                p = comments[pid] as Comment;
                if p.thread_source_id != c.thread_source_id {
                    pid = "";
                }
            }
        }
        eff[cid] = pid;
    }
    return eff;
}

def depth_of(cid: str, eff: dict[str, str], seen: list[str] | None = None) -> int {
    local_seen: list[str] = [];
    if seen is not None {
        for x in seen {
            local_seen.append(x);
        }
    }
    for x in local_seen {
        if x == cid {
            return 1;
        }
    }
    local_seen.append(cid);
    pid: str = "";
    if cid in eff {
        pid = eff[cid];
    }
    if pid == "" {
        return 0;
    }
    return 1 + depth_of(pid, eff, local_seen);
}

walker ChainProbe {
    has claimed: dict[str, bool] = {};
    has eff: dict[str, str] = {};
    has comments: dict[str, Comment] = {};
    has path: list[str] = [];
    has cycle_ids: list[str] = [];
    has hit_cycle: bool = False;

    can step with Comment entry {
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        print ["chain", here.cid];
        self.path.append(here.cid);
        pid: str = "";
        if here.cid in self.eff {
            pid = self.eff[here.cid];
        }
        if pid == "" {
            disengage;
        }
        on_path: bool = False;
        for x in self.path {
            if x == pid {
                on_path = True;
            }
        }
        if on_path {
            self.hit_cycle = True;
            for x in self.path {
                dup: bool = False;
                for y in self.cycle_ids {
                    if y == x {
                        dup = True;
                    }
                }
                if not dup {
                    self.cycle_ids.append(x);
                }
            }
            dup2: bool = False;
            for y in self.cycle_ids {
                if y == pid {
                    dup2 = True;
                }
            }
            if not dup2 {
                self.cycle_ids.append(pid);
            }
            disengage;
        }
        if pid not in self.comments {
            disengage;
        }
        nxt = self.comments[pid] as Comment;
        visit :0: [nxt];
    }
}

def find_cycle_members(comments: dict[str, Comment], eff: dict[str, str]) -> list[str] {
    merged: list[str] = [];
    keys: list[str] = sorted(comments.keys());
    for sid in keys {
        start = comments[sid] as Comment;
        w = start spawn ChainProbe(
            claimed={},
            eff=eff,
            comments=comments,
            path=[],
            cycle_ids=[],
            hit_cycle=False
        );
        if w.hit_cycle {
            for cid in w.cycle_ids {
                seen: bool = False;
                for m in merged {
                    if m == cid {
                        seen = True;
                    }
                }
                if not seen {
                    merged.append(cid);
                }
            }
        }
    }
    merged = sorted(merged);
    return merged;
}

def reroot_cycle_members(comments: dict[str, Comment], eff: dict[str, str]) -> dict {
    cyc = find_cycle_members(comments, eff);
    new_eff: dict[str, str] = {};
    for k in eff {
        new_eff[k] = eff[k];
    }
    for cid in cyc {
        new_eff[cid] = "";
    }
    out: dict = {};
    out["eff"] = new_eff;
    out["rerooted"] = sorted(cyc);
    return out;
}

def apply_parent_ids(comments: dict[str, Comment], eff: dict[str, str]) -> dict[str, str] {
    db: dict[str, str] = {};
    keys: list[str] = sorted(comments.keys());
    for cid in keys {
        pid: str = "";
        if cid in eff {
            pid = eff[cid];
        }
        db[cid] = pid;
    }
    return db;
}

walker DescentProbe {
    has claimed: dict[str, bool] = {};
    has order: list[str] = [];

    can descend with Comment entry {
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        print ["desc", here.cid];
        self.order.append(here.cid);
        kids: list[Comment] = [here <-:Parent:<-][?:Comment];
        batch: list[Comment] = [];
        for k in kids {
            batch.append(k);
        }
        if len(batch) > 0 {
            visit :0: batch;
        } else {
            disengage;
        }
    }
}

def walk_descent_order(comments: dict[str, Comment], eff: dict[str, str]) -> list[str] {
    # rebuild typed edges from eff outside any walk
    keys: list[str] = sorted(comments.keys());
    for cid in keys {
        c = comments[cid] as Comment;
        pid: str = "";
        if cid in eff {
            pid = eff[cid];
        }
        if pid != "" and pid in comments {
            p = comments[pid] as Comment;
            c +>:Parent:+> p;
        }
    }
    root_ids: list[str] = [];
    for cid in keys {
        pid: str = "";
        if cid in eff {
            pid = eff[cid];
        }
        if pid == "" {
            root_ids.append(cid);
        }
    }
    roots: list[Comment] = [];
    for rid in root_ids {
        roots.append(comments[rid] as Comment);
    }
    w = root spawn DescentProbe(claimed={}, order=[]);
    for r in roots {
        w = r spawn DescentProbe(claimed={}, order=[]);
    }
    return w.order;
}
