        out["marks"] = mk;
        out["steps"] = steps;
        return out;
    }
    new_ph = ph;
    if nxt == "clock" {
        new_ph = (ph + 1) % 3;
    }
    out["room_id"] = nxt;
    out["phase"] = new_ph;
    out["last_room_id"] = rid;
    out["marks"] = mk;
    out["steps"] = steps + 1;
    return out;
}

def reachable_exits(room_id: str, phase: int, last_room_id: any, marks: int) -> list[str] {
    dirs: list[str] = ["north", "south", "east", "west"];
    out: list[str] = [];
    for d in dirs {
        dest = transition(room_id, d, phase, last_room_id, marks);
        if dest != None {
            out.append(d);
        }
    }
    return sorted(out);
}

def attach_maze_graph -> Room {
    gate = Room(room_id="gate");
    well = Room(room_id="well");
    glass = Room(room_id="glass");
    clock = Room(room_id="clock");
    mirror = Room(room_id="mirror");
    archive = Room(room_id="archive");
    static = Room(room_id="static");
    fork = Room(room_id="fork");
    exit_room = Room(room_id="exit");
    root ++> gate;
    gate +>:Door:+> well;
    gate +>:Door:+> clock;
    gate +>:Door:+> static;
    well +>:Door:+> glass;
    glass +>:Door:+> fork;
    clock +>:Door:+> mirror;
    mirror +>:Door:+> archive;
    mirror +>:Door:+> static;
    archive +>:Door:+> fork;
    fork +>:Door:+> exit_room;
    return gate;
}

def shortest_path_to_exit(state: dict) -> any {
    rid = state["room_id"] as str;
    ph = state["phase"] as int;
    lr = state["last_room_id"];
    mk = state["marks"] as int;
    if rid == "exit" {
        return 0;
    }
    anchor = Room(room_id="search");
    root ++> anchor;
    start: dict = {};
    start["room_id"] = rid;
    start["phase"] = ph;
    start["last_room_id"] = lr;
    start["marks"] = mk;
    start["depth"] = 0;
    start["key"] = state_key(rid, ph, lr, mk);
    seeds: list[dict] = [start];
    wk = anchor spawn PathSearch(seeds=seeds);
    return wk.result;
}

