"""Konstantysz/vision-craft#11 - Cycle detection in node graph."""

node GraphNode {
    has cid: str;
}

edge GraphEdge {}

obj GraphHandle {
    has nodes_by_id: dict[str, GraphNode] = {};
    has graph_root: GraphNode;
}

def new_graph() -> GraphHandle {
    anchor = GraphNode(cid="__graph_root__");
    root ++> anchor;
    return GraphHandle(nodes_by_id={}, graph_root=anchor);
}

def add_node(handle: GraphHandle, node_id: str) -> bool {
    if node_id in handle.nodes_by_id {
        return False;
    }
    nd = GraphNode(cid=node_id);
    root ++> nd;
    handle.graph_root +>:GraphEdge:+> nd;
    handle.nodes_by_id[node_id] = nd;
    return True;
}

def add_edge(handle: GraphHandle, from_id: str, to_id: str) -> bool {
    if from_id not in handle.nodes_by_id {
        return False;
    }
    if to_id not in handle.nodes_by_id {
        return False;
    }
    src = handle.nodes_by_id[from_id];
    dst = handle.nodes_by_id[to_id];
    src +>:GraphEdge:+> dst;
    return True;
}

walker CycleWalker {
    has claimed: dict[str, bool] = {};
    has path_stack: list[str] = [];
    has cycle_path: list[str] = [];
    has finished: bool = False;

    can step with GraphNode entry {
        if self.finished {
            disengage;
        }
        if here.cid in self.claimed {
            idx = -1;
            for i in range(len(self.path_stack)) {
                if self.path_stack[i] == here.cid {
                    idx = i;
                }
            }
            if idx >= 0 {
                cyc: list[str] = [];
                for j in range(idx, len(self.path_stack)) {
                    cyc.append(self.path_stack[j]);
                }
                cyc.append(here.cid);
                self.cycle_path = cyc;
                self.finished = True;
                print {"cycle_detected": self.cycle_path};
            }
            skip;
        }
        if here.cid != "__graph_root__" {
            self.claimed[here.cid] = True;
            self.path_stack.append(here.cid);
        }
        kids: list[GraphNode] = [];
        for ch in [here ->:GraphEdge:->][?:GraphNode] {
            kids.append(ch);
        }
        ordered: list[GraphNode] = [];
        for ch in kids {
            ordered.insert(0, ch);
        }
        visit ordered else {
            disengage;
        }
        if here.cid != "__graph_root__" {
            new_claimed: dict[str, bool] = {};
            for pk in self.claimed {
                if pk != here.cid {
                    new_claimed[pk] = True;
                }
            }
            self.claimed = new_claimed;
            if len(self.path_stack) > 0 {
                top = self.path_stack[len(self.path_stack) - 1];
                if top == here.cid {
                    new_stack: list[str] = [];
                    for si in range(len(self.path_stack) - 1) {
                        new_stack.append(self.path_stack[si]);
                    }
                    self.path_stack = new_stack;
                }
            }
        }
    }
}

def detect_cycles(handle: GraphHandle) -> list[str] {
    w = handle.graph_root spawn CycleWalker(
        claimed={},
        path_stack=[],
        cycle_path=[],
        finished=False
    );
    print {"detect_cycles": w.cycle_path};
    return w.cycle_path;
