}

def add_vertex(g: Graph, vid: str) -> V {
    if vid in g.store {
        return g.store[vid];
    }
    nd = V(vid=vid);
    g.store[vid] = nd;
    g +>:Member:+> nd;
    return nd;
}

def add_edge(g: Graph, u: str, v: str) -> None {
    if u not in g.store { return; }
    if v not in g.store { return; }
    a = g.store[u];
    b = g.store[v];
    a +>:E:+> b;
    if not g.directed {
        b +>:E:+> a;
    }
}

def is_directed(g: Graph) -> bool {
    return g.directed;
}

def _find(parent: dict[str, str], x: str) -> str {
    px = parent[x];
    if px != x {
        parent[x] = _find(parent, px);
    }
    return parent[x];
}

def has_cycle_directed(g: Graph) -> bool {
    keys: list[str] = sorted(g.store.keys());
    for vid in keys {
        nd = g.store[vid];
        nd.dfs_color = 0;
    }
    for vid in keys {
        nd = g.store[vid];
        if nd.dfs_color == 0 {
            w = nd spawn DirectedCycleProbe(claimed={});
            if w.found {
                return True;
            }
        }
    }
    return False;
}

def has_cycle_undirected(g: Graph) -> bool {
    parent: dict[str, str] = {};
    keys: list[str] = sorted(g.store.keys());
    for vid in keys {
        parent[vid] = vid;
    }
    seen: dict[str, bool] = {};
    for u_vid in keys {
        u = g.store[u_vid];
        nbs: list[V] = [u ->:E:->][?:V];
        for v in nbs {
            v_vid = v.vid;
            if u_vid > v_vid { continue; }
            ek = u_vid + "|" + v_vid;
            if ek in seen { continue; }
            seen[ek] = True;
            pu = _find(parent, u_vid);
            pv = _find(parent, v_vid);
            if pu == pv { return True; }
            parent[pu] = pv;
        }
    }
    return False;
}

def has_cycle(g: Graph) -> bool {
    if g.directed {
        return has_cycle_directed(g);
    }
    return has_cycle_undirected(g);
}

