            a = vtx.vid;
            b = nxt.vid;
            if a > b {
                pair_key = b + ":" + a;
            } else {
                pair_key = a + ":" + b;
            }
            if pair_key in seen_pairs {
                continue;
            }
            seen_pairs[pair_key] = True;
            pu = _uf_find(parent, a);
            pv = _uf_find(parent, b);
            if pu == pv {
