"""Recursive-CTE traversal repository — andrelair-platform/retrieva#547."""

node RepoRoot {}

node Provider {
    has pid: str;
}

node Arrangement {
    has aid: str;
    has fid: str;
}

edge Catalog {}

edge Subcontracts {}

edge Hosts {}

walker ChainWalker {
    has claimed: dict[str, bool] = {};
    has depth: int = 0;
    has maxDepth: int = 64;
    has collected: list[str] = [];

    can follow with Provider entry {
        if here.pid in self.claimed {
            skip;
        }
        self.claimed[here.pid] = True;
        if self.depth > 0 {
            self.collected.append(here.pid);
        }
        self.depth = self.depth + 1;
        if self.depth >= self.maxDepth {
            disengage;
        }
        kids: list[Provider] = [];
        for ch in [here ->:Subcontracts:->][?:Provider] {
            kids.append(ch);
        }
        if len(kids) > 0 {
            visit :0: kids;
        } else {
            disengage;
        }
        print(self.collected);
    }
}

def findProvider(repo: RepoRoot, providerId: str) -> Provider | None {
    for p in [repo ->:Catalog:->][?:Provider] {
        if p.pid == providerId {
            return p;
        }
    }
    return None;
}

def providerSubcontractorChain(repo: RepoRoot, providerId: str) -> list[str] {
    start: Provider | None = findProvider(repo, providerId);
    if start is None {
        return [];
    }
    w = start spawn ChainWalker(claimed={}, depth=0, maxDepth=64, collected=[]);
    return sorted(w.collected);
}

def arrangementsReachingFunction(repo: RepoRoot, functionId: str) -> list[str] {
    seedHosts: list[str] = [];
    for arr in [repo ->:Catalog:->][?:Arrangement] {
        if arr.fid == functionId {
            for h in [arr ->:Hosts:->][?:Provider] {
                seedHosts.append(h.pid);
            }
        }
    }
    if len(seedHosts) == 0 {
        return [];
    }
    expanded: dict[str, bool] = {};
    for hp in seedHosts {
        expanded[hp] = True;
        chain = providerSubcontractorChain(repo, hp);
        for sp in chain {
            expanded[sp] = True;
        }
    }
    aids: list[str] = [];
    aidSeen: dict[str, bool] = {};
    for arr in [repo ->:Catalog:->][?:Arrangement] {
        for h in [arr ->:Hosts:->][?:Provider] {
            reachable = False;
            if h.pid in expanded {
                reachable = True;
            }
            if reachable {
                dup = False;
                if arr.aid in aidSeen {
                    dup = True;
                }
                if not dup {
                    aidSeen[arr.aid] = True;
                    aids.append(arr.aid);
                }
            }
        }
    }
    return sorted(aids);
}
