def add_document(coll: SelfRelCollection, doc_id: str, parent_id: str | None = None) -> Doc | None {
    if doc_id in coll.by_id {
        return coll.by_id[doc_id];
    }
    doc = Doc(cid=doc_id);
    coll.by_id[doc_id] = doc;
    if parent_id is None {
        coll ++> doc;
        return doc;
    }
    if parent_id not in coll.by_id {
        coll ++> doc;
        return doc;
    }
    parent = coll.by_id[parent_id];
    parent +>:ParentOf:+> doc;
    return doc;
}

def children_of(coll: SelfRelCollection, doc_id: str) -> list[str] {
    if doc_id not in coll.by_id {
        return [];
    }
    parent = coll.by_id[doc_id];
    out: list[str] = [];
    for ch in [parent ->:ParentOf:->][?:Doc] {
        out.append(ch.cid);
    }
    return sorted(out);
}

def ancestors_of(coll: SelfRelCollection, doc_id: str) -> list[str] {
    if doc_id not in coll.by_id {
        return [];
    }
    start = coll.by_id[doc_id];
    w = start spawn AncestorWalker(target_cid=doc_id);
    return sorted(w.found);
}

def descendants_of(coll: SelfRelCollection, doc_id: str) -> list[str] {
    if doc_id not in coll.by_id {
        return [];
    }
    start = coll.by_id[doc_id];
    w = start spawn DescendWalker(target_cid=doc_id);
    return sorted(w.found);
}

def link_would_cycle(coll: SelfRelCollection, child_id: str, parent_id: str) -> bool {
    if child_id not in coll.by_id or parent_id not in coll.by_id {
        return False;
    }
    if child_id == parent_id {
        return True;
    }
    start = coll.by_id[child_id];
    w = start spawn ReachWalker(goal=parent_id);
    return w.hit;
}

