"""OSP lift: aaronwesthoff84/SAP-IM-Config-Explorer#119 — compensation rule simulator."""

node RuleNode {
    has cid: str;
    has stage: str;
    has expr: str;
}

edge Depends {}

walker Collect {
    has claimed: dict[str, bool] = {};
    has found: list[RuleNode] = [];

    can gather with RuleNode entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        self.found.append(here);
        print("gather", here.cid);
        kids: list[RuleNode] = [here ->:Depends:->][?:RuleNode];
        visit :0: kids else { disengage; }
    }
}

walker CycleProbe {
    has on_path: dict[str, bool] = {};
    has found_cycle: bool = False;

    can probe with RuleNode entry {
        if here.cid in self.on_path {
            self.found_cycle = True;
            skip;
        }
        self.on_path[here.cid] = True;
        print("probe", here.cid);
        kids: list[RuleNode] = [here ->:Depends:->][?:RuleNode];
        visit kids else { disengage; }
        self.on_path[here.cid] = False;
    }
}

walker SimRun {
    has graph_root: RuleNode;
    has event_amt: float = 0.0;
    has max_steps: int = 1000;
    has trace_out: list[dict] = [];

    can run with entry {
        c = self.graph_root spawn Collect(claimed={});
        print("sim_run", len(c.found));
        self.trace_out = build_trace(c.found, self.event_amt, self.max_steps);
    }
}

def stage_rank_map() -> dict[str, int] {
    ranks: dict[str, int] = {};
    ranks["credit"] = 0;
    ranks["primary"] = 1;
    ranks["secondary"] = 2;
    ranks["incentive"] = 3;
    ranks["deposit"] = 4;
    return ranks;
}

def sort_by_stage(nodes: list[RuleNode], ranks: dict[str, int]) -> list[RuleNode] {
    out: list[RuleNode] = [];
    used: dict[str, bool] = {};
    k = 0;
    while k < len(nodes) {
        best_i = -1;
        best_rk = 1000;
        i = 0;
        while i < len(nodes) {
            if nodes[i].cid not in used {
                rk = ranks[nodes[i].stage] if nodes[i].stage in ranks else 99;
                if rk < best_rk {
                    best_rk = rk;
                    best_i = i;
                }
            }
            i += 1;
        }
        if best_i >= 0 {
            used[nodes[best_i].cid] = True;
            out.append(nodes[best_i]);
        }
        k += 1;
    }
    return out;
}

def eval_rule(nd: RuleNode, event_amt: float, store: dict[str, float]) -> float {
    if nd.stage == "credit" {
        return event_amt;
    }
    deps: list[RuleNode] = [nd ->:Depends:->][?:RuleNode];
    total = 0.0;
    i = 0;
    while i < len(deps) {
        dep = deps[i];
        if dep.cid in store {
            total += store[dep.cid];
        }
        i += 1;
    }
    if nd.stage == "incentive" {
        return total * 0.1;
    }
    return total;
}

def build_trace(nodes: list[RuleNode], event_amt: float, max_steps: int) -> list[dict] {
    ranks = stage_rank_map();
    ordered = sort_by_stage(nodes, ranks);
    store: dict[str, float] = {};
    steps: list[dict] = [];
    i = 0;
    while i < len(ordered) {
        if len(steps) >= max_steps { break; }
        nd = ordered[i];
        inputs: dict[str, float] = {};
        deps: list[RuleNode] = [nd ->:Depends:->][?:RuleNode];
        j = 0;
        while j < len(deps) {
            dep = deps[j];
            if dep.cid in store {
                inputs[dep.cid] = store[dep.cid];
            }
            j += 1;
        }
        out_val = eval_rule(nd, event_amt, store);
        store[nd.cid] = out_val;
        step: dict = {};
        step["node_id"] = nd.cid;
        step["stage"] = nd.stage;
        step["expr"] = nd.expr;
        step["inputs"] = inputs;
        step["output"] = out_val;
        steps.append(step);
        i += 1;
    }
    return steps;
}

def build_simulator(rules: list[dict]) -> RuleNode {
    by_id: dict[str, RuleNode] = {};
    i = 0;
    while i < len(rules) {
        spec = rules[i];
        cid = spec["id"] as str;
        st = spec["stage"] as str;
        ex = spec["expr"] as str;
        nd = RuleNode(cid=cid, stage=st, expr=ex);
        by_id[cid] = nd;
        i += 1;
    }
    j = 0;
    while j < len(rules) {
        spec = rules[j];
        cid = spec["id"] as str;
        src = by_id[cid];
        deps_raw = spec["deps"] if "deps" in spec else [];
        deps_list = deps_raw as list;
        k = 0;
        while k < len(deps_list) {
            dep_id = deps_list[k] as str;
            if dep_id in by_id {
                dep_nd = by_id[dep_id];
                src +>:Depends:+> dep_nd;
            }
            k += 1;
        }
        j += 1;
    }
    head_id = rules[0]["id"] as str;
    head = by_id[head_id];
    root ++> head;
    return head;
}

def run_simulation(graph_root: RuleNode, event: dict, max_steps: int = 1000) -> list[dict] {
    amt = 0.0;
    if "amount" in event {
        amt = event["amount"] as float;
    }
    w = graph_root spawn SimRun(graph_root=graph_root, event_amt=amt, max_steps=max_steps);
    return w.trace_out;
}

def detect_cycle(graph_root: RuleNode) -> bool {
    p = graph_root spawn CycleProbe(on_path={});
    return p.found_cycle;
}

def stage_names() -> list[str] {
    names: list[str] = [];
    names.append("credit");
    names.append("primary");
    names.append("secondary");
    names.append("incentive");
    names.append("deposit");
    return names;
}
