def set_parent(
    store: SelfRefStore,
    coll_id: str,
    doc_id: str,
    parent_id: str | None
) -> bool {
    d = _doc(store, coll_id, doc_id);
    if d is None {
        return False;
    }
    if parent_id is not None {
        if _doc(store, coll_id, parent_id) is None {
            return False;
        }
        if parent_id == doc_id {
            return False;
        }
        if would_cycle(store, coll_id, doc_id, parent_id) {
            return False;
        }
    }
    old_pars: list[Document] = [d <-:Parent:<-][?:Document];
    for op in old_pars {
        op del=:Parent:=> d;
    }
    if parent_id is not None {
        p = store.documents[parent_id];
        p +>:Parent:+> d;
    }
    return True;
}

def would_cycle(
    store: SelfRefStore,
    coll_id: str,
    doc_id: str,
    parent_id: str
) -> bool {
