                    kids.append(ch);
                }
            }
        }
        if kids {
            visit :0: kids;
        } else {
            disengage;
        }
        print(f"closure {here.name}");
    }
}

walker InferSteps {
    has max_iters: int;
    has steps: int = 0;
    has cycle: bool = False;
    has claimed: dict[str, bool] = {};
    has order: list[str] = [];

    can step with TypeDef entry {
        if here.name in self.claimed {
            self.cycle = True;
            skip;
        }
        if self.steps >= self.max_iters {
            self.cycle = True;
            skip;
        }
        self.claimed[here.name] = True;
        self.steps += 1;
        self.order.append(here.name);
        kids: list[TypeDef] = [];
        for ref_name in here.refs {
            for ch in [here ->:Depends:->][?:TypeDef] {
                if ch.name == ref_name {
                    kids.append(ch);
                }
            }
        }
        if kids {
            visit :0: kids;
        } else {
            disengage;
        }
        print(f"infer {here.name} step={self.steps}");
    }
}

def wire_deps(g: TypeGraph, nd: TypeDef) -> None {
    for ref_name in nd.refs {
        if ref_name in g.index {
            ref_nd = g.index[ref_name];
            nd +>:Depends:+> ref_nd;
        }
    }
}

def rewire_incoming(g: TypeGraph, nd: TypeDef) -> None {
    for other_name in g.index {
        if other_name == nd.name {
            continue;
        }
        other = g.index[other_name];
        for ref_name in other.refs {
            if ref_name == nd.name {
                other +>:Depends:+> nd;
            }
        }
    }
}

def make_graph() -> TypeGraph {
    g = TypeGraph();
    root ++> g;
    return g;
}

def register_type(g: TypeGraph, name: str, kind: str, refs: list[str]) -> None {
    nd = TypeDef(name=name, kind=kind, refs=refs);
    g ++> nd;
    g.index[name] = nd;
    wire_deps(g, nd);
    rewire_incoming(g, nd);
}

def find_type(g: TypeGraph, name: str) -> TypeDef | None {
    if name in g.index {
        return g.index[name];
    }
    return None;
}

def infer(g: TypeGraph, name: str, max_iters: int = 64) -> dict {
    start = find_type(g, name);
    if not start {
        empty_refs: list[str] = [];
        return {
            "name": name,
            "kind": "",
            "refs": empty_refs,
            "cycle": False,
            "iterations": 0,
            "unknown": True,
        };
    }
    w = start spawn InferSteps(max_iters=max_iters);
    refs_copy: list[str] = [];
    for r in start.refs {
        refs_copy.append(r);
    }
    return {
        "name": start.name,
        "kind": start.kind,
        "refs": refs_copy,
        "cycle": w.cycle,
        "iterations": w.steps,
        "unknown": False,
    };
}

def infer_closure(g: TypeGraph, name: str) -> list[str] {
    start = find_type(g, name);
    if not start {
        empty: list[str] = [];
        return empty;
    }
    w = start spawn CollectClosure();
    return sorted(w.found);
}
