def remove_prerequisite(store: PrerequisiteStore, item_id: str, prerequisite_id: str) -> bool {
    if item_id not in store.by_id or prerequisite_id not in store.by_id {
        return False;
    }
    item = store.by_id[item_id];
    prereq = store.by_id[prerequisite_id];
    linked = False;
    for p in [item ->:Prerequisite:->][?:Item] {
        if p.item_id == prerequisite_id {
            linked = True;
        }
    }
    if not linked {
        return False;
    }
    item -:Prerequisite:-> prereq;
    return True;
}

def get_prerequisites(store: PrerequisiteStore, item_id: str) -> list[str] {
    if item_id not in store.by_id {
        return [];
    }
    item = store.by_id[item_id];
    out: list[str] = [];
    for p in [item ->:Prerequisite:->][?:Item] {
        out.append(p.item_id);
    }
    return sorted(out);
}
