    for tid in store {
        ids.append(tid);
        indeg[tid] = 0;
    }
    for tid in store {
        nd = store[tid] as Task;
        for dep in [nd ->:Depends:->][?:Task] {
            indeg[nd.tid] = indeg[nd.tid] + 1;
        }
    }
    ready: list[str] = [];
    for tid in ids {
        if indeg[tid] == 0 {
            ready.append(tid);
        }
    }
    ready = sorted(ready);
    order: list[str] = [];
    while len(ready) > 0 {
        cur = ready[0];
        next_ready: list[str] = [];
        ri = 1;
        while ri < len(ready) {
            next_ready.append(ready[ri]);
            ri += 1;
