def _copy_deps(src: dict[str, list[str]]) -> dict[str, list[str]] {
    out: dict[str, list[str]] = {};
    for tid in sorted(src) {
        deps: list[str] = [];
        for dep in src[tid] {
            deps.append(dep);
        }
        out[tid] = deps;
    }
    return out;
}

def _merge_first_wins(tasks: list[dict]) -> dict[str, list[str]] {
    nodes: dict[str, list[str]] = {};
    for row in tasks {
        tid = row["id"] as str;
        if tid in nodes {
            continue;
        }
        deps: list[str] = row["dependsOn"] as list[str];
        nodes[tid] = deps;
    }
    return nodes;
}

def _merge_last_wins_edges(tasks: list[dict]) -> tuple[dict[str, list[str]], dict[str, list[str]]] {
    nodes: dict[str, list[str]] = {};
    edges: dict[str, list[str]] = {};
    for row in tasks {
        tid = row["id"] as str;
        deps: list[str] = row["dependsOn"] as list[str];
        if tid not in nodes {
            nodes[tid] = deps;
        }
        edges[tid] = deps;
    }
    return (nodes, edges);
}

def _deps_known(nodes: dict[str, list[str]]) -> bool {
    for tid in sorted(nodes) {
        for dep in nodes[tid] {
            if dep not in nodes {
                return False;
            }
        }
    }
    return True;
}

def _materialize(nodes: dict[str, list[str]]) -> tuple[GraphRoot, dict[str, TaskN]] {
    gr = GraphRoot(label="subgraph");
    root ++> gr;
    by_id: dict[str, TaskN] = {};
    for tid in sorted(nodes) {
        tn = TaskN(tid=tid, depends=nodes[tid]);
        by_id[tid] = tn;
        root ++> tn;
    }
    for tid in sorted(nodes) {
        dst = by_id[tid];
        for dep in nodes[tid] {
            src = by_id[dep];
            src +>:DepE:+> dst;
        }
    }
    indeg: dict[str, int] = {};
    for tid in sorted(nodes) {
        indeg[tid] = 0;
    }
    for tid in sorted(nodes) {
        for dep in nodes[tid] {
            indeg[tid] = indeg[tid] + 1;
        }
    }
    for tid in sorted(nodes) {
        if indeg[tid] == 0 {
            gr +>:RootsE:+> by_id[tid];
        }
    }
    return (gr, by_id);
}

def _detect_cycle(gr: GraphRoot) -> bool {
    w = gr spawn CycleProbe(claimed={}, on_stack={}, cyclic=False, visit_count=0);
    return w.cyclic;
}

def _collect_topo(gr: GraphRoot) -> list[str] {
    w = gr spawn TopoCollect(claimed={}, order=[]);
    return w.order;
}

def create_with_raw_edges(
    nodes: dict[str, list[str]],
    edges: dict[str, list[str]],
) -> PlanHandle {
    h = PlanHandle(
        node_deps=_copy_deps(nodes),
        edge_deps=_copy_deps(edges),
        order=sorted(nodes),
        validated=False,
    );
    return h;
}

def from_tasks(tasks: list[dict]) -> PlanHandle {
    merged = _merge_first_wins(tasks);
    if not _deps_known(merged) {
        raise UnknownDependencyError(message="unknown dependency");
    }
    pair = _materialize(merged);
    gr = pair[0];
    if _detect_cycle(gr) {
        raise CyclicDependencyError(message="cycle detected");
    }
    order = _collect_topo(gr);
    h = PlanHandle(
        node_deps=_copy_deps(merged),
        edge_deps=_copy_deps(merged),
        order=order,
        validated=True,
    );
    return h;
}

def build_subgraph_buggy(tasks: list[dict]) -> PlanHandle {
    _validated = from_tasks(tasks);
    _ = _validated;
    pair = _merge_last_wins_edges(tasks);
    nodes: dict[str, list[str]] = pair[0];
    edges: dict[str, list[str]] = pair[1];
    return create_with_raw_edges(nodes, edges);
}

def build_subgraph_fixed(tasks: list[dict]) -> PlanHandle {
    return from_tasks(tasks);
}

def topo_order(h: PlanHandle) -> list[str] {
    if h.validated {
        return h.order;
    }
    merged = _copy_deps(h.edge_deps);
    pair = _materialize(merged);
    gr = pair[0];
    return _collect_topo(gr);
}

def node_depends(h: PlanHandle, tid: str) -> list[str] {
    if tid not in h.node_deps {
        return [];
    }
    deps: list[str] = [];
    for dep in h.node_deps[tid] {
        deps.append(dep);
    }
    return sorted(deps);
}

def edge_deps(h: PlanHandle, tid: str) -> list[str] {
    if tid not in h.edge_deps {
        return [];
    }
    deps: list[str] = [];
    for dep in h.edge_deps[tid] {
        deps.append(dep);
    }
    return sorted(deps);
}

def edges_aligned(h: PlanHandle) -> bool {
    keys: list[str] = sorted(h.node_deps);
    for tid in keys {
        if sorted(h.node_deps[tid]) != sorted(h.edge_deps[tid]) {
            return False;
        }
    }
    return True;
}

def diagnose_from_tasks(tasks: list[dict]) -> str {
    try {
        from_tasks(tasks);
        return "";
    } except CyclicDependencyError {
        return "cyclic";
    } except UnknownDependencyError {
        return "unknown";
    }
}

