def _spawn_topo(root_node: PlanNode) -> TopoProbe {
    w: TopoProbe = root_node spawn TopoProbe(claimed={});
    return w;
}

def _spawn_cycle(root_node: PlanNode) -> CycleProbe {
    w: CycleProbe = root_node spawn CycleProbe(claimed={});
    return w;
}

def _tasks_to_maps(tasks: list[dict]) -> dict[str, any] {
    nodes: dict[str, list[str]] = {};
    edges: dict[str, list[str]] = {};
    out: dict[str, any] = {};
    for row in tasks {
        tid: str = row["id"] as str;
        deps: list[str] = row["dependsOn"] as list[str];
        if tid not in nodes {
            nodes[tid] = deps;
        }
        edges[tid] = deps;
    }
    out["nodes"] = nodes;
    out["edges"] = edges;
    return out;
}

def _build_graph(maps: dict[str, any]) -> PlanNode {
    nodes: dict[str, list[str]] = maps["nodes"] as dict[str, list[str]];
    edges: dict[str, list[str]] = maps["edges"] as dict[str, list[str]];
    store: dict[str, PlanNode] = {};
    root_node: PlanNode = PlanNode(nid="__root__", deps=[]);
    root ++> root_node;
    for nid in sorted(nodes.keys()) {
        nd: PlanNode = PlanNode(nid=nid, deps=nodes[nid]);
        store[nid] = nd;
        root_node +>:Dep:+> nd;
    }
    for src in sorted(edges.keys()) {
        src_nd: PlanNode = store[src] as PlanNode;
        for dst in edges[src] {
            if dst in store {
                dst_nd: PlanNode = store[dst] as PlanNode;
                src_nd +>:Dep:+> dst_nd;
            }
        }
    }
    return root_node;
}

def _kahn_order(root_node: PlanNode) -> list[str] {
    w: TopoProbe = _spawn_topo(root_node);
    indeg: dict[str, int] = w.indeg;
    adj: dict[str, list[str]] = w.adj;
    q: list[str] = [];
    for nid in sorted(indeg.keys()) {
        if indeg[nid] == 0 {
            q.append(nid);
        }
    }
    order: list[str] = [];
    while len(q) > 0 {
        cur: str = q[0];
        q = q[1:];
        order.append(cur);
        for nxt in sorted(adj[cur]) {
            indeg[nxt] -= 1;
            if indeg[nxt] == 0 {
                q.append(nxt);
            }
        }
    }
    return order;
}

def from_tasks(tasks: list[dict], reason: str | None = None) -> dict[str, any] {
    maps: dict[str, any] = _tasks_to_maps(tasks);
    nodes: dict[str, list[str]] = maps["nodes"] as dict[str, list[str]];
    edges: dict[str, list[str]] = maps["edges"] as dict[str, list[str]];
    root_node: PlanNode = _build_graph(maps);
    w: CycleProbe = _spawn_cycle(root_node);
    if w.cyclic {
        raise Exception("CyclicDependencyError");
    }
    for src in edges.keys() {
        for dst in edges[src] {
            if dst not in nodes {
                raise Exception("UnknownNodeError");
            }
        }
    }
    order: list[str] = _kahn_order(root_node);
    if len(order) != len(nodes) {
        raise Exception("CyclicDependencyError");
    }
    out: dict[str, any] = {};
    out["nodes"] = nodes;
    out["edges"] = edges;
    out["order"] = order;
    out["reason"] = reason;
    out["validated"] = True;
    return out;
}

def create_with_raw_edges(
    nodes: dict[str, list[str]],
    edges: dict[str, list[str]],
    depth: int,
    reason: str,
) -> dict[str, any] {
    out: dict[str, any] = {};
    out["nodes"] = nodes;
    out["edges"] = edges;
    out["depth"] = depth;
    out["reason"] = reason;
    out["validated"] = False;
    return out;
}

def build_subgraph(tasks: list[dict], fixed: bool) -> dict[str, any] {
    maps: dict[str, any] = _tasks_to_maps(tasks);
    nodes: dict[str, list[str]] = maps["nodes"] as dict[str, list[str]];
    edges: dict[str, list[str]] = maps["edges"] as dict[str, list[str]];
    if fixed {
        return from_tasks(tasks, reason="recursive expansion");
    }
    from_tasks(tasks, reason="recursive expansion");
    return create_with_raw_edges(nodes, edges, 0, "recursive expansion");
}

def edge_node_mismatch(nodes: dict[str, list[str]], edges: dict[str, list[str]]) -> bool {
    for tid in nodes.keys() {
        if tid in edges {
            if nodes[tid] != edges[tid] {
                return True;
            }
        }
    }
    return False;
}

def topo_sort(graph: dict[str, any]) -> list[str] {
    nodes: dict[str, list[str]] = graph["nodes"] as dict[str, list[str]];
    edges: dict[str, list[str]] = graph["edges"] as dict[str, list[str]];
    maps: dict[str, any] = {};
    maps["nodes"] = nodes;
    maps["edges"] = edges;
    root_node: PlanNode = _build_graph(maps);
    order: list[str] = _kahn_order(root_node);
    return order;
}

