"""Static analysis helpers for recursive CTE reference graphs (dbt-labs/dbt-core#13514)."""

node Cte {
    has cid: str;
}

edge Ref {}

node CteGraph {
    has store: dict[str, Cte] = {};
}

def normalize_graph(raw: dict) -> dict[str, list[str]] {
    out: dict[str, list[str]] = {};
    keys: list[str] = sorted(raw);
    for k in keys {
        raw_refs = raw[k] as list[str];
        normed: list[str] = [];
        seen: dict[str, bool] = {};
        for r in raw_refs {
            rs = r as str;
            if rs not in seen {
                seen[rs] = True;
                normed.append(rs);
            }
        }
        sorted(normed);
        out[k] = normed;
    }
    return out;
}

def make_cte_graph(entries: dict[str, list[str]]) -> CteGraph {
    g = CteGraph(store={});
    root ++> g;
    norm = normalize_graph(entries);
    store: dict[str, Cte] = {};
    names: list[str] = sorted(norm);
    for name in names {
        nd = Cte(cid=name);
        store[name] = nd;
        g +>:Ref:+> nd;
    }
    for name in names {
        src = store[name] as Cte;
        ref_names = norm[name];
        for rn in ref_names {
            if rn in store {
                dst = store[rn] as Cte;
                src +>:Ref:+> dst;
            }
        }
    }
    g.store = store;
    return g;
}

walker ReachWalker {
    has claimed: dict[str, bool] = {};
    has found: list[str] = [];
    has seen_found: dict[str, bool] = {};

    can step with Cte entry {
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        if here.cid not in self.seen_found {
            self.seen_found[here.cid] = True;
            self.found.append(here.cid);
        }
        print("reach", here.cid);
        nxt: list[Cte] = [here ->:Ref:->][?:Cte];
        if nxt {
            visit :0: nxt;
        } else {
            disengage;
        }
    }
}

def recursive_reach(g: CteGraph, start: str) -> list[str] {
    st = g.store as dict[str, Cte];
    if start not in st {
        return [];
    }
    start_nd = st[start] as Cte;
    w = start_nd spawn ReachWalker();
    res: list[str] = w.found;
    sorted(res);
    return res;
}

def partition_recursive_refs(anchor: list[str], body: list[str]) -> dict[str, list[str]] {
    anchor_set: dict[str, bool] = {};
    anchor_out: list[str] = [];
    for a in anchor {
        if a not in anchor_set {
            anchor_set[a] = True;
            anchor_out.append(a);
        }
    }
    sorted(anchor_out);
    recursive_only: list[str] = [];
    rec_seen: dict[str, bool] = {};
    for b in body {
        if b not in anchor_set and b not in rec_seen {
            rec_seen[b] = True;
            recursive_only.append(b);
        }
    }
    sorted(recursive_only);
    return {"anchor": anchor_out, "recursive_only": recursive_only};
}

def unknown_refs(refs: list[str], known: list[str]) -> list[str] {
    known_set: dict[str, bool] = {};
    for k in known {
        known_set[k] = True;
    }
    out: list[str] = [];
    seen: dict[str, bool] = {};
    for r in refs {
        if r not in known_set and r not in seen {
            seen[r] = True;
            out.append(r);
        }
    }
    sorted(out);
    return out;
}
