"""Synthetic OSP lift for tdupu/gascity#52 — two-phase workflow-root descendant counts."""

node Wisp {
    has id: str;
    has kind: str = "";
    has formula_contract: str = "";
    has root_bead_id: str = "";
    has active: bool = True;
}

edge Descends {}

node GraphAnchor {
    has tag: str = "anchor";
