```jac
"""devstein/langchain#23 — PythonREPL split globals/locals breaks recursion."""

node Ns {
    has nsid: str;
    has name: str = "";
    has bound: bool = False;
}

node Call {
    has cid: str;
    has n: int;
    has out: int = -1;
    with entry {
        root spawn CallEval(claimed={}, memo={}, target=-1, result=-1);
    }
}

edge ScopeLink {}
edge Arg {}

walker ScopeLookup {
    has claimed: dict[str, bool] = {};
    has want: str = "";
    has found: bool = False;
    has scope_id: str = "";

    can step with Ns entry {
        if here.nsid in self.claimed {
            skip;
        }
        self.claimed[here.nsid] = True;
        if here.bound and here.name == self.want {
            self.found = True;
            self.scope_id = here.nsid;
            print("bind ", here.name, " @ ", here.nsid);
            disengage;
        }
        nxt: list[Ns] = [here ->:ScopeLink:->][?:Ns];
        if len(nxt) > 0 {
            visit :0: nxt;
        } else {
            disengage;
        }
    }
}

walker CallEval {
    has claimed: dict[str, bool] = {};
    has memo: dict[str, int] = {};
    has target: int = -1;
    has result: int = -1;

    can eval with Call entry {
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        key: str = str(here.n);
        if key in self.memo {
            here.out = self.memo[key];
            print("memo ", here.n, " -> ", here.out);
        } elif here.n <= 1 {
            here.out = here.n;
            self.memo[key] = here.out;
            print("base ", here.n);
        } else {
            a: Call = Call(cid=here.cid + ":a", n=here.n - 1);
            b: Call = Call(cid=here.cid + ":b", n=here.n - 2);
            here +>:Arg:+> a;
            here +>:Arg:+> b;
            visit :0: [a, b];
            left: int = a.out;
            right: int = b.out;
            here.out = left + right;
            self.memo[key] = here.out;
            print("fold ", here.n, " -> ", here.out);
        }
        if here.n == self.target {
            self.result = here.out;
        }
    }
}

def make_repl(split_scopes: bool) -> dict {
    g: Ns = Ns(nsid="g0", name="fibonacci", bound=True);
    l: Ns = Ns(nsid="l0", name="", bound=False);
    root ++> g;
    root ++> l;
    g +>:ScopeLink:+> l;
    repl: dict = {"split": split_scopes, "globals": "g0", "locals": "l0"};
    return repl;
}

def lookup_name(repl: dict, fn_name: str) -> dict {
    start_id: str = repl["locals"] as str;
    if not (repl["split"] as bool) {
        start_id = repl["globals"] as str;
    }
    start: Ns = Ns(nsid=start_id);
    root ++> start;
    w: ScopeLookup = start spawn ScopeLookup(claimed={}, want=fn_name);
    out: dict = {"found": w.found, "scope": w.scope_id};
    return out;
}

def fibonacci_cte(n: int) -> int {
    memo: dict[str, int] = {};
    return fibonacci_cte_memo(n, memo);
}

def fibonacci_cte_memo(n: int, memo: dict[str, int]) -> int {
    key: str = str(n);
    if key in memo {
        return memo[key];
    }
    if n <= 1 {
        memo[key] = n;
        return n;
    }
    a: int = fibonacci_cte_memo(n - 1, memo);
    b: int = fibonacci_cte_memo(n - 2, memo);
    v: int = a + b;
    memo[key] = v;
    return v;
}

def call_graph_pairs(n: int) -> list[list[str]] {
    pairs: list[list[str]] = [];
    if n <= 1 {
        return pairs;
    }
    root_cid: str = "c" + str(n);
    left: list[list[str]] = call_graph_pairs(n - 1);
    right: list[list[str]] = call_graph_pairs(n - 2);
    for p in left {
        pairs.append(p);
    }
    for p in right {
        pairs.append(p);
    }
    pairs.append([root_cid, "c" + str(n - 1)]);
    pairs.append([root_cid, "c" + str(n - 2)]);
    return pairs;
}

def eval_fib_graph(n: int) -> int {
    root_c: Call = Call(cid="c" + str(n), n=n);
    root ++> root_c;
    w: CallEval = root_c spawn CallEval(claimed={}, memo={}, target=n, result=-1);
    return w.result;
}

def run_recursive_repl(repl: dict, n: int) -> dict {
    hit: dict = lookup_name(repl, "fibonacci");
    if not (hit["found"] as bool) {
        err: dict = {"ok": False, "value": -1, "error": "NameError: fibonacci is not defined"};
        return err;
    }
    val: int = fibonacci_cte(n);
    ok: dict = {"ok": True, "value": val, "error": ""};
    return ok;
}
