    has formula_contract: str = "";
    has root_bead_id: str = "";
    has active: bool = False;
}

edge Descends {}

def is_workflow_root(
    kind: str,
    formula_contract: str,
    root_bead_id: str,
    wisp_id: str,
    active: bool,
) -> bool {
    if active {
        return False;
    }
    if kind != "workflow" {
        return False;
    }
    if formula_contract != "issue" {
        return False;
    }
    if root_bead_id != wisp_id {
        return False;
    }
    return True;
}

def wisp_from_record(rec: dict) -> Wisp {
    wid = rec["id"] as str;
    kind_val: str = "";
    fc_val: str = "";
    rb_val: str = "";
    active_val: bool = False;
    if "kind" in rec {
        kind_val = rec["kind"] as str;
    }
    if "formula_contract" in rec {
        fc_val = rec["formula_contract"] as str;
    }
    if "root_bead_id" in rec {
        rb_val = rec["root_bead_id"] as str;
    }
    if "active" in rec {
        active_val = rec["active"] as bool;
    }
    w = Wisp(
        id=wid,
        kind=kind_val,
        formula_contract=fc_val,
        root_bead_id=rb_val,
        active=active_val,
    );
    return w;
}

def connect_descendants(all_wisps: list[Wisp]) -> None {
    by_id: dict[str, Wisp] = {};
    for w in all_wisps {
        by_id[w.id] = w;
    }
    for child in all_wisps {
        pid = child.root_bead_id;
        if pid in by_id {
            parent = by_id[pid];
            if child.id != parent.id {
                parent +>:Descends:+> child;
            }
        }
    }
}

walker CountDesc {
    has claimed: dict[str, bool] = {};
    has tally: int = 0;

    can walk with Wisp entry {
        if here.id in self.claimed {
            skip;
        }
        self.claimed[here.id] = True;
        self.tally += 1;
        print("visit", here.id, "tally", self.tally);
        kids: list[Wisp] = [here ->:Descends:->][?:Wisp];
        kid_ids: list[str] = [];
        for k in kids {
            kid_ids.append(k.id);
        }
        kid_ids = sorted(kid_ids);
        by_kid: dict[str, Wisp] = {};
        for k in kids {
            by_kid[k.id] = k;
        }
        ordered: list[Wisp] = [];
        for kid_id in kid_ids {
            ordered.append(by_kid[kid_id]);
        }
        if ordered {
            visit :0: ordered;
        } else {
            disengage;
        }
    }
}

def descendant_count(root_node: Wisp) -> int {
    wk = root_node spawn CountDesc(claimed={});
    total = wk.tally;
    if total > 0 {
        return total - 1;
    }
    return 0;
}

def workflow_root_descendant_counts(records: list) -> dict[str, int] {
    all_wisps: list[Wisp] = [];
    for rec in records {
        w = wisp_from_record(rec);
        all_wisps.append(w);
        root ++> w;
    }
    connect_descendants(all_wisps);
    counts: dict[str, int] = {};
    for w in all_wisps {
        if is_workflow_root(w.kind, w.formula_contract, w.root_bead_id, w.id, w.active) {
            counts[w.id] = descendant_count(w);
        }
    }
    return counts;
}
