        for fk in field_keys {
            tgt_nm = flds[fk];
            if tgt_nm in chk.defs {
                tgt = chk.defs[tgt_nm] as RecordDef;
                src +>:ByValue:+> tgt;
            }
        }
    }
    return chk;
}

def find_cyclic_records(handle: RecordChecker) -> list[str] {
    cyclic_acc: dict[str, bool] = {};
    visited_global: dict[str, bool] = {};
    start_names: list[str] = [];
    for nm in sorted(handle.defs.keys()) {
        start_names.append(nm);
    }
    for start_nm in start_names {
        if start_nm in visited_global {
            continue;
        }
        src = handle.defs[start_nm] as RecordDef;
        w = src spawn CycleWalker(claimed={}, on_stack={}, cyclic={});
        for ck in w.cyclic.keys() {
            cyclic_acc[ck] = True;
        }
        for ck in w.claimed.keys() {
            visited_global[ck] = True;
        }
    }
    out: list[str] = [];
    for nm in sorted(cyclic_acc.keys()) {
        out.append(nm);
    }
    return out;
}

def validate_no_record_cycles(handle: RecordChecker) -> None {
    cyc = find_cyclic_records(handle);
    if len(cyc) > 0 {
        raise ValueError("by-value record cycle detected");
    }
}
