def fibonacci_cte_memo(n: int, memo: dict[str, int]) -> int {
    key: str = str(n);
    if key in memo {
        return memo[key];
    }
    if n <= 1 {
        memo[key] = n;
        return n;
    }
    a: int = fibonacci_cte_memo(n - 1, memo);
    b: int = fibonacci_cte_memo(n - 2, memo);
    v: int = a + b;
    memo[key] = v;
    return v;
}

def call_graph_pairs(n: int) -> list[list[str]] {
    pairs: list[list[str]] = [];
    if n <= 1 {
        return pairs;
    }
    root_cid: str = "c" + str(n);
    left: list[list[str]] = call_graph_pairs(n - 1);
    right: list[list[str]] = call_graph_pairs(n - 2);
    for p in left {
        pairs.append(p);
    }
    for p in right {
        pairs.append(p);
    }
    pairs.append([root_cid, "c" + str(n - 1)]);
    pairs.append([root_cid, "c" + str(n - 2)]);
    return pairs;
}

def eval_fib_graph(n: int) -> int {
    root_c: Call = Call(cid="c" + str(n), n=n);
    root ++> root_c;
    w: CallEval = root_c spawn CallEval(claimed={}, memo={}, target=n, result=-1);
    return w.result;
}

def run_recursive_repl(repl: dict, n: int) -> dict {
    hit: dict = lookup_name(repl, "fibonacci");
    if not (hit["found"] as bool) {
        err: dict = {"ok": False, "value": -1, "error": "NameError: fibonacci is not defined"};
        return err;
    }
    val: int = fibonacci_cte(n);
    ok: dict = {"ok": True, "value": val, "error": ""};
    return ok;
}
