glob STR_PROPS: list[str] = ["s1", "s2", "s3"];

node SeqRoot {}
node A { has cid: str; }
node B { has cid: str; }
node C { has cid: str; }
node D { has cid: str; }
node Branch { has cid: str; }

edge L1 {}
edge L2 {}
edge R1 {}
edge R2 {}

walker UnionWalker {
    has claimed: dict[str, bool] = {};
    has results: list[str] = [];

    can u_a with A entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        for s in STR_PROPS { self.results.append(s); }
        print("union_a", here.cid);
        disengage;
    }

    can u_b with B entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        for n in NUM_PROPS { self.results.append(n); }
        print("union_b", here.cid);
        disengage;
    }

    can u_c with C entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        for n in NUM_PROPS {
            for s in STR_PROPS { self.results.append(n + s); }
        }
        print("union_c", here.cid);
        disengage;
    }

    can u_d with D entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        for s in STR_PROPS {
            for n in NUM_PROPS { self.results.append(s + n); }
        }
        print("union_d", here.cid);
        disengage;
    }

    can u_branch with Branch entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        print("union_branch", here.cid);
        l1_vals: list[str] = [];
        for nd in [here ->:L1:->][?] {
            sub_claimed: dict[str, bool] = {};
            for k in self.claimed { sub_claimed[k] = self.claimed[k]; }
            w = nd spawn UnionWalker(claimed=sub_claimed);
            for v in w.results { l1_vals.append(v); }
            for k in w.claimed { self.claimed[k] = w.claimed[k]; }
        }
        l2_vals: list[str] = [];
        for nd in [here ->:L2:->][?] {
            sub_claimed: dict[str, bool] = {};
            for k in self.claimed { sub_claimed[k] = self.claimed[k]; }
            w = nd spawn UnionWalker(claimed=sub_claimed);
            for v in w.results { l2_vals.append(v); }
            for k in w.claimed { self.claimed[k] = w.claimed[k]; }
        }
        r1_vals: list[str] = [];
        for nd in [here ->:R1:->][?] {
            sub_claimed: dict[str, bool] = {};
            for k in self.claimed { sub_claimed[k] = self.claimed[k]; }
            w = nd spawn UnionWalker(claimed=sub_claimed);
            for v in w.results { r1_vals.append(v); }
            for k in w.claimed { self.claimed[k] = w.claimed[k]; }
        }
        r2_vals: list[str] = [];
        for nd in [here ->:R2:->][?] {
            sub_claimed: dict[str, bool] = {};
            for k in self.claimed { sub_claimed[k] = self.claimed[k]; }
            w = nd spawn UnionWalker(claimed=sub_claimed);
            for v in w.results { r2_vals.append(v); }
            for k in w.claimed { self.claimed[k] = w.claimed[k]; }
        }
        for a in l1_vals {
            for b in r1_vals { self.results.append(a + b); }
        }
        for a in l2_vals {
            for b in r2_vals { self.results.append(a + b); }
        }
        disengage;
    }
}

def make_engine -> dict {
    eng: dict = {};
    store: dict[str, object] = {};
    tags: dict[str, str] = {};
    eng["store"] = store;
    eng["tags"] = tags;
    eng["next"] = 1;
    gr = SeqRoot();
    root ++> gr;
    eng["graph_root"] = gr;
    return eng;
}

def _next_cid(eng: dict, prefix: str) -> str {
    n: int = eng["next"] as int;
    eng["next"] = n + 1;
    return prefix + "_" + str(n);
}

def _attach(eng: dict, nd: object) {
    gr = eng["graph_root"] as SeqRoot;
    gr ++> nd;
}

def make_a(eng: dict) -> str {
    cid: str = _next_cid(eng, "a");
    nd = A(cid=cid);
    store = eng["store"] as dict[str, object];
    tags = eng["tags"] as dict[str, str];
    store[cid] = nd;
    tags[cid] = "A";
    _attach(eng, nd);
    return cid;
}

def make_b(eng: dict) -> str {
    cid: str = _next_cid(eng, "b");
    nd = B(cid=cid);
    store = eng["store"] as dict[str, object];
    tags = eng["tags"] as dict[str, str];
    store[cid] = nd;
    tags[cid] = "B";
    _attach(eng, nd);
    return cid;
}

def make_c(eng: dict) -> str {
    cid: str = _next_cid(eng, "c");
    nd = C(cid=cid);
    store = eng["store"] as dict[str, object];
    tags = eng["tags"] as dict[str, str];
    store[cid] = nd;
    tags[cid] = "C";
    _attach(eng, nd);
    return cid;
}

def make_d(eng: dict) -> str {
    cid: str = _next_cid(eng, "d");
    nd = D(cid=cid);
    store = eng["store"] as dict[str, object];
    tags = eng["tags"] as dict[str, str];
    store[cid] = nd;
    tags[cid] = "D";
    _attach(eng, nd);
    return cid;
}

def make_branch(eng: dict, l1: str, l2: str, r1: str, r2: str) -> str {
    store = eng["store"] as dict[str, object];
    tags = eng["tags"] as dict[str, str];
    cid: str = _next_cid(eng, "br");
    br = Branch(cid=cid);
    store[cid] = br;
    tags[cid] = "Branch";
    _attach(eng, br);
    _wire_quadrant(br, "L1", store, l1);
    _wire_quadrant(br, "L2", store, l2);
    _wire_quadrant(br, "R1", store, r1);
    _wire_quadrant(br, "R2", store, r2);
    return cid;
}

def _wire_quadrant(br: Branch, edge_name: str, store: dict[str, object], child_id: str) {
    if child_id not in store { return; }
    nd = store[child_id];
    if edge_name == "L1" {
        if nd is A { br +>:L1:+> (nd as A); }
        elif nd is B { br +>:L1:+> (nd as B); }
        elif nd is C { br +>:L1:+> (nd as C); }
        elif nd is D { br +>:L1:+> (nd as D); }
        elif nd is Branch { br +>:L1:+> (nd as Branch); }
    } elif edge_name == "L2" {
        if nd is A { br +>:L2:+> (nd as A); }
        elif nd is B { br +>:L2:+> (nd as B); }
        elif nd is C { br +>:L2:+> (nd as C); }
        elif nd is D { br +>:L2:+> (nd as D); }
        elif nd is Branch { br +>:L2:+> (nd as Branch); }
    } elif edge_name == "R1" {
        if nd is A { br +>:R1:+> (nd as A); }
        elif nd is B { br +>:R1:+> (nd as B); }
        elif nd is C { br +>:R1:+> (nd as C); }
        elif nd is D { br +>:R1:+> (nd as D); }
        elif nd is Branch { br +>:R1:+> (nd as Branch); }
    } elif edge_name == "R2" {
        if nd is A { br +>:R2:+> (nd as A); }
        elif nd is B { br +>:R2:+> (nd as B); }
        elif nd is C { br +>:R2:+> (nd as C); }
        elif nd is D { br +>:R2:+> (nd as D); }
        elif nd is Branch { br +>:R2:+> (nd as Branch); }
    }
}

def _leaf_id(eng: dict, kind: str) -> str {
    if kind == "A" { return make_a(eng); }
    if kind == "B" { return make_b(eng); }
    if kind == "C" { return make_c(eng); }
    return make_d(eng);
}

def rewrite_once(eng: dict, cid: str) -> str {
    if cid == "" { return cid; }
    store = eng["store"] as dict[str, object];
    tags = eng["tags"] as dict[str, str];
    if cid not in store { return cid; }
    tag = tags[cid];
    if tag == "A" {
        return make_branch(eng, _leaf_id(eng, "A"), _leaf_id(eng, "B"), _leaf_id(eng, "C"),
            _leaf_id(eng, "D"));
    }
    if tag == "B" {
        return make_branch(eng, _leaf_id(eng, "B"), _leaf_id(eng, "A"), _leaf_id(eng, "C"),
            _leaf_id(eng, "D"));
    }
    if tag == "C" {
        return make_branch(eng, _leaf_id(eng, "C"), _leaf_id(eng, "D"), _leaf_id(eng, "A"),
            _leaf_id(eng, "B"));
    }
    if tag == "D" {
        return make_branch(eng, _leaf_id(eng, "D"), _leaf_id(eng, "C"), _leaf_id(eng, "B"),
            _leaf_id(eng, "A"));
    }
    return cid;
}

def expand_union(eng: dict, cid: str) -> list[str] {
    store = eng["store"] as dict[str, object];
    if cid not in store { return []; }
    nd = store[cid];
    seed: dict[str, bool] = {};
    w = nd spawn UnionWalker(claimed=seed);
    out: list[str] = [];
    for v in w.results { out.append(v); }
    out.sort();
    return out;
}

def expansion_count(eng: dict, cid: str) -> int {
    vals = expand_union(eng, cid);
    return len(vals);
}

test "leaf_a_union" {
    eng = make_engine();
    cid = make_a(eng);
    got = expand_union(eng, cid);
    exp: list[str] = ["s1", "s2", "s3"];
    assert got == exp;
}

test "leaf_c_cross_product" {
    eng = make_engine();
    cid = make_c(eng);
    got = expand_union(eng, cid);
    exp: list[str] = [];
    for n in NUM_PROPS {
        for s in STR_PROPS { exp.append(n + s); }
    }
    exp.sort();
    assert got == exp;
}

test "branch_quadrant_merge" {
    eng = make_engine();
    a = make_a(eng);
    b = make_b(eng);
    c = make_c(eng);
    d = make_d(eng);
    br = make_branch(eng, a, b, c, d);
    assert expansion_count(eng, br) == 54;
}

test "rewrite_once_leaf" {
    eng = make_engine();
    a = make_a(eng);
    new_id = rewrite_once(eng, a);
    tags = eng["tags"] as dict[str, str];
    assert new_id != a;
    assert tags[new_id] == "Branch";
    assert rewrite_once(eng, new_id) == new_id;
}

test "unknown_id_tolerance" {
    eng = make_engine();
    assert rewrite_once(eng, "ghost") == "ghost";
    assert expand_union(eng, "ghost") == [];
    assert expansion_count(eng, "") == 0;
}

test "cycle_claim_skip" {
    eng = make_engine();
    a = make_a(eng);
    b = make_b(eng);
    inner = make_branch(eng, a, b, a, b);
    outer = make_branch(eng, inner, a, inner, b);
    got = expansion_count(eng, outer);
    assert got == 54;
}
