# arch-hdl-lang/harc-com#483 — by-value record cycle detection via gray/black DFS.

node SchemaRoot {
    with entry {
        root spawn CycleWalker(claimed={}, on_stack={}, cyclic={});
    }
}

node RecordDef {
    has name: str;
    has fields: dict[str, str] = {};
}

edge ByValue {}

obj RecordChecker {
    has defs: dict[str, RecordDef] = {};
    has anchor: SchemaRoot | None = None;
}

walker CycleWalker {
    has claimed: dict[str, bool] = {};
    has on_stack: dict[str, bool] = {};
    has cyclic: dict[str, bool] = {};

    can step with RecordDef entry {
        if here.name in self.claimed {
            if here.name in self.on_stack and self.on_stack[here.name] {
                self.cyclic[here.name] = True;
            }
            skip;
        }
        self.claimed[here.name] = True;
        self.on_stack[here.name] = True;
        print(f"probe {here.name}");
        kids: list[RecordDef] = [];
        for ch in [here ->:ByValue:->][?:RecordDef] {
            kids.append(ch);
        }
        if len(kids) > 0 {
            visit :0: kids;
        } else {
            disengage;
        }
        self.on_stack[here.name] = False;
    }
}

def make_record_checker(definitions: dict[str, dict[str, str]]) -> RecordChecker {
    chk = RecordChecker(defs={}, anchor=None);
    anchor = SchemaRoot();
    chk.anchor = anchor;
    names: list[str] = [];
    for nm in sorted(definitions.keys()) {
        names.append(nm);
    }
    for nm in names {
        rd = RecordDef(name=nm, fields=definitions[nm]);
        chk.defs[nm] = rd;
        anchor ++> rd;
    }
    for nm in names {
        src = chk.defs[nm] as RecordDef;
        flds = definitions[nm];
        field_keys: list[str] = [];
        for fk in sorted(flds.keys()) {
            field_keys.append(fk);
        }
        for fk in field_keys {
            tgt_nm = flds[fk];
            if tgt_nm in chk.defs {
                tgt = chk.defs[tgt_nm] as RecordDef;
                src +>:ByValue:+> tgt;
            }
        }
    }
    return chk;
}

def find_cyclic_records(handle: RecordChecker) -> list[str] {
    cyclic_acc: dict[str, bool] = {};
    visited_global: dict[str, bool] = {};
    start_names: list[str] = [];
    for nm in sorted(handle.defs.keys()) {
        start_names.append(nm);
    }
    for start_nm in start_names {
        if start_nm in visited_global {
            continue;
        }
        src = handle.defs[start_nm] as RecordDef;
        w = src spawn CycleWalker(claimed={}, on_stack={}, cyclic={});
        for ck in w.cyclic.keys() {
            cyclic_acc[ck] = True;
        }
        for ck in w.claimed.keys() {
            visited_global[ck] = True;
        }
    }
    out: list[str] = [];
    for nm in sorted(cyclic_acc.keys()) {
        out.append(nm);
    }
    return out;
}

def validate_no_record_cycles(handle: RecordChecker) {
    cyc = find_cyclic_records(handle);
    if len(cyc) > 0 {
        raise ValueError("by-value record cycle detected");
    }
}
