"""Workflow DAG cycle detection and topological validation.

Lifted from Aman-Git-hala/k8s-adaptive-workflows#2.
"""

node Task {
    has task_id: str;
    has label: str = "";
}

edge Depends {}

obj WorkflowGraph {
