    has tasks: dict[str, Task] = {};
}

walker CycleDetector {
    has on_stack: dict[str, bool] = {};
    has done: dict[str, bool] = {};
    has cycle_found: bool = False;

    can probe with Task entry {
        print({"walker": "CycleDetector", "at": here.task_id});
        if here.task_id == "__root__" {
            kids: list[Task] = [here ->][?:Task];
            for ch in kids {
                visit ch;
            }
            disengage;
        }
        if here.task_id in self.on_stack {
            self.cycle_found = True;
            disengage;
        }
        if here.task_id in self.done {
            skip;
        }
        self.on_stack[here.task_id] = True;
        deps: list[Task] = [here ->:Depends:->][?:Task];
        for ch in deps {
            visit ch;
        }
        self.on_stack[here.task_id] = False;
        self.done[here.task_id] = True;
    }
}

walker TopoVisitor {
    has claimed: dict[str, bool] = {};
    has order: list[str] = [];

    can walk with Task entry {
        print({"walker": "TopoVisitor", "at": here.task_id});
        if here.task_id == "__root__" {
            kids: list[Task] = [here ->][?:Task];
            for ch in kids {
                visit :0: ch;
            }
            disengage;
        }
        if here.task_id in self.claimed {
            skip;
        }
        self.claimed[here.task_id] = True;
        deps: list[Task] = [here ->:Depends:->][?:Task];
        for ch in deps {
            visit :0: ch;
        }
        if here.task_id != "__root__" {
            self.order.append(here.task_id);
        }
    }
}

def _reverse_ids(xs: list[str]) -> list[str] {
    out: list[str] = [];
    i = len(xs) - 1;
    while i >= 0 {
        out.append(xs[i]);
        i -= 1;
    }
    return out;
}

