    nd = Task(task_id=task_id);
    g.tasks[task_id] = nd;
    g.graph_root ++> nd;
    return True;
}

def add_dependency(g: WorkflowGraph, from_id: str, to_id: str) -> bool {
    if from_id not in g.tasks {
        return False;
    }
    if to_id not in g.tasks {
        return False;
    }
    frm = g.tasks[from_id];
    to = g.tasks[to_id];
    frm +>:Depends:+> to;
    return True;
}

