"""Workflow DAG cycle detection and topological validation.

Lifted from Aman-Git-hala/k8s-adaptive-workflows#2.
"""

node Task {
    has task_id: str;
    has label: str = "";
}

edge Depends {}

obj WorkflowGraph {
    has graph_root: Task;
    has tasks: dict[str, Task] = {};
}

walker CycleDetector {
    has on_stack: dict[str, bool] = {};
    has done: dict[str, bool] = {};
    has cycle_found: bool = False;

    can probe with Task entry {
        print({"walker": "CycleDetector", "at": here.task_id});
        if here.task_id == "__root__" {
            kids: list[Task] = [here ->:->][?:Task];
            for ch in kids {
                visit ch;
            }
            disengage;
        }
        if here.task_id in self.on_stack {
            self.cycle_found = True;
            disengage;
        }
        if here.task_id in self.done {
            skip;
        }
        self.on_stack[here.task_id] = True;
        deps: list[Task] = [here ->:Depends:->][?:Task];
        for ch in deps {
            visit ch;
        }
        self.on_stack[here.task_id] = False;
        self.done[here.task_id] = True;
    }
}

walker TopoVisitor {
    has claimed: dict[str, bool] = {};
    has order: list[str] = [];

    can walk with Task entry {
        print({"walker": "TopoVisitor", "at": here.task_id});
        if here.task_id == "__root__" {
            kids: list[Task] = [here ->:->][?:Task];
            for ch in kids {
                visit :0: ch;
            }
            disengage;
        }
        if here.task_id in self.claimed {
            skip;
        }
        self.claimed[here.task_id] = True;
        deps: list[Task] = [here ->:Depends:->][?:Task];
        for ch in deps {
            visit :0: ch;
        }
        if here.task_id != "__root__" {
            self.order.append(here.task_id);
        }
    }
}

def _reverse_ids(xs: list[str]) -> list[str] {
    out: list[str] = [];
    i = len(xs) - 1;
    while i >= 0 {
        out.append(xs[i]);
        i -= 1;
    }
    return out;
}

def create_workflow_graph -> WorkflowGraph {
    g = WorkflowGraph();
    anchor = Task(task_id="__root__", label="");
    g.graph_root = anchor;
    return g;
}

def add_task(g: WorkflowGraph, task_id: str) -> bool {
    if task_id == "__root__" {
        return False;
    }
    if task_id in g.tasks {
        return False;
    }
    nd = Task(task_id=task_id);
    g.tasks[task_id] = nd;
    g.graph_root ++> nd;
    return True;
}

def add_dependency(g: WorkflowGraph, from_id: str, to_id: str) -> bool {
    if from_id not in g.tasks {
        return False;
    }
    if to_id not in g.tasks {
        return False;
    }
    frm = g.tasks[from_id];
    to = g.tasks[to_id];
    frm +>:Depends:+> to;
    return True;
}

def has_cycle(g: WorkflowGraph) -> bool {
    w = g.graph_root spawn CycleDetector();
    print({"has_cycle": w.cycle_found});
    return w.cycle_found;
}

def topological_order(g: WorkflowGraph) -> list[str] | None {
    if has_cycle(g) {
        return None;
    }
    w = g.graph_root spawn TopoVisitor();
    rev = _reverse_ids(w.order);
    print({"topological_order": rev});
    return rev;
}

def validate_workflow(g: WorkflowGraph) -> tuple[bool, str | None] {
    if has_cycle(g) {
        return (False, "cyclic dependency detected");
    }
    ord = topological_order(g);
    if ord is None {
        return (False, "cyclic dependency detected");
    }
    return (True, None);
}

