                tgt: TypeNode = by_name[rname];
                src +>:Refs:+> tgt;
            }
        }
    }
    return anchor;
}

walker InlineCycleWalk {
    has specs: list[dict] = [];
    has claimed: dict[str, bool] = {};
    has stack: list[str] = [];
    has seen: dict[str, bool] = {};
    has out: list[dict] = {};

    can step with TypeNode entry {
        if here.cid in self.claimed { skip; }
        if here.name == "__root__" {
            kids: list[TypeNode] = [here ->:Tree:->][?:TypeNode];
            for ch in kids { visit :0: ch; }
            disengage;
        }
        self.stack.append(here.name);
        refs: list[TypeNode] = [here ->:Refs:->][?:TypeNode];
        for ch in refs {
            si: int = 0;
            start_idx: int = -1;
            while si < len(self.stack) {
                if self.stack[si] == ch.name { start_idx = si; }
                si += 1;
            }
            if start_idx >= 0 {
                cycle: list[str] = [];
                fi: int = start_idx;
                while fi < len(self.stack) {
                    cycle.append(self.stack[fi]);
                    fi += 1;
                }
                ck: str = cycle_key(cycle);
                if ck not in self.seen {
                    self.seen[ck] = True;
                    span: dict[str, int] = lookup_span(self.specs, cycle[0]);
                    self.out.append({
                        "code": CE2095,
                        "name": cycle[0],
                        "line": span["line"],
                        "col": span["col"],
                        "chain": format_chain(cycle)
                    });
                    print {"ce2095", cycle[0], format_chain(cycle)};
                }
                skip;
            }
            visit :0: ch;
        }
        new_stack: list[str] = [];
        pi: int = 0;
        while pi < len(self.stack) - 1 {
            new_stack.append(self.stack[pi]);
            pi += 1;
        }
        self.stack = new_stack;
        self.claimed[here.cid] = True;
    }
}

def normalize_diags(items: list[dict]) -> list[dict] {
    xs: list[dict] = sorted(items);
    return xs;
}

def find_inline_cycles(specs: list[dict]) -> list[dict] {
    anchor: TypeNode = build_anchor(specs);
    w: InlineCycleWalk = anchor spawn InlineCycleWalk(specs=specs, out=[], claimed={}, seen={});
    return normalize_diags(w.out);
}

def register_all_types(specs: list[dict], reruns: int) -> list[dict] {
    merged: dict[str, dict] = {};
    r: int = 0;
    while r < reruns {
        batch: list[dict] = find_inline_cycles(specs);
        for d in batch {
            ck: str = d["chain"] as str;
            merged[ck] = d;
        }
        r += 1;
    }
    keys: list[str] = sorted(merged);
    out: list[dict] = [];
    for k in keys { out.append(merged[k]); }
    return out;
}
