def HashTable(size: int = 50) -> HtState {
    ht = HtState(size=size);
    tbl: list[list[tuple[str, int]]] = [];
    i = 0;
    while i < size {
        tbl.append([]);
        i += 1;
    }
    ht.buckets = tbl;
    return ht;
}

def _hash(ht: HtState, key: str) -> int {
    return hash(key) % ht.size;
}

def set(ht: HtState, key: str, value: int) -> None {
    hk = _hash(ht, key);
    bucket = ht.buckets[hk];
    i = 0;
    while i < len(bucket) {
        kv = bucket[i];
        k = kv[0];
        if k == key {
            bucket[i] = (key, value);
            return;
        }
        i += 1;
    }
    bucket.append((key, value));
}

def get(ht: HtState, key: str) -> int {
    hk = _hash(ht, key);
    bucket = ht.buckets[hk];
    i = 0;
    while i < len(bucket) {
        kv = bucket[i];
        k = kv[0];
        v = kv[1];
        if k == key {
            return v;
        }
        i += 1;
    }
    raise KeyError(msg=key);
}

def delete(ht: HtState, key: str) -> None {
    hk = _hash(ht, key);
    bucket = ht.buckets[hk];
    i = 0;
    while i < len(bucket) {
        kv = bucket[i];
        k = kv[0];
        if k == key {
            nxt: list[tuple[str, int]] = [];
            j = 0;
            while j < len(bucket) {
                if j != i {
                    nxt.append(bucket[j]);
                }
                j += 1;
            }
            ht.buckets[hk] = nxt;
            return;
        }
        i += 1;
    }
    raise KeyError(msg=key);
}

def bfs_visit_order(graph_root: GNode) -> list[str] {
    wk = graph_root spawn BfsOrderWalker(claimed={});
    return wk.order;
}
