def parse_nested_comparam(raw: dict) -> dict {
    out: dict = {};
    keys = sorted(raw);
    for k in keys {
        v = raw[k];
        if v is int {
            out[k] = v;
        } else {
            if v is dict {
                nested: dict = parse_nested_comparam(v as dict);
                out[k] = nested;
            }
        }
    }
    return out;
}

def _wire_group(parent: ParamGroup, raw: dict, prefix: str) -> None {
    keys = sorted(raw);
    for k in keys {
        v = raw[k];
        if v is int {
            dot: str = k;
            if prefix != "" {
                dot = prefix + "." + k;
            }
            leaf = ParamLeaf(key=k, val=v, dot_path=dot);
            root ++> leaf;
            parent +>:Child:+> leaf;
        } else {
            if v is dict {
                child_grp = ParamGroup(name=k);
                root ++> child_grp;
                parent +>:Child:+> child_grp;
                child_prefix: str = k;
                if prefix != "" {
                    child_prefix = prefix + "." + k;
                }
                _wire_group(child_grp, v as dict, child_prefix);
            }
        }
    }
}

def build_param_graph(nested: dict) -> ParamGroup {
    grp = ParamGroup(name="");
    root ++> grp;
    _wire_group(grp, nested, "");
    return grp;
}

def flatten_comparam_leaves(nested: dict) -> dict[str, int] {
