    _collect_invalid(raw, "", bad);
    return sorted(bad);
}

def _collect_invalid(raw: dict, prefix: str, bad: list[str]) -> None {
    keys = sorted(raw);
    for k in keys {
        v = raw[k];
        path: str = k;
        if prefix != "" {
            path = prefix + "." + k;
        }
        if v is int {
            continue;
        }
        if v is dict {
            _collect_invalid(v as dict, path, bad);
        } else {
            bad.append(path);
        }
    }
}
