def collect_ids(adj: dict[str, list[str]]) -> list[str] {
    ids: list[str] = [];
    for src in adj {
        if src not in ids { ids.append(src); }
        nbrs = adj[src];
        for dst in nbrs {
            if dst not in ids { ids.append(dst); }
        }
    }
    return sorted(ids);
}

def build_graph(adj: dict[str, list[str]]) -> dict[str, GraphNode] {
    nodes: dict[str, GraphNode] = {};
    for nid in collect_ids(adj) {
        nd = GraphNode(nid=nid);
        nodes[nid] = nd;
        root ++> nd;
    }
    for src in adj {
        src_nd = nodes[src];
        for dst in sorted(adj[src]) {
            dst_nd = nodes[dst];
            src_nd +>:Adj:+> dst_nd;
        }
    }
    return nodes;
}

def bfs(adj: dict[str, list[str]], start: str) -> list[str] {
    if start not in adj {
        all_ids = collect_ids(adj);
        found = False;
        for x in all_ids {
            if x == start { found = True; }
        }
        if not found { return []; }
    }
    nodes = build_graph(adj);
    if start not in nodes { return []; }
    w = nodes[start] spawn BfsWalker(claimed={});
    return w.order;
}

def dfs_iterative(adj: dict[str, list[str]], start: str) -> list[str] {
    if start not in adj {
        all_ids = collect_ids(adj);
        found = False;
        for x in all_ids {
            if x == start { found = True; }
        }
        if not found { return []; }
    }
    nodes = build_graph(adj);
    if start not in nodes { return []; }
    w = nodes[start] spawn DfsIterWalker(claimed={});
    return w.order;
}

def dfs_recursive(adj: dict[str, list[str]], start: str) -> list[str] {
    if start not in adj {
        all_ids = collect_ids(adj);
        found = False;
        for x in all_ids {
            if x == start { found = True; }
        }
