def _make_dll_node(lst: ListState, data: int) -> DllNode {
    nd = DllNode(data=data, nid="dll_%d" % lst.next_seq);
    lst.next_seq += 1;
    root ++> nd;
    return nd;
}

def DoublyLinkedList -> ListState {
    return ListState();
}

def append(lst: ListState, data: int) {
    nd = _make_dll_node(lst, data);
    if not lst.head {
        lst.head = nd;
        lst.tail = nd;
    } else {
        lst.tail +>:Next:+> nd;
        nd +>:Prev:+> lst.tail;
        lst.tail = nd;
    }
    lst.length += 1;
}

def prepend(lst: ListState, data: int) {
    nd = _make_dll_node(lst, data);
    if not lst.head {
        lst.head = nd;
        lst.tail = nd;
    } else {
        nd +>:Next:+> lst.head;
        lst.head +>:Prev:+> nd;
        lst.head = nd;
    }
    lst.length += 1;
}

def traverse_to_index(lst: ListState, index: int) -> DllNode {
    if index < 0 or index >= lst.length {
        raise IndexError(msg="Index out of range");
    }
    wk = lst.head spawn IndexWalker(target=index, claimed={});
    if wk.found {
        return wk.found;
    }
    raise IndexError(msg="Index out of range");
}

def insert_at(lst: ListState, index: int, data: int) {
    if index < 0 or index > lst.length {
        raise IndexError(msg="Index out of range");
    }
    if index == 0 {
        prepend(lst, data);
        return;
    }
    if index == lst.length {
        append(lst, data);
        return;
    }
    nd = _make_dll_node(lst, data);
    leader = traverse_to_index(lst, index - 1);
    follower: DllNode | None = None;
    for ch in [leader ->:Next:->][?:DllNode] {
        follower = ch;
    }
    leader +>:Next:+> nd;
    nd +>:Prev:+> leader;
    if follower {
        nd +>:Next:+> follower;
        follower +>:Prev:+> nd;
    }
    lst.length += 1;
}

def remove_at(lst: ListState, index: int) {
    if index < 0 or index >= lst.length {
        raise IndexError(msg="Index out of range");
    }
    if index == 0 {
        old_head = lst.head;
        nxt: DllNode | None = None;
        for ch in [old_head ->:Next:->][?:DllNode] {
            nxt = ch;
        }
        lst.head = nxt;
        if not lst.head {
            lst.tail = None;
        }
        lst.length -= 1;
        return;
    }
    if index == lst.length - 1 {
        old_tail = lst.tail;
        prv: DllNode | None = None;
        for ch in [old_tail ->:Prev:->][?:DllNode] {
            prv = ch;
        }
        lst.tail = prv;
        lst.length -= 1;
        return;
    }
    leader = traverse_to_index(lst, index - 1);
    unwanted: DllNode | None = None;
    for ch in [leader ->:Next:->][?:DllNode] {
        unwanted = ch;
    }
    follower: DllNode | None = None;
    if unwanted {
        for ch in [unwanted ->:Next:->][?:DllNode] {
            follower = ch;
        }
    }
    if follower {
        leader +>:Next:+> follower;
        follower +>:Prev:+> leader;
    } else {
        lst.tail = leader;
    }
    lst.length -= 1;
}

