}

def _hash_index(ht: HtState, key: str) -> int {
    h = 0;
    for c in key {
        h = (h * 31 + ord(c)) % ht.size;
    }
    return h;
}

def HashTable(size: int = 50) -> HtState {
    ht = HtState(size=size);
    i = 0;
    while i < size {
        empty_bucket: list[tuple[str, int]] = [];
        ht.buckets.append(empty_bucket);
        i += 1;
    }
    root ++> ht;
    return ht;
}

def ht_put(ht: HtState, key: str, value: int) {
    idx = _hash_index(ht, key);
    bucket = ht.buckets[idx];
    i = 0;
    while i < len(bucket) {
        pair = bucket[i];
        if pair[0] == key {
            bucket[i] = (key, value);
            return;
        }
        i += 1;
    }
    bucket.append((key, value));
}

def ht_get(ht: HtState, key: str) -> int {
    idx = _hash_index(ht, key);
    bucket = ht.buckets[idx];
    i = 0;
    while i < len(bucket) {
        pair = bucket[i];
        if pair[0] == key {
            return pair[1];
        }
        i += 1;
    }
    raise KeyError(msg=key);
}

