            _dfs_validate(g, group_subtasks, group_names, active, done);
        }
    }
}

def _find_roots(group_subtasks: dict[str, list[str]], group_names: set[str]) -> list[str] {
    child_refs: dict[str, bool] = {};
    for parent in group_subtasks {
        subs: list[str] = group_subtasks[parent] as list[str];
        for ch in subs {
            if ch in group_names {
                child_refs[ch] = True;
            }
        }
    }
    roots: list[str] = [];
    sorted_names: list[str] = sorted(group_names);
    for g in sorted_names {
        if g in group_subtasks and g not in child_refs {
            roots.append(g);
        }
    }
    return roots;
}

def _materialize_nodes(group_subtasks: dict[str, list[str]], group_names: set[str]) -> dict[str, Group] {
    nodes: dict[str, Group] = {};
    sorted_names: list[str] = sorted(group_names);
    for g in sorted_names {
        nd = Group(gid=g);
        root ++> nd;
        nodes[g] = nd;
    }
    for parent in group_subtasks {
        if parent not in nodes {
            continue;
        }
        pnode: Group = nodes[parent];
        subs: list[str] = group_subtasks[parent] as list[str];
        for ch in subs {
            if ch not in nodes {
                continue;
            }
            cnode: Group = nodes[ch];
            pnode +>:HasSubtask:+> cnode;
        }
    }
    return nodes;
}

walker OrderWalk {
    has claimed: dict[str, bool] = {};
    has depths: dict[str, int] = {};
    has order: list[str] = [];
    has depth: int = 0;

    can step with Group entry {
        if here.gid in self.claimed {
            skip;
        }
        self.claimed[here.gid] = True;
        self.depths[here.gid] = self.depth;
        self.order.append(here.gid);
        child_nodes: list[Group] = [here ->:HasSubtask:->][?:Group];
        child_gids: list[str] = [];
        for cn in child_nodes {
            child_gids.append(cn.gid);
        }
        sorted_gids: list[str] = sorted(child_gids);
        for sg in sorted_gids {
            for cn in child_nodes {
                if cn.gid == sg {
                    visit :0: [cn];
                }
            }
        }
    }
}

def _build_hierarchy_info(group_subtasks: dict[str, list[str]], group_names: set[str]) -> dict[str, object] {
    _validate_acyclic(group_subtasks, group_names);
    nodes: dict[str, Group] = _materialize_nodes(group_subtasks, group_names);
    roots: list[str] = _find_roots(group_subtasks, group_names);
    depths: dict[str, int] = {};
    order: list[str] = [];
    claimed: dict[str, bool] = {};
    for rgid in roots {
        if rgid in nodes {
            rnode: Group = nodes[rgid];
            w = rnode spawn OrderWalk(claimed=claimed, depths=depths, order=order, depth=0);
            print(w.order);
        }
    }
    sorted_names: list[str] = sorted(group_names);
    for g in sorted_names {
        if g not in claimed {
            order.append(g);
            depths[g] = 0;
        }
    }
    result: dict[str, object] = {};
    result["depths"] = depths;
    result["order"] = order;
    return result;
}

