"""
Recursive ancestor queries — blacksmithgu/obsidian-dataview#318.
"""

node Item {
    has cid: str;
    has label: str;
}

edge Parent {}

node Store {
    has by_id: dict[str, Item] = {};
}

node Launcher {}

walker AncestorCollect {
    has claimed: dict[str, bool] = {};
    has found: list[str] = [];

    can rise with Item entry {
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        parents: list[Item] = [];
        for p in [here <-:Parent:<-][?:Item] {
            parents.append(p);
        }
        for p in parents {
            self.found.append(p.cid);
        }
        print("ancestor step", here.cid);
        if parents {
            visit :0: parents;
        } else {
            disengage;
        }
    }
}

walker BreadcrumbWalk {
    has claimed: dict[str, bool] = {};
    has chain: list[str] = [];

    can climb with Item entry {
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        self.chain.append(here.cid);
        parents: list[Item] = [];
        for p in [here <-:Parent:<-][?:Item] {
            parents.append(p);
        }
        print("breadcrumb step", here.cid);
        chosen: Item | None = None;
        best: str = "";
        for p in parents {
            if (not chosen) or (p.cid < best) {
                chosen = p;
                best = p.cid;
            }
        }
        if chosen {
            visit :0: [chosen];
        } else {
            disengage;
        }
    }
}

walker HierarchyDemo {
    can boot with Launcher entry {
        st = make_store();
        add_item(st, "epic", "Epic");
        add_item(st, "story", "Story", "epic");
        add_item(st, "task", "Task", "story");
        bc = breadcrumb(st, "task");
        ans = ancestors(st, "task");
        print("demo breadcrumb", bc);
        print("demo ancestors", ans);
        disengage;
    }
}

def make_store -> Store {
    s = Store(by_id={});
    root ++> s;
    return s;
}

def add_item(st: Store, item_id: str, label: str, parent_id: str | None = None) {
    nd = Item(cid=item_id, label=label);
    root ++> nd;
    st ++> nd;
    st.by_id[item_id] = nd;
    if parent_id {
        par = st.by_id[parent_id] as Item;
        nd +>:Parent:+> par;
    }
}

def ancestors(st: Store, item_id: str) -> list[str] {
    if item_id not in st.by_id {
        return [];
    }
    start = st.by_id[item_id] as Item;
    w = start spawn AncestorCollect(claimed={}, found=[]);
    out: list[str] = [];
    for cid in w.found {
        out.append(cid);
    }
    return sorted(out);
}

def breadcrumb(st: Store, item_id: str) -> list[str] {
    if item_id not in st.by_id {
        return [];
    }
    start = st.by_id[item_id] as Item;
    w = start spawn BreadcrumbWalk(claimed={}, chain=[]);
    out: list[str] = [];
    for cid in w.chain {
        out.append(cid);
    }
    return out;
}

with entry {
    ln = Launcher();
    root ++> ln;
    ln spawn HierarchyDemo;
}
