```jac
"""Recursive undeleted file traversal with phased ORDER/LIMIT — ent/ent#2167."""

node File {
    has fid: str;
    has name: str;
    has deleted: bool = False;
}

edge Parent {}

node GraphHub {
    has by_id: dict[str, File] = {};
    has roots: list[str] = [];
}

walker ChildGather {
    has claimed: dict[str, bool] = {};
    has found: list[str] = [];

    can gather with File entry {
        if here.fid in self.claimed { skip; }
        self.claimed[here.fid] = True;
        kids: list[File] = [here ->:Parent:->][?:File];
        for ch in kids {
            if ch.fid in self.claimed { continue; }
            if ch.deleted { continue; }
            self.found.append(ch.fid);
        }
        print(len(self.found));
        disengage;
    }
}

def sort_ids(hub: GraphHub, ids: list[str], key: str) -> list[str] {
    xs: list[str] = [];
    for x in ids { xs.append(x); }
    n = len(xs);
    i = 0;
    while i < n {
        j = i + 1;
        while j < n {
            av = hub.by_id[xs[i]].name;
            bv = hub.by_id[xs[j]].name;
            if key == "id" {
                av = xs[i];
                bv = xs[j];
            }
            if av > bv {
                tmp = xs[i];
                xs[i] = xs[j];
                xs[j] = tmp;
            }
            j += 1;
        }
        i += 1;
    }
    return xs;
}

def dedupe_ids(ids: list[str]) -> list[str] {
    seen: dict[str, bool] = {};
    out: list[str] = [];
    for x in ids {
        if x in seen { continue; }
        seen[x] = True;
        out.append(x);
    }
    return out;
}

def apply_limit(ids: list[str], lim: int) -> list[str] {
    if lim <= 0 { return ids; }
    out: list[str] = [];
    i = 0;
    while i < lim && i < len(ids) {
        out.append(ids[i]);
        i += 1;
    }
    return out;
}

def build_graph(entries: list[list[str]]) -> GraphHub {
    hub = GraphHub();
    nodes: dict[str, File] = {};
    for row in entries {
        fid = row[0];
        nm = row[1];
        par = row[2];
        del_flag = row[3] == "1";
        nd = File(fid=fid, name=nm, deleted=del_flag);
        nodes[fid] = nd;
        root ++> nd;
        hub.by_id[fid] = nd;
        if par == "" { hub.roots.append(fid); }
    }
    for row in entries {
        par = row[2];
        if par != "" {
            nodes[par] +>:Parent:+> nodes[row[0]];
        }
    }
    return hub;
}

def build_ent_fixture -> GraphHub {
    rows: list[list[str]] = [];
    rows.append(["1", "a", "", "0"]);
    rows.append(["2", "b", "1", "0"]);
    rows.append(["3", "ba", "2", "0"]);
    rows.append(["4", "bb", "2", "0"]);
    rows.append(["5", "bc", "2", "1"]);
    rows.append(["6", "c", "1", "1"]);
    rows.append(["7", "ca", "6", "0"]);
    rows.append(["8", "cb", "6", "0"]);
    rows.append(["9", "d", "1", "1"]);
    return build_graph(rows);
}

def lookup_name(hub: GraphHub, fid: str) -> str {
    if fid not in hub.by_id { return ""; }
    return hub.by_id[fid].name;
}

def recursive_undeleted_names(
    hub: GraphHub,
    initial_order: str,
    initial_limit: int,
    recursive_order: str,
    recursive_limit: int,
) -> list[str] {
    anchor: list[str] = [];
    for rid in hub.roots {
        nd = hub.by_id[rid];
        if not nd.deleted { anchor.append(rid); }
    }
    anchor = sort_ids(hub, anchor, initial_order);
    anchor = apply_limit(anchor, initial_limit);
    claimed: dict[str, bool] = {};
    result: list[str] = [];
    for aid in anchor {
        result.append(aid);
        claimed[aid] = True;
    }
    while True {
        batch: list[str] = [];
        for pid in result {
            pnd = hub.by_id[pid];
            w = pnd spawn ChildGather(claimed=claimed);
            for cid in w.found { batch.append(cid); }
        }
        batch = dedupe_ids(batch);
        fresh: list[str] = [];
        for x in batch {
            if x not in claimed { fresh.append(x); }
        }
        if len(fresh) == 0 { break; }
        fresh = sort_ids(hub, fresh, recursive_order);
        fresh = apply_limit(fresh, recursive_limit);
        for nid in fresh {
            claimed[nid] = True;
            result.append(nid);
        }
    }
    names: list[str] = [];
    for fid in result { names.append(hub.by_id[fid].name); }
    return names;
}
