"""EleutherAI/lm-evaluation-harness#4133 — hierarchy cycle validation and display order."""

node Group {
    has gid: str;
}

edge HasSubtask {}

def _dfs_validate(
    gid: str,
    group_subtasks: dict[str, list[str]],
    group_names: set[str],
    active: dict[str, bool],
    done: dict[str, bool],
) -> None {
    if gid in done {
        return;
    }
    if gid in active {
        raise ValueError("cyclic group metadata");
    }
    if gid not in group_names {
        return;
    }
    active[gid] = True;
    if gid in group_subtasks {
        raw: list[str] = group_subtasks[gid] as list[str];
        child_gids: list[str] = sorted(raw);
        for ch in child_gids {
            if ch in group_names {
                _dfs_validate(ch, group_subtasks, group_names, active, done);
            }
        }
    }
    del active[gid];
    done[gid] = True;
}

def _validate_acyclic(group_subtasks: dict[str, list[str]], group_names: set[str]) {
    active: dict[str, bool] = {};
    done: dict[str, bool] = {};
    sorted_names: list[str] = sorted(group_names);
    for g in sorted_names {
        if g not in done {
            _dfs_validate(g, group_subtasks, group_names, active, done);
        }
    }
}

def _find_roots(group_subtasks: dict[str, list[str]], group_names: set[str]) -> list[str] {
    child_refs: dict[str, bool] = {};
    for parent in group_subtasks {
        subs: list[str] = group_subtasks[parent] as list[str];
        for ch in subs {
            if ch in group_names {
                child_refs[ch] = True;
            }
        }
    }
    roots: list[str] = [];
    sorted_names: list[str] = sorted(group_names);
    for g in sorted_names {
        if g in group_subtasks and g not in child_refs {
            roots.append(g);
        }
    }
    return roots;
}

def _materialize_nodes(group_subtasks: dict[str, list[str]], group_names: set[str]) -> dict[str, Group] {
    nodes: dict[str, Group] = {};
    sorted_names: list[str] = sorted(group_names);
    for g in sorted_names {
        nd = Group(gid=g);
        root ++> nd;
        nodes[g] = nd;
    }
    for parent in group_subtasks {
        if parent not in nodes {
            continue;
        }
        pnode: Group = nodes[parent];
        subs: list[str] = group_subtasks[parent] as list[str];
        for ch in subs {
            if ch not in nodes {
                continue;
            }
            cnode: Group = nodes[ch];
            pnode +>:HasSubtask:+> cnode;
        }
    }
    return nodes;
}

walker OrderWalk {
    has claimed: dict[str, bool] = {};
    has depths: dict[str, int] = {};
    has order: list[str] = [];
    has depth: int = 0;

    can step with Group entry {
