                }
            }
        }
    }
}

def _build_hierarchy_info(group_subtasks: dict[str, list[str]], group_names: set[str]) -> dict[str, object] {
    _validate_acyclic(group_subtasks, group_names);
    nodes: dict[str, Group] = _materialize_nodes(group_subtasks, group_names);
    roots: list[str] = _find_roots(group_subtasks, group_names);
    depths: dict[str, int] = {};
