obj HashTable {
    has size: int = 50;
    has buckets: dict[int, dict[str, str]] = {};

    def _slot(self, key: str) -> int {
        total = 0;
        for c in key {
            total += ord(c);
        }
        return total % self.size;
    }

    def set(self, key: str, value: str) -> None {
        slot = self._slot(key);
        inner: dict[str, str] = {};
        if slot in self.buckets {
            inner = self.buckets[slot] as dict[str, str];
        }
        inner[key] = value;
        self.buckets[slot] = inner;
    }

    def get(self, key: str) -> str {
        slot = self._slot(key);
        if slot not in self.buckets {
            raise KeyError(message=key);
        }
        inner = self.buckets[slot] as dict[str, str];
        if key not in inner {
            raise KeyError(message=key);
        }
        return inner[key];
    }

    def delete(self, key: str) -> None {
        slot = self._slot(key);
        if slot not in self.buckets {
            raise KeyError(message=key);
        }
        inner = self.buckets[slot] as dict[str, str];
        if key not in inner {
            raise KeyError(message=key);
        }
        del inner[key];
        self.buckets[slot] = inner;
    }
