    def append(self, data: int) -> None {
        nd = ListNode(data=data, cid=self._mk_cid());
        if not self.head {
            self.head = nd;
            self.tail = nd;
            root ++> nd;
        } else {
            self.tail +>:Next:+> nd;
            nd +>:Prev:+> self.tail;
            self.tail = nd;
        }
        self.length += 1;
    }

    def prepend(self, data: int) -> None {
        nd = ListNode(data=data, cid=self._mk_cid());
        if not self.head {
            self.head = nd;
            self.tail = nd;
            root ++> nd;
        } else {
            nd +>:Next:+> self.head;
            self.head +>:Prev:+> nd;
            self.head = nd;
        }
        self.length += 1;
