    def traverse_to_index(self, index: int) -> ListNode {
        if index < 0 or index >= self.length {
            raise IndexError(message="Index out of range");
        }
        cur = self.head;
        counter = 0;
        while counter != index {
            nxt: list[ListNode] = [];
            for n in [cur ->:Next:->][?:ListNode] {
                nxt.append(n);
            }
            cur = nxt[0];
            counter += 1;
        }
        return cur;
    }

    def insert_at(self, index: int, data: int) -> None {
        if index < 0 or index > self.length {
            raise IndexError(message="Index out of range");
        }
        if index == 0 {
            self.prepend(data);
            return;
        }
        if index == self.length {
            self.append(data);
            return;
        }
        nd = ListNode(data=data, cid=self._mk_cid());
        leader = self.traverse_to_index(index - 1);
        follower: list[ListNode] = [];
        for n in [leader ->:Next:->][?:ListNode] {
            follower.append(n);
        }
        fol = follower[0];
        leader +>:Next:+> nd;
        nd +>:Prev:+> leader;
        nd +>:Next:+> fol;
        fol +>:Prev:+> nd;
        self.length += 1;
    }

    def remove_at(self, index: int) -> None {
        if index < 0 or index >= self.length {
            raise IndexError(message="Index out of range");
        }
        if index == 0 {
            old = self.head;
            nxt: list[ListNode] = [];
            for n in [old ->:Next:->][?:ListNode] {
                nxt.append(n);
            }
            if nxt {
                self.head = nxt[0];
            } else {
                self.head = None;
                self.tail = None;
            }
        } elif index == self.length - 1 {
            old = self.tail;
            prevs: list[ListNode] = [];
            for p in [old ->:Prev:->][?:ListNode] {
                prevs.append(p);
            }
            if prevs {
                self.tail = prevs[0];
            } else {
                self.head = None;
                self.tail = None;
            }
        } else {
            leader = self.traverse_to_index(index - 1);
            unwanted: list[ListNode] = [];
            for n in [leader ->:Next:->][?:ListNode] {
                unwanted.append(n);
            }
            un = unwanted[0];
            un_nxt: list[ListNode] = [];
            for n in [un ->:Next:->][?:ListNode] {
                un_nxt.append(n);
            }
            fol = un_nxt[0];
            leader +>:Next:+> fol;
            fol +>:Prev:+> leader;
        }
        self.length -= 1;
    }

