def dedupe_ids(ids: list[str]) -> list[str] {
    seen: dict[str, bool] = {};
    out: list[str] = [];
    for x in ids {
        if x in seen { continue; }
        seen[x] = True;
        out.append(x);
    }
    return out;
}

def apply_limit(ids: list[str], lim: int) -> list[str] {
    if lim <= 0 { return ids; }
    out: list[str] = [];
    i = 0;
    while i < lim && i < len(ids) {
        out.append(ids[i]);
        i += 1;
    }
    return out;
}

def build_graph(entries: list[list[str]]) -> GraphHub {
    hub = GraphHub();
    nodes: dict[str, File] = {};
    for row in entries {
