"""ent/ent#1024 — descendants and ancestors (WITH RECURSIVE style reachability)."""

node User {
    has uid: str;
    has name: str = "";
}

edge Follows {}

obj GraphStore {
    has by_uid: dict[str, User] = {};
}

def make_store -> GraphStore {
    return GraphStore(by_uid={});
}

def add_user(store: GraphStore, uid: str, name: str = "") -> User {
    u = User(uid=uid, name=name);
    store.by_uid[uid] = u;
    return u;
}

def connect_follows(follower: User, followee: User) {
    follower +>:Follows:+> followee;
}

walker DescCollect {
    has claimed: dict[str, bool] = {};
    has origin: str = "";
    has found: list[str] = [];

    can step with User entry {
        if here.uid in self.claimed {
            skip;
        }
        self.claimed[here.uid] = True;
        if here.uid != self.origin {
            self.found.append(here.uid);
        }
        kids: list[User] = [];
        for ch in [here ->:Follows:->][?:User] {
            kids.append(ch);
        }
        if len(kids) > 0 {
            visit :0: kids;
        } else {
            disengage;
        }
    }
}

walker AncCollect {
    has claimed: dict[str, bool] = {};
    has origin: str = "";
    has found: list[str] = [];

    can step with User entry {
        if here.uid in self.claimed {
            skip;
        }
        self.claimed[here.uid] = True;
        if here.uid != self.origin {
            self.found.append(here.uid);
        }
        preds: list[User] = [];
        for p in [here <-:Follows:<-][?:User] {
            preds.append(p);
        }
        if len(preds) > 0 {
            visit :0: preds;
        } else {
            disengage;
        }
    }
}

def get_descendants(store: GraphStore, uid: str) -> list[str] {
    if uid not in store.by_uid {
        return [];
    }
    start = store.by_uid[uid];
    w = start spawn DescCollect(claimed={}, origin=uid, found=[]);
    out: list[str] = [];
    for x in w.found {
        out.append(x);
    }
    return sorted(out);
}

def get_ancestors(store: GraphStore, uid: str) -> list[str] {
    if uid not in store.by_uid {
        return [];
    }
    start = store.by_uid[uid];
    w = start spawn AncCollect(claimed={}, origin=uid, found=[]);
    out: list[str] = [];
    for x in w.found {
        out.append(x);
    }
    return sorted(out);
}

