walker DemoPrint {
    can step with DemoAnchor entry {
        st: GraphStore = make_store();
        a = add_user(st, "a", "A");
        b = add_user(st, "b", "B");
        connect_follows(a, b);
        ds: list[str] = get_descendants(st, "a");
        print("descendants a:", ds);
        disengage;
    }
}

