walker DirectedCycleWalker {
    has claimed: dict[str, bool] = {};
    has color: dict[str, int] = {};
    has found: bool = False;

    can dfs with V entry {
        cv: int = 0;
        if here.vid in self.color {
            cv = self.color[here.vid];
        }
        if cv == 2 {
            skip;
        }
        if cv == 1 {
            self.found = True;
            print("directed_cycle", here.vid);
            skip;
        }
        if here.vid in self.claimed {
            skip;
        }
        self.claimed[here.vid] = True;
        self.color[here.vid] = 1;
        kids: list[V] = [];
        for nb in [here ->:E:->][?:V] {
            nvid = nb.vid;
            nc: int = 0;
            if nvid in self.color {
                nc = self.color[nvid];
            }
            if nc == 1 {
                self.found = True;
                print("directed_back_edge", here.vid, nvid);
            }
            if nc != 2 {
                kids.append(nb);
            }
        }
        self.color[here.vid] = 2;
        if kids {
            visit :0: kids;
        } else {
            disengage;
        }
    }
}

def new_graph(directed: bool) -> GraphMeta {
    return GraphMeta(directed=directed);
}

def add_vertex(meta: GraphMeta, vid: str) -> None {
    if vid in meta.verts {
        return;
    }
    nd = V(vid=vid);
    meta.verts[vid] = nd;
    if meta.anchor is None {
        meta.anchor = nd;
        root ++> nd;
    }
}

def add_edge(meta: GraphMeta, u: str, v: str) -> None {
    if u not in meta.verts or v not in meta.verts {
        return;
    }
    a = meta.verts[u];
    b = meta.verts[v];
    a +>:E:+> b;
    if not meta.directed {
        b +>:E:+> a;
    }
}

def _find_parent(parent: dict[str, str], x: str) -> str {
    px = parent[x];
    if px != x {
        px = _find_parent(parent, px);
        parent[x] = px;
    }
    return px;
}

def has_cycle_directed(meta: GraphMeta) -> bool {
    color: dict[str, int] = {};
    keys: list[str] = [];
    for k in meta.verts {
        keys.append(k);
    }
    keys = sorted(keys);
    for vid in keys {
        color[vid] = 0;
    }
    found = False;
    for vid in keys {
        if color[vid] != 0 {
            continue;
        }
        start = meta.verts[vid];
        w = start spawn DirectedCycleWalker(claimed={}, color=color, found=False);
        print("probe_directed", vid, w.found);
        color = w.color;
        if w.found {
            found = True;
        }
    }
    return found;
}

def has_cycle_undirected(meta: GraphMeta) -> bool {
    parent: dict[str, str] = {};
    keys: list[str] = [];
    for k in meta.verts {
        keys.append(k);
    }
    keys = sorted(keys);
    for vid in keys {
        parent[vid] = vid;
    }
    for u in keys {
        u_node = meta.verts[u];
        for nb in [u_node ->:E:->][?:V] {
            v = nb.vid;
            pu = _find_parent(parent, u);
            pv = _find_parent(parent, v);
            if pu == pv {
                print("undirected_cycle", u, v);
                return True;
            }
            parent[pu] = pv;
        }
    }
    return False;
}

def has_cycle(meta: GraphMeta) -> bool {
    if meta.directed {
        return has_cycle_directed(meta);
    }
    return has_cycle_undirected(meta);
}

