def load_all_edges(gr: GraphRoot, pairs: list[list[str]]) -> int {
    nodes: dict[str, GNode] = {};
    for ch in [gr ->:->][?:GNode] {
        if ch.nid not in nodes { nodes[ch.nid] = ch; }
    }
    added: int = 0;
    for pair in pairs {
        s = pair[0];
        t = pair[1];
        if s not in nodes {
            sn = GNode(nid=s);
            nodes[s] = sn;
            gr ++> sn;
        }
        if t not in nodes {
            tn = GNode(nid=t);
            nodes[t] = tn;
            gr ++> tn;
        }
        nodes[s] +>:Refer:+> nodes[t];
        added += 1;
