def load_all_edges(gr: GraphRoot, pairs: list[list[str]]) -> int {
    nodes: dict[str, GNode] = {};
    for ch in [gr ->:->][?:GNode] {
        if ch.nid not in nodes { nodes[ch.nid] = ch; }
    }
    added: int = 0;
    for pair in pairs {
        s = pair[0];
        t = pair[1];
        if s not in nodes {
            sn = GNode(nid=s);
            nodes[s] = sn;
            gr ++> sn;
        }
        if t not in nodes {
            tn = GNode(nid=t);
            nodes[t] = tn;
            gr ++> tn;
        }
        nodes[s] +>:Refer:+> nodes[t];
        added += 1;
    }
    gr.revision += 1;
    return added;
}

def get_incident_edges(gr: GraphRoot, node_id: str) -> list[str] {
    gr.query_count += 1;
    nd = find_node_under(gr, node_id);
    if nd is None { return []; }
    w = nd spawn IncidentPeek;
    out: list[str] = [];
    for x in w.incoming { out.append(x); }
    return sorted(out);
}

def query_count(gr: GraphRoot) -> int {
