def blast_radius_bulk(gr: GraphRoot, start_nid: str, max_depth: int) -> list[str] {
    nd = find_node_under(gr, start_nid);
    if nd is None { return []; }
    w = nd spawn BulkReach(max_depth=max_depth);
    print {"blast_radius_bulk": len(w.found)};
    return sorted(w.found);
}

def blast_radius_queries(gr: GraphRoot, start_nid: str, max_depth: int) -> list[str] {
    nd = find_node_under(gr, start_nid);
    if nd is None { return []; }
    w = nd spawn QueryReach(gr=gr, max_depth=max_depth);
    print {"blast_radius_queries": len(w.found), "queries": gr.query_count};
    return sorted(w.found);
}

