    for lk in links {
        sid = lk["src"];
        did = lk["dst"];
        if sid in nodes and did in nodes {
            nodes[sid] +>:Flow:+> nodes[did];
        }
    }
    sim: dict = {};
    sim["nodes"] = nodes;
    sim["roots"] = roots;
    sim["max_steps"] = max_steps;
    return sim;
