            claimed=claimed_all,
            trace_ids=[],
            trace_vals={},
            steps=0,
            max_steps=cap,
            seed_amount=amount,
            halted=False,
        );
        for tid in w.trace_ids {
            merged_ids.append(tid);
            merged_vals[tid] = w.trace_vals[tid];
        }
        total += w.steps;
        if w.halted {
