# PROGRAM iss_aaronwesthoff84__SAP-IM-Config-Explorer__119.jac
"""Compensation rule simulator OSP lift.
Provenance: aaronwesthoff84/SAP-IM-Config-Explorer#119
"""

glob STAGE_ORDER: list[str] = [
    "Credit",
    "Primary Measurement",
    "Secondary Measurement",
    "Incentive",
    "Deposit",
];

node RuleNode {
    has node_id: str;
    has stage: str;
    has expr: str = "";
    has value: float = 0.0;
    has rate: float = 0.1;
}

edge Flow {}

walker Propagate {
    has claimed: dict[str, bool] = {};
    has trace_ids: list[str] = [];
    has trace_vals: dict[str, float] = {};
    has steps: int = 0;
    has max_steps: int = 1000;
    has seed_amount: float = 0.0;
    has halted: bool = False;

    can step with RuleNode entry {
        if here.node_id in self.claimed { skip; }
        if self.steps >= self.max_steps {
            self.halted = True;
            disengage;
        }
        self.claimed[here.node_id] = True;
        self.steps += 1;
        outv = eval_stage(here, self.seed_amount);
        here.value = outv;
        self.trace_vals[here.node_id] = outv;
        self.trace_ids.append(here.node_id);
        print("propagate", here.node_id, here.stage, outv);
        kids: list[RuleNode] = [];
        for ch in [here ->:Flow:->][?:RuleNode] {
            kids.append(ch);
        }
        kids = stage_sort(kids);
        if kids {
            visit :0: kids;
        } else {
            disengage;
        }
    }
}

walker CycleProbe {
    has claimed: dict[str, bool] = {};
    has cyclic: bool = False;

    can probe with RuleNode entry {
        if here.node_id in self.claimed {
            self.cyclic = True;
            skip;
        }
        self.claimed[here.node_id] = True;
        print("cycle_probe", here.node_id);
        kids: list[RuleNode] = [];
        for ch in [here ->:Flow:->][?:RuleNode] {
            kids.append(ch);
        }
        if kids {
            visit kids;
        } else {
            disengage;
        }
    }
}

def stage_rank(stage: str) -> int {
    i = 0;
    for s in STAGE_ORDER {
        if s == stage {
            return i;
        }
        i += 1;
    }
    return 99;
}

def stage_sort(nodes: list[RuleNode]) -> list[RuleNode] {
    out: list[RuleNode] = [];
    for nd in nodes {
        out.append(nd);
    }
    i = 0;
    while i < len(out) {
        j = i + 1;
        while j < len(out) {
            if stage_rank(out[i].stage) > stage_rank(out[j].stage) {
                tmp = out[i];
                out[i] = out[j];
                out[j] = tmp;
            }
            j += 1;
        }
        i += 1;
    }
    return out;
}

def eval_stage(node: RuleNode, seed: float) -> float {
    if node.stage == "Credit" {
        return seed;
    }
    if node.stage == "Incentive" {
        base: float = 0.0;
        for p in [node <-:Flow:<-][?:RuleNode] {
            base += p.value;
        }
        return base * node.rate;
    }
    agg: float = 0.0;
    for p in [node <-:Flow:<-][?:RuleNode] {
        agg += p.value;
    }
    if agg == 0.0 {
        return seed;
    }
    return agg;
}

def build_simulator(
    specs: list[dict[str, str]],
    links: list[dict[str, str]],
    max_steps: int = 1000,
) -> dict[str, RuleNode | list[RuleNode] | int | dict[str, RuleNode]] {
    nodes: dict[str, RuleNode] = {};
    roots: list[RuleNode] = [];
    for sp in specs {
        nd = RuleNode(node_id=sp["node_id"], stage=sp["stage"]);
        if sp["stage"] == "Incentive" {
            nd.rate = 0.15;
        }
        nodes[sp["node_id"]] = nd;
        root ++> nd;
        if sp["stage"] == "Credit" {
            roots.append(nd);
        }
    }
    for lk in links {
        sid = lk["src"];
        did = lk["dst"];
        if sid in nodes and did in nodes {
            nodes[sid] +>:Flow:+> nodes[did];
        }
    }
    sim: dict[str, RuleNode | list[RuleNode] | int | dict[str, RuleNode]] = {};
    sim["nodes"] = nodes;
    sim["roots"] = roots;
    sim["max_steps"] = max_steps;
    return sim;
}

def run_simulation(
    sim: dict[str, RuleNode | list[RuleNode] | int | dict[str, RuleNode]],
    event_type: str,
    amount: float,
) -> dict[str, str | float | int | bool | list[str] | dict[str, float]] {
    roots = sim["roots"] as list[RuleNode];
    cap = sim["max_steps"] as int;
    merged_ids: list[str] = [];
    merged_vals: dict[str, float] = {};
    claimed_all: dict[str, bool] = {};
    total = 0;
    halted = False;
    for rt in roots {
        w = rt spawn Propagate(
            claimed=claimed_all,
            trace_ids=[],
            trace_vals={},
            steps=0,
            max_steps=cap,
            seed_amount=amount,
            halted=False,
        );
        for tid in w.trace_ids {
            merged_ids.append(tid);
            merged_vals[tid] = w.trace_vals[tid];
        }
        total += w.steps;
        if w.halted {
            halted = True;
        }
        for tid2 in w.trace_ids {
            claimed_all[tid2] = True;
        }
    }
    tr: dict[str, str | float | int | bool | list[str] | dict[str, float]] = {};
    tr["event_type"] = event_type;
    tr["amount"] = amount;
    tr["node_ids"] = merged_ids;
    tr["values"] = merged_vals;
    tr["steps"] = total;
    tr["halted"] = halted;
    return tr;
}

def trace_node_ids(
    trace: dict[str, str | float | int | bool | list[str] | dict[str, float]],
) -> list[str] {
    return trace["node_ids"] as list[str];
}

def trace_get_value(
    trace: dict[str, str | float | int | bool | list[str] | dict[str, float]],
    node_id: str,
) -> float | None {
    vals = trace["values"] as dict[str, float];
    if node_id in vals {
        return vals[node_id];
    }
    return None;
}

def lookup_node_value(
    sim: dict[str, RuleNode | list[RuleNode] | int | dict[str, RuleNode]],
    node_id: str,
) -> float | None {
    nodes = sim["nodes"] as dict[str, RuleNode];
    if node_id in nodes {
        return nodes[node_id].value;
    }
    return None;
}

def simulator_has_cycle(
    sim: dict[str, RuleNode | list[RuleNode] | int | dict[str, RuleNode]],
) -> bool {
    roots = sim["roots"] as list[RuleNode];
    for rt in roots {
        w = rt spawn CycleProbe(claimed={}, cyclic=False);
        if w.cyclic {
            return True;
        }
    }
    return False;
}
