        self.groups[gid] = g;
        root ++> g;
        return g;
    }

    def add_child(parent_id: str, child_id: str) -> None {
        if parent_id not in self.groups {
            return;
        }
        if child_id not in self.groups {
            return;
        }
        p = self.groups[parent_id];
        c = self.groups[child_id];
        p +>:Child:+> c;
    }

    def has_path_down(from_id: str, to_id: str, max_depth: int = 10) -> bool {
        if from_id not in self.groups {
            return False;
        }
        if to_id not in self.groups {
            return False;
        }
        if from_id == to_id {
            return True;
        }
        start = self.groups[from_id];
        w = start spawn PathDownW(
            target=to_id,
            max_depth=max_depth,
            claimed={}
        );
        return w.found;
    }

    def get_effective_groups(
        membership_ids: list[str],
        max_depth: int = 10
    ) -> list[str] {
        collected: dict[str, bool] = {};
        for mid in membership_ids {
            if mid not in self.groups {
                continue;
            }
            g = self.groups[mid];
            w = g spawn AncestorW(
                max_depth=max_depth,
                collected=collected,
                claimed={}
            );
        }
        out: list[str] = [];
        for gid in collected {
            out.append(gid);
        }
        out = sorted(out);
        return out;
    }
}

walker PathDownW {
    has target: str;
    has max_depth: int;
    has found: bool = False;
    has claimed: dict[str, bool] = {};
    has cur_depth: int = 0;

    can descend with Group entry {
        if self.found {
            disengage;
        }
        if here.gid in self.claimed {
            skip;
        }
        self.claimed[here.gid] = True;
        print("path_down visit ", here.gid, " depth=", self.cur_depth);
        if here.gid == self.target {
            self.found = True;
            disengage;
        }
        if self.cur_depth >= self.max_depth {
            disengage;
        }
        kids: list[Group] = [here ->:Child:->][?:Group];
        next_kids: list[Group] = [];
        for kid in kids {
            if kid.gid not in self.claimed {
                next_kids.append(kid);
            }
        }
        if len(next_kids) > 0 {
            for kid in next_kids {
                self.cur_depth += 1;
                visit :0: [kid];
                self.cur_depth -= 1;
                if self.found {
                    disengage;
                }
            }
        } else {
            disengage;
        }
    }
}

walker AncestorW {
    has max_depth: int;
    has collected: dict[str, bool];
    has claimed: dict[str, bool] = {};
    has cur_depth: int = 0;

    can climb with Group entry {
        if here.gid in self.claimed {
            skip;
        }
        self.claimed[here.gid] = True;
        self.collected[here.gid] = True;
        print("ancestor visit ", here.gid, " depth=", self.cur_depth);
        if self.cur_depth >= self.max_depth {
            disengage;
        }
        parents: list[Group] = [here <-:Child:<-][?:Group];
        next_parents: list[Group] = [];
        for p in parents {
            if p.gid not in self.claimed {
                next_parents.append(p);
            }
        }
        if len(next_parents) > 0 {
            for p in next_parents {
                self.cur_depth += 1;
                visit :0: [p];
                self.cur_depth -= 1;
            }
        } else {
            disengage;
        }
    }
}

