obj GraphStore {
    has nodes: dict[str, GNode] = {};
    has seeded: bool = False;

    def add_node(self, nid: str) -> bool {
        if nid in self.nodes {
            return False;
        }
        nd = GNode(nid=nid);
        self.nodes[nid] = nd;
        if not self.seeded {
            root ++> nd;
            self.seeded = True;
        }
        return True;
    }

    def add_edge(self, a: str, b: str) -> bool {
        if a not in self.nodes or b not in self.nodes {
            return False;
        }
        na = self.nodes[a] as GNode;
        nb = self.nodes[b] as GNode;
        na +>:GEdge:+> nb;
        nb +>:GEdge:+> na;
        return True;
    }
}

