def _uniq_sorted(a: list[str], b: list[str]) -> list[str] {
    bag: dict[str, bool] = {};
    out: list[str] = [];
    i: int = 0;
    while i < len(a) {
        bag[a[i]] = True;
        i += 1;
    }
    j: int = 0;
    while j < len(b) {
        bag[b[j]] = True;
        j += 1;
    }
    for k in bag {
