def _one_hop_fwd(g: GraphHandle, start: str, pred: str) -> list[str] {
    if start not in g.by_id {
        return [];
    }
    here = g.by_id[start];
    hits: list[str] = [];
    for e in [here ->:Triple:->] {
        t: Triple = e;
        if t.pred != pred {
