def path_targets(g: GraphHandle, start: str, spec: dict) -> list[str] {
    if start not in g.by_id {
        return [];
    }
    op: str = spec["op"];
    if op == "edge" {
        return _one_hop_fwd(g, start, spec["pred"]);
    }
    if op == "inv" {
        inner = spec["inner"] as dict;
        if inner["op"] != "edge" {
            return [];
        }
        return _one_hop_inv(g, start, inner["pred"]);
    }
    if op == "alt" {
        left = spec["left"] as dict;
        right = spec["right"] as dict;
        return _uniq_sorted(path_targets(g, start, left), path_targets(g, start, right));
    }
    if op == "seq" {
        left = spec["left"] as dict;
        right = spec["right"] as dict;
        mids = path_targets(g, start, left);
        acc: list[str] = [];
        for m in mids {
            acc = _uniq_sorted(acc, path_targets(g, m, right));
        }
        return acc;
    }
    if op == "star" {
        inner = spec["inner"] as dict;
        return _uniq_sorted([start], _plus_targets(g, start, inner));
    }
    if op == "plus" {
        inner = spec["inner"] as dict;
        return _plus_targets(g, start, inner);
    }
    if op == "opt" {
        inner = spec["inner"] as dict;
        return _uniq_sorted([start], path_targets(g, start, inner));
    }
    if op == "neg" {
        preds = spec["preds"] as list[str];
        return _neg_hop(g, start, preds);
    }
    return [];
}

