def make_syllabus -> Topic {
    fnd = Topic(cid="fnd", name="Foundations");
    fnd.done = True;
    arr_i = Topic(cid="arr_i", name="Array traversal");
    arr_i.done = True;
    arr_s = Topic(cid="arr_s", name="Sorting fundamentals");
    prefix = Topic(cid="prefix", name="Prefix Sum");
    str_b = Topic(cid="str_b", name="String basics");
    cyc_a = Topic(cid="cyc_a", name="Cycle A");
    cyc_b = Topic(cid="cyc_b", name="Cycle B");
    cyc_c = Topic(cid="cyc_c", name="Cycle C");
    fnd +>:SyllabusNext:+> arr_i;
    fnd +>:SyllabusNext:+> arr_s;
    arr_i +>:SyllabusNext:+> prefix;
    arr_s +>:SyllabusNext:+> prefix;
    prefix +>:SyllabusNext:+> str_b;
    arr_i +>:Requires:+> fnd;
    prefix +>:Requires:+> arr_i;
    str_b +>:Requires:+> prefix;
    cyc_a +>:Requires:+> cyc_b;
    cyc_b +>:Requires:+> cyc_c;
    cyc_c +>:Requires:+> cyc_a;
    fnd +>:SyllabusNext:+> cyc_a;
    return fnd;
}

def set_done(graph_root: Topic, tid: str) -> bool {
    nd = _find_topic(graph_root, tid);
    if nd {
