    return w.order;
}

def has_requires_cycle(graph_root: Topic) -> bool {
    w = graph_root spawn CycleProbe(on_stack={}, claimed={});
    return w.found_cycle;
}

def progress(graph_root: Topic) -> list[int] {
    w = graph_root spawn CountAll(claimed={});
    out: list[int] = [];
    out.append(w.done_n);
    out.append(w.total_n);
    return out;
