        if t.pred != pred {
            continue;
        }
        srcs: list[Resource] = [here <-:t:<-][?:Resource];
        for src in srcs {
            hits.append(src.cid);
        }
    }
    return sorted(hits);
}

def _neg_hop(g: GraphHandle, start: str, preds: list[str]) -> list[str] {
    if start not in g.by_id {
        return [];
    }
    blocked: dict[str, bool] = {};
    for p in preds {
        blocked[p] = True;
    }
    here = g.by_id[start];
    hits: list[str] = [];
    for e in [here ->:Triple:->] {
        t: Triple = e;
        if t.pred in blocked {
            continue;
        }
        nbrs: list[Resource] = [here ->:t:->][?:Resource];
        for ch in nbrs {
            hits.append(ch.cid);
        }
    }
    return sorted(hits);
}

def _plus_targets(g: GraphHandle, start: str, inner: dict[str, object]) -> list[str] {
    if start not in g.by_id {
        return [];
    }
    nd = g.by_id[start];
    w = nd spawn PlusWalk(claimed={}, found={}, gref=g, inner=inner, origin=start);
    out: list[str] = [];
    for k in w.found {
        out.append(k);
    }
    return sorted(out);
}

def path_targets(g: GraphHandle, start: str, spec: dict[str, object]) -> list[str] {
    if start not in g.by_id {
        return [];
    }
    op: str = spec["op"] as str;
    if op == "edge" {
        return _one_hop_fwd(g, start, spec["pred"] as str);
    }
    if op == "inv" {
        inner = spec["inner"] as dict[str, object];
        if inner["op"] as str != "edge" {
            return [];
        }
        return _one_hop_inv(g, start, inner["pred"] as str);
    }
    if op == "alt" {
        left = spec["left"] as dict[str, object];
        right = spec["right"] as dict[str, object];
        return _uniq_sorted(path_targets(g, start, left), path_targets(g, start, right));
    }
    if op == "seq" {
        left = spec["left"] as dict[str, object];
        right = spec["right"] as dict[str, object];
        mids = path_targets(g, start, left);
        acc: list[str] = [];
        for m in mids {
            acc = _uniq_sorted(acc, path_targets(g, m, right));
        }
        return acc;
    }
    if op == "star" {
        inner = spec["inner"] as dict[str, object];
        seed: list[str] = [start];
        more = _plus_targets(g, start, inner);
        return _uniq_sorted(seed, more);
    }
    if op == "plus" {
        inner = spec["inner"] as dict[str, object];
        return _plus_targets(g, start, inner);
    }
    if op == "opt" {
        inner = spec["inner"] as dict[str, object];
        seed: list[str] = [start];
        one = path_targets(g, start, inner);
        return _uniq_sorted(seed, one);
    }
    if op == "neg" {
        preds = spec["preds"] as list[str];
        return _neg_hop(g, start, preds);
    }
    return [];
}
