            preds: list[Task] = [<-:Dep:<-][?:Task];
            for p in preds {
                visit :0: [p];
            }
            self.active[here.tid] = False;
            self.done[here.tid] = True;
            self.post.append(here.tid);
            print("topo_post", here.tid);
        }
    }
}

def new_store -> PlanStore {
    rt = Task(tid="__root__");
    return PlanStore(graph_root=rt);
}

def ensure_node(st: PlanStore, tid: str) -> Task {
    if tid in st.nodes {
        return st.nodes[tid];
    }
    nd = Task(tid=tid);
    st.graph_root ++> nd;
    st.nodes[tid] = nd;
    return nd;
}

def compute_topo(st: PlanStore) -> list[str] | None {
    done_map: dict[str, bool] = {};
    active_map: dict[str, bool] = {};
    w = st.graph_root spawn TopoWalker(done=done_map, active=active_map, post=[], cyclic=False);
    if w.cyclic {
        return None;
    }
    return w.post;
}

def from_tasks(recs: list[TaskRec]) -> PlanStore | None {
    st = new_store();
    for r in recs {
        ensure_node(st, r.tid);
    }
    for r in recs {
        for d in r.deps {
            if d in st.nodes {
                st.nodes[d] +>:Dep:+> st.nodes[r.tid];
            }
        }
    }
    ord: list[str] | None = compute_topo(st);
    if ord is None {
        return None;
    }
    st.cached_order = ord;
    st.origin = "from_tasks";
    return st;
}

def create_with_raw_edges(nids: list[str], pairs: list[list[str]]) -> PlanStore {
    st = new_store();
    ins: list[str] = [];
    for nid in nids {
        ensure_node(st, nid);
        ins.append(nid);
    }
    for pr in pairs {
        a = pr[0];
        b = pr[1];
        if (a in st.nodes) and (b in st.nodes) {
            st.nodes[a] +>:Dep:+> st.nodes[b];
        }
    }
    st.cached_order = ins;
    st.origin = "raw";
    return st;
}

def build_sub_graph(recs: list[TaskRec], nids: list[str], pairs: list[list[str]]) -> PlanStore | None {
    validated = from_tasks(recs);
    if validated is None {
        return None;
    }
    return create_with_raw_edges(nids, pairs);
}

def build_sub_graph_fixed(recs: list[TaskRec]) -> PlanStore | None {
    return from_tasks(recs);
}

def get_task_order(st: PlanStore) -> list[str] {
    return st.cached_order;
}

def topo_sort(st: PlanStore) -> list[str] {
    ord: list[str] | None = compute_topo(st);
    if ord is None {
        return [];
    }
    return ord;
