"""jOOQ/jOOQ#12961 — recursive directory paths without dynamic recursive CTE."""

node Directory {
    has cid: str;
    has label: str;
}

edge ParentOf {}

walker Trace {
    has msg: str = "";
    can ping with Directory entry {
        print(self.msg);
        disengage;
    }
}

walker PathWalker {
    has claimed: dict[str, bool] = {};
    has prefix: str = "";
    has rows: list[tuple[str, str, str]] = [];

    can step with Directory entry {
        tr: Trace = root spawn Trace(msg=here.cid);
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        cur: str = here.label;
        if self.prefix != "" {
            cur = self.prefix + "\\" + here.label;
        }
        print(cur);
        self.rows.append((here.cid, here.label, cur));
        kids: list[Directory] = [here ->:ParentOf:->][?:Directory];
        kids_sorted: list[Directory] = [];
        for kid in kids {
            placed = False;
            for i in range(len(kids_sorted)) {
                if kid.cid < kids_sorted[i].cid {
                    kids_sorted.insert(i, kid);
                    placed = True;
                    break;
                }
            }
            if not placed {
                kids_sorted.append(kid);
            }
        }
        for kid in kids_sorted {
            sub: PathWalker = kid spawn PathWalker(
                claimed=self.claimed,
                prefix=cur,
            );
            for subrow in sub.rows {
                self.rows.append(subrow);
            }
        }
        disengage;
    }
}

def build_label_map(
    records: list[dict[str, str | None]],
) -> dict[str, str] {
    out: dict[str, str] = {};
    for row in records {
        rid = str(row["id"]);
        out[rid] = str(row["label"]);
    }
    return out;
}

def build_children_map(
    records: list[dict[str, str | None]],
) -> dict[str, list[str]] {
    seen: dict[str, bool] = {};
    children: dict[str, list[str]] = {};
    for row in records {
        rid = str(row["id"]);
        seen[rid] = True;
        if rid not in children {
            children[rid] = [];
        }
    }
    for row in records {
        rid = str(row["id"]);
        pid = row["parent_id"];
        if pid is not None {
            p = str(pid);
            if p in seen {
                if p not in children {
                    children[p] = [];
                }
                children[p].append(rid);
            }
        }
    }
    keys: list[str] = [];
    for k in children {
        keys.append(k);
    }
    keys = sorted(keys);
    out: dict[str, list[str]] = {};
    for k in keys {
        out[k] = sorted(children[k]);
    }
    return out;
}

def seed_directories(
    records: list[dict[str, str | None]],
) -> list[Directory] {
    by_id: dict[str, Directory] = {};
    roots: list[Directory] = [];
    for row in records {
        cid = str(row["id"]);
        nd = Directory(cid=cid, label=str(row["label"]));
        by_id[cid] = nd;
        root ++> nd;
    }
    for row in records {
        cid = str(row["id"]);
        pid = row["parent_id"];
        if pid is not None {
            p = str(pid);
            if p in by_id and cid in by_id {
                by_id[p] +>:ParentOf:+> by_id[cid];
            }
        }
    }
    for row in records {
        if row["parent_id"] is None {
            roots.append(by_id[str(row["id"])]);
        }
    }
    roots_sorted: list[Directory] = [];
    for nd in roots {
        placed = False;
        for i in range(len(roots_sorted)) {
            if nd.cid < roots_sorted[i].cid {
                roots_sorted.insert(i, nd);
                placed = True;
                break;
            }
        }
        if not placed {
            roots_sorted.append(nd);
        }
    }
    return roots_sorted;
}

def recursive_directory_paths(
    records: list[dict[str, str | None]],
) -> list[tuple[str, str, str]] {
    roots = seed_directories(records);
    claimed: dict[str, bool] = {};
    all_rows: list[tuple[str, str, str]] = [];
    for rt in roots {
        wk: PathWalker = rt spawn PathWalker(claimed=claimed, prefix="");
        for row in wk.rows {
            all_rows.append(row);
        }
    }
    sorted_rows: list[tuple[str, str, str]] = [];
    for row in all_rows {
        placed = False;
        for i in range(len(sorted_rows)) {
            if row[0] < sorted_rows[i][0] {
                sorted_rows.insert(i, row);
                placed = True;
                break;
            }
        }
        if not placed {
            sorted_rows.append(row);
        }
    }
    return sorted_rows;
}
