def build_graph_with_parent(schemas: dict, schema_id: str, new_parent: str) -> dict[str, Schema] {
  nodes: dict[str, Schema] = {};
  for sid in sorted(schemas.keys()) {
    info = schemas[sid] as dict;
    flds: list[str] = info["fields"] as list[str];
    nd = Schema(sid=sid, fields=flds);
    nodes[sid] = nd;
    root ++> nd;
  }
  for sid in sorted(schemas.keys()) {
    par = None;
    if sid == schema_id {
      par = new_parent;
    } else {
      info = schemas[sid] as dict;
      par = info["extends"];
    }
    if par != None {
      pid = par as str;
      if pid in nodes {
        nodes[sid] +>:Extends:+> nodes[pid];
      }
    }
  }
