      info = schemas[sid] as dict;
      par = info["extends"];
    }
    if par is not None {
      pid = par as str;
      if pid in nodes {
        nodes[sid] +>:Extends:+> nodes[pid];
      }
    }
  }
  return nodes;
}

def resolve_effective_fields(schemas: dict[str, dict], schema_id: str) -> list[str] {
  if schema_id not in schemas {
    return [];
  }
  nodes = build_graph(schemas);
  nd = nodes[schema_id];
  w = nd spawn FieldCollectWalker(claimed={});
  seen: dict[str, bool] = {};
  uniq: list[str] = [];
  for f in w.acc {
    if f not in seen {
      seen[f] = True;
      uniq.append(f);
    }
  }
  return sorted(uniq);
}

def would_create_extends_cycle(schemas: dict[str, dict], schema_id: str, new_parent: str) -> bool {
  if schema_id == new_parent {
    return True;
  }
  if new_parent not in schemas {
    return False;
  }
  nodes = build_graph_with_parent(schemas, schema_id, new_parent);
  if schema_id not in nodes {
    return False;
  }
  nd = nodes[new_parent];
  w = nd spawn CycleProbeWalker(claimed={}, target=schema_id);
  return w.found_cycle;
}

def collect_subtype_closure(schemas: dict[str, dict], base_id: str) -> list[str] {
  if base_id not in schemas {
    return [];
  }
  nodes = build_graph(schemas);
  nd = nodes[base_id];
  w = nd spawn SubtypeWalker(claimed={}, base_sid=base_id);
  return sorted(w.acc);
}

def validate_field_set(schemas: dict[str, dict], schema_id: str, own_fields: list[str]) -> bool {
  if schema_id not in schemas {
    return False;
  }
  info = schemas[schema_id] as dict;
  par = info["extends"];
  if par is None {
    return True;
  }
  pid = par as str;
  if pid not in schemas {
    return True;
  }
  inherited = resolve_effective_fields(schemas, pid);
  inh_map: dict[str, bool] = {};
  for f in inherited {
    inh_map[f] = True;
  }
  for f in own_fields {
    if f in inh_map {
      return False;
    }
  }
  return True;
}

