        self.claimed[here.fid] = True;
        nm = here.name;
        prev: float = 0.0;
        if nm in self.totals {
            prev = self.totals[nm];
        }
        self.totals[nm] = prev + here.flat_ms;
        print(here.name);
        kids: list[Frame] = [];
        for ch in [here ->:Call:->][?:Frame] {
            kids.append(ch);
        }
        for kid in kids {
            visit kid;
        }
    }
}

walker CumWalker {
    has claimed: dict[str, bool] = {};
    has totals: dict[str, float] = {};

    can scan_root with ProfileRoot entry {
        print("cum_scan");
        kids: list[Frame] = [];
        for ch in [here ->:Call:->][?:Frame] {
            kids.append(ch);
        }
        for kid in kids {
            visit :0: kid;
        }
    }

    can scan_frame with Frame entry {
        if here.fid in self.claimed {
            skip;
        }
        self.claimed[here.fid] = True;
        kids: list[Frame] = [];
        for ch in [here ->:Call:->][?:Frame] {
            kids.append(ch);
        }
        for kid in kids {
            visit :0: kid;
        }
        child_sum: float = 0.0;
        for kid in kids {
            child_sum = child_sum + kid.cum_ms;
        }
        here.cum_ms = here.flat_ms + child_sum;
        nm = here.name;
        prev: float = 0.0;
        if nm in self.totals {
            prev = self.totals[nm];
        }
        self.totals[nm] = prev + here.cum_ms;
        print(here.name);
    }
}

def new_profile() -> ProfileRoot {
    pr = ProfileRoot(pid="prof");
    return pr;
}

def add_frame(root_node: ProfileRoot, fid: str, name: str, flat_ms: float) -> Frame {
    fr = Frame(fid=fid, name=name, flat_ms=flat_ms);
    root_node ++> fr;
    return fr;
}

def link_by_id(store: dict[str, Frame], parent_fid: str, child_fid: str) -> bool {
    if parent_fid not in store {
        return False;
    }
    if child_fid not in store {
        return False;
    }
    parent = store[parent_fid] as Frame;
    child = store[child_fid] as Frame;
    parent +>:Call:+> child;
    return True;
}

def flat_totals(root_node: ProfileRoot) -> dict[str, float] {
    w = root_node spawn FlatWalker(claimed={}, totals={});
    return w.totals;
}

def cum_totals(root_node: ProfileRoot) -> dict[str, float] {
    w = root_node spawn CumWalker(claimed={}, totals={});
    return w.totals;
}

def top_functions(root_node: ProfileRoot, limit: int, use_cum: bool) -> list[tuple[str, float]] {
    src: dict[str, float] = {};
    if use_cum {
        src = cum_totals(root_node);
    } else {
        src = flat_totals(root_node);
    }
    items: list[tuple[str, float]] = [];
    for nm in src {
        items.append((nm, src[nm]));
    }
    ranked: list[tuple[str, float]] = [];
    used: dict[str, bool] = {};
    i = 0;
    while i < limit {
        best_idx = -1;
        best_val: float = -1.0;
        best_name = "";
        j = 0;
        while j < len(items) {
            cand_name = items[j][0];
            if cand_name in used {
                j += 1;
                continue;
            }
            cand_val = items[j][1];
            if cand_val > best_val {
                best_val = cand_val;
                best_idx = j;
                best_name = cand_name;
            }
            j += 1;
        }
        if best_idx < 0 {
            break;
        }
        ranked.append((best_name, best_val));
        used[best_name] = True;
        i += 1;
    }
    return ranked;
}
