"""djm204/frankenbeast#4363 — sub-graph build: validated from_tasks vs stale depends_on."""

node Task {
    has tid: str;
    has depends_on: list[str] = [];
}

edge Depends {}

node GraphRoot {
    has reason: str = "";
}

walker CycleDetect {
    has claimed: dict[str, bool] = {};
    has stack_set: dict[str, bool] = {};
    has has_cycle: bool = False;

    can walk with Task entry {
        if here.tid in self.claimed {
            if here.tid in self.stack_set {
                self.has_cycle = True;
            }
            skip;
        }
        self.claimed[here.tid] = True;
        self.stack_set[here.tid] = True;
        kids: list[Task] = [];
        for ch in [here ->:Depends:->][?:Task] {
            kids.append(ch);
        }
        print("cycle probe ", here.tid);
        visit :0: kids else { disengage; }
        self.stack_set[here.tid] = False;
    }
}

walker TopoWalk {
    has claimed: dict[str, bool] = {};
    has order: list[str] = [];

    can walk_root with GraphRoot entry {
        kids: list[Task] = [];
        for ch in [here ->] {
            kids.append(ch as Task);
        }
        print("topo root ", here.reason);
        visit :0: kids else { disengage; }
    }

    can walk_task with Task entry {
        if here.tid in self.claimed { skip; }
        self.claimed[here.tid] = True;
        kids: list[Task] = [];
        for ch in [here ->:Depends:->][?:Task] {
            kids.append(ch);
        }
        print("topo visit ", here.tid);
        visit :0: kids else { disengage; }
        self.order.append(here.tid);
    }
}

def _task_keys(task_map: dict) -> list[str] {
    keys: list[str] = [];
    for tid in task_map {
        keys.append(tid);
    }
    return sorted(keys);
}

def _wire_tasks(g: GraphRoot, task_map: dict[str, list[str]], raw_depends: dict[str, list[str]] | None) -> dict[str, Task] {
    nodes: dict[str, Task] = {};
    keys = _task_keys(task_map);
    for tid in keys {
        deps: list[str] = [];
        if raw_depends {
            if tid in raw_depends {
                deps = raw_depends[tid] as list[str];
            }
        }
        t = Task(tid=tid, depends_on=deps);
        nodes[tid] = t;
        g ++> t;
    }
    for tid in keys {
        edge_deps = task_map[tid] as list[str];
        for dep in edge_deps {
            if dep in nodes {
                nodes[tid] +>:Depends:+> nodes[dep];
            }
        }
    }
    return nodes;
}

def _serialize(g: GraphRoot) -> dict {
    nodes_out: dict = {};
    edges_out: dict = {};
    tasks: list[Task] = [];
    for ch in [g ->][?:Task] {
        tasks.append(ch);
    }
    keys: list[str] = [];
    for t in tasks {
        keys.append(t.tid);
    }
    keys = sorted(keys);
    for tid in keys {
        deps: list[str] = [];
        for t in tasks {
            if t.tid == tid {
                for dep_ch in [t ->:Depends:->][?:Task] {
                    deps.append(dep_ch.tid);
                }
                deps = sorted(deps);
                nodes_out[tid] = deps;
                edges_out[tid] = deps;
            }
        }
    }
    out: dict = {"nodes": nodes_out, "edges": edges_out};
    return out;
}

def _detect_cycle(g: GraphRoot) -> bool {
    start: Task | None = None;
    for ch in [g ->][?:Task] {
        start = ch;
        break;
    }
    if not start {
        return False;
    }
    w = start spawn CycleDetect(claimed={}, stack_set={}, has_cycle=False);
    return w.has_cycle;
}

def from_tasks(task_map: dict[str, list[str]], reason: str) -> dict {
    g = GraphRoot(reason=reason);
    root ++> g;
    _wire_tasks(g, task_map, None);
    if _detect_cycle(g) {
        raise Exception("cycle detected");
    }
    for ch in [g ->][?:Task] {
        t = ch;
        deps: list[str] = [];
        for dep_ch in [t ->:Depends:->][?:Task] {
            deps.append(dep_ch.tid);
        }
        t.depends_on = sorted(deps);
    }
    return _serialize(g);
}

def create_with_raw_edges(nodes: dict[str, list[str]], edges: dict[str, list[str]], version: int, reason: str) -> dict {
    g = GraphRoot(reason=reason);
    root ++> g;
    _wire_tasks(g, edges, nodes);
    nodes_out: dict = {};
    edges_out: dict = {};
    keys = _task_keys(nodes);
    for tid in keys {
        nodes_out[tid] = nodes[tid] as list[str];
        if tid in edges {
            edges_out[tid] = edges[tid] as list[str];
        } else {
            edges_out[tid] = [];
        }
    }
    out: dict = {"nodes": nodes_out, "edges": edges_out};
    return out;
}

def build_sub_graph(all_tasks: dict[str, list[str]], completed: list[str]) -> dict {
    done: dict[str, bool] = {};
    for cid in completed {
        done[cid] = True;
    }
    internal: dict[str, list[str]] = {};
    keys = _task_keys(all_tasks);
    for tid in keys {
        if tid in done {
            continue;
        }
        raw = all_tasks[tid] as list[str];
        kept: list[str] = [];
        for dep in raw {
            if dep in done {
                continue;
            }
            if dep in all_tasks {
                kept.append(dep);
            }
        }
        internal[tid] = sorted(kept);
    }
    return from_tasks(internal, "recursive expansion");
}

def get_dependencies(graph: dict, task_id: str) -> list[str] {
    edges = graph["edges"] as dict;
    if task_id in edges {
        deps = edges[task_id] as list[str];
        return sorted(deps);
    }
    return [];
}

def topo_sort(graph: dict) -> list[str] {
    nodes = graph["nodes"] as dict;
    g = GraphRoot(reason="topo");
    root ++> g;
    _wire_tasks(g, nodes, None);
    tw = g spawn TopoWalk(claimed={}, order=[]);
    return tw.order;
}

