```jac
"""Environmental recursive crafting — blushiemagic/MagicStorage#266."""

node Material {
    has mid: str;
    has is_env: bool = False;
}

node Recipe {
    has output: str;
}

edge Needs {
    has qty: int = 1;
}

node CraftStore {}

def merge_counts(base: dict[str, int], add: dict[str, int], mult: int) -> dict[str, int] {
    out: dict[str, int] = {};
    for k in base {
        out[k] = base[k];
    }
    for k in add {
        v: int = add[k] * mult;
        if k in out {
            out[k] = out[k] + v;
        } else {
            out[k] = v;
        }
    }
    return out;
}

def ing_qty(recipe_out: str, mat_mid: str) -> int {
    if recipe_out == "part_y" and mat_mid == "shared_ore" {
        return 2;
    }
    if recipe_out == "part_z" and mat_mid == "shared_ore" {
        return 1;
    }
    return 1;
}

walker RecipeProbe {
    has target: str;
    has found: bool = False;

    can scan with CraftStore entry {
        recipes: list[Recipe] = [-->][?:Recipe];
        for rec in recipes {
            if rec.output == self.target {
                self.found = True;
                disengage;
            }
        }
        disengage;
    }
}

def has_recipe_for(st: CraftStore, output: str) -> bool {
    w = st spawn RecipeProbe(target=output);
    return w.found;
}

walker NeedWalker {
    has item: str;
    has depth: int;
    has max_depth: int;
    has inv: dict[str, int];
    has env: dict[str, bool];
    has store: CraftStore;
    has out: dict[str, int] = {};
    has ok: bool = True;
    has claimed: dict[str, bool] = {};

    can begin with CraftStore entry {
        print("NeedWalker resolve ", self.item, " depth=", self.depth);
        if self.depth < self.max_depth {
            recipes: list[Recipe] = [-->][?:Recipe];
            for rec in recipes {
                if rec.output == self.item {
                    visit [rec];
                    disengage;
                }
            }
        }
        mats: list[Material] = [-->][?:Material];
        for mat in mats {
            if mat.mid == self.item {
                visit [mat];
                disengage;
            }
        }
        self.ok = False;
        print("NeedWalker unknown ", self.item);
        disengage;
    }

    can step_recipe with Recipe entry {
        if here.output in self.claimed {
            skip;
        }
        self.claimed[here.output] = True;
        if here.output != self.item {
            disengage;
        }
        ings: list[Material] = [here ->:Needs:->][?:Material];
        for ing in ings {
            q: int = ing_qty(here.output, ing.mid);
            sub = self.store spawn NeedWalker(
                item=ing.mid,
                depth=self.depth + 1,
                max_depth=self.max_depth,
                inv=self.inv,
                env=self.env,
                store=self.store
            );
            if not sub.ok {
                self.ok = False;
                print("NeedWalker ingredient fail ", ing.mid);
                disengage;
            }
            self.out = merge_counts(self.out, sub.out, q);
        }
        print("NeedWalker recipe ok ", here.output);
        disengage;
    }

    can step_mat with Material entry {
        if here.mid in self.claimed {
            skip;
        }
        self.claimed[here.mid] = True;
        if here.mid != self.item {
            disengage;
        }
        if here.is_env {
            if here.mid in self.env and self.env[here.mid] {
                print("NeedWalker env ok ", here.mid);
                disengage;
            }
            self.ok = False;
            print("NeedWalker env missing ", here.mid);
            disengage;
        }
        have: int = 0;
        if here.mid in self.inv {
            have = self.inv[here.mid];
        }
        if have >= 1 {
            self.out[here.mid] = 1;
            print("NeedWalker inv ok ", here.mid);
            disengage;
        }
        if has_recipe_for(self.store, here.mid) {
            if self.depth >= self.max_depth {
                self.ok = False;
                print("NeedWalker depth cap ", here.mid);
                disengage;
            }
            sub = self.store spawn NeedWalker(
                item=here.mid,
                depth=self.depth + 1,
                max_depth=self.max_depth,
                inv=self.inv,
                env=self.env,
                store=self.store
            );
            if not sub.ok {
                self.ok = False;
                print("NeedWalker subcraft fail ", here.mid);
                disengage;
            }
            self.out = merge_counts(self.out, sub.out, 1);
            print("NeedWalker subcraft ok ", here.mid);
            disengage;
        }
        self.out[here.mid] = 1;
        print("NeedWalker base mat ", here.mid);
        disengage;
    }
}

def build_craft_store -> CraftStore {
    st = CraftStore();
    root ++> st;
    env_water = Material(mid="liquid_water", is_env=True);
    bottled = Material(mid="bottled_water", is_env=False);
    stinger = Material(mid="stinger", is_env=False);
    shared = Material(mid="shared_ore", is_env=False);
    part_y = Material(mid="part_y", is_env=False);
    part_z = Material(mid="part_z", is_env=False);
    r_bottle = Recipe(output="bottled_water");
    r_fly = Recipe(output="flymeal");
    r_part_y = Recipe(output="part_y");
    r_part_z = Recipe(output="part_z");
    r_combo = Recipe(output="combo_item");
    st ++> env_water;
    st ++> bottled;
    st ++> stinger;
    st ++> shared;
    st ++> part_y;
    st ++> part_z;
    st ++> r_bottle;
    st ++> r_fly;
    st ++> r_part_y;
    st ++> r_part_z;
    st ++> r_combo;
    r_bottle +>:Needs(qty=1):+> env_water;
    r_fly +>:Needs(qty=1):+> bottled;
    r_fly +>:Needs(qty=1):+> stinger;
    r_part_z +>:Needs(qty=1):+> shared;
    r_part_y +>:Needs(qty=1):+> shared;
    r_combo +>:Needs(qty=1):+> part_z;
    r_combo +>:Needs(qty=1):+> part_y;
    return st;
}

def needs_for(
    st: CraftStore,
    item_id: str,
    recursion_depth: int,
    inventory: dict[str, int],
    environmental: dict[str, bool]
) -> dict[str, int] | None {
    w = st spawn NeedWalker(
        item=item_id,
        depth=0,
        max_depth=recursion_depth,
        inv=inventory,
        env=environmental,
        store=st
    );
    if not w.ok {
        return None;
    }
    return w.out;
}
