    cur: int = seed;
    while cur <= bound {
        rows.append(cur);
        cur += 1;
    }
    return rows;
}

def stage_builder_error(stage_id: str, dep_ids: list[str], has_scan: bool) -> str | None {
    if len(dep_ids) == 0 and not has_scan {
