def coordinator_route(has_recursive: bool, dag_recursive_ok: bool) -> list[str] {
    if has_recursive and not dag_recursive_ok {
        vals: list[int] = recursive_cte_values(1, 5);
        out: list[str] = ["local"];
        for v in vals {
            out.append(str(v));
        }
        return out;
    }
    if has_recursive and dag_recursive_ok {
        vals2: list[int] = recursive_cte_values(1, 5);
        out2: list[str] = ["dag"];
        for v2 in vals2 {
            out2.append(str(v2));
        }
        return out2;
    }
    return ["local"];
}

