    store: dict[str, Stage] = {};
    keys: list[str] = sorted(spec.keys());
    for k in keys {
        st = Stage(sid=k, scan_files=False);
        store[k] = st;
        root ++> st;
    }
    for dst_key in keys {
        dep_list: list[str] = spec[dst_key];
        for dep_key in dep_list {
            if dep_key in store and dst_key in store {
                src_node = store[dep_key] as Stage;
                dst_node = store[dst_key] as Stage;
                src_node +>:Dep:+> dst_node;
            }
        }
    }
    return store;
}

