        vals: list[int] = recursive_cte_values(1, 5);
        out: list[str] = ["local"];
        for v in vals {
            out.append(str(v));
        }
        return out;
    }
    if has_recursive and dag_recursive_ok {
        vals2: list[int] = recursive_cte_values(1, 5);
        out2: list[str] = ["dag"];
        for v2 in vals2 {
            out2.append(str(v2));
        }
        return out2;
    }
    return ["local"];
}

def build_stage_graph(spec: dict[str, list[str]]) -> dict[str, Stage] {
    store: dict[str, Stage] = {};
    keys: list[str] = sorted(spec.keys());
    for k in keys {
        st = Stage(sid=k, scan_files=False);
        store[k] = st;
        root ++> st;
    }
    for dst_key in keys {
        dep_list: list[str] = spec[dst_key];
        for dep_key in dep_list {
            if dep_key in store and dst_key in store {
                src_node = store[dep_key] as Stage;
                dst_node = store[dst_key] as Stage;
                src_node +>:Dep:+> dst_node;
            }
        }
    }
    return store;
}

def closure_stage_ids(root_key: str, spec: dict[str, list[str]]) -> list[str] {
    if root_key not in spec {
        return [];
    }
    store2: dict[str, Stage] = build_stage_graph(spec);
    graph_root = store2[root_key] as Stage;
    w = graph_root spawn StageClosure();
    return w.order;
}
