            if out[j].created_at < out[i].created_at {
                tmp = out[i];
                out[i] = out[j];
                out[j] = tmp;
            }
            j += 1;
        }
        i += 1;
    }
    return out;
}

def sort_by_created(items: list[dict]) -> list[dict] {
    out: list[dict] = [];
    for it in items {
        out.append(it);
    }
    i = 0;
    while i < len(out) {
        j = i + 1;
        while j < len(out) {
            if out[j]["created_at"] < out[i]["created_at"] {
                tmp = out[i];
                out[i] = out[j];
                out[j] = tmp;
            }
            j += 1;
        }
        i += 1;
    }
    for it in out {
        if len(it["replies"]) > 0 {
            it["replies"] = sort_by_created(it["replies"]);
        }
    }
    return out;
}

def build_reply_tree(flat: list[Comment], root_pid: str) -> list[dict] {
    mapped: dict[str, dict] = {};
    for c in flat {
        mapped[c.cid] = comment_to_dict(c);
    }
    tops: list[dict] = [];
    for c in flat {
        d = mapped[c.cid];
        if c.parent_id == root_pid {
            tops.append(d);
        } elif c.parent_id in mapped {
            mapped[c.parent_id]["replies"].append(d);
        }
    }
    return sort_by_created(tops);
