walker GatherReplies {
    has claimed: dict[str, bool] = {};
    has max_depth: int = 10;
    has anchor_id: str;
    has anchor_depth: int = 0;
    has ordered: list[Comment] = [];

    can descend with Comment entry {
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        rel: int = here.depth - self.anchor_depth;
        if here.cid != self.anchor_id and rel <= self.max_depth {
            self.ordered.append(here);
        }
        if rel >= self.max_depth {
            skip;
        }
        kids: list[Comment] = [here ->:Reply:->][?:Comment];
        for ch in kids {
            ch.depth = here.depth + 1;
            visit ch;
        }
        print(len(self.ordered));
    }
}

def build_store(records: list[dict]) -> GraphRoot {
    store = GraphRoot(by_id={});
    for rec in records {
        pid: str = "";
        if "parent_id" in rec {
            pid = rec["parent_id"];
        }
        nd = Comment(
            cid=rec["id"],
