    }
    parent = store.by_id[parent_id];
    w = parent spawn GatherReplies(
        claimed={},
        max_depth=MAX_DEPTH,
        anchor_id=parent.cid,
        anchor_depth=parent.depth
    );
    print(len(w.ordered));
    return build_reply_tree(w.ordered, parent_id);
