def get_by_content_id(store: GraphRoot, content_id: str) -> list[dict] {
    roots: list[Comment] = [];
    for cid in store.by_id {
        c = store.by_id[cid];
        if c.content_id == content_id and c.parent_id == "" {
            roots.append(c);
