def copy_grid(grid: list[list[int]]) -> list[list[int]] {
    out: list[list[int]] = [];
    for row in grid {
        nr: list[int] = [];
        for v in row {
            nr.append(v);
        }
        out.append(nr);
    }
    return out;
}

def solve_backtrack(grid: list[list[int]], store: dict[str, Cell]) -> list[list[int]] | None {
    work: list[list[list[int]]] = [];
    work.append(copy_grid(grid));
    while len(work) > 0 {
        cur = work.pop();
        pos = find_empty(cur);
        if pos is None {
            return cur;
        }
        r: int = pos[0];
        c: int = pos[1];
        cands: list[int] = candidates_for(store, cur, r, c);
        for i in range(len(cands) - 1, -1, -1) {
            d: int = cands[i];
            ng = copy_grid(cur);
            ng[r][c] = d;
            work.append(ng);
        }
    }
    return None;
}

def solve_puzzle(puzzle: str) -> str {
    grid = parse_puzzle(puzzle);
    store = build_cell_graph(grid);
    ans = solve_backtrack(grid, store);
    if ans is None {
        raise ValueError("unsolvable puzzle");
    }
    return format_puzzle(ans);
}

def solve_batch(records: list[tuple[int, str]]) -> list[tuple[int, str]] {
    items: list[tuple[int, str]] = [];
    for rec in records {
        items.append(rec);
    }
    items.sort();
    out: list[tuple[int, str]] = [];
    for rec in items {
        pid: int = rec[0];
        puz: str = rec[1];
        out.append((pid, solve_puzzle(puz)));
    }
    return out;
}
