def sort_stories_by_rank(rows: list[dict[str, any]]) -> list[dict[str, any]] {
  n: int = len(rows);
  if n < 2 {
    return rows;
  }
  out: list[dict[str, any]] = [];
  used: dict[int, bool] = {};
  pick: int = 0;
  while pick < n {
    best_i: int = -1;
    i: int = 0;
    while i < n {
      if i in used {
        i += 1;
        continue;
      }
      if best_i < 0 {
        best_i = i;
      } else {
        a = rows[best_i];
        b = rows[i];
        if b["score"] > a["score"] {
          best_i = i;
        } else {
          if b["score"] == a["score"] {
            b_post: int = b["posted_at"];
            a_post: int = a["posted_at"];
            if b_post > a_post {
              best_i = i;
            }
          }
        }
      }
      i += 1;
    }
    used[best_i] = True;
    out.append(rows[best_i]);
    pick += 1;
  }
  return out;
}

def build_comment_graph(stories: list[dict[str, any]], flat_comments: list[dict[str, any]]) -> bool {
  story_by_id: dict[str, Story] = {};
  comment_by_id: dict[str, Comment] = {};
  for s in stories {
    st = Story(
      sid=s["id"],
      title=s["title"],
      score=s["score"],
      posted_at=s["posted_at"]
    );
    root ++> st;
    story_by_id[s["id"]] = st;
  }
  for row in flat_comments {
    cm = Comment(cid=row["id"], body=row["body"], story_id=row["story_id"]);
    root ++> cm;
    comment_by_id[row["id"]] = cm;
  }
  for row in flat_comments {
    cm = comment_by_id[row["id"]];
    pid = None;
    if "parent_id" in row {
      pid = row["parent_id"];
    }
    if pid is None {
      st = story_by_id[row["story_id"]];
      st +>:OnStory:+> cm;
    } else {
      par = comment_by_id[pid];
      par +>:Reply:+> cm;
    }
  }
  return True;
}

