    return h;
}

def bfs_traverse(h: GraphHandle, start: str) -> list[str] {
    if start not in h.nodes {
        return [];
    }
    w = h.nodes[start] spawn BfsWalker(claimed={});
    return w.order;
}

def dfs_traverse(h: GraphHandle, start: str) -> list[str] {
    if start not in h.nodes {
        return [];
    }
    w = h.nodes[start] spawn DfsWalker(claimed={});
    return w.order;
}

def detect_bfs(h: GraphHandle, start: str) -> dict[str, any] {
    ord: list[str] = bfs_traverse(h, start);
    conf = 0.0;
    if len(ord) > 0 {
        conf = 0.95;
    }
    return {"pattern": "BFS", "order": ord, "confidence": conf};
}

def detect_dfs(h: GraphHandle, start: str) -> dict[str, any] {
    ord: list[str] = dfs_traverse(h, start);
    conf = 0.0;
    if len(ord) > 0 {
        conf = 0.9;
    }
    return {"pattern": "DFS", "order": ord, "confidence": conf};
}

def arbitrate_suppression(dp_conf: float, dfs_conf: float) -> str {
    if dp_conf > 0.8 {
        return "DP";
    }
    if dfs_conf > 0.8 {
        return "DFS";
    }
    return "NONE";
}
