"""kryonix/kryonix.github.io#8 — recursive peer-closure lift (manual recursive CTE)."""

node Cell {
    has cid: str;
    has row: int;
    has col: int;
    has digit: int;
}

edge Peer {}

def cell_id(row: int, col: int) -> str {
    return str(row) + ":" + str(col);
}

def parse_puzzle(text: str) -> list[list[int]] {
    flat: str = "";
    for ch in text {
        if ch != "\n" {
            flat += ch;
        }
    }
    rows: list[list[int]] = [];
    for r in range(9) {
        row: list[int] = [];
        for c in range(9) {
            ch = flat[r * 9 + c];
            if ch == "?" {
                row.append(0);
            } else {
                row.append(int(ch));
            }
        }
        rows.append(row);
    }
    return rows;
}

def format_puzzle(grid: list[list[int]]) -> str {
    parts: list[str] = [];
    for row in grid {
        digits: str = "";
        for d in row {
            digits += str(d);
        }
        parts.append(digits);
    }
    out: str = "";
    for i in range(len(parts)) {
        if i > 0 {
            out += "\n";
        }
        out += parts[i];
    }
    return out;
}

def list_peer_ids(row: int, col: int) -> list[str] {
    seen: dict[str, bool] = {};
    peers: list[str] = [];
    br: int = row - (row % 3);
    bc: int = col - (col % 3);
    for c in range(9) {
        pid: str = cell_id(row, c);
        if pid != cell_id(row, col) and pid not in seen {
            seen[pid] = True;
            peers.append(pid);
        }
    }
    for r in range(9) {
        pid = cell_id(r, col);
        if pid != cell_id(row, col) and pid not in seen {
            seen[pid] = True;
            peers.append(pid);
        }
    }
    for r in range(br, br + 3) {
        for c in range(bc, bc + 3) {
            pid = cell_id(r, c);
            if pid != cell_id(row, col) and pid not in seen {
                seen[pid] = True;
                peers.append(pid);
            }
        }
    }
    peers.sort();
    return peers;
}

def build_cell_graph(grid: list[list[int]]) -> dict[str, Cell] {
    store: dict[str, Cell] = {};
    for r in range(9) {
        for c in range(9) {
            cid: str = cell_id(r, c);
            nd = Cell(cid=cid, row=r, col=c, digit=grid[r][c]);
            root ++> nd;
            store[cid] = nd;
        }
    }
    for r in range(9) {
        for c in range(9) {
            a = store[cell_id(r, c)] as Cell;
            pids: list[str] = list_peer_ids(r, c);
            for pid in pids {
                b = store[pid] as Cell;
                a +>:Peer:+> b;
            }
        }
    }
    return store;
}

walker PeerGather {
    has claimed: dict[str, bool] = {};
    has values: list[int] = [];

    can step with Cell entry {
        print("peer-gather " + here.cid);
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        if here.digit > 0 {
            self.values.append(here.digit);
        }
        kids: list[Cell] = [];
        for ch in [here ->:Peer:->][?:Cell] {
            kids.append(ch);
        }
        if len(kids) > 0 {
            visit :0: kids;
        } else {
            disengage;
        }
    }
}

def recursive_peer_values(store: dict[str, Cell], start_id: str) -> list[int] {
    if start_id not in store {
        return [];
    }
    nd = store[start_id] as Cell;
    w = nd spawn PeerGather(claimed={});
    vals: list[int] = [];
    for v in w.values {
        vals.append(v);
    }
    vals.sort();
    return vals;
}

def sync_store_digits(store: dict[str, Cell], grid: list[list[int]]) {
    for r in range(9) {
        for c in range(9) {
            (store[cell_id(r, c)] as Cell).digit = grid[r][c];
        }
    }
}

def candidates_for(store: dict[str, Cell], grid: list[list[int]], row: int, col: int) -> list[int] {
    if grid[row][col] != 0 {
        return [];
    }
    sync_store_digits(store, grid);
    used: dict[int, bool] = {};
    for v in recursive_peer_values(store, cell_id(row, col)) {
        used[v] = True;
    }
    out: list[int] = [];
    for d in range(1, 10) {
        if d not in used {
            out.append(d);
        }
    }
    return out;
}

def find_empty(grid: list[list[int]]) -> tuple[int, int] | None {
    for r in range(9) {
        for c in range(9) {
            if grid[r][c] == 0 {
                return (r, c);
            }
        }
    }
    return None;
}

def copy_grid(grid: list[list[int]]) -> list[list[int]] {
    out: list[list[int]] = [];
    for row in grid {
        nr: list[int] = [];
        for v in row {
            nr.append(v);
        }
        out.append(nr);
    }
    return out;
}

def solve_backtrack(grid: list[list[int]], store: dict[str, Cell]) -> list[list[int]] | None {
    work: list[list[list[int]]] = [];
    work.append(copy_grid(grid));
    while len(work) > 0 {
        cur = work.pop();
        pos = find_empty(cur);
        if pos is None {
            return cur;
        }
        r: int = pos[0];
        c: int = pos[1];
        cands: list[int] = candidates_for(store, cur, r, c);
        for i in range(len(cands) - 1, -1, -1) {
            d: int = cands[i];
            ng = copy_grid(cur);
            ng[r][c] = d;
            work.append(ng);
        }
    }
    return None;
}

def solve_puzzle(puzzle: str) -> str {
    grid = parse_puzzle(puzzle);
    store = build_cell_graph(grid);
    ans = solve_backtrack(grid, store);
    if ans is None {
        raise ValueError("unsolvable puzzle");
    }
