"""Stellar-split/split-sdk#644 — iterative DFS cycle detection lifted to OSP."""

node Dep {
    has node_id: str;
}

edge Depends {}

obj GraphHandle {
    has nodes: dict[str, Dep] = {};
}

def get_node(g: GraphHandle, node_id: str) -> Dep | None {
    if node_id in g.nodes {
        return g.nodes[node_id];
    }
    return None;
}

def add_node(g: GraphHandle, node_id: str) -> Dep {
    existing = get_node(g, node_id);
    if existing {
        return existing;
    }
    nd = Dep(node_id=node_id);
    root ++> nd;
    g.nodes[node_id] = nd;
    return nd;
}

def add_edge(g: GraphHandle, src_id: str, dst_id: str) -> None {
    src_nd = add_node(g, src_id);
    dst_nd = add_node(g, dst_id);
    src_nd +>:Depends:+> dst_nd;
}

def build_graph(edge_pairs: list[tuple[str, str]]) -> GraphHandle {
    g = GraphHandle();
    for pair in edge_pairs {
        add_edge(g, pair[0], pair[1]);
    }
    return g;
}

walker CycleWalker {
    has path_stack: list[str] = [];
    has finished: dict[str, bool] = {};
    has found: bool = False;

    can step with Dep entry {
        nid = here.node_id;
        for i in range(len(self.path_stack)) {
            if self.path_stack[i] == nid {
                self.found = True;
                print("cycle at ", nid);
                skip;
            }
        }
        if nid in self.finished {
            skip;
        }
        self.path_stack.append(nid);
        kids: list[Dep] = [];
        for ch in [here ->:Depends:->][?:Dep] {
            kids.append(ch);
        }
        if kids {
            visit :0: kids;
        }
        self.path_stack.pop();
        self.finished[nid] = True;
        if not kids {
            disengage;
        }
    }
}

def detect_cycle(g: GraphHandle) -> bool {
    finished: dict[str, bool] = {};
    ids: list[str] = [];
    for k in g.nodes {
        ids.append(k);
    }
    sorted_ids = sorted(ids);
    for nid in sorted_ids {
        if nid not in finished {
            nd = g.nodes[nid];
            w = nd spawn CycleWalker(finished=finished);
            print("scan ", nid, " found=", w.found);
            if w.found {
                return True;
            }
        }
    }
    return False;
}
