def _find_task(qr: QueueRoot, tid: str) -> Task | None {
    for t in [qr ->][?:Task] {
        if t.tid == tid {
            return t;
        }
    }
    return None;
}

def _reachable(start: Task, target_tid: str) -> bool {
    w = start spawn ReachWalker(target=target_tid, claimed={});
    return w.found;
}

