def task_ids(qr: QueueRoot) -> list[str] {
    ids: list[str] = [];
    for t in [qr ->][?:Task] {
        ids.append(t.tid);
    }
    return sorted(ids);
}

def deps_of(qr: QueueRoot, tid: str) -> list[str] {
    t = _find_task(qr, tid);
    if t == None {
        return [];
    }
    ds: list[str] = [];
    ups: list[Task] = [<-:Depends:-< t][?:Task];
    for u in ups {
        ds.append(u.tid);
    }
    return sorted(ds);
}

def would_cycle(qr: QueueRoot, tid: str, deps: list | None = None) -> bool {
    if _find_task(qr, tid) != None {
        return True;
    }
    dep_ids: list[str] = [];
    if deps != None {
        for d in deps {
            dep_ids.append(d);
        }
    }
    for d in dep_ids {
        if _find_task(qr, d) == None {
            return False;
        }
        dn = _find_task(qr, d);
        if dn != None && _reachable(dn, tid) {
            return True;
        }
    }
    return False;
}

def add_task(qr: QueueRoot, tid: str, deps: list | None = None) -> bool {
    if _find_task(qr, tid) != None {
        raise ValueError("duplicate task id");
    }
    dep_ids: list[str] = [];
    if deps != None {
        for d in deps {
            dep_ids.append(d);
        }
    }
    for d in dep_ids {
        if _find_task(qr, d) == None {
            raise ValueError("unknown dependency");
        }
    }
    if would_cycle(qr, tid, dep_ids) {
        raise ValueError("dependency cycle");
    }
    nt = Task(tid=tid);
    qr ++> nt;
    for d in dep_ids {
        dn = _find_task(qr, d);
        if dn != None {
            dn +>:Depends:+> nt;
        }
    }
    return True;
}
