def find_roots(spec: dict[str, list[str]]) -> list[str] {
    all_ids: dict[str, bool] = {};
    for src_key in spec {
        all_ids[src_key] = True;
        tgt_list = spec[src_key] as list[str];
        for tgt_id in tgt_list {
            all_ids[tgt_id] = True;
        }
    }
    incoming: dict[str, int] = {};
    for node_id in all_ids {
        incoming[node_id] = 0;
    }
    for src_key in spec {
        tgt_list = spec[src_key] as list[str];
        for tgt_id in tgt_list {
            incoming[tgt_id] = incoming[tgt_id] + 1;
        }
    }
    roots: list[str] = [];
    for node_id in all_ids {
        if incoming[node_id] == 0 {
            roots.append(node_id);
        }
    }
    roots.sort();
    return roots;
}

def _run_walk(g: DagGraph) -> WalkState {
    st = WalkState();
    for r in g.roots {
        r spawn CycleTopoWalker(st=st);
    }
    return st;
}

def has_cycle(g: DagGraph) -> bool {
    st = _run_walk(g);
    return st.cyclic;
}

def topological_sort(g: DagGraph) -> list[str] | None {
    st = _run_walk(g);
    if st.cyclic {
        return None;
    }
    out: list[str] = [];
    idx = len(st.order) - 1;
    while idx >= 0 {
        out.append(st.order[idx]);
        idx = idx - 1;
    }
    return out;
}

def validate_dag(spec: dict[str, list[str]]) -> tuple[bool, list[str] | None] {
    g = build_graph(spec);
    if has_cycle(g) {
        return (False, None);
    }
    ord = topological_sort(g);
    return (True, ord);
}

