def detect_cycle(g: GraphHandle) -> bool {
    comp_visited: dict[str, bool] = {};
    ids: list[str] = [];
    for k in g.nodes {
        ids.append(k);
    }
    sorted_ids = sorted(ids);
    for nid in sorted_ids {
        if nid not in comp_visited {
            nd = g.nodes[nid];
            w = nd spawn CycleWalker(finished=comp_visited);
            print("scan ", nid, " found=", w.found);
            if w.found {
                return True;
            }
        }
    }
    return False;
}
