def _sort_nodes_by_nid(nodes: list[GNode]) -> list[GNode] {
    let ids: list[str] = [];
    for nd in nodes {
        ids.append(nd.nid);
    }
    ids = sorted(ids);
    let out: list[GNode] = [];
    for sid in ids {
        for nd in nodes {
            if nd.nid == sid {
