def _find_or_create(g: GraphHandle, nid: str) -> GNode {
    if nid in g.nodes {
        return g.nodes[nid];
    }
    let nd = GNode(nid=nid);
    g.graph_root ++> nd;
    g.nodes[nid] = nd;
    return nd;
}

