def pipeline_by_id(store: dict[str, Pipeline], pid: str) -> Pipeline {
    if pid not in store {
        nd = Pipeline(pid=pid);
        root ++> nd;
        store[pid] = nd;
    }
    return store[pid];
}

def wire_control_edges(edges: list[dict]) -> dict[str, Pipeline] {
    store: dict[str, Pipeline] = {};
    for e in edges {
        caller_id: str = e["caller_pipeline"];
        callee_id: str = e["callee_pipeline"];
        caller = pipeline_by_id(store, caller_id);
        callee = pipeline_by_id(store, callee_id);
        act: str = "";
        if "activity_name" in e {
            act = e["activity_name"];
        }
        wait_flag: bool = True;
        if "wait_on_completion" in e {
            wait_flag = e["wait_on_completion"];
        }
        caller +>:ControlCall(activity_name=act, wait_on_completion=wait_flag):+> callee;
    }
    return store;
}

def ensure_pipelines(store: dict[str, Pipeline], pipelines: list[str]) {
    for pid in pipelines {
        pipeline_by_id(store, pid);
    }
}

walker DeployOrderWalker {
    has claimed: dict[str, bool] = {};
    has order: list[str] = [];

    can bootstrap with root entry {
        nodes: list[Pipeline] = [here-->.][?:Pipeline];
        pids: list[str] = [];
        for nd in nodes {
            pids.append(nd.pid);
        }
        pids = sorted(pids);
        for pid in pids {
            for nd in nodes {
                if nd.pid == pid {
                    visit :0: nd;
                }
            }
        }
        print("deploy_bootstrap");
    }

    can step with Pipeline entry {
        if here.pid in self.claimed {
            skip;
        }
        self.claimed[here.pid] = True;
        kids: list[Pipeline] = [here ->:ControlCall:->][?:Pipeline];
        kid_pids: list[str] = [];
        for ch in kids {
            kid_pids.append(ch.pid);
        }
        kid_pids = sorted(kid_pids);
        for kpid in kid_pids {
            for ch in kids {
                if ch.pid == kpid {
                    visit :0: ch;
                }
            }
        }
        self.order.append(here.pid);
        print("deploy", here.pid);
    }
}

walker CalleeClosureWalker {
    has claimed: dict[str, bool] = {};
    has found: list[str] = [];
    has origin: str = "";

    can step with Pipeline entry {
        if here.pid in self.claimed {
            skip;
        }
        self.claimed[here.pid] = True;
        if here.pid != self.origin {
            self.found.append(here.pid);
        }
        kids: list[Pipeline] = [here ->:ControlCall:->][?:Pipeline];
        kid_pids: list[str] = [];
        for ch in kids {
            kid_pids.append(ch.pid);
