def deploy_order(control_edges: list[dict], pipelines: list[str]) -> list[str] {
    store: dict[str, Pipeline] = wire_control_edges(control_edges);
    ensure_pipelines(store, pipelines);
    w = root spawn DeployOrderWalker(claimed={}, order=[]);
    in_walk: dict[str, bool] = {};
    for x in w.order {
        in_walk[x] = True;
    }
    final: list[str] = [];
    orphans: list[str] = [];
    for pid in pipelines {
        if pid not in in_walk {
            orphans.append(pid);
        }
    }
    orphans = sorted(orphans);
    for pid in orphans {
        final.append(pid);
    }
    for x in w.order {
        keep: bool = False;
        for pid in pipelines {
            if pid == x {
                keep = True;
            }
        }
        if keep {
            final.append(x);
        }
    }
    return final;
}

def orchestration_depends_on(control_edges: list[dict], pipelines: list[str]) -> dict[str, list[str]] {
    result: dict[str, list[str]] = {};
    for pid in pipelines {
        result[pid] = [];
    }
    for e in control_edges {
        caller: str = e["caller_pipeline"];
        callee: str = e["callee_pipeline"];
        wait_flag: bool = True;
        if "wait_on_completion" in e {
            wait_flag = e["wait_on_completion"];
        }
        if caller in result and wait_flag {
            result[caller].append(callee);
        }
    }
    for pid in pipelines {
        result[pid] = sorted(result[pid]);
    }
    return result;
}

def callee_closure(control_edges: list[dict], root_pipeline: str) -> list[str] {
    store: dict[str, Pipeline] = wire_control_edges(control_edges);
