}

def create_task(g: TaskGraph, tid: str, title: str) -> dict {
  if tid in g.by_id {
    raise ValueError("duplicate");
  }
  nd = Task(tid=tid, title=title);
  root ++> nd;
  g.by_id[tid] = nd;
  return {"id": tid, "title": title, "archived": False, "done": False};
}

def get_task(g: TaskGraph, tid: str) -> dict | None {
  if tid not in g.by_id {
    return None;
  }
  nd = g.by_id[tid];
  return {"id": nd.tid, "title": nd.title, "archived": nd.archived, "done": nd.done};
}

walker ReachProbe {
  has target: str;
  has hit: bool = False;
  has claimed: dict[str, bool] = {};
  can step with Task entry {
    if here.tid in self.claimed { skip; }
    self.claimed[here.tid] = True;
    if here.tid == self.target {
      self.hit = True;
      disengage;
    }
    nbrs: list[Task] = [here ->:DependsOn:->][?:Task];
    if nbrs { visit nbrs; } else { disengage; }
  }
}

def _reachable(g: TaskGraph, start_id: str, end_id: str) -> bool {
  w = g.by_id[start_id] spawn ReachProbe(target=end_id, claimed={});
  print("reachable", start_id, end_id, w.hit);
  return w.hit;
}

def add_dependency(g: TaskGraph, task_id: str, depends_on_id: str) {
  if task_id not in g.by_id or depends_on_id not in g.by_id {
    raise ValueError("unknown task");
  }
  if _reachable(g, depends_on_id, task_id) {
    raise ValueError("cycle");
  }
  g.by_id[task_id] +>:DependsOn:+> g.by_id[depends_on_id];
}

walker PathFinder {
  has target: str;
  has found: list[str] = [];
  has parent_of: dict[str, str] = {};
  has claimed: dict[str, bool] = {};
  can bfs with Task entry {
    if here.tid in self.claimed { skip; }
    self.claimed[here.tid] = True;
    if here.tid == self.target {
      rev: list[str] = [];
      cur = here.tid;
      rev.append(cur);
      while cur in self.parent_of {
        cur = self.parent_of[cur];
        rev.append(cur);
      }
      self.found = [];
      i = len(rev) - 1;
      while i >= 0 {
        self.found.append(rev[i]);
        i = i - 1;
      }
      disengage;
    }
    nbrs: list[Task] = [here ->:DependsOn:->][?:Task];
    for nb in nbrs {
      if nb.tid not in self.parent_of {
        self.parent_of[nb.tid] = here.tid;
      }
    }
    if nbrs { visit :0: nbrs; } else { disengage; }
  }
}

def find_path(g: TaskGraph, from_id: str, to_id: str) -> list[str] | None {
  if from_id not in g.by_id or to_id not in g.by_id {
    return None;
  }
  w = g.by_id[from_id] spawn PathFinder(target=to_id, claimed={});
  print("find_path", from_id, to_id, w.found);
  if w.found { return w.found; }
  return None;
}

def set_parent(g: TaskGraph, parent_id: str, child_id: str) {
  if parent_id not in g.by_id or child_id not in g.by_id {
    raise ValueError("unknown task");
  }
  g.by_id[parent_id] +>:ChildOf:+> g.by_id[child_id];
