  can step with Task entry {
    if here.tid in self.claimed { skip; }
    self.claimed[here.tid] = True;
    self.collected.append(here.tid);
    kids: list[Task] = [here ->:ChildOf:->][?:Task];
    if kids { visit kids; } else { disengage; }
  }
}

def cascade_delete_ids(g: TaskGraph, root_id: str) -> list[str] {
  if root_id not in g.by_id {
    return [];
