  w = g.by_id[root_id] spawn DescendantCollector(claimed={});
  ids = sorted(w.collected);
  print("cascade_delete_ids", root_id, ids);
  drop: dict[str, bool] = {};
  for tid in ids { drop[tid] = True; }
  new_map: dict[str, Task] = {};
  for k in g.by_id {
    if k not in drop { new_map[k] = g.by_id[k]; }
  }
  g.by_id = new_map;
  return ids;
}

def mark_done(g: TaskGraph, tid: str) {
  if tid not in g.by_id { raise ValueError("unknown task"); }
  g.by_id[tid].done = True;
}

def get_incomplete_blockers(g: TaskGraph, task_id: str) -> list[str] {
  if task_id not in g.by_id { return []; }
  deps: list[Task] = [g.by_id[task_id] ->:DependsOn:->][?:Task];
  out: list[str] = [];
  for dep in deps {
    if not dep.done { out.append(dep.tid); }
  }
  return sorted(out);
}

def list_ready(g: TaskGraph) -> list[str] {
  ready: list[str] = [];
  keys: list[str] = sorted(g.by_id);
  for tid in keys {
    nd = g.by_id[tid];
    if nd.archived or nd.done { continue; }
    if not get_incomplete_blockers(g, tid) { ready.append(tid); }
  }
  return ready;
}

