        dist: int = self.distance[here.vid];
        self.order.append(here.vid);
        raw: list[Vertex] = [];
        for ch in [here ->:Link:->][?:Vertex] {
            raw.append(ch);
        }
        kids: list[Vertex] = sort_vertices_by_vid(raw);
        next_kids: list[Vertex] = [];
        for kid in kids {
            if kid.vid in self.claimed {
                continue;
