    if from_id >= graph.vertex_count or to_id >= graph.vertex_count {
        return;
    }
    a = graph.verts[from_id];
    b = graph.verts[to_id];
    a +>:Link:+> b;
    b +>:Link:+> a;
}

def traverse(graph: Graph, start: int) -> BFSResult {
    if start < 0 or start >= graph.vertex_count {
        empty_order: list[int] = [];
        empty_dist: list[int] = [];
        return BFSResult(order=empty_order, distance=empty_dist);
    }
    src = graph.verts[start];
    dist0: dict[int, int] = {};
    dist0[start] = 0;
    w = src spawn BfsWalk(claimed={}, order=[], distance=dist0, start_vid=start);
    dist_out: list[int] = [];
