  for tid in ids {
    reqs: list[str] = spec[tid];
    if reqs is None {
      reqs = [];
    }
    rid: str = "";
    for rid in reqs {
      if rid in nodes {
        nodes[tid] +>:Requires:+> nodes[rid];
      }
    }
  }
  return nodes;
}

