        fields: list[FieldDef] = [here ->:HasField:->][?:FieldDef];
        for fd in fields {
            if fd.fname not in self.raw {
                continue;
            }
            chunk = self.raw[fd.fname];
            if fd.is_array {
                items = chunk as list[dict[str, object]];
                parsed_items: list[dict[str, object]] = [];
                idx = 0;
                for item in items {
                    sub_path = step_key + "." + fd.fname + "[" + str(idx) + "]";
                    sub_raw = item as dict[str, object];
                    if fd.target in self.type_by_name {
                        sub_td = self.type_by_name[fd.target] as TypeDef;
                        sub_w = sub_td spawn ParseFields(
                            type_name=fd.target,
                            raw=sub_raw,
                            type_by_name=self.type_by_name,
                            path=sub_path,
                        );
                        parsed_items.append(sub_w.out);
                    } else {
                        parsed_items.append(sub_raw);
                    }
                    idx = idx + 1;
                }
                self.out[fd.fname] = parsed_items;
            } else if fd.target in self.type_by_name {
                sub_raw = chunk as dict[str, object];
