def build_type_graph(schema: dict[str, dict[str, str]]) -> TypeDef {
    anchor = JsonStub();
    root ++> anchor;
    type_by_name: dict[str, TypeDef] = {};
    tnames: list[str] = [];
    for tn in schema {
        tnames.append(tn);
    }
    for tn in sorted(tnames) {
        td = TypeDef(name=tn);
        type_by_name[tn] = td;
        anchor +>:Ref:+> td;
    }
    start = type_by_name["BalanceSheet"] as TypeDef;
    w = start spawn WireTypes(schema=schema, type_by_name=type_by_name);
    return w.type_by_name["BalanceSheet"] as TypeDef;
}

def parse_recursive(graph_root: TypeDef, type_name: str, raw: dict[str, object]) -> dict[str, object] {
    type_by_name: dict[str, TypeDef] = {};
    stack: list[TypeDef] = [graph_root];
    while len(stack) > 0 {
        cur = stack.pop();
        if cur.name not in type_by_name {
            type_by_name[cur.name] = cur;
        }
        refs: list[TypeDef] = [cur ->:Ref:->][?:TypeDef];
        for r in refs {
            stack.append(r);
        }
        fields: list[FieldDef] = [cur ->:HasField:->][?:FieldDef];
        for fd in fields {
            refs2: list[TypeDef] = [fd ->:Ref:->][?:TypeDef];
            for r2 in refs2 {
                if r2.name not in type_by_name {
                    type_by_name[r2.name] = r2;
                }
                stack.append(r2);
            }
        }
    }
    if type_name not in type_by_name {
        return {};
    }
    start = type_by_name[type_name] as TypeDef;
    pw = start spawn ParseFields(
        type_name=type_name,
        raw=raw,
        type_by_name=type_by_name,
        path="",
    );
    return pw.out;
}

def extract_balance_sheet(
    schema: dict[str, dict[str, str]],
    payload: dict[str, object],
) -> dict[str, object] {
    graph_root = build_type_graph(schema);
    parsed = parse_recursive(graph_root, "BalanceSheet", payload);
    years: list[object] = [];
    years_u: list[object] = [];
    if "years" in parsed {
        years = parsed["years"] as list[object];
    }
    if "yearsUnstructured" in parsed {
        years_u = parsed["yearsUnstructured"] as list[object];
    }
    return {"years": years, "yearsUnstructured": years_u};
}

