"""Federation read-path graph traversal — gaiaaiagent/koi-processor#10."""

node Entity {
    has eid: str;
    has label: str = "";
}

edge Rel {}

obj GraphStore {
    has graph_root: Entity;
    has by_id: dict[str, Entity] = {};
    has nb_cache: dict[str, list[str]] = {};
}

walker NeighborhoodWalk {
    has claimed: dict[str, bool] = {};
    has hops_seen: dict[str, int] = {};
    has hop_limit: int = 1;
    has cap: int = 100;
    has direction: str = "both";
    has origin: str = "";
    has collected: list[str] = [];

    can traverse with Entity entry {
        if here.eid in self.claimed {
            skip;
        }
        self.claimed[here.eid] = True;
        depth: int = 0;
        if here.eid in self.hops_seen {
            depth = self.hops_seen[here.eid];
        }
        if here.eid != self.origin and len(self.collected) < self.cap {
            self.collected.append(here.eid);
        }
        next_d: int = depth + 1;
        if next_d > self.hop_limit {
            print(["nb_stop", here.eid, depth]);
            disengage;
        }
        nbrs: list[Entity] = [];
        if self.direction == "out" or self.direction == "both" {
            for ch in [here ->:Rel:->][?:Entity] {
                nbrs.append(ch);
            }
        }
        if self.direction == "in" or self.direction == "both" {
            for ch in [<-:Rel:<- here][?:Entity] {
                nbrs.append(ch);
            }
        }
        nxt: list[Entity] = [];
        for nb in nbrs {
            if nb.eid not in self.hops_seen {
                self.hops_seen[nb.eid] = next_d;
            }
            if nb.eid not in self.claimed {
                nxt.append(nb);
            }
        }
        print(["nb_visit", here.eid, len(nxt)]);
        if len(nxt) > 0 {
            visit nxt;
        } else {
            disengage;
        }
    }
}

walker ShortestPathWalk {
    has claimed: dict[str, bool] = {};
    has goal: str = "";
    has direction: str = "both";
    has parent: dict[str, str] = {};
    has hit: bool = False;

    can find with Entity entry {
        if here.eid in self.claimed {
            skip;
        }
        self.claimed[here.eid] = True;
        if here.eid == self.goal {
            self.hit = True;
            print(["sp_hit", here.eid]);
            disengage;
        }
        nbrs: list[Entity] = [];
        if self.direction == "out" or self.direction == "both" {
            for ch in [here ->:Rel:->][?:Entity] {
                nbrs.append(ch);
            }
        }
        if self.direction == "in" or self.direction == "both" {
            for ch in [<-:Rel:<- here][?:Entity] {
                nbrs.append(ch);
            }
        }
        nxt: list[Entity] = [];
        for nb in nbrs {
            if nb.eid not in self.parent {
                self.parent[nb.eid] = here.eid;
            }
            if nb.eid not in self.claimed {
                nxt.append(nb);
            }
        }
        print(["sp_step", here.eid]);
        if len(nxt) > 0 {
            visit nxt;
        } else {
            disengage;
        }
    }
}

def new_store() -> GraphStore {
    root_ent: Entity = Entity(eid="__root__", label="root");
    root ++> root_ent;
    gs: GraphStore = GraphStore(graph_root=root_ent);
    gs.by_id["__root__"] = root_ent;
    return gs;
}

def register_entity(store: GraphStore, eid: str, label: str) -> Entity {
    if eid in store.by_id {
        return store.by_id[eid];
    }
    ent: Entity = Entity(eid=eid, label=label);
    store.graph_root ++> ent;
    store.by_id[eid] = ent;
    return ent;
}

def link_entities(store: GraphStore, out_id: str, in_id: str) -> bool {
    if out_id not in store.by_id {
        return False;
    }
    if in_id not in store.by_id {
        return False;
    }
    a: Entity = store.by_id[out_id];
    b: Entity = store.by_id[in_id];
    a +>:Rel:+> b;
    cleared: dict[str, list[str]] = {};
    store.nb_cache = cleared;
    return True;
}

def reverse_path(start: str, end: str, parent: dict[str, str]) -> list[str] {
    stack: list[str] = [];
    cur: str = end;
    while cur != start {
        stack.append(cur);
        if cur not in parent {
            return [];
        }
        cur = parent[cur];
    }
    stack.append(start);
    out: list[str] = [];
    idx: int = len(stack) - 1;
    while idx >= 0 {
        out.append(stack[idx]);
        idx = idx - 1;
    }
    return out;
}

def neighborhood(store: GraphStore, root_id: str, hops: int, cap: int, direction: str) -> list[str] {
    if root_id not in store.by_id {
        return [];
    }
    ent: Entity = store.by_id[root_id];
    if hops == 1 and direction == "both" and root_id in store.nb_cache {
        cached: list[str] = [];
        for c in store.nb_cache[root_id] {
            cached.append(c);
        }
        return sorted(cached);
    }
    w: NeighborhoodWalk = ent spawn NeighborhoodWalk(
        claimed={},
        hops_seen={},
        hop_limit=hops,
        cap=cap,
        direction=direction,
        origin=root_id,
        collected=[]
    );
    got: list[str] = [];
    for x in w.collected {
        got.append(x);
    }
    got = sorted(got);
    if hops == 1 and direction == "both" {
        store.nb_cache[root_id] = got;
    }
    return got;
}

def shortest_path(store: GraphStore, from_id: str, to_id: str, direction: str) -> list[str] | None {
    if from_id not in store.by_id {
        return None;
    }
    if to_id not in store.by_id {
        return None;
    }
    if from_id == to_id {
        return [from_id];
    }
    src: Entity = store.by_id[from_id];
    w: ShortestPathWalk = src spawn ShortestPathWalk(
        claimed={},
        goal=to_id,
        direction=direction,
        parent={},
        hit=False
    );
    if not w.hit {
        return None;
    }
    return reverse_path(from_id, to_id, w.parent);
}

def neighborhood_page(store: GraphStore, root_id: str, hops: int, cursor: str, page_size: int, direction: str) -> tuple[list[str], str] {
    full: list[str] = neighborhood(store, root_id, hops, 100000, direction);
    start: int = 0;
    if cursor != "" {
        pos: int = 0;
        found: bool = False;
        while pos < len(full) {
            if full[pos] == cursor {
                start = pos + 1;
                found = True;
                break;
            }
            pos = pos + 1;
        }
        if not found {
            return ([], "");
        }
    }
    out: list[str] = [];
    idx: int = start;
    limit: int = start + page_size;
    while idx < len(full) and idx < limit {
        out.append(full[idx]);
        idx = idx + 1;
    }
    nxt: str = "";
    if idx < len(full) {
        nxt = full[idx];
    }
    return (out, nxt);
}
