    for tid in keys {
        nd = Task(tid=tid);
        root ++> nd;
        idx[tid] = nd;
    }
    for tid in keys {
        src = idx[tid] as Task;
        reqs = deps[tid];
        for req in reqs {
            if req in idx {
                tgt = idx[req] as Task;
                src +>:Requires:+> tgt;
            }
        }
    }
    return idx;
}

