def aggregate_s3_machine_time(
    graph_root: Run,
    closure: list[str],
    window_start: str,
    window_end: str,
) -> list[dict] {
    in_closure: dict[str, bool] = {};
    for rid in closure {
        in_closure[rid] = True;
    }
    buckets: dict[str, int] = {};
    for nd in [graph_root ->][?:Run] {
        if nd.run_id not in in_closure {
            continue;
        }
        if nd.pr_create <= window_start or nd.pr_create >= window_end {
            continue;
        }
        key = nd.pr_id + "|" + nd.pr_create;
        if key not in buckets {
            buckets[key] = 0;
        }
        buckets[key] += s3_seconds(nd.job_name, nd.started, nd.completed);
    }
    keys: list[str] = [];
    for k in buckets {
        keys.append(k);
    }
    keys = sorted(keys);
    out: list[dict] = [];
    for key in keys {
        pr = "";
        tm = "";
        parts: list[str] = key.split("|");
        if len(parts) > 0 {
            pr = parts[0];
        }
        if len(parts) > 1 {
            tm = parts[1];
        }
        row: dict = {};
        row["pr"] = pr;
        row["time"] = tm;
        row["s3_machine_time"] = buckets[key];
        out.append(row);
    }
    return out;
}

