def _spec_str(spec: dict, key: str, default: str) -> str {
  if key in spec {
    return spec[key];
  }
  return default;
}

def _find_field(target: str) -> Field | None {
  w = root spawn FindField(target=target);
  return w.hit;
}

def _parent_group_id(parent_ref: str | list) -> str | None {
  if parent_ref is str {
    return parent_ref;
  }
  pr: list = parent_ref;
  if len(pr) < 2 {
    return None;
  }
  return pr[1];
}

