def add_field(form_id: str, spec: dict) -> str {
  fid: str = spec["id"];
  ftype: str = _spec_str(spec, "type", "text");
  nd = Field(
    fid=fid,
    name=_spec_str(spec, "name", ""),
    desc=_spec_str(spec, "desc", ""),
    ftype=ftype
  );
  par = _find_field(form_id);
  if par is not None {
    par +>:ChildOf:+> nd;
  }
  return fid;
}

def add_group_field(form_id: str, parent_ref: str | list, spec: dict) -> str | list {
  pgid: str | None = _parent_group_id(parent_ref);
  if pgid is None {
    return spec["id"];
  }
  parent_nd = _find_field(pgid);
  if parent_nd is None {
    return spec["id"];
  }
  fid: str = spec["id"];
  ftype: str = _spec_str(spec, "type", "group");
  nd = Field(
    fid=fid,
    name=_spec_str(spec, "name", ""),
    desc=_spec_str(spec, "desc", ""),
    ftype=ftype
  );
  parent_nd +>:ChildOf:+> nd;
  if ftype == "group" {
    return [pgid, fid];
  }
  return fid;
}

