def _spec_str(spec: dict[str, any], key: str, default: str) -> str {
  if key in spec {
    return spec[key];
  }
  return default;
}

def _find_field(target: str) -> Field | None {
  w = root spawn FindField(target=target);
  return w.hit;
}

def _parent_group_id(parent_ref: str | list[str]) -> str | None {
  if parent_ref is str {
    return parent_ref;
  }
  pr: list[str] = parent_ref;
  if len(pr) < 2 {
    return None;
  }
  return pr[1];
}

def make_form -> str {
  frm = Field(fid="__form__", ftype="group", name="Form");
  root ++> frm;
  return "__form__";
}

def add_field(form_id: str, spec: dict[str, any]) -> str {
  fid: str = spec["id"];
  ftype: str = _spec_str(spec, "type", "text");
  nd = Field(
    fid=fid,
    name=_spec_str(spec, "name", ""),
    desc=_spec_str(spec, "desc", ""),
    ftype=ftype
  );
  par = _find_field(form_id);
  if par is not None {
    par +>:ChildOf:+> nd;
  }
  return fid;
}

def add_group_field(form_id: str, parent_ref: str | list[str], spec: dict[str, any]) -> str | list[str] {
  if _find_field(form_id) is None {
    return spec["id"];
  }
  pgid: str | None = _parent_group_id(parent_ref);
  if pgid is None {
    return spec["id"];
  }
  parent_nd = _find_field(pgid);
  if parent_nd is None {
    return spec["id"];
  }
  fid: str = spec["id"];
  ftype: str = _spec_str(spec, "type", "group");
  nd = Field(
    fid=fid,
    name=_spec_str(spec, "name", ""),
    desc=_spec_str(spec, "desc", ""),
    ftype=ftype
  );
  parent_nd +>:ChildOf:+> nd;
  if ftype == "group" {
    return [pgid, fid];
  }
  return fid;
}

def list_children(form_id: str, group_id: str) -> list[str] {
  if _find_field(form_id) is None {
    return [];
  }
  grp = _find_field(group_id);
  if grp is None {
    return [];
  }
  kids: list[Field] = [grp ->:ChildOf:->][?:Field];
  ids: list[str] = [];
  for ch in kids {
    ids.append(ch.fid);
  }
  return sorted(ids);
}

def field_registered(form_id: str, group_id: str, field_id: str) -> bool {
  kids: list[str] = list_children(form_id, group_id);
  for cid in kids {
    if cid == field_id {
      return True;
    }
  }
  return False;
}

def subtree_field_ids(form_id: str, group_id: str) -> list[str] {
  if _find_field(form_id) is None {
    return [];
  }
  grp = _find_field(group_id);
  if grp is None {
    return [];
  }
  w = grp spawn CollectSubtree;
  return w.ordered;
}

