walker PositionFinder {
    has target: str = "";
    has found: Position | None = None;
    has claimed: dict[str, bool] = {};

    can boot entry {
        seeds: list[Position] = [];
        for nd in [root ->:RootLink:->][?:Position] {
            seeds.append(nd);
        }
        visit seeds else {
            disengage;
        };
    }

    can seek with Position entry {
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        if here.cid == self.target {
            self.found = here;
            disengage;
        }
        kids: list[Position] = [];
        for ch in [here ->:Move:->][?:Position] {
            kids.append(ch);
        }
        visit kids else {
            disengage;
        };
    }
}

walker Driver {
    has claimed: dict[str, bool] = {};
    has ply_limit: int = 4;
    has best: int = 0;

    can begin entry {
        targets: list[Position] = [];
        for nd in [root ->:RootLink:->][?:Position] {
