def order_by_static(nodes: list[Position]) -> list[Position] {
    out: list[Position] = [];
    for n in nodes {
        out.append(n);
    }
    i = 0;
    while i < len(out) {
        j = i + 1;
        while j < len(out) {
            if out[j].static_eval > out[i].static_eval {
                tmp = out[i];
                out[i] = out[j];
                out[j] = tmp;
            }
            j += 1;
        }
        i += 1;
    }
    return out;
}

def available_parallelism -> int {
    return PAR_CAP;
}

def warm_pool(capacity: int) -> str {
    c = capacity;
    if c < 1 {
        c = 1;
    }
    cap = available_parallelism();
    if c > cap {
        c = cap;
    }
    pn = PoolNode(pool_id="main", capacity=c);
    root ++> pn;
    pw = pn spawn PoolWarm(claimed={});
    print(["pool_ready", pn.pool_id, pw.claimed]);
    return pn.pool_id;
}

def select_active_workers(capacity: int, search_size: int, scale_hint: float) -> int {
    if capacity < 1 {
        return 1;
    }
    if search_size < 2 {
        return 1;
    }
    active = capacity;
    if scale_hint < 0.5 {
        active = 1;
    } elif scale_hint < 1.0 {
        active = capacity // 2;
        if active < 1 {
            active = 1;
        }
    }
    if search_size < active * 2 {
        active = 1;
    }
    if active > capacity {
        active = capacity;
    }
    return active;
}

def pack_task(board: int, depth: int, alpha: int, beta: int) -> list[int] {
    desc: list[int] = [];
    desc.append(board);
    desc.append(depth);
    desc.append(alpha);
    desc.append(beta);
    return desc;
}

def merge_subtree_scores(scores: list[int]) -> int {
    best: int = -1000000;
    for s in scores {
        if s > best {
            best = s;
        }
    }
    if best == -1000000 {
        return 0;
    }
    return best;
}

def find_position(cid: str) -> Position | None {
    pf = root spawn PositionFinder(target=cid, found=None, claimed={});
    return pf.found;
}

def build_fixture_graph {
    a = Position(cid="a", board=1, ply=0, static_eval=0);
    b = Position(cid="b", board=2, ply=1, static_eval=5);
    c = Position(cid="c", board=3, ply=1, static_eval=7);
    t = Position(cid="t", board=9, ply=2, static_eval=20);
    d = Position(cid="d", board=10, ply=3, static_eval=42);
    root +>:RootLink:+> a;
    a +>:Move:+> b;
    a +>:Move:+> c;
    b +>:Move:+> t;
    c +>:Move:+> t;
    t +>:Move:+> d;
}

def solve_subtree(start_cid: str, ply_limit: int) -> int {
    start = find_position(start_cid);
    if start is None {
        return 0;
    }
    w = start spawn SubtreeScore(claimed={}, ply_limit=ply_limit, result=-1000000, memo={});
    print(["solve", start_cid, w.result]);
    return w.result;
}

def coarse_dispatch(capacity: int, start_cid: str, ply_limit: int) -> int {
    warm_pool(capacity);
    search_size = ply_limit * 4;
    active = select_active_workers(capacity, search_size, 1.0);
    print(["dispatch", start_cid, active, search_size]);
    return solve_subtree(start_cid, ply_limit);
}

def demo_run -> int {
    build_fixture_graph();
    drv = root spawn Driver(claimed={}, ply_limit=4, best=0);
    return coarse_dispatch(available_parallelism(), "a", 4);
}
