"""ClickHouse/ClickHouse#115799 — recursive CTE over MergeTree with parallel replicas."""

node Row {
    has cid: str;
    has n: int;
    has p: int;
}

edge Child {}

obj TableHandle {
    has graph_root: Row;
    has rows: list[Row] = [];
    has n_index: dict[str, Row] = {};
}

class LogicalError(Exception) {
    has message: str;
}

class TooDeepRecursion(Exception) {
    has message: str;
}

walker RecursiveExpand {
    has claimed: dict[str, bool] = {};
    has anchor_n: int = 0;
    has collected: list[int] = [];
    has parallel_replicas: bool = False;
    has max_depth: int = 1000;
    has visit_steps: int = 0;
    has exceeded: bool = False;

    can boot with Row entry {
        if here.cid != "root" {
            skip;
        }
        print ["recursive_cte", self.anchor_n, self.parallel_replicas];
        attached: list[Row] = [here<:Row];
        for nd in attached {
            if nd.cid == "root" {
                continue;
            }
            if nd.n == self.anchor_n {
                visit :0: [nd];
            }
        }
        disengage;
    }

    can descend with Row entry {
        self.visit_steps += 1;
        if self.visit_steps > self.max_depth {
            self.exceeded = True;
            print ["too_deep", self.visit_steps];
            disengage;
        }
        if here.cid in self.claimed {
            skip;
        }
        if not self.parallel_replicas {
            self.claimed[here.cid] = True;
        }
        self.collected.append(here.n);
        print ["row", here.n];
        kids: list[Row] = [here ->:Child:->][?:Row];
        for kid in kids {
            visit :0: [kid];
        }
    }
}

def load_table(spec: list[list[int]]) -> TableHandle {
    rows: list[Row] = [];
    n_index: dict[str, Row] = {};
    graph_root = Row(cid="root", n=-1, p=-1);
    for item in spec {
        n_val = item[0];
        p_val = item[1];
        cid = "r" + str(n_val);
        nd = Row(cid=cid, n=n_val, p=p_val);
        rows.append(nd);
        n_index[str(n_val)] = nd;
        graph_root ++> nd;
    }
    for nd in rows {
        p_key = str(nd.p);
        if p_key in n_index {
            parent = n_index[p_key] as Row;
            parent +>:Child:+> nd;
        }
    }
    return TableHandle(graph_root=graph_root, rows=rows, n_index=n_index);
}

def evaluate_rows(handle: TableHandle, anchor_n: int, parallel_replicas: bool) -> list[int] {
    key = str(anchor_n);
    if key not in handle.n_index {
        return [];
    }
    w = handle.graph_root spawn RecursiveExpand(
        anchor_n=anchor_n,
        parallel_replicas=parallel_replicas,
        max_depth=1000
    );
    out: list[int] = [];
    seen: dict[str, bool] = {};
    for v in w.collected {
        sk = str(v);
        if sk in seen {
            continue;
        }
        seen[sk] = True;
        out.append(v);
    }
    out.sort();
    return out;
}

def count_in_subquery(handle: TableHandle, anchor_n: int, parallel_replicas: bool) -> int {
    if parallel_replicas {
        raise LogicalError("UNION query r is not recursive.");
    }
    vals = evaluate_rows(handle, anchor_n, False);
    val_set: dict[str, bool] = {};
    for v in vals {
        val_set[str(v)] = True;
    }
    cnt = 0;
    for nd in handle.rows {
        if str(nd.n) in val_set {
            cnt += 1;
        }
    }
    return cnt;
}

def count_from_cte(handle: TableHandle, anchor_n: int, parallel_replicas: bool, max_depth: int = 1000) -> int {
    key = str(anchor_n);
    if key not in handle.n_index {
        return 0;
    }
    if parallel_replicas {
        w = handle.graph_root spawn RecursiveExpand(
            anchor_n=anchor_n,
            parallel_replicas=True,
            max_depth=max_depth
        );
        if w.exceeded {
            raise TooDeepRecursion("Maximum recursive CTE evaluation depth (1000) exceeded");
        }
        return len(w.collected);
    }
    return len(evaluate_rows(handle, anchor_n, False));
}
