}

def _run_topo(node_ids: list[str], edges: list[list[str]]) -> list[str] {
    if len(node_ids) == 0 {
        return [];
    }
    id_map: dict[str, Step] = {};
    sorted_ids: list[str] = sorted(node_ids);
    for nid in sorted_ids {
        nd = Step(cid=nid);
        root ++> nd;
        id_map[nid] = nd;
    }
    for e in edges {
        if len(e) < 2 {
            continue;
        }
        src_id = e[0];
        dst_id = e[1];
        if src_id not in id_map {
            continue;
        }
        if dst_id not in id_map {
            continue;
        }
        id_map[src_id] +>:Requires:+> id_map[dst_id];
        id_map[dst_id].indeg = id_map[dst_id].indeg + 1;
    }
    w = root spawn TopoWalker(claimed={}, order=[]);
    return w.order;
}

def is_acyclic(node_ids: list[str], edges: list[list[str]]) -> bool {
    order = _run_topo(node_ids, edges);
    return len(order) == len(node_ids);
}

def topological_sort(node_ids: list[str], edges: list[list[str]]) -> list[str] {
    order = _run_topo(node_ids, edges);
    if len(order) < len(node_ids) {
        emitted: dict[str, bool] = {};
        for cid in order {
            emitted[cid] = True;
        }
        rem: list[str] = [];
        for nid in node_ids {
            if nid not in emitted {
                rem.append(nid);
            }
        }
        rem = sorted(rem);
        raise FilterCycle(remaining=rem);
    }
    return order;
}

def plan(node_ids: list[str], edges: list[list[str]]) -> list[str] {
