def _run_topo(node_ids: list[str], edges: list[list[str]]) -> list[str] {
    if len(node_ids) == 0 {
        return [];
    }
    id_map: dict[str, Step] = {};
    sorted_ids: list[str] = sorted(node_ids);
    for nid in sorted_ids {
        nd = Step(cid=nid);
        root ++> nd;
        id_map[nid] = nd;
    }
    for e in edges {
        if len(e) < 2 {
            continue;
        }
        src_id = e[0];
        dst_id = e[1];
        if src_id not in id_map {
            continue;
        }
        if dst_id not in id_map {
            continue;
        }
        id_map[src_id] +>:Requires:+> id_map[dst_id];
        id_map[dst_id].indeg = id_map[dst_id].indeg + 1;
