                    bh = self.bounds[ch.cid][1];
                    if bw > total_w { total_w = bw; }
                    total_h = total_h + bh;
                }
            }
            self.bounds[here.cid] = [total_w, total_h];
        }
        if !len(kids) {
            disengage;
        }
    }
