def id_in_targets(target: str, targets: list[str]) -> bool {
    for t in targets {
        if t == target {
            return True;
        }
    }
    return False;
}

def clamp_cursor(content: str, cursor: int) -> int {
    if cursor < 0 {
        return 0;
    }
    if cursor > len(content) {
        return len(content);
    }
    return cursor;
}

def insert_text(content: str, cursor: int, character: str) -> list {
    pos = clamp_cursor(content, cursor);
    left = "";
    if pos > 0 {
        left = content[0:pos];
    }
    right = "";
    if pos < len(content) {
        right = content[pos:];
    }
    new_text = left + character + right;
    new_pos = pos + len(character);
    return [new_text, new_pos];
}

