def bring_to_front(next_z: int, already_at_front: bool) -> list {
    if already_at_front {
        current = next_z - 1;
        if current < 0 {
            current = 0;
        }
        return [current, next_z];
    }
    local_z = next_z;
    new_next = next_z + 1;
    if local_z >= OVERLAY_Z_THRESHOLD {
        local_z = OVERLAY_Z_THRESHOLD - 1;
    }
    return [local_z, new_next];
}

