def topological_sort(hub: GraphHub) -> list[str] {
    indeg: dict[str, int] = {};
    for tid in hub.by_id {
        indeg[tid] = 0;
    }
    for tid in hub.by_id {
        task = hub.by_id[tid];
        deps: list[Task] = [];
        for dep in [task <-:Dep:<-][?:Task] {
            deps.append(dep);
        }
        indeg[tid] = len(deps);
    }
    ready: list[str] = [];
    for tid in hub.by_id {
        if indeg[tid] == 0 {
            ready.append(tid);
        }
    }
    ready = sorted(ready);
    order: list[str] = [];
    while len(ready) > 0 {
        cur = ready[0];
        nxt: list[str] = [];
        for i in range(1, len(ready)) {
            nxt.append(ready[i]);
        }
        ready = nxt;
        order.append(cur);
        task = hub.by_id[cur];
        dependents: list[Task] = [];
        for dep_task in [task ->:Dep:->][?:Task] {
            dependents.append(dep_task);
        }
        for dep_task in dependents {
            indeg[dep_task.tid] = indeg[dep_task.tid] - 1;
            if indeg[dep_task.tid] == 0 {
                ready.append(dep_task.tid);
            }
        }
        ready = sorted(ready);
    }
    if len(order) != len(hub.by_id) {
        return [];
    }
    return order;
