def critical_path(hub: GraphHub) -> tuple[list[str], int] {
    order = topological_sort(hub);
    if len(order) == 0 {
        return ([], 0);
    }
    dist: dict[str, int] = {};
    parent: dict[str, str] = {};
    for tid in hub.by_id {
        dist[tid] = 0;
    }
    for tid in order {
        task = hub.by_id[tid];
        deps: list[Task] = [];
        for dep in [task <-:Dep:<-][?:Task] {
            deps.append(dep);
        }
        best: int = 0;
        best_p: str = "";
        for dep in deps {
            d = dist[dep.tid] + dep.duration;
            if d > best {
                best = d;
                best_p = dep.tid;
            }
        }
        if len(deps) == 0 {
            dist[tid] = task.duration;
        } else {
            dist[tid] = best + task.duration;
            parent[tid] = best_p;
        }
    }
    end_tid: str = order[0];
    max_d: int = 0;
    for tid in hub.by_id {
        if dist[tid] > max_d {
            max_d = dist[tid];
            end_tid = tid;
        }
    }
    path: list[str] = [];
    cur: str = end_tid;
    while cur != "" {
        path.append(cur);
        if cur in parent {
            cur = parent[cur];
        } else {
            cur = "";
        }
    }
    rev: list[str] = [];
    idx = len(path) - 1;
    while idx >= 0 {
        rev.append(path[idx]);
        idx = idx - 1;
    }
    return (rev, max_d);
}

