"""Course Schedule — sudosf/leetcode#123.
Directed prerequisite graph; cycle probe via OSP walker + claim map.
"""

node Course {
    has cid: int;
}

edge Prereq {}

walker CycleProbe {
    has claimed: dict[str, bool] = {};
    has visiting: dict[str, bool] = {};
    has state: dict[str, bool] = {};

    can step with Course entry {
        key: str = str(here.cid);
        if key in self.claimed {
            skip;
        }
        if key in self.visiting {
            self.state["cycle"] = True;
            skip;
        }
        self.visiting[key] = True;
        print("probe ", here.cid);
        nbrs: list[Course] = [here ->:Prereq:->][?:Course];
        for nxt in nbrs {
            visit :0: nxt;
        }
        self.visiting[key] = False;
        self.claimed[key] = True;
    }
}

def build_courses(num_courses: int, prerequisites: list[list[int]]) -> list[Course] {
    by_id: dict[int, Course] = {};
    out: list[Course] = [];
    for i in range(num_courses) {
        nd = Course(cid=i);
        root ++> nd;
        by_id[i] = nd;
        out.append(nd);
    }
    for pair in prerequisites {
        a: int = pair[0];
        b: int = pair[1];
        src = by_id[b];
        dst = by_id[a];
        src +>:Prereq:+> dst;
    }
    return out;
}

def can_finish(num_courses: int, prerequisites: list[list[int]]) -> bool {
    nodes: list[Course] = build_courses(num_courses, prerequisites);
    claimed: dict[str, bool] = {};
    state: dict[str, bool] = {"cycle": False};
    for nd in nodes {
        key: str = str(nd.cid);
        if key in claimed {
            continue;
        }
        visiting: dict[str, bool] = {};
        w = nd spawn CycleProbe(claimed=claimed, visiting=visiting, state=state);
        claimed = w.claimed;
        if state["cycle"] {
            return False;
        }
    }
    return True;
}
