def clamp_cursor(content: str, cursor: int) -> int {
    if cursor < 0 {
        return 0;
    }
    if cursor > len(content) {
        return len(content);
    }
    return cursor;
}

def insert_text(content: str, cursor: int, character: str) -> list {
    pos = clamp_cursor(content, cursor);
    left = "";
    if pos > 0 {
        left = content[0:pos];
    }
    right = "";
    if pos < len(content) {
        right = content[pos:];
    }
    new_text = left + character + right;
    new_pos = pos + len(character);
    return [new_text, new_pos];
}

def overlay_threshold() -> int {
    return OVERLAY_Z_THRESHOLD;
}

def bring_to_front(next_z: int, already_at_front: bool) -> list[int] {
    if already_at_front {
        current = next_z - 1;
        if current < 0 {
            current = 0;
        }
        return [current, next_z];
    }
    local_z = next_z;
    new_next = next_z + 1;
    if local_z >= OVERLAY_Z_THRESHOLD {
        local_z = OVERLAY_Z_THRESHOLD - 1;
    }
    return [local_z, new_next];
}

