    }
    return sorted(out);
}

def relayout_dirty_bounds(graph_root: LayoutNode) -> dict[str, list[int]] {
    dirty_ids = collect_dirty_layout(graph_root);
    w = graph_root spawn MeasureWalker(claimed={}, bounds={}, targets=dirty_ids);
    return w.bounds;
}

def bounds_for_id(bounds: dict[str, list[int]], cid: str) -> list[int] {
    if cid in bounds {
        return bounds[cid];
    }
    return [0, 0];
