        self.route.append(here.sid);
        print({"route_hop": here.sid});
        if here.sid == self.target_id {
            self.hit = True;
            disengage;
        }
        nbrs: list[MemorySpace] = [here ->:TopologyHop:->][?:MemorySpace];
        if len(nbrs) == 0 {
            disengage;
        }
        order: list[str] = [];
        for nb in nbrs {
            order.append(nb.sid);
        }
        order = sorted(order);
        for sid in order {
            pick: MemorySpace | None = None;
            for nb in nbrs {
                if nb.sid == sid {
                    pick = nb;
                }
            }
            if pick is not None {
                visit [pick];
            }
        }
    }
