    if len(path) < 2 {
        return [];
    }
    out: list[TransferExpr] = [];
    step: int = 0;
    cur_tensor = tensor_id;
    while step < len(path) - 1 {
        hop_target = path[step + 1];
        leg = TransferExpr(
            tensor_id=cur_tensor,
            space_id=hop_target,
            implicit=False
        );
        out.append(leg);
        cur_tensor = "t_" + str(step);
        step += 1;
    }
    return out;
}

