def get_children_sorted(parent: Album) -> list[Album] {
    raw: list[Album] = [parent ->:Child:->][?:Album];
    n: int = len(raw);
    i: int = 0;
    while i < n {
        best: int = i;
        j: int = i + 1;
        while j < n {
            if raw[j].sort_key < raw[best].sort_key {
                best = j;
            }
            j = j + 1;
        }
        if best != i {
            tmp: Album = raw[i];
            raw[i] = raw[best];
            raw[best] = tmp;
        }
        i = i + 1;
    }
    return raw;
}

def find_parent(tree: SidebarTree, child_id: str) -> Album | None {
    if not (child_id in tree.by_id) { return None; }
    for pid in tree.by_id {
        par: Album = tree.by_id[pid];
        kids: list[Album] = [par ->:Child:->][?:Album];
        for k in kids {
            if k.cid == child_id {
                return par;
            }
        }
    }
    return None;
}

