    tree.counts = {};
    for fid in tree.by_id {
        nd: Album = tree.by_id[fid];
        wk: SubtreeSize = nd spawn SubtreeSize(claimed={});
        desc: int = wk.total - 1;
        if desc < 0 { desc = 0; }
        tree.counts[fid] = desc;
    }
    return tree.counts;
}

