        }
        visit :0: kids;
    }
}

walker ValidateW {
    has claimed: dict[str, bool] = {};
    has logs: list[str] = [];
    can step with ValNode entry {
        if here.nid in self.claimed { skip; }
        self.claimed[here.nid] = True;
        self.logs.append("validator called");
        print("validator called");
        if here.is_recursive_model {
            self.logs.append("validator called");
            print("validator called");
        }
        kids: list[ValNode] = [];
        for ch in [here ->:Child:->][?:ValNode] {
            kids.append(ch);
        }
        if len(kids) > 0 {
            visit :0: kids;
        } else {
            disengage;
        }
    }
}

def find_val_node(target_nid: str) -> ValNode | None {
    w = root spawn FinderW(target=target_nid, claimed={});
    return w.found;
}

def _make_node(sub: dict[str, object], ctr: BuildCounter, gtag: str) -> ValNode {
    nid: str = gtag + "_n" + str(ctr.n);
    ctr.n += 1;
    nd = ValNode(nid=nid, is_recursive_model=True);
    root ++> nd;
    if "child" in sub {
        raw = sub["child"];
        if raw is not None {
            child_spec: dict[str, object] = {};
            if raw is dict {
                child_spec = raw as dict[str, object];
            }
            child_nd = _make_node(child_spec, ctr, gtag);
            nd +>:Child:+> child_nd;
        }
    }
    return nd;
}

def build_val_graph(spec: dict[str, object]) -> ValGraph {
    ctr = BuildCounter();
    gtag: str = "v";
    if "_gtag" in spec {
        gtag = spec["_gtag"] as str;
    }
    inner: dict[str, object] = {};
    if "node" in spec {
        inner = spec["node"] as dict[str, object];
    } else {
        inner = spec;
    }
    root_nd = _make_node(inner, ctr, gtag);
    g = ValGraph(entry_nid=root_nd.nid);
    return g;
}

def validate_recursive(g: ValGraph) -> list[str] {
    start = find_val_node(g.entry_nid);
    if start is None {
        empty: list[str] = [];
        return empty;
