def find_parent(tree: SidebarTree, child_id: str) -> Album | None {
    if not (child_id in tree.by_id) { return None; }
    for pid in tree.by_id {
        par: Album = tree.by_id[pid];
        kids: list[Album] = [par ->:Child:->][?:Album];
        for k in kids {
            if k.cid == child_id {
                return par;
            }
        }
    }
    return None;
}

def create_sidebar_tree -> SidebarTree {
    gr: Album = Album(cid="__root__", name="Library", sort_key=0);
    root ++> gr;
    t: SidebarTree = SidebarTree(graph_root=gr);
    t.by_id["__root__"] = gr;
    return t;
}

def add_folder(tree: SidebarTree, parent_id: str, folder_id: str, name: str, order_idx: int) -> None {
    if not (parent_id in tree.by_id) { return; }
    if folder_id in tree.by_id { return; }
    parent: Album = tree.by_id[parent_id];
    nd: Album = Album(cid=folder_id, name=name, sort_key=order_idx);
    parent +>:Child:+> nd;
    tree.by_id[folder_id] = nd;
    tree.counts[folder_id] = 0;
}

def refresh_counts(tree: SidebarTree) -> dict[str, int] {
    tree.counts = {};
    for fid in tree.by_id {
        nd: Album = tree.by_id[fid];
        wk: SubtreeSize = nd spawn SubtreeSize(claimed={});
        desc: int = wk.total - 1;
        if desc < 0 { desc = 0; }
        tree.counts[fid] = desc;
    }
    return tree.counts;
}

def list_flat(tree: SidebarTree) -> list[dict[str, any]] {
    refresh_counts(tree);
    wk: FlatList = tree.graph_root spawn FlatList(claimed={}, counts=tree.counts);
    return wk.rows;
}

def move_folder(tree: SidebarTree, folder_id: str, new_parent_id: str) -> None {
    if not (folder_id in tree.by_id) { return; }
    if not (new_parent_id in tree.by_id) { return; }
    if folder_id == new_parent_id { return; }
    child: Album = tree.by_id[folder_id];
    par: Album | None = find_parent(tree, folder_id);
    if par is None { return; }
    new_par: Album = tree.by_id[new_parent_id];
    par del-->:Child:--> child;
    new_par +>:Child:+> child;
}

def reorder_folder(tree: SidebarTree, folder_id: str, new_order: int) -> None {
    if not (folder_id in tree.by_id) { return; }
    nd: Album = tree.by_id[folder_id];
    nd.sort_key = new_order;
}

def get_descendant_count(tree: SidebarTree, folder_id: str) -> int {
    if not (folder_id in tree.by_id) { return 0; }
    if not (folder_id in tree.counts) {
        refresh_counts(tree);
    }
    if folder_id in tree.counts {
        return tree.counts[folder_id];
    }
    return 0;
}

