"""Cross-reference resolver and dependency graph — yevheniidehtiar/gitpm#223."""

node DepNode { has id: str; }

edge Depends {}

walker TopoWalker {
    has claimed: dict[str, bool] = {};
    has order: list[str] = [];

    can walk_dep with DepNode entry {
        print("topo", here.id);
        if here.id in self.claimed { skip; }
        self.claimed[here.id] = True;
        kids: list[DepNode] = [];
        for ch in [here ->:Depends:->][?:DepNode] {
            kids.append(ch);
        }
        for kid in kids {
            visit :0: [kid];
        }
        self.order.append(here.id);
    }
}

walker CycleWalker {
    has claimed: dict[str, bool] = {};
    has stack: dict[str, bool] = {};
    has has_cycle: bool = False;

    can walk_dep with DepNode entry {
        print("cycle", here.id);
        if here.id in self.claimed {
            if here.id in self.stack {
                self.has_cycle = True;
            }
            skip;
        }
        self.claimed[here.id] = True;
        self.stack[here.id] = True;
        kids: list[DepNode] = [];
        for ch in [here ->:Depends:->][?:DepNode] {
            kids.append(ch);
        }
        for kid in kids {
            visit [kid];
        }
        self.stack[here.id] = False;
    }
}

def _collect_dep_ids(deps: dict[str, list[str]]) -> list[str] {
    ids: list[str] = [];
    seen: dict[str, bool] = {};
    for src in deps {
        if src not in seen {
            ids.append(src);
            seen[src] = True;
        }
        for tid in deps[src] {
            if tid not in seen {
                ids.append(tid);
                seen[tid] = True;
            }
        }
    }
    return sorted(ids);
}

def _wire_dep_nodes(ids: list[str], deps: dict[str, list[str]]) -> dict[str, DepNode] {
    index: dict[str, DepNode] = {};
    for eid in ids {
        dn = DepNode(id=eid);
        index[eid] = dn;
    }
    for src in ids {
        targets: list[str] = [];
        if src in deps {
            targets = deps[src];
        }
        for tid in targets {
            if tid in index {
                index[src] +>:Depends:+> index[tid];
            }
        }
    }
    return index;
}

def build_lookups(
    stories: list[dict],
    epics: list[dict],
    milestones: list[dict],
    roadmaps: list[dict],
    prds: list[dict]
) -> dict {
    story_epic: dict[str, str] = {};
    epic_milestone: dict[str, str] = {};
    milestone_roadmap: dict[str, str] = {};
    roadmap_milestones: dict[str, list[str]] = {};
    prd_epics: dict[str, list[str]] = {};
    for rm in roadmaps {
        rid = rm["id"] as str;
        roadmap_milestones[rid] = [];
    }
    for s in stories {
        sid = s["id"] as str;
        epic_id = "";
        if "epic_ref" in s {
            epic_id = s["epic_ref"] as str;
        }
        story_epic[sid] = epic_id;
    }
    for e in epics {
        eid = e["id"] as str;
        ms_id = "";
        if "milestone_ref" in e {
            ms_id = e["milestone_ref"] as str;
        }
        epic_milestone[eid] = ms_id;
    }
    for m in milestones {
        mid = m["id"] as str;
        rm_id = "";
        if "roadmap_ref" in m {
            rm_id = m["roadmap_ref"] as str;
        }
        milestone_roadmap[mid] = rm_id;
        if rm_id != "" and rm_id in roadmap_milestones {
            roadmap_milestones[rm_id].append(mid);
        }
    }
    for p in prds {
        pid = p["id"] as str;
        refs: list[str] = [];
        if "epic_refs" in p {
            refs = p["epic_refs"] as list[str];
        }
        prd_epics[pid] = refs;
    }
    result: dict = {};
    result["story_epic"] = story_epic;
    result["epic_milestone"] = epic_milestone;
    result["milestone_roadmap"] = milestone_roadmap;
    result["roadmap_milestones"] = roadmap_milestones;
    result["prd_epics"] = prd_epics;
    return result;
}

def resolve_story_chain(
    story_id: str,
    story_epic: dict[str, str],
    epic_milestone: dict[str, str],
    milestone_roadmap: dict[str, str]
) -> list[str] {
    chain: list[str] = [story_id];
    epic_id = "";
    if story_id in story_epic {
        epic_id = story_epic[story_id];
    }
    chain.append(epic_id);
    ms_id = "";
    if epic_id != "" and epic_id in epic_milestone {
        ms_id = epic_milestone[epic_id];
    }
    chain.append(ms_id);
    rm_id = "";
    if ms_id != "" and ms_id in milestone_roadmap {
        rm_id = milestone_roadmap[ms_id];
    }
    chain.append(rm_id);
    return chain;
}

def detect_cycle(deps: dict[str, list[str]]) -> bool {
    ids = _collect_dep_ids(deps);
    if len(ids) == 0 {
        return False;
    }
    index = _wire_dep_nodes(ids, deps);
    start = ids[0];
    w = index[start] spawn CycleWalker(claimed={}, stack={});
    return w.has_cycle;
}

def topological_sort(deps: dict[str, list[str]]) -> list[str] {
    if detect_cycle(deps) {
        return [];
    }
    ids = _collect_dep_ids(deps);
    if len(ids) == 0 {
        return [];
    }
    index = _wire_dep_nodes(ids, deps);
    start = ids[0];
    w = index[start] spawn TopoWalker(claimed={});
    rev: list[str] = [];
    i = len(w.order) - 1;
    while i >= 0 {
        rev.append(w.order[i]);
        i = i - 1;
    }
    return rev;
}

def resolve_tree(
    stories: list[dict],
    epics: list[dict],
    milestones: list[dict],
    roadmaps: list[dict],
    prds: list[dict],
    deps: dict[str, list[str]] | None = None
) -> dict {
    lookups = build_lookups(stories, epics, milestones, roadmaps, prds);
    se = lookups["story_epic"] as dict[str, str];
    em = lookups["epic_milestone"] as dict[str, str];
    mr = lookups["milestone_roadmap"] as dict[str, str];
    chains: dict[str, list[str]] = {};
    errors: list[str] = [];
    for s in stories {
        sid = s["id"] as str;
        ch = resolve_story_chain(sid, se, em, mr);
        chains[sid] = ch;
        want = "";
        if "epic_ref" in s {
            want = s["epic_ref"] as str;
        }
        if want != "" and ch[1] == "" {
            errors.append(sid);
        }
    }
    has_cyc = False;
    dep_order: list[str] = [];
    if deps is not None {
        has_cyc = detect_cycle(deps);
        if not has_cyc {
            dep_order = topological_sort(deps);
        }
    }
    out: dict = {};
    out["lookups"] = lookups;
    out["chains"] = chains;
    out["errors"] = sorted(errors);
    out["has_cycle"] = has_cyc;
    out["dep_order"] = dep_order;
    return out;
}
