        if key_colfilial != None and kf != key_colfilial {
            continue;
        }
        pa = ensure_node(nodes, row["parent_id"], kf);
        ch = ensure_node(nodes, row["child_id"], kf);
        qv = row["qty"];
        pa +>:BomEdge:{has qty=qv}:+> ch;
    }
    return nodes;
}

def find_root_ids(df_bom: list[dict], key_colfilial: str | None) -> list[int] {
