    parent_set: dict[int, bool] = {};
    for row in df_bom {
        if key_colfilial != None and row["key_colfilial"] != key_colfilial {
            continue;
        }
        child_set[row["child_id"]] = True;
        parent_set[row["parent_id"]] = True;
    }
    out: list[int] = [];
    for pid in parent_set {
        if pid not in child_set {
            out.append(pid);
        }
    }
    return sorted(out);
