def rebalance_rows(
    rows: list[dict],
    max_iter: int,
    tol: float,
    mode: str
) -> list[dict] {
    if mode != "split" {
        return rows;
    }
    cur: list[dict] = rows;
    it: int = 0;
    while it < max_iter {
        nxt: list[dict] = [];
        for r in cur {
            q = r["qty"];
            if q < MIN_QUANTITY_THRESHOLD {
                q = 0.0;
            }
            r2: dict = {};
            for k in r {
                r2[k] = r[k];
            }
            r2["qty"] = q;
            nxt.append(r2);
        }
        cur = nxt;
        it += 1;
    }
    return cur;
}

def explode_bom(
    df_bom: list[dict],
    key_colfilial: str | None = None,
    roots: list[int] | None = None,
    max_depth: int = 50,
    max_iter: int = 20,
    tol: float = 1e-9,
    intermediate_handling: str = "split",
    enable_logging: bool = True
) -> list[dict] {
    if len(df_bom) == 0 {
        raise BOMExplosionError("empty bom");
    }
    nodes = build_bom_graph(df_bom, key_colfilial);
    out_rows: list[dict] = [];
    start_roots: list[int] = [];
    if roots != None {
        start_roots = roots;
    } else {
        start_roots = find_root_ids(df_bom, key_colfilial);
    }
    ri: int = 0;
    while ri < len(start_roots) {
        rid = start_roots[ri];
        if rid not in nodes {
            ri += 1;
            continue;
        }
        rnode = nodes[rid];
        with entry {
            w = rnode spawn ExplodeWalker(
                claimed={},
                max_depth=max_depth,
                depth=0,
                root_pid=rid,
                path=[],
                cum_qty=1.0,
                results=[],
                parent_pid=-1
            );
        }
        for row in w.results {
            out_rows.append(row);
        }
        ri += 1;
    }
    out_rows = rebalance_rows(out_rows, max_iter, tol, intermediate_handling);
    if enable_logging {
        print("explode_bom complete rows=" + str(len(out_rows)));
    }
    return out_rows;
}
