"""python/cpython#63061 — recursive exception chain walk with cycle guard."""

node Exc {
    has exc_id: str;
    has msg: str = "";
}

edge Cause {}
edge Context {}

walker ChainWalk {
    has claimed: dict[str, bool] = {};
    has order: list[str] = [];
    has found_cycle: bool = False;

    can chain with Exc entry {
        if here.exc_id in self.claimed {
            self.found_cycle = True;
            skip;
        }
        self.claimed[here.exc_id] = True;
        self.order.append(here.exc_id);
        cause_kids: list[Exc] = [here ->:Cause:->][?:Exc];
        ctx_kids: list[Exc] = [here ->:Context:->][?:Exc];
        nxt: list[Exc] = [];
        if cause_kids {
            nxt.append(cause_kids[0]);
        } elif ctx_kids {
            nxt.append(ctx_kids[0]);
        }
        visit :0: nxt else {
            disengage;
        }
    }
}

walker ClosureWalk {
    has claimed: dict[str, bool] = {};
    has order: list[str] = [];

    can expand with Exc entry {
        if here.exc_id in self.claimed {
            skip;
        }
        self.claimed[here.exc_id] = True;
        self.order.append(here.exc_id);
        kids: list[Exc] = [];
        for c in [here ->:Cause:->][?:Exc] {
            kids.append(c);
        }
        for c in [here ->:Context:->][?:Exc] {
            kids.append(c);
        }
        visit :0: kids else {
            disengage;
        }
    }
}

obj ExcChainStore {
    has graph_root: Exc;
}

def make_store -> ExcChainStore {
    root_nd = Exc(exc_id="__root__", msg="");
    store = ExcChainStore(graph_root=root_nd);
    return store;
}

def register_exc(store: ExcChainStore, exc_id: str, msg: str) {
    nd = Exc(exc_id=exc_id, msg=msg);
    store.graph_root ++> nd;
}

def find_exc(store: ExcChainStore, exc_id: str) -> Exc | None {
    kids: list[Exc] = [store.graph_root ->][?:Exc];
    for ch in kids {
        if ch.exc_id == exc_id {
            return ch;
        }
    }
    return None;
}

def link_cause(store: ExcChainStore, exc_id: str, cause_id: str) {
    src = find_exc(store, exc_id);
    dst = find_exc(store, cause_id);
    if src is not None and dst is not None {
        src +>:Cause:+> dst;
    }
}

def link_context(store: ExcChainStore, exc_id: str, ctx_id: str) {
    src = find_exc(store, exc_id);
    dst = find_exc(store, ctx_id);
    if src is not None and dst is not None {
        src +>:Context:+> dst;
    }
}

def walk_chain(store: ExcChainStore, start_id: str) -> list[str] {
    start = find_exc(store, start_id);
    if start is None {
