walker CycleWalker {
    has claimed: dict[str, bool] = {};
    has stack: dict[str, bool] = {};
    has has_cycle: bool = False;

    can walk_dep with DepNode entry {
        print("cycle", here.id);
        if here.id in self.claimed {
            if here.id in self.stack {
                self.has_cycle = True;
            }
            skip;
        }
        self.claimed[here.id] = True;
        self.stack[here.id] = True;
        kids: list[DepNode] = [];
        for ch in [here ->:Depends:->][?:DepNode] {
            kids.append(ch);
        }
        for kid in kids {
            visit [kid];
        }
        self.stack[here.id] = False;
    }
}

def _collect_dep_ids(deps: dict[str, list[str]]) -> list[str] {
    ids: list[str] = [];
    seen: dict[str, bool] = {};
    for src in deps {
        if src not in seen {
            ids.append(src);
            seen[src] = True;
        }
        for tid in deps[src] {
            if tid not in seen {
                ids.append(tid);
                seen[tid] = True;
            }
        }
    }
    return sorted(ids);
}

def _wire_dep_nodes(ids: list[str], deps: dict[str, list[str]]) -> dict[str, DepNode] {
    index: dict[str, DepNode] = {};
    for eid in ids {
        dn = DepNode(id=eid);
        index[eid] = dn;
    }
    for src in ids {
        targets: list[str] = [];
        if src in deps {
            targets = deps[src];
        }
        for tid in targets {
            if tid in index {
                index[src] +>:Depends:+> index[tid];
            }
        }
    }
    return index;
