    milestone_roadmap: dict[str, str] = {};
    roadmap_milestones: dict[str, list[str]] = {};
    prd_epics: dict[str, list[str]] = {};
    for rm in roadmaps {
        rid = rm["id"] as str;
        roadmap_milestones[rid] = [];
    }
    for s in stories {
        sid = s["id"] as str;
        epic_id = "";
        if "epic_ref" in s {
            epic_id = s["epic_ref"] as str;
        }
        story_epic[sid] = epic_id;
