        ms_id = "";
        if "milestone_ref" in e {
            ms_id = e["milestone_ref"] as str;
        }
        epic_milestone[eid] = ms_id;
    }
    for m in milestones {
        mid = m["id"] as str;
        rm_id = "";
        if "roadmap_ref" in m {
            rm_id = m["roadmap_ref"] as str;
        }
        milestone_roadmap[mid] = rm_id;
        if rm_id != "" and rm_id in roadmap_milestones {
