    se = lookups["story_epic"] as dict[str, str];
    em = lookups["epic_milestone"] as dict[str, str];
    mr = lookups["milestone_roadmap"] as dict[str, str];
    chains: dict[str, list[str]] = {};
    for s in stories {
        sid = s["id"] as str;
        chains[sid] = resolve_story_chain(sid, se, em, mr);
    }
    dep_order: list[str] = [];
    has_cycle = False;
    if deps is not None {
        has_cycle = detect_cycle(deps);
        if not has_cycle {
            dep_order = topological_sort(deps);
        }
    }
    result: dict = {};
    result["lookups"] = lookups;
    result["story_chains"] = chains;
    result["dependency_order"] = dep_order;
    result["has_cycle"] = has_cycle;
    return result;
