            }
            r2["qty"] = q;
            nxt.append(r2);
        }
        cur = nxt;
        it += 1;
    }
    return cur;
}

def explode_bom(
    df_bom: list[dict],
    key_colfilial: str | None = None,
    roots: list[int] | None = None,
    max_depth: int = 50,
    max_iter: int = 20,
    tol: float = 1e-9,
    intermediate_handling: str = "split",
    enable_logging: bool = True
) -> list[dict] {
    return explode_bom_run(
        df_bom,
        key_colfilial,
        roots,
        max_depth,
        max_iter,
        tol,
        intermediate_handling,
        enable_logging
    );
}

def explode_bom_run(
    df_bom: list[dict],
    key_colfilial: str | None,
    roots: list[int] | None,
    max_depth: int,
    max_iter: int,
    tol: float,
    intermediate_handling: str,
    enable_logging: bool
) -> list[dict] {
    if len(df_bom) == 0 {
        raise BOMExplosionError("empty bom");
    }
    nodes = build_bom_graph(df_bom, key_colfilial);
    out_rows: list[dict] = [];
    start_roots: list[int] = [];
    if roots is not None {
        start_roots = roots;
    } else {
        start_roots = find_root_ids(df_bom, key_colfilial);
    }
    ri: int = 0;
    while ri < len(start_roots) {
        rid = start_roots[ri];
        if rid not in nodes {
            ri += 1;
            continue;
        }
        rnode = nodes[rid];
        w = rnode spawn ExplodeWalker(
            claimed={},
            max_depth=max_depth,
            depth=0,
            root_pid=rid,
            path=[],
            cum_qty=1.0,
            results=[],
            parent_pid=-1
        );
        wi: int = 0;
        while wi < len(w.results) {
            out_rows.append(w.results[wi]);
            wi += 1;
        }
        ri += 1;
    }
    return rebalance_rows(out_rows, max_iter, tol, intermediate_handling);
}

def row_key(r: dict) -> str {
    return (
        str(r["root_id"])
        + ":"
        + str(r["parent_id"])
        + ":"
        + str(r["child_id"])
        + ":"
        + str(r["depth"])
    );
}

def qty_by_key(rows: list[dict]) -> dict[str, float] {
    out: dict[str, float] = {};
    i: int = 0;
    while i < len(rows) {
        out[row_key(rows[i])] = rows[i]["qty"];
        i += 1;
    }
    return out;
}

