    for i in range(len(seq)) {
        if seq[i] == val {
            return i;
        }
    }
    return -1;
}

def precedes(seq: list[str], a: str, b: str) -> bool {
    pa = idx_of(seq, a);
    pb = idx_of(seq, b);
    if pa < 0 or pb < 0 {
        return False;
    }
    return pa < pb;
}

