    first_seq = execution_order(handle, entry_ids[0]);
    first_libs: list[str] = [];
    for mid in first_seq {
        if mid != entry_ids[0] {
            first_libs.append(mid);
        }
    }
    for ei in range(1, len(entry_ids)) {
        eid = entry_ids[ei];
        seq = execution_order(handle, eid);
        libs: list[str] = [];
        for mid in seq {
            if mid != eid {
                libs.append(mid);
            }
        }
        for a in first_libs {
            for b in first_libs {
                if a == b {
                    continue;
                }
                fwd = precedes(first_libs, a, b);
                rev = precedes(libs, b, a);
                if fwd and rev {
                    return [];
                }
            }
        }
    }
    return first_libs;
}

def entry_chunk_valid(
    handle: BundleHandle,
    entry: str,
    shared: list[str],
) -> bool {
    if entry not in handle.modules {
        return False;
    }
    seq = execution_order(handle, entry);
    libs: list[str] = [];
    for mid in seq {
        if mid != entry {
            libs.append(mid);
        }
    }
    if len(shared) != len(libs) {
        return False;
    }
    for a in libs {
        for b in libs {
            if a == b {
                continue;
            }
            if precedes(libs, a, b) and not precedes(shared, a, b) {
                return False;
            }
        }
    }
    return True;
}
