    for up in [here ->:Parent:->][?:Comment] { nexts.append(up); }
    visit :0: nexts;
  }
}

walker ClimbAnchor {
  has max_depth: int;
  has anchor: Comment | None = None;
  has claimed: dict[str, bool] = {};

  can step with Comment entry {
    if here.cid in self.claimed { skip; }
    self.claimed[here.cid] = True;
    if here.depth < self.max_depth {
      self.anchor = here;
      disengage;
    }
    ups: list[Comment] = [here ->:Parent:->][?:Comment];
    if ups { visit :0: ups; } else { disengage; }
  }
}

def find_node(graph_anchor: Comment, cid: str) -> Comment | None {
  w = graph_anchor spawn Locate(want=cid);
  return w.hit;
}

def resolve_anchor(graph_anchor: Comment, parent_id: str, max_depth: int) -> str | None {
  start = find_node(graph_anchor, parent_id);
  if start is None { return None; }
  wk = start spawn ClimbAnchor(max_depth=max_depth);
  if wk.anchor is None { return None; }
  return wk.anchor.cid;
}

def propose_insert(
  graph_anchor: Comment,
  parent_id: str | None,
  max_depth: int,
  fixed: bool = False,
) -> dict[str, object] {
  stored_parent_id: str | None = None;
  intended_parent_id: str | None = parent_id;
  depth: int = 0;
  if parent_id is None {
    out: dict[str, object] = {};
    out["stored_parent_id"] = None;
    out["intended_parent_id"] = None;
    out["depth"] = 0;
    return out;
  }
  anchor_cid = resolve_anchor(graph_anchor, parent_id, max_depth);
  if anchor_cid is not None {
    anch = find_node(graph_anchor, anchor_cid);
    stored_parent_id = anchor_cid;
    if anch is not None { depth = anch.depth + 1; }
  } else {
    stored_parent_id = None;
    depth = 0;
    if fixed { intended_parent_id = None; }
  }
  shaped: dict[str, object] = {};
  shaped["stored_parent_id"] = stored_parent_id;
  shaped["intended_parent_id"] = intended_parent_id;
  shaped["depth"] = depth;
  return shaped;
}

def trigger_aborts(record: dict[str, object]) -> bool {
  sp = record["stored_parent_id"];
  ip = record["intended_parent_id"];
  if sp is None and ip is not None { return True; }
  return False;
}

def attach_comment(
  graph_anchor: Comment,
  cid: str,
  depth: int,
  parent_cid: str | None,
) -> Comment {
  nd = Comment(cid=cid, depth=depth);
  graph_anchor ++> nd;
  if parent_cid is not None {
    par = find_node(graph_anchor, parent_cid);
    if par is not None { nd +>:Parent:+> par; }
  }
  return nd;
}

