    seq = execution_order(handle, entry_id);
    libs: list[str] = [];
    for mid in seq {
        if mid != entry_id {
            libs.append(mid);
        }
    }
    if len(shared) != len(libs) {
        return False;
    }
    for a in libs {
        for b in libs {
            if a == b {
                continue;
            }
            if precedes(libs, a, b) and not precedes(shared, a, b) {
                return False;
            }
        }
    }
    return True;
}

