  seen: int = 0;
  while len(ready) > 0 {
    wave: list[str] = sorted(ready);
    waves.append(wave);
    seen = seen + len(wave);
    nxt_ready: list[str] = [];
    for cur in wave {
      for sid in ids {
        deps: list[str] = spec[sid];
        uses: bool = False;
        for dep in deps {
          if dep == cur {
            uses = True;
          }
        }
        if uses {
          indeg[sid] = indeg[sid] - 1;
          if indeg[sid] == 0 {
            nxt_ready.append(sid);
          }
        }
      }
    }
    ready = sorted(nxt_ready);
  }
  if seen != len(ids) {
    raise ValueError("DependencyCycleError");
  }
  return waves;
}

def subset_order(full: dict[str, list[str]], selected: list[str]) -> list[str] {
  order: list[str] = resolve_order(full);
  pick: dict[str, bool] = {};
  for sid in selected {
    pick[sid] = True;
  }
  out: list[str] = [];
  for sid in order {
    if sid in pick {
      out.append(sid);
    }
  }
  return out;
}

def cycle_members(spec: dict[str, list[str]]) -> list[str] | None {
  ids: list[str] = sorted(spec.keys());
  if len(ids) == 0 {
    return None;
  }
  indeg: dict[str, int] = {};
  try {
    indeg = indegrees(spec);
  } catch {
    return None;
  }
  ready: list[str] = [];
  for sid in ids {
    if indeg[sid] == 0 {
      ready.append(sid);
    }
  }
  ready = sorted(ready);
  seen: int = 0;
  while len(ready) > 0 {
    cur = ready[0];
    nxt_ready: list[str] = [];
    for i in range(1, len(ready)) {
      nxt_ready.append(ready[i]);
    }
    ready = nxt_ready;
    seen = seen + 1;
    for sid in ids {
      deps: list[str] = spec[sid];
      uses: bool = False;
      for dep in deps {
        if dep == cur {
          uses = True;
        }
      }
      if uses {
        indeg[sid] = indeg[sid] - 1;
        if indeg[sid] == 0 {
          ready.append(sid);
        }
      }
    }
    ready = sorted(ready);
  }
  if seen == len(ids) {
    return None;
  }
  cyc: list[str] = [];
  for sid in ids {
    if indeg[sid] > 0 {
      cyc.append(sid);
    }
  }
  return sorted(cyc);
}

def downstream_fan(changed: str, spec: dict[str, list[str]]) -> list[str] {
  nodes: dict[str, Stack] = build_nodes(spec);
  if changed not in nodes {
    return [];
  }
  anchor = nodes[changed];
  w = anchor spawn FanWalker(claimed={}, touched=[], origin=changed);
  ranked: list[str] = resolve_order(spec);
  hit: dict[str, bool] = {};
  for sid in w.touched {
    hit[sid] = True;
  }
  out: list[str] = [];
  for sid in ranked {
    if sid in hit {
      out.append(sid);
    }
  }
  return out;
}

def bootstrap_walk(spec: dict[str, list[str]]) -> list[str] {
  build_nodes(spec);
  w = root spawn BootstrapWalker(claimed={}, seen=[]);
  return w.seen;
}
