"""Lifted from s3tools/s3cmd#624 — recursive S3 prefix listing."""

node S3Prefix {
    has pid: str;
    has name: str = "";
}

node S3Object {
    has key: str;
    has size: int = 0;
}

edge Contains {}

walker PrefixFinder {
    has want: str = "";
    has hit: S3Prefix | None = None;
    has claimed: dict[str, bool] = {};

    can seek with S3Prefix entry {
        if here.pid == self.want {
            self.hit = here;
            disengage;
        }
        if here.pid in self.claimed {
            skip;
        }
        self.claimed[here.pid] = True;
        kids: list[S3Prefix] = [here ->:Contains:->][?:S3Prefix];
        for ch in kids {
            visit ch;
        }
        disengage;
    }
}

walker BufferedLister {
    has claimed: dict[str, bool] = {};
    has keys: list[str] = [];

    can walk with S3Prefix entry {
        if here.pid in self.claimed {
            skip;
        }
        self.claimed[here.pid] = True;
        objs: list[S3Object] = [here ->:Contains:->][?:S3Object];
        for ob in objs {
            self.keys.append(ob.key);
        }
        kids: list[S3Prefix] = [here ->:Contains:->][?:S3Prefix];
        for ch in kids {
            visit :0: ch;
        }
        disengage;
    }
}

walker StreamLister {
    has claimed: dict[str, bool] = {};
    has keys: list[str] = [];
    has pages: int = 0;

    can walk with S3Prefix entry {
        if here.pid in self.claimed {
            skip;
        }
        self.claimed[here.pid] = True;
        page: list[str] = [];
        objs: list[S3Object] = [here ->:Contains:->][?:S3Object];
        for ob in objs {
            page.append(ob.key);
            self.keys.append(ob.key);
        }
        if len(page) > 0 {
            self.pages = self.pages + 1;
            print("flush", self.pages, len(page));
        }
        kids: list[S3Prefix] = [here ->:Contains:->][?:S3Prefix];
        for ch in kids {
            visit :0: ch;
        }
        disengage;
    }
}

walker SmokeWalker {
    has claimed: dict[str, bool] = {};

    can ping with S3Prefix entry {
        if here.pid in self.claimed {
            skip;
        }
        self.claimed[here.pid] = True;
        print("visit", here.pid);
        kids: list[S3Prefix] = [here ->:Contains:->][?:S3Prefix];
        for ch in kids {
            visit ch;
        }
        disengage;
    }
}

def find_prefix(pid: str) -> S3Prefix | None {
    w: PrefixFinder = root spawn PrefixFinder(want=pid, claimed={});
    return w.hit;
}

def list_recursive_buffered(prefix_id: str) -> list[str] {
    start: S3Prefix | None = find_prefix(prefix_id);
    if start is None {
        return [];
    }
    claimed: dict[str, bool] = {};
    keys: list[str] = [];
    bw: BufferedLister = start spawn BufferedLister(claimed=claimed, keys=keys);
    out: list[str] = bw.keys;
    return sorted(out);
}

def list_recursive_streaming(prefix_id: str) -> list[str] {
    start: S3Prefix | None = find_prefix(prefix_id);
    if start is None {
        return [];
    }
    claimed: dict[str, bool] = {};
    keys: list[str] = [];
    sw: StreamLister = start spawn StreamLister(claimed=claimed, keys=keys, pages=0);
    out: list[str] = sw.keys;
    return sorted(out);
}

