edge RefType {}

walker DepWalker {
    has claimed: dict[str, bool] = {};
    has deps: list[str] = {};
    has schema_types: dict[str, bool] = {};

    can step with TypeN entry {
        if here.name in self.claimed {
            skip;
        }
        self.claimed[here.name] = True;
        self.deps.append(here.name);
        for fld in [here ->:HasField:->][?:FieldN] {
            if fld.ftype in self.schema_types {
                for ref_t in [fld ->:RefType:->][?:TypeN] {
                    visit :0: [ref_t];
                }
            }
        }
    }
