    by_name: dict[str, TypeN] = {};
    for tname in spec {
        tn = TypeN(name=tname, ordered_fields=[]);
        root ++> tn;
        by_name[tname] = tn;
    }
    for tname in spec {
        tn = by_name[tname];
        pairs: list[tuple] = _field_pairs(spec, tname);
        ordered: list[str] = [];
        for pr in pairs {
            fname: str = pr[0];
            ftype: str = pr[1];
            fn = FieldN(fname=fname, ftype=ftype);
            tn +>:HasField:+> fn;
            ordered.append(fname);
            if ftype in by_name {
                fn +>:RefType:+> by_name[ftype];
            }
        }
        tn.ordered_fields = ordered;
    }
    return by_name;
}

def encode_type(spec: dict, type_name: str) -> str {
    if not _is_struct(spec, type_name) {
        return "";
    }
    parts: list[str] = [];
    for pr in _field_pairs(spec, type_name) {
        parts.append(pr[1] + " " + pr[0]);
    }
    inner: str = ", ".join(parts);
    return type_name + "(" + inner + ")";
}

def dependency_names(spec: dict, type_name: str) -> list[str] {
    if not _is_struct(spec, type_name) {
        return [];
    }
    by_name: dict[str, TypeN] = _build_graph(spec);
    root_t = by_name[type_name];
    schema_types: dict[str, bool] = {};
    for k in spec {
        schema_types[k] = True;
    }
    w = root_t spawn DepWalker(claimed={}, deps=[], schema_types=schema_types);
    raw: list[str] = w.deps;
    uniq: dict[str, bool] = {};
    for nm in raw {
        uniq[nm] = True;
    }
    out: list[str] = [];
    for k in uniq {
        out.append(k);
    }
    out.sort();
    return out;
}

def primary_and_deps(spec: dict, type_name: str) -> list[str] {
    enc: list[str] = [];
    primary = encode_type(spec, type_name);
    if primary == "" {
        return [];
    }
    enc.append(primary);
    deps = dependency_names(spec, type_name);
    for d in deps {
        if d != type_name {
            enc.append(encode_type(spec, d));
        }
    }
    return enc;
}

