"""KingPin/Garrul#119 — same-thread parent cycle detection and re-rooting."""

node GraphRoot {}

node Comment {
    has cid: str;
    has thread_id: str;
    has raw_parent: str = "";
    has eff_parent: str = "";
}

edge ParentEdge {}

walker ParentFollowWalker {
    has claimed: dict[str, bool] = {};
    has trail: list[str] = [];
    has hit_cycle: bool = False;
    has cycle_set: dict[str, bool] = {};

    can ascend with Comment entry {
        if here.cid in self.claimed {
            self.hit_cycle = True;
            idx: int = -1;
            ti: int = 0;
            for tid in self.trail {
                if tid == here.cid {
                    idx = ti;
                }
                ti = ti + 1;
            }
            if idx >= 0 {
                si: int = idx;
                for tid in self.trail {
                    if si <= ti and si >= idx {
                        self.cycle_set[tid] = True;
                    }
                    si = si + 1;
                }
            }
            self.cycle_set[here.cid] = True;
            skip;
        }
        self.claimed[here.cid] = True;
        self.trail.append(here.cid);
        ups: list[Comment] = [here ->:ParentEdge:->][?:Comment];
        if len(ups) > 0 {
            visit :0: [ups[0]];
        } else {
            disengage;
        }
    }
}

def build_effective_parent(comments: list) -> dict[str, str] {
    by_id: dict[str, Comment] = {};
    eff: dict[str, str] = {};
    for row in comments {
        cid: str = row["id"];
        tid: str = row["thread_id"];
        raw: str = "";
        if "parent_id" in row {
            pv = row["parent_id"];
            if pv is not None {
                raw = pv;
            }
        }
        c = Comment(cid=cid, thread_id=tid, raw_parent=raw);
        by_id[cid] = c;
    }
    for row in comments {
        cid: str = row["id"];
        raw: str = by_id[cid].raw_parent;
        parent_eff: str = "";
        if raw == cid {
            parent_eff = "";
        } elif raw != "" and raw in by_id {
            if by_id[raw].thread_id == by_id[cid].thread_id {
                parent_eff = raw;
            }
        }
        eff[cid] = parent_eff;
        by_id[cid].eff_parent = parent_eff;
    }
    return eff;
}

def depth_of(comment_id: str, effective: dict[str, str]) -> int {
    seen: dict[str, bool] = {};
    depth: int = 0;
    cur: str = comment_id;
    while cur != "" {
        if cur in seen {
            return 1;
        }
        seen[cur] = True;
        depth = depth + 1;
        nxt: str = "";
        if cur in effective {
            nxt = effective[cur];
        }
        if nxt == "" {
            break;
        }
        cur = nxt;
    }
    return depth;
}

def attach_eff_graph(comments: list, eff: dict[str, str]) -> GraphRoot {
    graph_root = GraphRoot();
    by_id: dict[str, Comment] = {};
    for row in comments {
        cid: str = row["id"];
        c = Comment(cid=cid, thread_id=row["thread_id"]);
        by_id[cid] = c;
        graph_root ++> c;
    }
    for cid in by_id {
        c = by_id[cid];
        p: str = "";
        if cid in eff {
            p = eff[cid];
        }
        c.eff_parent = p;
        if p != "" and p in by_id {
            c +>:ParentEdge:+> by_id[p];
        }
    }
    return graph_root;
}

def reroot_cycle_members(eff: dict[str, str], comments: list) -> list[str] {
    graph_root = attach_eff_graph(comments, eff);
    all_cycle: dict[str, bool] = {};
    for row in comments {
        start: str = row["id"];
        kids: list[Comment] = [graph_root ->:][?:Comment];
        start_nd: Comment | None = None;
        for nd in kids {
            if nd.cid == start {
                start_nd = nd;
            }
        }
        if start_nd is not None {
            pw = start_nd spawn ParentFollowWalker();
            if pw.hit_cycle {
                for k in pw.cycle_set {
                    if pw.cycle_set[k] {
                        all_cycle[k] = True;
                    }
                }
            }
        }
    }
    rerooted: list[str] = [];
    for cid in all_cycle {
        if all_cycle[cid] {
            eff[cid] = "";
            rerooted.append(cid);
        }
    }
    return sorted(rerooted);
}

def run_import_plan(comments: list) -> dict {
    eff: dict[str, str] = build_effective_parent(comments);
    rerooted: list[str] = reroot_cycle_members(eff, comments);
    depths: dict[str, int] = {};
    cids: list[str] = [];
    for row in comments {
        cids.append(row["id"]);
    }
    for cid in cids {
        depths[cid] = depth_of(cid, eff);
    }
    roots: list[str] = [];
    for cid in cids {
        p: str = "";
        if cid in eff {
            p = eff[cid];
        }
        if p == "" {
            roots.append(cid);
        }
    }
    return {
        "effective_parent": eff,
        "depths": depths,
        "rerooted": rerooted,
        "roots": sorted(roots),
    };
}
