"""Recursive layer-name resolution for Keras-like model graphs — sicara/tf-explain#63."""

node Layer {
    has lid: str;
    has name: str;
    has is_group: bool = False;
}

edge Contains {}

walker CollectWalker {
    has claimed: dict[str, bool] = {};
    has targets: dict[str, bool] = {};
    has hits: list[str] = [];
    has names: list[str] = [];

    can visit_layer with Layer entry {
        if here.lid in self.claimed {
            skip;
        }
        self.claimed[here.lid] = True;
        self.names.append(here.name);
        if here.name in self.targets {
            self.hits.append(here.name);
        }
        print(here.name);
        kids: list[Layer] = [here ->:Contains:->][?:Layer];
        for kid in kids {
            visit :0: [kid];
        }
    }
}

walker DepthWalker {
    has claimed: dict[str, bool] = {};
    has target: str = "";
    has depth: int = -1;
    has cur: int = 0;
    has found: bool = False;

    can measure with Layer entry {
        if here.lid in self.claimed {
            skip;
        }
        self.claimed[here.lid] = True;
        if here.name == self.target {
            self.depth = self.cur;
            self.found = True;
            print(self.depth);
            disengage;
        }
        kids: list[Layer] = [here ->:Contains:->][?:Layer];
        for kid in kids {
            self.cur = self.cur + 1;
            visit :0: [kid];
            self.cur = self.cur - 1;
        }
    }
}

def spawn_layer(lid: str, name: str, is_group: bool = False) -> Layer {
    return Layer(lid=lid, name=name, is_group=is_group);
}

def link(parent: Layer, child: Layer) -> None {
    parent +>:Contains:+> child;
}

def enumerate_layers(graph_root: Layer) -> list[str] {
    w = graph_root spawn CollectWalker(
        claimed={},
        targets={},
        hits=[],
        names=[]
    );
    out: list[str] = [];
    for nm in w.names {
        out.append(nm);
    }
    out.sort();
    return out;
}

def resolve_layers_name(
    graph_root: Layer,
    layers_name: list[str],
) -> tuple[list[str], list[str]] {
    targets: dict[str, bool] = {};
    for nm in layers_name {
        targets[nm] = True;
    }
    w = graph_root spawn CollectWalker(
        claimed={},
        targets=targets,
        hits=[],
        names=[]
    );
    hit_set: dict[str, bool] = {};
    for h in w.hits {
        hit_set[h] = True;
    }
    found: list[str] = [];
    missing: list[str] = [];
    for nm in layers_name {
        if nm in hit_set {
            found.append(nm);
        } else {
            missing.append(nm);
        }
    }
    found.sort();
    missing.sort();
    print(found);
    return (found, missing);
}

def layer_depth(graph_root: Layer, layer_name: str) -> int {
    w = graph_root spawn DepthWalker(
        claimed={},
        target=layer_name,
        depth=-1,
        cur=0,
        found=False
    );
    if w.found {
        return w.depth;
    }
    print(-1);
    return -1;
}
