def _dedupe_sorted_edges(raw: list[list[str]]) -> list[list[str]] {
    out: list[list[str]] = [];
    seen: dict[str, bool] = {};
    for row in raw {
        key = row[0] + "\t" + row[1];
        if key not in seen {
            seen[key] = True;
            out.append(row);
        }
    }
    out = sorted(out);
    return out;
}

def _zero_matrix(n: int) -> list[list[int]] {
    mat: list[list[int]] = [];
    ri: int = 0;
    while ri < n {
        row: list[int] = [];
        ci: int = 0;
        while ci < n {
            row.append(0);
            ci += 1;
        }
        mat.append(row);
        ri += 1;
    }
    return mat;
}

def build_graph(graph_name: str, node_ids: list[str], edge_pairs: list[list[str]]) -> CoCitationGraph {
    g = CoCitationGraph(graph_name=graph_name);
    root ++> g;
    id_map: dict[str, CitationNode] = {};
    for nid in node_ids {
        nd = CitationNode(cid=nid, label=nid);
        id_map[nid] = nd;
        g ++> nd;
    }
    for pair in edge_pairs {
        a = pair[0];
        b = pair[1];
        if a in id_map and b in id_map {
            src = id_map[a];
            dst = id_map[b];
            src +>:Citation:+> dst;
        }
    }
    return g;
}

def export_edge_list(graph_root: CoCitationGraph) -> list[list[str]] {
    nodes: list[CitationNode] = [];
    for nd in [graph_root ->][?:CitationNode] {
        nodes.append(nd);
    }
    sorted_nodes: list[CitationNode] = _sort_nodes_by_cid(nodes);
    merged: list[list[str]] = [];
    outside_claimed: dict[str, bool] = {};
    for nd in sorted_nodes {
        if nd.cid not in outside_claimed {
            w = nd spawn EdgeCollector(claimed={});
            for row in w.edges {
                merged.append(row);
            }
            for vid in w.visited_order {
                outside_claimed[vid] = True;
            }
        }
    }
    return _dedupe_sorted_edges(merged);
}

def export_adjacency_matrix(graph_root: CoCitationGraph, node_order: list[str]) -> list[list[int]] {
    edges = export_edge_list(graph_root);
    idx: dict[str, int] = {};
    i: int = 0;
    for nid in node_order {
        idx[nid] = i;
        i += 1;
    }
    n = len(node_order);
    mat = _zero_matrix(n);
    for pair in edges {
        a = pair[0];
        b = pair[1];
        if a in idx and b in idx {
            mat[idx[a]][idx[b]] = 1;
        }
    }
    return mat;
}

def bfs_spanning_tree(graph_root: CoCitationGraph, root_id: str) -> list[list[str]] {
    start = _find_node(graph_root, root_id);
    if start is None {
        return [];
    }
    w = start spawn BfsTreeWalker(claimed={});
    return w.tree_edges;
}
