    has cid: str;
    has val: int;
}

node AstUnOp {
    has cid: str;
    has op: str;
}

node AstCall {
    has cid: str;
    has fname: str;
}

node AstFork {
    has cid: str;
}

edge Child {}

def parse_unary_depth(tokens: list[str]) -> int {
    depth = 0;
    for tok in tokens {
        if tok == "+" or tok == "-" {
            depth += 1;
        } else {
            break;
        }
    }
    return depth;
}

def eval_ast_safe(
    store: dict[str, object],
    root_cid: str,
    funcs: dict[str, str],
) -> int | None {
    if root_cid not in store {
        return None;
    }
    start = store[root_cid];
    w = start spawn EvalW(store=store, funcs=funcs, claimed={});
    if w.cycle {
        return None;
    }
    return w.result;
}

def funcs_have_cycle(store: dict[str, object], funcs: dict[str, str]) -> bool {
    names: list[str] = sorted(funcs);
    for fname in names {
        body_cid = funcs[fname];
        if body_cid not in store {
            continue;
        }
        body = store[body_cid];
        w = body spawn CycleW(store=store, funcs=funcs, claimed={});
        if w.found {
            return True;
        }
    }
    return False;
}

def diamond_revisit_skips(store: dict[str, object], entry_cid: str) -> int {
    if entry_cid not in store {
        return 0;
    }
    entry = store[entry_cid];
    w = entry spawn DiamondW(claimed={});
    return w.skips;
}

walker EvalW {
    has store: dict[str, object] = {};
    has funcs: dict[str, str] = {};
    has claimed: dict[str, bool] = {};
    has result: int = 0;
    has cycle: bool = False;

    can eval_num with AstNum entry {
        if here.cid in self.claimed {
            self.cycle = True;
            skip;
        }
        self.claimed[here.cid] = True;
        self.result = here.val;
        print ["eval_num", here.cid, self.result];
        disengage;
    }

    can eval_un with AstUnOp entry {
        if here.cid in self.claimed {
            self.cycle = True;
            skip;
        }
        self.claimed[here.cid] = True;
        kids_n: list[AstNum] = [];
        for ch in [here ->:Child:->][?:AstNum] {
            kids_n.append(ch);
        }
        kids_u: list[AstUnOp] = [];
        for ch in [here ->:Child:->][?:AstUnOp] {
            kids_u.append(ch);
        }
        kids_c: list[AstCall] = [];
        for ch in [here ->:Child:->][?:AstCall] {
            kids_c.append(ch);
        }
        if len(kids_n) > 0 {
            visit :0: kids_n;
        } elif len(kids_u) > 0 {
            visit :0: kids_u;
        } elif len(kids_c) > 0 {
            visit :0: kids_c;
        } else {
            self.result = 0;
            print ["eval_un_empty", here.cid];
            disengage;
        }
        if self.cycle {
            disengage;
        }
        v = self.result;
        if here.op == "-" {
            v = 0 - v;
        }
        self.result = v;
        print ["eval_un", here.cid, self.result];
        disengage;
    }

    can eval_call with AstCall entry {
        if here.cid in self.claimed {
            self.cycle = True;
            skip;
        }
        self.claimed[here.cid] = True;
        if here.fname not in self.funcs {
            self.result = 0;
            print ["eval_call_unknown", here.fname];
            disengage;
        }
        body_cid = self.funcs[here.fname];
        if body_cid not in self.store {
            self.result = 0;
            print ["eval_body_unknown", body_cid];
            disengage;
        }
        body = self.store[body_cid];
        visit :0: [body];
        if self.cycle {
            disengage;
        }
        print ["eval_call", here.fname, self.result];
        disengage;
    }
}

walker CycleW {
    has store: dict[str, object] = {};
    has funcs: dict[str, str] = {};
    has claimed: dict[str, bool] = {};
    has found: bool = False;

    can probe_num with AstNum entry {
        print ["probe_num", here.cid];
        disengage;
    }

    can probe_un with AstUnOp entry {
        if here.cid in self.claimed {
            self.found = True;
            skip;
        }
        self.claimed[here.cid] = True;
        print ["probe_un", here.cid];
        kids_c: list[AstCall] = [];
        for ch in [here ->:Child:->][?:AstCall] {
            kids_c.append(ch);
        }
        if len(kids_c) > 0 {
            visit :0: kids_c;
        } else {
            disengage;
        }
    }

    can probe_call with AstCall entry {
        if here.cid in self.claimed {
            self.found = True;
            skip;
        }
        self.claimed[here.cid] = True;
        print ["probe_call", here.cid, here.fname];
        if here.fname not in self.funcs {
            disengage;
        }
        body_cid = self.funcs[here.fname];
        if body_cid not in self.store {
            disengage;
        }
        body = self.store[body_cid];
        visit :0: [body];
        disengage;
    }
}

walker DiamondW {
    has claimed: dict[str, bool] = {};
    has skips: int = 0;
    has visit_count: int = 0;

    can walk_fork with AstFork entry {
        if here.cid in self.claimed {
            self.skips += 1;
            skip;
        }
        self.claimed[here.cid] = True;
        self.visit_count += 1;
        print ["walk_fork", here.cid, self.visit_count];
        has_kids: bool = False;
        kids_f: list[AstFork] = [];
        for ch in [here ->:Child:->][?:AstFork] {
            kids_f.append(ch);
        }
        for ch in kids_f {
            has_kids = True;
            visit :0: [ch];
        }
        kids_n: list[AstNum] = [];
        for ch in [here ->:Child:->][?:AstNum] {
            kids_n.append(ch);
        }
        for ch in kids_n {
            has_kids = True;
            visit :0: [ch];
        }
        if not has_kids {
            disengage;
        }
    }

    can walk_num with AstNum entry {
        if here.cid in self.claimed {
            self.skips += 1;
            skip;
        }
        self.claimed[here.cid] = True;
        self.visit_count += 1;
        print ["walk_num", here.cid, self.visit_count];
        disengage;
    }
}
