def build_method_cfg(specs: list[tuple[str, list[str], str]]) -> CfgHandle {
    gr = CfgRoot();
    root ++> gr;
    h = CfgHandle(graph_root=gr);
    for spec in specs {
        lbl = spec[0];
        nd = BytecodeBlock(label=lbl, jsr_target=spec[2]);
        gr ++> nd;
        h.blocks[lbl] = nd;
    }
    for spec in specs {
        lbl = spec[0];
        src = h.blocks[lbl];
        fall_lbls: list[str] = spec[1];
        for tgt_lbl in fall_lbls {
            if tgt_lbl in h.blocks {
                dst = h.blocks[tgt_lbl];
                src +>:FallThrough:+> dst;
            }
        }
        jsr_lbl = spec[2];
        if jsr_lbl != "" {
            if jsr_lbl in h.blocks {
                jdst = h.blocks[jsr_lbl];
                src +>:JsrCall:+> jdst;
            }
        }
    }
    return h;
}

def reachable_labels(h: CfgHandle, start: str) -> list[str] {
    if start not in h.blocks {
        return [];
    }
    src = h.blocks[start];
    wk = src spawn ReachWalker(claimed={});
    out: list[str] = wk.found;
    return sorted(out);
}

def revisit_labels(h: CfgHandle, start: str) -> list[str] {
    if start not in h.blocks {
        return [];
    }
    src = h.blocks[start];
    wk = src spawn ReachWalker(claimed={});
    out: list[str] = wk.revisit;
    return sorted(out);
}

def decompile_safe(h: CfgHandle, start: str) -> bool {
    rv = revisit_labels(h, start);
    return len(rv) == 0;
}
