"""YourTechBudStudio/Raphael#1 — durable hierarchical text notes with favorites."""

node RaphaelNode {
    has nid: str;
    has title: str;
    has kind: str;
    has body: str = "";
    has archived: bool = False;
}

edge Contains {}

obj NoteStore {
    has graph_root: RaphaelNode;
    has fav_ids: list[str] = [];
}

walker NodeFinder {
    has target: str;
    has found: RaphaelNode | None = None;
    has claimed: dict[str, bool] = {};
    can probe with RaphaelNode entry {
        if here.nid in self.claimed { skip; }
        self.claimed[here.nid] = True;
        print(["find", here.nid, self.target]);
        if here.nid == self.target {
            self.found = here;
            disengage;
        }
        kids: list[RaphaelNode] = [];
        for ch in [here ->:Contains:->][?:RaphaelNode] {
            kids.append(ch);
        }
        if kids { visit :0: kids; } else { disengage; }
    }
}

walker DescendantCollector {
    has claimed: dict[str, bool] = {};
    has seen_out: dict[str, bool] = {};
    has out: list[str] = [];
    can walk with RaphaelNode entry {
        if here.nid in self.claimed { skip; }
        self.claimed[here.nid] = True;
        print(["desc", here.nid]);
        kids: list[RaphaelNode] = [];
        for ch in [here ->:Contains:->][?:RaphaelNode] {
            if not ch.archived and ch.nid not in self.seen_out {
                self.out.append(ch.nid);
                self.seen_out[ch.nid] = True;
            }
            kids.append(ch);
        }
        if kids { visit :0: kids; } else { disengage; }
    }
}

walker NoteSearcher {
    has query: str;
    has claimed: dict[str, bool] = {};
    has hits: list[str] = [];
    can search with RaphaelNode entry {
        if here.nid in self.claimed { skip; }
        self.claimed[here.nid] = True;
        print(["search", here.nid, self.query]);
        q = self.query.lower();
        if here.kind == "note" and not here.archived {
            if q in here.title.lower() or q in here.body.lower() {
                self.hits.append(here.nid);
            }
        }
        kids: list[RaphaelNode] = [];
        for ch in [here ->:Contains:->][?:RaphaelNode] {
            kids.append(ch);
        }
        if kids { visit :0: kids; } else { disengage; }
    }
}

def make_store() -> NoteStore {
    graph_root = RaphaelNode(nid="root", title="root", kind="area");
    s = NoteStore(graph_root=graph_root);
    return s;
}

def find_node_by_id(graph_root: RaphaelNode, target_nid: str) -> RaphaelNode | None {
    w = graph_root spawn NodeFinder(target=target_nid, claimed={});
    return w.found;
}

def create_node(
    store: NoteStore,
    nid: str,
    parent_nid: str,
    kind: str,
    title: str,
    body: str = "",
) -> RaphaelNode | None {
    parent = find_node_by_id(store.graph_root, parent_nid);
    if parent is None { return None; }
    nd = RaphaelNode(nid=nid, title=title, kind=kind, body=body);
    parent +>:Contains:+> nd;
    return nd;
}

def get_node(store: NoteStore, nid: str) -> RaphaelNode | None {
    return find_node_by_id(store.graph_root, nid);
}

def list_children(store: NoteStore, parent_nid: str, recursive: bool = False) -> list[str] {
    parent = find_node_by_id(store.graph_root, parent_nid);
    if parent is None { return []; }
    if not recursive {
        direct: list[str] = [];
        for ch in [parent ->:Contains:->][?:RaphaelNode] {
            if not ch.archived { direct.append(ch.nid); }
        }
        return sorted(direct);
    }
    w = parent spawn DescendantCollector(claimed={}, seen_out={});
    return sorted(w.out);
}

def add_favorite(store: NoteStore, nid: str) -> bool {
    nd = find_node_by_id(store.graph_root, nid);
    if nd is None { return False; }
    for fid in store.fav_ids {
        if fid == nid { return True; }
    }
    store.fav_ids.append(nid);
    return True;
}

def remove_favorite(store: NoteStore, nid: str) -> bool {
    kept: list[str] = [];
    removed = False;
    for fid in store.fav_ids {
        if fid == nid { removed = True; }
        else { kept.append(fid); }
    }
    store.fav_ids = kept;
    return removed;
}

def list_favorites(store: NoteStore) -> list[str] {
    visible: list[str] = [];
    for fid in store.fav_ids {
        nd = find_node_by_id(store.graph_root, fid);
        if nd is not None and not nd.archived { visible.append(fid); }
    }
    ordered: list[str] = [];
    used: dict[str, bool] = {};
    total = len(visible);
    picked = 0;
    while picked < total {
        best_nid = "";
        best_key = "";
        for cand in visible {
            if cand in used { continue; }
            nd2 = find_node_by_id(store.graph_root, cand);
            if nd2 is None { continue; }
            key = nd2.title + "\0" + cand;
            if best_nid == "" or key < best_key {
                best_nid = cand;
                best_key = key;
            }
        }
        ordered.append(best_nid);
        used[best_nid] = True;
        picked += 1;
    }
    return ordered;
}

def archive_node(store: NoteStore, nid: str) -> bool {
    nd = find_node_by_id(store.graph_root, nid);
    if nd is None { return False; }
    nd.archived = True;
    return True;
}

def restore_node(store: NoteStore, nid: str) -> bool {
    nd = find_node_by_id(store.graph_root, nid);
    if nd is None { return False; }
    nd.archived = False;
    return True;
}

def search_notes(
    store: NoteStore,
    root_nid: str,
    query: str,
    recursive: bool = True,
) -> list[str] {
    scope = find_node_by_id(store.graph_root, root_nid);
    if scope is None { return []; }
    if not recursive {
        hits: list[str] = [];
        q = query.lower();
        for ch in [scope ->:Contains:->][?:RaphaelNode] {
            if ch.kind == "note" and not ch.archived {
                if q in ch.title.lower() or q in ch.body.lower() {
                    hits.append(ch.nid);
                }
            }
        }
        return sorted(hits);
    }
    w = scope spawn NoteSearcher(query=query, claimed={});
    return sorted(w.hits);
}
