def _path_join(prefix: str, key: str) -> str {
    if prefix == "" { return key; }
    return prefix + "." + key;
}

def _attach_dict(parent: Field, values: dict, prefix: str, depth: int, memo: dict[int, Field]) -> None {
    keys: list[str] = sorted(values.keys());
    for k in keys {
        v = values[k];
        p: str = _path_join(prefix, k);
        if v is dict {
            oid: int = id(v);
            if oid in memo {
                shared: Field = memo[oid];
                parent +>:Child:+> shared;
            } else {
                obj = Field(key=k, kind="object", path=p, depth=depth + 1);
                memo[oid] = obj;
                parent +>:Child:+> obj;
                _attach_dict(obj, v as dict[str, object], p, depth + 1, memo);
            }
        } elif v is list {
            arr = Field(key=k, kind="array", path=p, depth=depth + 1);
            parent +>:Child:+> arr;
            i: int = 0;
            while i < len(v) {
                item = v[i];
                ip: str = p + "[" + str(i) + "]";
                if item is dict {
                    oid2: int = id(item);
                    if oid2 in memo {
                        shared2: Field = memo[oid2];
                        arr +>:Child:+> shared2;
                    } else {
                        obj2 = Field(key=str(i), kind="object", path=ip, depth=depth + 2);
                        memo[oid2] = obj2;
                        arr +>:Child:+> obj2;
                        _attach_dict(obj2, item as dict[str, object], ip, depth + 2, memo);
                    }
                } else {
                    leaf = Field(key=str(i), kind="scalar", path=ip, depth=depth + 2, scal=str(item));
                    arr +>:Child:+> leaf;
                }
                i += 1;
            }
        } else {
            leaf2 = Field(key=k, kind="scalar", path=p, depth=depth + 1, scal=str(v));
            parent +>:Child:+> leaf2;
        }
    }
