    _attach_dict(root_nd, values, "", 0, memo);
    return root_nd;
}

def field_paths(values: dict, max_depth: int = 64) -> list[str] {
    graph_root = _graph_root(values);
    w = graph_root spawn CollectPaths(max_depth=max_depth);
    return sorted(w.paths);
}

def field_depth(values: dict) -> int {
    graph_root = _graph_root(values);
    w = graph_root spawn DepthProbe();
    return w.max_seen;
}

def exceeds_type_depth(values: dict, limit: int = 50) -> bool {
    return field_depth(values) > limit;
}

def provider_field_paths(values: dict, provider_keys: list[str]) -> list[str] {
    out: list[str] = [];
    keys: list[str] = sorted(provider_keys);
    for pk in keys {
        if pk not in values { continue; }
        sub: dict[str, object] = {};
        sub[pk] = values[pk];
        paths: list[str] = field_paths(sub);
        for p in paths {
            out.append(p);
        }
    }
    return sorted(out);
}
