def _attach_dict(parent: Field, values: dict[str, object], prefix: str, depth: int, memo: dict[int, Field]) {
    keys: list[str] = sorted(values.keys());
    for k in keys {
        v: object = values[k];
        p: str = _path_join(prefix, k);
        if v is dict {
            vd: dict[str, object] = v as dict[str, object];
            oid: int = id(vd);
            if oid in memo {
                shared: Field = memo[oid];
                parent +>:Child:+> shared;
            } else {
                obj: Field = Field(key=k, kind="object", path=p, depth=depth + 1);
                memo[oid] = obj;
                parent +>:Child:+> obj;
                _attach_dict(obj, vd, p, depth + 1, memo);
