                        memo[oid2] = obj2;
                        arr +>:Child:+> obj2;
                        _attach_dict(obj2, idct, ip, depth + 2, memo);
                    }
                } else {
                    leaf: Field = Field(key=str(i), kind="scalar", path=ip, depth=depth + 2, scal=str(item));
                    arr +>:Child:+> leaf;
                }
