def _path_join(prefix: str, key: str) -> str {
    if prefix == "" { return key; }
    return prefix + "." + key;
}

def _attach_dict(parent: Field, values: dict[str, object], prefix: str, depth: int, memo: dict[int, Field]) {
    keys: list[str] = sorted(values.keys());
    for k in keys {
        v: object = values[k];
        p: str = _path_join(prefix, k);
        if v is dict {
            vd: dict[str, object] = v as dict[str, object];
            oid: int = id(vd);
            if oid in memo {
                shared: Field = memo[oid];
                parent +>:Child:+> shared;
            } else {
                obj: Field = Field(key=k, kind="object", path=p, depth=depth + 1);
                memo[oid] = obj;
                parent +>:Child:+> obj;
                _attach_dict(obj, vd, p, depth + 1, memo);
            }
        } elif v is list {
            lst: list[object] = v as list[object];
            arr: Field = Field(key=k, kind="array", path=p, depth=depth + 1);
            parent +>:Child:+> arr;
            i: int = 0;
            while i < len(lst) {
                item: object = lst[i];
                ip: str = p + "[" + str(i) + "]";
                if item is dict {
                    idct: dict[str, object] = item as dict[str, object];
                    oid2: int = id(idct);
                    if oid2 in memo {
                        shared2: Field = memo[oid2];
                        arr +>:Child:+> shared2;
                    } else {
                        obj2: Field = Field(key=str(i), kind="object", path=ip, depth=depth + 2);
                        memo[oid2] = obj2;
                        arr +>:Child:+> obj2;
                        _attach_dict(obj2, idct, ip, depth + 2, memo);
                    }
                } else {
                    leaf: Field = Field(key=str(i), kind="scalar", path=ip, depth=depth + 2, scal=str(item));
                    arr +>:Child:+> leaf;
                }
                i += 1;
            }
        } else {
            leaf2: Field = Field(key=k, kind="scalar", path=p, depth=depth + 1, scal=str(v));
            parent +>:Child:+> leaf2;
        }
    }
}

def _graph_root(values: dict[str, object]) -> Field {
    memo: dict[int, Field] = {};
    root_nd: Field = Field(key="root", kind="object", path="", depth=0);
    root ++> root_nd;
    _attach_dict(root_nd, values, "", 0, memo);
    return root_nd;
}

def field_paths(values: dict[str, object], max_depth: int = 64) -> list[str] {
    graph_root = _graph_root(values);
    w = graph_root spawn CollectPaths(max_depth=max_depth);
    return sorted(w.paths);
}

def field_depth(values: dict[str, object]) -> int {
    graph_root = _graph_root(values);
    w = graph_root spawn DepthProbe();
    return w.max_seen;
}

def exceeds_type_depth(values: dict[str, object], limit: int = 50) -> bool {
    return field_depth(values) > limit;
}

def provider_field_paths(values: dict[str, object], provider_keys: list[str]) -> list[str] {
    out: list[str] = [];
    keys: list[str] = sorted(provider_keys);
    for pk in keys {
        if pk not in values { continue; }
        sub: dict[str, object] = {};
        sub[pk] = values[pk];
        paths: list[str] = field_paths(sub);
        for p in paths {
            out.append(p);
        }
    }
    return sorted(out);
}

