    eng = graph_root spawn CTEEngineWalker(
        nodes=coll.nodes,
        distinct_applied=distinct_applied,
        max_depth=max_depth,
        claimed={}
    );
    print "execute_cte_limit";
    return eng.limit_hit;
}

def recurse_cte_names(graph_root: Person, distinct: bool, max_depth: int = 50) -> list[str] {
    rows: list[str] = execute_cte(graph_root, distinct, max_depth);
    print "recurse_cte_names";
    return sort_names(rows);
}

def unmerged_distinct_names(graph_root: Person, max_depth: int = 50) -> list[str] {
    # Planner records DISTINCT but engine omits seen-set — UNION ALL semantics.
    rows: list[str] = execute_cte(graph_root, False, max_depth);
    print "unmerged_distinct_names";
    return sort_names(rows);
}

def recursion_limit_hit(graph_root: Person, max_depth: int = 10) -> bool {
    hit: bool = execute_cte_limit(graph_root, False, max_depth);
    print "recursion_limit_hit " + str(hit);
    return hit;
}
