"""
adrianbrowning/prisma-ts-select#162 — typed recursive CTE hierarchy traversal.
"""

node Row {
    has row_id: str;
    has label: str;
    has depth: int = 0;
}

edge HierarchyLink {}

node RecursiveCte {
    has name: str;
    has columns: list[str] = [];
    has anchor_ids: list[str] = [];
}

walker RecursiveTraverseWalker {
    has claimed: dict[str, bool] = {};
    has results: list[dict] = [];
    has columns: list[str] = [];

    can expand with Row entry {
        if here.row_id in self.claimed {
            skip;
        }
        self.claimed[here.row_id] = True;
        row_out: dict = {};
        for col in self.columns {
            if col == "id" {
                row_out["id"] = here.row_id;
            } elif col == "label" {
                row_out["label"] = here.label;
            } elif col == "depth" {
                row_out["depth"] = here.depth;
            }
        }
        self.results.append(row_out);
        print("recursive_union", here.row_id, here.depth);
        children: list[Row] = [];
        for ch in [here ->:HierarchyLink:->][?:Row] {
            children.append(ch);
        }
        visit :0: children;
    }
}

walker CteOrchestratorWalker {
    has claimed: dict[str, bool] = {};
    has results: list[dict] = [];
    has columns: list[str] = [];
    has anchor_ids: list[str] = [];

    can launch with Row entry {
        is_anchor: bool = False;
        for aid in self.anchor_ids {
            if aid == here.row_id {
                is_anchor = True;
            }
        }
        if is_anchor {
            exp = here spawn RecursiveTraverseWalker(
                claimed=self.claimed,
                results=self.results,
                columns=self.columns
            );
            self.claimed = exp.claimed;
            self.results = exp.results;
        }
        print("orchestrate", here.row_id);
        remaining: list[Row] = [];
        for nd in [root-->][?:Row] {
            if nd.row_id != here.row_id {
                remaining.append(nd);
            }
        }
        if remaining.length > 0 {
            visit :0: remaining;
        } else {
            disengage;
        }
    }
}

def register_row(row_id: str, label: str, depth: int = 0) -> Row {
    nd = Row(row_id=row_id, label=label, depth=depth);
    root ++> nd;
    return nd;
}

def find_row(row_id: str) -> Row | None {
    for nd in [root-->][?:Row] {
        if nd.row_id == row_id {
            return nd;
        }
    }
    return None;
}

def link_rows(parent_id: str, child_id: str) -> bool {
    parent_nd = find_row(parent_id);
    child_nd = find_row(child_id);
    if parent_nd is None or child_nd is None {
        return False;
    }
    parent_nd +>:HierarchyLink:+> child_nd;
    return True;
}

def with_recursive(name: str, anchor_cols: list[str], recursive_cols: list[str]) -> RecursiveCte {
    if len(anchor_cols) != len(recursive_cols) {
        raise ValueError;
    }
    cols: list[str] = [];
    for c in anchor_cols {
        cols.append(c);
    }
    cte = RecursiveCte(name=name, columns=cols, anchor_ids=[]);
    root ++> cte;
    return cte;
}

def set_anchor_ids(cte: RecursiveCte, ids: list[str]) -> None {
    anchors: list[str] = [];
    for i in ids {
        anchors.append(i);
    }
    cte.anchor_ids = anchors;
}

def validate_projection(anchor_cols: list[str], recursive_cols: list[str]) -> bool {
    return len(anchor_cols) == len(recursive_cols);
}

def sort_results(rows: list[dict]) -> list[dict] {
    keys: list[str] = [];
    for r in rows {
        keys.append(r["id"] as str);
    }
    keys = sorted(keys);
    ordered: list[dict] = [];
    for k in keys {
        for r in rows {
            rid = r["id"] as str;
            if rid == k {
                ordered.append(r);
            }
        }
    }
    return ordered;
}

def run_recursive_cte(cte: RecursiveCte) -> list[dict] {
    w = root spawn CteOrchestratorWalker(
        claimed={},
        results=[],
        columns=cte.columns,
        anchor_ids=cte.anchor_ids
    );
    return sort_results(w.results);
}

def build_sql_fragment(cte: RecursiveCte) -> str {
    col_sql: list[str] = [];
    for c in cte.columns {
        col_sql.append(c);
    }
    joined = "";
    for i in range(len(col_sql)) {
        if i > 0 {
            joined = joined + ", ";
        }
        joined = joined + col_sql[i];
    }
    return "WITH RECURSIVE " + cte.name + " AS (anchor UNION ALL recursive) SELECT " + joined + " FROM " + cte.name;
}
