}

def build_diamond_plan -> str {
    sc = Scan(table="items", nid="scan_d");
    f1 = Filter(predicate="a > 0", nid="f1");
    f2 = Filter(predicate="b > 0", nid="f2");
    top = Project(exprs=["x"], nid="top_d");
    root ++> top;
    top +>:Child:+> f1;
    top +>:Child:+> f2;
    f1 +>:Child:+> sc;
    f2 +>:Child:+> sc;
