def rewrite_remove_filters(plan_root: str) -> str {
    nd = find_node_by_nid(plan_root);
    if nd is None {
        return plan_root;
    }
    w = nd spawn CollectFilters(claimed={});
    ordered: list[str] = sorted(w.targets);
    for fid in ordered {
        filt = find_node_by_nid(fid);
        if filt is None {
            continue;
        }
        par = parent_of(filt);
        ch = child_of(filt);
        if par is not None and ch is not None {
            par -: Child :- filt;
            par +>:Child:+> ch;
        }
    }
    return plan_root;
