edge ParentChild {}

def index_nodes(edges: list[tuple[str, str]]) -> dict[str, Entity] {
    nodes: dict[str, Entity] = {};
    for e in edges {
        p: str = e[0];
        c: str = e[1];
        if p not in nodes {
            pn = Entity(cid=p);
            root ++> pn;
            nodes[p] = pn;
        }
        if c not in nodes {
            cn = Entity(cid=c);
            root ++> cn;
            nodes[c] = cn;
        }
        pa = nodes[p] as Entity;
        ch = nodes[c] as Entity;
        pa +>:ParentChild:+> ch;
    }
    return nodes;
}

walker DescendWalker {
    has claimed: dict[str, bool] = {};
    has acc: list[str] = [];

    can descend with Entity entry {
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        self.acc.append(here.cid);
        print("descend ", here.cid);
        kids: list[Entity] = [here ->:ParentChild:->][?:Entity];
        if kids {
            visit :0: kids;
        } else {
            disengage;
        }
    }
}

walker AscendWalker {
    has claimed: dict[str, bool] = {};
    has acc: list[str] = [];

    can ascend with Entity entry {
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        self.acc.append(here.cid);
        print("ascend ", here.cid);
        pars: list[Entity] = [here <-:ParentChild:-][?:Entity];
        if pars {
            visit :0: pars;
        } else {
            disengage;
        }
    }
}

def descendants_of(edges: list[tuple[str, str]], node_id: str) -> list[str] {
