"""Self-referencing collection hierarchies — appwrite/appwrite#9471."""

node Doc {
    has doc_id: str;
    has data: str;
}

edge Parent {}

obj CollectionGraph {
    has docs: dict[str, Doc] = {};
}

walker AncestorWalk {
    has claimed: dict[str, bool] = {};
    has found: list[str] = [];
    has skip_root: bool = True;

    can climb with Doc entry {
        if here.doc_id in self.claimed { skip; }
        self.claimed[here.doc_id] = True;
        if not self.skip_root {
            self.found.append(here.doc_id);
        }
        self.skip_root = False;
        print(["ancestor", here.doc_id]);
        parents: list[Doc] = [here ->:Parent:->][?:Doc];
        for p in parents {
            visit :0: [p];
        }
    }
}

walker DescendantWalk {
    has claimed: dict[str, bool] = {};
    has found: list[str] = [];

    can descend with Doc entry {
        if here.doc_id in self.claimed { skip; }
        self.claimed[here.doc_id] = True;
        print(["descendant", here.doc_id]);
        kids: list[Doc] = [here <-:Parent:<-][?:Doc];
        for kid in kids {
            visit :0: [kid];
        }
        self.found.append(here.doc_id);
    }
}

def new_store() -> CollectionGraph {
    return CollectionGraph();
}

def add_document(store: CollectionGraph, doc_id: str, data: str) -> bool {
    if doc_id in store.docs { return False; }
    nd = Doc(doc_id=doc_id, data=data);
    root ++> nd;
    store.docs[doc_id] = nd;
    return True;
}

def get_parent_id(store: CollectionGraph, doc_id: str) -> str | None {
    if doc_id not in store.docs { return None; }
    doc = store.docs[doc_id];
    parents: list[Doc] = [doc ->:Parent:->][?:Doc];
    if parents { return parents[0].doc_id; }
    return None;
}

def get_child_ids(store: CollectionGraph, doc_id: str) -> list[str] {
    if doc_id not in store.docs { return []; }
    doc = store.docs[doc_id];
    kids: list[Doc] = [doc <-:Parent:<-][?:Doc];
    ids: list[str] = [];
    for kid in kids {
        ids.append(kid.doc_id);
    }
    return sorted(ids);
}

def get_ancestor_ids(store: CollectionGraph, doc_id: str) -> list[str] {
    if doc_id not in store.docs { return []; }
    doc = store.docs[doc_id];
    w = doc spawn AncestorWalk(claimed={});
    return w.found;
}

def get_descendant_ids(store: CollectionGraph, doc_id: str) -> list[str] {
    if doc_id not in store.docs { return []; }
    doc = store.docs[doc_id];
    w = doc spawn DescendantWalk(claimed={});
    ids: list[str] = [];
    for did in w.found {
        if did != doc_id {
            ids.append(did);
        }
    }
    return sorted(ids);
}

def would_create_cycle(store: CollectionGraph, child_id: str, parent_id: str) -> bool {
    if child_id not in store.docs or parent_id not in store.docs { return False; }
    if child_id == parent_id { return True; }
    child = store.docs[child_id];
    w = child spawn DescendantWalk(claimed={});
    for did in w.found {
        if did == parent_id { return True; }
    }
    return False;
}

def clear_parent(store: CollectionGraph, doc_id: str) -> bool {
    if doc_id not in store.docs { return False; }
    child = store.docs[doc_id];
    parents: list[Doc] = [child ->:Parent:->][?:Doc];
    if not parents { return False; }
    for p in parents {
        child -:Parent:- p;
    }
    return True;
}

def set_parent(store: CollectionGraph, child_id: str, parent_id: str) -> bool {
    if child_id not in store.docs or parent_id not in store.docs { return False; }
    if would_create_cycle(store, child_id, parent_id) { return False; }
    child = store.docs[child_id];
    old_parents: list[Doc] = [child ->:Parent:->][?:Doc];
    for op in old_parents {
        child -:Parent:- op;
    }
    parent = store.docs[parent_id];
    child +>:Parent:+> parent;
    return True;
}
