test "diamond_revisit_descendant_closure" {
    store = new_store();
    add_document(store, "top", "t");
    add_document(store, "left", "l");
    add_document(store, "right", "r");
    add_document(store, "join", "j");
    add_document(store, "deep", "d");
    set_parent(store, "left", "top");
    set_parent(store, "right", "top");
    set_parent(store, "join", "left");
    set_parent(store, "deep", "join");
    set_parent(store, "join", "right");
    assert (get_descendant_ids(store, "top") == ["deep", "join", "left", "right"]);
    assert (get_ancestor_ids(store, "deep") == ["right", "join"]);
}

test "unknown_id_tolerance" {
    store = new_store();
    assert (get_parent_id(store, "missing") is None);
    assert (get_child_ids(store, "missing") == []);
    assert (get_ancestor_ids(store, "missing") == []);
    assert (get_descendant_ids(store, "missing") == []);
    assert (set_parent(store, "ghost", "also_ghost") == False);
    assert (add_document(store, "solo", "x") == True);
    assert (clear_parent(store, "solo") == False);
}

test "cycle_set_parent_blocked" {
    store = new_store();
    add_document(store, "a", "1");
    add_document(store, "b", "2");
    add_document(store, "c", "3");
    set_parent(store, "b", "a");
    set_parent(store, "c", "b");
    assert (would_create_cycle(store, "a", "c") == True);
    assert (set_parent(store, "a", "c") == False);
    assert (get_parent_id(store, "a") is None);
}

test "reparent_mutation_outside_walk" {
    store = new_store();
    add_document(store, "root", "r");
    add_document(store, "child", "c");
    add_document(store, "other", "o");
    set_parent(store, "child", "root");
    assert (get_parent_id(store, "child") == "root");
    assert (get_child_ids(store, "root") == ["child"]);
    set_parent(store, "child", "other");
    assert (get_parent_id(store, "child") == "other");
    assert (get_child_ids(store, "root") == []);
    assert (get_child_ids(store, "other") == ["child"]);
    assert (clear_parent(store, "child") == True);
    assert (get_parent_id(store, "child") is None);
}

test "linear_ancestor_chain" {
    store = new_store();
    add_document(store, "cat", "root");
    add_document(store, "sub", "mid");
    add_document(store, "leaf", "end");
    set_parent(store, "sub", "cat");
    set_parent(store, "leaf", "sub");
    assert (get_ancestor_ids(store, "leaf") == ["sub", "cat"]);
    assert (get_descendant_ids(store, "cat") == ["leaf", "sub"]);
}
