"""back2dos/tinkerbell#55 — cycle-safe toComplex with recursive constraint cache."""

node Type {
    has cid: str;
    has name: str;
}

edge Constrains {}

node GraphHandle {
    has types: dict[str, Type] = {};
}

walker ToComplexWalker {
    has cache: dict[str, str];
    has claimed: dict[str, bool] = {};
    has out: str = "";

    can resolve with Type entry {
        if here.cid in self.cache {
            self.out = self.cache[here.cid];
            print {"to_complex_cache_hit": here.cid, "out": self.out};
            disengage;
        }
        if here.cid in self.claimed {
            self.out = "REF(" + here.cid + ")";
            print {"to_complex_cycle_ref": here.cid};
            disengage;
        }
        self.claimed[here.cid] = True;
        kids: list[Type] = [here ->:Constrains:->][?:Type];
        kid_ids: list[str] = [];
        for ch in kids {
            kid_ids.append(ch.cid);
        }
        sorted_ids: list[str] = sorted(kid_ids);
        parts: list[str] = [];
        for sid in sorted_ids {
            ch_node: Type | None = None;
            for ch in kids {
                if ch.cid == sid {
                    ch_node = ch;
                }
            }
            if ch_node is not None {
                sub_cache: dict[str, str] = {};
                for k, v in self.cache {
                    sub_cache[k] = v;
                }
                sub_claimed: dict[str, bool] = {};
                for k, v in self.claimed {
                    sub_claimed[k] = v;
                }
                sub_w = ch_node spawn ToComplexWalker(cache=sub_cache, claimed=sub_claimed);
                parts.append(sub_w.out);
            }
        }
        inner = "";
        idx = 0;
        for p in parts {
            if idx > 0 {
                inner = inner + ",";
            }
            inner = inner + p;
            idx = idx + 1;
        }
        self.out = "Complex(" + here.name + ",[" + inner + "])";
        self.cache[here.cid] = self.out;
        print {"to_complex_resolved": here.cid, "out": self.out};
        disengage;
    }
}

walker ClosureWalker {
    has claimed: dict[str, bool] = {};
    has found: list[str] = [];

    can step with Type entry {
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        self.found.append(here.cid);
        print {"closure_visit": here.cid};
        kids: list[Type] = [here ->:Constrains:->][?:Type];
        if len(kids) > 0 {
            visit :0: kids;
        } else {
            disengage;
        }
    }
}

walker SmokeWalker {
    has claimed: dict[str, bool] = {};
    can step with Type entry {
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        print {"smoke": here.cid};
        disengage;
    }
}

def make_graph() -> GraphHandle {
    return GraphHandle();
}

def add_type(g: GraphHandle, cid: str, name: str) -> None {
    if cid in g.types {
        return;
    }
    nd = Type(cid=cid, name=name);
    root ++> nd;
    g.types[cid] = nd;
}

def add_constraint(g: GraphHandle, from_id: str, to_id: str) -> None {
    if from_id not in g.types {
        return;
    }
    if to_id not in g.types {
        return;
    }
    a = g.types[from_id];
    b = g.types[to_id];
    a +>:Constrains:+> b;
}

def to_complex(g: GraphHandle, type_id: str, cache: dict[str, str] | None = None) -> str {
    if type_id not in g.types {
        return "UNKNOWN";
    }
    c: dict[str, str] = {};
    if cache is not None {
        for k, v in cache {
            c[k] = v;
        }
    }
    claimed: dict[str, bool] = {};
    nd = g.types[type_id];
    w = nd spawn ToComplexWalker(cache=c, claimed=claimed);
    return w.out;
}

def constraint_closure(g: GraphHandle, type_id: str) -> list[str] {
    if type_id not in g.types {
        return [];
    }
    claimed: dict[str, bool] = {};
    nd = g.types[type_id];
    w = nd spawn ClosureWalker(claimed=claimed);
    return sorted(w.found);
}
