def add_type(g: GraphHandle, cid: str, name: str) -> None {
    if cid in g.types {
        return;
    }
    nd = Type(cid=cid, name=name);
    root ++> nd;
    g.types[cid] = nd;
}

def add_constraint(g: GraphHandle, from_id: str, to_id: str) -> None {
    if from_id not in g.types {
        return;
    }
    if to_id not in g.types {
        return;
    }
    a = g.types[from_id];
    b = g.types[to_id];
    a +>:Constrains:+> b;
}

def to_complex(g: GraphHandle, type_id: str, cache: dict[str, str] | None = None) -> str {
    if type_id not in g.types {
        return "UNKNOWN";
    }
    c: dict[str, str] = {};
    if cache is not None {
        for k in cache {
            c[k] = cache[k];
        }
    }
    claimed: dict[str, bool] = {};
    nd = g.types[type_id];
    w = nd spawn ToComplexWalker(cache=c, claimed=claimed);
    return w.out;
}

def constraint_closure(g: GraphHandle, type_id: str) -> list[str] {
    if type_id not in g.types {
        return [];
    }
    claimed: dict[str, bool] = {};
    nd = g.types[type_id];
    w = nd spawn ClosureWalker(claimed=claimed);
    return sorted(w.found);
}
