def build_and_link(units: list[dict]) -> dict[int, OrgUnit] {
    idx: dict[int, OrgUnit] = {};
    for row in units {
        uid: int = row["id"];
        nd = OrgUnit(cid=str(uid), uid=uid);
        root ++> nd;
        idx[uid] = nd;
    }
    for row in units {
        pid = row["parent_id"];
        if pid is not None {
            par = idx[pid];
            ch = idx[row["id"]];
            par +>:ParentOf:+> ch;
        }
        if "extra_parents" in row {
            extras: list = row["extra_parents"];
            ch = idx[row["id"]];
            for ep in extras {
                par = idx[ep];
                par +>:ParentOf:+> ch;
            }
        }
    }
    return idx;
}

