    claimed: dict[str, bool] = {};
    depths: dict[int, int] = {};
    wk = DepthWalker(claimed=claimed, depths=depths);
    for row in units {
        if row["parent_id"] is None {
            nd = idx[row["id"]];
            wk = nd spawn DepthWalker(claimed=claimed, depths=depths);
        }
