"""Derived view registry and recursive CTE depth lift — zenstackhq/zenstack#2363."""

node OrgUnit {
    has cid: str;
    has uid: int;
}

edge ParentOf {}

walker DepthWalker {
    has claimed: dict[str, bool] = {};
    has depths: dict[int, int] = {};

    can fill with OrgUnit entry {
        if here.cid in self.claimed { skip; }
        parents: list[OrgUnit] = [here <-:ParentOf:<-][?:OrgUnit];
        d: int = 1;
        if len(parents) > 0 {
            d = self.depths[parents[0].uid] + 1;
        }
        self.depths[here.uid] = d;
        self.claimed[here.cid] = True;
        kids: list[OrgUnit] = [here ->:ParentOf:->][?:OrgUnit];
        if len(kids) > 0 {
            visit kids;
        } else {
            disengage;
        }
        print(f"depth {here.uid} {d}");
    }
}

walker DescWalker {
    has claimed: dict[str, bool] = {};
    has found: list[int] = [];

    can collect with OrgUnit entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        self.found.append(here.uid);
        kids: list[OrgUnit] = [here ->:ParentOf:->][?:OrgUnit];
        if len(kids) > 0 {
            visit :0: kids;
        } else {
            disengage;
        }
        print(f"desc {here.uid}");
    }
}

def build_and_link(units: list[dict]) -> dict[int, OrgUnit] {
    idx: dict[int, OrgUnit] = {};
    for row in units {
        uid: int = row["id"];
        nd = OrgUnit(cid=str(uid), uid=uid);
        root ++> nd;
        idx[uid] = nd;
    }
    for row in units {
        pid = row["parent_id"];
        if pid is not None {
            par = idx[pid];
            ch = idx[row["id"]];
            par +>:ParentOf:+> ch;
        }
        if "extra_parents" in row {
            extras: list[int] = row["extra_parents"] as list[int];
            ch = idx[row["id"]];
            for ep in extras {
                par = idx[ep];
                par +>:ParentOf:+> ch;
            }
        }
    }
    return idx;
}

def view_meta(name: str) -> dict[str, object] {
    meta: dict[str, object] = {};
    meta["type"] = "unknown";
    meta["recursive"] = False;
    meta["refresh_on_migrate"] = False;
    if name == "MonthlySales" {
        meta["type"] = "materialized";
        meta["refresh_on_migrate"] = True;
        return meta;
    }
    if name == "ActiveUsers" {
        meta["type"] = "standard";
        return meta;
    }
    if name == "OrgHierarchy" {
        meta["type"] = "cte";
        meta["recursive"] = True;
        return meta;
    }
    return meta;
}

def compute_org_depths(units: list[dict]) -> dict[int, int] {
    if len(units) == 0 {
        return {};
    }
    idx: dict[int, OrgUnit] = build_and_link(units);
    claimed: dict[str, bool] = {};
    depths: dict[int, int] = {};
    for row in units {
        if row["parent_id"] is None {
            nd = idx[row["id"]];
            nd spawn DepthWalker(claimed=claimed, depths=depths);
        }
    }
    print(f"depths {len(depths)}");
    return depths;
}

def closure_descendant_ids(units: list[dict], start_id: int) -> list[int] {
    idx: dict[int, OrgUnit] = build_and_link(units);
    if start_id not in idx {
        return [];
    }
    nd = idx[start_id];
    w = nd spawn DescWalker();
    out: list[int] = sorted(w.found);
    print(f"closure {start_id} {len(out)}");
    return out;
}

def materialize_monthly_totals(orders: list[dict]) -> list[dict] {
    buckets: dict[str, float] = {};
    for o in orders {
        m: str = o["month"];
        if m not in buckets {
            buckets[m] = 0.0;
        }
        buckets[m] = buckets[m] + float(o["amount"]);
    }
    keys: list[str] = list(buckets.keys());
    keys = sorted(keys);
    out: list[dict] = [];
    rid: int = 1;
    for k in keys {
        row: dict[str, object] = {};
        row["id"] = rid;
        row["month"] = k;
        row["total"] = buckets[k];
        out.append(row);
        rid = rid + 1;
    }
    print(f"materialized {len(out)}");
    return out;
}
