        prev +>:Next:+> nd;
    }
    return nd;
}

def _scan_build(raw: str, skip_comments: bool, fail_on_js: bool) -> JsonRoot {
    root_node = JsonRoot(raw=raw, fail_on_js=fail_on_js, skip_comments=skip_comments);
    root ++> root_node;
    head: JsonTok | None = None;
    tail: JsonTok | None = None;
    i: int = 0;
    n: int = len(raw);
    in_str: bool = False;
    esc: bool = False;
    block_depth: int = 0;
    while i < n {
        ch = raw[i];
        if in_str {
            head = _append_tok(tail, "char", ch, i, block_depth);
            if not tail {
                root_node +>:Child:+> head;
            }
            tail = head;
            if esc {
                esc = False;
            } elif ch == "\\" {
                esc = True;
            } elif ch == "\"" {
                in_str = False;
            }
            i += 1;
            continue;
        }
        if ch == "\"" {
            in_str = True;
            head = _append_tok(tail, "char", ch, i, block_depth);
            if not tail {
                root_node +>:Child:+> head;
            }
            tail = head;
            i += 1;
            continue;
        }
        if not skip_comments and block_depth == 0 and i + 1 < n and raw[i] == "/" and raw[i + 1] == "/" {
            while i < n and raw[i] != "\n" {
                i += 1;
            }
            continue;
        }
        if not skip_comments and block_depth == 0 and i + 1 < n and raw[i] == "/" and raw[i + 1] == "*" {
            open_t = JsonTok(kind="open", val="/*", pos=i, depth=block_depth, nid=_tok_id("open", "/*", i, block_depth));
            if not tail {
                root_node +>:Child:+> open_t;
            } else {
                tail +>:Next:+> open_t;
            }
            tail = open_t;
            block_depth += 1;
            i += 2;
            inner: JsonTok | None = None;
            while i < n {
                if i + 1 < n and raw[i] == "/" and raw[i + 1] == "*" {
                    inner = _append_tok(inner, "char", "/*", i, block_depth);
                    open_t +>:Child:+> inner;
                    block_depth += 1;
                    i += 2;
                    continue;
                }
                if i + 1 < n and raw[i] == "*" and raw[i + 1] == "/" {
                    inner = _append_tok(inner, "char", "*/", i, block_depth);
                    open_t +>:Child:+> inner;
                    block_depth -= 1;
                    i += 2;
                    if block_depth == 0 {
                        break;
                    }
                    continue;
                }
                inner = _append_tok(inner, "char", raw[i], i, block_depth);
                open_t +>:Child:+> inner;
                i += 1;
            }
            continue;
        }
        if fail_on_js and ((i + 1 < n and raw[i] == "/" and raw[i + 1] == "/") or (i + 1 < n and raw[i] == "/" and raw[i + 1] == "*")) {
            js_t = JsonTok(kind="js", val=ch, pos=i, depth=block_depth, nid=_tok_id("js", ch, i, block_depth));
            if not tail {
                root_node +>:Child:+> js_t;
            } else {
                tail +>:Next:+> js_t;
            }
            tail = js_t;
            i += 1;
            continue;
        }
        head = _append_tok(tail, "char", ch, i, block_depth);
        if not tail {
            root_node +>:Child:+> head;
        }
        tail = head;
        i += 1;
    }
    return root_node;
}

def strip_json_comments(text: str) -> str {
    g = _scan_build(text, False, False);
    w = g spawn StripComments(claimed={});
    print(w.buf);
    return g.out;
}

def is_js_fragment(text: str) -> bool {
    g = _scan_build(text, True, True);
    w = g spawn DetectJs(claimed={});
    print(w.found);
    return w.found;
}

def parse_weak_json(text: str, fail_on_js: bool = False) -> str {
    if fail_on_js {
        g_chk = _scan_build(text, True, True);
        w_chk = g_chk spawn DetectJs(claimed={});
        print(w_chk.found);
        if w_chk.found {
            return "";
        }
    }
    out = strip_json_comments(text);
    print(out);
    return out;
}
