def recursive_bindings(ctx: EqualRefineCtx, pattern_id: str) -> dict[str, str] | None {
    if pattern_id not in ctx.pat_by_id {
        return None;
    }
    ep = ctx.pat_by_id[pattern_id] as EqPat;
    w = ep spawn BindWalker(pat_by_id=ctx.pat_by_id);
    if w.failed {
        return None;
    }
    return w.bindings;
}

def equal_targets(ctx: EqualRefineCtx) -> list[str] {
    ids: list[str] = [];
    for k in ctx.pat_by_id {
