        for ex_raw in excl_list {
            ex_name = ex_raw as str;
            ev = anchor_vars[ex_name];
            ep +>:Excl:+> ev;
        }
        pat_by_id[pid] = ep;
    }
    if first_pat is None {
        empty = EqPat(pid="__empty__", target_vid="__empty__");
        root ++> empty;
        first_pat = empty;
    }
    ctx = EqualRefineCtx(anchor=first_pat, pat_by_id=pat_by_id, var_by_id=anchor_vars);
    root spawn EqSeedWalker;
    return ctx;
}

def can_refine(ctx: EqualRefineCtx, pattern_id: str, exclude: list[str], target: str) -> bool {
    if pattern_id not in ctx.pat_by_id {
        return False;
    }
    ep = ctx.pat_by_id[pattern_id] as EqPat;
    excl_copy: list[str] = [];
    for e in exclude {
        excl_copy.append(e);
    }
    w = ep spawn RefineWalker(want_excl=excl_copy, want_tgt=target);
    return w.ok;
}

def recursive_bindings(ctx: EqualRefineCtx, pattern_id: str) -> dict[str, str] | None {
    if pattern_id not in ctx.pat_by_id {
        return None;
    }
    ep = ctx.pat_by_id[pattern_id] as EqPat;
    w = ep spawn BindWalker(pat_by_id=ctx.pat_by_id);
    if w.failed {
        return None;
    }
    return w.bindings;
}

def equal_targets(ctx: EqualRefineCtx) -> list[str] {
    ids: list[str] = [];
    for k in ctx.pat_by_id {
        ids.append(k);
    }
    sorted(ids);
    return ids;
}
