def kahn_topo(gh: GraphHandle, node_ids: list[str]) -> list[str] | None {
    needed_set: dict[str, bool] = {};
    for nid in node_ids {
        needed_set[nid] = True;
    }
    indeg: dict[str, int] = {};
    for nid in node_ids {
        indeg[nid] = 0;
    }
    for nid in node_ids {
        nd = gh.nodes[nid];
        kids: list[Skill] = [nd ->:Requires:->][?:Skill];
        for kid in kids {
            if kid.sid in needed_set {
                indeg[kid.sid] += 1;
            }
        }
    }
    queue: list[str] = [];
    for nid in sorted(node_ids) {
        if indeg[nid] == 0 {
            queue.append(nid);
        }
    }
    result: list[str] = [];
    while len(queue) > 0 {
        cur = queue[0];
        rest: list[str] = [];
        idx = 1;
        while idx < len(queue) {
            rest.append(queue[idx]);
            idx += 1;
        }
        queue = rest;
        result.append(cur);
        cur_nd = gh.nodes[cur];
        out_kids: list[Skill] = [cur_nd ->:Requires:->][?:Skill];
        for kid in out_kids {
            if kid.sid in needed_set {
                indeg[kid.sid] -= 1;
                if indeg[kid.sid] == 0 {
                    queue.append(kid.sid);
                    queue = sorted(queue);
                }
            }
        }
    }
    if len(result) != len(node_ids) {
        return None;
    }
    return result;
