"""Synthetic lift for crate/crate-clients-tools#52 — recursive typeinfo tree introspection."""

node TypeInfo {
    has oid: int;
    has ns: str;
    has name: str;
    has kind: str;
    has basetype_oid: int = 0;
    has elemtype_oid: int = 0;
    has attrtypoids: list[int] = [];
}

edge TypeDep {}

walker TypeTreeCollect {
    has claimed: dict[int, bool] = {};
    has found: list[int] = [];

    can step with TypeInfo entry {
        if here.oid in self.claimed { skip; }
        if here.oid < 0 { skip; }
        self.claimed[here.oid] = True;
        self.found.append(here.oid);
        print(f"typeinfo visit {here.oid} {here.name}");
        deps: list[TypeInfo] = [here ->:TypeDep:->][?:TypeInfo];
        visit :0: deps else { disengage; }
    }
}

walker BasetypeResolve {
    has claimed: dict[int, bool] = {};
    has answer: int = 0;

    can resolve with TypeInfo entry {
        if here.oid in self.claimed { skip; }
        self.claimed[here.oid] = True;
        print(f"basetype step {here.oid} kind={here.kind}");
        if here.kind != "d" or here.basetype_oid == 0 {
            self.answer = here.oid;
            disengage;
        }
        nxt: list[TypeInfo] = [here ->:TypeDep:->][?:TypeInfo];
        for cand in nxt {
            if cand.oid == here.basetype_oid {
                visit cand;
            }
        }
        if self.answer == 0 {
            self.answer = here.oid;
        }
        disengage;
    }
}

def _make_node(catalog: dict, oid: int) -> TypeInfo {
    meta = catalog[oid] as dict;
    return TypeInfo(
        oid=oid,
        ns=meta["ns"] as str,
        name=meta["name"] as str,
        kind=meta["kind"] as str,
        basetype_oid=meta["basetype_oid"] as int,
        elemtype_oid=meta["elemtype_oid"] as int,
        attrtypoids=meta["attrtypoids"] as list[int]
    );
}

def _connect_deps(nd: TypeInfo, store: dict[int, TypeInfo]) -> None {
    if nd.basetype_oid != 0 and nd.basetype_oid in store {
        dst = store[nd.basetype_oid];
        nd +>:TypeDep:+> dst;
    }
    if nd.elemtype_oid != 0 and nd.elemtype_oid in store {
        dst2 = store[nd.elemtype_oid];
        nd +>:TypeDep:+> dst2;
    }
    for a_oid in nd.attrtypoids {
        if a_oid in store {
            dst3 = store[a_oid];
            nd +>:TypeDep:+> dst3;
        }
    }
}

def _build_type_graph(start_oids: list[int], catalog: dict) -> TypeInfo {
    store: dict[int, TypeInfo] = {};
    todo: list[int] = [];
    made: list[int] = [];
    for s_oid in start_oids {
        todo.append(s_oid);
    }
    while todo {
        cur = todo.pop();
        if cur == 0 { continue; }
        if cur in store { continue; }
        if cur not in catalog { continue; }
        nd = _make_node(catalog, cur);
        store[cur] = nd;
        made.append(cur);
        meta = catalog[cur] as dict;
        b_oid = meta["basetype_oid"] as int;
        e_oid = meta["elemtype_oid"] as int;
        attrs = meta["attrtypoids"] as list[int];
        if b_oid != 0 { todo.append(b_oid); }
        if e_oid != 0 { todo.append(e_oid); }
        for a_oid in attrs { todo.append(a_oid); }
    }
    anchor = TypeInfo(oid=-1, ns="", name="__root__", kind="");
    root ++> anchor;
    for oid in made {
        _connect_deps(store[oid], store);
    }
    for s_oid in start_oids {
        if s_oid in store {
            anchor +>:TypeDep:+> store[s_oid];
        }
    }
    return anchor;
}

def typeinfo_tree_oids(start_oids: list[int], catalog: dict) -> list[int] {
    anchor = _build_type_graph(start_oids, catalog);
    w = anchor spawn TypeTreeCollect(claimed={}, found=[]);
    out: list[int] = sorted(w.found);
    return out;
}

def resolve_basetype_oid(oid: int, catalog: dict) -> int {
    if oid not in catalog { return oid; }
    anchor = _build_type_graph([oid], catalog);
    if oid not in catalog { return oid; }
    store: dict[int, TypeInfo] = {};
    # re-resolve start node via graph anchor edges
    starts: list[TypeInfo] = [anchor ->:TypeDep:->][?:TypeInfo];
    if not starts { return oid; }
    w = starts[0] spawn BasetypeResolve(claimed={}, answer=0);
    if w.answer == 0 { return oid; }
    return w.answer;
}

def array_element_oid(oid: int, catalog: dict) -> int {
    if oid not in catalog { return 0; }
    meta = catalog[oid] as dict;
    return meta["elemtype_oid"] as int;
}
