"""guevara/read-it-later#7155 closure-table hierarchy maintenance."""

node Nomen {
    has nid: str;
    has pid: str = "";
}

edge ParentOf {}

obj Store {
    has graph_root: Nomen;
    has nodes: dict[str, Nomen] = {};
    has closure: dict[str, dict[str, int]] = {};
}

def new_store() -> Store {
    anchor = Nomen(nid="__root__");
    st = Store(graph_root=anchor, nodes={}, closure={});
    return st;
}

def _children(st: Store, nd: Nomen) -> list[Nomen] {
    out: list[Nomen] = [];
    for cid in st.nodes {
        ch = st.nodes[cid];
        if ch.pid == nd.nid {
            out.append(ch);
        }
    }
    return out;
}

def _detach(st: Store, nd: Nomen) {
    old_pid = nd.pid;
    if old_pid != "" {
        if old_pid in st.nodes {
            par = st.nodes[old_pid];
            par -:ParentOf:- nd;
        }
    }
    nd.pid = "";
}

def _attach(st: Store, nd: Nomen, parent_id: str) {
    par = st.nodes[parent_id];
    nd.pid = parent_id;
    par +>:ParentOf:+> nd;
}

walker DescWalk {
    has claimed: dict[str, bool] = {};
    has origin: str = "";
    has rows: list[tuple[str, int]] = [];
    has cur_depth: int = 0;
    has st: Store;

    can step with Nomen entry {
        if here.nid in self.claimed { skip; }
        self.claimed[here.nid] = True;
        if here.nid != self.origin {
            row: tuple[str, int] = (here.nid, self.cur_depth);
            self.rows.append(row);
        }
        kids: list[Nomen] = _children(self.st, here);
        nxt: list[Nomen] = [];
        for kid in kids {
            nxt.insert(0, kid);
        }
        visit :0: nxt else { disengage; }
        print "desc", here.nid, self.cur_depth;
    }
}

walker AncWalk {
    has claimed: dict[str, bool] = {};
    has rows: list[tuple[str, int]] = [];
    has depth: int = 0;
    has st: Store;

    can climb with Nomen entry {
        if here.nid in self.claimed { skip; }
        self.claimed[here.nid] = True;
        if self.depth > 0 {
            row: tuple[str, int] = (here.nid, self.depth);
            self.rows.append(row);
        }
        if here.pid != "" {
            if here.pid in self.st.nodes {
                par = self.st.nodes[here.pid];
                nd = self.depth + 1;
                wk = par spawn AncWalk(
                    claimed=self.claimed,
                    rows=self.rows,
                    depth=nd,
                    st=self.st
                );
                self.rows = wk.rows;
            }
        }
        print "anc", here.nid, self.depth;
    }
}

walker ReachWalk {
    has claimed: dict[str, bool] = {};
    has target: str = "";
    has hit: bool = False;
    has st: Store;

    can step with Nomen entry {
        if here.nid in self.claimed { skip; }
        self.claimed[here.nid] = True;
        if here.nid == self.target {
            self.hit = True;
        }
        kids: list[Nomen] = _children(self.st, here);
        buf: list[Nomen] = [];
        for kid in kids {
            buf.insert(0, kid);
        }
        visit :0: buf else { disengage; }
        print "reach", here.nid;
