    cur = store.by_id[node_id] as Item;
    while True {
        trail.append(cur.cid);
        if cur.cid in seen { break; }
        seen[cur.cid] = True;
        pars: list[Item] = [cur ->:Parent:->][?:Item];
        if !len(pars) { break; }
        cur = pars[0];
    }
    trail.reverse();
    return trail;
