def materialize(
    registry: dict[str, object],
    start: str,
    claimed: dict[str, bool],
    max_depth: int,
    depth: int
) -> dict {
    if not (start in registry) {
        return {};
    }
    if depth > max_depth {
        shallow: dict = {};
        shallow["title"] = "truncated";
        return shallow;
    }
    if start in claimed {
        cyclic: dict = {};
        cyclic["$ref"] = "#/definitions/" + start;
        return cyclic;
    }
    claimed[start] = True;
    nd = registry[start] as Def;
    doc: dict = {};
    doc["title"] = nd.title;
    doc["id"] = start;
    props_out: dict = {};
    for pk in nd.prop_map {
        pk_s = pk as str;
        tid = nd.prop_map[pk_s] as str;
        props_out[pk_s] = materialize(registry, tid, claimed, max_depth, depth + 1);
    }
    if len(props_out) > 0 {
        doc["properties"] = props_out;
    }
    claimed[start] = False;
    return doc;
}

