"""levelgraph/levelgraph#181 — graph traversal, path, and query helpers."""

node Store {
    has sid: str;
}

node LGNode {
    has cid: str;
    has label: str = "";
}

edge Member {}
edge Down {}

def make_store() -> Store {
    st = Store(sid="lg");
    root ++> st;
    return st;
}

def put_node(st: Store, node_id: str, label: str = "") -> None {
    nd = LGNode(cid=node_id, label=label);
    st +>:Member:+> nd;
    root ++> nd;
}

def link(st: Store, parent_id: str, child_id: str) -> None {
    p = find_node(st, parent_id);
    c = find_node(st, child_id);
    if p is not None and c is not None {
        p +>:Down:+> c;
    }
}

def find_node(st: Store, node_id: str) -> LGNode | None {
    for m in [st ->:Member:->][?:LGNode] {
        if m.cid == node_id {
            return m;
        }
    }
    return None;
}

def descendants(st: Store, node_id: str, max_depth: int | None = None) -> list[tuple[str, int]] {
    nd = find_node(st, node_id);
    if nd is None {
        out: list[tuple[str, int]] = [];
        return out;
    }
    claimed: dict[str, bool] = {};
    found: list[tuple[str, int]] = [];
    w = nd spawn DescendWalk(claimed=claimed, max_depth=max_depth, found=found, cur_depth=0);
    return found;
}

def ancestors(st: Store, node_id: str, max_depth: int | None = None) -> list[tuple[str, int]] {
    nd = find_node(st, node_id);
    if nd is None {
        out: list[tuple[str, int]] = [];
        return out;
    }
    claimed: dict[str, bool] = {};
    found: list[tuple[str, int]] = [];
    w = nd spawn AscendWalk(claimed=claimed, max_depth=max_depth, found=found, cur_depth=0);
    return found;
}

def shortest_path(st: Store, from_id: str, to_id: str) -> list[str] | None {
    start = find_node(st, from_id);
    end = find_node(st, to_id);
    if start is None or end is None {
        return None;
    }
    if from_id == to_id {
        one: list[str] = [from_id];
        return one;
    }
    claimed: dict[str, bool] = {};
    parent_map: dict[str, str | None] = {};
    parent_map[from_id] = None;
    w = start spawn PathBfs(target=to_id, claimed=claimed, parent_map=parent_map);
    if not w.hit {
        return None;
    }
    return rebuild_path(parent_map, to_id, from_id);
}

def bfs_nodes(st: Store, start_id: str) -> list[str] {
    nd = find_node(st, start_id);
    if nd is None {
        empty: list[str] = [];
        return empty;
    }
    claimed: dict[str, bool] = {};
    order: list[str] = [];
    w = nd spawn CollectBfs(claimed=claimed, order=order);
    return order;
}

def dfs_nodes(st: Store, start_id: str) -> list[str] {
    nd = find_node(st, start_id);
    if nd is None {
        empty: list[str] = [];
        return empty;
    }
    claimed: dict[str, bool] = {};
    order: list[str] = [];
    w = nd spawn CollectDfs(claimed=claimed, order=order);
    return order;
}

def query_and(result_a: list[str], result_b: list[str]) -> list[str] {
    bset: dict[str, bool] = {};
    for x in result_b {
        bset[x] = True;
    }
    out: list[str] = [];
    for x in result_a {
        if x in bset {
            out.append(x);
        }
    }
    return out;
}

def query_or(result_a: list[str], result_b: list[str]) -> list[str] {
    seen: dict[str, bool] = {};
    out: list[str] = [];
    merged: list[str] = [];
    for x in result_a {
        merged.append(x);
    }
    for x in result_b {
        merged.append(x);
    }
    for x in merged {
        if x not in seen {
            seen[x] = True;
            out.append(x);
        }
    }
    return out;
}

def rebuild_path(parent_map: dict[str, str | None], end_id: str, start_id: str) -> list[str] {
    path: list[str] = [];
    cur: str | None = end_id;
    while cur is not None {
        path.append(cur);
        if cur == start_id {
            break;
        }
        if cur in parent_map {
            cur = parent_map[cur];
        } else {
            cur = None;
        }
    }
    rev: list[str] = [];
    i = len(path) - 1;
    while i >= 0 {
        rev.append(path[i]);
        i -= 1;
    }
    return rev;
}

walker DescendWalk {
    has claimed: dict[str, bool] = {};
    has max_depth: int | None = None;
    has found: list[tuple[str, int]] = [];
    has cur_depth: int = 0;

    can step with LGNode entry {
        print(f"descend {here.cid} depth {self.cur_depth}");
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        if self.max_depth is not None and self.cur_depth > self.max_depth {
            disengage;
        }
        self.found.append((here.cid, self.cur_depth));
        kids: list[LGNode] = [];
        for ch in [here ->:Down:->][?:LGNode] {
            kids.append(ch);
        }
        for ch in kids {
            ch spawn DescendWalk(
                claimed=self.claimed,
                max_depth=self.max_depth,
                found=self.found,
                cur_depth=self.cur_depth + 1
            );
        }
        disengage;
    }
}

walker AscendWalk {
    has claimed: dict[str, bool] = {};
    has max_depth: int | None = None;
    has found: list[tuple[str, int]] = [];
    has cur_depth: int = 0;

    can step with LGNode entry {
        print(f"ascend {here.cid} depth {self.cur_depth}");
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        if self.max_depth is not None and self.cur_depth > self.max_depth {
            disengage;
        }
        self.found.append((here.cid, self.cur_depth));
        pars: list[LGNode] = [];
        for p in [here <-:Down:<-][?:LGNode] {
            pars.append(p);
        }
        for p in pars {
            p spawn AscendWalk(
                claimed=self.claimed,
                max_depth=self.max_depth,
                found=self.found,
                cur_depth=self.cur_depth + 1
            );
        }
        disengage;
    }
}

walker PathBfs {
    has target: str;
    has claimed: dict[str, bool] = {};
    has parent_map: dict[str, str | None] = {};
    has hit: bool = False;

    can step with LGNode entry {
        print(f"pathbfs {here.cid}");
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        if here.cid == self.target {
            self.hit = True;
            disengage;
        }
        kids: list[LGNode] = [];
        for ch in [here ->:Down:->][?:LGNode] {
            if ch.cid not in self.parent_map {
                self.parent_map[ch.cid] = here.cid;
            }
            kids.append(ch);
        }
        if kids {
            visit kids;
        } else {
            disengage;
        }
    }
}

walker CollectBfs {
    has claimed: dict[str, bool] = {};
    has order: list[str] = [];

    can step with LGNode entry {
        print(f"bfs {here.cid}");
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        self.order.append(here.cid);
        kids: list[LGNode] = [];
        for ch in [here ->:Down:->][?:LGNode] {
            kids.append(ch);
        }
        if kids {
            visit kids;
        } else {
            disengage;
        }
    }
}

walker CollectDfs {
    has claimed: dict[str, bool] = {};
    has order: list[str] = [];

    can step with LGNode entry {
        print(f"dfs {here.cid}");
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        self.order.append(here.cid);
        kids: list[LGNode] = [];
        for ch in [here ->:Down:->][?:LGNode] {
            kids.append(ch);
        }
        if kids {
            visit :0: kids;
        } else {
            disengage;
        }
    }
}
