def export_edge_list(hub: GraphHub) -> list {
    pairs: list = [];
    seen: dict[str, bool] = {};
    for nid in sorted(hub.members.keys()) {
        if nid not in hub.members { continue; }
        nd = hub.members[nid] as Note;
        for tgt in [nd ->:Cite:->][?:Note] {
            lo = nid;
            hi = tgt.nid;
            if hi < lo {
                lo = tgt.nid;
                hi = nid;
            }
            key = lo + "|" + hi;
            if key not in seen {
