    parts: list[str] = [];
    cursor = 0;
    for sp in spans {
        st = sp[0];
        en = sp[1];
        if st > cursor {
            parts.append(src[cursor:st]);
        }
        cursor = en;
    }
    if cursor < len(src) {
        parts.append(src[cursor:]);
    }
    result = "";
    for p in parts {
        result += p;
