def sort_by_key(items: list[file], key: str) -> list[file] {
    xs: list[file] = [];
    for it in items {
        xs.append(it);
    }
    n = len(xs);
    i = 0;
    while i < n {
        j = i + 1;
        while j < n {
            ki = key_val(xs[i], key);
            kj = key_val(xs[j], key);
            if kj < ki {
                tmp = xs[i];
                xs[i] = xs[j];
                xs[j] = tmp;
            }
            j += 1;
        }
        i += 1;
    }
    return xs;
}

