def build_registry(entries: list[list]) -> RegistryRoot {
    reg = RegistryRoot();
    by_id: dict[str, Account] = {};
    for row in entries {
        aid: str = row[0];
        if aid not in by_id {
            arch: bool = False;
            if len(row) > 2 {
                arch = row[2];
            }
            by_id[aid] = Account(cid=aid, archived=arch);
        }
    }
    for row in entries {
        aid: str = row[0];
        pid: str = "";
        if len(row) > 1 {
            pid = row[1];
        }
        nd = by_id[aid];
        if pid == "" {
            reg ++> nd;
        } else if pid in by_id {
            par = by_id[pid];
            par +>:Parent:+> nd;
        } else {
            reg ++> nd;
        }
    }
    return reg;
