def DoublyLinkedList() -> DllList {
    lst = DllList(length=0, head=None, tail=None);
    root ++> lst;
    return lst;
}

def _connect_dll(a: DllNode, b: DllNode) -> None {
    a +>:DllFwd:+> b;
    b +>:DllBack:+> a;
}

def append(dll: DllList, data: int) -> None {
    nd = DllNode(data=data, slot="d" + str(dll.length) + "a");
    root ++> nd;
    if dll.length == 0 {
        dll.head = nd;
        dll.tail = nd;
    } else {
        tail = dll.tail;
        if tail {
            _connect_dll(tail, nd);
        }
        dll.tail = nd;
    }
    dll.length += 1;
}

def prepend(dll: DllList, data: int) -> None {
    nd = DllNode(data=data, slot="d" + str(dll.length) + "p");
    root ++> nd;
    if dll.length == 0 {
        dll.head = nd;
        dll.tail = nd;
    } else {
        head = dll.head;
        if head {
            _connect_dll(nd, head);
        }
        dll.head = nd;
    }
    dll.length += 1;
}

def traverse_to_index(dll: DllList, index: int) -> DllNode {
    if index < 0 or index >= dll.length {
        raise IndexError("Index out of range");
    }
    head = dll.head;
    if not head {
        raise IndexError("Index out of range");
    }
    w = head spawn DllIndexWalker(target=index, claimed={});
    if w.result {
        return w.result;
    }
    raise IndexError("Index out of range");
}

def insert_at(dll: DllList, index: int, data: int) -> None {
    if index < 0 or index > dll.length {
        raise IndexError("Index out of range");
    }
    if index == 0 {
        prepend(dll, data);
        return;
    }
    if index == dll.length {
        append(dll, data);
        return;
    }
    leader = traverse_to_index(dll, index - 1);
    follower: DllNode | None = None;
    for ch in [leader ->:DllFwd:->][?:DllNode] {
        follower = ch;
    }
    nd = DllNode(data=data, slot="d" + str(dll.length) + "i");
    root ++> nd;
    leader +>:DllFwd:+> nd;
    nd +>:DllBack:+> leader;
    if follower {
        nd +>:DllFwd:+> follower;
        follower +>:DllBack:+> nd;
    }
    dll.length += 1;
}

def remove_at(dll: DllList, index: int) -> None {
    if index < 0 or index >= dll.length {
        raise IndexError("Index out of range");
    }
    victim = traverse_to_index(dll, index);
    prev: DllNode | None = None;
    for ch in [victim ->:DllBack:->][?:DllNode] {
        prev = ch;
    }
    nxt: DllNode | None = None;
    for ch in [victim ->:DllFwd:->][?:DllNode] {
        nxt = ch;
    }
    if not prev {
        dll.head = nxt;
    } else if nxt {
        prev +>:DllFwd:+> nxt;
    }
    if not nxt {
        dll.tail = prev;
    } else if prev {
        nxt +>:DllBack:+> prev;
    }
    dll.length -= 1;
}

