def HashTable(size: int = 50) -> HtTable {
    tbl = HtTable(size=size, heads={});
    root ++> tbl;
    i = 0;
    while i < size {
        tbl.heads[i] = None;
        i += 1;
    }
    return tbl;
}

def _hash(tbl: HtTable, key: str) -> int {
    return hash(key) % tbl.size;
}

def set(tbl: HtTable, key: str, value: int) -> None {
    slot = _hash(tbl, key);
    head = tbl.heads[slot];
    if head {
        w = head spawn HtFindWalker(want=key, claimed={});
        if w.found {
            w.found.value = value;
            return;
        }
    }
    ent = HtEntry(key=key, value=value, eid=key + "@" + str(slot));
    root ++> ent;
    if not head {
        tbl.heads[slot] = ent;
        return;
    }
    cur = head;
    while cur {
        nxt: HtEntry | None = None;
        for ch in [cur ->:HtChain:->][?:HtEntry] {
            nxt = ch;
        }
        if not nxt {
            cur +>:HtChain:+> ent;
            return;
        }
        cur = nxt;
    }
}

def get(tbl: HtTable, key: str) -> int {
    slot = _hash(tbl, key);
    head = tbl.heads[slot];
    if not head {
        raise KeyError(key);
    }
    w = head spawn HtFindWalker(want=key, claimed={});
    if w.found {
        return w.found.value;
    }
    raise KeyError(key);
}

def delete(tbl: HtTable, key: str) -> None {
    slot = _hash(tbl, key);
    head = tbl.heads[slot];
    if not head {
        raise KeyError(key);
    }
    if head.key == key {
        nxt: HtEntry | None = None;
        for ch in [head ->:HtChain:->][?:HtEntry] {
            nxt = ch;
        }
        tbl.heads[slot] = nxt;
        return;
    }
    cur = head;
    while cur {
        nxt: HtEntry | None = None;
        for ch in [cur ->:HtChain:->][?:HtEntry] {
            nxt = ch;
        }
        if nxt and nxt.key == key {
            after: HtEntry | None = None;
            for ch2 in [nxt ->:HtChain:->][?:HtEntry] {
                after = ch2;
            }
            if after {
                cur +>:HtChain:+> after;
            }
            return;
        }
        cur = nxt;
    }
    raise KeyError(key);
}

def __str__(tbl: HtTable) -> str {
    rows: list[str] = [];
    i = 0;
    while i < tbl.size {
        cells: list[str] = [];
        head = tbl.heads[i];
        cur = head;
        while cur {
            cells.append("('" + cur.key + "', " + str(cur.value) + ")");
            nxt: HtEntry | None = None;
            for ch in [cur ->:HtChain:->][?:HtEntry] {
                nxt = ch;
            }
            cur = nxt;
        }
        rows.append("[" + ", ".join(cells) + "]");
        i += 1;
    }
    return "[" + ", ".join(rows) + "]";
}

def dll_values(dll: DllList) -> list[int] {
    out: list[int] = [];
    cur = dll.head;
    while cur {
        out.append(cur.data);
        nxt: DllNode | None = None;
        for ch in [cur ->:DllFwd:->][?:DllNode] {
            nxt = ch;
        }
        cur = nxt;
    }
    return out;
}
