        items.append((eid, emp.revenue));
    }
    n = len(items);
    i = 0;
    while i < n {
        j = i + 1;
        while j < n {
            a_rev = items[i][1];
            b_rev = items[j][1];
            a_id = items[i][0];
            b_id = items[j][0];
            swap = False;
            if a_rev < b_rev {
                swap = True;
            } elif a_rev == b_rev and a_id > b_id {
                swap = True;
            }
            if swap {
                tmp = items[i];
                items[i] = items[j];
                items[j] = tmp;
            }
            j += 1;
        }
        i += 1;
    }
    out: list[tuple[str, int, int]] = [];
    idx = 0;
    dense = 0;
    prev_rev = -1;
    while idx < n {
        rev = items[idx][1];
        rank_skip = idx + 1;
        if rev != prev_rev {
            dense += 1;
            prev_rev = rev;
        }
        out.append((items[idx][0], rank_skip, dense));
        idx += 1;
    }
    return out;
}
