def state_key(st: dict) -> str {
    lr = st["lastRoomId"];
    if lr is None {
        lr = "";
    }
    return st["roomId"] + "\x1f" + str(st["phase"]) + "\x1f" + lr + "\x1f" + str(st["marks"]);
}

def initial_state() -> dict {
    return {
        "roomId": "gate",
        "phase": 0,
        "lastRoomId": "",
        "marks": 0,
        "steps": 0,
    };
}

def transition(
    room_id: str,
    direction: str,
    phase: int,
    last_room_id: str,
    marks: int,
) -> dict {
    new_phase = phase;
    new_marks = marks;
    dest = "";
    if room_id == "gate" {
        if direction == "north" {
            dest = "well";
        } elif direction == "east" {
            dest = "clock";
        }
    } elif room_id == "well" {
        if direction == "north" {
            dest = "gate";
        } elif direction == "south" {
            dest = "glass";
        }
    } elif room_id == "glass" {
        if direction == "south" {
            dest = "well";
        } elif direction == "north" and phase >= 1 {
            dest = "fork";
        }
    } elif room_id == "clock" {
        if direction == "south" {
            dest = "rotunda";
        } elif direction == "west" {
            dest = "glass";
            new_phase = (phase + 1) % 3;
        }
    } elif room_id == "rotunda" {
        if phase == 0 {
            if direction == "north" {
                dest = "archive";
            } elif direction == "west" {
                dest = "static";
            }
        } elif phase == 1 {
            if direction == "north" {
                dest = "static";
            } elif direction == "west" {
                dest = "archive";
            }
        } elif phase == 2 {
            if direction == "north" {
                dest = "well";
            } elif direction == "west" {
                dest = "archive";
            }
        }
    } elif room_id == "archive" {
        if direction == "south" {
            dest = "rotunda";
        }
    } elif room_id == "static" {
        if direction == "east" {
            dest = "rotunda";
        }
    } elif room_id == "fork" {
        if direction == "north" {
            if last_room_id == "glass" and phase == 2 {
                dest = "exit";
            } elif last_room_id == "static" {
                dest = "well";
            } else {
                dest = "archive";
            }
        } elif direction == "south" {
            dest = "glass";
        }
    }
    return {"roomId": dest, "phase": new_phase, "marks": new_marks};
}

def list_exits(state: dict) -> list[str] {
    out: list[str] = [];
    for d in CARDINALS {
        tr = transition(state["roomId"], d, state["phase"], state["lastRoomId"], state["marks"]);
        if tr["roomId"] != "" {
            out.append(d);
        }
    }
    return sorted(out);
}

def step(state: dict, direction: str) -> dict {
    if direction != "east" and direction != "north" and direction != "south" and direction != "west" {
        raise ValueError("unknown direction");
    }
    tr = transition(state["roomId"], direction, state["phase"], state["lastRoomId"], state["marks"]);
    if tr["roomId"] == "" {
        raise ValueError("blocked");
    }
    return {
        "roomId": tr["roomId"],
        "phase": tr["phase"],
        "lastRoomId": state["roomId"],
        "marks": tr["marks"],
        "steps": state["steps"] + 1,
    };
}

def is_solved(state: dict) -> bool {
    return state["roomId"] == "exit";
}

def reverse_list(xs: list[str]) -> list[str] {
    out: list[str] = [];
    i = len(xs) - 1;
    while i >= 0 {
        out.append(xs[i]);
        i -= 1;
    }
    return out;
}

def rebuild_path(end_k: str, prev: dict[str, str], pdir: dict[str, str]) -> list[str] {
    rev: list[str] = [];
    cur_k = end_k;
    for _i in range(64) {
        if cur_k not in prev {
            break;
        }
        rev.append(pdir[cur_k]);
        cur_k = prev[cur_k];
    }
    return reverse_list(rev);
}

def build_graph() -> Room {
    graph_root = Room(room_id="__graph__");
    gate = Room(room_id="gate");
    graph_root ++> gate;
    return gate;
}

def shortest_path() -> list[str] {
    gate = build_graph();
    w = gate spawn BfsWalker(claimed={});
    return w.out;
}
