"""SPARQL 1.1 Property Paths — corese-stack/corese-core#566."""

node Term {
    has cid: str;
}

edge Property {
    has iri: str;
}

obj RdfGraph {
    has terms: dict[str, Term] = {};
}

def new_graph() -> RdfGraph {
    return RdfGraph(terms={});
}

def term_for(g: RdfGraph, cid: str) -> Term {
    if cid not in g.terms {
        nd = Term(cid=cid);
        g.terms[cid] = nd;
        root ++> nd;
    }
    return g.terms[cid];
}

def add_triple(g: RdfGraph, subj: str, pred: str, obj: str) -> None {
    s = term_for(g, subj);
    o = term_for(g, obj);
    s +>:Property(iri=pred):+> o;
}

def fwd_neighbors(here: Term, pred: str) -> list[Term] {
    xs: list[Term] = [];
    for pe in [here ->:Property:->] {
        if pe.iri == pred {
            for ch in [pe ->][?:Term] {
                xs.append(ch);
            }
        }
    }
    return xs;
}

def rev_neighbors(here: Term, pred: str) -> list[Term] {
    xs: list[Term] = [];
    for pe in [here <-:Property:->] {
        if pe.iri == pred {
            for ch in [pe <-][?:Term] {
                xs.append(ch);
            }
        }
    }
    return xs;
}

walker StarW {
    has pred: str;
    has claimed: dict[str, bool] = {};
    has found: list[str] = [];

    can walk with Term entry {
