```jac
"""NCEAS/metacat#1429 — closure table for version chains."""

node ChainRoot {
    has closure_rows: list[tuple[str, str, int]] = [];
}

node Version {
    has guid: str;
}

edge Member {}
edge Obsoletes {}

walker ListVersions {
    has vers: list[Version] = [];
    has claimed: dict[str, bool] = {};

    can search with ChainRoot entry {
        kids: list[Version] = [];
        for k in [here ->:Member:->][?:Version] {
            kids.append(k);
        }
        visit kids else { disengage; }
        print "list_versions";
    }

    can scan with Version entry {
        if here.guid in self.claimed { skip; }
        self.claimed[here.guid] = True;
        self.vers.append(here);
    }
}

walker FindVersion {
    has target: str;
    has result: Version | None = None;
    has claimed: dict[str, bool] = {};

    can search with ChainRoot entry {
        kids: list[Version] = [];
        for k in [here ->:Member:->][?:Version] {
            kids.append(k);
        }
        visit kids else { disengage; }
        print "find " + self.target;
    }

    can scan with Version entry {
        if here.guid in self.claimed { skip; }
        self.claimed[here.guid] = True;
        if here.guid == self.target {
            self.result = here;
            disengage;
        }
    }
}

walker DescendantsClosure {
    has parent_guid: str;
    has depth: int = 0;
    has rows: list[tuple[str, str, int]] = [];
    has claimed: dict[str, bool] = {};

    can walk with Version entry {
        if here.guid in self.claimed { skip; }
        self.claimed[here.guid] = True;
        self.rows.append((self.parent_guid, here.guid, self.depth));
        newer: list[Version] = [];
        for n in [here <-:Obsoletes:<-][?:Version] {
            newer.append(n);
        }
        saved: int = self.depth;
        self.depth = saved + 1;
        visit :0: newer;
        self.depth = saved;
        print "desc " + here.guid;
    }
}

walker AncestorWalk {
    has found: list[tuple[str, int]] = [];
    has depth: int = 0;
    has claimed: dict[str, bool] = {};

    can walk with Version entry {
        if here.guid in self.claimed { skip; }
        self.claimed[here.guid] = True;
        self.found.append((here.guid, self.depth));
        older: list[Version] = [];
        for o in [here ->:Obsoletes:->][?:Version] {
            older.append(o);
        }
        saved: int = self.depth;
        self.depth = saved + 1;
        visit :0: older;
        self.depth = saved;
        print "anc " + here.guid;
    }
}

def make_store() -> ChainRoot {
    st = ChainRoot();
    root ++> st;
    return st;
}

def get_version(root_node: ChainRoot, guid: str) -> Version | None {
    w = root_node spawn FindVersion(target=guid);
    return w.result;
}

def add_version(root_node: ChainRoot, guid: str, obsoletes: str | None = None) -> None {
    v = Version(guid=guid);
    root_node +>:Member:+> v;
    if obsoletes is not None && obsoletes != "" {
        older_v = get_version(root_node, obsoletes);
        if older_v is not None {
            v +>:Obsoletes:+> older_v;
        }
    }
}

def link_obsoletes(root_node: ChainRoot, newer_guid: str, older_guid: str) -> bool {
    newer_v = get_version(root_node, newer_guid);
    older_v = get_version(root_node, older_guid);
    if newer_v is None || older_v is None {
        return False;
    }
    newer_v +>:Obsoletes:+> older_v;
    return True;
}

def rebuild_closure(root_node: ChainRoot) -> list[tuple[str, str, int]] {
    rows: list[tuple[str, str, int]] = [];
    lw = root_node spawn ListVersions();
    vers: list[Version] = lw.vers;
    for v in vers {
        w = v spawn DescendantsClosure(parent_guid=v.guid);
        for row in w.rows {
            rows.append(row);
        }
    }
    rows.sort();
    root_node.closure_rows = rows;
    return rows;
}

def query_descendants(root_node: ChainRoot, guid: str) -> list[tuple[str, int]] {
    anchor = get_version(root_node, guid);
    if anchor is None {
        return [];
    }
    w = anchor spawn DescendantsClosure(parent_guid=guid);
    out: list[tuple[str, int]] = [];
    for row in w.rows {
        out.append((row[1], row[2]));
    }
    out.sort();
    return out;
}

def query_ancestors(root_node: ChainRoot, guid: str) -> list[tuple[str, int]] {
    anchor = get_version(root_node, guid);
    if anchor is None {
        return [];
    }
    w = anchor spawn AncestorWalk();
    out: list[tuple[str, int]] = w.found;
    out.sort();
    return out;
}
