"""iMelki/paperclip#56 — owned Vitest scratch roots, quiescence, and cleanup."""

node ScratchRoot {
    has rid: str;
    has caller: str;
    has manifest_ok: bool = False;
    has cleaned: bool = False;
    has logical_bytes: int = 0;
    has child_count: int = 0;
    has exit_status: int = 0;
