    has label: str;
    has quiescent: bool = False;
}

edge Owns {}

walker QuiesceWalker {
    has claimed: dict[str, bool] = {};
    has all_ok: bool = True;

    can probe_scratch with ScratchRoot entry {
        if here.rid in self.claimed { skip; }
        self.claimed[here.rid] = True;
        procs: list[ChildProc] = [here ->:Owns:->][?:ChildProc];
        nested: list[ScratchRoot] = [here ->:Owns:->][?:ScratchRoot];
        for ch in procs {
            if not ch.quiescent { self.all_ok = False; }
            visit :0: [ch];
        }
        for nr in nested { visit :0: [nr]; }
    }

    can probe_child with ChildProc entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        if not here.quiescent { self.all_ok = False; }
    }
}

walker CleanupCollectWalker {
    has claimed: dict[str, bool] = {};
    has victims: list[str] = [];

    can sweep_scratch with ScratchRoot entry {
        if here.rid in self.claimed { skip; }
        self.claimed[here.rid] = True;
        self.victims.append(here.rid);
        procs: list[ChildProc] = [here ->:Owns:->][?:ChildProc];
        nested: list[ScratchRoot] = [here ->:Owns:->][?:ScratchRoot];
        for ch in procs { visit :0: [ch]; }
        for nr in nested { visit :0: [nr]; }
    }

    can sweep_child with ChildProc entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        self.victims.append(here.cid);
    }
}

walker DemoWalker {
    has claimed: dict[str, bool] = {};

    can show with ScratchRoot entry {
        if here.rid in self.claimed { skip; }
        self.claimed[here.rid] = True;
        print(here.rid);
        kids: list[ChildProc] = [here ->:Owns:->][?:ChildProc];
        for ch in kids { visit :0: [ch]; }
    }

    can show_child with ChildProc entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        print(here.cid);
    }
}

def make_scratch_store -> dict[str, object] {
