def attach_child(store: dict[str, object], owner_id: str, child_id: str, label: str) -> bool {
    nodes = store["nodes"] as dict[str, ScratchRoot];
    child_nodes = store["child_nodes"] as dict[str, ChildProc];
    child_map = store["child_map"] as dict[str, list[str]];
    if owner_id not in nodes { return False; }
    owner = nodes[owner_id];
    ch = ChildProc(cid=child_id, label=label);
    child_nodes[child_id] = ch;
    owner +>:Owns:+> ch;
    if owner_id not in child_map { child_map[owner_id] = []; }
    kids = child_map[owner_id] as list[str];
