def all_children_quiescent(store: dict[str, object], root_id: str) -> bool {
    nodes = store["nodes"] as dict[str, ScratchRoot];
    if root_id not in nodes { return True; }
    target = nodes[root_id];
    w = target spawn QuiesceWalker(claimed={}, all_ok=True);
    return w.all_ok;
}

def root_present(store: dict[str, object], root_id: str) -> bool {
    nodes = store["nodes"] as dict[str, ScratchRoot];
