}

def cleanup_owned_root(store: dict[str, object], root_id: str) -> dict[str, object] {
    receipt: dict[str, object] = {};
    residual: list[str] = [];
    receipt["cleanup_result"] = "skipped";
    receipt["residual_paths"] = residual;
    receipt["duration_ms"] = 0;
    receipt["exit_status"] = 0;
    receipt["logical_bytes"] = 0;
    receipt["child_count"] = 0;
    receipt["caller"] = "";
    nodes = store["nodes"] as dict[str, ScratchRoot];
    child_nodes = store["child_nodes"] as dict[str, ChildProc];
    child_map = store["child_map"] as dict[str, list[str]];
    if root_id not in nodes { return receipt; }
    target = nodes[root_id];
    receipt["caller"] = target.caller;
    if not target.manifest_ok {
        receipt["cleanup_result"] = "manifest_failed";
        return receipt;
    }
    qw = target spawn QuiesceWalker(claimed={}, all_ok=True);
    if not qw.all_ok {
        receipt["cleanup_result"] = "busy";
        receipt["child_count"] = target.child_count;
        return receipt;
    }
    cw = target spawn CleanupCollectWalker(claimed={}, victims=[]);
    victims = cw.victims;
    scratch_hits: list[str] = [];
    proc_hits: list[str] = [];
    for vid in victims {
        if vid in nodes { scratch_hits.append(vid); }
        elif vid in child_nodes { proc_hits.append(vid); }
    }
    for sid in scratch_hits {
        if sid in nodes { nodes.pop(sid); }
        if sid in child_map { child_map.pop(sid); }
    }
    for pid in proc_hits {
        if pid in child_nodes { child_nodes.pop(pid); }
    }
    target.cleaned = True;
    receipt["cleanup_result"] = "ok";
    receipt["exit_status"] = target.exit_status;
    receipt["logical_bytes"] = target.logical_bytes;
    receipt["child_count"] = target.child_count;
    if root_id in nodes { residual.append(root_id); }
    receipt["residual_paths"] = residual;
    return receipt;
}

