}

test "quiescence_diamond_revisit" {
    cid = allocate_scratch_root("diamond");
    assert attach_proc(cid, "p1", False);
    assert attach_proc(cid, "p2", False);
    assert attach_proc(cid, "p3", False);
    assert link_proc(cid, "p1", "p3");
    assert link_proc(cid, "p2", "p3");
    assert prove_quiescence(cid);
    pids = collect_process_tree(cid);
    assert pids == sorted(["p1", "p2", "p3"]);
}

test "unknown_root_tolerance" {
    rep = cleanup_owned_root("missing-root-id");
    assert rep["ok"] == False;
    assert rep["reason"] == "unknown";
    assert rep["residual"] == ["missing-root-id"];
    assert prove_quiescence("missing-root-id") == False;
    assert collect_process_tree("missing-root-id") == [];
