# agda/agda#4911 — mutual block scope vs separate context/hypothesis definitions.

node Context {
    has cid: str;
    has block_rank: int = 0;
}

node Hypothesis {
    has hid: str;
    has host_ctx: str;
    has reg_seq: int = 0;
}

edge InCtx {}
edge Extends {}

node SeqSeed {
    has n: int = 0;
}

def _bump_seq() -> int {
    for s in [root ->][?:SeqSeed] {
        s.n += 1;
        return s.n;
    }
    s = SeqSeed(n=1);
    root ++> s;
    return 1;
}

def _find_ctx(cid: str) -> Context | None {
    for c in [root ->][?:Context] {
        if c.cid == cid {
            return c;
        }
    }
    return None;
}

def _find_hyp(hid: str) -> Hypothesis | None {
    for h in [root ->][?:Hypothesis] {
        if h.hid == hid {
            return h;
        }
    }
    return None;
}

def empty_context() -> str {
    c = Context(cid="dot", block_rank=0);
    root ++> c;
    print(["empty_context", "dot"]);
    return "dot";
}

def make_mutual_surface(ctx_id: str) -> bool {
    if _find_ctx(ctx_id) is not None {
        return False;
    }
    rank = _bump_seq();
    c = Context(cid=ctx_id, block_rank=rank);
    root ++> c;
    print(["make_mutual_surface", ctx_id, rank]);
    return True;
}

def declare_hypothesis(host_ctx: str, hyp_id: str) -> bool {
    host = _find_ctx(host_ctx);
    if host is None {
        print(["declare_hypothesis", hyp_id, False]);
        return False;
    }
    if _find_hyp(hyp_id) is not None {
        print(["declare_hypothesis", hyp_id, False]);
        return False;
    }
    seq = _bump_seq();
    h = Hypothesis(hid=hyp_id, host_ctx=host_ctx, reg_seq=seq);
    root ++> h;
    h +>:InCtx:+> host;
    print(["declare_hypothesis", hyp_id, True]);
    return True;
}

def mutual_extend(parent_ctx: str, hyp_id: str, new_ctx: str) -> bool {
    parent = _find_ctx(parent_ctx);
    hyp = _find_hyp(hyp_id);
    if parent is None or hyp is None {
