"""Message subtree batch query and client retreeify — max-gaspers-scott/bens_chat#45."""

node Message {
    has message_id: str;
    has parent_id: str = "";
    has body: str = "";
    has sent_at: str = "";
}

edge Reply {}

walker SubtreeWalk {
    has max_depth: int;
    has cur_depth: int = 0;
    has out_rows: list[dict[str, any]] = [];
    has claimed: dict[str, bool] = {};

    can collect with Message entry {
        if here.message_id in self.claimed { skip; }
        self.claimed[here.message_id] = True;
        next_depth = self.cur_depth + 1;
        if next_depth > self.max_depth {
            disengage;
        }
        if next_depth >= 1 {
            row: dict[str, any] = {};
            row["message_id"] = here.message_id;
            row["parent_id"] = here.parent_id;
            row["body"] = here.body;
            row["sent_at"] = here.sent_at;
            row["depth"] = next_depth;
            self.out_rows.append(row);
        }
        kids: list[Message] = [];
        for ch in [here ->:Reply:->][?:Message] {
            kids.append(ch);
        }
        if kids {
            self.cur_depth = next_depth;
            visit kids;
        } else {
            disengage;
        }
        print({"walker": "SubtreeWalk", "at": here.message_id, "depth": next_depth});
    }
}

def _spec_parent_id(spec: dict[str, any]) -> str {
    if "parent_id" in spec {
        return spec["parent_id"];
    }
    return "";
}

def _spec_body(spec: dict[str, any]) -> str {
    if "body" in spec {
        return spec["body"];
    }
    return "";
}

def _spec_sent_at(spec: dict[str, any]) -> str {
    if "sent_at" in spec {
        return spec["sent_at"];
    }
    return "";
}

def _index_messages(specs: list) -> dict[str, Message] {
    nodes: dict[str, Message] = {};
    for spec in specs {
        mid = spec["message_id"];
        m = Message(
            message_id=mid,
            parent_id=_spec_parent_id(spec),
            body=_spec_body(spec),
            sent_at=_spec_sent_at(spec),
        );
        nodes[mid] = m;
    }
    for spec in specs {
        pid = _spec_parent_id(spec);
        mid = spec["message_id"];
        if pid != "" and pid in nodes {
            nodes[pid] +>:Reply:+> nodes[mid];
        }
        if "alt_parents" in spec {
            alt_list = spec["alt_parents"];
            for alt_pid in alt_list {
                if alt_pid in nodes {
                    nodes[alt_pid] +>:Reply:+> nodes[mid];
                }
            }
        }
    }
    return nodes;
}

def _sort_subtree_rows(rows: list) -> list {
    n = len(rows);
    if n <= 1 {
        return rows;
    }
    out: list[dict[str, any]] = [];
    used: list[bool] = [];
    i = 0;
    while i < n {
        used.append(False);
        i += 1;
    }
    picked = 0;
    while picked < n {
        best_j = -1;
        best_d = 0;
        best_s = "";
        j = 0;
        while j < n {
            if not used[j] {
                r = rows[j];
                if best_j < 0 or r["depth"] < best_d or (r["depth"] == best_d and r["sent_at"] < best_s) {
                    best_j = j;
                    best_d = r["depth"];
                    best_s = r["sent_at"];
                }
            }
            j += 1;
        }
        used[best_j] = True;
        out.append(rows[best_j]);
        picked += 1;
    }
    return out;
}

def query_subtree(messages: list, parent_id: str, max_depth: int) -> list {
    if max_depth < 1 {
        return [];
    }
    nodes = _index_messages(messages);
    if parent_id not in nodes {
        return [];
    }
    anchor = nodes[parent_id];
    w = anchor spawn SubtreeWalk(max_depth=max_depth);
    return _sort_subtree_rows(w.out_rows);
}

def retreeify(flat_rows: list) -> dict {
    if len(flat_rows) == 0 {
        return {};
    }
    by_id: dict[str, dict[str, any]] = {};
    for row in flat_rows {
        nid = row["message_id"];
        node: dict[str, any] = {};
        node["message_id"] = nid;
        node["parent_id"] = row["parent_id"];
        node["body"] = row["body"];
        node["sent_at"] = row["sent_at"];
        node["depth"] = row["depth"];
        node["children"] = [];
        by_id[nid] = node;
    }
    roots: list[dict[str, any]] = [];
    for row in flat_rows {
        nid = row["message_id"];
        node = by_id[nid];
        pid = row["parent_id"];
        if pid != "" and pid in by_id {
            parent = by_id[pid];
            parent["children"].append(node);
        } else {
            roots.append(node);
        }
    }
    if len(roots) == 1 {
        return roots[0];
    }
    wrap: dict[str, any] = {};
    wrap["message_id"] = "";
    wrap["parent_id"] = "";
    wrap["body"] = "";
    wrap["sent_at"] = "";
    wrap["depth"] = 0;
    wrap["children"] = roots;
    return wrap;
}
