def ensure_parent_folders_naive(store: dict[str, bool], bucket: str, object_key: str) -> list[str] {
    keys: list[str] = parent_folder_keys(object_key);
    if len(keys) == 0 {
        return [];
    }
    head = build_parent_chain(object_key);
    wk = head spawn CollectPrefixes(claimed={}, out=[]);
    walk_keys: list[str] = wk.out;
    created: list[str] = [];
    for fk in walk_keys {
        sid = _store_id(bucket, fk);
        if sid not in store {
            store[sid] = True;
            created.append(fk);
        }
    }
    return created;
}

def ensure_parent_folders_batch(store: dict[str, bool], bucket: str, object_key: str) -> list[str] {
    keys: list[str] = parent_folder_keys(object_key);
    if len(keys) == 0 {
        return [];
    }
    head = build_parent_chain(object_key);
    wk = head spawn CollectPrefixes(claimed={}, out=[]);
    walk_keys: list[str] = wk.out;
    missing: list[str] = [];
    for fk in walk_keys {
        sid = _store_id(bucket, fk);
        if sid not in store {
            missing.append(fk);
        }
    }
    created: list[str] = [];
    for fk in missing {
        sid = _store_id(bucket, fk);
        store[sid] = True;
        created.append(fk);
    }
    return created;
}

