```jac
"""Lift for t-benze/happyranch#827 — batched task-root subtree severity rollup."""

SEVERITY_RANK: dict[str, int] = {"critical": 4, "high": 3, "medium": 2, "low": 1, "none": 0};

node TaskGraph {}
node Task {
  has tid: str;
  has severity: str = "none";
  has created_at: int = 0;
  has root_tid: str = "";
}
edge ParentLink {}

walker CollectStatuses {
  has claimed: dict[str, bool] = {};
  has statuses: list[str] = [];
  can walk with Task entry {
    if here.tid in self.claimed { skip; }
    self.claimed[here.tid] = True;
    self.statuses.append(here.severity);
    kids: list[Task] = [here ->:ParentLink:->][?:Task];
    for ch in kids { visit :0: [ch]; }
    print(["collect", here.tid]);
  }
}

walker BatchRollup {
  has claimed: dict[str, bool] = {};
  has wanted: dict[str, bool] = {};
  has buckets: dict[str, list[str]] = {};
  can begin with TaskGraph entry {
    for t in [here ->][?:Task] { visit :0: [t]; }
    print(["batch_begin"]);
  }
  can walk with Task entry {
    if here.tid in self.claimed { skip; }
    self.claimed[here.tid] = True;
    rt = here.root_tid;
    if rt in self.wanted {
      cur: list[str] = [];
      if rt in self.buckets { cur = self.buckets[rt]; }
      cur.append(here.severity);
      self.buckets[rt] = cur;
    }
    kids: list[Task] = [here ->:ParentLink:->][?:Task];
    for ch in kids { visit :0: [ch]; }
    print(["batch", here.tid]);
  }
}

def rollup_severity(statuses: list[str]) -> str {
  best: str = "none";
  best_rank: int = 0;
  for st in statuses {
    rank = 0;
    if st in SEVERITY_RANK { rank = SEVERITY_RANK[st]; }
    if rank > best_rank { best_rank = rank; best = st; }
  }
  return best;
}

def sort_roots(xs: list[Task]) -> list[Task] {
  ys: list[Task] = [];
  for x in xs { ys.append(x); }
  n = len(ys);
  i = 0;
  while i < n {
    j = i + 1;
    while j < n {
      a = ys[i]; b = ys[j]; swap = False;
      if b.created_at > a.created_at { swap = True; }
      else if b.created_at == a.created_at && b.tid > a.tid { swap = True; }
      if swap { ys[i] = b; ys[j] = a; }
      j += 1;
    }
    i += 1;
  }
  return ys;
}

def create_task_graph(specs: list[dict]) -> TaskGraph {
  g = TaskGraph();
  root ++> g;
  by_id: dict[str, Task] = {};
  for spec in specs {
    t = Task(tid=spec["tid"], severity=spec["severity"], created_at=spec["created_at"], root_tid=spec["tid"]);
    by_id[spec["tid"]] = t;
    g ++> t;
  }
  for spec in specs {
    pt = spec["parent_tid"];
    if pt != None {
      pid = pt as str;
      if pid in by_id {
        par = by_id[pid]; ch = by_id[spec["tid"]];
        par +>:ParentLink:+> ch;
        ch.root_tid = par.root_tid;
      }
    }
  }
  return g;
}

def get_subtree_statuses(graph: TaskGraph, root_id: str) -> list[str] {
  for t in [graph ->][?:Task] {
    if t.tid == root_id {
      w = t spawn CollectStatuses(claimed={}, statuses=[]);
      return w.statuses;
    }
  }
  return [];
}

def batch_subtree_rollups(graph: TaskGraph, root_ids: list[str]) -> dict[str, str] {
  wanted: dict[str, bool] = {};
  for rid in root_ids { wanted[rid] = True; }
  w = graph spawn BatchRollup(claimed={}, wanted=wanted, buckets={});
  out: dict[str, str] = {};
  for rid in root_ids {
    sts: list[str] = [];
    if rid in w.buckets { sts = w.buckets[rid]; }
    out[rid] = rollup_severity(sts);
  }
  return out;
}

def list_roots(graph: TaskGraph, limit: int) -> list[dict] {
  candidates: list[Task] = [];
  for t in [graph ->][?:Task] {
    ups: list[Task] = [t <-:ParentLink:<-][?:Task];
    if len(ups) == 0 { candidates.append(t); }
  }
  page: list[Task] = [];
  c = 0;
  for r in sort_roots(candidates) {
    if c >= limit { break; }
    page.append(r);
    c += 1;
  }
  ids: list[str] = [];
  for r in page { ids.append(r.tid); }
  rolls = batch_subtree_rollups(graph, ids);
  rows: list[dict] = [];
  for r in page {
    row: dict = {};
    row["tid"] = r.tid;
    row["severity_rollup"] = rolls[r.tid];
    row["created_at"] = r.created_at;
    rows.append(row);
  }
  return rows;
}
