def sort_roots(xs: list[Task]) -> list[Task] {
  ys: list[Task] = [];
  for x in xs { ys.append(x); }
  n = len(ys);
  i = 0;
  while i < n {
    j = i + 1;
    while j < n {
      a = ys[i]; b = ys[j]; swap = False;
      if b.created_at > a.created_at { swap = True; }
      else if b.created_at == a.created_at && b.tid > a.tid { swap = True; }
      if swap { ys[i] = b; ys[j] = a; }
      j += 1;
    }
    i += 1;
  }
  return ys;
}

def create_task_graph(specs: list[dict]) -> TaskGraph {
  g = TaskGraph();
