edge HasChild {}

walker NodeFinder {
    has target_id: str;
    has found: RecipeNode | None = None;
    has claimed: dict[str, bool] = {};

    can seek with RecipeNode entry {
        if here.id == self.target_id {
            self.found = here;
            disengage;
        }
        if here.id in self.claimed {
            skip;
        }
        self.claimed[here.id] = True;
        nxt: list[RecipeNode] = [here ->:HasChild:->][?:RecipeNode];
        if nxt {
            visit nxt;
        } else {
            disengage;
        }
    }
}

walker AncestorWalker {
    has claimed: dict[str, bool] = {};
    has ancestors: list[str] = [];
    has max_depth: int = 100;

    can climb with RecipeNode entry {
        if here.id in self.claimed {
            skip;
        }
        self.claimed[here.id] = True;
        if len(self.ancestors) >= self.max_depth {
            disengage;
        }
        parents: list[RecipeNode] = [here <-:HasChild:<-][?:RecipeNode];
        ups: list[RecipeNode] = [];
        for par in parents {
            if len(self.ancestors) >= self.max_depth {
                break;
            }
            self.ancestors.append(par.id);
            ups.append(par);
        }
        if ups {
            visit :0: ups;
        } else {
            disengage;
        }
    }
}

walker AncestorDemo {
    has graph_root: RecipeNode;
    has node_id: str;

    can show with RecipeNode entry {
        got: list[str] = get_node_ancestors(self.graph_root, self.node_id);
        print({"node": self.node_id, "ancestors": got});
        disengage;
    }
}

def find_node(graph_root: RecipeNode, node_id: str) -> RecipeNode | None {
    w = graph_root spawn NodeFinder(target_id=node_id);
    return w.found;
}

def link_parent_child(parent: RecipeNode, child: RecipeNode) -> None {
    parent +>:HasChild:+> child;
}

def get_node_ancestors(graph_root: RecipeNode, node_id: str, max_depth: int = 100) -> list[str] {
    target: RecipeNode | None = find_node(graph_root, node_id);
    if not target {
        return [];
    }
    w = target spawn AncestorWalker(max_depth=max_depth);
    return w.ancestors;
}

def build_linear_tree(ids: list[str]) -> RecipeNode {
    graph_root: RecipeNode = RecipeNode(id=ids[0]);
    root ++> graph_root;
    prev: RecipeNode = graph_root;
    i: int = 1;
    while i < len(ids) {
        nd: RecipeNode = RecipeNode(id=ids[i]);
        link_parent_child(prev, nd);
        prev = nd;
        i += 1;
    }
    return graph_root;
}

