"""Type tree canonical origin inspection — ilevkivskyi/typing_inspect#36."""

node TypeGraph {
    has by_id: dict[str, TypeNode] = {};
}

node TypeNode {
    has tid: str;
    has raw_origin: str;
    has canonical_origin: str;
}

edge ArgEdge {}

walker OriginFold {
    has claimed: dict[str, bool] = {};
    has out: list[str] = [];

    can visit_type with TypeNode entry {
        if here.tid in self.claimed {
            skip;
        }
        self.claimed[here.tid] = True;
        self.out.append(here.canonical_origin);
        print(here.canonical_origin);
        kids: list[TypeNode] = [];
        for ch in [here ->:ArgEdge:->][?:TypeNode] {
            kids.append(ch);
        }
        if kids {
            visit :0: kids;
        } else {
            disengage;
        }
    }
}

def alias_table() -> dict[str, str] {
    aliases: dict[str, str] = {};
    aliases["collections.abc.Iterable"] = "typing.Iterable";
    aliases["collections.abc.Mapping"] = "typing.Mapping";
    aliases["collections.abc.Sequence"] = "typing.Sequence";
    return aliases;
}

def canonicalize(raw: str) -> str {
    aliases: dict[str, str] = alias_table();
    if raw in aliases {
        return aliases[raw];
    }
    return raw;
}

def make_store(entries: list[list]) -> TypeGraph {
    g = TypeGraph();
    pending: list[list] = [];
    for ent in entries {
        pending.append(ent);
    }
    for ent in pending {
        tid: str = ent[0];
        raw: str = ent[1];
        canon: str = canonicalize(raw);
        nd = TypeNode(tid=tid, raw_origin=raw, canonical_origin=canon);
        g.by_id[tid] = nd;
        g ++> nd;
    }
    for ent in pending {
        tid: str = ent[0];
        arg_ids: list = ent[2];
        parent = g.by_id[tid];
        for aid in arg_ids {
            if aid in g.by_id {
                child = g.by_id[aid];
                parent +>:ArgEdge:+> child;
            }
        }
    }
    return g;
}

def get_origin(store: TypeGraph, tid: str) -> str {
    if tid not in store.by_id {
        return "";
    }
    nd = store.by_id[tid];
    return nd.canonical_origin;
}

def get_args(store: TypeGraph, tid: str) -> list[str] {
    ids: list[str] = [];
    if tid not in store.by_id {
        return ids;
    }
    nd = store.by_id[tid];
    for ch in [nd ->:ArgEdge:->][?:TypeNode] {
        ids.append(ch.tid);
    }
    return ids;
}

def walk_canonical_origins(store: TypeGraph, tid: str) -> list[str] {
    empty: list[str] = [];
    if tid not in store.by_id {
        return empty;
    }
    start = store.by_id[tid];
    w = start spawn OriginFold(claimed={}, out=[]);
    return w.out;
}
