    if sa < sb {
        return -1;
    }
    if sa > sb {
        return 1;
    }
    return 0;
}

def sort_rows(rows: list) -> list {
    out: list = [];
    for r in rows {
        out.append(r);
    }
    n = len(out);
    i = 0;
    while i < n {
        j = i + 1;
        while j < n {
            if cmp_rows(out[j] as dict, out[i] as dict) < 0 {
                tmp = out[i];
                out[i] = out[j];
                out[j] = tmp;
            }
            j += 1;
        }
        i += 1;
    }
    return out;
}

def sort_msgs(nodes: list[Message]) -> list[Message] {
    out: list[Message] = [];
