    while i < n {
        j = i + 1;
        while j < n {
            if out[j].sent_at < out[i].sent_at {
                tmp = out[i];
                out[i] = out[j];
                out[j] = tmp;
            }
            j += 1;
        }
        i += 1;
    }
    return out;
}

def materialize(store: dict[str, dict], focus_id: str) -> Message | None {
    nodes: dict[str, Message] = {};
    mids: list[str] = sorted(store);
    for mid in mids {
        row = store[mid] as dict;
        pid = "";
        if "parent_id" in row {
            pid = row["parent_id"] as str;
        }
        sat = "";
        if "sent_at" in row {
            sat = row["sent_at"] as str;
        }
        bod = "";
        if "body" in row {
            bod = row["body"] as str;
        }
        nd = Message(mid=mid, parent_ref=pid, sent_at=sat, body=bod);
        nodes[mid] = nd;
        root ++> nd;
    }
    focus: Message | None = None;
    for mid in mids {
        nd = nodes[mid];
        if mid == focus_id {
            focus = nd;
        }
        pr = nd.parent_ref;
        if pr != "" {
            if pr in nodes {
                par = nodes[pr];
                par +>:Reply:+> nd;
            }
        }
        row = store[mid] as dict;
        if "extra_replies" in row {
            extras = row["extra_replies"] as list;
            for xr in extras {
                xid = xr as str;
                if xid in nodes {
                    xp = nodes[xid];
