    has built: dict[str, dict] = {};

    can assemble with Message entry {
        if here.mid in self.claimed {
            skip;
        }
        self.claimed[here.mid] = True;
        print(["treeify_visit", here.mid]);
        kids: list[Message] = [];
        for ch in [here ->:Reply:->][?:Message] {
            kids.append(ch);
        }
        kids = sort_msgs(kids);
        for kid in kids {
            visit :0: [kid];
        }
        self.built[here.mid] = nest_node(here, self.built);
    }
}

def retreeify_messages(flat_rows: list) -> dict | None {
    if len(flat_rows) == 0 {
        return None;
    }
    store: dict[str, dict] = {};
    for row in flat_rows {
        r = row as dict;
        mid = r["message_id"] as str;
        store[mid] = {
            "message_id": mid,
            "parent_id": r["parent_id"] if "parent_id" in r else "",
            "sent_at": r["sent_at"] if "sent_at" in r else "",
            "body": r["body"] if "body" in r else "",
        };
        if "extra_replies" in r {
            store[mid]["extra_replies"] = r["extra_replies"];
        }
    }
    roots: list[str] = [];
    mids: list[str] = sorted(store);
    id_set: dict[str, bool] = {};
    for mid in mids {
        id_set[mid] = True;
    }
    for mid in mids {
        r = store[mid] as dict;
        pid = "";
        if "parent_id" in r {
            pid = r["parent_id"] as str;
        }
        if pid == "" or not (pid in id_set) {
            roots.append(mid);
        }
    }
    if len(roots) == 0 {
