    }
    graph_root_id = roots[0];
    anchor = materialize(store, graph_root_id);
    if anchor is None {
        return None;
    }
    w = anchor spawn TreeifyWalker(claimed={}, built={});
    if graph_root_id in w.built {
        return w.built[graph_root_id];
    }
    return None;
}

def load_message_thread_tree(parent_id: str, max_depth: int, store: dict[str, dict]) -> dict | None {
    flat = query_message_subtree(parent_id, max_depth, store);
    if len(flat) == 0 {
        return None;
    }
    return retreeify_messages(flat);
}
