# Lift of astral-sh/uv#9191: cache invalidation on local dependencies in docker.
# Python original hand-rolled adjacency dicts + memoized ancestor closure +
# cascade invalidation sweep. Here: native OSP graph with node Pkg, edge Dep.

node Pkg {
    has pid: str;
    has ctime: int = 0;
    has inode: int = 0;
    has checksum: str = "";
}

edge Dep {
    has requires_editable: bool = True;
}

obj FreshnessCache {
    has stamp_inode: dict[str, int];
    has stamp_ctime: dict[str, int];
    has memo: dict[str, list[str]];

    def init() {
        self.stamp_inode = {};
        self.stamp_ctime = {};
        self.memo = {};
    }

    def record(pkg: Pkg) {
        self.stamp_inode[pkg.pid] = pkg.inode;
        self.stamp_ctime[pkg.pid] = pkg.ctime;
    }

    def is_fresh(pkg: Pkg) -> bool {
        # Docker layer rebuilds change inode + birth/change times; checksum
        # (content) stays stable, so inode drift alone must not invalidate.
        if pkg.pid not in self.stamp_inode { return False; }
        return self.stamp_inode[pkg.pid] == pkg.inode
            and self.stamp_ctime[pkg.pid] == pkg.ctime;
    }

    def memo_ancestors(pkg: Pkg) -> list[str] {
        if pkg.pid in self.memo { return self.memo[pkg.pid]; }
        acc: list[str] = [];
        wk = pkg spawn AncestorWalk(claimed={}, acc=acc);
        sorted(acc);
        self.memo[pkg.pid] = acc;
        return acc;
    }
}

walker AncestorWalk {
    has claimed: dict[str, bool] = {};
    has acc: list[str] = [];

    can step with Pkg entry {
        if here.pid in self.claimed { skip; }
        self.claimed[here.pid] = True;
        if here.pid != self._origin() { self.acc.append(here.pid); }
        visit [here ->:Dep:->];
    }

    def _origin() -> str { return ""; }
}

graph registry {
    has nodes: dict[str, Pkg];

    def init() {
        self.nodes = {};
    }

    def add(pid: str, ctime: int, inode: int, checksum: str) -> Pkg {
        p = Pkg(pid=pid, ctime=ctime, inode=inode, checksum=checksum);
        self.nodes[pid] = p;
        root ++> p;
        return p;
    }

    def link(src: str, dst: str) -> bool {
        if (src not in self.nodes) or (dst not in self.nodes) { return False; }
        self.nodes[src] +>:Dep:+> self.nodes[dst];
        return True;
    }

    def get(pid: str) -> Pkg | None {
        if pid in self.nodes { return self.nodes[pid]; }
        return None;
    }
}

def build_index(specs: list[tuple[str, int, int, str]]) -> registry {
    reg = registry();
    for s in specs { reg.add(s[0], s[1], s[2], s[3]); }
    return reg;
}

def cascade_invalidate(reg: registry, pid: str) -> list[str] {
    # Collect first (claim-map walk), then mutate outside any walk.
    start = reg.get(pid);
    if start is None { return []; }
    acc: list[str] = [];
    wk = start spawn AncestorWalk(claimed={}, acc=acc);
    sorted(acc);
    return acc;
}
