# sydlexius/canticle#665 — transactional repository seam for provenance row resets.
# Constants for status / priority / next_attempt_at live ONLY in Resetter;
# reset + cache invalidation are one transaction: walk stages, commit applies.

node Track { has tid: str; }
node ScanResult {
    has sid: str;
    has status: str = "done";
    has priority: int = 0;
    has next_attempt_at: str = "";
    has last_error: str = "";
    has invalidated: bool = False;
}
node WorkItem {
    has wid: str;
    has status: str = "done";
    has priority: int = 0;
    has next_attempt_at: str = "";
    has last_error: str = "";
}

edge SCAN_FOR {}
edge QUEUE_FOR {}
edge INDEX {}

# Repository seam: the ONLY place reset literals exist.
obj Resetter {
    def reset_scan(r: ScanResult) -> None {
        r.status = "pending";
        r.priority = -100;
        r.next_attempt_at = "1970-01-01T00:00:00Z";
        r.last_error = "";
    }
    def reset_work(w: WorkItem) -> None {
        w.status = "pending";
        w.priority = -100;
        w.next_attempt_at = "1970-01-01T00:00:00Z";
        w.last_error = "";
    }
}

# Failing seam: mimics an error after the reset stage — used to prove atomicity.
obj FailingResetter {
    def reset_scan(r: ScanResult) -> None {
        r.status = "pending";
        r.priority = -100;
        raise RuntimeError("tx aborted after reset stage");
    }
    def reset_work(w: WorkItem) -> None {
        raise RuntimeError("tx aborted after reset stage");
    }
}

walker PurgeProvenance {
    has claimed: dict[str, bool] = {};
    has srs: list = [];
    has wis: list = [];

    can sweep_t with Track entry {
        if here.tid in self.claimed { skip; }
        self.claimed[here.tid] = True;
        for r in [here ->:SCAN_FOR:->][?:ScanResult] {
            self.srs.append(r);
        }
        for w in [here ->:QUEUE_FOR:->][?:WorkItem] {
            self.wis.append(w);
        }
        # adversarial diamond: extra index edges force revisit attempts
        for t in [here ->:INDEX:->][?:Track] {
            visit [t];
        }
    }
}

# Transactional purge: collect, then commit atomically outside the walk.
# Unknown track id returns (0, 0) with no mutation; commit failure leaves
# zero partial state (staged list discarded, invalidations rolled back).
def purge_provenance(idx: Track, track_id: str, resetter: Resetter) -> tuple {
    target: Track | None = None;
    for t in [idx ->:INDEX:->][?:Track] {
        if t.tid == track_id { target = t; }
    }
    if target is None {
        return (0, 0);
    }
    wk = idx spawn PurgeProvenance(claimed={});
    staged: list = [];
    staged.extend(wk.srs);
    staged.extend(wk.wis);
    if len(staged) == 0 {
        return (0, 0);
    }
    # commit phase — all-or-nothing
    done_sr: list = [];
    done_wq: list = [];
    try {
        for r in wk.srs {
            resetter.reset_scan(r);
            done_sr.append(r.sid);
        }
        for w in wk.wis {
            resetter.reset_work(w);
            done_wq.append(w.wid);
        }
    } except {
        # rollback: undo any already-applied invalidations and statuses
        for r in wk.srs {
            r.invalidated = False;
            r.status = "done";
            r.priority = 0;
            r.next_attempt_at = "";
            r.last_error = "stale";
        }
        for w in wk.wis {
            w.status = "done";
            w.priority = 0;
            w.next_attempt_at = "";
            w.last_error = "stale";
        }
        return (0, 0);
    }
    for r in wk.srs { r.invalidated = True; }  # invalidation commits with reset
    return (len(done_sr), len(done_wq));
}

def seed(idx: Track, tid: str, sids: list, wids: list) -> Track {
    t = Track(tid=tid);
    idx +>:INDEX:+> t;
    for s in sids {
        r = ScanResult(sid=s, status="done", last_error="boom");
        t +>:SCAN_FOR:+> r;
    }
    for w in wids {
        wi = WorkItem(wid=w, status="done", last_error="boom");
        t +>:QUEUE_FOR:+> wi;
    }
    return t;
}
