"""yukostan/Leetcode-Solutions#196 — Leetcode 207 Course Schedule.

Idiomatic OSP lift: Course nodes connected by typed Prereq edges; Kahn
topological walk with claim-map + skip cycle policy (revisits are skipped,
never disengaged). Public API mirrors the issue's canFinish plus LC210-style
find_order, with unknown-id tolerance (pairs referencing out-of-range course
ids are ignored, matching dict-based lookups in the source).
"""
node Course {
    has cid: int;
    has indeg: int = 0;
}
edge Prereq;
node Hub;

# Build the directed graph pre -> ready; ignore pairs with unknown ids.
def build_graph(num_courses: int, prereqs: list[list[int]]) -> list[Course] {
    nodes: list[Course] = [];
    by_id: dict[int, Course] = {};
    for i in range(num_courses) {
        c = Course(cid=i);
        root ++> c;
        nodes.append(c);
        by_id[i] = c;
    }
    for p in prereqs {
        ready: int = p[0];
        pre: int = p[1];
        if pre in by_id {
            if ready in by_id {
                by_id[pre] +>:Prereq:+> by_id[ready];
                by_id[ready].indeg += 1;
            }
        }
    }
    return nodes;
}

walker Kahn {
    has seeds: list[Course] = [];
    has claimed: dict[int, bool] = {};
    has order: list[int] = [];
    can start with Hub entry {
        visit :0: self.seeds;
    }
    can step with Course entry {
        # claim-map + skip: revisits (diamonds, duplicate edges) are skipped
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        self.order.append(here.cid);
        print(here.cid);
        kids: list[Course] = [];
        for kid in [here ->:Prereq:->][?:Course] {
            kid.indeg -= 1;
            if kid.indeg <= 0 {
                kids.append(kid);
            }
        }
        if len(kids) > 0 {
            visit kids;
        }
    }
}

# Shared driver: returns the Kahn walker after the topological sweep.
def _run_topo(num_courses: int, prereqs: list[list[int]]) -> Kahn | None {
    nodes: list[Course] = build_graph(num_courses, prereqs);
    seeds: list[Course] = [];
    for c in nodes {
        if c.indeg == 0 {
            seeds.append(c);
        }
    }
    if len(seeds) == 0 {
        return None;
    }
