    # Build a field graph, walk it recursively (claim-map cycle guard),
    # collecting the converted body. Mirrors the recursive pre-toJSON pass.
    out: dict = {};
    for k in sorted(root_val.keys()) {
        v = root_val[k];
        if type(v) == dict {
            out[k] = sanitize_body(v);
        } elif type(v) == list {
            conv: list = [];
            for item in v {
                s: str = item;
                if looks_datetime(s) {
                    conv.append(to_utc_iso(s));
                } else {
                    conv.append(s);
                }
            }
            out[k] = conv;
        } else {
            s: str = v;
            if looks_datetime(s) {
                out[k] = to_utc_iso(s);
            } else {
                out[k] = s;
            }
        }
    }
    return out;
}

def build_field_graph(body: dict) -> BodyField {
    # Flatten a body into an explicit node/edge graph; returns the root node.
    root_node = BodyField(key="__root__", raw="", kind="dict");
    flat: dict[str, BodyField] = {};
    flat["__root__"] = root_node;
    for k in sorted(body.keys()) {
        v = body[k];
        nd: BodyField;
        if looks_datetime(v) {
            nd = BodyField(key=k, raw=v, kind="datetime", fixed=to_utc_iso(v));
        } else {
            nd = BodyField(key=k, raw=v, kind="scalar", fixed=v);
