# OpenMS/OpenMS#9792 — ownership model: copy-vs-view binding policy
# get_* returns owned copies; *_view returns aliased views with an
# invalidation contract (resize/sort invalidates live views).

node Peak {
    has mz: float;
    has intensity: float;
    has generation: int = 0;
}

node Spectrum {
    has sid: str;
    has generation: int = 0;
    has invalidated: bool = False;
}

edge contains {
    has gen_at_bind: int = 0;
}

edge owner_of {}

obj BindingStore {
    # facade over the graph: fresh per test, no module-level state
    has spectra: dict[str, Spectrum] = {};
    has peaks_of: dict[str, list[Peak]] = {};
    has views_out: dict[str, list[str]] = {};

    def add_spectrum(sid: str) -> str {
        sp = Spectrum(sid=sid);
        root ++> sp;
        self.spectra[sid] = sp;
        ps: list[Peak] = [];
        self.peaks_of[sid] = ps;
        return sid;
    }

    def add_peak(sid: str, mz: float, intensity: float) -> int {
        if sid not in self.spectra {
            raise ValueError("unknown spectrum id");
        }
        pk = Peak(mz=mz, intensity=intensity);
        self.spectra[sid] ++> pk;
        self.peaks_of[sid].append(pk);
        return len(self.peaks_of[sid]) - 1;
    }

    # R-6: element access returns an owned copy (tuple snapshot)
    def get_peak(sid: str, i: int) -> tuple[float, float] | None {
        if sid not in self.spectra or i < 0 or i >= len(self.peaks_of[sid]) {
            return None;
        }
        pk = self.peaks_of[sid][i];
        return (pk.mz, pk.intensity);
    }

    # _view contract: alias; recorded so resize/sort can invalidate
    def peak_view(sid: str, i: int) -> Peak | None {
        if sid not in self.spectra or i < 0 or i >= len(self.peaks_of[sid]) {
            return None;
        }
        pk = self.peaks_of[sid][i];
        vkey: str = sid + "#" + str(i);
        if vkey not in self.views_out {
            self.views_out[vkey] = [];
        }
        self.views_out[vkey].append(sid);
        return pk;
    }

    # structural op: sort by mz, cascade invalidate live views + generations
    def sort_peaks(sid: str) -> bool {
        if sid not in self.spectra {
            return False;
        }
        ps: list[Peak] = self.peaks_of[sid];
        ps.sort(key=lambda p: p.mz);
        self.peaks_of[sid] = ps;
        sp = self.spectra[sid];
        sp.generation = sp.generation + 1;
        sp.invalidated = True;
        for vkey in self.views_out {
            if self.views_out[vkey] != [] and vkey.split("#")[0] == sid {
                self.views_out[vkey] = [];
            }
        }
        return True;
    }

    # erase_by_mask: aligned structural delete, invalidates views (VII.2)
    def erase_mask(sid: str, mask: list[bool]) -> int {
        if sid not in self.spectra {
            return -1;
        }
        ps: list[Peak] = self.peaks_of[sid];
        kept: list[Peak] = [];
        for i in range(len(ps)) {
            if i >= len(mask) or not mask[i] {
                kept.append(ps[i]);
            }
        }
        erased = len(ps) - len(kept);
        self.peaks_of[sid] = kept;
        sp = self.spectra[sid];
        sp.generation = sp.generation + 1;
        sp.invalidated = True;
        for vkey in self.views_out {
            if self.views_out[vkey] != [] and vkey.split("#")[0] == sid {
                self.views_out[vkey] = [];
            }
        }
        return erased;
    }

    # audit sweep: cascade walker counting stale bindings per spectrum
    def audit_stale() -> dict[str, int] {
        counts: dict[str, int] = {};
        claimed: dict[str, bool] = {};
        for sid in self.spectra {
            sp = self.spectra[sid];
            if sp.sid in claimed {
                continue;
            }
            claimed[sp.sid] = True;
            stale = 0;
            for pk in self.peaks_of[sid] {
                if pk.generation < sp.generation {
                    stale = stale + 1;
                }
            }
            counts[sid] = stale;
        }
        return counts;
    }
}

walker SimulateSort {
    has sid: str;
    has claimed: dict[str, bool] = {};

    can step with Spectrum entry {
        if here.sid in self.claimed {
            skip;
        }
        self.claimed[here.sid] = True;
        if here.sid == self.sid {
            here.generation = here.generation + 1;
            here.invalidated = True;
            print("sorted", here.sid, "gen", here.generation);
        }
    }
}
