def forced_candidate_sets(specs: list[dict]) -> list[list[int]] {
    n: int = len(specs);
    forced: list[list[int]] = [];
    for _i in range(n) {
        forced.append([]);
    }
    if n == 0 {
        return forced;
    }
    prime_to_ix: dict[int, list[int]] = {};
    for i in range(n) {
        sp = specs[i] as dict;
        p: int = sp["p"];
        if p in prime_to_ix {
            prime_to_ix[p].append(i);
        } else {
            prime_to_ix[p] = [i];
        }
    }
    for i in range(n) {
        sp_i = specs[i] as dict;
        modulus: int = sp_i["two_e"] + 1;
        divs: list[int] = divisors_gt1(modulus);
        seen_j: dict[int, bool] = {};
        for d in divs {
            for j in range(n) {
                if j == i {
                    continue;
                }
                sp_j = specs[j] as dict;
                if sp_j["p"] % d == 1 {
                    if j not in seen_j {
                        seen_j[j] = True;
                        forced[i].append(j);
                    }
                }
            }
        }
        forced[i] = sorted(forced[i]);
    }
    return forced;
}

