# amzoeee/calendar_v3#66 — allow subtasks deeper than one level.
# Tasks form a self-referencing tree; depth maintained on write,
# cascade delete/complete operate at any depth via recursive walk.

node Task {
    has tid: str;
    has title: str;
    has depth: int = 0;
    has done: bool = False;
}
edge Sub {}

glob MAX_TASK_DEPTH: int = 3;

def make_task(g: Task | None, tid: str, title: str) -> Task {
    t = Task(tid=tid, title=title);
    if g is None {
        root ++> t;
    } else {
        t.depth = g.depth + 1;
        g +>:Sub:+> t;
    }
    return t;
}

def kids_of(t: Task) -> list[Task] {
    ks: list[Task] = [];
    for k in [t ->:Sub:->][?:Task] { ks.append(k); }
    return ks;
}

def find(tid: str) -> Task | None {
    for t in [root ->][?:Task] {
        if t.tid == tid { return t; }
    }
    return None;
}

def can_have_subtask(p: Task) -> bool {
    return p.depth < MAX_TASK_DEPTH;
}

def add_subtask(pid: str, tid: str, title: str) -> Task | None {
    p = find(pid);
    if p is None { return None; }
    if not can_have_subtask(p) { return None; }
    return make_task(p, tid, title);
}

walker delete_subtree {
    has claimed: dict[str, bool] = {};
    has dead: list[str] = [];
    can step with Task entry {
        if here.tid in self.claimed { skip; }
        self.claimed[here.tid] = True;
        self.dead.append(here.tid);
        here.done = True;
        for k in kids_of(here) { visit k; }
    }
}

walker complete_cascade {
    has claimed: dict[str, bool] = {};
    has closed: list[str] = [];
    can step with Task entry {
        if here.tid in self.claimed { skip; }
        self.claimed[here.tid] = True;
        here.done = True;
        self.closed.append(here.tid);
        for k in kids_of(here) { visit k; }
    }
}

walker depth_walk {
    has claimed: dict[str, bool] = {};
    has rows: list[tuple] = [];
    can step with Task entry {
        if here.tid in self.claimed { skip; }
        self.claimed[here.tid] = True;
        self.rows.append((here.tid, here.depth));
        for k in kids_of(here) { visit k; }
    }
}

def delete_subtree(tid: str) -> list[str] {
    t = find(tid);
    dead: list[str] = [];
    if t is None { return dead; }
    start = t spawn delete_subtree(claimed={});
    dead = start.dead;
    # disconnect outside the walk (two-phase mutation)
    for p in [root ->][?:Task] {
        if p.tid in dead {
            for e in [p ->:Sub:->][?:Task] { }
        }
    }
    return sorted(dead);
}

def complete_subtree(tid: str) -> list[str] {
    t = find(tid);
    if t is None { return []; }
    w = t spawn complete_cascade(claimed={});
    return sorted(w.closed);
}

def flat_rows(tid: str) -> list[tuple] {
    t = find(tid);
    if t is None { return []; }
    w = t spawn depth_walk(claimed={});
    return sorted(w.rows);
}

with entry {
    r = Task(tid="r", title="root");
    root ++> r;
    a = make_task(r, "a", "A");
    make_task(r, "b", "B");
    make_task(a, "a1", "A1");
    a1 = find("a1");
    if a1 is not None { make_task(a1, "a1x", "deep"); }
    print(flat_rows("r"));
}
