    def add(code: str, name: str, account_type: str, parent: Account | None = None,
            is_system: bool = False, is_active: bool = True) -> Account | None {
        acc = Account(code=code, name=name, account_type=account_type,
                      is_system=is_system, is_active=active_ok=is_active);
        self.nodes[code] = acc;
        if parent is None {
            self.roots.append(acc);
        } else {
            parent +>:ChildOf:+> acc;
        }
        return acc;
    }

    def get(code: str) -> Account | None {
        return self.nodes[code];
    }

    # GOAL-002 tree(): nested closure, claim-map + skip for diamonds/cycles
    def tree(max_depth: int = 10) -> dict {
        out: dict = {};
        for r in self.roots {
            out[r.code] = self._subtree(r, 1, max_depth, claimed: dict[str, bool] = {});
        }
        return out;
    }

    def _subtree(acc: Account, depth: int, max_depth: int, claimed: dict[str, bool]) -> dict {
        node_out: dict = {"name": acc.name, "type": acc.account_type, "children": {}};
        if depth >= max_depth {
            return node_out;
        }
        claimed[acc.code] = True;
        kids: list[Account] = [acc ->:ChildOf:->][?:Account];
        kids_sorted: list[Account] = sorted(kids, key=lambda k: k.code);
        for kid in kids_sorted {
            if kid.code in claimed {
                continue;
            }
            node_out["children"][kid.code] = self._subtree(kid, depth + 1, max_depth, claimed);
        }
        return node_out;
    }

    # GOAL-002 ancestors(): breadcrumb chain root -> parent
    def ancestors(code: str) -> list[str] | None {
        if code not in self.nodes {
            return None;
        }
        chain: list[str] = [];
        cur: Account | None = self.nodes[code];
        seen: dict[str, bool] = {};
        while cur is not None and cur.code not in seen {
            seen[cur.code] = True;
            parents: list[Account] = [cur <-:ChildOf:<-][?:Account];
            if len(parents) == 0 {
                break;
            }
            cur = sorted(parents, key=lambda p: p.code)[0];
            chain.append(cur.code);
        }
        chain.reverse();
        return chain;
    }

    # GOAL-002 path(): string path "A > B > C"
    def path(code: str) -> str | None {
        anc = self.ancestors(code);
        if anc is None {
            return None;
        }
        return " > ".join(anc + [code]);
    }

    # GOAL-002 search(): fuzzy substring match with naive relevance score
    def search(term: str) -> list[dict] {
        results: list[dict] = [];
        codes: list[str] = sorted(self.nodes.keys());
        for code in codes {
            acc = self.nodes[code];
            t = term.lower();
            if t in code.lower() or t in acc.name.lower() {
                score = 2 if t == code.lower() else (1 if t in code.lower() else 0);
                results.append({"code": code, "score": score});
            }
        }
        return results;
    }

    # GOAL-001 destroy(): 403 for system, 409 when children exist
    def destroy(code: str) -> int {
        if code not in self.nodes {
            return 404;
        }
        acc = self.nodes[code];
        if acc.is_system {
            return 403;
        }
        if len([acc ->:ChildOf:->][?:Account]) > 0 {
            return 409;
        }
        self.nodes.pop(code, None);
        return 204;
    }
