# HashSlap-Summer-of-Code/Algorithms#7 — DFS traversal
# Idiomatic OSP lift: recursive DFS over a graph of nodes and typed edges,
# printing the traversal order. Cycle policy via claim-map + skip.

node GNode {
    has name: str;
}

edge E;

# module-level helper: build a fresh graph, returns root node object
def build_graph(names: list[str], edges: list[tuple[str, str]]) -> GNode {
    byname: dict[str, GNode] = {};
    for nm in names {
        nd = GNode(name=nm);
        root ++> nd;
        byname[nm] = nd;
    }
    for pr in edges {
        a: GNode = byname[pr[0]];
        b: GNode = byname[pr[1]];
        a +>:E:+> b;
    }
    return byname[names[0]];
}

# module-level helper: neighbors of a node via typed edge navigation
def neighbors(nd: GNode) -> list[GNode] {
    ns: list[GNode] = [];
    for ch in [nd ->:E:->][?:GNode] {
        ns.append(ch);
    }
    return ns;
}

# public API: deterministic DFS order list from a start node
def dfs_order(start: GNode) -> list[str] {
    claimed: dict[str, bool] = {};
    out: list[str] = [];
    _dfs_visit(start, claimed, out);
    return out;
}

# recursive DFS worker (module-level, no docstring inside)
def _dfs_visit(nd: GNode, claimed: dict[str, bool], out: list[str]) {
    if nd.name in claimed {
        return;
    }
    claimed[nd.name] = True;
    out.append(nd.name);
    for ch in neighbors(nd) {
        _dfs_visit(ch, claimed, out);
    }
}

walker DfsWalker {
    has claimed: dict[str, bool] = {};
    has order: list[str] = [];

    can step with GNode entry {
        if here.name in self.claimed {
            skip;
        }
        self.claimed[here.name] = True;
        self.order.append(here.name);
        kids: list[GNode] = neighbors(here);
        for kid in kids {
            visit :0: [kid];
        }
    }
}

