    names: list[str] = ["A", "B", "C", "D"];
    edges: list[tuple[str, str]] = [("A", "B"), ("A", "C"), ("B", "D"), ("C", "D")];
    rt = build_graph(names, edges);
    w = rt spawn DfsWalker(claimed={});
    print("DFS order:", w.order);
}
