# metel-lang/metel-core#726 — RFC-0132 comptime execution model settlement
# Models comptime evaluation over a value graph: known-arity buffers
# ([T; N] fixed scratch), growable comptime String concat lattice, and a
# depth-limited recursive comptime fun evaluator. Cycle policy: claim-map + skip.

node CVal {
    has vid: str;
    has kind: str;            # "string" | "buffer"
    has lit: str = "";        # literal payload for strings
    has arity: int = 0;       # fixed arity for buffer shape
    has depth: int = 0;       # recorded eval depth
}

edge Concat {}              # string growth by concatenation
edge SizedTo {}             # sized-array dependency ([T; N] path)

walker EvalString {
    has claimed: dict[str, bool] = {};
    has parts: list[str] = [];
    has max_depth: int = 8;
    has depth: int = 0;
    has aborted: bool = False;

    can step with CVal entry {
        if here.vid in self.claimed { skip; }
        self.claimed[here.vid] = True;
        if self.depth > self.max_depth {
            self.aborted = True;   # comptime recursion limit hit
            disengage;
        }
        here.depth = self.depth;
        if here.kind == "string" {
            self.parts.append(here.lit);
        }
        kids: list[CVal] = [here ->:Concat:->CVal];
        self.depth = self.depth + 1;
        visit kids;
        self.depth = self.depth - 1;
    }
}

walker CheckArity {
    has claimed: dict[str, bool] = {};
    has ok: bool = True;
    has seen_arities: list[int] = [];

    can step with CVal entry {
        if here.vid in self.claimed { skip; }
        self.claimed[here.vid] = True;
        if here.kind == "buffer" {
            if here.arity <= 0 { self.ok = False; }
            self.seen_arities.append(here.arity);
        }
        kids: list[CVal] = [here ->:SizedTo:->CVal];
        visit kids;
    }
}

# module-level API: build the comptime value graph, evaluate it

def build_string_graph(parts: list[str]) -> list[CVal] {
    # chain parts v0 ->Concat-> v1 ->Concat-> ... growing a comptime String
    nodes: list[CVal] = [];
    prev: CVal | None = None;
    for i in range(len(parts)) {
        nd = CVal(vid="s" + str(i), kind="string", lit=parts[i]);
        if prev is None {
            root ++> nd;
        } else {
            prev +>:Concat:+> nd;
        }
        nodes.append(nd);
        prev = nd;
    }
    return nodes;
}

def eval_comptime_string(parts: list[str]) -> str {
    # full comptime String growth: concatenated expansion of the chain
    build_string_graph(parts);
    w = root spawn EvalString(claimed={});
    return "".join(w.parts);
}

def recursion_limit_blocks(parts: list[str], limit: int) -> bool {
    # depth-limited comptime fun: oversized chains must be rejected
    build_string_graph(parts);
    w = root spawn EvalString(claimed={}, max_depth=limit);
    return w.aborted;
}

def build_sized_array(arity: int) -> CVal {
    # known-arity buffer: [f64; N] scratch, size in the type
    buf = CVal(vid="buf", kind="buffer", arity=arity);
    root ++> buf;
    return buf;
}

def check_sized_impl_path(arity: int) -> bool {
    # OQ5 probe: sized-array literal-arity case registers and dispatches
    buf = build_sized_array(arity);
    buf +>:SizedTo:+> CVal(vid="elem", kind="buffer", arity=arity);
    w = buf spawn CheckArity(claimed={});
    return w.ok and sorted(w.seen_arities) == sorted([arity, arity]);
}
