# Iterative cycle-detecting resolver: returns list of names on a cycle,
# or [] if the dependency closure from `start` is acyclic.
def resolve_trace(store: dict[str, Expr], deps: dict[str, list[str]], start: str) -> list[str]:
    path: list[str] = [];
    claimed: dict[str, bool] = {};
    stack: list[tuple] = [(start, False)];
    while len(stack) > 0 {
        cur, leaving = stack[-1];
        if leaving {
            stack.pop();
            if cur in claimed {
                claimed[cur] = False;
            }
            path.pop();
            continue;
        }
        if cur not in store {
            stack.pop();
            continue;
        }
        if cur in claimed {
            return _extract_cycle(path, cur);
        }
        claimed[cur] = True;
        path.append(cur);
        stack[-1] = (cur, True);
        for child in deps.get(cur, []) {
            stack.append((child, False));
        }
    }
    return [];

def _extract_cycle(path: list[str], start_name: str) -> list[str]:
    idx = 0;
    for i, name in enumerate(path) {
        if name == start_name {
            idx = i;
            break;
        }
    }
    cycle: list[str] = [];
    for name in path[idx:] {
        cycle.append(name);
    }
    cycle.append(start_name);
    return cycle;

