# microsoft/TypeScript#10649 — recursive module resolution
# Model a directory tree as a graph; resolve module specifiers by
# recursively searching module directories from the importing file upward.

node Dir {
    has name: str;
    has is_module_dir: bool = False;
}

node ModuleFile {
    has specifier: str;
}

edge contains {}
edge lookup {}

obj Resolver {
    has by_name: dict[str, Dir];
    has parent_of: dict[str, str | None];

    def root_node(self) -> Dir | None {
        return self.by_name.get("/");
    }

    def add_dir(self, path: str, name: str, parent: str | None, is_module_dir: bool = False) -> Dir {
        d = Dir(name=name, is_module_dir=is_module_dir);
        root ++> d;
        self.by_name[path] = d;
        self.parent_of[path] = parent;
        if parent != None {
            p = self.by_name.get(parent);
            if p != None { p +>:contains:+> d; }
        }
        return d;
    }

    def add_file(self, dir_path: str, specifier: str) -> ModuleFile {
        f = ModuleFile(specifier=specifier);
        d = self.by_name.get(dir_path);
        if d != None { d +>:contains:+> f; }
        return f;
    }

    # upward chain of module dirs from a starting dir (parent walk)
    def module_chain(self, start_path: str) -> list[str] {
        chain: list[str] = [];
        cur: str | None = start_path;
        while cur != None {
            d = self.by_name.get(cur);
            if d != None and d.is_module_dir { chain.append(cur); }
            cur = self.parent_of.get(cur);
        }
        return chain;
    }

    # recursive resolution: BFS over module chain + typed edges, claim-map cycles
    def resolve(self, importer_path: str, spec: str) -> str | None {
        start = self.by_name.get(importer_path);
        if start == None { return None; }
        claimed: dict[str, bool] = {};
        queue: list[Dir] = [start];
        qi: int = 0;
        while qi < len(queue) {
            d = queue[qi];
            qi = qi + 1;
            if d.name in claimed { continue; }
            claimed[d.name] = True;
            if d.is_module_dir {
                for ch in [d ->:contains:->][?:ModuleFile] {
                    if ch.specifier == spec { return d.name + "/" + spec; }
                }
            }
            for pd in [d ->:contains:->][?:Dir] {
                queue.append(pd);
            }
        }
        return None;
    }
}

