```jac
/*
  Stewie-pixel/claude-with-leetcode#157
  Maximum Path Quality of a Graph (LC 2065) — backtracking DFS lifted to
  idiomatic Jac OSP: edges are graph Edge objects, the walk is a walker
  whose per-path state (time used, collected value, visit counts) is
  carried on the walker, and backtracking is OSP visit-exploration.
*/

node GNode {
    has idx: int;
    has value: int;
}

edge GEdge {
    has weight: int;
}

obj Solver {
    has max_time: int;
    has best: int = 0;
    has visit_count: dict[int, int] = {};

    def build(values: list[int], edges: list[list[int]]) -> GNode {
        nodes: list[GNode] = [];
        for i in range(len(values)) {
            nd = GNode(idx=i, value=values[i]);
            root ++> nd;
            nodes.append(nd);
            self.visit_count[i] = 0;
        }
        for e in edges {
            u: int = e[0];
            v: int = e[1];
            t: int = e[2];
            nodes[u] +>:GEdge(weight=t):+> nodes[v];
            nodes[v] +>:GEdge(weight=t):+> nodes[u];
        }
        return nodes[0];
    }
}

walker Backtrack {
    has max_time: int;
    has time_used: int = 0;
    has collected: int = 0;
    has visit_count: dict[int, int] = {};
    has best: int = 0;
    has claims: dict[str, bool] = {};

    can step with GNode entry {
        k: str = here.idx |~ "";
        if k in self.claims { skip; }
        self.claims[k] = True;

        if here.idx == 0 and self.time_used > 0 or here.idx == 0 and self.collected > 0 {
            if self.collected > self.best {
                self.best = self.collected;
            }
        }

        for (e, nxt) in zip([here ->:GEdge:->], [here ->:GEdge:->][?:GNode]) {
            nt: int = self.time_used + e.weight;
            if nt > self.max_time {
                continue;
            }
            added: int = 0;
            if nxt.idx not in self.visit_count or self.visit_count[nxt.idx] == 0 {
                added = nxt.value;
                self.visit_count[nxt.idx] = 1;
            } else {
                self.visit_count[nxt.idx] += 1;
            }
            child = Backtrack(
                max_time=self.max_time,
                time_used=nt,
                collected=self.collected + added,
                visit_count=self.visit_count,
                best=self.best
            );
            nxt spawn child;
            if child.best > self.best {
                self.best = child.best;
            }
            # backtrack: restore count
            self.visit_count[nxt.idx] -= 1;
        }
    }
}

def maximalPathQuality(values: list[int], edges: list[list[int]], maxTime: int) -> int {
    sv = Solver(max_time=maxTime);
    sv.visit_count = {};
    start: GNode = sv.build(values, edges);
    w = start spawn Backtrack(max_time=maxTime, collected=values[0], visit_count={0: 1});
    return w.best;
}
