# Lifting Stewie-pixel/claude-with-leetcode#158 — Reconstruct Itinerary
# Hierholzer Eulerian path over a directed multigraph of tickets,
# greedy smallest-lexical edge consumption via a used-edge claim map.

node Airport {
    has code: str;
}

edge Flight {
}

# Walker performing iterative Hierholzer from the spawn airport.
walker Itin {
    has used: dict[str, int] = {};
    has result: list[str] = [];

    can fly with Airport entry {
        stack: list[Airport] = [here];
        path: list[str] = [];
        while len(stack) {
            top: Airport = stack[-1];
            kids: list[Airport] = [top ->:Flight:->][?:Airport];
            avail: dict[str, int] = {};
            for k in kids {
                avail[k.code] = avail.get(k.code, 0) + 1;
            }
            best_code: str | None = None;
            for dest in sorted(avail.keys()) {
                ukey: str = top.code + ">" + dest;
                if self.used.get(ukey, 0) < avail[dest] {
                    best_code = dest;
                    break;
                }
            }
            if best_code is None {
                # stuck: emit vertex and backtrack (sub-cycle splice point)
                path.append(stack.pop().code);
            } else {
                claim_key: str = top.code + ">" + best_code;
                self.used[claim_key] = self.used.get(claim_key, 0) + 1;
                for k in kids {
                    if k.code == best_code {
                        stack.append(k);
                        break;
                    }
                }
            }
        }
        path.reverse();
        self.result = path;
        print(self.result);
    }
}

# Public API: tickets as ["U", "V"] pairs; returns smallest-lexical
# itinerary using every ticket exactly once, starting at "JFK".
def reconstruct_itinerary(tickets: list[list[str]]) -> list[str] {
    if len(tickets) == 0 {
        return ["JFK"];
    }
    nodes: dict[str, Airport] = {};
    for t in tickets {
        u: str = t[0];
        v: str = t[1];
        if nodes.get(u) is None {
            nu = Airport(code=u);
            root ++> nu;
            nodes[u] = nu;
        }
        if nodes.get(v) is None {
            nv = Airport(code=v);
            root ++> nv;
            nodes[v] = nv;
        }
        nodes[u] +>:Flight:+> nodes[v];
    }
    start: Airport = nodes["JFK"];
    w = start spawn Itin();
    return w.result;
}
