# Parse a SKILL.md front-matter block into (name, description).
def parse_front_matter(text: str) -> tuple[str, str] | None {
    lines: list[str] = text.split("\n");
    nm: str = "";
    ds: str = "";
    in_fm: bool = False;
    for ln in lines {
        if ln.strip() == "---" {
            if in_fm { break; }
            in_fm = True;
            continue;
        }
        if in_fm and ln.startswith("name:") { nm = ln[5:].strip(); }
        if in_fm and ln.startswith("description:") { ds = ln[12:].strip(); }
    }
    if nm == "" { return None; }
    return (nm, ds);
}

walker Discover {
    has claimed: dict[str, bool] = {};
    has entries: list[SkillEntry] = [];
    has max_depth: int = 8;

    can scan_dir with SkillDir entry {
        if here.path in self.claimed { skip; }
        self.claimed[here.path] = True;
        kids: list[SkillDir] = [];
        sub: list[SkillFile] = [];
        for ch in [here ->:contains:->] {
            if isinstance(ch, SkillDir) {
                if ch.is_symlink and [ch ->:symlink_to:->] {
                    kids.append([ch ->:symlink_to:->][0]);
                } else {
                    kids.append(ch);
                }
            } else {
                sub.append(ch);
            }
        }
        for sf in sub {
            if parse_front_matter(sf.path) is None { continue; }
            parts: list[str] = sf.path.split("/");
            e = SkillEntry(name=sf.name, path=sf.path, depth=len(parts));
            self.entries.append(e);
        }
        if self.max_depth > 0 {
            visit kids;
        } else {
            visit [] else { disengage; }
        }
    }
}

