node Learner {
    has uid: str;
}

edge HAS {}
edge ENROLLED {}

# One batched traversal fetches every child: no per-lesson query loop.
def lesson_ids(course: Course) -> list[str] {
    ids: list[str] = [];
    for l in [course ->:HAS:->][?:Lesson] {
        ids.append(l.lid);
    }
    return sorted(ids);
}

# Cache membership derived from real graph relationship, never client input.
def is_enrolled(course: Course, uid: str) -> bool {
    for l in [course ->:ENROLLED:->][?:Learner] {
        if l.uid == uid {
            return True;
        }
    }
    return False;
}

def enroll(course: Course, learner: Learner) -> bool {
    # unknown or empty principal defaults to deny
    if learner.uid == "" {
        return False;
    }
    if is_enrolled(course, learner.uid) {
        return False;
    }
    course +>:ENROLLED:+> learner;
    return True;
}

walker BudgetAudit {
    has claimed: dict[str, bool] = {};
    has total_lessons: int = 0;
    has over_budget: bool = False;

    can start with Course entry {
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        kids: list[Lesson] = [];
        for l in [here ->:HAS:->][?:Lesson] {
            kids.append(l);
        }
        self.total_lessons += len(kids);
        if len(kids) > here.query_budget {
            self.over_budget = True;
        }
        print("course", here.cid, "queries", 1, "lessons", len(kids),
              "within_budget", len(kids) <= here.query_budget);
        visit kids else {
            disengage;
        }
    }

    can see_lesson with Lesson entry {
        if here.lid in self.claimed {
            skip;
        }
        self.claimed[here.lid] = True;
        print("lesson", here.lid);
    }
}

# Runs the audit once and reports aggregate findings (queries == 1 per course).
def audit_budgets(course: Course) -> dict[str, bool | int] {
    wk = course spawn BudgetAudit(claimed={});
    out: dict[str, bool | int] = {};
    out["queries"] = 1;
    out["lessons"] = wk.total_lessons;
    out["over_budget"] = wk.over_budget;
    return out;
}
