```jac
# alg003/algorithm#193 — island flood fill + course schedule topological sort
# lifted from hand-written BFS/DFS study notes to idiomatic Jac OSP.

node Land {
    has cid: str;
    has seen: bool = False;
}

node Course {
    has cid: int;
    has state: int = 0;   # 0 unvisited, 1 in-stack, 2 done
}

edge Adjacent {}
edge Prereq {}

walker Flood {
    has claimed: dict[str, bool] = {};

    can sweep with Land entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        here.seen = True;
        for nb in [here ->:Adjacent:->] {
            visit [nb];
        }
    }
}

walker PostOrder {
    has order: list[int] = [];
    has ok: bool = True;

    can dfs with Course entry {
        if here.state == 2 { skip; }
        if here.state == 1 {
            self.ok = False;
            skip;
        }
        here.state = 1;
        for nxt in [here ->:Prereq:->] {
            visit [nxt];
        }
        here.state = 2;
        self.order.append(here.cid);
    }
}

def build_island_graph(grid: list[str]) -> dict[str, Land] {
    cells: dict[str, Land] = {};
    for i in range(grid | len) {
        for j in range(grid[i] | len) {
            if grid[i][j] == "1" {
                cells[f"{i},{j}"] = Land(cid=f"{i},{j}");
            }
        }
    }
    for key in cells {
        parts = key.split(",");
        i = int(parts[0]);
        j = int(parts[1]);
        for d in [(1, 0), (0, 1)] {
            nk = f"{i + d[0]},{j + d[1]}";
            if nk in cells {
                cells[key] +>:Adjacent:+> cells[nk];
            }
        }
    }
    return cells;
}

def num_islands(grid: list[str]) -> int {
    cells: dict[str, Land] = build_island_graph(grid);
    count = 0;
    for key in cells {
        if not cells[key].seen {
            count += 1;
            cells[key] spawn Flood(claimed={});
        }
    }
    return count;
}

def find_order(num_courses: int, prerequisites: list[list[int]]) -> list[int] {
    nodes: dict[int, Course] = {};
    for c in range(num_courses) {
        nodes[c] = Course(cid=c);
    }
    for pr in prerequisites {
        nodes[pr[1]] +>:Prereq:+> nodes[pr[0]];
    }
    order: list[int] = [];
    for c in range(num_courses) {
        if nodes[c].state == 0 {
            wk = nodes[c] spawn PostOrder(order=[], ok=True);
            if not wk.ok { return []; }
            for cid in wk.order { order.append(cid); }
        }
    }
    return order;
}
