"""Recursive subagent lifecycle — openai/codex#42032.

Recursive delegation tree with budgeted growth, cascade
cancellation, stop-all, and orphan accounting.
"""

node Agent {
    has aid: str;
    has role: str;
    has active: bool = True;
}

edge Child {}

walker Grow {
    has fanout: int = 2;
    has claimed: dict[str, bool] = {};
    has created: int = 0;

    can step with Agent entry {
        if here.aid in self.claimed { skip; }
        self.claimed[here.aid] = True;
        next_id: int = 0;
        kids: list[Agent] = [];
        for ch in [here ->:Child:->][?:Agent] {
            kids.append(ch);
        }
        while len(kids) < self.fanout {
            next_id = next_id + 1;
            kid = Agent(aid=here.aid + "." + str(next_id),
                        role="reviewer");
            here +>:Child:+> kid;
            kids.append(kid);
            self.created = self.created + 1;
        }
        for k in kids {
            visit k;
        }
    }
}

walker Sweep {
    has claimed: dict[str, bool] = {};
    has hits: list[str] = [];
    has only_active: bool = False;

    can sweep with Agent entry {
        if here.aid in self.claimed { skip; }
        self.claimed[here.aid] = True;
        if not self.only_active or here.active {
            self.hits.append(here.aid);
        }
        visit [here ->:Child:->][?:Agent];
    }
}

def delegate(parent: Agent, aid: str, role: str) -> Agent {
    kid = Agent(aid=aid, role=role);
    parent +>:Child:+> kid;
    return kid;
}

def build_task() -> Agent {
    root_node = Agent(aid="coord", role="coordinator");
    return root_node;
}

def grow_tree(root_node: Agent, fanout: int) -> int {
    g = root_node spawn Grow(fanout=fanout, claimed={});
    return g.created;
}

def cancel_tree(root_node: Agent) -> list[str] {
    s = root_node spawn Sweep(claimed={}, only_active=False);
    doomed: list[str] = sorted(s.hits);
    return doomed;
}

def active_agents(root_node: Agent) -> list[str] {
    s = root_node spawn Sweep(claimed={}, only_active=True);
    return sorted(s.hits);
}

def stop_all(root_node: Agent) -> int {
    ids = cancel_tree(root_node);
    return len(ids);
}

def find_agent(root_node: Agent, aid: str) -> Agent | None {
    s = root_node spawn Sweep(claimed={}, only_active=False);
    if aid in s.claimed {
        return root_node;
    }
    return None;
}
