```jac
# Recursive templating of hostvars — ansible/ansible#17806
# Model: hosts hold variables; variables may reference other hostvars via
# template dependencies. Resolution must recurse through the dependency
# graph so nested templates are fully interpolated, not returned raw.

node Host {
    has name: str;
}

node Var {
    has host: str;          # owning host name
    has key: str;           # variable name
    has raw: str;           # raw value, may embed {{ other }}
    has value: str = "";    # fully resolved value
}

edge refs { }               # Var -> Var template dependency

# Extract {{ ident }} template references from a raw string.
def extract_refs(raw: str) -> list[str] {
    refs: list[str] = [];
    i: int = 0;
    while i + 2 < len(raw) {
        if raw[i] == "{" and raw[i + 1] == "{" {
            end: int = raw.find("}}", i);
            if end != -1 {
                token: str = raw[i + 2:end].strip(" ");
                refs.append(token);
                i = end + 2;
            } else {
                i = i + 1;
            }
        } else {
            i = i + 1;
        }
    }
    return refs;
}

def substitute(raw: str, table: dict[str, str]) -> str {
    out: str = raw;
    for token in extract_refs(raw) {
        if token in table {
            out = out.replace("{{ " + token + " }}", table[token]);
            out = out.replace("{{" + token + "}}", table[token]);
        }
    }
    return out;
}

walker resolve {
    has claimed: dict[str, bool] = {};   # cycle policy: claim-map + skip
    has found: dict[str, str] = {};

    can step with Var entry {
        token: str = here.host + "." + here.key;
        if token in self.claimed { skip; }
        self.claimed[token] = True;
        deps: list[Var] = [here ->:refs:->][?:Var];
        for d in deps {
            dtok: str = d.host + "." + d.key;
            if dtok not in self.found {
                visit d;
            }
        }
        # resolve only after dependencies (front-visit gives DFS closure)
        table: dict[str, str] = {};
        for d in deps { table[d.key] = d.value; }
        here.value = substitute(here.raw, table);
        self.found[token] = here.value;
    }
}

# Public API: build hostvars graph, resolve every variable recursively.
def build_hostvars(hosts: dict[str, dict[str, str]],
                   deps: dict[str, list[str]]) -> dict[str, Var] {
    index: dict[str, Var] = {};
    for hname in sorted(hosts.keys()) {
        h = Host(name=hname);
        root ++> h;
        for key in sorted(hosts[hname].keys()) {
            v = Var(host=hname, key=key, raw=hosts[hname][key]);
            index[hname + "." + key] = v;
            h ++> v;
        }
    }
    for src in sorted(deps.keys()) {
        if src in index {
            for tgt in deps[src] {
                if tgt in index {
                    index[src] +>:refs:+> index[tgt];
                }
                # unknown target ids are tolerated silently
            }
        }
    }
    return index;
}

def resolve_all(index: dict[str, Var]) -> dict[str, str] {
    w = index[next(iter(sorted(index.keys())))] spawn resolve(claimed={});
    return w.found;
}

def get_var(index: dict[str, Var], host: str, key: str) -> str | None {
    token: str = host + "." + key;
    if token in index {
        return index[token].value;
    }
    return None;   # unknown-id tolerance
}

walker demo {
    can go with root entry {
        idx: dict[str, Var] = build_hostvars(
            {"localhost": {"test_var": "this is localhost"},
             "otherhost": {"test_var": "this is otherhost"}},
            {"localhost.groupvar": ["otherhost.test_var", "localhost.test_var",
                                    "ghost.missing"]});
        resolve_all(idx);
        gv = get_var(idx, "localhost", "groupvar");
        print("groupvar:", gv);
        print("missing:", get_var(idx, "ghost", "missing"));
    }
}
