    gr = GraphRoot();
    root ++> gr;
    by_id: dict[str, Fact] = {};
    for fid in fact_ids {
        nd = Fact(fid=fid);
        gr ++> nd;
        by_id[fid] = nd;
    }
    i = 0;
    while i < len(rel_from) {
        sf = rel_from[i];
        st = rel_to[i];
        if sf in by_id and st in by_id {
            by_id[sf] +>:Rel:+> by_id[st];
