# openclaw/openclaw#47320 — recursive subagent listing (--depth / --recursive)
# Orchestrator pattern: main agent -> PM -> worker experts. Recursive listing
# of descendants with depth control, claim-map cycle policy.

node Agent {
    has key: str;
    has label: str = "";
    has status: str = "running";
    has runtime_ms: int = 0;
    has model: str = "default";
    has depth: int = 0;
}

edge SPAWNED {}

def _children(a: Agent) -> list[Agent] {
    kids: list[Agent] = [];
    for ch in [a ->:SPAWNED:->][?:Agent] {
        kids.append(ch);
    }
    return sorted(kids, key=lambda k: k.key);
}

# Recursive descendant listing; claim-map + skip for cycle safety.
walker Descend {
    has max_depth: int;
    has claimed: dict[str, bool] = {};
    has found: list[dict] = [];

    can step with Agent entry {
        if here.key in self.claimed { skip; }
        self.claimed[here.key] = True;
        if here.depth > self.max_depth { skip; }
        self.found.append({
            "key": here.key,
            "label": here.label,
            "status": here.status,
            "runtime_ms": here.runtime_ms,
            "model": here.model,
            "parent": _parent_key(here),
            "depth": here.depth,
        });
        visit [_ ->:SPAWNED:->][?:Agent];
    }
}

def _parent_key(a: Agent) -> str | None {
    for p in [<-:SPAWNED:- a][?:Agent] {
        return p.key;
    }
    return None;
}

# Public API: list descendants up to depth (None => full recursive).
def list_subagents(root: Agent, depth: int | None = None) -> list[dict] {
    max_d: int = depth;
    if depth is None {
        max_d = 999;
    }
    wk = root spawn Descend(max_depth=max_d, claimed={});
    return sorted(wk.found, key=lambda r: (r["depth"], r["key"]));
}

def agent(key: str, label: str = "", model: str = "default", status: str = "running") -> Agent {
    a = Agent(key=key, label=label, model=model, status=status);
    return a;
}

def spawn_child(parent: Agent, child: Agent) -> None {
    parent +>:SPAWNED:+> child;
    child.depth = parent.depth + 1;
}

