# dependo: recursive dependency tracing (auchenberg/dependo#7)
# Lift of hand-rolled adjacency-dict DFS to native OSP walkers.

node Module {
    has name: str;
}

edge DEPENDS_ON {}

glob graph_root: Module | None = None;

def build_graph(modules: dict[str, list[str]]) -> dict[str, Module] {
    built: dict[str, Module] = {};
    for m in sorted(modules.keys()) {
        built[m] = Module(name=m);
    }
    for m in sorted(modules.keys()) {
        for dep in modules[m] {
            if dep in built {
                built[m] +>:DEPENDS_ON:+> built[dep];
            }
        }
    }
    return built;
}

# direct (depth-1) dependencies — public API parity with dependo
def direct_deps(name: str, built: dict[str, Module]) -> list[str] {
    if name not in built {
        return [];
    }
    out: list[str] = [];
    for ch in [built[name] ->:DEPENDS_ON:->][?:Module] {
        out.append(ch.name);
    }
    return sorted(out);
}

walker TraceAll {
    has claimed: dict[str, bool] = {};
    has found: list[str] = [];

    can start with Module entry {
        if here.name in self.claimed {
            skip;
        }
        self.claimed[here.name] = True;
        self.found.append(here.name);
        kids: list[Module] = [here ->:DEPENDS_ON:->][?:Module];
        if len(kids) == 0 {
            disengage;
        }
        visit kids;
    }
}

# recursive transitive closure, sorted for determinism
def trace_deps(name: str, built: dict[str, Module]) -> list[str] {
    if name not in built {
        return [];
    }
    wk = built[name] spawn TraceAll(claimed={});
    return sorted(wk.found);
}

walker TraceLevels {
    has claimed: dict[str, bool] = {};
    has levels: dict[str, int] = {};
    has depth: int = 0;

    can walk with Module entry {
        if here.name in self.claimed and self.levels[here.name] <= self.depth {
            skip;
        }
        self.claimed[here.name] = True;
        self.levels[here.name] = self.depth;
        kids: list[Module] = [here ->:DEPENDS_ON:->][?:Module];
        if len(kids) == 0 {
            disengage;
        }
        self.depth += 1;
        visit kids;
        self.depth -= 1;
    }
}

def trace_levels(name: str, built: dict[str, Module]) -> dict[str, int] {
    if name not in built {
        return {};
    }
    wk = built[name] spawn TraceLevels(claimed={});
    return wk.levels;
}

