        if path in self.by_path {
            return self.by_path[path];
        }
        nd: DirNode = DirNode(path=path, is_dir=True);
        self.by_path[path] = nd;
        return nd;
    }

    def mkfile(path: str) -> DirNode {
        nd: DirNode = DirNode(path=path, is_dir=False);
        self.by_path[path] = nd;
        return nd;
    }

    def link(parent: DirNode, child: DirNode) {
        parent +>:Child:+> child;
    }

    def resolve(path: str) -> DirNode | None {
        if path in self.by_path {
            return self.by_path[path];
        }
        return None;
    }
}

def read_dir(tree: FsTree, dir_path: str) -> list[str] {
    # shallow, non-recursive counterpart of read_dir_all
    nd: DirNode | None = tree.resolve(dir_path);
    out: list[str] = [];
    if nd is None {
        return out;
    }
    for ch in [nd ->:Child:->][?:DirNode] {
        out.append(ch.path);
    }
    out.sort();
    return out;
}

walker ReadDirAll {
    has claimed: dict[str, bool] = {};
    has found: list[str] = [];

    can step with DirNode entry {
        if here.path in self.claimed {
            skip;
        }
        self.claimed[here.path] = True;
        kids: list[DirNode] = [];
        for ch in [here ->:Child:->][?:DirNode] {
            kids.append(ch);
        }
        kids.sort(key=lambda n: n.path);
        visit kids;
    }
}

def read_dir_all(tree: FsTree, dir_path: str) -> list[str] {
    # recursive walk; unknown dir tolerated with empty result
    root_node: DirNode | None = tree.resolve(dir_path);
    if root_node is None {
        return [];
    }
    wk = root_node spawn ReadDirAll(claimed={}, found=[]);
    wk.found.sort();
    return wk.found;
}
