def build_topic_graph(specs: list[tuple[str, list[str]]]) -> dict[str, Topic] {
    by_name: dict[str, Topic] = {};
    for sp in specs {
        if sp[0] not in by_name {
            t = Topic(name=sp[0]);
            root ++> t;
            by_name[sp[0]] = t;
        }
    }
    for sp in specs {
        child = by_name[sp[0]];
        for dep_name in sp[1] {
            if dep_name in by_name {
                parent = by_name[dep_name];
                parent +>:PREREQ:+> child;
            }
        }
    }
    return by_name;
}

def bfs_topics(graph: dict[str, Topic], start: str) -> list[str] {
    if start not in graph {
        return [];
    }
    order: list[str] = [];
    claimed: dict[str, bool] = {};
    queue: list[str] = [start];
    claimed[start] = True;
    while len(queue) > 0 {
        cur_name = queue.pop(0);
        order.append(cur_name);
        cur = graph[cur_name];
        for nxt in [cur ->:PREREQ:->][?:Topic] {
            if nxt.name not in claimed {
                claimed[nxt.name] = True;
                queue.append(nxt.name);
            }
        }
    }
    return order;
}

def dfs_topics(graph: dict[str, Topic], start: str) -> list[str] {
    order: list[str] = [];
    claimed: dict[str, bool] = {};
    stack: list[str] = [start];
    while len(stack) > 0 {
        cur_name = stack.pop();
        if cur_name in claimed {
            skip;
        }
        if cur_name not in graph {
            continue;
        }
        claimed[cur_name] = True;
        order.append(cur_name);
        cur = graph[cur_name];
        kids: list[str] = [];
        for nxt in [cur ->:PREREQ:->][?:Topic] {
            kids.append(nxt.name);
        }
        kids = sorted(kids);
        i = len(kids) - 1;
        while i >= 0 {
            stack.append(kids[i]);
            i -= 1;
        }
    }
    return order;
}

walker StudyPlan {
    has start: str;
    has claimed: dict[str, bool] = {};
    has visited: list[str] = [];

    can step with Topic entry {
        if here.name in self.claimed {
            skip;
        }
        self.claimed[here.name] = True;
        self.visited.append(here.name);
        here.done = True;
        targets: list[Topic] = [here ->:PREREQ:->][?:Topic];
        targets = sorted(targets, key=lambda t: t.name);
        visit :0: targets;
    }
}

def plan_study(graph: dict[str, Topic], start: str) -> list[str] {
    if start not in graph {
        return [];
    }
    wk = graph[start] spawn StudyPlan(start=start, claimed={});
    return sorted(wk.visited);
}
