node TypeField {
    has name: str;
    has children: int = 0;  # count hint, informational
}

edge FieldOf {}

# Depth-limited query builder: expands each node's subtree at most `depth` levels.
def write_query(root: TypeField, depth: int) -> str {
    body: str = "";
    frag: str = fragment_for(root, depth);
    return "{ " + frag + " }";
}

def fragment_for(node: TypeField, depth: int) -> str {
    inner: list[str] = [];
    inner.append(node.name);
    if depth > 0 {
        for ch in [node ->:FieldOf:->][?:TypeField] {
            inner.append(fragment_for(ch, depth - 1));
        }
    }
    parts: str = "";
    for i, p in enumerate(inner) {
        if i > 0 { parts += " "; }
        parts += p;
    }
    return parts;
}

walker ExpandQuery {
    has max_depth: int = 1;
    has emitted: dict[str, bool] = {};
    has tokens: list[str] = [];

    can step with TypeField entry {
        if here.name in self.emitted { skip; }  # cycle policy: claim-map + skip
        self.emitted[here.name] = True;
        self.tokens.append(here.name);
        if self.max_depth > 0 {
            kids: list[TypeField] = [];
            for ch in [here ->:FieldOf:->][?:TypeField] { kids.append(ch); }
            self.max_depth -= 1;
            visit :0: kids;  # front-insert for depth-first emission order
        }
    }
}

# Public fixture builder matching the Python module's make_tree.
def make_tree(spec: dict[str, list[str]]) -> dict[str, TypeField] {
    nodes: dict[str, TypeField] = {};
    for k in sorted(spec.keys()) { nodes[k] = TypeField(name=k); }
    for k in sorted(spec.keys()) {
        for cname in spec[k] {
            if cname in nodes {
                nodes[k] +>:FieldOf:+> nodes[cname];
            }
        }
    }
    return nodes;
}

# Public bounded-expansion walker entry; returns emitted tokens.
def expand(root: TypeField, depth: int) -> list[str] {
    wk = root spawn ExpandQuery(max_depth=depth, emitted={}, tokens=[]);
    return wk.tokens;
