# dart-lang/sdk#50414 — horizontal inference extended to record literals
# Flattens an argument expression tree (descending into record literal
# children) and applies horizontal inference: the first concrete parameter
# type of a lambda fixes the free type variable for all sibling lambdas.

node ArgExpr {
    has aid: str;
    has kind: str;   # "value" | "record" | "lambda" | "unknown"
    has typ: str;    # concrete type or "T" (free type var)
}

edge child {}

# Global type environment: type var -> concrete type
obj TypeEnv {
    has bindings: dict[str, str] = dict();

    def bind(tv: str, concrete: str) -> bool {
        if tv in self.bindings {
            return self.bindings[tv] == concrete;
        }
        self.bindings[tv] = concrete;
        return True;
    }
}

def flatten_args(node: ArgExpr) -> list[ArgExpr] {
    # DFS through record-literal children; leaves in order.
    out: list[ArgExpr] = [];
    stack: list[ArgExpr] = [node];
    while len(stack) {
        cur: ArgExpr = stack.pop();
        kids: list[ArgExpr] = [cur ->:child:->ArgExpr];
        if cur.kind == "record" {
            rev: list[ArgExpr] = [];
            for k in kids { rev.append(k); }
            i: int = len(rev) - 1;
            while i >= 0 { stack.append(rev[i]); i -= 1; }
        } else {
            out.append(cur);
        }
    }
    return out;
}

def infer_horizontal(leaves: list[ArgExpr]) -> dict[str, str] {
    # Each lambda leaf with a free "T" gets bound to the first concrete
    # type seen; later lambdas must unify or keep their own concrete type.
    env = TypeEnv();
    resolved: dict[str, str] = {};
    for lf in leaves {
        if lf.kind == "lambda" and lf.typ == "T" {
            if not env.bind("T", "int") {
                resolved[lf.aid] = "T";
            } else {
                resolved[lf.aid] = env.bindings["T"];
            }
        } else {
            resolved[lf.aid] = lf.typ;
        }
    }
    return resolved;
}

def infer_record_args(root_id: str, lookup: dict[str, ArgExpr]) -> dict[str, str] | None {
    # Facade: unknown ids tolerated (return None), known ids flattened+inferred.
    if root_id not in lookup {
        return None;
    }
    rt: ArgExpr = lookup[root_id];
    leaves: list[ArgExpr] = flatten_args(rt);
    return infer_horizontal(leaves);
}

