    for m in mods {
        if m.specifier in claimed { continue; }
        w = m spawn Transpiler(claimed=claimed);
        ks: list[str] = [];
        for k in w.out.keys() { ks.append(k); }
        for k in sorted(ks) {
            out[k] = w.out[k];
            claimed[k] = True;
        }
    }
    return out;
