# tramhao/termusic#103 — add tracks recursively from library (shift+L)
# Directory tree walk with symlink-safe cycle policy: claim-map + skip.

node Directory {
    has name: str;
    has is_link: bool = False;
}

node Track {
    has name: str;
    has path: str;
}

edge contains {}

edge parent_of {}

walker DirScanner {
    has claimed: dict[str, bool] = {};
    has collected: list[str] = [];

    can scan with Directory entry {
        if here.name in self.claimed {
            skip;
        }
        self.claimed[here.name] = True;
        for kid in [here ->:contains:->] {
            if kid isa Track {
                if kid.path not in self.claimed {
                    self.claimed[kid.path] = True;
                    self.collected.append(kid.path);
                }
            } else {
                visit kid;
            }
        }
    }
}

walker DeepAdder {
    has claimed: dict[str, bool] = {};
    has added: list[str] = [];

    can add with Directory entry {
        if here.name in self.claimed {
            skip;
        }
        self.claimed[here.name] = True;
        for t in [here ->:contains:->] {
            if t isa Track and t.path not in self.claimed {
                self.claimed[t.path] = True;
                self.added.append(t.name);
            }
        }
        for kid in [here ->:contains:->] {
            if kid isa Directory {
                visit kid;
            }
        }
    }
}

def build_library(flat: dict[str, list[str]]) -> Directory | None {
    # flat maps dir name -> list of child names; names starting with "song_"
    # are tracks, otherwise subdirectories.
    dirs: dict[str, Directory] = {};
    tracks: dict[str, Track] = {};
    keys: list[str] = sorted(flat.keys());
    for k in keys {
        d = Directory(name=k);
        dirs[k] = d;
    }
    root: Directory | None = None;
    if "library" in dirs {
        root = dirs["library"];
    }
    for k in keys {
        kids: list[str] = flat[k];
        for child in sorted(kids) {
            if child.startswith("song_") {
                t: Track | None = None;
                if child in tracks {
                    t = tracks[child];
                } else {
                    t = Track(name=child, path=k + "/" + child);
                    tracks[child] = t;
                }
                dirs[k] +>:contains:+> t;
            } else {
                if child in dirs {
                    dirs[k] +>:contains:+> dirs[child];
                }
            }
        }
    }
    return root;
}

def list_tracks_recursively(flat: dict[str, list[str]]) -> list[str] {
    root = build_library(flat);
    found: list[str] = [];
    if root == None {
        return found;
    }
    w = root spawn DirScanner(claimed={});
    found = sorted(w.collected);
    return found;
}

def shift_l_add(flat: dict[str, list[str]]) -> list[str] {
    root = build_library(flat);
    added: list[str] = [];
    if root == None {
        return added;
    }
    wk = root spawn DeepAdder(claimed={});
    added = sorted(wk.added);
    return added;
}

def unknown_library_lookup(flat: dict[str, list[str]], name: str) -> bool {
    # tolerant probe: reports whether a track id resolves anywhere in tree
    all_paths: list[str] = list_tracks_recursively(flat);
    for p in all_paths {
        if p.find(name) >= 0 {
            return True;
        }
    }
    return False;
}
