# resolve a glob-ish pattern: only '**' recursion supported, like the issue
def glob_match(path: str, pattern: str) -> bool {
    parts: list[str] = pattern.split("/");
    segs: list[str] = path.split("/");
    if len(parts) > 1 and parts[0] == ".." {
        # a `..` glob rooted at the project's parent may still land on
        # files inside the project folder — excludes must still apply
        parts = parts[1:];
    }
    pi: int = 0;
    si: int = 0;
    while pi < len(parts) {
        if parts[pi] == "**" {
            return True;
        }
        if si >= len(segs) or segs[si] != parts[pi] {
            return False;
        }
        pi += 1;
        si += 1;
    }
    return si == len(segs);
}

def path_of(n: FileNode) -> str {
    segs: list[str] = [n.name];
    cur = n;
    while [cur ->:Child:->] {
        # walk to root by scanning a root index built below instead
        break;
    }
    return n.name;
