        if here.name in self.claimed {
            skip;
        }
        self.claimed[here.name] = True;
        if not here.is_dir {
            ok: bool = glob_match(self.prefix + here.name, self.pattern);
            excluded: bool = False;
            for ex in self.excludes {
                if here.name == ex or glob_match(self.prefix + here.name, ex) {
                    excluded = True;
