"""Reactive queries over a grain dependency graph — dotnet/orleans#1883.

Grains memoize query results; subscribers are connected via Sub edges and
dependencies via Dep edges. A non-query call invalidates a grain, which
recursively pushes new memoized results to all downstream subscribers
(latest-wins memoization, cycle-safe via claim-map + skip).
"""

node Grain {
    has name: str;
    has memo: str = "";
    has version: int = 0;
    has invalidated: bool = False;
}

edge Sub { }
edge Dep { }

# Locate a grain by name; unknown ids return None (caller-side tolerance).
def find_grain(registry: dict[str, Grain], name: str) -> Grain | None {
    if name in registry {
        return registry[name];
    }
    return None;
}

# Non-query method invocation: bump the version, mark invalidated.
def touch(g: Grain) -> int {
    g.version = g.version + 1;
    g.invalidated = True;
    return g.version;
}

# Query execution: memoized result read (re-execution uses memoized values).
def execute_query(g: Grain) -> str {
    if g.invalidated {
        g.memo = g.name + "#v" + str(g.version);
        g.invalidated = False;
    }
    return g.memo;
}

# Recursive invalidation sweep: push updates to every subscriber exactly once.
walker Propagate {
    has claimed: dict[str, bool] = {};
    has updates: list[str] = [];

    can sweep with Grain entry {
        if here.name in self.claimed {
            skip;
        }
        self.claimed[here.name] = True;
        touch(here);
        self.updates.append(here.name);
        subs: list[Grain] = [];
        for s in [here ->:Sub:->][?:Grain] {
            subs.append(s);
        }
        if len(subs) == 0 {
            visit [here] else { disengage; }
        }
        # front-insert for depth-first propagation order
        visit :0: subs;
    }
}

# Public API: invalidate a grain and propagate; returns sorted touched ids.
def invalidate_and_propagate(g: Grain) -> list[str] {
    wk = g spawn Propagate(claimed={});
    return sorted(wk.updates);
}

# Public API: wire subscription + dependency edges.
def subscribe(src: Grain, dst: Grain) -> bool {
    src +>:Sub:+> dst;
    return True;
}

def depends_on(src: Grain, dst: Grain) -> bool {
    src +>:Dep:+> dst;
    return True;
}
