# gleam-lang/gleam#3830 — mutual-recursion tail-call optimization group analysis.
# Hand-rolled call-graph machinery lifted to idiomatic OSP: function nodes,
# call edges, cycle detection via claim-map walkers, and grouping of
# mutually recursive functions eligible for a combined TCO trampoline.

node Func {
    has name: str;
    has is_exported: bool = False;
}

edge Calls {}

obj Graph {
    has root: Func;
    has by_name: dict[str, Func];

    def get(self, name: str) -> Func | None {
        if name in self.by_name {
            return self.by_name[name];
        }
        return None;
    }
}

# Build the call graph; unknown callees are tolerated (forward refs).
def build_graph(funcs: dict[str, list[str]], exported: list[str] | None = None) -> Graph {
    exp: list[str] = [];
    if exported is None {
        exp = [];
    } else {
        exp = exported;
    }
    nodes: dict[str, Func] = {};
    for fname in sorted(funcs) {
        nd = Func(name=fname, is_exported=fname in exp);
        nodes[fname] = nd;
        root ++> nd;
    }
    for fname in sorted(funcs) {
        src = nodes[fname];
        for callee in funcs[fname] {
            if callee in nodes {
                tgt = nodes[callee];
                src +>:Calls:+> tgt;
            }
        }
    }
    return Graph(root=root, by_name=nodes);
}

walker Reach {
    has target: str = "";
    has claimed: dict[str, bool] = {};
    has found: bool = False;

    can step with Func entry {
        if here.name in self.claimed {
            skip;
        }
        self.claimed[here.name] = True;
        if here.name == self.target {
            self.found = True;
            disengage;
        }
        for kid in [here ->:Calls:->][?:Func] {
            visit kid;
        }
    }
}

walker CycleGroup {
    has source: str = "";
    has members: dict[str, bool] = {};
    has claimed: dict[str, bool] = {};

    can step with Func entry {
        if here.name in self.claimed {
            skip;
        }
        self.claimed[here.name] = True;
        probe = here spawn Reach(target=self.source, claimed={}, found=False);
        if probe.found {
            self.members[here.name] = True;
        }
        for kid in [here ->:Calls:->][?:Func] {
            visit kid;
        }
    }
}

# All mutual-recursion groups (size >= 2), sorted for determinism.
def mutual_groups(graph: Graph) -> list[list[str]] {
    seen: dict[str, bool] = {};
    groups: list[list[str]] = [];
    for fname in sorted(graph.by_name) {
        if fname in seen {
            continue;
        }
        start = graph.by_name[fname];
        wk = start spawn CycleGroup(source=fname, members={}, claimed={});
        grp: list[str] = [];
        for m in sorted(wk.members) {
            grp.append(m);
            seen[m] = True;
        }
        if len(grp) >= 2 {
            groups.append(grp);
        }
    }
    return groups;
}

# TCO group for one function; a non-mutually-recursive function is its
# own group (self-recursion already handled upstream).
def tco_group(graph: Graph, name: str) -> list[str] {
    if name not in graph.by_name {
        return [];
    }
    for grp in mutual_groups(graph) {
        if name in grp {
            return grp;
        }
    }
    return [name];
}
