# Lifting gustavopch/tsc-files#6: type-check dependent files too.
# A dependency graph maps each file to the files that depend on it
# (reverse imports). When a file changes, its full recursive dependent
# closure must be type-checked, not just the changed file itself.

obj DepGraph {
  has by_id: dict[str, File] = {};

  def add_file(fid: str) {
    if fid not in self.by_id {
      f = File(fid=fid);
      self.by_id[fid] = f;
      root ++> f;
    }
  }

  def add_dep(user: str, provider: str) {
    # `user` imports from `provider`; a change to provider affects user.
    self.add_file(user);
    self.add_file(provider);
    u = self.by_id[user];
    p = self.by_id[provider];
    u +>:DependsOn:+> p;
  }

  def dependents(fid: str) -> list[str] {
    # Sorted direct dependents (unknown-id tolerant, like tsc-files CLI).
    if fid not in self.by_id {
      return [];
    }
    src = self.by_id[fid];
    ds: list[str] = [];
    for e in [src <-:DependsOn:-] {
      for other in [e ->:File:] {
        ds.append(other.fid);
      }
    }
    return sorted(ds);
  }

  def changed(fid: str) -> list[str] {
    # Full recursive closure of dependents that must be re-checked.
    if fid not in self.by_id {
      return [];
    }
    start = self.by_id[fid];
    w = start spawn CheckWalker(claimed={}, queue=[fid], checked=[]);
    return sorted(w.checked);
  }
}

node File {
  has fid: str;
}

edge DependsOn {}

walker CheckWalker {
  has claimed: dict[str, bool] = {};
  has queue: list[str] = [];
  has checked: list[str] = [];

  can step with File entry {
    if here.fid in self.claimed {
      skip;  # cycle policy: claim-map + skip, never disengage on revisit
    }
    self.claimed[here.fid] = True;
    if here.fid not in self.checked {
      self.checked.append(here.fid);
    }
    kids: list[str] = [];
    for e in [here <-:DependsOn:-] {
      for other in [e ->:File:] {
        kids.append(other.fid);
      }
    }
    visit [self.by_id[k] for k in sorted(kids)] else { disengage; }
  }
}

# Public API mirroring tsc-files: resolve the file set to type-check.
def files_to_check(graph: DepGraph, changed_files: list[str]) -> list[str] {
  result: list[str] = [];
  seen: dict[str, bool] = {};
  for cf in changed_files {
    closure = graph.changed(cf);
    for fid in closure {
      if fid not in seen {
        seen[fid] = True;
        result.append(fid);
      }
    }
  }
  return sorted(result);
}

