```jac
"""Lift for hashicorp/terraform#27248.

Recursive child module references with count/for_each: models the module
expansion graph where each declared module instance may spawn child
instances. Terraform init must detect unbounded recursion instead of
blowing the stack, so the expansion walker uses a claim-map keyed by
"module.key = instance" to skip already-claimed nodes (cycle policy),
and reports the set of expanded instance ids plus detected cycle roots.
"""
node Module {
  has name: str;
  has key: str = "";
  has instance: str = "";
}

edge Child {}

def find_module(groot: Module, name: str) -> Module | None {
  for ch in [groot ->:Child:->][?:Module] {
    if ch.name == name { return ch; }
  }
  return None;
}

def expand_modules(groot: Module, root_name: str) -> tuple[list[str], list[str]] {
  tgt: Module | None = find_module(groot, root_name);
  if tgt == None { return ([], []); }
  expanded: list[str] = [];
  cycles: list[str] = [];
  w = groot spawn Expander(expanded=expanded, cycles=cycles);
  return (sorted(w.expanded), sorted(w.cycles));
}

walker Expander {
  has expanded: list[str] = [];
  has cycles: list[str] = [];
  has claimed: dict[str, bool] = {};

  can step with Module entry {
    if here.key in self.claimed { self.cycles.append(here.name); skip; }
    self.claimed[here.key] = True;
    self.expanded.append(here.instance);
    kids: list[Module] = [];
    for ch in [here ->:Child:->][?:Module] {
      kids.append(ch);
    }
    if len(kids) == 0 { visit [] else { disengage; } }
    visit kids;
  }
}

def build_module_graph(specs: list[tuple[str, str, str]]) -> Module {
  groot = Module(name="__root__", key="__root__", instance="__root__");
  nodes: dict[str, Module] = {};
  for s in specs {
    nd = Module(name=s[0], key=s[1], instance=s[2]);
    nodes[s[1]] = nd;
    root ++> nd;
  }
  for s in specs {
    parent: Module = nodes[s[1]];
    if s[0] != "__root__" {
      parent +>:Child:+> nodes[s[0]];
    }
  }
  return groot;
}
