def layered_bfs_2(g: Graph, start_id: str, fanout_cap: int = 3, total_cap: int = 12) -> dict[str, str] {
    # 4 point queries equivalent: 2 levels x 2 directions via forward walk here
    start = find_node(g, start_id);
    if start is None { return {}; }
    rev: dict[str, str] = {};
    for mid2 in g.nodes {
        for (lnk, nxt) in [g.nodes[mid2] ->:Link:->Memory] {
            if nxt.mid == start_id { rev[mid2] = lnk.anchor; }
        }
    }
    fwd = start spawn BfsLayer(start_id=start_id, fanout_cap=fanout_cap, total_cap=total_cap, claimed={}, paths={}, roots=[], visited_rows=0);
    merged: dict[str, str] = {};
    for k in fwd.paths { merged[k] = fwd.paths[k]; }
    for k in rev {
        if k not in merged { merged[k] = rev[k]; }
    }
    return merged;
}

walker ApplyFeedback {
    has principal: str;
    has target_id: str;
    has delta: float = 0.05;
    has factors: dict[str, float] = {};
    has applied: bool = False;

    can apply with Memory entry {
        if here.mid != self.target_id { skip; }
        cur: float = 0.0;
        if self.principal in self.factors { cur = self.factors[self.principal]; }
        newf: float = cur + self.delta;
        if newf > 0.2 { newf = 0.2; }  # bounded delta per principal (I6)
        self.factors[self.principal] = newf;
        self.applied = True;
        print("applied", self.principal, newf);
        disengage;
    }
}

def apply_feedback(g: Graph, factors: dict[str, float], principal: str, target_id: str, delta: float) -> bool {
    tgt = find_node(g, target_id);
    if tgt is None { return False; }  # uniform-404 on apply path
    wk = tgt spawn ApplyFeedback(principal=principal, target_id=target_id, delta=delta, factors=factors, applied=False);
    return wk.applied;
}

def connect(g: Graph, a: str, b: str, anchor: str, w_edge: float = 1.0) -> bool {
    na = find_node(g, a);
    nb = find_node(g, b);
    if na is None { return False; }
    if nb is None { return False; }
    na +>:Link(w_edge=w_edge, anchor=anchor):+> nb;
    g.epoch += 1;  # epoch increments on any edge write
    return True;
}

def add_memory(g: Graph, mid: str, conf: float = 1.0) -> bool {
    if mid in g.nodes { return False; }
    nd = Memory(mid=mid, conf=conf);
    g.nodes[mid] = nd;
    return True;
}

def assemble_context(g: Graph, key: str) -> str {
    # CCR cache key must include graph_epoch or feedback serves stale rankings
    return key + "@epoch=" + str(g.epoch);
}

def recall_at_5(g: Graph, start_id: str, gold: list[str]) -> float {
    paths = layered_bfs_2(g, start_id);
    hits: int = 0;
    top: list[str] = sorted(paths.keys())[0:5];
    for gid in gold {
        if gid in top { hits += 1; }
    }
    if not len(gold) { return 0.0; }
    return float(hits) / float(len(gold));
}
