"""
Lift of yukostan/Leetcode-Solutions#196 (Leetcode 207 Course Schedule).

Hand-rolled Java adjacency map + indegree array + status-array DFS is
idiomized to a Jac graph: Course nodes connected by typed Pre edges
(pre -> ready), with Kahn's BFS walker (indegree cascade) and a DFS
walker (front-insert ordering) replacing the manual queue/stack loops.
"""

node Course {
    has cid: int;
    has indeg: int = 0;
}

edge Pre {}

# build fresh graph per call: edge pre -> ready, maintain indegree
def build_graph(num_courses: int, prerequisites: list[list[int]]) -> list[Course]:
    nodes: list[Course] = [];
    i: int = 0;
    while i < num_courses {
        nd: Course = Course(cid=i);
        root ++> nd;
        nodes.append(nd);
        i += 1;
    }
    for pair in prerequisites {
        pre: int = pair[1];
        ready: int = pair[0];
        if pre >= 0 and pre < num_courses and ready >= 0 and ready < num_courses {
            nodes[pre] +>:Pre:+> nodes[ready];
            nodes[ready].indeg += 1;
        }
    }
    return nodes;

# Kahn cascade: claim-map + skip dedups diamond revisits; count of
# processed nodes equals n iff the prerequisite graph is acyclic.
walker KahnSweep {
    has done: dict[str, bool] = {};
    has count: int = 0;
    has order: list[int] = [];
    can step with Course entry {
        key: str = str(here.cid);
        if key in self.done { skip; }
        self.done[key] = True;
        self.count += 1;
        self.order.append(here.cid);
        for ch in [here ->:Pre:->][?:Course] {
            ch.indeg -= 1;
            if ch.indeg == 0 {
                visit ch;
            }
        }
    }
}

# DFS closure with front-insert visits (traversal ordering) and
# claim-map + skip cycle policy — never disengage on revisit.
walker DfsClosure {
    has done: dict[str, bool] = {};
    has seen: list[int] = [];
    can step with Course entry {
        key: str = str(here.cid);
        if key in self.done { skip; }
        self.done[key] = True;
        self.seen.append(here.cid);
        kids: list[Course] = [];
        for ch in [here ->:Pre:->][?:Course] {
            kids.append(ch);
        }
        kids = sorted(kids, key=lambda c: c.cid);
