    code_map: dict[str, Airport] = {};
    for pair in edges {
        u = pair[0];
        v = pair[1];
        if u not in code_map {
            nd_u = Airport(code=u);
            root ++> nd_u;
            code_map[u] = nd_u;
        }
        if v not in code_map {
            nd_v = Airport(code=v);
            root ++> nd_v;
            code_map[v] = nd_v;
        }
        src = code_map[u];
        dst = code_map[v];
        src +>:Flight:+> dst;
        if v not in src.remaining {
            src.remaining[v] = 0;
        }
        src.remaining[v] += 1;
    }
    if start not in code_map {
        return [start];
    }
    start_node = code_map[start];
    w = start_node spawn HierWalk(route=[], claimed={}, code_map=code_map);
    out: list[str] = [];
    idx = len(w.route) - 1;
    while idx >= 0 {
        out.append(w.route[idx]);
        idx -= 1;
    }
    return out;
}

