def build_topic_graph(edges: list[tuple[str, str]]) -> dict[str, Topic] {
    store: dict[str, Topic] = {};
    for pair in edges {
        a: str = pair[0];
        b: str = pair[1];
        if a not in store {
            nd_a = Topic(cid=a);
            store[a] = nd_a;
            root ++> nd_a;
        }
        if b not in store {
            nd_b = Topic(cid=b);
            store[b] = nd_b;
            root ++> nd_b;
