    succs: list[Neuron] = [];
    for s in [victim ->:Synapse:->][?:Neuron] {
        succs.append(s);
    }
    for p in preds {
        for e in [p ->:Synapse:-> victim] {
            del e;
        }
        if p.kind == "IF" {
            p.kind = "IDENTITY";
        }
    }
    for s in succs {
        for e in [victim ->:Synapse:-> s] {
            del e;
        }
