    ancestors = expand_ancestors(hub, selected, depth, include_archived);
    ghosts = sibling_ghosts_for_scope(hub, ancestors);
    merged: list[str] = [];
    seen: dict[str, bool] = {};
    for cid in ancestors {
        if cid in seen {
            continue;
        }
        seen[cid] = True;
        merged.append(cid);
    }
    for gid in ghosts {
        if gid in seen {
            continue;
        }
        seen[gid] = True;
        merged.append(gid);
    }
    return sorted(merged);
}
