def reset_for_refetch(
    graph_root: Track,
    scan_result_ids: list[int],
    work_item_ids: list[int]
) -> list[int] {
    w = graph_root spawn ResetCollect(
        want_scan=scan_result_ids,
        want_work=work_item_ids,
        claimed={}
    );
    sr_n: int = 0;
    for sr in w.scans {
        sr.status = SCAN_STATUS_RESET;
        sr.last_error = "";
        sr_n += 1;
    }
    wq_n: int = 0;
    for wi in w.works {
        wi.status = WORK_STATUS_RESET;
        wi.priority = WORK_PRIORITY_RESET;
        wi.next_attempt_at = WORK_NEXT_ATTEMPT_FMT;
        wi.last_error = "";
        wq_n += 1;
    }
    return [sr_n, wq_n];
}

def purge_track(
    graph_root: Track,
    track_id: str,
    fail_after_reset: bool = False
) -> dict[str, int] {
    out: dict[str, int] = {};
    w = graph_root spawn PurgeCollect(target_tid=track_id, claimed={});
    if fail_after_reset {
        raise ValueError("purge failed after reset");
    }
    sr_n: int = 0;
    for sr in w.scans {
        sr.status = SCAN_STATUS_RESET;
        sr.last_error = "";
        sr_n += 1;
    }
    wi_n: int = 0;
    for wi in w.works {
        wi.status = WORK_STATUS_RESET;
        wi.priority = WORK_PRIORITY_RESET;
        wi.next_attempt_at = WORK_NEXT_ATTEMPT_FMT;
        wi.last_error = "";
        wi_n += 1;
    }
    cs_n: int = 0;
    for cs in w.caches {
        cs.hit = False;
        cs_n += 1;
    }
    out["scans"] = sr_n;
    out["works"] = wi_n;
    out["caches"] = cs_n;
    return out;
}
