    has graph_epoch: int = 0;
    has alpha: float = 0.5;
    has rrf_k: int = 60;
}

node Memory {
    has mem_id: str;
    has pipeline_confidence: float = 1.0;
    has feedback_factor: float = 1.0;
}

edge Link {
    has w_edge: float = 1.0;
}

walker Bfs2Walker {
    has claimed: dict[str, bool] = {};
    has paths: dict[str, str] = {};
    has depths: dict[str, int] = {};
    has rows: list[dict] = [];
    has anchor_nodes: list[Memory] = [];
    has fanout_cap: int = 10;
    has work_cap: int = 100;
    has work_done: int = 0;
    has max_depth: int = 2;

    can bootstrap with GraphHub entry {
        print("bfs2 bootstrap");
        visit self.anchor_nodes else { disengage; }
    }

    can explore with Memory entry {
        if here.mem_id in self.claimed { skip; }
        self.claimed[here.mem_id] = True;
        if self.work_done >= self.work_cap { disengage; }
        self.work_done = self.work_done + 1;
        if here.mem_id not in self.paths {
            self.paths[here.mem_id] = here.mem_id;
            self.depths[here.mem_id] = 1;
        }
        row = {
            "mem_id": here.mem_id,
            "anchor_id": self.paths[here.mem_id],
            "depth": self.depths[here.mem_id],
            "w_edge": 1.0
        };
        self.rows.append(row);
        kids: list[Memory] = [];
        outs = [here ->:Link:->][?:Memory];
        for k in outs { kids.append(k); }
        ins = [here <-:Link:-<][?:Memory];
        for k in ins { kids.append(k); }
        picked: list[Memory] = [];
        fi: int = 0;
        for ch in kids {
            if fi >= self.fanout_cap { break; }
            picked.append(ch);
            fi = fi + 1;
        }
        nxt: list[Memory] = [];
        pdepth = self.depths[here.mem_id];
        for ch in picked {
            if ch.mem_id in self.claimed { continue; }
            if pdepth >= self.max_depth { continue; }
            if ch.mem_id not in self.paths {
                self.paths[ch.mem_id] = self.paths[here.mem_id];
                self.depths[ch.mem_id] = pdepth + 1;
            }
            nxt.append(ch);
        }
        print(f"bfs2 visit {here.mem_id} depth={self.depths[here.mem_id]}");
        visit nxt else { disengage; }
    }
}

def density_gate_pass(record_count: int, edge_count: int) -> bool {
    if record_count <= 0 { return False; }
    return (edge_count * 100) >= (record_count * 50);
}

def compute_rank_score(
    alpha: float, rrf_k: int, pos: int, w_edge: float, depth: int
) -> float {
    decay: float = 1.0;
    d: int = 1;
    while d < depth {
        decay = decay * 0.7;
        d = d + 1;
    }
    return ((1.0 - alpha) / (float(rrf_k) + 2.0 * float(pos))) * w_edge * decay;
}

def bump_graph_epoch(hub: GraphHub) -> int {
    hub.graph_epoch = hub.graph_epoch + 1;
    return hub.graph_epoch;
}

def assemble_context_cache_key(hub: GraphHub, principal: str, query: str) -> str {
    return f"{hub.graph_epoch}:{principal}:{query}";
}

def memory_by_id(hub: GraphHub, mem_id: str) -> Memory | None {
    found: Memory | None = None;
    kids = [hub ->>][?:Memory];
    for m in kids {
        if m.mem_id == mem_id { found = m; }
    }
    return found;
}

def write_edge(hub: GraphHub, a: Memory, b: Memory, w_edge: float) -> None {
    a +>:Link:{w_edge: w_edge}:+> b;
    hub.edge_count = hub.edge_count + 1;
    bump_graph_epoch(hub);
}

def finalize_ranks(hub: GraphHub, rows: list[dict]) -> list[dict] {
    ids: list[str] = [];
    for r in rows { ids.append(r["mem_id"]); }
    ids = sorted(ids);
    out: list[dict] = [];
    pos: int = 1;
    for mid in ids {
        for r in rows {
            if r["mem_id"] == mid {
                m = memory_by_id(hub, mid);
                eff: float = 1.0;
                if m != None { eff = m.pipeline_confidence * m.feedback_factor; }
                score = compute_rank_score(
                    hub.alpha, hub.rrf_k, pos, r["w_edge"] * eff, r["depth"]
                );
                out.append({
                    "mem_id": mid,
                    "anchor_id": r["anchor_id"],
                    "depth": r["depth"],
                    "rank": score
                });
                pos = pos + 1;
            }
        }
    }
    return out;
}

def layered_bfs2(
    hub: GraphHub,
    anchor_ids: list[str],
    fanout_cap: int,
    work_cap: int
) -> list[dict] {
    if not density_gate_pass(hub.record_count, hub.edge_count) { return []; }
    anchor_nodes: list[Memory] = [];
    for aid in anchor_ids {
        m = memory_by_id(hub, aid);
        if m != None { anchor_nodes.append(m); }
    }
    w = hub spawn Bfs2Walker(
        claimed={},
        paths={},
        depths={},
        rows=[],
        anchor_nodes=anchor_nodes,
        fanout_cap=fanout_cap,
        work_cap=work_cap,
        work_done=0,
        max_depth=2
    );
    return finalize_ranks(hub, w.rows);
}

def apply_feedback_rank(
    hub: GraphHub,
    principal: str,
    deltas: dict[str, float],
    max_delta: float
) -> dict[str, float] {
    applied: dict[str, float] = {};
    for mid in deltas {
        raw = deltas[mid];
        if raw > max_delta { raw = max_delta; }
        if raw < -max_delta { raw = -max_delta; }
        m = memory_by_id(hub, mid);
        if m != None {
            m.feedback_factor = 1.0 + raw;
            applied[mid] = raw;
        }
    }
    return applied;
}
