            if m.message_id == mid {
                return m;
            }
        }
        chs: list = [cur-->:all:->];
        for ch in chs {
            stack.append(ch);
        }
    }
    return None;
}

def sort_rows(rows: list[dict]) -> list[dict] {
    out: list[dict] = [];
    for r in rows {
        out.append(r);
    }
    n: int = len(out);
    for i in range(n) {
        for j in range(i + 1, n) {
            a: dict = out[i];
            b: dict = out[j];
            da: int = a["depth"];
            db: int = b["depth"];
            swap: bool = False;
            if db < da {
                swap = True;
            } else {
                if db == da {
                    sa: str = a["sent_at"];
                    sb: str = b["sent_at"];
                    if sb < sa {
                        swap = True;
                    }
                }
            }
            if swap {
                tmp: dict = out[i];
                out[i] = out[j];
                out[j] = tmp;
            }
        }
    }
    return out;
}

def connect_messages(specs: list[dict]) -> list[Message] {
    nodes: list[Message] = [];
    id_map: dict[str, Message] = {};
    for s in specs {
        pid: str = "";
        if "parent_id" in s {
