def split_object_key(object_key: str) -> list[str] {
    parts: list[str] = [];
    if object_key == "" {
        return parts;
    }
    token: str = "";
    for ch in object_key {
        if ch == "/" {
            if token != "" {
                parts.append(token);
                token = "";
            }
        } else {
            token = token + ch;
        }
    }
    if token != "" {
        parts.append(token);
    }
    return parts;
}

def folder_prefix(folder_key: str) -> str {
    parts: list[str] = split_object_key(folder_key);
    if len(parts) <= 1 {
        return "";
    }
    out: str = parts[0];
    for i in range(1, len(parts) - 1) {
        out = out + "/" + parts[i];
    }
