    tot["cached"] = 0;
    tot["output"] = 0;
    for nd in [-->:Session] {
        if nd.sid == "__root__" {
            continue;
        }
        tot["input"] += nd.inp;
        tot["cached"] += nd.cached;
        tot["output"] += nd.out;
    }
    return tot;
}

def fork_depth(sid: str) -> int {
    nd: Session | None = find_session(sid);
    if nd == None {
        return -1;
    }
    depth: int = 0;
    cur_sid: str = nd.parent_sid;
