def ingest_definitions(specs: list[dict]) -> GraphRoot {
    graph_root = GraphRoot();
    root ++> graph_root;
    vocab = construct_vocab();
    construct_cache: dict[str, Construct] = {};
    for spec in specs {
        did = spec["id"] as str;
        sigs = spec["signals"] as list[str];
        prov_raw = spec["provenance"] if "provenance" in spec else [];
        prov: list[str] = prov_raw as list[str];
        defn = Definition(id=did, signals=sigs);
        graph_root ++> defn;
        seen_edge: dict[str, bool] = {};
        for sig in sigs {
            if sig not in vocab { continue; }
            pair = vocab[sig] as list[str];
            cid = pair[0] as str;
            etag = pair[1] as str;
            if etag in seen_edge { continue; }
            seen_edge[etag] = True;
            if cid not in construct_cache {
                cnode = Construct(cid=cid);
                construct_cache[cid] = cnode;
                graph_root ++> cnode;
            }
            ctarget = construct_cache[cid] as Construct;
            defn.usage_tags[cid] = etag;
            defn +>:Uses(tag=etag, provenance=prov):+> ctarget;
        }
    }
    return graph_root;
