    ids = sorted(ids);
    out: list[dict] = [];
    for sid in ids {
        for it in items {
            if (it["id"] as str) == sid {
                out.append(it);
                break;
            }
        }
    }
    return out;
}

def sort_edges(edges: list[dict]) -> list[dict] {
    keys: list[str] = [];
    for e in edges {
        fk = (e["from"] as str) + "|" + (e["to"] as str) + "|" + (e["tag"] as str);
        keys.append(fk);
    }
    keys = sorted(keys);
    out: list[dict] = [];
    for k in keys {
        for e in edges {
            fk = (e["from"] as str) + "|" + (e["to"] as str) + "|" + (e["tag"] as str);
            if fk == k {
                out.append(e);
                break;
            }
        }
    }
    return out;
}

def emit_kggraph(graph_root: GraphRoot) -> tuple[list[dict], list[dict]] {
    nodes: list[dict] = [];
    edges: list[dict] = [];
    seen_c: dict[str, bool] = {};
    defs: list[Definition] = [graph_root ->>][?:Definition];
    for defn in defs {
        uses: list[Construct] = [defn ->:Uses:->][?:Construct];
        for c in uses {
            if c.cid in seen_c { continue; }
            seen_c[c.cid] = True;
            nd: dict = {};
            nd["id"] = c.cid;
            nd["kind"] = c.kind;
            nodes.append(nd);
        }
        for c in uses {
            ed: dict = {};
            ed["from"] = defn.id;
            ed["to"] = c.cid;
            ed["tag"] = defn.usage_tags[c.cid] if c.cid in defn.usage_tags else "";
            ed["provenance"] = [];
            edge_objs: list[Uses] = [defn ->:Uses:-> c];
            if len(edge_objs) > 0 {
                ed["provenance"] = edge_objs[0].provenance;
            }
            edges.append(ed);
        }
    }
    nodes = sort_dicts_by_id(nodes);
    edges = sort_edges(edges);
    return (nodes, edges);
}

def find_construct(graph_root: GraphRoot, node_id: str) -> Construct | None {
    constructs: list[Construct] = [graph_root ->>][?:Construct];
    for c in constructs {
        if c.cid == node_id { return c; }
    }
    return None;
}

def graph_neighbors(
    graph_root: GraphRoot,
    node_id: str,
    direction: str,
    edge_kinds: list[str] | None = None,
) -> list[str] {
    kinds: list[str] = [];
    if edge_kinds is not None { kinds = edge_kinds; }
    if direction != "in" { return []; }
    target = find_construct(graph_root, node_id);
    if target is None { return []; }
    w = target spawn InboundQuery(target_cid=node_id, edge_kinds=kinds, claimed={});
    return sorted(w.found);
}
