        self.claimed[here.pkg_id] = True;
        self.found.append(here.pkg_id);
        kids: list[Pkg] = [];
        for ch in [here ->:Depends:->][?:Pkg] {
            kids.append(ch);
        }
        kids = sort_pkgs_by_id(kids);
        if kids {
            visit :0: kids;
        } else {
            disengage;
        }
        print(f"transitive {here.pkg_id}");
    }
}

walker ChainWalker {
    has claimed: dict[str, bool] = {};
    has parent_of: dict[str, str] = {};
    has target: str;
    has root_id: str;
    has hit: bool = False;

    can step with Pkg entry {
        if here.pkg_id in self.claimed { skip; }
        self.claimed[here.pkg_id] = True;
        if here.pkg_id == self.target {
            self.hit = True;
            print(f"chain hit {self.target}");
            disengage;
        }
        kids: list[Pkg] = [];
        for ch in [here ->:Depends:->][?:Pkg] {
            if ch.pkg_id not in self.claimed {
                self.parent_of[ch.pkg_id] = here.pkg_id;
                kids.append(ch);
            }
        }
        kids = sort_pkgs_by_id(kids);
        if kids {
            visit :0: kids;
        } else {
            disengage;
        }
        print(f"chain step {here.pkg_id}");
    }
}

def sort_pkgs_by_id(kids: list[Pkg]) -> list[Pkg] {
    out: list[Pkg] = [];
    for k in kids {
        out.append(k);
    }
    i = 0;
    while i < len(out) {
        j = i + 1;
        while j < len(out) {
            if out[j].pkg_id < out[i].pkg_id {
                tmp = out[i];
                out[i] = out[j];
                out[j] = tmp;
            }
            j += 1;
        }
        i += 1;
    }
    return out;
}

def new_auditor() -> Auditor {
    a = Auditor(index={});
    root ++> a;
    return a;
}

def add_package(a: Auditor, pkg_id: str, version: str, severity: str = "") -> None {
    if pkg_id in a.index { return; }
    p = Pkg(pkg_id=pkg_id, version=version, severity=severity);
    root ++> p;
    a.index[pkg_id] = p;
}

def add_dependency(a: Auditor, parent_id: str, child_id: str) -> None {
    if parent_id not in a.index { return; }
    if child_id not in a.index { return; }
    parent = a.index[parent_id] as Pkg;
    child = a.index[child_id] as Pkg;
    parent +>:Depends:+> child;
}

def transitive_deps(a: Auditor, root_id: str) -> list[str] {
    if root_id not in a.index { return []; }
    start = a.index[root_id] as Pkg;
    w = start spawn TransitiveWalker(claimed={});
    out: list[str] = [];
    for pid in w.found {
        if pid != root_id {
            out.append(pid);
        }
    }
    return sorted(out);
}

def vulnerable_reachable(a: Auditor, root_id: str) -> list[str] {
    out: list[str] = [];
    for pid in transitive_deps(a, root_id) {
        p = a.index[pid] as Pkg;
        if p.severity != "" {
            out.append(pid);
        }
    }
    return sorted(out);
}

def fails_high_audit(a: Auditor, root_id: str) -> bool {
    for pid in vulnerable_reachable(a, root_id) {
        p = a.index[pid] as Pkg;
        if p.severity == "high" {
            return True;
        }
    }
    return False;
}

def dependency_chain(a: Auditor, root_id: str, target_id: str) -> list[str] {
    if root_id not in a.index { return []; }
    if target_id not in a.index { return []; }
    if root_id == target_id { return [root_id]; }
    start = a.index[root_id] as Pkg;
    w = start spawn ChainWalker(
        claimed={},
        parent_of={},
        target=target_id,
        root_id=root_id,
        hit=False
    );
    if not w.hit { return []; }
    rev: list[str] = [];
    cur = target_id;
    while cur != root_id {
        rev.append(cur);
        if cur not in w.parent_of { return []; }
        cur = w.parent_of[cur];
    }
    rev.append(root_id);
    out: list[str] = [];
    i = len(rev) - 1;
    while i >= 0 {
        out.append(rev[i]);
        i -= 1;
    }
    return out;
}
