    doomed = eng.nodes[node_id];
    keys: list[str] = [];
    for k in eng.nodes {
        keys.append(k);
    }
    for k in keys {
        if k != node_id {
            drop_typed_edge(eng.nodes[k], doomed);
            drop_typed_edge(doomed, eng.nodes[k]);
        }
    }
    destroy doomed;
    updated: dict[str, WfNode] = {};
    for k in keys {
        if k != node_id {
            updated[k] = eng.nodes[k];
        }
    }
    eng.nodes = updated;
    return True;
}
