def can_run(store: dict[str, object], name: str, core_resolved: bool) -> bool {
    canonical = validate_exact_name(name, store);
    if canonical == "" {
        return False;
    }
    exps = store["experiments"] as dict[str, Experiment];
    exp = exps[canonical];
    if exp.post_core and not core_resolved {
        return False;
    }
    deps: list[Experiment] = [exp ->:Depends:->][?:Experiment];
    done = store["done"] as dict[str, bool];
    for dep in deps {
        if dep.name not in done {
            return False;
        }
    }
    return True;
}

def plan(store: dict[str, object]) -> dict[str, object] {
    done = store["done"] as dict[str, bool];
    w = root spawn PlanWalker(done=done);
    out: dict[str, object] = {};
    out["order"] = w.order;
    out["blocked"] = w.blocked;
    out["cell_counts"] = cell_counts(store);
    return out;
}

def run_experiment(name: str, store: dict[str, object]) -> dict[str, object] {
    result: dict[str, object] = {};
    canonical = validate_exact_name(name, store);
    if canonical == "" {
        result["status"] = "Failed";
        result["reason"] = "unknown_name";
        return result;
    }
    core_ok = store["core_resolved"] as bool;
    if not can_run(store, canonical, core_ok) {
        result["status"] = "Failed";
        result["reason"] = "prerequisite";
        return result;
    }
    cells = enumerate_cells(store, canonical);
    result["status"] = "Completed";
    result["cells_run"] = cells;
    print "run", canonical, result["status"];
    return result;
}
