    can step with Job entry {
        if here.jid in self.claimed {
            skip;
        }
        self.claimed[here.jid] = True;
        if here.jid != self.start_id and here.jid != "ci_root" {
            self.found.append(here.jid);
        }
        nxt: list[Job] = [];
        for ch in [here ->:Depends:->][?:Job] {
            nxt.append(ch);
        }
        if len(nxt) > 0 {
            visit :0: nxt;
        } else {
            disengage;
        }
    }
}

walker MemoUp {
    has claimed: dict[str, bool] = {};
    has found: list[str] = [];

    can climb with Job entry {
        if here.jid in self.claimed {
            skip;
        }
        self.claimed[here.jid] = True;
        ups: list[Job] = [];
        for p in [<-:Depends:-<][?:Job] {
            ups.append(p);
        }
        for p in ups {
            if p.jid != "ci_root" {
                self.found.append(p.jid);
            }
        }
        if len(ups) > 0 {
            visit :0: ups;
        } else {
            disengage;
        }
    }
}

walker CollectJobs {
    has claimed: dict[str, bool] = {};
    has jobs: list[Job] = [];

    can gather with Job entry {
        if here.jid in self.claimed {
            skip;
        }
        self.claimed[here.jid] = True;
        if here.jid != "ci_root" {
            self.jobs.append(here);
        }
        nxt: list[Job] = [];
        for ch in [here ++>][?:Job] {
            nxt.append(ch);
        }
        if len(nxt) > 0 {
            visit :0: nxt;
        } else {
            disengage;
        }
    }
}


def find_job(root_node: Job, job_id: str) -> Job | None {
    w: FindJob = root_node spawn FindJob(target=job_id, claimed={}, result=None);
    print("find done", job_id);
    return w.result;
}

def make_workflow() -> Job {
    graph_root = Job(jid="ci_root", toolchain="", lock_ids=[]);
    fe: Job = Job(jid="frontend", toolchain="npm", lock_ids=["package-lock.json"]);
    be: Job = Job(jid="backend", toolchain="pnpm", lock_ids=["pnpm-lock.yaml"]);
    ct: Job = Job(jid="contracts", toolchain="cargo", lock_ids=["Cargo.lock"]);
    sh: Job = Job(jid="shared", toolchain="pnpm", lock_ids=["pnpm-lock.yaml"]);
    graph_root ++> fe;
    graph_root ++> be;
    graph_root ++> ct;
    fe +>:Depends:+> sh;
    be +>:Depends:+> sh;
    be +>:Depends:+> ct;
    ct +>:Depends:+> sh;
    print("workflow ready");
    return graph_root;
}

def build_revisit_diamond() -> Job {
    graph_root = Job(jid="ci_root", toolchain="", lock_ids=[]);
    s: Job = Job(jid="start", toolchain="x", lock_ids=[]);
    b: Job = Job(jid="mid_b", toolchain="x", lock_ids=[]);
    c: Job = Job(jid="mid_c", toolchain="x", lock_ids=[]);
    d: Job = Job(jid="sink", toolchain="x", lock_ids=[]);
    graph_root ++> s;
    s +>:Depends:+> b;
    s +>:Depends:+> c;
    b +>:Depends:+> d;
    c +>:Depends:+> d;
    print("diamond ready");
    return graph_root;
}

def cache_key(job_id: str, lock_hashes: dict[str, str]) -> str {
    j: Job | None = find_job(graph_root, job_id);
    if j is None {
        return "";
    }
    out: str = j.toolchain;
    lids: list[str] = sorted(j.lock_ids);
    for lid in lids {
        h: str = "";
        if lid in lock_hashes {
            h = lock_hashes[lid];
        }
        out = out + "|" + lid + ":" + h;
    }
    print("cache_key", job_id, out);
    return out;
}

def reachable_jobs(root_node: Job, start_id: str) -> list[str] {
    start: Job | None = find_job(root_node, start_id);
    if start is None {
        return [];
    }
    w: Reach = start spawn Reach(start_id=start_id, claimed={}, found=[]);
    out: list[str] = sorted(w.found);
    print("reachable", start_id, out);
    return out;
}

def memo_ancestor_jobs(root_node: Job, job_id: str) -> list[str] {
    start: Job | None = find_job(root_node, job_id);
    if start is None {
        return [];
    }
    w: MemoUp = start spawn MemoUp(claimed={}, found=[]);
    out: list[str] = sorted(w.found);
    print("memo_ancestors", job_id, out);
    return out;
}

def invalidate_on_lock_change(root_node: Job, changed_locks: list[str]) -> list[str] {
    w: CollectJobs = root_node spawn CollectJobs(claimed={}, jobs=[]);
    hit: list[str] = [];
    for j in w.jobs {
        for lid in j.lock_ids {
            for cl in changed_locks {
                if lid == cl {
                    hit.append(j.jid);
                }
            }
        }
    }
    out: list[str] = sorted(hit);
    print("invalidate", changed_locks, out);
    return out;
}
