    dirs: dict[str, ScanDir] = {};
    handle["dirs"] = dirs;
    local = ScanDir(path=blocks_dir, rel="", source="local", source_dir=blocks_dir, priority=0);
    hub +>:ScanRoot:+> local;
    dirs[blocks_dir] = local;
    pri = 1;
    if shared is not None {
        for sp in shared {
            sd = ScanDir(path=sp, rel="", source="shared", source_dir=sp, priority=pri);
            hub +>:ScanRoot:+> sd;
            dirs[sp] = sd;
            pri = pri + 1;
        }
    }
    if auto_shared {
        ap = blocks_dir + "/../../shared-blocks/blocks";
        ad = ScanDir(path=ap, rel="", source="shared", source_dir=ap, priority=100);
