    dirs = handle["dirs"] as dict[str, ScanDir];
    nd = ScanDir(path=path, rel=rel, source=source, source_dir=source_dir, priority=priority);
    dirs[path] = nd;
    if parent_path is None {
        hub +>:ScanRoot:+> nd;
    } else {
        parent = dirs[parent_path] as ScanDir;
        parent +>:DirTree:+> nd;
    }
}

def wire_block(handle: dict, dir_path: str, filename: str, block_type: str = "composite") -> None {
    dirs = handle["dirs"] as dict[str, ScanDir];
    d = dirs[dir_path] as ScanDir;
    stem = block_stem(filename);
    sub: str = "";
    if d.rel != "" {
        sub = d.rel;
    }
    be = BlockEntry(
        stem=stem,
        path=dir_path + "/" + filename,
        source=d.source,
        source_dir=d.source_dir,
        subdirectory=sub,
        block_type=block_type
    );
    d +>:DirBlock:+> be;
}

def scan_blocks(handle: dict) -> dict[str, dict] {
    hub = handle["hub"] as RegistryHub;
    hub.manifest = {};
