    roots: list[ScanDir] = [hub ->:ScanRoot:->][?:ScanDir];
    ordered = sort_scan_dirs_by_priority(roots);
    for rd in ordered {
        w = rd spawn ScanWalker(hub=hub, claimed={});
    }
    return hub.manifest;
}

def get_block(handle: dict, name: str) -> dict | None {
    hub = handle["hub"] as RegistryHub;
    if name in hub.manifest {
        return hub.manifest[name];
    }
    return None;
}

def list_block_names(handle: dict) -> list[str] {
    hub = handle["hub"] as RegistryHub;
    names: list[str] = [];
    for k in hub.manifest {
        names.append(k);
    }
    return sorted(names);
}

def collision_warnings(handle: dict) -> list[str] {
    hub = handle["hub"] as RegistryHub;
    return hub.warnings;
}
