    for r in reach_list {
        reach_set[r] = True;
    }
    super_set: dict[str, bool] = {};
    for s in superseded {
        super_set[s] = True;
    }
    result: dict[str, str] = {};
    for cid in idx {
        nd = idx[cid];
        if nd.purged {
            continue;
        }
        if cid in super_set {
            result[cid] = "superseded_duplicate";
        elif nd.test_only {
            result[cid] = "test_only";
        elif nd.retain_standalone {
            result[cid] = "standalone_reusable";
        elif cid in reach_set {
            result[cid] = "active_production";
        } else {
            result[cid] = "orphaned";
        }
    }
    return result;
}

def removable_ids(
    graph_root: Component,
    seed_ids: list[str],
    superseded: list[str],
) -> list[str] {
    classes = classify_all(graph_root, seed_ids, superseded);
    out: list[str] = [];
    for cid in classes {
        tag = classes[cid];
        if tag == "orphaned" or tag == "superseded_duplicate" {
            out.append(cid);
        }
    }
    return sorted(out);
}

def apply_removals(graph_root: Component, target_ids: list[str]) -> list[str] {
    idx = index_components(graph_root);
